  Event_117279_ChoiceDesc1 = {
    Text = "【คุณเคยปรารถนาความไร้เดียงสา】วางการ์ด「(Skill.Arg1)」 3 ใบลงในสำรับ."
  },
  Event_117279_Desc = {
    Text = "\nหมอกขาวบางเบาลอยขึ้นจากผิวน้ำปกคลุมทุกสิ่งทุกอย่างในความพร่า.\nข้ามขอบเขตของชีวิตและความตาย,      ข้ามระยะห่างภายในและภายนอกประตู,      ข้ามความทรงจำที่จางหาย,      คุณเห็นภาพเงาของคุณหญิงที่ถือร่มกันแดดกลับแสง.\nช่วงเวลาที่คุณได้ใช้ร่วมกับเธอได้ถูกทิ้งไปแล้ว,      เหมือนกับสีสันรุ่นเยาว์ที่อ่อนบางแต่สดใสของเธอ.\nรอคอยการขึ้นของดวงอาทิตย์เทียม,      หมอกบางแตกตัวออกไปเป็นอากาศ,      ภาพเงาของเธอยังโยกเยกและกลายเป็นฟองอากาศล่องลอย,      ส่งอำลาอย่างเงียบสงบให้กับคุณ."
  },
  Event_117279_Name = {
    Text = "ภาพลวงตาของมอร์ฟี่"
  },
  Event_117280_ChoiceDesc1 = {
    Text = "【คุณเคยปรารถนาให้ไร้เดียงสา】เลือกการ์ด 2 ใบเพื่อมอบการแกะสลัก「เสียงสะท้อนของมหาสมุทร」"
  },
  Event_117280_Desc = {
    Text = "\nหมอกขาวบางเบาลอยขึ้นจากผิวน้ำปกคลุมทุกสิ่งทุกอย่างในความพร่า.\nข้ามขอบเขตของชีวิตและความตาย,      ข้ามระยะห่างภายในและภายนอกประตู,      ข้ามความทรงจำที่จางหาย,      คุณเห็นภาพเงาของคุณหญิงที่ถือร่มกันแดดกลับแสง.\nช่วงเวลาที่คุณได้ใช้ร่วมกับเธอได้ถูกทิ้งไปแล้ว,      เหมือนกับสีสันรุ่นเยาว์ที่อ่อนบางแต่สดใสของเธอ.\nรอคอยการขึ้นของดวงอาทิตย์เทียม,      หมอกบางแตกตัวออกไปเป็นอากาศ,      ภาพเงาของเธอยังโยกเยกและกลายเป็นฟองอากาศล่องลอย,      ส่งอำลาอย่างเงียบสงบให้กับคุณ."
  },
  Event_117280_Name = {
    Text = "ภาพลวงตาของมอร์ฟี่"
  },
  Event_118414_ChoiceDesc1 = {
    Text = "【สามจุด】"
  },
  Event_118414_ChoiceDesc2 = {
    Text = "【หกโมง】"
  },
  Event_118414_ChoiceDesc3 = {
    Text = "【จุดเดียว】"
  },
  Event_118414_Desc = {
    Text = "ลูกเต๋าหมุนไป ส่งเสียงกลิ้งกลอก.\nมันจะหยุดเมื่อไหร่?\nคุณไม่รู้ แต่คุณต้องให้คำตอบ."
  },
  Event_118414_Name = {
    Text = "การพนันแห่งโชคชะตา"
  },
  Event_118415_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118415_Desc = {
    Text = "การตอบรับของคุณทำให้「ท้องฟ้า」ยิ่งอ่อนโยนขึ้น\nมันจุมพิตเบาๆ บนหน้าผากของคุณ\nจากนั้น หน้าผากของคุณก็บานเป็นดอกคลื่น."
  },
  Event_118415_Name = {
    Text = "อ้อมกอดแห่งมหาสมุทร"
  },
  Event_118416_ChoiceDesc1 = {
    Text = "【หลงใหลในภาพลวงตา】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118416_ChoiceDesc2 = {
    Text = "【รักษาสติ】สำหรับทุกร่างกายที่ตื่นขึ้นซึ่งมีค่าความคลั่ง 50 หรือมากกว่า จะได้รับ 15 รอยดำ"
  },
  Event_118416_ChoiceDesc3 = {
    Text = "【บังคับออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_118416_Desc = {
    Text = "บางทีอาจเป็นเพราะการต่อสู้ยาวนานทำให้คุณเกิดอาการมึนงง หรือบางทีสมองของคุณแค่ทรยศต่อร่างกายของคุณ.\nความรู้สึกไร้น้ำหนักบางอย่างปรากฏขึ้นในหัวของคุณ.\nในชั่วพริบตา สมองของคุณกลายเป็นกล้องส่องทัศน์ วิจิตร สดใส เปล่งประกายสีสันหลากหลาย.\nแรงบันดาลใจ ความลึกลับ และจินตนาการบ้าคลั่งนับไม่ถ้วนแทรกเข้ามาในสมอง ครอบครองทุกซอกทุกมุมของสมองคุณ.\nถ้าปล่อยไปอย่างนี้ สมองของคุณจะถูกสิ่งวุ่นวายเหล่านี้ทำให้ระเบิดในไม่ช้า."
  },
  Event_118416_Name = {
    Text = "กล้องส่องทัศน์แห่งความคิด"
  },
  Event_118417_ChoiceDesc1 = {
    Text = "【เข้าร่วมเกมพนัน】ติดเชื้อ「(Skill.Arg1)」 เข้าสู่เกมเสี่ยงโชค"
  },
  Event_118417_ChoiceDesc2 = {
    Text = "【หรือว่าจะไม่เอาดีกว่า】ได้รับ25รอยดำ"
  },
  Event_118417_Desc = {
    Text = "ในห้วงเคลิ้มฝัน จิตสำนึกของคุณทะลุผ่านม่านหมอกชั้นแล้วชั้นเล่า ล่องลอยไปยังพื้นที่ที่ไม่รู้จัก.\nลูกเต๋าสองลูกถูกโยนมาตรงหน้าคุณ แต่สิ่งที่ไม่รู้จักที่บังคับพาคุณมาที่นี่ยังไม่ปรากฏตัว.\nคุณได้ยินเพียงเสียงอันสับสนวุ่นวายของสิ่งนั้นดังมาจากทุกทิศทาง.\n「อยากกลับไปเหรอ? งั้นก็มาเล่นสักตาสิ.」\n「เอาชีวิตของเจ้าเป็นเดิมพัน มาพนันกับโชคชะตาสักหน่อย.」"
  },
  Event_118417_Name = {
    Text = "การพนันแห่งโชคชะตา"
  },
  Event_118418_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118418_Desc = {
    Text = "ประสบการณ์เหนือธรรมดามักจะสั้นเสมอ มันมาอย่างเงียบๆ แล้วก็หายไปอย่างกะทันหัน.\nแต่อย่างน้อยหัวของคุณยังอยู่ที่นี่ ไม่ได้ระเบิดจริงๆ."
  },
  Event_118418_Name = {
    Text = "กล้องส่องทัศน์แห่งความคิด"
  },
  Event_118419_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_118419_Desc = {
    Text = "คุณไม่ได้แพ้ แต่ก็ไม่ได้ชนะ ผลลัพธ์ไม่ดีไม่ร้าย\n「เสมอกัน...」\nสิ่งมีชีวิตที่ไม่รู้จักถอนหายใจ แต่ในเสียงนั้นไม่มีความเสียดาย\n「สนุกดีจริงๆ」"
  },
  Event_118419_Name = {
    Text = "การพนันแห่งโชคชะตา"
  },
  Event_118420_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118420_Desc = {
    Text = "ค่อยๆ เสียงดนตรีอันบ้าคลั่งนั้นกลับกลายเป็นเสียงที่กลมกลืนและศักดิ์สิทธ์ในหูของคุณ\nในที่สุดคุณก็ตระหนักรู้ เข้าใจว่าทำไมมันถึงถูกเรียกว่า「เพลงสวดสมบูรณ์แบบ」\nเพราะมัน「สมบูรณ์แบบอย่างไร้ที่ติ」จริงๆ."
  },
  Event_118420_Name = {
    Text = "เพลงสวด「สมบูรณ์แบบ」"
  },
  Event_118421_ChoiceDesc1 = {
    Text = "【รับรู้สมอง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_118421_ChoiceDesc2 = {
    Text = "【รับรู้วิญญาณ】ติดเชื้อ「(Skill.Arg1)」，การแกะสลักใหม่，ทำได้มากที่สุด 2 ครั้ง"
  },
  Event_118421_Desc = {
    Text = "กรงขังแรกของมนุษย์ คือร่างกายของตนเอง.\nในกรงขังแห่งร่างกายนี้ สมอง คือคุกสุดท้ายและสำคัญที่สุด.\n「ที่รัก เธอคิดว่าตัวเองยังมีชีวิตอยู่ ยังหายใจอยู่ ก็ปลอดภัยแล้วหรือ?」\nเมื่อสมองของเธอทรยศต่อวิญญาณของเธอ เธอจะได้สัมผัสกับความทรมานที่เจ็บปวดที่สุดในโลก.\nและความทรมานนี้ จะติดตามเธอไปตลอดชีวิต."
  },
  Event_118421_Name = {
    Text = "กรงขังในสมอง"
  },
  Event_118422_ChoiceDesc1 = {
    Text = "【สัมผัสผีเสื้อ】ลบการ์ด 2 ใบ"
  },
  Event_118422_ChoiceDesc2 = {
    Text = "【ไล่ผีเสื้อ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118422_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ Arg1 รอยดำ"
  },
  Event_118422_Desc = {
    Text = "ในทะเลลึกไม่มีผีเสื้อ เป็นเด็กสาวที่ถูกกักขังในห้องที่จินตนาการสิ่งมีชีวิตเหล่านี้ขึ้นมา\nพวกมันสวยงามมาก โบยบินอย่างอิสระในอากาศ\n「ถ้า...ถ้าฉันก็สามารถเป็นเหมือนพวกมัน บินออกไปจากที่นี่ได้ก็ดี...」\nผีเสื้อตัวหนึ่งส่งเสียงสะอื้น แต่เสียงนั้นถูกกลบด้วยเสียงกระพือปีกนับไม่ถ้วน ถูกกลบด้วยเสียงพิมพ์ดีดดังแปะๆ แทบไม่ได้ยิน"
  },
  Event_118422_Name = {
    Text = "วิญญาณโบยบินดั่งผีเสื้อ"
  },
  Event_118423_ChoiceDesc1 = {
    Text = "【ตัดเชือก】ติดเชื้อ「(Skill.Arg1)」ได้รับเรลิกที่ถูกสาป「(RelicConfig.Arg2)」"
  },
  Event_118423_ChoiceDesc2 = {
    Text = "【แก้มัดให้เขา】ติดเชื้อ 2 ครั้ง「(Skill.Arg1)」ได้รับเรลิกเงิน「(RelicConfig.Arg2)」และ「(RelicConfig.Arg3)」"
  },
  Event_118423_ChoiceDesc3 = {
    Text = "【ช่วยให้เขาหลุดพ้น】ได้รับเรลิกเงิน「(RelicConfig.Arg1)」"
  },
  Event_118423_Desc = {
    Text = "「มีคนกล่าวว่า ความปรารถนาอันไม่สิ้นสุดคือแรงผลักดันที่ทำให้คนก้าวไปข้างหน้า」\n「แต่เมื่อความปรารถนานี้แข็งแกร่งจนไม่อาจเพิกเฉย ไม่อาจตัดขาดได้ ฉันกลับรู้สึกว่าความปรารถนาที่มาจากตัวฉันเอง กลายเป็นกรงขังที่คุมขังฉันไว้」\nเสียงอ่อนแรงดังมาจากความมืด คุณมองไม่เห็นใบหน้าของอีกฝ่าย เห็นเพียงมือทั้งสองที่ถูกพันธนาการ\n「ความปรารถนาเหล่านี้กินความกลัว ความขลาด ความหวัง และความเจ็บปวดของฉันเป็นอาหาร แล้วย้อนกลับมาเพิ่มพูนความปรารถนาของฉัน」\nเสียงอ่อนแรงนั้น เปล่งคำวิงวอนสุดท้าย\n「ฉันยินดีมอบทุกสิ่ง! คนใจดี ช่วยฉันด้วย... หรือไม่ก็ปลดปล่อยฉัน...」"
  },
  Event_118423_Name = {
    Text = "ตัณหาแห่งพันธนาการ"
  },
  Event_118424_ChoiceDesc1 = {
    Text = "【รับรู้สมอง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_118424_Desc = {
    Text = "คุณรู้สึกว่าไขสมองของตัวเองกระตุกขึ้นมาครั้งหนึ่ง\n「สิ่งนี้มีความหมายพิเศษอะไรหรือเปล่า?」\nคุณถามตัวเอง แต่สมองเงียบงัน\nไม่ใช่ทุกครั้งที่การตั้งคำถามกับตัวเองจะได้รับคำตอบ"
  },
  Event_118424_Name = {
    Text = "กรงขังในสมอง"
  },
  Event_118425_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118425_Desc = {
    Text = "คุณพยายามว่ายขึ้นไปในน้ำ และในที่สุดก็โผล่ขึ้นมาจากผิวน้ำ\nอากาศที่ผสมกับกลิ่นคาวทะเลไหลเข้าสู่ปอดของคุณ เตือนคุณว่า คุณยังไม่ได้หลบหนีจากอันตรายอย่างแท้จริง\nแต่คุณรู้ว่า ท้องฟ้าที่แท้จริงอยู่เหนือศีรษะของคุณ\nเพียงเช่นเดียวกับความจริง จะไม่มีใครสามารถปกปิดด้วยคำโกหกที่อ่อนโยน"
  },
  Event_118425_Name = {
    Text = "อ้อมกอดแห่งมหาสมุทร"
  },
  Event_118426_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118426_Desc = {
    Text = "ในชั่วขณะที่คุณสัมผัสเชือกแห่งตัณหา ความเจ็บปวดแปลบขึ้นจากส่วนลึกของวิญญาณ\nความกลัว ความขลาด ความหวัง ความเจ็บปวดทั้งหมดหลั่งไหลออกจากร่างกายคุณ แปรเปลี่ยนเป็นเชือกเปื้อนเลือดที่มัดมือทั้งสองของคุณ\nในขณะนั้น คุณได้ยินเสียงนั้นส่งเสียงเชียร์อย่างมุ่งร้าย\n「คนดี คุณจะได้รับรางวัล... แน่นอน พร้อมกับคำสาปด้วย」"
  },
  Event_118426_Name = {
    Text = "ตัณหาแห่งพันธนาการ"
  },
  Event_118427_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118427_Desc = {
    Text = "การสัมผัสของคุณทำให้ผีเสื้อสั่นไหว\nตั้งแต่เกิดมา พวกมันไม่เคยได้รับการปฏิบัติอย่างอ่อนโยนเช่นนี้\nผีเสื้อถูกครอบงำด้วยอารมณ์ที่ไม่รู้จะทำอย่างไร จนลืมแม้กระทั่งการบิน\nแล้วผีเสื้อนับไม่ถ้วนก็ร่วงหล่น เผยให้เห็นเครื่องพิมพ์ดีดที่เคยถูกปีกนับไม่ถ้วนบดบัง\nสิ่งน่าสงสารที่สูญเสียชีวิตไปแล้วนั้น ใช้พลังสุดท้ายพิมพ์คำว่า「อิสรภาพ」"
  },
  Event_118427_Name = {
    Text = "วิญญาณโบยบินดั่งผีเสื้อ"
  },
  Event_118428_ChoiceDesc1 = {
    Text = "【เตรียมพร้อมสู้】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118428_ChoiceDesc2 = {
    Text = "【ลองอ้อมทาง】รับได้ 25 รอยดำ"
  },
  Event_118428_Desc = {
    Text = "ในทะเลลึกที่แสงดาวทอดลงมา เหล่าผู้เหยียบทะเลซ่อนตัวมานับพันปี.\nผืนน้ำอันไร้ขอบเขตเป็นพยานแห่งความบ้าคลั่งของพวกเขา เป็นพยานแห่งความอดทนของพวกเขา และเป็นพยานแห่งศรัทธาอันเลื่อมใสที่สุดที่พวกเขามีต่อเทพเจ้า.\nไม่มีผู้ใดสามารถขัดขวางการเสด็จมาอันยิ่งใหญ่ของเทพเจ้าได้.\nผู้ขวางทางทุกคนจะถูกเผาเป็นเถ้าถ่านในเปลวเพลิงแห่งความโกรธของเหล่าผู้เหยียบทะเล."
  },
  Event_118428_Name = {
    Text = "การรอคอยใต้หมู่ดาว"
  },
  Event_118429_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118429_Desc = {
    Text = "คุณปิดหูด้วยสัญชาตญาณโดยไม่ทันคิด\nอย่างไม่น่าเชื่อ เสียงดนตรีจากส่วนลึกของวิญญาณนั้นหายไป\nแน่นอน เป็นเพียงชั่วคราวเท่านั้น."
  },
  Event_118429_Name = {
    Text = "เสียงเปียโนลบหลู่"
  },
  Event_118430_ChoiceDesc1 = {
    Text = "【ย้อนรำลึกอดีต】ได้รับการแกะสลักขั้นสูง เลือก 1 จาก 3"
  },
  Event_118430_ChoiceDesc2 = {
    Text = "【แอบมองอนาคต】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118430_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_118430_Desc = {
    Text = "ไม่มีสิ่งใดในโลกนี้ที่จะมั่นคงไม่เปลี่ยนแปลง\nแม้แต่สวรรค์ที่พระมารดาสร้างขึ้นก็เช่นกัน\nในชั่วขณะสั้นๆ คุณมองเห็นบางสิ่งจากรอยแยกกาลอวกาศ\nอดีต ปัจจุบัน อนาคต พันกันอยู่ในรอยร้าวนั้น เปลี่ยนแปลงไม่หยุด\nรอคอยการสอดส่องอย่างอยากรู้อยากเห็นของคุณ."
  },
  Event_118430_Name = {
    Text = "รอยแยกกาลอวกาศ"
  },
  Event_118431_ChoiceDesc1 = {
    Text = "【ได้รับ 100 รอยดำ】"
  },
  Event_118431_ChoiceDesc2 = {
    Text = "【การ์ดคำสั่งสุ่ม 2 ใบรับตราประทับ：「(EnchantConfig.Arg1)」】"
  },
  Event_118431_Desc = {
    Text = "เจตจำนงที่ไร้รูปร่างไม่ยอมรับทางเลือกของคุณ มันเต็มใจให้โอกาสคุณอีกครั้ง เพื่อให้คุณทำการเปลี่ยนแปลง——\nระวังไว้ แม้ดนตรีจะไร้รูปร่าง แต่ก็สามารถเก็บเกี่ยวชีวิตได้."
  },
  Event_118431_Name = {
    Text = "เพลงสวด「สมบูรณ์แบบ」"
  },
  Event_118432_ChoiceDesc1 = {
    Text = "【ให้อาหารหนู】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，เลือกติดเชื้ออาการ 1 ครั้ง"
  },
  Event_118432_ChoiceDesc2 = {
    Text = "【ไล่หนู】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118432_ChoiceDesc3 = {
    Text = "【เพิกเฉยหนู】ได้รับ 25 รอยดำ"
  },
  Event_118432_Desc = {
    Text = "ทุกสิ่งบนเรือลำนี้ล้วนอยู่ในวัฏจักร\nสิ่งมีชีวิตตัวเล็กๆ ที่น่ารังเกียจและเต็มไปด้วยขนสกปรกที่หากินบนเรือ ย่อมหนีไม่พ้นชะตากรรมนี้เช่นกัน\nในวัฏจักรครั้งแล้วครั้งเล่า พวกมันกินทุกสิ่งที่เห็น แต่ก็ยังไม่อิ่ม\n「หิว...จัง...」\nฝูงหนูส่งเสียงร้องแหลมที่ป่วยไข้และแสบแก้วหู\nวัฏจักรซ้ำแล้วซ้ำเล่าทำให้พวกมันหิวจนทนไม่ไหว พวกมันต้องกินอะไรสักอย่าง\nทันที เดี๋ยวนี้!"
  },
  Event_118432_Name = {
    Text = "ฝูงหนูหิวโหย"
  },
  Event_118433_ChoiceDesc1 = {
    Text = "【หลบสายตา】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118433_ChoiceDesc2 = {
    Text = "【จ้องตรงไปที่ดวงตา】สุ่มการตื่นรู้ 2 ร่างกายที่ตื่นขึ้น ติดเชื้อสองครั้ง「(Skill.Arg1)」"
  },
  Event_118433_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_118433_Desc = {
    Text = "เช่นเดียวกับดวงดาวบนท้องฟ้า ในทะเลลึกย่อมมีดวงตามากมายเช่นกัน\nดวงตาเหล่านั้นมาจากปลาที่อาศัยอยู่ใต้ท้องทะเล มาจากเหงือกที่ลบหลู่ และมาจากมหาสมุทรเอง\nชู่ อย่าทำให้พวกมันตกใจ\nอย่า ทำให้ความบ้าคลั่งของทะเลลึกตกใจ."
  },
  Event_118433_Name = {
    Text = "ตาแห่งทะเลลึก"
  },
  Event_118434_ChoiceDesc1 = {
    Text = "【เพิกเฉยเสียงกระซิบ】"
  },
  Event_118434_ChoiceDesc2 = {
    Text = "【ฟังเสียงกระซิบ】"
  },
  Event_118434_ChoiceDesc3 = {
    Text = "【โฆษณาชวนเชื่อย้อนกลับ】"
  },
  Event_118434_Desc = {
    Text = "「ปรารถนาที่จะได้รับความโปรดปรานจากเทพเจ้าหรือ? อยากรู้ความหมายของตัวเองหรือ?」\nเสียงถอนหายใจดังขึ้นข้างหูคุณ เหมือนเสียงพึมพำของผู้ป่วยจิตเวช หรือเสียงกระซิบอย่างสนิทสนมของสิ่งที่มองไม่เห็น\nด้วยสติและความระมัดระวัง คุณปฏิเสธออกเสียง แต่เสียงนั้นยังคงพูดต่อไปตามลำพัง\n「กรุณาตั้งใจฟัง สิ่งที่เจ้าจะได้รู้ คือความจริงเกี่ยวกับโชคชะตาของโลก...」"
  },
  Event_118434_Name = {
    Text = "การเทศนาของผู้ไร้รูป"
  },
  Event_118435_ChoiceDesc1 = {
    Text = "【รับรู้สมอง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_118435_ChoiceDesc2 = {
    Text = "【รับรู้วิญญาณ】ติดเชื้อ「(Skill.Arg1)」，ทำการแกะสลักแบบสุ่มอีกครั้ง"
  },
  Event_118435_Desc = {
    Text = "สมองที่ถูกปกป้องอย่างปลอดภัยภายในกะโหลกศีรษะส่งข้อมูลบางอย่างมาถึงคุณ\nคุณไม่รู้ว่าข้อมูลเหล่านี้ถูกสึกกร่อนไปในกระบวนการแปลงสารสื่อประสาทและการส่งผ่านกระแสไฟฟ้าชีวภาพหรือไม่\nสิ่งเดียวที่แน่นอนคือ คุณได้รับข้อมูลนี้ และในการดำรงอยู่อย่างเป็นรูปธรรมของร่างกาย คุณรับรู้ได้ถึงการมีชีวิตอยู่ของตัวเอง"
  },
  Event_118435_Name = {
    Text = "กรงขังในสมอง"
  },
  Event_118436_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_118436_Desc = {
    Text = "「คำตอบไม่เลว แต่น่าเสียดาย ไม่ใช่คำตอบที่ถูกต้อง.」\n「แล้วอะไรคือคำตอบที่ถูกต้อง?」\nสิ่งที่ไม่รู้จักไม่ตอบคำถามของคุณ เพียงแค่หัวเราะเยาะเบาๆ.\n「ใครบอกเจ้าว่าโชคชะตามีคำตอบที่ถูกต้อง?」"
  },
  Event_118436_Name = {
    Text = "การพนันแห่งโชคชะตา"
  },
  Event_118437_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118437_Desc = {
    Text = "「แกคิดว่าฉันไม่เคยพยายามตัดมันหรือ? ไม่ เมื่อแกต่อต้านตัณหา มันจะยิ่งรุนแรงขึ้นเท่านั้น!」\nรู้สึกได้ว่าเชือกที่เกิดจากตัณหารัดแน่นขึ้นเรื่อยๆ จนกรีดเข้าเนื้อ เสียงนั้นส่งเสียงร้องอย่างสิ้นหวัง\n「ฉันจะไม่มีวันหลุดพ้นจากมัน... ไม่มีวัน!」"
  },
  Event_118437_Name = {
    Text = "ตัณหาแห่งพันธนาการ"
  },
  Event_118438_ChoiceDesc1 = {
    Text = "【ฟังเสียงร้องเพลง】ได้รับ 25 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_118438_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_118438_Desc = {
    Text = "อีกาสีดำสนิทกำลังร้องไห้.\nอีกาสีดำสนิทกำลังตะโกน.\nอีกาสีดำสนิทกำลังคำราม.\nแต่ในหูของผู้คน มันเพียงแค่กำลังร้องเพลง.\n「อา เสียงเพลงที่ไร้กังวลเหลือเกิน อยากเป็นอีกาสักตัวจัง จะได้ห่างไกลจากความทุกข์ของโลกมนุษย์」"
  },
  Event_118438_Name = {
    Text = "เสียงคร่ำครวญที่ไม่มีใครรับรู้"
  },
  Event_118439_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118439_Desc = {
    Text = "ผีเสื้อกระจายไป ในที่สุดคุณก็มองเห็นเครื่องพิมพ์ดีดด้านล่างอย่างชัดเจน\nสิ่งน่าสงสารที่สูญเสียชีวิตไปแล้วนั้น ใช้พลังสุดท้ายพิมพ์คำว่า「จากไป」"
  },
  Event_118439_Name = {
    Text = "วิญญาณโบยบินดั่งผีเสื้อ"
  },
  Event_118440_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118440_Desc = {
    Text = "ในภาพของอดีต เด็กสาวที่สวมเสื้อขนสัตว์ตัวใหญ่โบกมือให้คุณ\nคุณไม่ได้ยินว่าเธอพูดอะไร แต่คุณเห็นรอยยิ้มของเด็กสาว."
  },
  Event_118440_Name = {
    Text = "รอยแยกกาลอวกาศ"
  },
  Event_118441_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118441_Desc = {
    Text = "ใต้ทะเลลึกกลับคืนสู่ความมืดมิดและความเงียบสงบอีกครั้ง\nในความมืดมิดและความเงียบสงบนี้ คุณได้ยินเสียงหัวใจเต้นอีกครั้ง\nเสียงนั้นมาจากภายในร่างกายของคุณ\nในสายตาของผู้อื่น คุณก็เป็นเพียงหัวใจที่เต้นอยู่ ล่องลอยไปในใต้ทะเลลึกอันมืดมิด."
  },
  Event_118441_Name = {
    Text = "กฎแห่งผู้แข็งแกร่ง"
  },
  Event_118442_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118442_Desc = {
    Text = "ครั้งนี้ ผู้ที่ถูกเผาเป็นเถ้าถ่านไม่ใช่ผู้ขวางทาง แต่เป็นเหล่าผู้เหยียบทะเล.\nหมู่ดาวเฝ้ามองเหตุการณ์นี้อย่างเงียบงัน เหมือนเช่นที่ผ่านมานับพันปี ยังคงนิ่งเงียบ."
  },
  Event_118442_Name = {
    Text = "การรอคอยใต้หมู่ดาว"
  },
  Event_118443_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118443_Desc = {
    Text = "แม้จะมีจำนวนมากกว่า แต่ความกล้าของฝูงหนูสกปรกเหล่านั้นกลับเล็กกว่าตัวของมันเสียอีก\nพวกมันถูกข่มขู่ด้วยท่าทีแข็งกร้าวของคุณ จึงแตกกระเจิงหนีไป."
  },
  Event_118443_Name = {
    Text = "ฝูงหนูหิวโหย"
  },
  Event_118444_ChoiceDesc1 = {
    Text = "【ยื่นมือช่วย】สุ่มปลุกร่างกายที่ตื่นขึ้น 1 ตัว ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_118444_ChoiceDesc2 = {
    Text = "【เฝ้าดูเงียบๆ】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_118444_Desc = {
    Text = "หัวใจที่เต้นอยู่ดวงหนึ่งล่องลอยในทะเลลึกมืดมิด\nมันอาจเป็นของปลาตัวหนึ่ง หรืออาจเป็นของสิ่งมีชีวิตที่มีเหงือกปลา\nคุณมองไม่ชัด สิ่งเดียวที่คุณมองเห็นได้ชัดคือหัวใจที่เต้นไม่หยุด และด้านหลังหัวใจนั้น ปากขนาดใหญ่ที่ค่อยๆ อ้าออก\nการล่า หรือถูกล่า คือกฎของธรรมชาติ\nไม่ว่าจะบนบก หรือในมหาสมุทร"
  },
  Event_118444_Name = {
    Text = "กฎแห่งผู้แข็งแกร่ง"
  },
  Event_118445_ChoiceDesc1 = {
    Text = "【โบกมือไล่】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118445_ChoiceDesc2 = {
    Text = "【คงอยู่โดยไม่เคลื่อนไหว】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับการติดตั้ง「(Skill.Arg2)」"
  },
  Event_118445_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_118445_Desc = {
    Text = "เสียงเบาๆ ดังขึ้นจากความมืด\nนั่นคือผีเสื้อตัวหนึ่งถามอย่างสุภาพ\n「ฉันเกาะบนฝ่ามือของคุณได้ไหม?」\n「ฉันแค่เหนื่อยเกินไป อยากพักผ่อนสักหน่อย...」\nถามอย่างนั้นแล้ว ผีเสื้อก็บินฝ่าความมืด วนเวียนอยู่ตรงหน้าคุณ\nของเหลวสีดำหยดลงจากปีกของมัน——นั่นคือของขวัญจากความมืดที่ผีเสื้อได้รับขณะบินฝ่าความมืดมา."
  },
  Event_118445_Name = {
    Text = "คำขอของผีเสื้อ"
  },
  Event_118446_ChoiceDesc1 = {
    Text = "【ออก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_118446_Desc = {
    Text = "หลังจากความเงียบชั่วขณะ มีบางอย่างถูกโยนมาในอ้อมแขนของคุณ.\n「เอามันไปแล้วจากไปเถอะ.」\n「โชคชะตาต่อผู้โชคดีนั้น เอื้อเฟื้อเสมอ.」"
  },
  Event_118446_Name = {
    Text = "การพนันแห่งโชคชะตา"
  },
  Event_118447_ChoiceDesc1 = {
    Text = "【ติดตามการนำทาง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118447_ChoiceDesc2 = {
    Text = "【ไม่สนใจการนำทาง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118447_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_118447_Desc = {
    Text = "เทศกาลได้เริ่มต้นแล้ว\nภายใต้เปลวไฟแห่งวิญญาณและคำอธิษฐานแห่งเลือด วิญญาณของผู้ศรัทธานับไม่ถ้วนกลายเป็นประภาคาร——\nวิญญาณเลือนลางกระจายอยู่รอบตัวคุณ ดุจภูตแห่งทางนำ ส่องแสงรอคอยการเลือกของคุณ."
  },
  Event_118447_Name = {
    Text = "ประภาคารแห่งวิญญาณ"
  },
  Event_118448_ChoiceDesc1 = {
    Text = "【Leave】การติดเชื้อ「(Skill.Arg1)」 ได้รับ 50 รอยดำ"
  },
  Event_118448_Desc = {
    Text = "「มนุษย์ผู้โง่เขลา!」\nเสียงนั้นส่งเสียงบ่นด้วยความหงุดหงิด แต่ยังไม่ถึงขั้นโกรธ\nเพราะมันรู้ดีว่า ผู้ไม่รู้ย่อมมีวันตื่นรู้\nมันเพียงต้องรอวันนั้นมาถึง\nและก่อนวันนั้นจะมาถึง มันจะสลักตราประทับของเทพเจ้าลงบนตัวเจ้า เพื่อยืนยันว่าวิญญาณของเจ้าเป็นของใคร"
  },
  Event_118448_Name = {
    Text = "การเทศนาของผู้ไร้รูป"
  },
  Event_118449_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118449_Desc = {
    Text = "「@2的@3...」\nความรู้มหาศาลไหลเข้าสู่สมองของคุณพร้อมกับเสียงดนตรีที่ลบหลู่\nแต่ร่างกายของมนุษย์กลับจำกัดคุณ ทำให้คุณไม่สามารถเข้าใจความรู้จากจักรวาลได้\nช่างเป็นความเสียใจที่น่าสมเพช."
  },
  Event_118449_Name = {
    Text = "เสียงเปียโนลบหลู่"
  },
  Event_118450_ChoiceDesc1 = {
    Text = "【Leave】การติดเชื้อ「(Skill.Arg1)」 ได้รับ 50 รอยดำ"
  },
  Event_118450_Desc = {
    Text = "「จริงๆ แล้ว ฉันก็มีความจริงของโลกอยากจะบอกเจ้าเหมือนกัน...」\n「โลกถูกสร้างขึ้นโดยเทพสปาเก็ตตี้บินได้ ผู้มีดวงตาลูกชิ้นสองดวงที่เปี่ยมด้วยปัญญา และเส้นพาสต้าที่เป็นสัญลักษณ์แห่งพลังอันไร้ขีดจำกัด...」\nคุณพูดเรื่องสนุกที่เคยได้ยินมาอย่างจริงจัง รอดูปฏิกิริยาของอีกฝ่าย\nแต่ผ่านไปนาน อีกฝ่ายก็ไม่มีความเคลื่อนไหวใดๆ\n「เฮ้อ ดูเหมือนพวกคลั่งศรัทธาจะไม่เข้าใจอารมณ์ขัน」\nคุณถอนหายใจ ได้แต่จากไป"
  },
  Event_118450_Name = {
    Text = "การเทศนาของผู้ไร้รูป"
  },
  Event_118451_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118451_Desc = {
    Text = "การปรับเสียงของคุณไม่ได้ทำให้โน้ตที่วุ่นวายนี้กลมกลืนขึ้น\nแต่อย่างน้อย เจตจำนงที่ไร้รูปร่างก็เห็นความพยายามของคุณ\nนี่เป็นจุดเริ่มต้นที่ดี."
  },
  Event_118451_Name = {
    Text = "เพลงสวด「สมบูรณ์แบบ」"
  },
  Event_118452_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118452_Desc = {
    Text = "เงาสามร่างสั่นเทา สะอื้นไห้อย่างไร้เสียง\nความศรัทธาของพวกมันถูกคุณตั้งคำถาม และนี่คือการดูหมิ่นที่ผู้คลั่งศรัทธาไม่อาจทนได้"
  },
  Event_118452_Name = {
    Text = "เครื่องบูชาที่ดีที่สุด"
  },
  Event_118453_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118453_Desc = {
    Text = "ในภาพแห่งอนาคต เด็กสาวที่มีหนวดปลาหมึกงอกออกมาชำเลืองมองคุณอย่างหยิ่งผยอง แล้วเปล่งเสียงตำหนิ.\n「พระพักตร์ที่แท้จริงของเทพมารดาไม่อาจถูกลบหลู่ได้.」\nแล้วภาพก็หายไป รอยแยกของกาลเวลาก็ปิดลงในทันที เหลือเพียงคุณที่ยังคงหวนนึกถึงภาพที่เพิ่งเห็น."
  },
  Event_118453_Name = {
    Text = "รอยแยกกาลอวกาศ"
  },
  Event_118454_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118454_Desc = {
    Text = "คุณหลุดพ้นจากเหล่าผู้เหยียบทะเลได้สำเร็จ และเดินหน้าต่อไป.\nเหนือศีรษะของคุณ หมู่ดาวส่องแสงระยิบระยับอย่างเงียบงัน เหมือนเช่นที่ผ่านมานับพันปี."
  },
  Event_118454_Name = {
    Text = "การรอคอยใต้หมู่ดาว"
  },
  Event_118455_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118455_Desc = {
    Text = "สิ่งมีชีวิตที่ไม่รู้จักไม่ได้ขัดขวางคุณ\n「สักวันหนึ่ง เจ้าจะกลับมาอีก」\n「ไม่มีใครสามารถปฏิเสธโชคชะตาได้」"
  },
  Event_118455_Name = {
    Text = "การพนันแห่งโชคชะตา"
  },
  Event_118456_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118456_Desc = {
    Text = "ภายใต้ท่าทางที่ฉับไว มือทั้งสองข้างห้อยลงอย่างไร้แรง\nแต่คุณไม่พลาดเสียงถอนหายใจสุดท้ายของเขา\nในที่สุดเขาก็หลุดพ้นจากตัณหาอันไม่สิ้นสุดของตัวเองอย่างแท้จริง"
  },
  Event_118456_Name = {
    Text = "ตัณหาแห่งพันธนาการ"
  },
  Event_118457_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118457_Desc = {
    Text = "การไม่ถูกรับรู้คือชะตากรรมที่หลีกเลี่ยงไม่ได้ของโลกนี้.\nไม่มีใครสามารถเข้าใจความรู้สึกของชีวิตอื่นได้อย่างสมบูรณ์."
  },
  Event_118457_Name = {
    Text = "เสียงคร่ำครวญที่ไม่มีใครรับรู้"
  },
  Event_118458_ChoiceDesc1 = {
    Text = "【ฟังเสียงร้องเพลง】ได้รับ 35 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_118458_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_118458_Desc = {
    Text = "อีกาสีดำสนิทกำลังร้องไห้.\nอีกาสีดำสนิทกำลังตะโกน.\nอีกาสีดำสนิทกำลังคำราม.\nแต่ในหูของผู้คน มันเพียงแค่กำลังร้องเพลง.\n「อา เสียงเพลงที่ไร้กังวลเหลือเกิน อยากเป็นอีกาสักตัวจัง จะได้ห่างไกลจากความทุกข์ของโลกมนุษย์」"
  },
  Event_118458_Name = {
    Text = "เสียงคร่ำครวญที่ไม่มีใครรับรู้"
  },
  Event_118459_ChoiceDesc1 = {
    Text = "【ฟังอย่างตั้งใจ】ได้รับสิ่งประดิษฐ์เงิน 「(RelicConfig.Arg1)」, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_118459_ChoiceDesc2 = {
    Text = "【ปิดหู】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_118459_Desc = {
    Text = "ในความคลั่งไคล้ที่ไร้รูปร่าง คุณเหมือนจะเห็นเปียโนตัวหนึ่ง\nมีมือคู่หนึ่งที่มองไม่เห็นรูปร่าง กระโดดไปมาบนคีย์เปียโนที่ไร้รูปนี้ บรรเลงเสียงดนตรีที่ลบหลู่\nเสียงดนตรีอันพิลึกดังขึ้นจากส่วนลึกของวิญญาณคุณ ผ่านเส้นทางของหลอดเลือด ตรงไปยังสมองที่สั่นสะท้านของคุณ."
  },
  Event_118459_Name = {
    Text = "เสียงเปียโนลบหลู่"
  },
  Event_118460_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118460_Desc = {
    Text = "แรงบันดาลใจ ความลึกลับ และจินตนาการบ้าคลั่งเหล่านั้นผสมปนเปกัน กลมกลืนเป็นสีสันที่วิจิตรที่สุดในโลก.\nคุณเห็นอวกาศพับตัวภายในร่างกายของคุณ เวลาหมุนวนตามความปรารถนาของคุณ.\nในขณะนี้ คุณหยั่งรู้กาลเวลา ทำได้ทุกอย่าง รู้ทุกสิ่ง.\nแน่นอน คุณก็ต้องจ่ายราคาที่ต้องจ่ายเช่นกัน."
  },
  Event_118460_Name = {
    Text = "กล้องส่องทัศน์แห่งความคิด"
  },
  Event_118461_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118461_Desc = {
    Text = "วิญญาณแห่งความวุ่นวายชี้นำทางข้างหน้าให้คุณด้วยเสียงร้องไห้แหลมคม\nนั่นเป็นเส้นทางที่ปลอดภัยหรือไม่? คุณไม่รู้\nทางเลือกเดียวของคุณ คือเดินหน้าต่อไป."
  },
  Event_118461_Name = {
    Text = "ประภาคารแห่งวิญญาณ"
  },
  Event_118462_ChoiceDesc1 = {
    Text = "【ฟังเสียงร้องเพลง】ได้รับ 40 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_118462_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】ได้รับ 25 รอยดำ，แล้วจากไป"
  },
  Event_118462_Desc = {
    Text = "อีกาสีดำสนิทกำลังร้องไห้.\nอีกาสีดำสนิทกำลังตะโกน.\nอีกาสีดำสนิทกำลังคำราม.\nแต่ในหูของผู้คน มันเพียงแค่กำลังร้องเพลง.\n「อา เสียงเพลงที่ไร้กังวลเหลือเกิน อยากเป็นอีกาสักตัวจัง จะได้ห่างไกลจากความทุกข์ของโลกมนุษย์」"
  },
  Event_118462_Name = {
    Text = "เสียงคร่ำครวญที่ไม่มีใครรับรู้"
  },
  Event_118463_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118463_Desc = {
    Text = "วิญญาณแห่งความโกลาหลส่งเสียงถอนหายใจอันเศร้าโศก\nมันค่อยๆ สลายไป แต่เสียงถอนหายใจอันเศร้าโศกนั้น ราวกับมีตัวตน ตกลงบนหัวใจของคุณ\nตุ้บตุ้บ จังหวะหัวใจของคุณดังขึ้นพร้อมกับเสียงดนตรีของพิธีกรรม."
  },
  Event_118463_Name = {
    Text = "ประภาคารแห่งวิญญาณ"
  },
  Event_118464_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_118464_Desc = {
    Text = "「อา อา ช่างเป็นลูกแกะที่ศรัทธาแรงกล้าเสียจริง!」\nเสียงนั้นอุทานด้วยความปีติยินดีเต็มเปี่ยมด้วยคำสรรเสริญ\n「เมื่อองค์เจ้านายของเราตื่นขึ้น ลูกแกะอย่างเจ้าย่อมจะได้พบที่พักพิงในอาณาจักรแห่งเทพที่สูงส่งและยิ่งใหญ่นั้น...」"
  },
  Event_118464_Name = {
    Text = "การเทศนาของผู้ไร้รูป"
  },
  Event_118465_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118465_Desc = {
    Text = "「ท้องฟ้า」โอบรับความดื้อรั้นของคุณ\nสักวันหนึ่ง เด็กที่หลงทางจะกลับสู่อ้อมกอดของแม่\nเพราะ คุณไม่มีที่ไหนให้หนี."
  },
  Event_118465_Name = {
    Text = "อ้อมกอดแห่งมหาสมุทร"
  },
  Event_118466_ChoiceDesc1 = {
    Text = "【ยอมรับอ้อมกอด】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118466_ChoiceDesc2 = {
    Text = "【ปฏิเสธอ้อมกอด】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118466_ChoiceDesc3 = {
    Text = "【ว่ายขึ้นผิวน้ำ】ได้รับ 25 รอยดำ"
  },
  Event_118466_Desc = {
    Text = "โลกพลิกคว่ำในสายตาของคุณ\nในขณะนี้ ทะเลลึกที่ล้อมรอบคุณคือ「ท้องฟ้า」\nในความเจ็บปวดที่เกือบจมน้ำตาย「ท้องฟ้า」สีน้ำเงินเข้มนี้เข้ามาใกล้อย่างอ่อนโยน ตั้งใจจะโอบกอดคุณไว้\nมันจะไม่ตัดสิน มีแต่จะมอบให้."
  },
  Event_118466_Name = {
    Text = "อ้อมกอดแห่งมหาสมุทร"
  },
  Event_118467_ChoiceDesc1 = {
    Text = "【ตวาดพวกมัน】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」ถูกทำให้ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118467_ChoiceDesc2 = {
    Text = "【ตอบสนองต่อพวกมัน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_118467_ChoiceDesc3 = {
    Text = "【เพิกเฉยพวกมัน】ได้รับ 50 ตราดำ"
  },
  Event_118467_Desc = {
    Text = "วิญญาณสามดวงที่มีรูปร่างเลือนลางขวางทางคุณไว้\nเงาหนึ่งก้มกราบคุณอย่างศรัทธา วิงวอนให้คุณประทานเลือด เลือดที่ไหลเวียนของคุณคือเครื่องบูชาที่ดีที่สุดสำหรับพระเจ้า\nเงาหนึ่งยกมีดขึ้นอย่างเย็นชา ตั้งใจจะตัดเนื้อหนังของคุณ เนื้อมนุษย์ที่ยังไม่กลายพันธุ์ ย่อมสามารถเอาชนะใจพระเจ้าได้\nเงาสุดท้ายเพียงจ้องมองคุณอย่างเงียบงัน หวังให้คุณพรากชีวิตของมันไป เพื่อพิสูจน์ศรัทธาที่แรงกล้าที่สุด."
  },
  Event_118467_Name = {
    Text = "เครื่องบูชาที่ดีที่สุด"
  },
  Event_118468_ChoiceDesc1 = {
    Text = "【ฟังเสียงร้องเพลง】ได้รับ 30 รอยดำ, ได้รับผล「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_118468_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_118468_Desc = {
    Text = "อีกาสีดำสนิทกำลังร้องไห้.\nอีกาสีดำสนิทกำลังตะโกน.\nอีกาสีดำสนิทกำลังคำราม.\nแต่ในหูของผู้คน มันเพียงแค่กำลังร้องเพลง.\n「อา เสียงเพลงที่ไร้กังวลเหลือเกิน อยากเป็นอีกาสักตัวจัง จะได้ห่างไกลจากความทุกข์ของโลกมนุษย์」"
  },
  Event_118468_Name = {
    Text = "เสียงคร่ำครวญที่ไม่มีใครรับรู้"
  },
  Event_118469_ChoiceDesc1 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_118469_ChoiceDesc2 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_118469_ChoiceDesc3 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_118469_Desc = {
    Text = "「ไม่! เราไม่ต้องการสิ่งเหล่านี้! เราต้องการสิ่งที่... อร่อยกว่านี้」\n「นั่นก็คือ... เลือดเนื้อของเจ้า!」\nฝูงหนูส่งเสียงร้องแหลม พุ่งเข้าหาคุณ\nดูเหมือนว่าความเมตตาที่มากเกินไป บางครั้งกลับนำมาซึ่งปัญหา."
  },
  Event_118469_Name = {
    Text = "ฝูงหนูหิวโหย"
  },
  Event_118470_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118470_Desc = {
    Text = "ความเคารพของคุณได้รับความชื่นชอบจากดวงตาเหล่านั้น\nก่อนที่จะหายไป พวกมันมอบของขวัญให้คุณผ่านกระแสน้ำที่ไหลเชี่ยว\nนั่นคือหลักฐานที่ทะเลลึกฝึกฝนคุณ."
  },
  Event_118470_Name = {
    Text = "ตาแห่งทะเลลึก"
  },
  Event_118471_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118471_Desc = {
    Text = "ภายใต้สายตาที่ไม่ปิดบังของคุณ ทะเลลึกค่อยๆ ตื่นขึ้น\nน้ำทะเลไหลเชี่ยวอย่างคลั่งไคล้รอบตัวคุณ นำมาซึ่งเสียงพร่ำเพ้อที่ไม่อาจเอ่ยนาม\nจงรับรู้ความโกรธของทะเลลึก นี่คือพรและคำสาป."
  },
  Event_118471_Name = {
    Text = "ตาแห่งทะเลลึก"
  },
  Event_118472_ChoiceDesc1 = {
    Text = "【ฟังเสียงเพลง】ได้รับ 20 รอยดำ ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_118472_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_118472_Desc = {
    Text = "อีกาสีดำสนิทกำลังร้องไห้.\nอีกาสีดำสนิทกำลังตะโกน.\nอีกาสีดำสนิทกำลังคำราม.\nแต่ในหูของผู้คน มันเพียงแค่กำลังร้องเพลง.\n「อา เสียงเพลงที่ไร้กังวลเหลือเกิน อยากเป็นอีกาสักตัวจัง จะได้ห่างไกลจากความทุกข์ของโลกมนุษย์」"
  },
  Event_118472_Name = {
    Text = "เสียงคร่ำครวญที่ไม่มีใครรับรู้"
  },
  Event_118473_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118473_Desc = {
    Text = "เลือด เนื้อ ชีวิต\nเครื่องบูชาถูกจัดเตรียมไว้แล้ว ต่อจากนี้เพียงแค่รอคอยงานเลี้ยงของเทพเจ้าอย่างเงียบๆ"
  },
  Event_118473_Name = {
    Text = "เครื่องบูชาที่ดีที่สุด"
  },
  Event_118474_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118474_Desc = {
    Text = "ผีเสื้อเข้าใจการปฏิเสธของคุณ\nปีกที่เปื้อนของเหลวสีดำสั่นไหวอีกครั้ง โยกเยกบินอยู่ในความมืด\nไม่นาน ความมืดก็กลืนกินผีเสื้ออีกครั้ง คราวนี้ มันไม่มีแรงดิ้นรนอีกแล้ว."
  },
  Event_118474_Name = {
    Text = "คำขอของผีเสื้อ"
  },
  Event_118475_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118475_Desc = {
    Text = "ผีเสื้อเกาะลงบนฝ่ามือของคุณ สิ่งที่ตกลงมาด้วยคือของเหลวสีดำจากปีกอันสวยงามของมัน\nในเสียงถอนหายใจของคุณ ปีกอันสวยงามค่อยๆ หลอมละลาย ผสานเข้ากับของเหลวสีดำกลายเป็นรูปทรงอันสับสนที่ไม่อาจระบุได้\nผีเสื้อตัวนี้ไม่ต้องเผชิญกับความมืดอีกต่อไปแล้ว\nมันหลับใหลอยู่ในฝ่ามือของคุณ."
  },
  Event_118475_Name = {
    Text = "คำขอของผีเสื้อ"
  },
  Event_118477_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118477_Desc = {
    Text = "อีกาที่ร้องจนเสียงแหบในที่สุดก็หลับตาลง.\nในความแค้นที่ไม่มีใครรู้ ไม่มีใครรับรู้ มันสิ้นลมหายใจสุดท้าย กลายเป็นแอ่งน้ำดำข้น."
  },
  Event_118477_Name = {
    Text = "เสียงคร่ำครวญที่ไม่มีใครรับรู้"
  },
  Event_118478_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118478_Desc = {
    Text = "「ขอบคุณนะ...」\nหัวใจที่เต้นระรัวกระโจนไปสู่ที่ไกลอย่างร่าเริง\nไม่นานหลังจากนั้น เสียงเคี้ยวเนื้อและเลือดก็ดังขึ้นจากใต้ทะเลลึกอันมืดมิด."
  },
  Event_118478_Name = {
    Text = "กฎแห่งผู้แข็งแกร่ง"
  },
  Event_118479_ChoiceDesc1 = {
    Text = "【ยอมรับคำเชิญ】ได้รับผลกระทบจาก「(Skill.Arg1)」，ได้รับสิ่งสร้างแห่งคำสาป-「(RelicConfig.Arg2)」"
  },
  Event_118479_ChoiceDesc2 = {
    Text = "【ปฏิเสธคำเชิญ】เลือกทำลายสิ่งสร้าง 1 ชิ้น เพื่อรับรางวัล 1 รายการ"
  },
  Event_118479_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_118479_Desc = {
    Text = "「ทุกสิ่งบนเรือลำนี้ จะต้องเป็นส่วนหนึ่งของสวนสวรรค์แห่งวัฏจักรที่ล่มสลายและเริ่มต้นใหม่อย่างไม่สิ้นสุด」\nเสียงดนตรีอันบ้าคลั่งดังก้องในจิตใจของคุณ นั่นคือการเปิดเผยจากเจตจำนงที่ไร้รูปร่าง\n「ที่นี่ไม่มีเสียงร้องไห้ ไม่มีความเศร้า มีเพียงเสียงเพลงศักดิ์สิทธ์อันบริสุทธิ์และเสียงหัวเราะนิรันดร์」\n「เจ้าเต็มใจที่จะเข้าร่วมสวนสวรรค์ เป็นส่วนหนึ่งของเสียงเพลงอันสมบูรณ์แบบนี้หรือไม่?」"
  },
  Event_118479_Name = {
    Text = "เพลงสวด「สมบูรณ์แบบ」"
  },
  Event_118480_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_118480_Desc = {
    Text = "ในความเงียบงันของคุณ ดวงวิญญาณทั้งหลายสลายหายไปอย่างไร้เสียง\nผู้ที่ไม่เข้าใจศรัทธา ไม่คุ้มค่าที่พวกมันจะเสียเวลาด้วย"
  },
  Event_118480_Name = {
    Text = "เครื่องบูชาที่ดีที่สุด"
  },
  Event_123616_ChoiceDesc1 = {
    Text = "【รับสิ่งสร้างมาตรฐาน】"
  },
  Event_123616_Desc = {
    Text = "ตั้งค่าความคลั่งของผู้ปลุกตื่นทั้งหมดเป็น 100 ตั้งค่ากุญแจเงินเป็น 1000 ตั้งค่าชีวิตเป็น 80％.\nลบการ์ด 2 ใบ ใส่การ์ดอาการ 3 ใบ.\nตั้งค่าเตาหลอมเลือดเป็น 12.5％ เลือกการ์ด 4 ใบใส่มิติพิเศษ.\nรับชุดเรลิกมาตรฐาน."
  },
  Event_123616_Name = {
    Text = "ข้ามระหว่างทางด้วยการกดปุ่มเดียว"
  },
  Event_125696_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125696_Desc = {
    Text = "ความโกรธที่ไร้ที่มาผลักดันเจ้า เจ้ายกมือขึ้นขับไล่อย่างสุดแรง. เจ้าจมอยู่กับปริศนานานเกินไป บางทีสิ่งที่เจ้าโหยหาคือการต่อสู้อย่างสาแก่ใจ หรือแม้แต่เพียงแค่จุดจบ...\nแต่ฝูงกาไม่ได้ทำอะไรเลย. ภายใต้สายตาของเจ้า เหวลึกเลือนหายไป.\nฝูงกาหายไปที่ปลายเวที สถานที่ที่เจ้าจะต้องมุ่งไป."
  },
  Event_125696_Name = {
    Text = "เหวลึกแห่งฝูงกา"
  },
  Event_125697_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125697_Desc = {
    Text = "「ขี้ขลาด」เสียงหญิงสาวไม่ปิดบังความเยาะเย้ยในเสียงหัวเราะของเธอเลยแม้แต่น้อย\n「ไปเถอะ ไปให้ไกลที่สุดเท่าที่จะไกลได้」"
  },
  Event_125697_Name = {
    Text = "กุญแจแห่งโชคชะตา"
  },
  Event_125698_ChoiceDesc1 = {
    Text = "【ไล่】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125698_ChoiceDesc2 = {
    Text = "【รับฟัง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125698_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_125698_Desc = {
    Text = "เสียงเบาๆ ดังมาจากความมืด ผีเสื้อตัวหนึ่งร่วงลงบนฝ่ามือของคุณ คุณจำมันได้\n「คุณอาราคเน่... คุณไม่เคยทอดทิ้งพวกเรา ใช่ไหม?」\nลวดลายอันงดงามของผีเสื้อ จ้องมองไปยังคนข้างกายคุณ"
  },
  Event_125698_Name = {
    Text = "ชีวิตที่เหลือของผีเสื้อ"
  },
  Event_125699_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125699_Desc = {
    Text = "เสียงและตัวอักษรเหล่านั้นบุกรุกเข้าสู่จิตใจของคุณราวกับฝูงผึ้ง คุณกลั้นหายใจ สำรวมจิต ขับไล่ความคิดไร้สาระออกจากหัว\nการเพิกเฉยนั้นยากกว่าการอ่านมากมายนัก แต่คุณทำได้สำเร็จ"
  },
  Event_125699_Name = {
    Text = "โทรเลขมิติ"
  },
  Event_125700_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125700_Desc = {
    Text = "นั่นคือภาพลวงตาที่ศัตรูสร้างขึ้น!\nคุณส่ายหัว, ตื่นขึ้นมาอีกครั้ง, แล้วกำกุญแจเงินในมือให้แน่นอีกครั้ง."
  },
  Event_125700_Name = {
    Text = "เงาสะท้อนในแก้วเหล้า"
  },
  Event_125701_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125701_Desc = {
    Text = "เจ้าจ้องมองดวงตานั้นอย่างตั้งใจ พยายามเฝ้ามองและรับฟัง เจ้าพยายามเข้าไปในจิตใจของนักแสดง สัมผัสความทุกข์ทรมานที่เขากำลังเผชิญ\nเจ้าเข้าใกล้ เข้าใกล้ เจ้าทะลุผ่านร่างกายของเขา สัมผัสถึงวิญญาณของเขา...\nเจ้าลืมตาขึ้นอย่างกะทันหัน พบว่าตัวเองกำลังยืนอยู่กลางเวที น้ำตาไหลรินตามปลายนิ้ว\nนั่นคือคำสารภาพที่เจ้ามอบให้แก่ผู้ชม"
  },
  Event_125701_Name = {
    Text = "คำสารภาพของนักแสดง"
  },
  Event_125702_ChoiceDesc1 = {
    Text = "【พูดคุยกับเธอ】ลบการ์ดคำสั่ง 1 ใบ ได้รับตราดำ Arg1"
  },
  Event_125702_ChoiceDesc2 = {
    Text = "【นิ่งเงียบ】"
  },
  Event_125702_Desc = {
    Text = "「ตอนจบที่มีความสุขนั้นงดงามก็จริง แต่ความสุขอันเป็นเท็จนั้น ไม่มีวันสัมผัสหัวใจของผู้ชมได้...」\nนักเขียนบทหลับตาครุ่นคิด เธอไม่พอใจกับตอนจบนี้"
  },
  Event_125702_Name = {
    Text = "บทสรุปของบทละคร"
  },
  Event_125703_ChoiceDesc1 = {
    Text = "【ฟังเสียงร้องเพลง】ได้รับ 35 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_125703_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_125703_Desc = {
    Text = "「เอี๊ยด——เอี๊ยด——เทพีแห่งโชคชะตาหมุนกี่ปั่นด้ายของเธอ\nเอี๊ยด——เอี๊ยด——สายด้ายแห่งโชคชะตารวมกันในมือของเธอ」"
  },
  Event_125703_Name = {
    Text = "คำทำนายสุดท้าย"
  },
  Event_125704_ChoiceDesc1 = {
    Text = "【ตัวเอง】สุ่มรับการ์ดคำสั่ง 3 ใบจากสำรับ เลือก 1 ใบเพื่อทำสำเนา"
  },
  Event_125704_ChoiceDesc2 = {
    Text = "【วิลเลียม】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125704_ChoiceDesc3 = {
    Text = "【ไม่มีใคร】ได้รับ 25 ตราประทับดำ"
  },
  Event_125704_Desc = {
    Text = "เจ้ามั่นใจว่าตัวเองไม่ได้เมา แต่เมื่อมองลงไปในแก้วเหล้า เจ้าจมดิ่งลงสู่ทะเลสาบอันเงียบสงบ\nในแก้วอันสง่างามสะท้อนเงาร่างหนึ่ง นั่นคือใคร?"
  },
  Event_125704_Name = {
    Text = "เงาสะท้อนในแก้วเหล้า"
  },
  Event_125705_ChoiceDesc1 = {
    Text = "【รับฟัง】ได้รับสิ่งประดิษฐ์ระดับเงิน「(RelicConfig.Arg1)」"
  },
  Event_125705_ChoiceDesc2 = {
    Text = "【ขับไล่】ได้รับ 75 ตราดำ, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125705_Desc = {
    Text = "เมื่อคุณเข้าใกล้พลังของพลาสมิดภายในร่างกาย, ฝูงอีกาปรากฏขึ้นในความคิดของคุณ, โฉบวนอยู่ในพื้นที่จิตใจที่วุ่นวายของคุณ.\n\nฝูงอีกาล้อมรอบคุณ, เหวลึกหนึ่งแห่งหมุนวนอยู่เหนือหัวของคุณอย่างกลับหัว.\nอีกาแสนตัวส่งเสียงร้องพร้อมกัน, ดุจคำทำนายแห่งการเยาะเย้ย."
  },
  Event_125705_Name = {
    Text = "เหวลึกแห่งฝูงกา"
  },
  Event_125706_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125706_Desc = {
    Text = "เจ้ากับอาราคเนพยายามรักษาเสถียรภาพของโชคชะตาที่กำลังพังทลายรอบข้าง ความพยายามของพวกเจ้าได้ผลเพียงเล็กน้อย แต่ก็เพียงพอแล้ว ด้วยเวลาที่แย่งชิงมาได้ พวกเจ้าเข้าใกล้เนฟเรียต่อไป\nเจ้ามาที่นี่ เพื่อมอบอิสรภาพให้แก่เธอ"
  },
  Event_125706_Name = {
    Text = "ม่านปิดแห่งใยชะตากรรม"
  },
  Event_125707_ChoiceDesc1 = {
    Text = "【ฟังเสียงเพลง】ได้รับ 20 รอยดำ ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125707_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_125707_Desc = {
    Text = "「พวกมันตายไปพร้อมกับตาข่ายยักษ์ เงียบสงัดไร้เสียง」"
  },
  Event_125707_Name = {
    Text = "คำทำนายสุดท้าย"
  },
  Event_125708_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125708_Desc = {
    Text = "นั่นคือโทรเลขที่ส่งถึงนรกลึก\n「อย่ารีบร้อน ลูกๆ ของข้า ประตูคุกกำลังจะเปิดออก อิสรภาพของพวกเจ้าใกล้จะมาถึงแล้ว」"
  },
  Event_125708_Name = {
    Text = "โทรเลขมิติ"
  },
  Event_125709_ChoiceDesc1 = {
    Text = "【ไล่ออกไป】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125709_ChoiceDesc2 = {
    Text = "【รับฟัง】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับจารึก:「(EnchantConfig.Arg1)」"
  },
  Event_125709_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_125709_Desc = {
    Text = "ผีเสื้อตัวหนึ่งเกาะลงบนมือของคุณเบาๆ ลวดลายอันงดงามราวกับดวงตา จ้องมองคุณอย่างเงียบงัน\nบางที มันอยากจะบอกอะไรคุณสักอย่าง?"
  },
  Event_125709_Name = {
    Text = "การพักผ่อนของผีเสื้อ"
  },
  Event_125710_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125710_Desc = {
    Text = "ดวงตาที่เปี่ยมด้วยความเศร้าโศกยี่สิบคู่จ้องมองมาที่เจ้า. อีกาหยุดร้องเพลง พาคำทำนายสุดท้ายจากไปจากใยแมงมุมที่ใกล้จะขาดผุพัง."
  },
  Event_125710_Name = {
    Text = "คำทำนายสุดท้าย"
  },
  Event_125711_ChoiceDesc1 = {
    Text = "【ก้มตัวตรวจสอบ】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」"
  },
  Event_125711_ChoiceDesc2 = {
    Text = "【ยกเลิกการดู】ได้รับ 50 รอยดำ"
  },
  Event_125711_Desc = {
    Text = "เมื่อเดินผ่านหัวมุมถนน เจ้าเห็นโรงฉายภาพยนตร์เรียบง่ายแห่งหนึ่ง เจ้าจำไม่ได้ว่าเลนดิเนียนเคยมีร้านแบบนี้อยู่"
  },
  Event_125711_Name = {
    Text = "โรงฉายแห่งความทรงจำ"
  },
  Event_125712_ChoiceDesc1 = {
    Text = "【ยอมรับชะตากรรม】เลือก 1 จาก 3 การ์ดคำสั่งเพื่อรับการสลักตรา:「(EnchantConfig.Arg1)」"
  },
  Event_125712_ChoiceDesc2 = {
    Text = "【ต่อต้านชะตากรรม】ติดเชื้อ「(Skill.Arg1)」, สลักตราใหม่ สูงสุด 2 ครั้ง"
  },
  Event_125712_Desc = {
    Text = "「อา เราพบกันอีกแล้วนะ ที่รัก.」\nเจ้าเริ่มเพลิดเพลินกับเสียงหญิงสาวที่ก้องอยู่ในสมอง. มันอ่อนโยน ยั่วยวน ดุจใยแมงมุมที่ดักจับแมลง.\n「มาเถอะ บอกฉันสิ เจ้ายินดีจะยอมรับชะตากรรมของตัวเองไหม?」"
  },
  Event_125712_Name = {
    Text = "กรงแห่งโชคชะตา"
  },
  Event_125713_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125713_Desc = {
    Text = "「มนุษย์โง่เขลา ข้าสนิทกับแกมากหรือไง?」\nแมวดำกลอกตาใส่เจ้าอย่างรังเกียจ แล้วหันหลังกลับไป\n「ออกไปจากที่นี่เถอะ ครั้งหน้าอย่าทำเรื่องโง่ๆ แบบนี้อีก」"
  },
  Event_125713_Name = {
    Text = "ภาพลวงแปรรูป"
  },
  Event_125714_ChoiceDesc1 = {
    Text = "【ถ่ายรูป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ:「(EnchantConfig.Arg1)」"
  },
  Event_125714_ChoiceDesc2 = {
    Text = "【เปลี่ยนท่าโพส】ติดเชื้อ「(Skill.Arg1)」 เปลี่ยนตราประทับที่ได้รับจากตัวเลือก 1 สามารถใช้ได้สองครั้ง"
  },
  Event_125714_Desc = {
    Text = "กล้องตัวหนึ่งยืนอยู่อย่างโดดเดี่ยวบนเวที เลนส์สีดำสนิทจ้องมองมายังเจ้า ราวกับดวงตารวมลึกลับที่ถูกสร้างขึ้นโดยเทพแห่งจักรกล\n「โรงละครแห่งนี้ไม่มีผู้ชมมานานแล้ว...ยินดีต้อนรับ! ยินดีต้อนรับ! มาถ่ายรูปกันเถอะ! ฟรีทั้งหมด!」\nกล้องตะโกนด้วยความตื่นเต้น บนเวทีที่ไม่มีใครสนใจแห่งนี้ มันคือตัวเอกเพียงหนึ่งเดียว"
  },
  Event_125714_Name = {
    Text = "ภาพถ่ายจากที่นั่งผู้ชม"
  },
  Event_125715_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125715_Desc = {
    Text = "「คนที่ไม่มีคำถามต่อโชคชะตา จะหวังคำตอบจากโชคชะตาได้อย่างไร?」"
  },
  Event_125715_Name = {
    Text = "กุญแจแห่งโชคชะตา"
  },
  Event_125716_ChoiceDesc1 = {
    Text = "【คิดหาทางออก】ได้รับเรลิกเงิน「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125716_ChoiceDesc2 = {
    Text = "【ปล่อยไปตามธรรมชาติ】ได้รับเรลิกทอง「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」,「(Skill.Arg3)」"
  },
  Event_125716_ChoiceDesc3 = {
    Text = "【ผุดขึ้น】ได้รับ 25 รอยดำ"
  },
  Event_125716_Desc = {
    Text = "เวทีใหม่ ชีวิตสองชีวิตที่ซ้อนทับกัน... ระหว่างทางหลบหนีตำรวจ เจ้าจัดระเบียบเรื่องราวที่อาราคเน่บอกเจ้า\nท่ามกลางความคิดอันสับสน เจ้าจมลงสู่ทะเลลึกอันสงบ"
  },
  Event_125716_Name = {
    Text = "ความสงบ"
  },
  Event_125717_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125717_Desc = {
    Text = "ผีเสื้อบินมาเกาะบนไหล่ของคุณ เข้ามาใกล้หูของคุณ คุณตั้งใจฟัง แต่ได้ยินเพียงเสียงกระพือปีกของมัน ราวกับเสียงถอนหายใจไร้เสียง\nในขณะที่คุณรับฟัง ปีกอันวิจิตรค่อยๆ ละลาย ผีเสื้อหลับใหลบนไหล่ของคุณ\nคุณจะไม่มีวันรู้ถ้อยคำที่มันต้องการบอกคุณอีกแล้ว"
  },
  Event_125717_Name = {
    Text = "ชีวิตที่เหลือของผีเสื้อ"
  },
  Event_125718_ChoiceDesc1 = {
    Text = "【เคี้ยว】ปลุกตื่นผู้ถูกปลุกสุ่ม 1 ตน, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_125718_ChoiceDesc2 = {
    Text = "【ปฏิเสธ】ได้รับสูงสุด 3 ออริซอน"
  },
  Event_125718_Desc = {
    Text = "「หิวแล้วใช่ไหม แขกที่รัก?」\nเสียงเหนียวหนึบดังขึ้นจากหลังเคาน์เตอร์บาร์ เธอหันกลับไป ไม่เห็นสิ่งใดเลย\n「ของว่างของบาร์หน้ากากเที่ยงคืนก็มีชื่อเสียงไม่น้อย ลองชิมดูไหม?」"
  },
  Event_125718_Name = {
    Text = "รสชาติแห่งโชคชะตา"
  },
  Event_125719_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125719_Desc = {
    Text = "เจ้าไม่กล้าอ่านข้อความบนนั้นอย่างพลการ เพียงแต่พินิจพิเคราะห์ซองจดหมายอันประณีตอย่างถี่ถ้วน\nตราครั่งบนซองจดหมายสลักตราตระกูลที่เลือนราง ด้านบนเขียนด้วยอักษรดอกไม้อันสวยงามว่า:\n「ถึงคุณหนูอาราคเน่ผู้เพิ่งถือกำเนิด」\n「พ่อบ้านผู้ซื่อสัตย์ของท่าน เอ็ดการ์」"
  },
  Event_125719_Name = {
    Text = "ราตรีสวัสดิ์ คุณเอ็ดการ์"
  },
  Event_125720_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125720_Desc = {
    Text = "「เข้าใจแล้วค่ะ ฉันเข้าใจแล้ว พี่สาว...」\n「นักเขียนบทไม่เคยสามารถเปลี่ยนแปลงตอนจบของตัวละครได้ ชะตากรรมอันแสนเศร้านั้นถูกกำหนดไว้แล้ว แม้แต่พี่สาว ก็ไม่เคยเปลี่ยนแปลงมันได้...」\nเสียงสะอื้นอันเศร้าโศกหายไป เครื่องพิมพ์ดีดของนักเขียนบทกลายเป็นผีเสื้อทีละตัว กระจายไปในโรงละครแห่งโชคชะตาอันว่างเปล่า ไม่เห็นร่องรอยอีกต่อไป"
  },
  Event_125720_Name = {
    Text = "บทสรุปของบทละคร"
  },
  Event_125721_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125721_Desc = {
    Text = "นักแสดงไร้นาม จังหวะเต้นอันตราย... แล้วมันจะเป็นอะไรไป? ไม่มีอะไรจะเลวร้ายไปกว่าโชคชะตาเองอีกแล้ว\nเจ้ายื่นมือออกไป ก้าวขึ้นบนเวที หุ่นเชิดจับมือเจ้า เต้นรำอย่างสนุกสนาน\nเจ้าได้ยินเสียงปรบมือ"
  },
  Event_125721_Name = {
    Text = "เต้นรำสามคน"
  },
  Event_125722_ChoiceDesc1 = {
    Text = "【ฟังเสียงร้องเพลง】ได้รับ 25 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_125722_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_125722_Desc = {
    Text = "「พวกมันเต้นรำ พวกมันร้องเพลง เอี๊ยด——เอี๊ยด——」"
  },
  Event_125722_Name = {
    Text = "คำทำนายสุดท้าย"
  },
  Event_125723_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125723_Desc = {
    Text = "ผู้นำทาง, สหาย, เพื่อนร่วมทางเพียงหนึ่งเดียวในมิติแห่งความโดดเดี่ยว.\nพวกคุณจะร่วมกันจัดการทุกสิ่งที่นี่แล้วกลับไปยังคาดาธ. คุณไม่เคยสงสัยในเรื่องนี้เลย."
  },
  Event_125723_Name = {
    Text = "เงาสะท้อนในแก้วเหล้า"
  },
  Event_125724_ChoiceDesc1 = {
    Text = "【ลองดู】ติดเชื้อ「(Skill.Arg1)」 เข้าสู่เกมเสี่ยงโชค"
  },
  Event_125724_ChoiceDesc2 = {
    Text = "【หรือว่าจะไม่เอาดีกว่า】ได้รับ25รอยดำ"
  },
  Event_125724_Desc = {
    Text = "ที่มุมตรอกซอกซอย มือสกปรกคู่หนึ่งขวางทางเจ้า\nขอทานในชุดขาดวิ่นค่อยๆ เข้ามาใกล้ สายตาโลภโมโทสันราวกับไฮยีน่าที่เห็นซากศพ\n「มาเลย! มาเล่นสักตา! ข้าจะบอกทุกสิ่งที่เจ้าอยากรู้! ขอแค่เจ้าชนะ...」"
  },
  Event_125724_Name = {
    Text = "การพนันริมถนน"
  },
  Event_125725_ChoiceDesc1 = {
    Text = "【เพิกเฉย】ลบการ์ดคำสั่ง 1 ใบ, ได้รับ 25 ตราประทับดำ"
  },
  Event_125725_ChoiceDesc2 = {
    Text = "【อ่าน】คัดลอกการ์ด 1 ใบจากกองการ์ด, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_125725_Desc = {
    Text = "ตุ๊ก ตุ๊ก ตุ๊ก, ตุ๊ก ตุ๊ก ตุ๊ก...\nมุมบาร์ว่างเปล่าไร้ผู้คน เครื่องโทรเลขดังกังวานใส ราวกับบทเพลงเปียโนอันไพเราะ"
  },
  Event_125725_Name = {
    Text = "โทรเลขมิติ"
  },
  Event_125726_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125726_Desc = {
    Text = "「หุบปาก ข้าเป็นแมว ข้าไม่อยากฟังเรื่องโง่ๆ ของพวกแก」\nแมวดำถอนหายใจแล้วหันหลังกลับไป\n「ออกไปจากที่นี่เถอะ ครั้งหน้าอย่าทำเรื่องโง่ๆ แบบนี้อีก」"
  },
  Event_125726_Name = {
    Text = "ภาพลวงแปรรูป"
  },
  Event_125727_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125727_Desc = {
    Text = "สิ่งที่เธอพูดอาจไม่ผิด นั่นคือตัวเธอ คือความคิดที่ซ่อนเร้นและสกปรกที่สุดในส่วนลึกของหัวใจ\nทุกคนล้วนเห็นแก่ตัว เธอไม่เคยสูงส่งอย่างที่คนอื่นคิด\nเธอลิ้มรสความเจ็บปวดอันต่ำช้านั้น เธอรู้ว่าสิ่งที่ผ่านไปแล้วก็ผ่านไป และการไถ่บาปของเธออยู่เบื้องหน้า"
  },
  Event_125727_Name = {
    Text = "ความเจ็บปวดแผ่ขยาย"
  },
  Event_125728_ChoiceDesc1 = {
    Text = "【พูดคุยกับเธอ】ลบการ์ดคำสั่ง 1 ใบ ได้รับตราดำ Arg1"
  },
  Event_125728_ChoiceDesc2 = {
    Text = "【นิ่งเงียบ】"
  },
  Event_125728_Desc = {
    Text = "「ตอนจบที่ยิ่งใหญ่นั้นสมจริงเพียงใด แต่ความเป็นจริงของเราก็แสนเศร้าอยู่แล้ว แม้แต่ในเรื่องราว เราก็ไม่สามารถมอบที่พักพิงอันงดงามให้เธอได้หรือ...」\nนักเขียนบทหลับตาครุ่นคิด เธอไม่พอใจกับตอนจบนี้"
  },
  Event_125728_Name = {
    Text = "บทสรุปของบทละคร"
  },
  Event_125729_ChoiceDesc1 = {
    Text = "【ออก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_125729_Desc = {
    Text = "กลิ้งๆ ลูกเต๋าเต้นรำอย่างตื่นเต้นในถ้วยเต๋า เต้นจนหมดแรง\n\n「ทำไม... ทำไมไม่เคยมีใครชนะได้เลย!...」"
  },
  Event_125729_Name = {
    Text = "การพนันริมถนน"
  },
  Event_125730_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125730_Desc = {
    Text = "คุณพยายามเข้าใกล้มัน ตั้งใจฟังมันอย่างจริงจัง\nผีเสื้อกระพือปีก บินจากฝ่ามือของคุณไป\nคุณไม่ได้ยินอะไรเลย"
  },
  Event_125730_Name = {
    Text = "การพักผ่อนของผีเสื้อ"
  },
  Event_125731_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125731_Desc = {
    Text = "เมื่อเผชิญกับการไล่ของคุณ ผีเสื้อไม่สะทกสะท้าน\nมันไล่ตามฝ่ามือของคุณอย่างดื้อดึง จนกระทั่งคุณโบกแขนครั้งสุดท้าย มันจึงเลือกที่จะจากไป\nคุณรู้สึกเสียใจเล็กน้อย บางที คุณควรฟังสิ่งที่มันจะพูด?"
  },
  Event_125731_Name = {
    Text = "การพักผ่อนของผีเสื้อ"
  },
  Event_125732_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125732_Desc = {
    Text = "หมอกดำสั่นไหวอย่างสิ้นหวัง เสียงร่ำไห้ของขอทานแหบแห้งจนสุดเสียง\nลูกเต๋าและขอทานหายวับไปหลังเจ้ากะพริบตาครั้งหนึ่ง ในหมวกทรงสูงเก่าๆ หลงเหลือเพียงรางวัลจากเกม"
  },
  Event_125732_Name = {
    Text = "การพนันริมถนน"
  },
  Event_125733_ChoiceDesc1 = {
    Text = "【เข้าร่วมงานเฉลิมฉลอง】ติดเชื้อ「(Skill.Arg1)」 ได้รับสิ่งประดิษฐ์สาปแช่ง–「(RelicConfig.Arg2)」"
  },
  Event_125733_ChoiceDesc2 = {
    Text = "【หยุดการบรรเลง】เลือกทำลายสิ่งประดิษฐ์ 1 ชิ้น ได้รับรางวัล 1 อย่าง"
  },
  Event_125733_ChoiceDesc3 = {
    Text = "【ปิดหู】ได้รับ 50 ตราประทับดำ"
  },
  Event_125733_Desc = {
    Text = "「อา! ดนตรี! การแสดงอันยิ่งใหญ่จะขาดดนตรีได้อย่างไร!!」\nซิมโฟนีที่ไม่ประสานกันดังก้องในโรงละครที่แตกสลาย ราวกับงานเฉลิมฉลองแห่งความโกลาหล นักแสดงจากนรกลึกเต้นรำและโห่ร้องในบทเพลงสรรเสริญอันไร้ระเบียบนี้ นั่นคือโน้ตเพลงที่พวกเขาดำรงชีวิตอยู่ได้"
  },
  Event_125733_Name = {
    Text = "บทเพลงแห่งโชคชะตา"
  },
  Event_125734_ChoiceDesc1 = {
    Text = "【ได้รับ 100 รอยดำ】"
  },
  Event_125734_ChoiceDesc2 = {
    Text = "【การ์ดคำสั่งสุ่ม 2 ใบรับตราประทับ：「(EnchantConfig.Arg1)」】"
  },
  Event_125734_Desc = {
    Text = "สายใยโชคชะตาที่มองไม่เห็นเต้นรำในท่วงทำนอง ท่ามกลางเสียงอันสับสนวุ่นวาย เจ้าค่อยๆ จับทำนองอันน่าหลงใหลนั้นได้——ใช่แล้ว นั่นคือเสียงที่โชคชะตาควรจะเป็น\nผู้ถูกทอดทิ้งแห่งนรกลึกโห่ร้องต้อนรับเจ้า พวกเขาห้อมล้อมเจ้า พาเจ้าเข้าสู่งานเฉลิมฉลองอันไร้ระเบียบของพวกเขา\nยินดีด้วย ผู้ชมผู้โชคดี! บัดนี้ เจ้าจะร่วมกับนักแสดงคำนับลาโชคชะตา"
  },
  Event_125734_Name = {
    Text = "บทเพลงแห่งโชคชะตา"
  },
  Event_125735_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125735_Desc = {
    Text = "เจ้าไม่อาจแยกแยะความหมายของเสียงนี้ได้ แต่เจ้ารู้ว่ามันต้องหยุด\nแสงเงินวาดวงราวกับใบมีดที่คลั่ง จังหวะนั้นกลับกลมกลืนกับโน้ตเพลงอย่างน่าอัศจรรย์\nเมื่อเจ้ารู้ตัวอีกครั้ง โน้ตเพลงก็หยุดลงไปตั้งแต่เมื่อไหร่ไม่รู้ เจ้าไม่ได้ยินเสียงใดอีกต่อไป สิ่งที่เจ้าเห็นมีเพียงราตรีกาล สิ่งที่เจ้าได้ยินมีเพียงความเงียบงัน\nความอึกทึกไร้ระเบียบกับความเงียบสนิทสมบูรณ์ สิ่งใดน่ากลัวกว่ากัน...ผู้พิทักษ์ความลับ?"
  },
  Event_125735_Name = {
    Text = "บทเพลงแห่งโชคชะตา"
  },
  Event_125736_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125736_Desc = {
    Text = "เจ้ายื่นมือออกไป ผีเสื้อตัวหนึ่งค่อยๆ เกาะลงบนมือของเจ้า.\nถูกต้อง. ความตาย การเลือนสลาย การผ่านพ้น... ผีเสื้อถือกำเนิดจากรังไหม ความเจ็บปวดคือดินที่หล่อเลี้ยงศิลปะชั่วนิรันดร์.\nในฐานะผู้ชมที่ยอดเยี่ยม นี่คือสัจธรรมที่เจ้าต้องเข้าใจ."
  },
  Event_125736_Name = {
    Text = "เบ่งบานท่ามกลางการเลือนสลาย"
  },
  Event_125737_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125737_Desc = {
    Text = "นี่อาจเป็นกลอุบายอะไรสักอย่างของเนฟเรียอีกครั้ง\nผีเสื้อเข้าใจคำพูดของคุณ เสียงถอนหายใจไร้เสียงดังขึ้นในความมืด ปีกที่หยดย้อยด้วยของเหลวสีดำสนิทสั่นไหว ในไม่ช้า ร่างอันหนักอึ้งของผีเสื้อก็จมหายไปในความมืดอันไม่มีที่สิ้นสุด\nคุณจะไม่มีวันรู้ถ้อยคำที่มันต้องการบอกคุณอีกแล้ว"
  },
  Event_125737_Name = {
    Text = "ชีวิตที่เหลือของผีเสื้อ"
  },
  Event_125738_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_125738_Desc = {
    Text = "กลิ้งๆ ลูกเต๋าเต้นรำอย่างตื่นเต้นในถ้วยเต๋า เต้นจนหมดแรง\n\n「ทำไม... ทำไมไม่เคยมีใครชนะได้เลย!...」"
  },
  Event_125738_Name = {
    Text = "การพนันริมถนน"
  },
  Event_125739_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125739_Desc = {
    Text = "ตอนนี้การปล่อยให้ความคิดไหลบ่าอย่างไร้ทิศทางนั้นอันตราย เจ้าส่ายหัวแล้วรีบลอยขึ้นสู่ผิวน้ำ..."
  },
  Event_125739_Name = {
    Text = "ความสงบ"
  },
  Event_125740_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125740_Desc = {
    Text = "ไม่ใช่ทุกโน้ตเพลงที่ต้องการผู้ฟัง ไม่ใช่ทุกโชคชะตาที่ต้องการคำตอบ\nเจ้าปิดหูแน่น แล้วจากไปจากเวทีอันอึกทึกนี้\nเจ้ายังคงอยากรู้ความหมายของเสียงดนตรีที่ไม่ประสานนั้น แต่เจ้ารู้ว่า เจ้าได้เลือกทางเดียวที่ถูกต้องแล้ว"
  },
  Event_125740_Name = {
    Text = "บทเพลงแห่งโชคชะตา"
  },
  Event_125741_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125741_Desc = {
    Text = "แสงเงินทะลุทะลวงภาพลวง ฝูงแมวดำกลายเป็นแอ่งเมือกสีดำ\nจะแปลงร่างเป็นแมวดำเพื่อหลบหนีงั้นหรือ หนีสายตาของเจ้าไม่พ้นหรอก"
  },
  Event_125741_Name = {
    Text = "ภาพลวงแปรรูป"
  },
  Event_125742_ChoiceDesc1 = {
    Text = "【ยอมรับชะตากรรม】เลือก 1 จาก 3 การ์ดคำสั่งเพื่อรับการสลักตรา:「(EnchantConfig.Arg1)」"
  },
  Event_125742_Desc = {
    Text = "「ไม่มีใครต่อต้านชะตากรรมได้อย่างแท้จริงหรอก ที่รัก. เราไม่เคยมีสิทธิ์เลือกมาตั้งแต่แรก.」\nเสียงหญิงสาวกลายเป็นเศร้าสร้อยและห่างไกล. เจ้าไม่แน่ใจว่า เธอต้องการสนทนากับเจ้า หรือกับสิ่งอื่นบางอย่าง."
  },
  Event_125742_Name = {
    Text = "กรงแห่งโชคชะตา"
  },
  Event_125743_ChoiceDesc1 = {
    Text = "【ฟังเสียงร้องเพลง】ได้รับ 30 รอยดำ, ได้รับผล「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_125743_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_125743_Desc = {
    Text = "「หุ่นเชิดเข้าแถวเดินเข้ามา ก้าวเข้าสู่ตาข่ายยักษ์แห่งโชคชะตา」"
  },
  Event_125743_Name = {
    Text = "คำทำนายสุดท้าย"
  },
  Event_125744_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125744_Desc = {
    Text = "เจ้าเงยหน้ามองเหวลึกที่หมุนวนดุจกระแสน้ำ พยายามฟังวจนะของฝูงกา.\nแต่ฝูงกาไม่ได้พูดอะไรเลย. ภายใต้สายตาของเจ้า เหวลึกเลือนหายไป.\nฝูงกาหายไปที่ปลายเวที สถานที่ที่เจ้าจะต้องมุ่งไป."
  },
  Event_125744_Name = {
    Text = "เหวลึกแห่งฝูงกา"
  },
  Event_125745_ChoiceDesc1 = {
    Text = "【เห็นด้วยกับผีเสื้อ】ลบการ์ด 2 ใบ"
  },
  Event_125745_ChoiceDesc2 = {
    Text = "【ไม่เห็นด้วยกับผีเสื้อ】ได้รับสิ่งประดิษฐ์ต้องคำสาป「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125745_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ Arg1 รอยดำ"
  },
  Event_125745_Desc = {
    Text = "ม่านเวทีพลิ้วไหวในสายลม ในของเหลวสีดำที่ไหลจากศพ เจ้าเห็นฝูงผีเสื้อ.\n「ศิลปะที่แท้จริง ย่อมเบ่งบานท่ามกลางการเลือนสลายเสมอ... ใช่ไหมล่ะ ผู้พิทักษ์?」\nศพของนักเต้นกำลังยิ้มให้เจ้า. เจ้าได้ยินเสียงผีเสื้อกระพือปีก."
  },
  Event_125745_Name = {
    Text = "เบ่งบานท่ามกลางการเลือนสลาย"
  },
  Event_125746_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125746_Desc = {
    Text = "คำเล่ห์ลิ้นไม่อาจรบกวนเธอได้ เธอรู้ชัดว่าตนเองกำลังเดินอยู่บนเส้นทางแบบไหน รู้ว่าจุดหมายปลายทางอยู่ที่ใด\nหนามแหลมสลายไปในร่างกายของเธอ เธอก้าวเดินบนเส้นทาง เหมือนเช่นทุกวัน"
  },
  Event_125746_Name = {
    Text = "ความเจ็บปวดแผ่ขยาย"
  },
  Event_125747_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125747_Desc = {
    Text = "เธอหันหลังกลับ พยายามลืมดวงตาเหล่านั้นที่อยู่ข้างหลัง แต่เธอพบว่าร่างกายของตนเองดูเหมือนจะควบคุมได้ยากเหมือนเช่นเคย\nเธอรู้ดีว่า สายตาที่จ้องมองเหล่านั้น เธอไม่มีวันหนีพ้น"
  },
  Event_125747_Name = {
    Text = "ผู้ชม"
  },
  Event_125748_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125748_Desc = {
    Text = "ไม่ว่าจะด้วยความเคารพหรือความเกรงกลัว เจ้าไม่อยากแตะต้องมันอย่างง่ายดาย จึงวางซองจดหมายกลับที่เดิม ขณะที่เจ้ากำลังจะจากไป เสียงขุ่นมัวแต่อ่อนโยนดังขึ้นจากความมืดด้านหลังซองจดหมาย\n「ขอบคุณที่ท่านยังจดจำข้า คุณหนูอาราคเน่...」"
  },
  Event_125748_Name = {
    Text = "ราตรีสวัสดิ์ คุณเอ็ดการ์"
  },
  Event_125749_ChoiceDesc1 = {
    Text = "【พลังแห่งการปกป้อง】ได้รับเรลิกเงิน「(RelicConfig.Arg1)」"
  },
  Event_125749_ChoiceDesc2 = {
    Text = "【อิสรภาพแห่งการหลบหนี】การ์ดสุ่ม 1 ใบได้รับตราประทับ:「(EnchantConfig.Arg1)」"
  },
  Event_125749_ChoiceDesc3 = {
    Text = "【ปฏิเสธตอบ】ได้รับ 50 ตราดำ"
  },
  Event_125749_Desc = {
    Text = "แอลกอฮอล์จากหน้ากากเที่ยงคืนไหลเข้าสู่สมองของเจ้า ราวกับโซ่ตรวนที่พันธนาการร่างกาย ตามสายโซ่อันเย็นเยือก เสียงของหญิงสาวก้องอยู่ในหัวของเจ้า\n「บอกข้ามาสิ ที่รัก โชคชะตาที่เจ้าปรารถนา แท้จริงแล้วคืออะไร?」"
  },
  Event_125749_Name = {
    Text = "กุญแจแห่งโชคชะตา"
  },
  Event_125750_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125750_Desc = {
    Text = "ไม่ว่าเรื่องจะซับซ้อนเพียงใด ก็ต้องอาศัยพวกเจ้าเป็นผู้แก้ไข\nในขณะที่รู้สึกหนักอึ้งมากขึ้น เจ้าก็สัมผัสได้ถึงพลังใหม่เช่นกัน"
  },
  Event_125750_Name = {
    Text = "ความสงบ"
  },
  Event_125751_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125751_Desc = {
    Text = "นักแสดงไร้นาม จังหวะเต้นอันตราย ใช่แล้ว การหลบหนีเป็นทางเลือกที่ปลอดภัยที่สุดเสมอ\nเจ้าหันหลังวิ่ง เปิดม่านโรงละคร แล้วเจ้าก็พบว่าตัวเองยืนอยู่บนเวที หุ่นเชิดจับมือเจ้า เต้นรำอย่างสนุกสนาน\nเวทีแห่งโชคชะตา ไม่เคยมีทางเลือก"
  },
  Event_125751_Name = {
    Text = "เต้นรำสามคน"
  },
  Event_125752_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125752_Desc = {
    Text = "ตอนนี้ไม่ใช่เวลาที่จะไปดูหนังสักเรื่อง"
  },
  Event_125752_Name = {
    Text = "โรงฉายแห่งความทรงจำ"
  },
  Event_125753_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125753_Desc = {
    Text = "อันตรายบนเส้นทางไม่ได้ผ่านเข้ามาในหัวของเจ้าเลยแม้แต่น้อย เจ้าเดินผ่านโชคชะตาที่พังทลายรอบข้าง เข้าใกล้เนฟเรียต่อไป\nเจ้ามาที่นี่ เพื่อมอบอิสรภาพให้แก่เธอ"
  },
  Event_125753_Name = {
    Text = "ม่านปิดแห่งใยชะตากรรม"
  },
  Event_125754_ChoiceDesc1 = {
    Text = "【อ่านซองจดหมาย】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」 ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125754_ChoiceDesc2 = {
    Text = "【อ่านจดหมาย】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราจารึก:「(EnchantConfig.Arg1)」"
  },
  Event_125754_ChoiceDesc3 = {
    Text = "【นำกลับไปที่เดิม】ได้รับสัญลักษณ์ดำ 50 ใบ"
  },
  Event_125754_Desc = {
    Text = "การเคลื่อนไหวของพวกเจ้าฉีกใยแมงมุมที่ถักทอหนาแน่นออก จดหมายเก่าคร่ำคร่าฉบับหนึ่งร่วงหล่นลงมาจากใยแมงมุม\nน้ำหนักของมันหนักกว่ากระดาษบางๆ มากนัก"
  },
  Event_125754_Name = {
    Text = "ราตรีสวัสดิ์ คุณเอ็ดการ์"
  },
  Event_125755_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125755_Desc = {
    Text = "น้ำตาหลั่งจากดวงตาของอีกา เลือดไหลจากมุมปากของอีกา อีกาใช้ชีวิตทั้งหมดของมัน ร้องเพลงคำทำนายสุดท้ายให้คุณฟัง"
  },
  Event_125755_Name = {
    Text = "คำทำนายสุดท้าย"
  },
  Event_125756_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125756_Desc = {
    Text = "「เฮอะเฮอะ...ฮ่าฮ่าฮ่าฮ่า!」\n「เป็นอย่างไรบ้าง แขกของฉัน? รสชาติแห่งโชคชะตา เธอจะคิดถึงมันอย่างบ้าคลั่ง...」"
  },
  Event_125756_Name = {
    Text = "รสชาติแห่งโชคชะตา"
  },
  Event_125757_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125757_Desc = {
    Text = "「น่าเบื่อ」เสียงหญิงสาวหาวอย่างเกียจคร้าน\n「เอาพลังของเจ้าไป ไปต่อยมวยที่สโมสรเถอะ」"
  },
  Event_125757_Name = {
    Text = "กุญแจแห่งโชคชะตา"
  },
  Event_125758_ChoiceDesc1 = {
    Text = "【รักษาเสถียรภาพสายใยแห่งโชคชะตา】ได้รับตราสลักขั้นสูงเลือก 1 จาก 3"
  },
  Event_125758_ChoiceDesc2 = {
    Text = "【เพิกเฉยอันตราย】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125758_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_125758_Desc = {
    Text = "เธอคือที่รักของความงดงาม เธอคือทารกที่ถูกชะตากรรมทอดทิ้ง เธอคือผู้ล้างแค้นที่ไต่ขึ้นจากเหวลึกตามแสงริบหรี่ เธอมาที่นี่ เพื่อนำการปลดปล่อยมาสู่ทุกสิ่ง\nใยแห่งชะตากรรมพังทลายรอบตัวพวกคุณ คุณยืนอยู่บนเวทีของโรงละคร อยู่ห่างจากเนฟเรียในระยะที่ไม่ไกลนัก"
  },
  Event_125758_Name = {
    Text = "ม่านปิดแห่งใยชะตากรรม"
  },
  Event_125759_ChoiceDesc1 = {
    Text = "【ไม่เข้าใจ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_125759_ChoiceDesc2 = {
    Text = "【เข้าใจความเจ็บปวด】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125759_Desc = {
    Text = "เสียงร่ำไห้แหลกสลายดังมาจากเวที แสงไฟดวงเดียวส่องลงบนร่างเงาอันโดดเดี่ยว\nเขากำลังมอบการแสดงที่จริงใจที่สุดให้แก่เจ้า——ผ่าเปิดอวัยวะภายในของเขา เผยให้ผู้ชมทุกคนได้เห็น\nอะไรทำให้ตัวละครนี้เจ็บปวดถึงเพียงนี้?"
  },
  Event_125759_Name = {
    Text = "คำสารภาพของนักแสดง"
  },
  Event_125760_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125760_Desc = {
    Text = "มือของเจ้าเอื้อมไปทางขวา\nนั่นคืออนาคตของเจ้า ความปรารถนาอันแรงกล้าที่สุด จุดหมายปลายทาง สถานที่ที่เจ้าจะไปถึง\nการดำรงอยู่ของเจ้า คือเพื่อไล่ตามดวงอาทิตย์เบื้องหน้า"
  },
  Event_125760_Name = {
    Text = "อดีต อนาคต"
  },
  Event_125761_ChoiceDesc1 = {
    Text = "【สามจุด】"
  },
  Event_125761_ChoiceDesc2 = {
    Text = "【หกโมง】"
  },
  Event_125761_ChoiceDesc3 = {
    Text = "【จุดเดียว】"
  },
  Event_125761_Desc = {
    Text = "เจ้าจะเดินจากไปก็ได้ แต่ลูกเต๋าอันประณีตนั้นดึงดูดเจ้าจนหมดสิ้น\nเจ้าลืมผู้ไล่ตามเบื้องหลัง หยิบมันขึ้นมาอย่างศรัทธา แล้วโยนลงในหมวกทรงสูง——"
  },
  Event_125761_Name = {
    Text = "การพนันริมถนน"
  },
  Event_125762_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_125762_Desc = {
    Text = "กลิ้งๆ ลูกเต๋าเต้นรำอย่างตื่นเต้นในถ้วยเต๋า เต้นจนหมดแรง\n\n「ทำไม... ทำไมไม่เคยมีใครชนะได้เลย!...」"
  },
  Event_125762_Name = {
    Text = "การพนันริมถนน"
  },
  Event_125763_ChoiceDesc1 = {
    Text = "【ยอมรับชะตากรรม】เลือก 1 จาก 3 การ์ดคำสั่งเพื่อรับการสลักตรา:「(EnchantConfig.Arg1)」"
  },
  Event_125763_ChoiceDesc2 = {
    Text = "【ต่อต้านชะตากรรม】ติดเชื้อ「(Skill.Arg1)」, สลักตราแบบสุ่มอีกครั้ง"
  },
  Event_125763_Desc = {
    Text = "「อา เจ้าตัวดื้อ. ชะตากรรมนั้นเมตตาเสมอ... แต่การต่อต้านทุกครั้งย่อมมีราคาที่ต้องจ่าย. ตอนนี้ เจ้ายินดีจะยอมรับมันไหม?」"
  },
  Event_125763_Name = {
    Text = "กรงแห่งโชคชะตา"
  },
  Event_125764_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125764_Desc = {
    Text = "เธอมองไปรอบๆ สายตาเหล่านั้น แล้วโบกมือทักทายพวกมัน\nในไม่ช้า เธอจะมอบจุดสุดยอดของเรื่องราวให้แก่พวกมัน"
  },
  Event_125764_Name = {
    Text = "ผู้ชม"
  },
  Event_125765_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125765_Desc = {
    Text = "「คุณหนูอารัคเนที่รัก วันนี้เป็นวันเกิดของท่าน ฉันรู้สึกดีใจสำหรับท่านและท่านผู้เป็นนายกับท่านผู้เป็นหญิง ยินดีต้อนรับท่านสู่โลกที่สวยงามนี้ ฉันขอมอบเพลงกล่อมเด็กอันอบอุ่นนี้ให้กับท่าน ขอให้ท่านมีชีวิตที่ปราศจากความกังวลตั้งแต่วันเกิดนี้ไป...」"
  },
  Event_125765_Name = {
    Text = "ราตรีสวัสดิ์ คุณเอ็ดการ์"
  },
  Event_125766_ChoiceDesc1 = {
    Text = "【ถ่ายรูป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ:「(EnchantConfig.Arg1)」"
  },
  Event_125766_ChoiceDesc2 = {
    Text = "【เปลี่ยนอีกครั้ง】ติดเชื้อ「(Skill.Arg1)」 เปลี่ยนตราประทับที่ได้รับจากตัวเลือก 1 ยังสามารถใช้ได้อีกหนึ่งครั้ง"
  },
  Event_125766_Desc = {
    Text = "เมื่อเผชิญหน้ากับเลนส์ คุณรู้สึกหวาดหวั่นเล็กน้อย บางทีท่านี้ถ่ายออกมาจะดีกว่า? หรือท่านั้น?"
  },
  Event_125766_Name = {
    Text = "ภาพถ่ายจากที่นั่งผู้ชม"
  },
  Event_125767_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125767_Desc = {
    Text = "เจ้าอยากดูเนื้อหาบนนั้น แต่ไม่มีอะไรปรากฏบนจอผ้า มีเพียงเสียงฟิล์มหมุนก้องอยู่ในโรงฉาย\nบางทีต้องอีกนานมาก เจ้าถึงจะมีโอกาสรู้เนื้อหาในฟิล์มนั้น"
  },
  Event_125767_Name = {
    Text = "โรงฉายแห่งความทรงจำ"
  },
  Event_125768_ChoiceDesc1 = {
    Text = "【หลีกเลี่ยงสายตา】การฟื้นคืนแบบสุ่มของ 1 ร่างกายที่ตื่นขึ้น"
  },
  Event_125768_ChoiceDesc2 = {
    Text = "【จ้องมองตรง】เลือกร่างกายที่ตื่นขึ้น 1 ตน และลดการใช้พลังการคำนวณของบัตรปลุกลง 2 หน่วย ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_125768_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_125768_Desc = {
    Text = "เมื่อก้าวขึ้นเวที เธอได้ยินเสียงกระซิบกระซาบ เธอหันกลับไป ดวงตาของผู้ชมหมื่นคนลอยอยู่รอบเวที จ้องมองเธอ\nมาเลย! พวกมันพูด ละครอันแสนวิเศษ จะหยุดลงตรงนี้หรือ?\nเต้นสิ! พวกมันพูด นำจุดสุดยอดของบทเพลงเต้นรำมาให้พวกเรา!"
  },
  Event_125768_Name = {
    Text = "ผู้ชม"
  },
  Event_125769_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125769_Desc = {
    Text = "เจ้าไม่เข้าใจความเจ็บปวดของเขา และก็ไม่จำเป็นต้องเข้าใจ\nโรงละครมีเวทีมากมาย บนเวทีมีหุ่นเชิดมากมาย เจ้าก็เป็นเพียงหนึ่งในนั้น\nเจ้ายังมีเรื่องสำคัญกว่าที่ต้องทำ"
  },
  Event_125769_Name = {
    Text = "คำสารภาพของนักแสดง"
  },
  Event_125770_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125770_Desc = {
    Text = "ความตาย การเลือนสลาย การผ่านพ้น... ศิลปะไม่ได้มีอยู่เพื่อนำมาซึ่งความเจ็บปวด. หากความงามมีอยู่เพียงในความเจ็บปวด ความงามเช่นนั้นไม่มีก็ได้.\nเจ้าขับไล่อย่างสุดแรง. ผีเสื้อกระจายหายไป ทิ้งไว้เพียงศพที่เปี่ยมด้วยความเศร้า."
  },
  Event_125770_Name = {
    Text = "เบ่งบานท่ามกลางการเลือนสลาย"
  },
  Event_125771_ChoiceDesc1 = {
    Text = "【ฟังเสียงร้องเพลง】ได้รับ 40 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_125771_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】ได้รับ 25 รอยดำ，แล้วจากไป"
  },
  Event_125771_Desc = {
    Text = "ฝูงกาที่เคยพบเจอกับคุณรวมตัวกันเป็นหนึ่งเดียว มันยืนอยู่ตรงหน้าคุณและร้องเพลงให้คุณฟัง เสียงเพลงแสนเศร้า ราวกับคำทำนายสุดท้าย"
  },
  Event_125771_Name = {
    Text = "คำทำนายสุดท้าย"
  },
  Event_125772_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125772_Desc = {
    Text = "มือของเจ้าเอื้อมไปทางซ้าย\nนั่นคืออดีตของเจ้า ความทรงจำอันล้ำค่าที่สุด เส้นทางที่เจ้าเดินทางมา สถานที่ที่เจ้าจะหวนกลับไป\nทุกสิ่งในอดีตประกอบขึ้นเป็นตัวตนทั้งหมดของเจ้า"
  },
  Event_125772_Name = {
    Text = "อดีต อนาคต"
  },
  Event_125773_ChoiceDesc1 = {
    Text = "【ถ่ายรูป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ:「(EnchantConfig.Arg1)」"
  },
  Event_125773_Desc = {
    Text = "เมื่อเผชิญหน้ากับเลนส์ คุณรู้สึกหวาดหวั่นเล็กน้อย บางทีท่านี้ถ่ายออกมาจะดีกว่า? หรือท่านั้น?\nคุณยังคงลังเล แต่คุณสังเกตได้ว่า กล้องเริ่มหมดความอดทนแล้ว"
  },
  Event_125773_Name = {
    Text = "ภาพถ่ายจากที่นั่งผู้ชม"
  },
  Event_125774_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125774_Desc = {
    Text = "คุณจัดท่าโพสเรียบร้อยแล้วยืนอยู่หน้ากล้อง สง่างาม อยากรู้อยากเห็น ทุ่มเท ราวกับเป็นผู้ชมตัวจริง\nกุบ——\nกล้องกดชัตเตอร์ เมือกสีดำระเบิดออกจากตัวกล้อง กระเซ็นไปทั่วเวที\nตรงกลางซากกล้อง ฟิล์มว่างเปล่าไม่มีอะไรเลย"
  },
  Event_125774_Name = {
    Text = "ภาพถ่ายจากที่นั่งผู้ชม"
  },
  Event_125775_ChoiceDesc1 = {
    Text = "【ยอมรับ】ได้รับสิ่งประดิษฐ์เงินเลือก 1 จาก 3"
  },
  Event_125775_ChoiceDesc2 = {
    Text = "【หลบหนี】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」ติดเชื้อสองครั้ง「(Skill.Arg3)」"
  },
  Event_125775_Desc = {
    Text = "ตะ ตะ ตะ ตะ... ส้นรองเท้ากระทบพื้นไม้ ดังเป็นเสียงกรอบแกรบอย่างรื่นเริง\nหุ่นเชิดสองตัวในชุดนักเรียนกำลังเต้นรำอยู่บนเวที ทันใดนั้น พวกมันหยุดเต้น หันมายื่นมือให้เจ้า"
  },
  Event_125775_Name = {
    Text = "เต้นรำสามคน"
  },
  Event_125776_ChoiceDesc1 = {
    Text = "【อดทนต่อความเจ็บปวด】เพิ่มพลังชีวิตสูงสุด Arg1 แต้ม"
  },
  Event_125776_ChoiceDesc2 = {
    Text = "【โต้แย้งความเจ็บปวด】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ 1 ใบ「(Skill.Arg2)」"
  },
  Event_125776_Desc = {
    Text = "「เธอไม่เคยสนใจการตายของลิซเลย เธอไม่เคยสนใจใครเลย」\n「สิ่งที่เธอสนใจมีแค่ตัวเอง...ทุกคนรอบตัวเธอ ล้วนเป็นเพียงเครื่องมือที่จะพาเธอไปสู่อิสรภาพและความสงบ」\n「ไม่ใช่หรือ...ผู้พิทักษ์ความลับ?」\nเสียงกระซิบของผู้ประกาศดังขึ้นข้างหูเธอ หัวใจของเธอบีบรัด หดตัว ความเจ็บปวดอันรุนแรงแผ่ขยายไปทั่วร่างกายตามคำพูดของเธอ..."
  },
  Event_125776_Name = {
    Text = "ความเจ็บปวดแผ่ขยาย"
  },
  Event_125777_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125777_Desc = {
    Text = "ปล่อยให้จิตสำนึกจมลงไปเถิด น้ำทะเลมีแรงลอยตัวของมันเอง โชคชะตาจะชี้ทางทั้งหมดให้แก่พวกเจ้า"
  },
  Event_125777_Name = {
    Text = "ความสงบ"
  },
  Event_125778_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125778_Desc = {
    Text = "นั่นคือตัวคุณเอง. แหล่งที่มาของพลัง, ผู้แบกรับหน้าที่, เป้าหมายเดียวที่ซื่อสัตย์ต่อ.\nคุณเดินอยู่บนเส้นทางที่เป็นของคุณเพียงผู้เดียว."
  },
  Event_125778_Name = {
    Text = "เงาสะท้อนในแก้วเหล้า"
  },
  Event_125779_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125779_Desc = {
    Text = "「น่าเสียดายจริงๆ แขกของฉัน รสชาติแห่งโชคชะตา เธอไม่มีโอกาสได้ลิ้มลองอีกแล้ว...」"
  },
  Event_125779_Name = {
    Text = "รสชาติแห่งโชคชะตา"
  },
  Event_125780_ChoiceDesc1 = {
    Text = "【พูดคุยกับเธอ】ลบการ์ดคำสั่ง 1 ใบ ได้รับตราดำ Arg1"
  },
  Event_125780_ChoiceDesc2 = {
    Text = "【นิ่งเงียบ】"
  },
  Event_125780_Desc = {
    Text = "「นี่เป็นละครที่น่าเศร้าจริงๆ...เด็กหญิงน่าสงสารคนนั้น ถูกคนที่เธอรักทอดทิ้งหรือเปล่าคะ พี่สาว?」\nในเสียงที่คุ้นเคยนี้ คุณไม่ได้ยินความบ้าคลั่งหรือความเกลียดชังใดๆ เสียงนั้นใสกระจ่าง เศร้าโศก ราวกับลำธารอันอ่อนโยนในป่า\n「นักร้องผู้นั้น ใบไม้แห้งที่ลอยไร้แรง ทำได้เพียงปล่อยให้โชคชะตาทำลาย...ช่างน่าสงสารเหลือเกิน...」\n「พี่สาวว่า ถ้าฉันเป็นผู้ถือปากกาคนนั้น...ฉันควรเขียนบทสรุปแบบไหนให้เธอดีคะ?」"
  },
  Event_125780_Name = {
    Text = "บทสรุปของบทละคร"
  },
  Event_125781_ChoiceDesc1 = {
    Text = "【ลูบหัว】50％ โอกาสได้รับ 125 ตราดำ, 50％ โอกาสติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125781_ChoiceDesc2 = {
    Text = "【อธิบาย】75％ โอกาสได้รับ 100 ตราดำ, 25％ โอกาสติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125781_ChoiceDesc3 = {
    Text = "【ถอดรหัส】ได้รับ 50 ตราดำ"
  },
  Event_125781_Desc = {
    Text = "เมื่อเจ้าไล่ตามไปยังตรอกหลังบาร์ ร่างของสัตว์ประหลาดก็หายวับไป ฝูงแมวดำขวางทางเจ้าอยู่\n「เฮ้ แก」แมวดำตัวหนึ่งเลียอุ้งเท้าของมันแล้วมองมาที่เจ้า\n「แกมาทำอะไรในที่ของพวกเรา?」"
  },
  Event_125781_Name = {
    Text = "ภาพลวงแปรรูป"
  },
  Event_125782_ChoiceDesc1 = {
    Text = "【โอบกอดอดีต】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125782_ChoiceDesc2 = {
    Text = "【ต้อนรับอนาคต】ได้รับสิ่งประดิษฐ์ทองคำเลือก 1 จาก 3 ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_125782_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_125782_Desc = {
    Text = "การปรากฏตัวของเนฟเรียรบกวนสายใย ในโชคชะตาที่ปั่นป่วน เจ้าเห็นเงาเลือนลางสองร่าง\nนั่นคืออดีตของเจ้า นั่นคืออนาคตของเจ้า เจ้าเดินเข้าหาพวกมัน ยื่นมือออกไป..."
  },
  Event_125782_Name = {
    Text = "อดีต อนาคต"
  },
  Event_125855_ChoiceDesc1 = {
    Text = "【สัมผัส】เลือกสิ่งประดิษฐ์ 1 ชิ้นเปลี่ยนเป็นสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_125855_ChoiceDesc2 = {
    Text = "【จ้องมอง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อไวรัส「(Skill.Arg2)」"
  },
  Event_125855_ChoiceDesc3 = {
    Text = "【ละเว้น】ได้รับ 25 รอยดำ"
  },
  Event_125855_Desc = {
    Text = "บนท้องถนนแห่งคาซาลิม แสงเจิดจ้าจากร้านคริสตัลแห่งหนึ่งดึงดูดสายตาของเจ้า เจ้าเดินมาที่หน้าร้านและหยิบคริสตัลรูปทรงแกนเงินขึ้นมา"
  },
  Event_125855_Name = {
    Text = "ความลับของคริสตัล"
  },
  Event_125856_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125856_Desc = {
    Text = "เจ้าหลับตาลง สัมผัสมันอย่างตั้งใจ\nแสงริบหรี่วาบขึ้นในจิตสำนึกของเจ้า มันต้องการบอกอะไรบางอย่างแก่เจ้า..."
  },
  Event_125856_Name = {
    Text = "ความลับของคริสตัล"
  },
  Event_125857_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125857_Desc = {
    Text = "การต่อต้านและการสอดแนมโชคชะตาทุกอย่างล้วนไร้ประโยชน์ เจ้าหลับตาลงอย่างเงียบงัน ปล่อยให้โชคชะตาพาเจ้าไปยังที่ที่เจ้าจะต้องไป"
  },
  Event_125857_Name = {
    Text = "ใยแห่งพันธนาการ"
  },
  Event_125858_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125858_Desc = {
    Text = "「อารมณ์คือความหมายของการดำรงอยู่. หวังว่าคุณจะไม่เสียใจกับการเลือกของตัวเอง.」"
  },
  Event_125858_Name = {
    Text = "ราคาที่ต้องจ่ายของการเลือก"
  },
  Event_125859_ChoiceDesc1 = {
    Text = "【อารมณ์】ฟื้นฟูพลังชีวิต Arg1 จุด"
  },
  Event_125859_ChoiceDesc2 = {
    Text = "【เหตุผล】การ์ดคำสั่งสุ่ม 1 ใบได้รับตราประทับ:「(EnchantConfig.Arg1)」"
  },
  Event_125859_ChoiceDesc3 = {
    Text = "【ปฏิเสธการเลือก】ได้รับสัญลักษณ์ดำ 25 ใบ"
  },
  Event_125859_Desc = {
    Text = "ตาชั่งปรากฏขึ้นบนเวที.\n「สมองกับหัวใจ, เหตุผลกับอารมณ์, เทากับแดง...เราไม่อาจหลีกเลี่ยงการเลือกได้ นี่คือชะตากรรมของเรา.」\n「จุดสิ้นสุดของเวทีถูกกำหนดไว้แล้ว. ตอนนี้, จงเลือกเส้นทางที่เวทีนี้จะก้าวผ่านไป.」"
  },
  Event_125859_Name = {
    Text = "ราคาที่ต้องจ่ายของการเลือก"
  },
  Event_125860_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125860_Desc = {
    Text = "「อย่าเงยหน้าขึ้น จงออกไปจากที่นี่」\nเจ้าได้ยินเสียงของโชคชะตา เจ้าปรารถนาอย่างแรงกล้าที่จะมองขึ้นไปบนท้องฟ้า แต่เจ้ารู้ดีว่า เธอพูดถูก"
  },
  Event_125860_Name = {
    Text = "เงยหน้ามอง"
  },
  Event_125861_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125861_Desc = {
    Text = "เจ้าไม่มีวันยอมรับโชคชะตา เจ้าไม่มีวันยอมรับการจองจำ\nเจ้าดิ้นรนอย่างสุดกำลัง หลังจากสังเวยอวัยวะของผีเสื้อกลางคืนไปชิ้นหนึ่ง ในที่สุดเจ้าก็หลุดรอดออกมาได้..."
  },
  Event_125861_Name = {
    Text = "ใยแห่งพันธนาการ"
  },
  Event_125862_ChoiceDesc1 = {
    Text = "【มิตรภาพ】ได้รับ 50 ตราดำ"
  },
  Event_125862_ChoiceDesc2 = {
    Text = "【ความช่วยเหลือ】ได้รับ 75 ตราดำ, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_125862_Desc = {
    Text = "ตรอกหลังบาร์ เธอพบแมวดำเหล่านั้นอีกครั้ง\n「ฉันได้ยินมาแล้ว เมือกสีดำพวกนั้นแปลงร่างเป็นพวกเรา สร้างปัญหาให้เธอไม่น้อย」\n「เพื่อเป็นการขอโทษ บอกฉันสิ เธออยากได้อะไร?」\nแมวดำวนรอบขาเธอสองรอบ แล้วเงยหน้ามองเธอ"
  },
  Event_125862_Name = {
    Text = "ของขวัญแรกพบ"
  },
  Event_125863_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125863_Desc = {
    Text = "กำลังดิบไม่อาจถอดรหัสโชคชะตาได้ แต่บางทีปัญญาอาจทำได้?\nเจ้าสังเกตใยแมงมุมนี้อย่างถี่ถ้วน พยายามมองหาร่องรอยของโชคชะตาจากมัน..."
  },
  Event_125863_Name = {
    Text = "ใยแห่งพันธนาการ"
  },
  Event_125864_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125864_Desc = {
    Text = "เจ้าก้มลงใกล้ จ้องมองมันอย่างพินิจพิเคราะห์\nแสงริบหรี่วาบขึ้นในดวงตาของเจ้า มันต้องการบอกอะไรบางอย่างแก่เจ้า..."
  },
  Event_125864_Name = {
    Text = "ความลับของคริสตัล"
  },
  Event_125865_ChoiceDesc1 = {
    Text = "【ดิ้นรน】สุ่มรับการ์ดคำสั่ง 3 ใบจากสำรับ เลือก 1 ใบเพื่อลบ, ได้รับ 75 ตราดำ"
  },
  Event_125865_ChoiceDesc2 = {
    Text = "【ครุ่นคิด】สุ่มรับการ์ดคำสั่ง 3 ใบจากกองการ์ด เลือก 1 ใบเพื่อนำสำเนาต้นฉบับเข้ากองการ์ด ได้รับ 25 ตราประทับดำ"
  },
  Event_125865_ChoiceDesc3 = {
    Text = "【พักผ่อน】ได้รับ 50 ตราประทับดำ"
  },
  Event_125865_Desc = {
    Text = "ความรู้สึกคุ้นเคยถาโถมเข้ามาหาเจ้า แต่สิ่งที่ต่างออกไปคือ สัมผัสเหนียวหนืดนั้น สัญชาตญาณที่ไม่อาจต้านทาน รุนแรงกว่าครั้งก่อน อันตรายกว่าครั้งก่อน\nผีเสื้อกลางคืนตกลงสู่ใยแมงมุม และเจ้าก็ก้าวขึ้นสู่เวทีแล้ว"
  },
  Event_125865_Name = {
    Text = "ใยแห่งพันธนาการ"
  },
  Event_125866_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125866_Desc = {
    Text = "「สติปัญญาคือหนทางแห่งการอยู่รอด หวังว่าเจ้าจะไม่เสียใจกับทางเลือกของตนเอง」"
  },
  Event_125866_Name = {
    Text = "ราคาที่ต้องจ่ายของการเลือก"
  },
  Event_125867_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125867_Desc = {
    Text = "ความอยากรู้ถูกจุดขึ้น เจ้าเดินเข้าไปในฝูงชน เงยหน้าขึ้นเหมือนพวกเขา\nที่นั่นไม่มีอะไรเลย แต่ไม่รู้ทำไม เจ้าไม่ยอมละสายตาลง เจ้าอยากจะมองอย่างนี้ต่อไป มองต่อไปเรื่อยๆ..."
  },
  Event_125867_Name = {
    Text = "เงยหน้ามอง"
  },
  Event_125868_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_125868_Desc = {
    Text = "「การสละสิทธิ์เลือกก็เป็นทางเลือกอย่างหนึ่ง นี่คือคำสาปแห่งโชคชะตา หวังว่าเจ้าจะไม่เสียใจกับทางเลือกของตนเอง」"
  },
