  },
  Event_129177_Name = {
    Text = "บทที่ 1 ของดวงดาว@"
  },
  Event_129178_ChoiceDesc1 = {
    Text = "【ทิศทางการชี้】ได้รับของประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129178_ChoiceDesc2 = {
    Text = "【สวดมนต์ร่วมกัน】รับตราประทับแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129178_Desc = {
    Text = "เสียงเปียโนและเสียงออร์แกนผสมผสานกันในสายลมที่มืดมน ราวกับว่าเสียงทำนองที่มีพลังเวทย์มนตร์ล่องลอยอยู่ในตรอกซอกซอยที่ไม่มีผู้คน \nแม่ชีผู้ไม่ปรากฏชื่อกำลังสวดภาวนาในเสียงเพลง \n「การสวดภาวนาอย่างง่ายไม่จำเป็นต้องมีพิธีการที่ยิ่งใหญ่ พ่อพระผู้ยิ่งใหญ่จะหว่านความหวังให้กับเรา เหมือนที่พระองค์เคยมอบการสอนที่มีความเชื่อมั่นให้กับเรา」"
  },
  Event_129178_Name = {
    Text = "การอธิษฐานของออร์แกน"
  },
  Event_129179_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129179_Name = {
    Text = "บทที่ 1 ของดวงดาว@"
  },
  Event_129180_ChoiceDesc1 = {
    Text = "【เผชิญหน้าอย่างแข็งขัน】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」ได้รับการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129180_ChoiceDesc2 = {
    Text = "【ยอมแพ้】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129180_ChoiceDesc3 = {
    Text = "【รีบเผ่น】ได้รับ 50 รอยดำ"
  },
  Event_129180_Desc = {
    Text = "หุ่นขี้ผึ้งดินหลายตัวขวางทางคุณอยู่。\nพวกมันเอียงไปเอียงมา หน้าตาดูหยาบกร้าน ไม่เหมือนกับมาตรฐานการผลิตที่ควรจะเป็นของโรเจอร์ส。\n「คำสั่ง... คำสั่งของท่าน...」"
  },
  Event_129180_Name = {
    Text = "แบบฝึกหัด"
  },
  Event_129181_ChoiceDesc1 = {
    Text = "【ละทิ้งการคิด】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_129181_ChoiceDesc2 = {
    Text = "【ไล่ตามแรงบัลดาลใจ】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129181_Desc = {
    Text = "ท่าเรือถูกโจมตี เรือบรรทุกสินค้าลึกลับที่มาและไปไม่มีวันกลับ และ 「เพื่อนใหม่」 ที่มีครีบ... นี่คือกับดักที่วางแผนมาอย่างดีหรือ? หรือเป็นการเดินทางที่เกิดอุบัติเหตุอีกครั้ง? \n ความเป็นจริงและเหตุผลดึงกันและพันกัน ความคิดและแรงบัลดาลใจนับไม่ถ้วนพุ่งออกจากสมอง。"
  },
  Event_129181_Name = {
    Text = "แรงบันดาลใจพุ่งพล่าน"
  },
  Event_129182_ChoiceDesc1 = {
    Text = "【เข้าร่วม】ติดเชื้อ「(Skill.Arg1)」สองครั้ง การ์ดสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg2)」สองครั้ง"
  },
  Event_129182_ChoiceDesc2 = {
    Text = "【ขับไล่】ติดเชื้อ「(Skill.Arg1)」สองครั้ง การ์ดสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg2)」สองครั้ง"
  },
  Event_129182_ChoiceDesc3 = {
    Text = "【เมินเฉย】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129182_Desc = {
    Text = "คุณได้ยินเสียงแตรกระดูกที่เลือนรางมาจากที่ไกลโพ้น。\nฝูงหนูเดินตามเสียงออกมาจากโคลนดำ กัดกินซากศพที่ไม่มีชื่อซึ่งนอนอยู่บนพื้นแม่น้ำที่แห้งแล้ง。\nพวกมันล้อมรอบเป็นวง กลางวงคือซากศพที่ว่างเปล่า และรอบวงคืออาณาจักรใหม่ที่มีการลืมเป็นกฎหมาย。\nและคุณกำลังยืนอยู่ที่ทางเข้าสู่อาณาจักรนี้。"
  },
  Event_129182_Name = {
    Text = "อาณาจักรที่ถูกเนรเทศ"
  },
  Event_129183_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129183_Name = {
    Text = "ลืมเลือนบทที่ 5@"
  },
  Event_129184_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129184_Name = {
    Text = "บทที่ 8 ของการลืมเลือน@"
  },
  Event_129185_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129185_Name = {
    Text = "บทที่ 1 ของการลืมเลือน@"
  },
  Event_129186_ChoiceDesc1 = {
    Text = "【ช่วยเหลือภาพเหมือน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129186_ChoiceDesc2 = {
    Text = "【ยอมรับความว่างเปล่า】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129186_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_129186_Desc = {
    Text = "คุณยืนอยู่ต่อหน้าของขวัญจากพิคแมน \n นั่นคือภาพวาดที่สร้างจากเลือดสด เปลวไฟสีดำมืดกำลังลุกไหม้อย่างเงียบ ๆ \n ผ่านทางเบ้าตาที่ว่างเปล่าของตัวละครในภาพ คุณเห็นว่า— \n ความทรงจำของคุณกำลังพลุ่งพล่านและลุกไหม้ ยืดออก บิดเบือน เปล่งประกาย ราวกับไฟที่มองไม่เห็นกำลังเลียทางเดินในสมองของคุณ ในช่วงที่สับสน คุณได้ยินเสียงคนพูด \n 「ถึงเวลาลงหม้อแล้ว อุณหภูมินี้พอดี」 \n นี่คือภาพความทรงจำที่คุณวาดขึ้นเอง คุณกำลังดิ้นรนและเปลี่ยนแปลงในเปลวไฟ。"
  },
  Event_129186_Name = {
    Text = "ภาพเหมือนลุกไหม้"
  },
  Event_129187_ChoiceDesc1 = {
    Text = "【คุณยินดีจ่ายด้วยอะไร?】อัปเกรดคุณภาพตราประทับของการ์ด 1 ใบแบบสุ่มสองครั้ง"
  },
  Event_129187_ChoiceDesc2 = {
    Text = "【เลี้ยงเครื่องดื่ม Bloody Mary หมดอายุให้พวกเขาสักแก้ว】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129187_Desc = {
    Text = "「ยินดีต้อนรับ แขกผู้มีค่าของฉัน เชิญเลือกได้ตามสบาย ทุกสิ่งที่เห็นนี้ล้วนรอคอยคุณอยู่」\n「เอ่อ ขอโทษครับ คุณคือ... น้องสาวฝาแฝดของคุณนายดาฟโฟดิลใช่ไหมครับ?」\n「ฉันคือคุณนายดาฟโฟดิลเอง ขอถามคุณแขกว่ามาที่นี่ในวันนี้มีธุระอะไร...?」\n「ขอโทษ ขอโทษ คุณมีเสน่ห์มากขึ้นกว่าเดิม ฉันถึงกับไม่รับรู้เลย คุณยังจำได้ไหม? ยี่สิบปีที่แล้ว คุณช่วยไล่คนแปลกหน้าคนหนึ่งออกจากบาร์ของฉัน... เมื่อวานนี้ ความฝันร้ายกลับมาอีกครั้ง มันยึดบาร์ พร้อมกับพี่น้องของมัน กลุ่มใหญ่เลย...」"
  },
  Event_129187_Name = {
    Text = "ชิ้นส่วนแห่งความทรงจำ·ความฝันในอดีตหวนคืน"
  },
