  },
  Event_129192_ChoiceDesc2 = {
    Text = "【เผชิญหน้ากับจิตใจ】การ์ดคำสั่งสุ่ม 2 ใบรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ 2 ใบ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129192_Desc = {
    Text = "ในการล่าที่มีเสียงดังกึกก้องนี้ การไล่ล่าของโกไลแอทเหมือนสัตว์ร้ายในยามค่ำคืน พยายามกลืนกินแสงแห่งความหวังทั้งหมด อย่างไรก็ตาม การไล่ล่าที่ไร้ความปรานีนี้ไม่ได้ทำให้คุณแช่แข็ง แต่กลับจุดประกายไฟภายในใจลึก ๆ ของคุณ มันแพร่กระจายและเผาไหม้ในอกของคุณ ทำให้ร้อนแรงขึ้นเรื่อย ๆ。"
