  Event_129194_ChoiceDesc1 = {
    Text = "【อ่านทางของผู้มาก่อน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129194_ChoiceDesc2 = {
    Text = "【เขียนเส้นทางของตนเอง】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129194_ChoiceDesc3 = {
    Text = "【จ้องมองความมืด】ได้รับ 25 รอยดำ"
  },
  Event_129194_Desc = {
    Text = "ถ้าคุณเดินทางในดินแดนลับแลคนเดียว คุณจะไม่มั่นใจในเส้นทางข้างหน้าของคุณอย่างนี้แน่นอน\nรอยเท้าในดินแดนลับแลถูกแบ่งออกเป็นสามเส้น ทุกรอยเท้าที่ทิ้งไว้ล้วนเขียนถึงอนาคตที่มองไม่เห็น。"
  },
  Event_129194_Name = {
    Text = "ทางออก"
  },
  Event_129195_ChoiceDesc1 = {
    Text = "【ชี้ให้เห็นข้อผิดพลาด】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129195_ChoiceDesc2 = {
    Text = "【หลังจากฟังการบรรเลง】ทุกครั้งที่มีร่างกายที่ตื่นขึ้นที่มีค่าความคลั่ง 50 ขึ้นไป จะได้รับ 15 รอยดำ"
  },
  Event_129195_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_129195_Desc = {
    Text = "เด็กชายหุ่นขี้ผึ้งนั่งอยู่หน้เปียโนเล่นบทฝึกซ้อม。\nครูของเขา——ซึ่งเป็นหุ่นขี้ผึ้งเช่นกัน กำลังให้คำแนะนำอยู่ข้างๆ。\n133，355，244……\nผิดแล้ว ทุกโน้ตผิดหมด。"
  },
