  Event_129198_ChoiceDesc1 = {
    Text = "【รับฟังความเศร้า】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129198_ChoiceDesc2 = {
    Text = "【เพลิดเพลินกับความสุข】ทุกครั้งที่มีร่างกายที่ตื่นขึ้นที่มีค่าความคลั่ง 50 หรือมากกว่า จะได้รับ 15 รอยดำ"
