  Event_129198_ChoiceDesc3 = {
    Text = "【ออกไป】รับตราประทับแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129198_Desc = {
    Text = "เสียงเพลงที่ไพเราะ อ่อนหวาน เต็มไปด้วยความสุข และความเศร้า... ทำนองดังก้องอยู่ในดินแดนลับแล ยากที่จะบอกได้ว่ามันมาจากไหน \n นี่คือซิมโฟนีที่ไหลออกมาจากเรือผี หรือว่าเป็นความเพ้อฝันในยามค่ำคืนที่ถูกผูกมัดอยู่ในดินแดนลับแล?"
