  Event_129200_ChoiceDesc2 = {
    Text = "【อ่าน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
