  Event_129204_Name = {
    Text = "บทที่ 6 ของลืมเลือน@"
  },
  Event_129205_ChoiceDesc1 = {
    Text = "【ปล่อยเธอ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」、ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129205_ChoiceDesc2 = {
    Text = "【ช่วยเธอ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129205_ChoiceDesc3 = {
    Text = "【ฉันจะเดินบนเส้นทางของตัวเอง】ได้รับ 50 รอยดำ"
  },
  Event_129205_Desc = {
    Text = "เงาสามคนขวางทางคุณไว้ \n 「คุณปล่อยเธอไปเถอะ」 เงาของคนที่กอดตุ๊กตาหมีที่เปื้อนเมือก D พูดว่า 「เธอแค่ขี้ขลาด ไม่ได้ชั่วร้าย เธอไม่อยากทำร้ายใครเลย」 \n 「คุณช่วยเธอได้」 เงาของคนที่ถือขนมที่บรรจุอย่างสวยงามพูดว่า 「คุณสามารถทำสิ่งที่เธอทำไม่ได้ คุณสามารถยุติทุกอย่างนี้ได้」 \n 「คุณไม่จำเป็นต้องฟังเรา」 เงาของคนที่มือว่างเปล่าพูดว่า 「คุณมีทางของคุณเอง」"
  },
  Event_129205_Name = {
    Text = "ทางแยกเล็กๆ"
  },
  Event_129206_ChoiceDesc1 = {
    Text = "【ให้อาหารหนู】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，เลือกติดเชื้ออาการ 1 ครั้ง"
  },
  Event_129206_ChoiceDesc2 = {
    Text = "【ขับไล่หนู】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129206_ChoiceDesc3 = {
    Text = "【เพิกเฉยหนู】ได้รับ 25 รอยดำ"
  },
  Event_129206_Desc = {
    Text = "ทุกสิ่งบนเรือลำนี้ล้วนอยู่ในวัฏจักร\nสิ่งมีชีวิตตัวเล็กๆ ที่น่ารังเกียจและเต็มไปด้วยขนสกปรกที่หากินบนเรือ ย่อมหนีไม่พ้นชะตากรรมนี้เช่นกัน\nในวัฏจักรครั้งแล้วครั้งเล่า พวกมันกินทุกสิ่งที่เห็น แต่ก็ยังไม่อิ่ม\n「หิว...จัง...」\nฝูงหนูส่งเสียงร้องแหลมที่ป่วยไข้และแสบแก้วหู\nวัฏจักรซ้ำแล้วซ้ำเล่าทำให้พวกมันหิวจนทนไม่ไหว พวกมันต้องกินอะไรสักอย่าง\nทันที เดี๋ยวนี้!"
  },
  Event_129206_Name = {
    Text = "ฝูงหนูหิวโหย"
  },
  Event_129207_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129207_Name = {
    Text = "บทที่ 8 ของการลืมเลือน@"
  },
  Event_129208_ChoiceDesc1 = {
    Text = "【สัมผัสสมอง】การ์ดคำสั่งสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129208_ChoiceDesc2 = {
    Text = "【สัมผัสหัวใจ】เพิ่มพลังชีวิตสูงสุด Arg1 จุด，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129208_Desc = {
    Text = "คุณเดินเข้าไปในห้องสีเทาที่ไร้เสียงกระซิบ มีตาชั่งปรากฏอยู่ในหมอกดำ \n ด้านซ้ายคือสมองที่สงบเหมือนทะเลสาบ ร่องรอยสีเงินเปล่งประกายเล็กน้อย; ด้านขวาคือหัวใจสีแดงร้อนที่มีไอน้ำพวยพุ่งออกมา \n ทันใดนั้นคุณได้กลิ่นหอม ความปรารถนาที่หิวโหยพุ่งสูงขึ้นเรื่อยๆ สติของคุณถูกความมืดอันไม่มีที่สิ้นสุดกดดัน \n คุณยื่นมือออกไป。"
  },
  Event_129208_Name = {
    Text = "เกมหิวโหย"
  },
  Event_129209_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129209_Name = {
    Text = "ลืมเลือนบทที่ 4@"
  },
  Event_129210_ChoiceDesc1 = {
    Text = "【สังหารเงา】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129210_ChoiceDesc2 = {
    Text = "【บดขยี้ตัวอ่อน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129210_ChoiceDesc3 = {
    Text = "【ปิดตา】ได้รับ 25 รอยดำ"
  },
  Event_129210_Desc = {
    Text = "คุณเห็นผู้คนที่เคยพบในอาลานเข้ามาหาคุณในขณะที่คุณรู้สึกมึนงง \n พวกเขาหัวเราะและเชิญชวนให้คุณดื่ม เต้นรำ และชิมอาหาร \n จากนั้นเนื้อและเลือดของพวกเขาก็ถูกลอกออกเป็นชั้นๆ ขณะที่สิ่งที่ตกลงบนพื้นกำลังขยับและงอกขึ้นเป็นตัวอ่อนใหม่ \n พวกเขายื่นมือออกมา เชิญชวนให้คุณเข้าร่วมในงานฉลองของเนื้อและเลือดกับการเกิดใหม่."
  },
  Event_129210_Name = {
    Text = "เงาของวันเก่า"
  },
  Event_129211_ChoiceDesc1 = {
    Text = "【ให้อาหารพวกเขา】ได้รับของโบราณเงิน「(RelicConfig.Arg1)」เลือกติดเชื้อ 1 ครั้งอาการ"
  },
  Event_129211_ChoiceDesc2 = {
    Text = "【ไม่สนใจ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129211_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_129211_Desc = {
    Text = "ผู้อยู่อาศัยมาแล้วจากไป แต่ฝูงหนูยังอยู่ยืนนาน\nเมื่อเทียบกับมนุษย์แล้ว พวกมันต่างหากคือ 「ผู้อยู่ที่แท้จริง」 ของปราสาทเก่าแก่แห่งนี้\nแต่พวกมันไม่มีข้อขัดแย้งใดๆ กับการเข้ามาของมนุษย์\nเพราะเหล่าสิ่งขาวนุ่มนิ่ม กลิ่นหอม ที่ดูแปลกประหลาดเหล่านั้น ชอบโยนอาหารที่หอมขาวนุ่มนิ่มและประหลาดอยู่เสมอมาให้พวกมัน\n「แล้วเจ้า สิ่งประหลาด เจ้าเป็นพวกแบบไหนกัน?」"
  },
  Event_129211_Name = {
    Text = "ความลับของปราสาทโบราณ"
  },
  Event_129212_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129212_Name = {
    Text = "ลืมเลือนบทที่ 5@"
  },
  Event_129213_ChoiceDesc1 = {
    Text = "【แยกแยะเสียงของผู้ชาย】สุ่ม 3 การ์ดคำสั่งจากกองการ์ด เลือก 1 ใบแล้วทำการคัดลอก"
  },
  Event_129213_ChoiceDesc2 = {
    Text = "【แยกแยะเสียงผู้หญิง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129213_ChoiceDesc3 = {
    Text = "【ฟังเสียงผู้สูงอายุให้ออก】ได้รับ 25 รอยดำ"
  },
  Event_129213_Desc = {
    Text = "คุณยืนอยู่คนเดียวในหนองน้ำที่มืดมิด \n ในความพร่ามัว คุณได้ยินเสียงพึมพำที่เคออสสลับกันเหมือนคลื่นทะเลที่พัดมา บางเสียงมาจากคนชราที่อายุยืน บางเสียงมาจากเด็กเล็กที่เริ่มพูด บางเสียงมาจากผู้หญิงที่วิตกกังวล และบางเสียงมาจากผู้ชายที่รู้สึกกลัวอย่างไม่รู้สาเหตุ..."
  },
