    Text = "คำพูดสุดท้ายที่ไม่ชัดเจน"
  },
  Event_129214_ChoiceDesc1 = {
    Text = "【ดูอย่างละเอียด】รับตราประทับแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129214_ChoiceDesc2 = {
    Text = "【ฉีกโปสเตอร์】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129214_Desc = {
    Text = "เชิงเทียนที่เห็นได้ทั่วไปในพิพิธภัณฑ์หุ่นขี้ผึ้ง\nด้วยแสงสีส้มที่ผิดปกติ คุณพบว่าในกำแพงมีโปสเตอร์ที่วาดด้วยมือแปะอยู่。"
  },
