  },
  Event_129218_Desc = {
    Text = "ผีเสื้อเล็กๆก็มีความฝันมากมาย.\nความฝันเหล่านี้กระจัดกระจายอยู่ในทุ่งดอกไม้,      ในห้องคนป่วย,      และบน@2แท่นบูชาที่เต็มไปด้วยเนื้อและเลือด.\nในวันนี้มันได้รอคอยคนที่ผูกพันกับมันในที่สุด ไม่รู้ว่าคุณจะยินดีรับฟังความปรารถนาเล็กๆ ที่เล็กน้อยของมันหรือไม่."
  },
  Event_129218_Name = {
    Text = "ความฝันของผีเสื้อ"
  },
  Event_129219_ChoiceDesc1 = {
    Text = "【ติดตามการนำทาง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129219_ChoiceDesc2 = {
    Text = "【เพิกเฉยต่อการนำทาง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129219_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_129219_Desc = {
    Text = "เทศกาลได้เริ่มต้นแล้ว\nภายใต้เปลวไฟแห่งวิญญาณและคำอธิษฐานแห่งเลือด วิญญาณของผู้ศรัทธานับไม่ถ้วนกลายเป็นประภาคาร——\nวิญญาณเลือนลางกระจายอยู่รอบตัวคุณ ดุจภูตแห่งทางนำ ส่องแสงรอคอยการเลือกของคุณ."
  },
  Event_129219_Name = {
    Text = "ประภาคารแห่งวิญญาณ"
  },
  Event_129220_ChoiceDesc1 = {
    Text = "【เพิกเฉยต่อเสียงกริ่ง】รับการแกะสลักขั้นสูงแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129220_ChoiceDesc2 = {
    Text = "【หยิบหูฟังขึ้น】ได้รับของโบราณทอง「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129220_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_129220_Desc = {
    Text = "มันไม่ควรดังขึ้น——โทรศัพท์เครื่องนั้นซึ่งซุกซ่อนอยู่หลังผ้าใบ。\nสายของหูฟังพันอยู่กับตัวเครื่องขนาดใหญ่ ราวกับสายสะดือที่เป็นสนิม ดูเหมือนจะยืดออกมาจากสมองของคุณ。\nคุณพยายามแยกแยะความถี่ของการสั่นสะเทือน เสียงแปลกๆ นั้นเหมือนกับศิลปะเหนือจริงของพิคแมน。"
  },
  Event_129220_Name = {
    Text = "การโทรที่พลาด"
  },
  Event_129221_ChoiceDesc1 = {
    Text = "【พวกเราปลอดภัยดี】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129221_ChoiceDesc2 = {
    Text = "【คุณเป็นใคร?】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129221_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_129221_Desc = {
    Text = "เครื่องพิมพ์ดีดพ่นหมึกออกมาอย่างกะทันหัน โดยมีเครื่องหมายตกใจมากมายจนทำให้แสบตา \n「ดอลล์ คุณสบายดีไหม???ทำไมผู้พิทักษ์หายไปแล้วคุณก็หายไปด้วย!!!กรุณาตอบกลับถ้าปลอดภัย!!!ถ้ารอนานกว่านี้วิลเลียมผมจะหลุดหมดแล้ว!!!」"
  },
  Event_129221_Name = {
