  },
  Event_129231_Desc = {
    Text = "เพลงเรือโบราณดังก้องอยู่ในดินแดนลับแล。\nความทรงจำที่ติดอยู่ในดินแดนลับแลใช้ภาษาที่คุณไม่เคยได้ยิน ร้องเพลงเกี่ยวกับคลื่นทะเล ท้องฟ้า และสุราแรง。"
