  },
  Event_129234_ChoiceDesc1 = {
    Text = "【กรีดฝ่ามือ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129234_ChoiceDesc2 = {
    Text = "【ยอมรับการเติบโต】ได้รับของโบราณเงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129234_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_129234_Desc = {
    Text = "ผีเสื้อตัวนั้นไม่ได้บินมา แต่ค่อยๆ เติบโตขึ้นจากฝ่ามือของคุณ\nตอนแรกคุณคิดว่าเป็นแค่เหงื่อ แต่กลับเห็นของเหลวสีดำราวกับเส้นเลือดที่ค่อยๆ ซึมออกมาผ่านร่องนิ้วของคุณ ก่อรวมตัวเป็นปีกที่เย็นเยียบและเต้นกระพือ\nทุกครั้งที่มันกระพือปีก มันก็ทำให้เกิดระลอกในเลือดของคุณ。"
  },
  Event_129234_Name = {
    Text = "ปรสิตชนชั้นสูง"
  },
  Event_129235_ChoiceDesc1 = {
    Text = "【อ่านต่อไป】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129235_ChoiceDesc2 = {
    Text = "【ออกจาก】เพิ่มพลังชีวิตสูงสุด Arg1 หน่วย และติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129235_Desc = {
    Text = "ตาชั่งที่ใช้สำหรับชั่งน้ำหนัก。\nเบื้องหลังมันมีอวัยวะนับไม่ถ้วนแช่อยู่ในฟอร์มาลินสีแดง。\nพวกมันถูกจัดเรียงอย่างเป็นระเบียบบนชั้นเก็บของ。\nคุณหยิบสมุดบันทึกข้างๆ ขึ้นมาเปิดอ่าน：\n「หัวใจ：8 ออนซ์，สมอง：50 ออนซ์……」"
  },
  Event_129235_Name = {
    Text = "การลงทะเบียนอวัยวะ"
  },
  Event_129236_ChoiceDesc1 = {
    Text = "【เลี่ยงเส้นทาง】ลบการ์ดคำสั่ง 1 ใบ ได้รับรอยดำ Arg1"
  },
  Event_129236_ChoiceDesc2 = {
    Text = "【สอบถามเหตุผลที่จม】คัดลอกการ์ดคำสั่ง 1 ใบ ส่งผลกระทบ「(Skill.Arg1)」"
  },
  Event_129236_ChoiceDesc3 = {
    Text = "【ทักทายลูกเรือ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129236_Desc = {
    Text = "เดินอยู่บนทางไปยังห้องเครื่อง คุณได้พบกับบางอย่างที่ถูกตรึงอยู่ในดินแดนลับแลอีกครั้ง นั่นคือ「ความทรงจำ」\nพวกเขาไม่ใช่ผี แต่เป็นความห่วงใยของกัปตันเอลตันต่อสมาชิกลูกเรือที่จากไป。"
  },
  Event_129236_Name = {
    Text = "เจ้าของเรือโซนาเนียร์"
  },
