  },
  Event_129241_Name = {
    Text = "บทที่ 4 ของดวงดาว@"
  },
  Event_129242_ChoiceDesc1 = {
    Text = "【เล่นดนตรีให้เขาฟัง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129242_ChoiceDesc2 = {
    Text = "【ฟังเสียงดนตรีเครื่องสาย】ทุกครั้งที่มีร่างกายที่ตื่นขึ้นที่มีค่าความคลั่ง 50 หรือมากกว่า จะได้รับ 15 รอยดำ"
  },
  Event_129242_ChoiceDesc3 = {
    Text = "【ออกไป】รับตราประทับแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129242_Desc = {
    Text = "「ที่รักจอห์น：\n    เมื่อเร็ว ๆ นี้ฉันเพิ่งตระหนักว่า เวลาที่ผ่านไปตั้งแต่ครั้งที่คุณเล่นเปียโนให้เราฟังนั้นได้ผ่านไปหลายปีแล้ว \n    ปีนี้ฉันอายุ 81 ปี ยิ่งอายุมากขึ้น ฉันก็ยิ่งตระหนักถึงความมีค่าของความทรงจำในวัยเยาว์ \n    หากคุณได้รับจดหมายนี้ ก็ขอให้คุณแวะที่หน้าห้องของฉันในลอนดีเนี่ยนเมื่อคุณผ่านมาที่นี่ และมาเล่นเพลงให้ฉันฟังสักเพลงนะ.」"
  },
  Event_129242_Name = {
    Text = "โซนาตาแห่งความเสียใจ"
  },
  Event_129243_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129243_Name = {
    Text = "บทที่ 3 ของดาว@"
  },
  Event_129244_ChoiceDesc1 = {
    Text = "【บอกว่าตัวเองไม่มีกระเป๋าสตางค์】รับตราประทับแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129244_ChoiceDesc2 = {
    Text = "【ทำลายตาข่าย】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง，ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129244_Desc = {
    Text = "อวนสีส้มเหลืองลอยอยู่นิ่ง ๆ ในอากาศ รูของมันเบาบาง ห่างไกลจากความประณีตของญาติห่าง ๆ ของแมงมุมที่อาศัยอยู่บนข้างกำแพง\nคุณอดไม่ได้ที่จะยื่นมือสัมผัส อวนที่เปราะบางละลายทันที เสียงหัวเราะของเด็ก ๆ ดังขึ้นที่ข้างหูคุณ\n「สีทอง สีเงิน สีเหลือง สีแดง ทุกกระเป๋าสตางค์เป็นของเรา!」"
  },
  Event_129244_Name = {
