  Event_129249_ChoiceDesc2 = {
    Text = "【ตัดสายใย】คัดลอกการ์ดคำสั่ง 1 ใบ ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_129249_ChoiceDesc3 = {
    Text = "【อดทนนิ่งเงียบ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129249_Desc = {
    Text = "ตลอดเส้นทางคุณถูกผลักดันให้เดินหน้า ทุกการเลือกของคุณถูกควบคุมโดยเส้นด้ายที่มองไม่เห็น \n คุณพยายามดิ้นรนด้วยมือทั้งสองเพื่อจับสิ่งที่คุณให้ความสำคัญ \n ชะตากรรมของโลกแขวนอยู่ที่ปลายนิ้วของคุณ \n เส้นด้ายจำนวนมากพันธนาการคุณไว้ทั่วทั้งร่างกาย。"
  },
  Event_129249_Name = {
    Text = "มือที่ถูกบังคับ"
  },
  Event_129250_ChoiceDesc1 = {
    Text = "【ถามทางเขา】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129250_ChoiceDesc2 = {
    Text = "【ออกไปจากมัน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129250_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_129250_Desc = {
    Text = "เงายืนอยู่ใต้โคมไฟที่สูงและเรียว。\n「ขอไฟยืมหน่อยได้ไหมครับ」\nคุณไม่มีนิสัยใช้@2 แต่คุณไม่รังเกียจที่จะใช้「เวทมนตร์」เล็กน้อย。\nด้วยความช่วยเหลือของคุณ เงาจะจุด@2 ลงไปในวังวนสีดำที่มองไม่เห็นก้น。\nไม่นาน คุณก็เห็นควันสีขาวพวยพุ่งออกมา。\n「อา——」\nเงาออกเสียงถอนหายใจอย่างมีความสุข。"
  },
