  Event_129254_ChoiceDesc1 = {
    Text = "【ยอมรับภาพหลอน】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
