  Event_129254_ChoiceDesc2 = {
    Text = "【ปฏิเสธภาพหลอน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129254_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_129254_Desc = {
    Text = "ใต้สะพานเหล็กที่มืดทึบและหนักหน่วง บนชายฝั่งแม่น้ำที่เงียบสงบซึ่งมีต้นอ้อขึ้นรก อยู่ๆ ก็มีผีเสื้อที่เปล่งประกายบินออกมา\nผีเสื้อเบาๆ ลงบนฝ่ามือของคุณ เสียงร้องโหยหวนที่น่าขนลุกหยุดลง แทนที่ด้วยเสียงคำรามของรถไฟที่ทับเหล็กขึ้นสนิม เสียงป๊อกป๊อกของถ่านที่เผาไหม้ และเสียงโลหะที่เสียดสีกันของเพลาล้อ……"
  },
  Event_129254_Name = {
    Text = "ภาพลวงตาทางรถไฟ"
  },
  Event_129255_ChoiceDesc1 = {
    Text = "【เลือกปฏิเสธ】ลบการ์ดคำสั่ง 1 ใบ รับสัญลักษณ์ดำ Arg1"
  },
  Event_129255_ChoiceDesc2 = {
    Text = "【เลือกเชื่อฟัง】คัดลอกการ์ดคำสั่ง 1 ใบ ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_129255_ChoiceDesc3 = {
    Text = "【เลือกโอบกอด】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129255_Desc = {
    Text = "「ฉันคือนกในกรง ถูกขังอยู่ในลานที่เต็มไปด้วยห้องมากมาย」\nในความมืดมีเงาคนที่ไม่ชัดเจนเดินไปมา นั่นคือความหลงใหลที่เหลืออยู่จากผู้ที่จากไป\n「พวกเขาบอกว่านี่คือโรงพยาบาลจิตเวช แต่ฉันรู้ว่านี่คือกรงพิเศษของมนุษย์ ที่กักขังนกอิสระที่ไม่ยอมปฏิบัติตามกฎของสังคม」\n「แต่นกถ้าไม่สามารถบินได้ ยังจะเรียกว่านกอยู่ไหม?」\nความหลงใหลต่างๆเข้าหาคุณ ส่งเสียงขอความช่วยเหลือเพื่อไถ่บาป\n「โปรดหักปีกของฉัน ฉันเบื่อหน่ายกับการบินแล้ว」"
  },
  Event_129255_Name = {
    Text = "คนว่าง"
  },
  Event_129256_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129256_Name = {
    Text = "บทที่ 2 ของลืมเลือน@"
  },
  Event_129257_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129257_Name = {
    Text = "บทที่ 2 ของดวงดาว@"
  },
  Event_129258_ChoiceDesc1 = {
    Text = "【ปล่อยผีเสื้อ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129258_ChoiceDesc2 = {
    Text = "【กลายเป็นผีเสื้อ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129258_ChoiceDesc3 = {
    Text = "【กลืนลงท้อง】ได้รับ 25 รอยดำ"
  },
  Event_129258_Desc = {
    Text = "คืนนี้เกิดเรื่องราวมากมาย \n การโจมตีที่ท่าเรือ เรือผี ผู้เหยียบทะเล ธูลู เมอร์ฟี่ ราโมน่า... ทุกอย่างหมุนวนอยู่ในวังวน ถูกคนกวนจนกลายเป็นข้าวโอ๊ตที่ร้านมิซากะตอนเจ็ดโมงเช้า \n อยากจะถามผู้ปลุกตื่นที่อยู่ตรงหน้า แต่ไม่รู้จะเริ่มถามอย่างไร เหมือนมีอะไรติดอยู่ในคอ—หรือจะพูดว่าสิ่งที่อยู่ในท้องคือผีเสื้อ。"
  },
  Event_129258_Name = {
    Text = "เอฟเฟกต์ผีเสื้อ"
  },
  Event_129259_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129259_Name = {
    Text = "บทที่ 8 ของการลืมเลือน@"
  },
  Event_129260_ChoiceDesc1 = {
    Text = "【ปล่อยให้อยู่】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129260_ChoiceDesc2 = {
    Text = "【โบกมือไล่】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ถูกทำให้ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129260_ChoiceDesc3 = {
    Text = "【ต้อนรับผีเสื้อ】รับ 25 รอยดำ"
  },
  Event_129260_Desc = {
    Text = "พวกคุณเดินวนเวียนอยู่ในสถานพักฟื้นที่มีลมหนาวพัดแรง ผีเสื้อสีดำตัวหนึ่งบินโฉบมาอย่างสง่างามซึ่งไม่ควรมีอยู่ในฤดูกาลนี้\nปีกของผีเสื้อที่กระพือสะบัดมีน้ำยางสีดำติดอยู่ โยกไปมาและบินผ่านไป ชั้นของน้ำยางสีดำที่ไหลออกมาจากปีก เมื่อแห้งแล้วจะถูกลมพัดหลุดออกมา\nมันบินจนเหนื่อยแล้ว หยุดอยู่ที่ปลายนิ้วของคุณ。"
  },
  Event_129260_Name = {
    Text = "สิ่งที่ไม่ควรมีอยู่"
  },
  Event_129261_ChoiceDesc1 = {
    Text = "【ย้อนอดีต】รับการแกะสลักขั้นสูงแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129261_ChoiceDesc2 = {
    Text = "【แอบมองอนาคต】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129261_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_129261_Desc = {
    Text = "ไม่มีสิ่งใดในโลกนี้ที่จะมั่นคงไม่เปลี่ยนแปลง\nแม้แต่สวรรค์ที่พระมารดาสร้างขึ้นก็เช่นกัน\nในชั่วขณะสั้นๆ คุณมองเห็นบางสิ่งจากรอยแยกกาลอวกาศ\nอดีต ปัจจุบัน อนาคต พันกันอยู่ในรอยร้าวนั้น เปลี่ยนแปลงไม่หยุด\nรอคอยการสอดส่องอย่างอยากรู้อยากเห็นของคุณ."
  },
  Event_129261_Name = {
    Text = "รอยแยกกาลอวกาศ"
  },
  Event_129262_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129262_Name = {
    Text = "บทที่ 7 ของการลืมเลือน@"
  },
  Event_129263_ChoiceDesc1 = {
    Text = "【เพิกเฉยต่อมัน】รับตราประทับแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129263_ChoiceDesc2 = {
    Text = "【สัมผัสมัน】การ์ดคำสั่งสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129263_Desc = {
    Text = "สิ่งแปลกประหลาดที่คล้ายกับสปอร์ดึงดูดความสนใจของคุณ \n มันเหมือนกับแมงกะพรุนที่ประกอบขึ้นจากเนื้อและเลือด หรือเส้นประสาทที่เก็บสัญญาณอยู่ลึกในสมอง \n 「มาสัมผัสฉันสิ」 มันล่อลวงคุณอย่างไร้เสียง 「ฉันจะให้คุณเห็นความทรงจำที่โหดร้าย」"
  },
  Event_129263_Name = {
    Text = "ความทรงจำลึกซึ้ง"
  },
