  },
  Event_129267_ChoiceDesc1 = {
    Text = "【ฟัง】รับการแกะสลักขั้นสูงแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129267_ChoiceDesc2 = {
    Text = "【ตะโกน】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_129267_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_129267_Desc = {
    Text = "ตั้งแต่เกิดเหตุไม่คาดคิด คุณก็ไม่ได้รับข่าวจากคู่หูอีกเลย\nการติดต่อมากมายที่ส่งออกไปเหมือนกับหินที่ตกลงในทะเลลึก ไม่มีเสียงตอบกลับ\nในขณะที่คุณเริ่มหมดหวัง เครื่องสื่อสารก็ส่งเสียงขึ้นมาอย่างกะทันหัน\nคุณเปิดกระเป๋าเดินทางและนำโทรศัพท์แนบเข้ากับหู\n“ผู้พิทักษ์…”\nในความมึนงง คุณได้ยินเสียงที่คิดถึงมาตลอด เหมือนเสียงที่สะท้อนอยู่ห่างไกลผ่านความว่างเปล่าหลายชั้น。"
  },
  Event_129267_Name = {
    Text = "เสียงสะท้อนความคิดถึง"
  },
  Event_129268_ChoiceDesc1 = {
