  },
  Event_129270_ChoiceDesc1 = {
    Text = "【แหล่งที่มาของสุนัขแห่งนรก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129270_ChoiceDesc2 = {
    Text = "【มุ่งสู้】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129270_Desc = {
    Text = "รูปร่างของสุนัขแห่งนรกกำลังเปลี่ยนแปลง。\nร่างกายของมันเชื่อมต่อกับรอยแยกของผนัง เผยให้เห็นภาพลวงที่แปลกประหลาด。"
  },
  Event_129270_Name = {
    Text = "จากมุม"
  },
  Event_129271_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129271_Name = {
    Text = "บทที่ 2 ของลืมเลือน@"
  },
  Event_129272_ChoiceDesc1 = {
    Text = "【รวมกระดาษ】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129272_ChoiceDesc2 = {
    Text = "【อ่าน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง"
  },
  Event_129272_ChoiceDesc3 = {
    Text = "【ทิ้งมันไป】ได้รับ 50 รอยดำ"
  },
  Event_129272_Desc = {
    Text = "กระดาษแผ่นหนึ่งที่มีสีเหลืองร่วงหล่นจากใต้ผ้าคลุมของผู้ศรัทธาแห่งโคมไฟ\nบนกระดาษมีข้อความแปลกๆ ที่เขียนแน่นหนา บางอย่างดูเหมือนอักษรภาพ บางอย่างมีลักษณะแปลกๆ ยกขึ้น และบางตัวอักษรก็ทับซ้อนกันอยู่ มีเพียงไม่กี่คำที่สามารถอ่านออกได้\nหัวข้อคือ《@2 การถือกำเนิดของบุตรศักดิ์สิทธิ์》"
  },
  Event_129272_Name = {
    Text = "รหัสลับ·ลง"
  },
  Event_129273_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129273_Name = {
    Text = "บทที่ 2 ของลืมเลือน@"
  },
  Event_129274_ChoiceDesc1 = {
    Text = "【ตัวยึดตำแหน่ง】ข้อความชั่วคราว."
  },
  Event_129274_Name = {
    Text = "บทที่ 2 ของดวงดาว@"
  },
  Event_129275_ChoiceDesc1 = {
    Text = "【เตรียมพร้อมสู้】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129275_ChoiceDesc2 = {
    Text = "【ลองอ้อมทาง】รับได้ 25 รอยดำ"
  },
  Event_129275_Desc = {
    Text = "ในทะเลลึกที่แสงดาวทอดลงมา เหล่าผู้เหยียบทะเลซ่อนตัวมานับพันปี.\nผืนน้ำอันไร้ขอบเขตเป็นพยานแห่งความบ้าคลั่งของพวกเขา เป็นพยานแห่งความอดทนของพวกเขา และเป็นพยานแห่งศรัทธาอันเลื่อมใสที่สุดที่พวกเขามีต่อเทพเจ้า.\nไม่มีผู้ใดสามารถขัดขวางการเสด็จมาอันยิ่งใหญ่ของเทพเจ้าได้.\nผู้ขวางทางทุกคนจะถูกเผาเป็นเถ้าถ่านในเปลวเพลิงแห่งความโกรธของเหล่าผู้เหยียบทะเล."
  },
  Event_129275_Name = {
    Text = "การรอคอยใต้หมู่ดาว"
  },
  Event_129276_ChoiceDesc1 = {
    Text = "【เล่นโน้ตไม่กี่ตัว】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129276_ChoiceDesc2 = {
    Text = "【ปิดฝาลง】รับตราประทับแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129276_Desc = {
    Text = "เปียโนที่อยู่ข้างกำแพงเปิดฝาออก มันมีคีย์ที่เหลืองซีดและขอบที่แตกออกเผยให้เห็นสีไม้ แต่ละคีย์ถูกเช็ดทำความสะอาดอย่างดี\nมันเป็นแหล่งความสุขของผู้คนมากมาย。"
  },
  Event_129276_Name = {
    Text = "เพลงของวัยเด็ก"
  },
  Event_129277_ChoiceDesc1 = {
    Text = "【ยอมรับภาพหลอน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129277_ChoiceDesc2 = {
    Text = "【ปฏิเสธภาพหลอน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129277_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_129277_Desc = {
    Text = "ใต้สะพานเหล็กที่มืดทึบและหนักหน่วง บนชายฝั่งแม่น้ำที่เงียบสงบซึ่งมีต้นอ้อขึ้นรก อยู่ๆ ก็มีผีเสื้อที่เปล่งประกายบินออกมา\nผีเสื้อเบาๆ ลงบนฝ่ามือของคุณ เสียงร้องโหยหวนที่น่าขนลุกหยุดลง แทนที่ด้วยเสียงร้องเรียงรายของคนงานที่ขนเหล็กเส้น เสียงเคาะของค้อนตอก และเสียงโลหะที่กระทบกันอย่างใสแจ๋ว……"
  },
  Event_129277_Name = {
    Text = "ภาพหลอนของสะพานเหล็ก"
  },
  Event_129278_ChoiceDesc1 = {
    Text = "【แสดงคำสาปแช่ง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」สองครั้ง ติดเชื้อ「(Skill.Arg2)」สองครั้ง"
  },
  Event_129278_ChoiceDesc2 = {
    Text = "【ปฏิเสธอีกา】รับตราประทับแบบเลือก 1 จาก 3 สองครั้ง"
  },
  Event_129278_ChoiceDesc3 = {
    Text = "【ละเลย】"
  },
  Event_129278_Desc = {
    Text = "อีกาที่มีหลายหัวที่ดำมืดและมีอาการป่วยบินออกมาจากผ้าคลุมสีดำของผู้ศรัทธาแห่งโคมไฟ และลงบนไหล่ของคุณ \n「เห็นหัวของฉันไหม? แค่ลองชิมคำสาป ฉันก็จะมีหัวใหม่ขึ้นมา ให้ฉันดูสิ คำสาปของคุณ!」"
  },
  Event_129278_Name = {
