  Event_129900_ChoiceDesc2 = {
    Text = "【คำอธิษฐาน】ได้รับสิ่งประดิษฐ์ทอง「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_129900_Desc = {
    Text = "ชิ้นหนึ่งของกระดูกซีดขาว ครึ่งหนึ่งจมอยู่ในลาวาหลอมละลายสีดำสนิท"
  },
  Event_129900_Name = {
    Text = "กระดูกซีดจาง"
  },
  Event_130337_ChoiceDesc1 = {
    Text = "【นั่งลง】นำ「หุ่นเชิด」ใส่กองการ์ด"
  },
  Event_130337_Desc = {
    Text = "เมื่อเท้าทั้งสองของเจ้าก้าวขึ้นบันไดโรงละคร สายตาก็ไม่อาจละจากเวทีนี้ได้อีกต่อไป\nสายใยโชคชะตาชักนำเรื่องราวนับอนันต์ให้หมุนเวียนอยู่ ณ ที่นี้——ฝุ่นผงแห่งอดีต แสงเงาแห่งปัจจุบัน หมอกมัวแห่งอนาคต ล้วนปั่นป่วนอยู่เบื้องหน้าเวที\nเจ้าลืมไปว่าตนมาจากที่ใด ต้องการไปที่ไหน ร่องรอยแห่ง「ตัวตน」หลอมละลายหายไปในเงาของม่าน ขณะนี้ เจ้าเป็นทั้งผู้ชมที่นั่งเงียบงัน และนักแสดงที่ลุกโชนบนเวที\nความหมายทั้งหมดของการดำรงอยู่ของเจ้า ยุบรวมเป็นรอยจารึกสองเส้น: จ้องมอง และแสดง"
  },
  Event_130337_Name = {
    Text = "เวทีแห่งพรหมลิขิต"
  },
  Event_131264_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_131264_Desc = {
    Text = "พวกเจ้าเลือกพลัง เลือกความเชื่อมั่นอันแน่วแน่และความกล้าหาญที่มุ่งไปข้างหน้าไม่หยุดยั้ง\nแต่...ราคาที่ต้องจ่าย...ความหมายของราคาที่ต้องจ่ายที่มีอยู่ ก็คือเพื่อให้แบกรับ ไม่ใช่หรือ?"
  },
  Event_131264_Name = {
    Text = "สายตาจากอดีต"
  },
  Event_131265_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_131265_Desc = {
    Text = "เจ้าทนความเจ็บปวดในห้วงสมอง กำมือแน่นยึดความทรงจำที่กระจัดกระจายและแตกสลายไว้ ภายใต้ความอดทนอันยากลำบากของเจ้า รอยร้าวเหล่านั้นเริ่มถูกเย็บปะ\nเจ้าจากมาเพื่อจดจำ ต่อสู้เพื่อจดจำ เจ้าจะไม่ยอมให้ความทรงจำใดหลุดลอยไปจากตัวเอง"
  },
  Event_131265_Name = {
    Text = "ความทรงจำที่แตกสลาย"
  },
  Event_131266_ChoiceDesc1 = {
    Text = "【ปกป้องความทรงจำ】ได้รับตราจารึก เลือก 1 จาก 3"
  },
  Event_131266_ChoiceDesc2 = {
    Text = "【ปิดกั้นรอยแยก】เลือก 1 จาก 3 การ์ดคำสั่งเพื่อรับตราจารึก:「(EnchantConfig.Arg1)」 ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_131266_Desc = {
    Text = "เจ้าไม่เคยสงสัยความทรงจำของตัวเอง มันอบอุ่น แข็งแกร่ง เป็นท่าเรือที่เจ้าพึ่งพาได้มากที่สุดและสมบัติล้ำค่าที่เจ้าหวงแหนที่สุด\nแต่ตอนนี้ ภายใต้การรบกวนของนรกลึก ความทรงจำเหล่านั้นเริ่มปรากฏรอยร้าวที่ปั่นป่วน"
  },
  Event_131266_Name = {
    Text = "ความทรงจำที่แตกสลาย"
  },
  Event_131267_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_131267_Desc = {
    Text = "พลังจิตหลั่งไหลเข้าสู่ห้วงสมอง ซ่อมแซมรอยแยกอันน่าสะพรึง เจ้าใช้กำลังทั้งหมด ในที่สุดก็ทำให้รอยร้าวเหล่านั้นกลับคืนสู่สภาพสมบูรณ์\nเจ้าจากมาเพื่อจดจำ ต่อสู้เพื่อจดจำ เจ้าจะไม่ยอมให้ความทรงจำใดหลุดลอยไปจากตัวเอง"
  },
  Event_131267_Name = {
    Text = "ความทรงจำที่แตกสลาย"
  },
  Event_131268_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_131268_Desc = {
    Text = "「อู้ฮู้ฮู้ฮู้...ฮ่าฮ่าฮ่าฮ่า!!」\nไม่มีใครเข้าใจคำถามของเจ้า พวกเขาตอบรับด้วยเสียงร่ำไห้และหัวเราะแหลมคม"
  },
  Event_131268_Name = {
    Text = "ผู้ถูกทอดทิ้ง"
  },
  Event_131269_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_131269_Desc = {
    Text = "พวกเจ้ามองกลับไปยังมัน สายใยสั่นไหว สายตาอันอ่อนโยนโอบกอดความทรงจำไว้ในอ้อมแขน\nเจ้าเงียบงันมองผู้ควบคุมชะตากรรมคนนั้น หากได้เลือกอีกครั้ง เธอจะตัดสินใจอย่างไร?"
  },
  Event_131269_Name = {
    Text = "สายตาจากอดีต"
  },
  Event_131270_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_131270_Desc = {
    Text = "「อู้ฮู้ฮู้ฮู้...ฮ่าฮ่าฮ่าฮ่า!!」\nเสียงร่ำไห้และหัวเราะแหลมคมค่อยๆ จางหายไปต่อหน้าเจ้า ไม่มีวิญญาณใดมาทำร้ายเจ้า——พวกเขาชินชากับการถูกเพิกเฉยมานานแล้ว"
  },
  Event_131270_Name = {
    Text = "ผู้ถูกทอดทิ้ง"
  },
  Event_131271_ChoiceDesc1 = {
    Text = "【จ้องมองความทรงจำ】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」 ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_131271_ChoiceDesc2 = {
    Text = "【ลืมเลือนความทรงจำ】ปลุกตื่นผู้ถูกปลุกสุ่ม 2 คน ติดเชื้อสองครั้ง「(Skill.Arg1)」"
  },
  Event_131271_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_131271_Desc = {
    Text = "ภายในร่างของเด็กหญิง เจ้าได้ยินเสียงไหแตก ความทรงจำหลุดออกจากภาชนะของมัน มาถึงข้างกายพวกเจ้า\nเพื่อนเล่นวัยเด็ก ของขวัญจากพ่อแม่ จินตนาการอันบริสุทธิ์ของเมฆขาวและนกบิน อุดมคติขาวสะอาดดั่งท้องฟ้า...ความทรงจำทั้งหมดลืมตาขึ้น เงียบงันจ้องมองมายังพวกเจ้า\nมันถามไถ่ มันร่ำไห้ มันรอคอย"
  },
  Event_131271_Name = {
    Text = "สายตาจากอดีต"
  },
  Event_131272_ChoiceDesc1 = {
    Text = "【ถาม】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_131272_ChoiceDesc2 = {
    Text = "【ไม่สนใจ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_131272_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_131272_Desc = {
    Text = "เสียงร้องโหยหวนแหลมคมดังขึ้นข้างหูเจ้า วิญญาณที่เจ็บปวดกำลังฉีกใบหน้าและร่างกายของตัวเองต่อหน้าเจ้า...\nพวกเขาเป็นใคร? นักโทษแห่งนรกลึก? ชะตากรรมที่ถูกทอดทิ้ง? ความทรงจำที่ถูกฝังกลบ?"
  },
  Event_131272_Name = {
    Text = "ผู้ถูกทอดทิ้ง"
  },
  Event_133380_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_133380_Desc = {
    Text = "เจ้านั่งลงบนเก้าอี้กำมะหยี่ที่เป็นของเจ้า ม่านสีแดงสดค่อยๆ เปิดออกอย่างเงียบงัน\nผู้ชมที่รัก เวทีจะตอบสนองความคาดหวังของท่าน\nนักแสดงนำของละครเรื่องนี้ ได้ขึ้นเวทีแล้ว"
  },
  Event_133380_Name = {
    Text = "เวทีแห่งพรหมลิขิต"
  },
  Event_141995_ChoiceDesc1 = {
    Text = "【ลองดูง่ายๆ】ลบการ์ดใดก็ได้สูงสุด 5 ใบ"
  },
  Event_141995_ChoiceDesc2 = {
    Text = "【ให้เขาวิจัย】ลบการ์ดคำสั่งแบบสุ่ม 5 ใบ รับเรลิกที่ได้รับพร 「(RelicConfig.Arg1)」."
  },
  Event_141995_ChoiceDesc3 = {
    Text = "【คิดย้อนกลับ?】เลือกร่างตื่นสูงสุดสองร่าง สร้างชุดการ์ดพื้นฐานครบชุดของพวกเขาใส่ลงในสำรับ"
  },
  Event_141995_Desc = {
    Text = "คุณมาถึงลานกว้างแห่งหนึ่ง ผู้คนมากมายเดินผ่านไปมาอย่างรีบเร่ง บางทีอาจหาสิ่งที่น่าสนใจได้ที่นี่.\nคุณเคาะประตูห้องที่มีแสงไฟสลัวส่องอยู่ ชายคนหนึ่งที่แต่งกายเหมือนนักวิจัยโผล่หัวออกมา คุณเห็นเครื่องมือทางวิทยาศาสตร์ที่ไม่รู้จักมากมาย เขาดึงคุณนั่งลงและอ้างตัวว่าเป็น 「นักวิวัฒนาการ」 เขาเต็มไปด้วยความคลั่งไคล้ พยายามแนะนำ 「วิธีการทางวิทยาศาสตร์」 ของเขาอย่างเต็มที่.\n「มีเพียงการลบสิ่งที่ซ้ำซ้อนและน่าเบื่อในตัวมนุษย์ออกไป นั่นคือทางแห่งวิวัฒนาการที่แท้จริง!」"
  },
  Event_141995_Name = {
    Text = "นักวิวัฒนาการ"
  },
  Event_141996_ChoiceDesc1 = {
    Text = "【ฝึกพิเศษด้านการโจมตี】เพิ่มตราประทับแบบสุ่มให้กับโจมตีพื้นฐานทั้งหมดที่ยังไม่มีตราประทับ"
  },
  Event_141996_ChoiceDesc2 = {
    Text = "【ฝึกพิเศษด้านการป้องกัน】เพิ่มตราประทับแบบสุ่มให้กับการป้องกันพื้นฐานทั้งหมดที่ยังไม่มีตราประทับ"
  },
  Event_141996_ChoiceDesc3 = {
    Text = "【ฝึกอย่างไม่ลังเล】เพิ่มตราประทับแบบสุ่มให้กับการ์ดคำสั่ง 15 ใบแบบสุ่ม และรับการ์ดอาการแบบสุ่ม 5 ใบ"
  },
  Event_141996_Desc = {
    Text = "คุณมาถึงลานกว้างแห่งหนึ่ง ผู้คนต่างเดินกันขวักไขว่ บางทีอาจหาสิ่งน่าสนใจได้ที่นี่.\nเสียงกระทบของโลหะกึกก้องอยู่ในลานโล่ง มีหลายคนกำลังประลองฝีมือกันอยู่เพื่อพัฒนาทักษะการต่อสู้ ชายหนุ่มสวมเกราะแบบโบราณคนหนึ่งสังเกตเห็นคุณ จึงโยนดาบมาให้และส่งคำเชิญให้คุณร่วมฝึกซ้อมด้วยกัน."
  },
  Event_141996_Name = {
    Text = "เวลาฝึกพิเศษ"
  },
  Event_141997_ChoiceDesc1 = {
    Text = "【เดิมพันสูง】50% โอกาสได้รับการแกะสลักแบบสุ่มและเดิมพันใหม่, 50% โอกาสได้รับรอยดำ 75"
  },
  Event_141997_ChoiceDesc2 = {
    Text = "【เดิมพันต่ำ】50% โอกาสได้รับการแกะสลักแบบสุ่มและเดิมพันใหม่, 50% โอกาสได้รับรอยดำ 75"
  },
  Event_141997_Desc = {
    Text = "พนักงานเสิร์ฟคงรอยยิ้มไว้ไม่เปลี่ยนแปลง ยกถ้วยลูกเต๋าขึ้น เสียงกังวานกึกก้อง ผู้เล่นคนอื่นๆ ต่างทำการเลือกของตนเอง. 「ปิดรับ.」เขากล่าว 「กรุณาวางเดิมพัน——」"
  },
  Event_141997_Name = {
    Text = "คาสิโนอึกทึก"
  },
  Event_141998_ChoiceDesc1 = {
    Text = "【วางเดิมพันตรงๆ】ลบการ์ดคำสั่งหนึ่งใบ"
  },
  Event_141998_ChoiceDesc2 = {
    Text = "【ลองโกง】ลบการ์ดอาการหนึ่งใบ"
  },
  Event_141998_ChoiceDesc3 = {
    Text = "【ออกจาก】"
  },
  Event_141998_Desc = {
    Text = "คุณมาถึงสถานที่ที่คึกคักอย่างยิ่ง ทุกคนมีรอยยิ้มแห่งความสุขบนใบหน้า แสงไฟสีสันที่กระพริบอย่างสุดเหวี่ยงบีบให้ความมืดของราตรีไม่มีที่อยู่. ป้ายที่มองเห็นได้ทุกหนทุกแห่งเขียนว่า：「ยินดีต้อนรับสู่คาร์นิวัล! ความฝันที่นี่ไม่มีวันสิ้นสุด ปิติสุขที่นี่ไม่มีวันการโค้งคำนับ!」\nตามกระแสฝูงชนที่แออัด คุณถูกผลักดันเข้าไปในอาคารอันหรูหรา ภายในห้องโถงทองอร่ามตระการตา เสียงผู้คนอึกทึกครึกโครม อากาศเต็มไปด้วยกลิ่นหวานของไวน์. ลูกเต๋าหนึ่งลูกกลิ้งมาหยุดที่เท้าของคุณพอดี พนักงานเสิร์ฟยิ้มประจบและบอกว่านี่คือสัญลักษณ์แห่งโชคดี. ด้วยความอยากรู้อยากเห็น คุณก้าวเดินไปข้างหน้าอีกหนึ่งก้าว บางทีอาจจะได้แสดงฝีมือในเกมนี้สักครั้ง."
  },
  Event_141998_Name = {
    Text = "คาสิโนอึกทึก"
  },
  Event_141999_ChoiceDesc1 = {
    Text = "【แลกเปลี่ยนสินค้า】ลบเรลิก 1 ชิ้น มีอัตราความน่าจะเป็น 50% ได้รับสิ่งประดิษฐ์ทองคำเลือก 3 จาก 1 และอัตราความน่าจะเป็น 50% ได้รับ 25 รอยดำ"
  },
  Event_141999_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_141999_Desc = {
    Text = "คุณมาถึงสถานที่อันคึกคักเป็นอย่างยิ่ง ทุกคนมีรอยยิ้มแห่งความสุขบนใบหน้า ไฟสีสันที่กระพริบอย่างไม่หยุดหย่อนขับไล่ความมืดของราตรีจนไม่มีที่หลบ บนป้ายที่มีอยู่ทั่วไปเขียนว่า：「ยินดีต้อนรับสู่คาร์นิวัล！ที่นี่ความฝันไม่มีสิ้นสุด ที่นี่ปิติสุขไม่มีการโค้งคำนับ！」\nในฝูงชน พ่อค้าคนหนึ่งที่แต่งกายด้วยผ้าขี้ริ้วแต่แบกห่อขนาดใหญ่อย่างน่าประหลาดใจโบกมือเรียกคุณ เขาตบห่อข้างๆ ตัว เข้ามาใกล้และพูดเสียงเบาลง ยื่นคำเชิญให้แลกเปลี่ยนสินค้ากับคุณ ถุงผ้าเก่าๆ ใบนั้นแกว่งเบาๆ ตามจังหวะที่เขาพูด และยังส่งเสียงกรอบแกรบเป็นครั้งคราว"
  },
  Event_141999_Name = {
    Text = "พ่อค้าผ้าขี้ริ้ว"
  },
  Event_142000_ChoiceDesc1 = {
    Text = "【ลองอธิษฐาน】ใช้ HP ปัจจุบัน 50% รับสิ่งประดิษฐ์ทองคำแบบสุ่ม 2 ชิ้น"
  },
  Event_142000_ChoiceDesc2 = {
    Text = "【อธิษฐานด้วยทั้งหัวใจ】ใช้ HP ปัจจุบัน 99% รับลูกตุ้มเวลา「(RelicConfig.Arg2)」"
  },
  Event_142000_ChoiceDesc3 = {
    Text = "【เอื้อมมือล้วงก้นบ่อ】รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_142000_Desc = {
    Text = "วายุพัดผ่านทุ่งนอกเมือง รอบข้างเงียบสงัด มีเพียงเสียงใบไม้ไหวของต้นไม้\nทันใดนั้น คุณได้ยินเสียงบางอย่างไหลเอื่อยๆ เดินตามเสียงไป กลิ่นคาวหวานอันเข้มข้นโชยมาก่อน คุณจึงมองเห็นต้นกำเนิดของเสียงน้ำนั้นอย่างชัดเจน——เป็นบ่ออธิษฐาน เต็มไปด้วยสีแดงเข้ม เลือดของผู้คนนับไม่ถ้วนกำลังเคลื่อนไหวอย่างต่อเนื่องอยู่ในบ่อ ราวกับว่ามีบางสิ่งใต้ผิวของเหลวกำลังจะโผล่ออกมา\nเสียงดังขึ้นในส่วนลึกของหัวใจคุณ：「จงถวายเลือดของคุณมา ข้าจะประทานพรให้แก่คุณ」"
  },
  Event_142000_Name = {
    Text = "น้ำพุเลือด"
  },
  Event_142001_ChoiceDesc1 = {
    Text = "【การเครื่องบูชาอย่างง่าย】เลือกลบเรลิก 2 ชิ้น รับสิ่งสร้างที่มีความผิด「(RelicConfig.Arg1)」"
  },
  Event_142001_ChoiceDesc2 = {
    Text = "【การเครื่องบูชาอย่างจิตศรัทธา】เลือกลบเรลิก 4 ชิ้น รับเรลิกที่ได้รับพร「(RelicConfig.Arg1)」"
  },
  Event_142001_ChoiceDesc3 = {
    Text = "【แอบหยิบเครื่องบูชา ไม่มีใครรู้】รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_142001_Desc = {
    Text = "วายุพัดผ่านทุ่งนอกเมือง รอบข้างเงียบสงัด มีเพียงเสียงใบไม้ไหวของต้นไม้\nโดยไม่รู้ตัว คุณมาถึงหน้าแท่นบูชาโบราณแห่งหนึ่ง รูปปั้นขนาดใหญ่จ้องมองคุณจากที่สูง ราวกับว่าต้องการหยิบบางสิ่งจากมือคุณ คุณเห็นตัวอักษรที่เลือนรางสลักอยู่ใต้แท่นบูชา——「การได้และเสียต้องสมดุล」"
  },
  Event_142001_Name = {
    Text = "แท่นบูชาแห่งการได้และเสีย"
  },
  Event_142002_ChoiceDesc1 = {
    Text = "【ทดลองใช้ฟรี】อัปเกรดสิ่งประดิษฐ์เงินแบบสุ่ม Arg2 ชิ้น"
  },
  Event_142002_ChoiceDesc2 = {
    Text = "【บริการปกติ】ใช้รอยดำ Arg1: อัปเกรดสิ่งประดิษฐ์เงินแบบสุ่ม Arg2 ชิ้น"
  },
  Event_142002_ChoiceDesc3 = {
    Text = "【บริการหรูหรา】ใช้รอยดำ Arg1: อัปเกรดสิ่งประดิษฐ์เงินแบบสุ่ม Arg2 ชิ้น"
  },
  Event_142002_Desc = {
    Text = "คุณมาถึงลานกว้างแห่งหนึ่ง ผู้คนมากมายเดินผ่านไปมาอย่างรีบเร่ง บางทีอาจหาสิ่งที่น่าสนใจได้ที่นี่.\nอาคารเล็กที่สาดแสงไฟอบอุ่นตั้งอยู่อย่างเงียบสงบในมุมหนึ่งของลาน ดูเหมือนจะเป็นสโมสรขั้นสูง แต่ป้ายสีเข้มที่แขวนอยู่บนกำแพงกลับเขียนไว้อย่างชัดเจนว่า 「ร้านนี้ให้บริการเพียงสิ่งมีชีวิตที่อยู่นอกเหนือจากมนุษย์เท่านั้น.」"
  },
  Event_142002_Name = {
    Text = "สโมสรพิเศษ"
  },
  Event_142003_ChoiceDesc1 = {
    Text = "【จับหนึ่งครั้ง】ได้รับการ์ดอาการหนึ่งใบ"
  },
  Event_142003_ChoiceDesc2 = {
    Text = "【ออกไป】ได้รับรอยดำ 75"
  },
  Event_142003_Desc = {
    Text = "คุณมาถึงสถานที่ที่คึกคักอย่างยิ่ง ทุกคนมีรอยยิ้มแห่งความสุขบนใบหน้า แสงไฟสีสันที่กระพริบอย่างสุดเหวี่ยงบีบให้ความมืดของราตรีไม่มีที่อยู่. ป้ายที่มองเห็นได้ทุกหนทุกแห่งเขียนว่า：「ยินดีต้อนรับสู่คาร์นิวัล! ความฝันที่นี่ไม่มีวันสิ้นสุด ปิติสุขที่นี่ไม่มีวันการโค้งคำนับ!」\nคุณสังเกตเห็นแผงจับฉลากข้างทางที่มีผู้คนรุมล้อม สายตาของทุกคนมุ่งไปที่รางวัลใหญ่ที่ถูกปิดบังอย่างมิดชิด——พ่อค้าโฆษณาความหายากของมันอย่างเต็มที่ ผู้คนต่างแย่งกันเข้าร่วม."
  },
  Event_142003_Name = {
    Text = "ความท้าทายการจับฉลาก"
  },
  Event_142004_ChoiceDesc1 = {
    Text = "【ขอยืมใช้หน่อย】"
  },
  Event_142004_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_142004_Desc = {
    Text = "ลมพัดผ่านทุ่งโล่ง รอบข้างเงียบสงัด มีเพียงเสียงใบไม้กระซิบของต้นไม้.\nทันใดนั้น คุณเห็นกระท่อมหญ้าทรุดโทรมแห่งหนึ่ง ตรงกลางมีทั่งเหล็กตั้งอยู่ ข้างๆ มีอาวุธโลหะขึ้นสนิมมากมาย ดูเหมือนจะเป็นร้านตีเหล็กที่ถูกทิ้งร้างมานาน ข้างทั่งมีคู่มือการใช้งานโดยละเอียด บอกให้คุณรู้ว่าสามารถนำเรลิกมาดัดแปลงได้ที่นี่."
  },
  Event_142004_Name = {
    Text = "ร้านตีเหล็ก"
  },
  Event_142005_ChoiceDesc1 = {
    Text = "【วางเดิมพันตรงๆ】ลบการ์ดคำสั่งหนึ่งใบ"
  },
  Event_142005_ChoiceDesc2 = {
    Text = "【ลองโกง】ลบการ์ดอาการหนึ่งใบ"
  },
  Event_142005_ChoiceDesc3 = {
    Text = "【ออกจาก】"
  },
  Event_142005_Desc = {
    Text = "เสียงเชียร์ของผู้คนรอบข้างประกาศชัยชนะของคุณ ท่ามกลางเสียงอึกทึกของผู้คน ในที่สุดคุณก็เหมือนกับพวกเขา หลงใหลอยู่ในความฝันอันแปลกประหลาดของการเดิมพันทุกสิ่ง. คุณมองไปที่ชิปในมือ ราวกับว่าพวกมันคือเพื่อนที่ซื่อสัตย์ที่สุดที่นำเกียรติยศมาให้คุณ เสียงกระซิบดังมาจากก้นโต๊ะเดิมพัน พร้อมคำร้องขออันคลุมเครือ：「ทำมันอีกครั้งเถอะ ชนะอีกครั้งเถอะ.」"
  },
  Event_142005_Name = {
    Text = "คาสิโนอึกทึก"
  },
  Event_142013_ChoiceDesc1 = {
    Text = "【เดิมพันสูง】50% โอกาสได้รับสิ่งประดิษฐ์เงินแบบสุ่มและเดิมพันใหม่, 50% โอกาสได้รับรอยดำ 75 และเข้าสู่การต่อสู้เอลิท"
  },
  Event_142013_ChoiceDesc2 = {
    Text = "【เดิมพันต่ำ】50% โอกาสได้รับสิ่งประดิษฐ์เงินแบบสุ่มและเดิมพันใหม่, 50% โอกาสได้รับรอยดำ 75 และเข้าสู่การต่อสู้เอลิท"
  },
  Event_142013_Desc = {
    Text = "พนักงานเสิร์ฟคงรอยยิ้มไว้ไม่เปลี่ยนแปลง ยกถ้วยลูกเต๋าขึ้น เสียงกังวานกึกก้อง ผู้เล่นคนอื่นๆ ต่างทำการเลือกของตนเอง. 「ปิดรับ.」เขากล่าว 「กรุณาวางเดิมพัน——」"
  },
  Event_142013_Name = {
    Text = "คาสิโนอึกทึก"
  },
  Event_142073_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142073_Desc = {
    Text = "พนักงานเสิร์ฟยกถ้วยลูกเต๋าขึ้น เพียงไม่กี่วินาที อากาศราวกับว่าชะงักงัน. ในขณะที่คำตอบถูกเปิดเผย คุณได้ยินเสียงเฮและเสียงคร่ำครวญปะปนกัน. โชคไม่ได้มงคลวาทคุณ ลูกเต๋าไม่กี่ลูกที่นอนนิ่งอยู่บนโต๊ะให้คำตอบที่ตรงข้ามกับที่คุณเลือก. คุณกวาดสายตาเป็นครั้งสุดท้าย มองดูนักพนันที่บ้าคลั่งเหล่านั้น. ถึงเวลาต้องไปแล้ว."
  },
  Event_142073_Name = {
    Text = "คาสิโนอึกทึก"
  },
  Event_142074_ChoiceDesc1 = {
    Text = "【เข้าสู่การต่อสู้】"
  },
  Event_142074_Desc = {
    Text = "ขณะที่คุณจ้องมองโต๊ะเดิมพันด้วยความคาดหวัง มือของคุณถูกจับไว้แน่น เงยหน้าขึ้นมา เจ้านายของคาสิโนกำลังมองลงมา พร้อมจะพาแขกที่ไม่ปฏิบัติตามกฎออกไป. ในทันใดนั้น สายตาทุกคู่มุ่งมาที่คุณเพียงคนเดียว ทั้งความประหลาดใจ ความเป็นศัตรู และความสะใจ......คุณตระหนักว่า คนๆ หนึ่งอาจโกงได้หลายครั้ง แต่ตราบใดที่ถูกค้นพบเพียงครั้งเดียว ก็ต้องเผชิญกับความอับอายขายหน้าอย่างสิ้นเชิง."
  },
  Event_142074_Name = {
    Text = "คาสิโนอึกทึก"
  },
  Event_142103_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142103_Desc = {
    Text = "คุณหลบหนีออกจากคาสิโนได้สำเร็จด้วยวิธีทางกายภาพ เสียงอึกทึกของฝูงชนถูกทิ้งไว้เบื้องหลัง คุณเร่งฝีเท้าจากไป——ส่วนความวุ่นวายที่เกิดขึ้น ก็จะมีคนไปจัดการเองอยู่แล้ว."
  },
  Event_142103_Name = {
    Text = "คาสิโนอึกทึก"
  },
  Event_142105_ChoiceDesc1 = {
    Text = "【จับอีกครั้ง】ได้รับการ์ดอาการหนึ่งใบ"
  },
  Event_142105_ChoiceDesc2 = {
