  },
  Event_142105_Desc = {
    Text = "คุณลองจับดูครั้งหนึ่ง ไม่มีอะไรเกิดขึ้น. แต่ด้านหลังของการ์ดเขียนว่า：「ครั้งต่อไปง่ายกว่า」\n......จะลองอีกครั้งไหม?"
