    Text = "【ออกจาก】"
  },
  Event_142109_Desc = {
    Text = "ฟังเสียงหัวใจเต้น คุณเปิดตั๋วจับรางวัล ตัวอักษรสีทองอันสุกสว่างโดดเข้ามาในสายตาคุณ พ่อค้าเขย่ากระดิ่งด้วยความกระตุ้น คนเดินถนนทุกคนต่างมองคุณด้วยสายตาอิจฉา\n「รางวัลใหญ่ถูกจับไปแล้ว！」"
  },
  Event_142109_Name = {
