  },
  Event_142110_Desc = {
    Text = "คุณลองจับดูครั้งหนึ่ง ไม่มีอะไรเกิดขึ้น. แต่ด้านหลังของการ์ดเขียนว่า：「ครั้งต่อไปง่ายกว่า」\n......จะลองอีกครั้งไหม?"
  },
  Event_142110_Name = {
    Text = "ความท้าทายการจับฉลาก"
  },
  Event_142118_ChoiceDesc1 = {
    Text = "【แลกเปลี่ยนสินค้า】ลบเรลิก 1 ชิ้น มีอัตราความน่าจะเป็น 25% ได้รับลูกตุ้มเวลาเลือก 3 จาก 1 อัตราความน่าจะเป็น 50% ได้รับสิ่งประดิษฐ์ทองคำแบบสุ่ม 2 ชิ้น และอัตราความน่าจะเป็น 25% ได้รับ 25 รอยดำ"
  },
  Event_142118_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_142118_Desc = {
    Text = "พ่อค้ารับสิ่งของที่คุณส่งมาให้ พลิกดูไปมาใต้แสงจันทร์จนตาเกือบจะถลน คุณรอนานมาก กว่าเขาจะยิ้มออก แล้วหยิบกล่องเหล็กขึ้นสนิมออกมาจากถุง 「ลองเปิดดูสิ นี่คือกล่องสุ่มที่กำลังฮิตที่สุดในตอนนี้」\nคุณเปิดมันออก แต่กลับค้นพบว่าข้างในมีเพียงตราดำเล็กน้อยที่ไม่เป็นที่พอใจ พ่อค้าถูมือ แสดงสีหน้าเสียใจและบอกว่าสามารถลองอีกครั้งได้"
  },
  Event_142118_Name = {
    Text = "พ่อค้าผ้าขี้ริ้ว"
  },
  Event_142119_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142119_Desc = {
    Text = "พ่อค้ารับสิ่งของที่คุณส่งมาให้ พลิกดูไปมาใต้แสงจันทร์จนตาเกือบจะถลน คุณรอนานมาก กว่าเขาจะยิ้มออก แล้วหยิบกล่องเหล็กขึ้นสนิมออกมาจากถุง 「ลองเปิดดูสิ นี่คือกล่องสุ่มที่กำลังฮิตที่สุดในตอนนี้」\nคุณเปิดมันออก ข้างในมีบางสิ่งนอนอยู่"
  },
  Event_142119_Name = {
    Text = "พ่อค้าผ้าขี้ริ้ว"
  },
  Event_142120_ChoiceDesc1 = {
    Text = "【แลกเปลี่ยนสินค้า】ลบสิ่งประดิษฐ์ทองคำ 1 ชิ้น มีอัตราความน่าจะเป็น 50% ได้รับลูกตุ้มเวลาเลือก 3 จาก 1 และอัตราความน่าจะเป็น 50% ได้รับเรลิกที่ได้รับพรเลือก 3 จาก 1"
  },
  Event_142120_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_142120_Desc = {
    Text = "คุณเปิดกล่องสุ่มอีกครั้ง แต่กลับพบว่ายังไม่มีสิ่งของที่คุณต้องการ พ่อค้ารีบยิ้มแก้เขิน แล้วหยิบกล่องเหล็กอีกใบออกมา ยื่นให้คุณด้วยสองมือ\n「อย่าโกรธเลย ลูกค้า！ฉันสาบานว่าครั้งนี้จะต้องมีของดีชั้นเลิศ......」เขาพูดอย่างนั้น แต่แอบเลื่อนมือข้างหนึ่งออกมา แบฝ่ามือให้คุณ 「แน่นอน ของมีค่าย่อมต้องแลกด้วยของมีค่า」"
  },
  Event_142120_Name = {
    Text = "พ่อค้าผ้าขี้ริ้ว"
  },
  Event_142138_ChoiceDesc1 = {
    Text = "【ขอยืมใช้หน่อย】"
