    Text = "ร้านตีเหล็ก"
  },
  Event_142142_ChoiceDesc1 = {
    Text = "【หลอมทำลาย】เลือกเรลิกทองคำ 1 ชิ้นเพื่อลบออก รับสิ่งประดิษฐ์เงิน 2 ชิ้น และรับรอยดำ 50"
  },
  Event_142142_ChoiceDesc2 = {
    Text = "【ชุบแข็ง】เลือกเรลิก 2 ชิ้นเพื่อลบออก รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」."
  },
  Event_142142_ChoiceDesc3 = {
    Text = "【ชุบแข็งสูงสุด】เลือกเรลิกทองคำ 2 ชิ้นเพื่อลบออก รับลูกตุ้มเวลา「(RelicConfig.Arg1)」."
  },
  Event_142142_Desc = {
    Text = "คุณหยิบค้อนที่วางอยู่ข้างๆ และตั้งใจจะ..."
  },
  Event_142142_Name = {
    Text = "ร้านตีเหล็ก"
  },
  Event_142167_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142167_Desc = {
    Text = "หลังจากใช้งานไปสามรอบ ทั่งก็บุบลงอย่างสิ้นเชิง และค้อนก็เต็มไปด้วยรอยสึกหรอ ดูเหมือนจะใช้งานไม่ได้อีกต่อไปแล้ว."
  },
  Event_142167_Name = {
    Text = "ร้านตีเหล็ก"
  },
  Event_142235_ChoiceDesc1 = {
    Text = "【ฉันจะมุ่งมั่นก้าวไปข้างหน้า】รับ「บริสุทธิ์」：การ์ดคำสั่งทั้งหมดได้รับการเสริมสร้างถาวร 20 ชั้น"
  },
  Event_142235_ChoiceDesc2 = {
    Text = "【ฉันจะไม่หลีกหนี】รับ「การยกระดับ」：ขีดจำกัดกุญแจเงินและขีดจำกัดความคลั่งลดลงถาวร 20%"
  },
  Event_142235_Desc = {
    Text = "ทันใดนั้นสายตาของคุณก็ถูกปกคลุมด้วยหมอก โลกเริ่มพร่ามัวไปหมด ในความมึนงง เสียงหนึ่งดังขึ้นในใจคุณ:\n「คุณยังจะก้าวต่อไปอีกหรือ?」"
  },
  Event_142235_Name = {
    Text = "ใกล้ถึงสถานีสุดท้าย"
  },
  Event_142925_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142925_Desc = {
    Text = "พนักงานของสโมสรรับค่าตอบแทนแล้วให้บริการขั้นพื้นฐานแก่คุณ พวกเขานำสิ่งของที่คุณมอบให้เข้าไปในห้องมืดทึบ ไม่ต้องรอนาน เมื่อเขากลับออกมา สิ่งของถูกวางไว้บนถาดแล้ว ดูเหมือนจะแตกต่างจากเดิมเล็กน้อย."
  },
  Event_142925_Name = {
    Text = "สโมสรพิเศษ"
  },
  Event_142926_ChoiceDesc1 = {
    Text = "【ลบสิ่งประดิษฐ์ทองคำหนึ่งชิ้น】(ต้องมีสิ่งประดิษฐ์ทองคำ)"
  },
  Event_142926_ChoiceDesc2 = {
    Text = "【มีเรลิกที่เสริมสร้าง (Forged) ให้เลือก】"
  },
  Event_142926_ChoiceDesc3 = {
    Text = "【ออกจาก】"
  },
  Event_142926_Desc = {
    Text = "ทดสอบ「จำนวนเรลิก」「เลือกรายการเรลิก」"
  },
  Event_142927_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142927_Desc = {
    Text = "พนักงานของสโมสรรับค่าตอบแทนแล้วให้บริการหรูหราแก่คุณ พวกเขาวางสิ่งของของคุณลงในกล่องอย่างระมัดระวัง แล้วนำเข้าไปในห้องมืดทึบ คุณรอคอยอยู่นานมาก จนกระทั่งเขากลับออกมาอีกครั้ง ยื่นสิ่งของให้ด้วยสองมือ สีหน้าสงบนิ่งเช่นเคย."
  },
  Event_142927_Name = {
    Text = "สโมสรพิเศษ"
  },
  Event_142928_ChoiceDesc1 = {
    Text = "【เลือกร่างตื่นสูงสุด 2 ร่างให้เต็มด้วยอาลีมัส】"
  },
  Event_142928_ChoiceDesc2 = {
    Text = "【ต้องเลือกร่างตื่น 2 ร่างที่เต็มไปด้วยอาลีมัส】"
  },
  Event_142928_ChoiceDesc3 = {
    Text = "【ออกจาก】"
  },
  Event_142928_Desc = {
    Text = "ทดสอบ「เลือกร่างตื่นตามเงื่อนไข」"
  },
  Event_142929_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142929_Desc = {
    Text = "นักวิจัยเดินวนรอบคุณซ้ำแล้วซ้ำเล่า พิจารณาอย่างละเอียดนานมาก จึงเริ่มลงมือทำงาน — โดยไม่ถามความเห็นคุณ เวลาผ่านไประยะหนึ่ง เมื่อคุณเตรียมจะออกจากสถาบันวิจัยแปลกๆ แห่งนี้ คุณรู้ชัดว่าตัวเองสูญเสียสิ่งต่างๆ ไปมาก แต่เขากลับปรบมือแสดงความยินดีกับคุณว่า: 「นี่คือแก่นแท้ของวิวัฒนาการ!」"
  },
  Event_142929_Name = {
    Text = "นักวิวัฒนาการ"
  },
  Event_142930_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142930_Desc = {
    Text = "คุณเอื้อมมือล้วงลงไปในน้ำสีชาดแดงฉาน และสัมผัสได้ถึงบางสิ่งที่มีประโยชน์."
  },
  Event_142930_Name = {
    Text = "น้ำพุเลือด"
  },
  Event_142931_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142931_Desc = {
    Text = "เสียงนั้นจางหายไป คุณรู้สึกเต็มเปี่ยมด้วยความมุ่งมั่น และรู้สึกถึงพละกำลังที่อุบัติขึ้น."
  },
  Event_142931_Name = {
    Text = "ใกล้ถึงสถานีสุดท้าย"
  },
  Event_142932_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142932_Desc = {
    Text = "เสียงนั้นจางหายไป คุณรู้สึกเต็มเปี่ยมด้วยความมุ่งมั่น และจิตใจแจ่มใสยิ่งขึ้น."
  },
  Event_142932_Name = {
    Text = "ใกล้ถึงสถานีสุดท้าย"
  },
  Event_142933_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142933_Desc = {
    Text = "คุณหยิบเครื่องบูชาเล็กน้อยจากกองที่สูงเป็นภูเขา แล้วรีบเดินออกไปอย่างรวดเร็ว ขณะที่คุณจากไป ดวงตาของรูปปั้มดูเหมือนจะขยับ"
  },
  Event_142933_Name = {
    Text = "แท่นบูชาแห่งการได้และเสีย"
  },
  Event_142934_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142934_Desc = {
    Text = "คุณฝึกซ้อมโดยมุ่งเน้นไปที่การป้องกัน เผชิญกับการจู่โจมของคู่ต่อสู้ คุณใช้อาวุธรับมืออยู่ตลอดเวลา ความสามารถในการป้องกันและปฏิกิริยาตอบสนองของคุณดีขึ้นอย่างเห็นได้ชัด."
  },
  Event_142934_Name = {
    Text = "เวลาฝึกพิเศษ"
  },
  Event_142935_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142935_Desc = {
    Text = "นักวิจัยสวมถุงมือ หยิบเครื่องมือรูปร่างแปลกๆ จากตู้มาสาธิตให้คุณดู คุณไม่รู้ว่าเขาทำอะไรกันแน่ แต่ดูเหมือนจะรู้สึกเบาสบายขึ้นจริงๆ."
  },
  Event_142935_Name = {
    Text = "นักวิวัฒนาการ"
  },
  Event_142936_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142936_Desc = {
    Text = "คุณไม่ได้เลือกทิศทางที่จะมุ่งเน้น แต่กลับฝึกซ้อมกับผู้อื่นโดยไม่สนใจขีดจำกัดของร่างกายตัวเอง จนกระทั่งทุกคนหมดแรง คุณรู้ว่าตัวเองพัฒนาขึ้นมาก แต่ในขณะเดียวกัน คุณก็ต้องจ่ายราคาที่ต้องจ่ายสำหรับสิ่งนั้นด้วย."
  },
  Event_142936_Name = {
    Text = "เวลาฝึกพิเศษ"
  },
  Event_142937_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142937_Desc = {
    Text = "คุณหยิบสิ่งของบางอย่างจากถุงอย่างสุ่มสี่สุ่มห้าไปเครื่องบูชา และได้รับรางวัลที่เท่าเทียมกัน"
  },
  Event_142937_Name = {
    Text = "แท่นบูชาแห่งการได้และเสีย"
  },
  Event_142938_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142938_Desc = {
    Text = "คุณถวายเครื่องบูชาอันล้ำค่า และได้รับรางวัลที่เท่าเทียมกัน"
  },
  Event_142938_Name = {
    Text = "แท่นบูชาแห่งการได้และเสีย"
  },
  Event_142939_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142939_Desc = {
    Text = "คุณเต็มไปด้วยความสงสัยต่อวิธีการวิจัยของเขา หลังจากถกเถียงกันสักพัก เขาก็ยอมให้คุณใช้เครื่องมือเหล่านี้ด้วยตัวเอง เพื่อแสวงหา 「วิวัฒนาการ」 ในแบบอื่น.\nด้วยอุปกรณ์ชุดเดียวกัน คุณกลับทำให้สิ่งที่ควรจะถูก 「ลบ」 ออกไปนั้น 「เพิ่มพูน」 ขึ้นมากมายโดยบังเอิญ ก่อนจะจากไป คุณได้ยินเสียงร่ำไห้คร่ำครวญของนักวิจัย."
  },
  Event_142939_Name = {
    Text = "นักวิวัฒนาการ"
  },
  Event_142940_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142940_Desc = {
    Text = "พนักงานของสโมสรให้บริการฟรีแก่คุณ พวกเขานำสิ่งของที่คุณมอบให้เข้าไปในห้องมืดทึบ ไม่นานนักเขาก็กลับออกมา วางสิ่งของคืนในมือคุณโดยไม่พูดอะไรสักคำ."
  },
  Event_142940_Name = {
    Text = "สโมสรพิเศษ"
  },
  Event_142941_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142941_Desc = {
    Text = "คุณถวายเลือดจำนวนมากแก่บ่ออธิษฐาน ของขวัญอันล้ำค่าได้ปรากฏขึ้นมาจากบ่อ."
  },
  Event_142941_Name = {
    Text = "น้ำพุเลือด"
  },
  Event_142942_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142942_Desc = {
    Text = "คุณเริ่มฝึกซ้อมในด้านการโจมตี ท่ามกลางเสียงกระทบของเหล็กกล้า ทักษะการตีและความเร็วของคุณได้รับการพัฒนาขึ้น."
  },
  Event_142942_Name = {
    Text = "เวลาฝึกพิเศษ"
  },
  Event_142943_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_142943_Desc = {
    Text = "คุณถวายเลือดเพียงเล็กน้อยแก่บ่ออธิษฐาน ของขวัญได้ลอยขึ้นมาจากก้นบ่อ."
  },
  Event_142943_Name = {
    Text = "น้ำพุเลือด"
  },
  Event_142944_ChoiceDesc1 = {
    Text = "【เลือกอัปเกรดเรลิก】"
  },
  Event_142944_ChoiceDesc2 = {
    Text = "【อัปเกรดเรลิกแบบสุ่ม】"
  },
  Event_142944_ChoiceDesc3 = {
    Text = "【ออกจาก (ทดสอบ)】"
  },
  Event_142944_Desc = {
    Text = "ทดสอบ「อัปเกรดเรลิก」, เรลิกเพิ่มเอง"
  },
  Event_146258_ChoiceDesc1 = {
    Text = "【อัญเชิญเขา】รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146258_ChoiceDesc2 = {
    Text = "【ตอบสนองต่อพวกมัน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_146258_ChoiceDesc3 = {
    Text = "【เพิกเฉยพวกมัน】ได้รับ 50 ตราดำ"
  },
  Event_146258_Desc = {
    Text = "บนแท่นบูชา, ชุดคลุมขาวของจูเลียตจมอยู่ในควันหนาทึบ, เถ้าธูปผสมกับกลิ่นคาวหวานบางอย่าง.\n「ผู้ถือไฟทรงเมตตาต่อคนบาปในโลก,」เสียงของเธอไม่ดังนัก, แต่กลับกดทับเสียงสวดมนต์อันพึมพำทั่วทั้งวิหารได้อย่างชัดเจน, 「ดังเช่นมารดาผู้เมตตาต่อทารกในอ้อมแขน.」\nเครื่องบูชาบนแท่นสะท้อนแสงมันวาวในเปลวเทียน, ควันบางๆ ขดตัวขึ้นตามรูปทรงของมัน, ทำให้ใบหน้าของผู้คนด้านล่างเลือนราง.\nคาสเตอร์มองผ่านควันที่แกว่งไหวนั้นไปยังโพลลักซ์, เขายืนอยู่ท่ามกลางผู้ศรัทธา, ก้มตา, ใบหน้าแสดงความศรัทธาอันพอดิบพอดีที่ถูกฝึกมา."
  },
  Event_146258_Name = {
    Text = "ความฝันเก่า III"
  },
  Event_146259_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146259_Desc = {
    Text = "อย่าใส่ใจ, เป็นเพียงเสียงโหยหวนของลมหิมะ, เสียงため้าวของทะเลสาบน้ำแข็ง, หรือเสียงโศกเศร้าของยอดเขา.\nเป็นกิ่งไม้แห้งตายที่ยังหลงเหลืออยู่, กระซิบกระซาบถูไถกัน.\nพวกมันพร่ำรำพันอย่างโศกเศร้าชั่วนิรันดร์, เพื่อผู้บุกเบิกทุกคนที่เคยฝังร่างอยู่ในรอยแยกของน้ำแข็ง."
  },
  Event_146259_Name = {
    Text = "บทเพลงแห่งทะเลสาบน้ำแข็ง"
  },
  Event_146260_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146260_Desc = {
    Text = "หากความเท่าเทียมอย่างสมบูรณ์คือความยุติธรรม เฮลอต: ตรวนสีชาดจะมีโอกาสอธิษฐานเท่าเทียมกับพวกเจ้าหรือไม่?\nแล้วต่อการกระทำที่เธอแย่งชิงและขับไล่คู่แข่งนั้น เจ้าควรจะวางเฉยหรือเปล่า?\n「หรือจะหยุดคิดเรื่องไร้สาระแล้วปีนต่อไปซะที!」เสียงเรียกของคาราบูดังขึ้นข้างหู."
  },
  Event_146260_Name = {
    Text = "ความยุติธรรมที่ไร้สาระ"
  },
  Event_146261_ChoiceDesc1 = {
    Text = "【ภูเขาเกรงกลัวความหิวโหย】"
  },
  Event_146261_ChoiceDesc2 = {
    Text = "【ภูเขาเกรงกลัวการสูญเสีย】"
  },
  Event_146261_ChoiceDesc3 = {
    Text = "【ภูเขาเกรงกลัวความตาย】"
  },
  Event_146261_Desc = {
    Text = "เธอเดินอยู่บนร่างกายของภูเขา.\nการสั่นสะเทือนของภูเขาเปิดเผยความลับของมัน.\nความโลภของภูเขา กำหนดความหวาดกลัวของภูเขา."
  },
  Event_146261_Name = {
    Text = "ความลับของภูเขา"
  },
  Event_146262_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146262_Desc = {
    Text = "เจ้าเพลิดเพลินกับขนอันเรียบนุ่ม, เจ้าถูกจองจำอยู่ในความปรารถนาของตนเอง.\nเจ้าพึงพอใจกับสัมผัสของมัน.\nสิ่งที่ซ่อนอยู่ใต้รูปลักษณ์ภายนอกนั้น, สำคัญจริงๆ หรือ?"
  },
  Event_146262_Name = {
    Text = "แมวดำย่องเดิน"
  },
  Event_146263_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146263_Desc = {
    Text = "เธอรับปลายเชือกแดงมาอย่างเงียบๆ แล้วผูกมันไว้ที่ข้อมือของเธอ.\nโพลลักซ์ทำตามแบบเดียวกัน มือของเด็กทั้งสองก็ถูกเชือกแดงเส้นเล็กๆ ผูกเชื่อมไว้ด้วยกันในไม่ช้า.\nแม้ว่าพื้นที่ค้นหาในเวลาเดียวกันจะแคบลง แต่พวกเธอก็ถูกกำหนดให้เกิดมาด้วยกันและตายด้วยกัน ใช่ไหม?\nที่เหลือ ก็ปล่อยให้โชคชะตาจัดการเถอะ."
  },
  Event_146263_Name = {
    Text = "ความฝันเก่า I"
  },
  Event_146264_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146264_Desc = {
    Text = "「ข้ารู้ดีว่ามันยากเพียงใด, ลูกที่รัก.」\n「แต่โลกนี้ไม่เคยง่ายสำหรับใครทั้งนั้น.」\n「สักวันหนึ่ง, ผีเสื้อตัวนั้นจะบินออกจากฝ่ามือของเจ้า, แล้วก็หายไปตลอดกาล.」"
  },
  Event_146264_Name = {
    Text = "มายาหรือความจริง"
  },
  Event_146265_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146265_Desc = {
    Text = "วิลเลียมเงยหน้าขึ้น สายตาของเขากวาดผ่านเจ้าอย่างรวดเร็วแล้วหยุดอยู่ที่สันเขาที่เต็มไปด้วยหิมะในระยะไกล.\n「เจ้าไม่ได้ทำสิ่งใดที่ต้องขอโทษ」เขากล่าวอย่างจริงจัง 「คำถามบางอย่างเป็นของฉัน และมีเพียงฉันเท่านั้นที่จะตอบได้」\n「แต่ขอบคุณสำหรับความเฉียบแหลมและการมองเห็นของเจ้า」"
  },
  Event_146265_Name = {
    Text = "การจมอย่างอ่อนโยน"
  },
  Event_146266_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146266_Desc = {
    Text = "สายตาของวิลเลียมระยิบระยับ.\nเจ้าอ้าปากแต่ไม่ได้พูดอะไร ความเงียบคือทางเลือกที่ดีที่สุดในขณะนี้.\nยังมีความเข้าใจกันที่ล้ำค่าระหว่างพวกเจ้า อย่าทำลายมันเลย."
  },
  Event_146266_Name = {
    Text = "การจมอย่างอ่อนโยน"
  },
  Event_146267_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_146267_Desc = {
    Text = "「คืนมาให้ฉัน, คืนมาให้ฉัน, นั่นคือพลังของฉัน!」\nภูเขาร้องไห้คร่ำครวญ, ภูเขาโหยหวน.\nภูเขาทนไม่ไหว, ทุกสิ่งที่มันเคยมีถูกพรากไปจนหมดสิ้น."
  },
  Event_146267_Name = {
    Text = "ความลับของภูเขา"
  },
  Event_146268_ChoiceDesc1 = {
    Text = "【หนีต่อไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146268_ChoiceDesc2 = {
    Text = "【รอจังหวะ】รับตราประทับ 1 ใบจาก 3 ตัวเลือก"
  },
  Event_146268_ChoiceDesc3 = {
    Text = "【ค่อยๆ จากไป】"
  },
  Event_146268_Desc = {
    Text = "「พี่ชาย, ระวังด้วย, มีอีกากำลังมอง.」\nคาสเตอร์วัยหนุ่มแบกโพลลักซ์เดินรวดเร็ว, สายตาวิตกกังวลกวาดมองทุกมุมที่น่าสงสัย, แต่ก็ไม่พบสิ่งใด.\n「อยู่ข้างบน.」\nเจ้าสะดุ้งทั้งตัว, แหงนหน้ามอง.\nในเงามืดของชายคา, อีกาตัวหนึ่งนั่งนิ่งอยู่, ดวงตาประหลาดที่หันไปทุกทิศทางต่างจ้องมองเจ้าอย่างเข้มข้น."
  },
  Event_146268_Name = {
    Text = "ความฝันเก่า II"
  },
  Event_146269_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146269_Desc = {
    Text = "คุณจดจำคำเตือนจากการฝึกไว้ดี, ว่าอย่าพึ่งพาเชือกนิรภัย.\nด้วยการเตะถีบ, คุณพอจะทรงตัวได้อย่างหวุดหวิด.\nแต่มีบางอย่างในเป้สะพายหลังกลิ้งลงไปตามหน้าผา, กลายเป็นจุดเล็กจนมองแทบไม่เห็น.\nไม่สำคัญแล้ว, อย่างน้อยคุณยังมีชีวิตอยู่."
  },
  Event_146269_Name = {
    Text = "ร่วงหล่นอย่างเงียบงัน"
  },
  Event_146270_ChoiceDesc1 = {
    Text = "【ฟังอย่างตั้งใจ】ได้รับสิ่งประดิษฐ์เงิน 「(RelicConfig.Arg1)」, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_146270_ChoiceDesc2 = {
    Text = "【ปิดหู】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_146270_Desc = {
    Text = "ลมหิมะกระแทกกับผนังหิน, ผสมกับเสียงแตกร้าวเบาๆ ที่ดังมาจากใต้ชั้นน้ำแข็ง, แตกกระจายเป็นเสียงสะอื้นที่ขาดๆ หายๆ.\nคุณยืนอยู่บนที่สูงอันเงียบสงัด, แล้วก็ได้ยินทำนองของภูเขาอย่างชัดเจน.\nมันโศกเศร้าและยิ่งใหญ่, ขับขานเพลงที่เป็นของผู้ล่วงลับเท่านั้นด้วยเสียงทุ้มต่ำ."
  },
  Event_146270_Name = {
    Text = "เพลงมนต์แห่งธรรมชาติ"
  },
  Event_146271_ChoiceDesc1 = {
    Text = "【เป็นเสียงกระดิ่ง】ติดเชื้อ「(Skill.Arg1)」, การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg2)」"
  },
  Event_146271_ChoiceDesc2 = {
    Text = "【เป็นอาหาร】ติดเชื้อ「(Skill.Arg1)」, การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg2)」"
  },
  Event_146271_ChoiceDesc3 = {
    Text = "【เป็นความคาดหวังของสุนัข】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_146271_Desc = {
    Text = "「พาฟลอฟเขย่ากระดิ่ง แล้วให้อาหารสุนัข. เมื่อทำซ้ำนานๆ เข้า เพียงแค่เขย่ากระดิ่ง สุนัขก็จะหลั่งน้ำลายออกมา.」\n「แล้วสิ่งที่ทำให้สุนัขหลั่งน้ำลาย แท้จริงแล้วคืออะไรกัน?」"
  },
  Event_146271_Name = {
    Text = "การตอบสนองแบบพาฟลอฟ"
  },
  Event_146272_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146272_Desc = {
    Text = "อย่าไปรื้อฟื้นความทรงจำ.\nวิลเลียมอยู่ในระยะที่เจ้าเอื้อมถึง.\nอย่าให้ความเจ็บปวดกลืนกินเจ้า.\nเจ้าพลาดไปมาก, แต่ยังไม่สาย."
  },
  Event_146272_Name = {
    Text = "มาจากฝั่งโน้น"
  },
  Event_146273_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146273_Desc = {
    Text = "「กำมือลงเถิด.」\n「สิ่งที่เคยงดงาม, ในฝ่ามือของเจ้าจะเหลือเพียงก้อนโคลนสีดำ.」"
  },
  Event_146273_Name = {
    Text = "มายาหรือความจริง"
  },
  Event_146274_ChoiceDesc1 = {
    Text = "【เปลี่ยนกลับ】รับรอยดำ 50"
  },
  Event_146274_ChoiceDesc2 = {
    Text = "【ลูบไล้】รับรอยดำ 75，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146274_Desc = {
    Text = "「เมี๊ยว.」แมวดำดวงตาสีเขียวก้าวย่างด้วยเท้าอันนุ่มนวลมาถูขาของเจ้า.\nในขณะเดียวกัน, 「N」ก็หายไปแล้ว."
  },
  Event_146274_Name = {
    Text = "แมวดำย่องเดิน"
  },
  Event_146275_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146275_Desc = {
    Text = "คุณไม่ได้เปล่งเสียง, เพียงปล่อยให้สายตานั้นทะลุผ่านควันไปตกลงที่ดวงตาของโพลลักซ์, ไม่ยอมเคลื่อนแม้แต่นิดเดียว.\nเขาก็ไม่ได้หลบเช่นกัน, น้องชายมักเป็นแบบนี้เสมอ, ยอมซ่อนความดื้อรั้นไว้ในส่วนลึกที่สุด, ก็ไม่ยอมก้มหัวก่อน.\nเสียงสวดในวิหาร, กลิ่นเถ้าธูป, ถ้อยคำของจูเลียตเกี่ยวกับความเมตตาและการบูชายัญ, ล้วนกลายเป็นสิ่งไกลโพ้นขึ้นมาในทันที, ราวกับเหลือเพียงแค่คุณสองคน, คั่นด้วยความเมตตาอันหลอกลวงทั่วทั้งวิหาร, คั่นด้วยกาลเวลาอันยาวนาน, จ้องมองซึ่งกันและกัน."
  },
  Event_146275_Name = {
    Text = "ความฝันเก่า III"
  },
  Event_146276_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146276_Desc = {
    Text = "ณ บัดนี้, เจ้าคือทหารยามเพียงผู้เดียวของความทรงจำอันซีดเซียวและยาวนานของตนเอง.\nเวนดิโกเหยียดมือดั่งกิ่งไม้แห้งออกมา, ปลายนิ้วตรงเข้าหาหัวใจของเจ้า, แต่ในนาทีสุดท้ายก็ถูกเจ้าสกัดกั้นไว้อย่างแข็งขัน.\nมันโซเซถอยกลับเข้าหมอก, ทิ้งไว้เพียงเสียงพึมพำแหบเบา——\n「ไม่ช้าก็เร็ว เจ้าจะยินยอมมอบทุกสิ่งให้ข้าเอง...」"
  },
  Event_146276_Name = {
    Text = "ผู้ตะกละ"
  },
  Event_146277_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146277_Desc = {
    Text = "นั่นคือความฝันอันไกลโพ้น ความฝันที่ชื่อว่าวัยเด็ก.\nตื่นขึ้นมาหน่อย. เธอไม่ได้อยู่ที่นั่น.\nเธออยู่ในพายุหิมะ ถูกล้อมรอบด้วยผู้ศรัทธาแห่งโคมไฟชั้นแล้วชั้นเล่า และคมดาบของโพลลักซ์กำลังชี้ตรงมาที่หน้าอกเธอ."
  },
  Event_146277_Name = {
    Text = "ความฝันเก่า I"
  },
  Event_146278_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146278_Desc = {
    Text = "「ข้ายอมรับการมาถึงของความตาย.」\n「ข้ายินดีฝังร่างในการเดินทางอันแสนทุกข์ทรมาน.」\n「ใต้หน้าผาชัน, ฟ้าดินจะสร้างแผ่นจารึกให้แก่ข้า.」"
  },
  Event_146278_Name = {
    Text = "ลางมรณะใกล้มาถึง"
  },
  Event_146279_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146279_Desc = {
    Text = "ภาพสะท้อนไม่ใช่อะไรนอกจากปรากฏการณ์การสะท้อนของแสง.\nสิ่งที่ทิงค์มองเห็น ส่วนใหญ่ก็คงเป็นเพียงเงาของตัวเธอเอง.\nดาวแม่ของเธออยู่ห่างออกไปหลายล้านปีแสง แม้แต่การเบี่ยงเส้นทางเพียงเล็กน้อยก็อาจทำให้พวกเธอตกลงสู่ระบบดาวที่ต่างกัน.\nปลอบใจตัวเองเช่นนี้แล้ว เจ้าก็ไม่ยึดติดกับภาพสะท้อนใต้เท้าอีกต่อไป."
  },
  Event_146279_Name = {
    Text = "เงาสะท้อนใต้ทะเลสาบ"
  },
  Event_146280_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146280_Desc = {
    Text = "มาจากกลุ่มดาว. มาจากยุคดึกดำบรรพ์. มาจากสิ่งที่มนุษย์ยังไม่รู้, หรืออาจไม่รู้ชั่วนิรันดร์.\nอย่าขอคำตอบจากพวกท่าน.\nคุณไม่รู้ราคาที่ต้องจ่าย."
  },
  Event_146280_Name = {
    Text = "บทเพลงแห่งทะเลสาบน้ำแข็ง"
  },
  Event_146281_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146281_Desc = {
    Text = "คุณหยุดก้าว, ปล่อยให้เสียงดนตรีอันโศกเศร้านั้นเต็มเปี่ยมในหู.\nเสียงลมคือไวโอลิน, เม็ดหิมะคือกลอง, เสียงระเบิดของชั้นน้ำแข็งที่แตกในระยะไกลคือเสียงประสานที่ทุ้มต่ำและถูกกดทับมานาน.\nคุณไม่อาจจับทำนองหลักของมันได้, แต่คุณรู้ว่า, ไม่ว่าในอดีตหรืออนาคต, มันจะดังขึ้นซ้ำแล้วซ้ำเล่าเพื่อนักเดินทางนับไม่ถ้วนที่ฝังร่างอยู่ที่นี่."
  },
  Event_146281_Name = {
    Text = "เพลงมนต์แห่งธรรมชาติ"
  },
  Event_146283_ChoiceDesc1 = {
    Text = "【มองขึ้นสู่แสงสวรรค์】ผู้ปลุกตื่นทุกคนตอบกลับ Arg1 อาลีมัส"
  },
  Event_146283_ChoiceDesc2 = {
    Text = "【ยืนบนยอดน้ำแข็ง】เลือกการตื่นรู้ผู้ปลุกตื่น 2 คน"
  },
  Event_146283_Desc = {
    Text = "ยอดเขาเปล่งแสงอยู่อย่างเงียบงันในม่านหมอก.\nหุบเขา, ผาหิน, พายุ, สิ่งที่ครองอยู่ที่นี่ไม่เคยมีอยู่เพื่อมนุษย์.\nเมื่ออยู่ท่ามกลางสิ่งเหล่านั้น เธอช่างเปราะบางเสียเหลือเกิน."
  },
  Event_146283_Name = {
    Text = "แตะถึงจุดสูงสุด"
  },
  Event_146284_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146284_Desc = {
    Text = "「ไม่, ไม่ใช่ความผิดของเธอ.」\n「เธอเป็นเพียงของเล่นแห่งโชคชะตา ที่ถูกไขลานไว้เท่านั้น.」"
  },
  Event_146284_Name = {
    Text = "หนูตะกละ"
  },
  Event_146285_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146285_Desc = {
    Text = "「ฟังออกแล้ว, เธอเป็นคนประเภทที่ถนัดสรุปประสบการณ์เชิงวัตถุวิสัย. แต่อย่าลืมว่า บางครั้ง ภายใต้ปรากฏการณ์ที่คล้ายคลึงกัน แท้จริงแล้วอาจซ่อนความเป็นไปได้ที่แตกต่างกันไว้.」เสียงกระดิ่งหัวเราะแล้วก็ค่อยๆ ห่างหายไป."
  },
  Event_146285_Name = {
    Text = "การตอบสนองแบบพาฟลอฟ"
  },
  Event_146286_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146286_Desc = {
    Text = "หากความดีได้รับรางวัลและความชั่วได้รับโทษคือความยุติธรรม แล้วใครเล่าจะเป็นผู้ตัดสินความดีและความชั่ว?\nจะให้ตาชั่งของอนูบิสนั้นหรือ?\nหากแรงโน้มถ่วงในยมโลกเป็นไปตามหลักฟิสิกส์ เจ้าก็ไม่ค่อยมั่นใจนักว่าหัวใจของตัวเองจะเบากว่าขนนกนั้น."
  },
  Event_146286_Name = {
    Text = "ความยุติธรรมที่ไร้สาระ"
  },
  Event_146287_ChoiceDesc1 = {
    Text = "【ซักถามต่อ】รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146287_ChoiceDesc2 = {
    Text = "【นิ่งเงียบ】รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146287_ChoiceDesc3 = {
    Text = "【ขอโทษ】รับ 25 รอยดำ"
  },
  Event_146287_Desc = {
    Text = "「รุ่นพี่วิลเลียม ตอนที่ทุกคนถูกเวนดิโกหลอกลวง ดูเหมือนพี่จะเป็นคนแรกที่ตื่นขึ้นมาได้ ต่อไปก็จะต้องเผชิญหน้ากับฝูงเวนดิโกโดยตรงแล้ว มีเคล็ดลับอะไรจะบอกบ้างไหม?」\nดวงตาของวิลเลียมกระเพื่อมเล็กน้อย จากสายตาของเขาเจ้าแอบเห็นความงุนงงที่จับต้องไม่ได้ ความเศร้าและความสงบ.\nดั่งการจมอยู่ในน้ำทะเลที่มีแสงส่องผ่าน ล่องลอยตกลงสู่ก้นทะเลที่มืดมิด.\n「ขอโทษ กลัวว่าฉันจะไม่มีอะไรช่วยได้」"
  },
  Event_146287_Name = {
    Text = "การจมอย่างอ่อนโยน"
  },
  Event_146288_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146288_Desc = {
    Text = "「ไร้ซึ่งความเป็นมนุษย์, ไร้ซึ่งความเป็นมนุษย์จริงๆ.」เงาดำส่ายหัวปรากฏขึ้น, 「ความจริงอาจเป็นยาพิษที่แทงทะลุกระดูก. บางครั้ง, การยอมรับภาพลวงตาช่วยรักษาความสุขในปัจจุบันได้ดีกว่า, มิใช่หรือ?」"
  },
  Event_146288_Name = {
    Text = "แมวดำย่องเดิน"
  },
  Event_146290_ChoiceDesc1 = {
    Text = "【ใครคือฆาตกร】ติดเชื้อ「(Skill.Arg1)」, การ์ดสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg2)」"
  },
  Event_146290_ChoiceDesc2 = {
    Text = "【เป็นความผิดของฉัน】ติดเชื้อ「(Skill.Arg1)」, การ์ดสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg2)」"
  },
  Event_146290_ChoiceDesc3 = {
    Text = "【ราคาที่ต้องจ่ายของความตะกละ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_146290_Desc = {
    Text = "「หนูน้อย, คลานไปเรื่อยๆ. ท่อระบายน้ำ, มืดและยาว. จู่ๆ ก็ได้กลิ่นชีสหอมฟุ้ง.」\n「หนูน้อย, ลากชีส, วิ่งกลับบ้าน. หัวอื้ออื้อ, หัวอื้ออื้อ.」\n「ผลักประตูเปิด, ผลักประตูเปิด, ในบ้านเงียบสงัด.」\n「พี่น้องนอนอยู่บนพื้น, ท้องทุกคนมีรู, มีรูอยู่รู.」"
  },
  Event_146290_Name = {
    Text = "หนูตะกละ"
  },
  Event_146291_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146291_Desc = {
    Text = "เจ้าย่อตัวลง, เช็ดรอยน้ำตาบนแก้มของเธอ, โดยไม่ถามว่าน้ำตานั้นจริงหรือปลอม.\n「ไม่ว่าจะจริงหรือปลอม,」เจ้าพูด, 「ไม่จำเป็นต้องพิสูจน์ให้ใครเห็น.」\nคาราบูขยับปาก, คำพูดเสียดสีที่เตรียมไว้เพื่อ얼버울ยาไม่ออกมาในที่สุด.\nน้ำตาของเธอไหลออกมาโดยไม่มีสัญญาณเตือน, หยดลงบนหลังมือของเจ้า."
  },
  Event_146291_Name = {
    Text = "น้ำตาจอมปลอม"
  },
  Event_146292_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146292_Desc = {
    Text = "「ไม่ต้องถามดีกว่านะ. บางคำถามไม่จำเป็นต้องรู้คำตอบ.」"
  },
  Event_146292_Name = {
    Text = "หนูตะกละ"
  },
  Event_146293_ChoiceDesc1 = {
    Text = "【พูดเตือน】รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146293_ChoiceDesc2 = {
    Text = "【ฟังต่อไป】ผู้ปลุกตื่นทุกคนตอบกลับ 50 อาลีมัส ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_146293_ChoiceDesc3 = {
    Text = "【ยักไหล่เพิกเฉย】รับตราประทับแบบเลือก 1 จาก 3"
  },
  Event_146293_Desc = {
    Text = "ดินแดนที่นารากาตกลงมานั้นมีแต่ความมืด.\nท่วงทำนองชื้นแฉะลอยมาจากโคลนตม ดั่งมือเย็นชาซีดเซียวที่ลูบไล้แก้มของเจ้าอย่างอ่อนโยน.\nมันร้องเบาๆ ว่า 「มาเถิด มาหาฉันในความเงียบสงัดของราตรี」"
  },
  Event_146293_Name = {
    Text = "เสียงแห่งความอาลัย"
  },
  Event_146294_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146294_Desc = {
    Text = "คุณก้มหัวลง, ปล่อยให้ควันนั้นทำให้รูปร่างของโพลลักซ์เลือนราง, พร้อมกับสีหน้าของเขาในขณะนั้น, ซ่อนทุกอย่างไว้ในหมอกสีเทาขาว.\nแบบนี้ปลอดภัยที่สุด——คุณบอกตัวเอง, ไม่จำเป็นต้องมอง, ไม่จำเป็นต้องคิด.\nเสียงบรรยายของจูเลียตยังคงไหลอยู่ในหู, คุณจ้องมองมือที่ประสานกันของตัวเองอย่างแน่วแน่, ไม่พูดสักคำ.\nจนกระทั่งเสียงระฆังแห่งพิธีกรรมดังขึ้น, คุณจึงกล้ายกตาขึ้นมองอีกครั้ง.\nและโพลลักซ์ยังคงรักษาท่าทีอันศรัทธาของเขาไว้ตลอด.\nคั่นด้วยกาลเวลาอันยาวนานและจินตนาการ, คุณไม่แน่ใจว่ามีบางอย่างหลุดลอยไปในช่วงเวลานั้นหรือเปล่า."
  },
  Event_146294_Name = {
    Text = "ความฝันเก่า III"
  },
  Event_146295_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146295_Desc = {
    Text = "「โพลลักซ์——」เสียงของคุณเพิ่งพุ่งออกจากลำคอก็ถูกกลืนกลับลงไปอย่างแน่วแน่, เหลือเพียงเสียงลมบางๆ ที่กระจายไปในควันธูป.\nเสียงสวดของผู้ศรัทธาข้างๆ ไม่ได้หยุดชะงัก, แต่มีสายตาหลายคู่ค่อยๆ กวาดมาอย่างไม่เป็นที่สังเกต.\nโพลลักซ์ตัวแข็งทื่อขึ้นอย่างฉับพลัน, ความตื่นตระหนกแวบขึ้นในดวงตา, แล้วก็ถูกปิดทับด้วยสีหน้าอ่อนน้อมที่ฝึกมาอย่างรวดเร็ว.\nเขาไม่ตอบสนอง, เพียงแต่ก้มตาลง, แต่ปลายนิ้วกลับค่อยๆ กำแน่นอยู่ในแขนเสื้อ——คุณรู้ว่า, เขาได้ยิน."
  },
  Event_146295_Name = {
    Text = "ความฝันเก่า III"
  },
  Event_146297_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146297_Desc = {
    Text = "อย่างน้อยในขณะนั้น เจ้าทำไม่ได้ที่จะยืนดูเธอถูกขับออกจากทีมคนเดียว.\nปัญหาที่ต้องแก้ไขในตอนนี้ ก็ฝากไว้กับตัวเองในตอนนี้แล้วกัน."
  },
  Event_146297_Name = {
    Text = "แผนซ้อนแผน"
  },
  Event_146298_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146298_Desc = {
    Text = "「โพลลักซ์, เราควรเดินไปคนละทิศทางกัน. แบบนี้ เราจะมีโอกาสมากขึ้นในการหาขอบป่า.」\n「แล้วพี่จะหาฉันเจอได้ยังไงล่ะ พี่ชาย?」\nผ่านม่านหมอกแห่งกาลเวลา เธอมองเห็นสีหน้าหม่นหมองของเขา. ความเจ็บปวดบีบรัดหัวใจเธอ. เธอหายใจเข้าลึกๆ แล้วค่อยๆ ปล่อยออก.\n「เราเป็นคู่แฝด. เราอ่านจังหวะหัวใจของกันและกันได้.」\n「เราจะไม่มีวันพรากจากกัน.」"
  },
  Event_146298_Name = {
    Text = "ความฝันเก่า I"
  },
  Event_146299_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146299_Desc = {
    Text = "มันกำลังพิพากษา มันกำลังตั้งคำถาม. มันประทานความตายอันเย็นชาแก่ผู้ท้าทายทุกคนที่ไม่มีวันกลับ."
  },
  Event_146299_Name = {
    Text = "การพิพากษาแห่งเส้นหิมะ"
  },
  Event_146300_ChoiceDesc1 = {
    Text = "【เริ่มต้นใหม่】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146300_ChoiceDesc2 = {
    Text = "【มันยากเย็นนัก】รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146300_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_146300_Desc = {
    Text = "หนอนสอนเธอเรื่องการโกหก.\nนอกจากนั้น, เธอไม่เคยเรียนรู้วิธีการมีชีวิตอยู่เลย.\nแต่การโกหกก็ยังคงเป็นแค่การโกหก, ตั้งแต่วันหนึ่ง, เจ้าต้องดำรงชีวิตต่อไปโดยปราศจากมันค้ำจุน."
  },
  Event_146300_Name = {
    Text = "มายาหรือความจริง"
  },
  Event_146301_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146301_Desc = {
    Text = "「ใช่แล้ว, แต่หนูตัวเล็กขนาดนั้น จะรู้ได้อย่างไรว่าราคาที่ต้องจ่ายของความตะกละคืออะไร?」"
  },
  Event_146301_Name = {
    Text = "หนูตะกละ"
  },
  Event_146302_ChoiceDesc1 = {
    Text = "【ผูกเชือกแดง】ลบการ์ดคำสั่ง 1 ใบ，รับรอยดำ Arg1"
  },
  Event_146302_ChoiceDesc2 = {
    Text = "【ปฏิเสธเชือกแดง】คัดลอกการ์ดคำสั่ง 1 ใบ，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_146302_ChoiceDesc3 = {
    Text = "【กลับสู่ความเป็นจริง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_146302_Desc = {
    Text = "ความฝันแรก. ความฝันในป่า. เด็กสองคนที่อายุไม่ถึงสิบขวบ ถูกหัวหน้าลัทธิทอดทิ้งไว้ในป่าลึกมืดมิด.\n「หลังจากค่ำคืนมาถึง บรรดาสัตว์ร้ายที่หลับใหลก็จะเริ่มออกล่า. หนีออกไปให้ได้ก่อนนั้นนะ. คนที่หนีออกไปได้ ถึงจะเป็นลูกที่ดีของข้า.」\nน้องชายจับมือเขาไว้ แล้วหยิบเชือกแดงสั้นๆ ออกมา.\n「พี่ชาย, ผูกมือเราไว้ด้วยกันเถอะนะ. แบบนี้ เราจะได้ไม่พลัดหลงกัน.」"
  },
  Event_146302_Name = {
    Text = "ความฝันเก่า I"
  },
  Event_146304_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146304_Desc = {
    Text = "คุณได้ยินเสียงหัวเราะคิกคัก.\nเสียงแห่งความยินดี, การยั่วยุ, เต็มไปด้วยความสนุกสนาน.\nการสำรวจจักรวาลที่มนุษย์ทุ่มเทสุดกำลัง, ในสายตาของพวกท่าน ไม่ต่างอะไรจากการปีนป่ายของมด."
  },
  Event_146304_Name = {
    Text = "ผู้ถูกมองข้าม"
  },
  Event_146306_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146306_Desc = {
    Text = "มันจะชำระล้าง. มันจะละลาย. มันจะรับนักปีนเขาทุกคนที่ไม่มีวันกลับเข้าสู่อ้อมอก."
  },
  Event_146306_Name = {
    Text = "การพิพากษาแห่งเส้นหิมะ"
  },
  Event_146307_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146307_Desc = {
    Text = "เธอและอีกาต่างตกอยู่ในภาวะชะงักงัน.\nเป็นที่ประจักษ์ชัดว่า ในการเผชิญหน้าครั้งนี้ เธอไม่มีทางเป็นผู้ชนะในที่สุดได้.\nในการต่อสู้กับจูเลียต พวกเธอดูเหมือนจะไม่มีวันเป็นเช่นนั้นได้เลย."
  },
  Event_146307_Name = {
    Text = "ความฝันเก่า II"
  },
  Event_146308_ChoiceDesc1 = {
    Text = "【ใครกำลังมองฉัน?】สุ่มปลุกตื่นผู้ปลุกตื่น 1 คน ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_146308_ChoiceDesc2 = {
    Text = "【มุ่งสนใจสิ่งตรงหน้า】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_146308_Desc = {
    Text = "ลมที่พัดพาหิมะและน้ำแข็งโหมกระหน่ำผ่านจุดสูงสุดที่รอยเท้ามนุษย์เคยเหยียบ.\nคุณเงยหน้ามอง, สูงขึ้นไปมีเพียงดวงอาทิตย์ที่ไม่เคยดับสูญมาแต่กาลก่อน.\nแต่คุณรู้ว่า, ในที่ไกลและสูงกว่านั้น, ยังมีดวงตานับไม่ถ้วน, บ้างเปิด, บ้างปิด.\nในจำนวนนั้น, มีอยู่หลายคู่ที่กำลังมองลงมายังโลกทั้งใบใต้เท้าของคุณอย่างเงียบสงบ."
  },
  Event_146308_Name = {
    Text = "ผู้ถูกมองข้าม"
  },
  Event_146309_ChoiceDesc1 = {
    Text = "【ข้ายังอาลัย】รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146309_ChoiceDesc2 = {
    Text = "【ข้าลืมเลือนแล้ว】การ์ด 1 ใบแบบสุ่มรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_146309_Desc = {
    Text = "เจ้าพยายามปิดกั้นโมดูลที่เก็บ「ความทรงจำ」ในสมอง.\nในกล่องลับนั้นซ่อนคำตอบที่ประกอบขึ้นเป็นตัวเจ้าทั้งหมด, ความคิดทุกอย่างที่เจ้าละอายใจ, จินตนาการทุกอย่างที่เจ้าไม่อยากให้ใครรู้.\nแต่ความปรารถนาคือคำสาปของจิตใต้สำนึก, ความหลงใหลในฝันที่เจ้าต้านทานไม่ได้."
  },
  Event_146309_Name = {
    Text = "คำสาปจิตใต้สำนึก"
  },
  Event_146310_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146310_Desc = {
    Text = "วิลเลียมหลบสายตาของเจ้า.\n「จิตสำนึกคืออาวุธในการต่อต้านการหลอกลวง และประสบการณ์ชีวิตของแต่ละคนกำหนดจิตสำนึกของเขา ไม่สามารถทดแทนหรือถ่ายทอดได้」\n「สิ่งเดียวที่ฉันบอกได้คือ อย่าปล่อยให้ตัวเองถูกความอ่อนแอกลืนกิน」"
  },
  Event_146310_Name = {
    Text = "การจมอย่างอ่อนโยน"
  },
  Event_146311_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146311_Desc = {
    Text = "「ฟังออกแล้ว, เธอเป็นคนประเภทที่อยากเป็นนักปรัชญา. แต่อย่าลืมว่า ไม่มีความคาดหวัง ไม่ได้แปลว่าไม่มีความเจ็บปวด.」เสียงกระดิ่งหัวเราะแล้วก็ค่อยๆ ห่างหายไป."
  },
  Event_146311_Name = {
    Text = "การตอบสนองแบบพาฟลอฟ"
  },
  Event_146312_ChoiceDesc1 = {
    Text = "【Leave】การติดเชื้อ「(Skill.Arg1)」 ได้รับ 50 รอยดำ"
  },
  Event_146312_Desc = {
    Text = "「หิวจัง, หิวจัง.」\nภูเขาร้องไห้คร่ำครวญ, ภูเขาโหยหวน.\nภูเขาทนไม่ไหว, ท้องของมันว่างเปล่า."
  },
  Event_146312_Name = {
    Text = "ความลับของภูเขา"
  },
  Event_146313_ChoiceDesc1 = {
    Text = "【เตะผนังหิน】ลบการ์ดคำสั่ง 1 ใบ และตอบกลับ Arg1 จุด HP"
  },
  Event_146313_ChoiceDesc2 = {
    Text = "【คว้าเชือกนิรภัย】รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146313_Desc = {
    Text = "ภาพหลอนหลากสีสันวนเวียนอยู่ในความคิดของคุณ.\nเริ่มต้นด้วยผงหิมะที่ร่วงหลุด.\nตามด้วยชายคาหิมะที่พังทลาย.\nคุณไม่อาจหยุดตัวเองจากการลื่นไถล, เชือกนิรภัยก่อประกายไฟอันจ้าตาจากแรงเสียดทานที่ตะขอ.\nแต่เมื่อเผชิญกับเทือกเขา, มันช่างเล็กน้อยและเปราะบางเสียเหลือเกิน."
  },
  Event_146313_Name = {
    Text = "ร่วงหล่นอย่างเงียบงัน"
  },
  Event_146314_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146314_Desc = {
    Text = "「มาหาฉันในความฝันเถิด ให้ฉันได้มีชีวิตอีกครั้ง」\nเครื่องเล่นแผ่นเสียงส่งเสียงคร่ำครวญ แล้วเสียงหายใจก็ค่อยๆ เลือนหายไปในความมืด.\nเหลือเพียงเสียงสะท้อน. มีแต่เสียงสะท้อน."
  },
  Event_146314_Name = {
    Text = "เสียงแห่งความอาลัย"
  },
  Event_146315_ChoiceDesc1 = {
    Text = "【เกิดความสำนึกผิด】รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_146315_ChoiceDesc2 = {
    Text = "【ทุกอย่างเป็นการจัดสรรของชะตากรรม】รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146315_Desc = {
    Text = "เจ้ารู้มาตลอดว่าการเดินทางครั้งนี้ไม่ง่ายอย่างที่คิด และนักปีนเขาส่วนใหญ่ในทีมนี้ต่างก็มีวาระซ่อนเร้น.\nแต่เมื่อเจ้ามองดูใบหน้าหัวเราะอย่างหยิ่งยโสของคาราบูที่กำลังค่อยๆ คลั่งไคล้ ก็ยังมีเสียงแก้วแตกดังขึ้นในอกของเจ้า.\nบางทีตอนที่นารากาจะขับเธอออกจากทีม เจ้าควรจะเลือกทางอื่น."
  },
  Event_146315_Name = {
    Text = "แผนซ้อนแผน"
  },
  Event_146316_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146316_Desc = {
    Text = "มีผู้คนมากเพียงใดที่ถูกกลืนกินที่นี่?\nห้วงลึกเหนียวหนืดยื่นมือสีดำออกมา พยายามดึงเจ้าเข้าสู่โลกของพวกเขา.\nแต่เจ้าเดินหน้าต่อไป และดูเหมือนพวกมันก็ไม่ได้ตั้งใจจะรั้งไว้ ต่างถอยร่นไปทีละคน.\nยังมียอดเขารออยู่ข้างหน้า."
  },
  Event_146316_Name = {
    Text = "เสียงแห่งความอาลัย"
  },
  Event_146317_ChoiceDesc1 = {
    Text = "【ยอมแพ้】รับ 25 รอยดำ"
  },
  Event_146317_ChoiceDesc2 = {
    Text = "【โน้มตัวดู】รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146317_Desc = {
    Text = "ตามสายตาของทิงค์ เจ้าอดไม่ได้ที่จะจ้องมองก้นทะเลสาบ.\nมีอะไรในภาพสะท้อนนั้นที่ดึงดูดเธออยู่?\nแต่เจ้ามองไม่ชัด บนผิวน้ำแข็งมีเพียงเงาของเจ้าเองที่สะท้อนอยู่อย่างเลือนราง."
  },
  Event_146317_Name = {
    Text = "เงาสะท้อนใต้ทะเลสาบ"
  },
  Event_146318_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146318_Desc = {
    Text = "วิธีเดียวที่จะต้านทานการกลืนกินคือการสละทิ้ง.\nไม่มีใครสูญเสียสิ่งที่ตนเองไม่เคยมีได้.\nเวนดิโกขบฟันส่งเสียงคำรามอย่างไม่ยอมแพ้ในลำคอ, ถอยกลับเข้าหมอกทีละก้าว."
  },
  Event_146318_Name = {
    Text = "คำสาปจิตใต้สำนึก"
  },
  Event_146319_ChoiceDesc1 = {
    Text = "【หิมะจะชำระล้างฉัน】สุ่มเพิ่มคุณภาพตราประทับของการ์ด 1 ใบ"
  },
  Event_146319_ChoiceDesc2 = {
    Text = "【หิมะจะพิพากษาฉัน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146319_Desc = {
    Text = "ข้างหน้าคือการปีนป่ายครั้งสุดท้าย แนวหิมะเย็นชาและทอดยาวสุดสายตา.\nหิมะขาวจนแสบตา แม้แต่ความตายที่นี่ก็ดูสะอาดบริสุทธิ์."
  },
  Event_146319_Name = {
    Text = "การพิพากษาแห่งเส้นหิมะ"
  },
  Event_146320_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146320_Desc = {
    Text = "อย่าละเลยรายละเอียดใดๆ ในภาพนั้น.\nจารึกมันลงในความทรงจำ.\nจารึกความงุนงง, ความว่างเปล่า และความเจ็บปวดที่ตามมาในขณะนั้นลงไปด้วย.\nอย่าลืมมันเป็นอันขาด."
  },
  Event_146320_Name = {
    Text = "มาจากฝั่งโน้น"
  },
  Event_146321_ChoiceDesc1 = {
    Text = "【ร่วมรบด้วยกัน】รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_146321_ChoiceDesc2 = {
    Text = "【ปลอบประโลม】รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146321_Desc = {
    Text = "ยอดเขาสั่นสะเทือนอย่างรุนแรง, ดั่งสิ่งมีชีวิตที่กำลังจะสิ้นใจ.\nเนื้อขาวซีดเป็นปล้องๆ พุ่งทะลักออกมาจากใต้ชั้นหินที่แตกร้าว, ยืดสูงขึ้นทีละปล้อง, พันกันจนโยนคาราบูลงมาอย่างรุนแรง.\nเมื่อเธอปรากฏตัวต่อหน้าพวกเจ้าอีกครั้ง, แก้มของเธอมีรอยน้ำตาไหลอยู่แล้ว.\nนั่นคือรอยน้ำตาแห่งความเจ็บปวดหรือ?\nเจ้าไม่แน่ใจ.\nคำโกหกนับไม่ถ้วนเคยออกมาจากปากของเธอ, ใครจะยังเชื่อน้ำตาจระเข้อีก?"
  },
  Event_146321_Name = {
    Text = "น้ำตาจอมปลอม"
  },
  Event_146322_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146322_Desc = {
    Text = "เจ้าไม่ได้ไปถามหาคำตอบ, เพียงแต่ก้าวมายืนข้างๆ เธอ.\n「ลุกขึ้นเถิด,」เจ้าพูด, 「การแสดงยังไม่จบ, อย่าถอนตัวกลางคัน.」\nคาราบูตะลึงอยู่ครู่หนึ่ง, แล้วก็เช็ดหน้าอย่างแรง.\nเธอลุกขึ้นอย่างโซเซ, กำอาวุธไว้แน่นอีกครั้ง, เดินเคียงบ่าเคียงไหล่เผชิญหน้ากับปากอ้าอันมหึมาที่หุบลงมาอีกครั้ง.\nโกหกมามากเกินไป, จนแม้แต่ตัวเธอเองก็แทบแยกไม่ออกว่าน้ำตาหยดไหนจริงหรือปลอม.\nแต่อย่างน้อยครั้งนี้, ไม่มีใครคิดคำนวณความจริงหรือเท็จ."
  },
  Event_146322_Name = {
    Text = "น้ำตาจอมปลอม"
  },
  Event_146323_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146323_Desc = {
    Text = "「ฟังออกแล้ว, เธอเป็นคนประเภทที่ถนัดทลายปรากฏการณ์ภายนอก. แต่อย่าลืมว่า ในความเป็นจริงของช่วงเวลานั้น อาหารมีอยู่เพียงในประสบการณ์และจินตนาการของเธอเท่านั้น.」เสียงกระดิ่งหัวเราะแล้วก็ค่อยๆ ห่างหายไป."
  },
  Event_146323_Name = {
    Text = "การตอบสนองแบบพาฟลอฟ"
  },
  Event_146324_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146324_Desc = {
    Text = "เธอเบาและชะลอฝีเท้าลง.\nเบาๆ, ช้าๆ, เงียบสนิท...\nเธอก็แอบหลบเลี้ยวผ่านมุมถัดไปหายไปได้.\nแล้วอีกาตัวนั้นได้ตามทันมาหรือเปล่า?\nเธอจำไม่ได้แล้ว."
  },
  Event_146324_Name = {
    Text = "ความฝันเก่า II"
  },
  Event_146325_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146325_Desc = {
    Text = "ท่วงทำนองหยุดลงอย่างกะทันหัน.\nดวงตาคู่หนึ่งที่เต็มไปด้วยความโหยหาเปิดขึ้นในหล่มโคลนสีดำ.\nดวงตาคู่นั้นจ้องมองเจ้าอย่างชุ่มฉ่ำ กระซิบสิ่งที่เจ้าแทบจะแยกแยะไม่ออก.\nแล้วก็ค่อยๆ ปิดลง... ช้าๆ ช้ามาก."
  },
  Event_146325_Name = {
    Text = "เสียงแห่งความอาลัย"
  },
  Event_146326_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146326_Desc = {
    Text = "คุณไม่ได้หยุดอยู่นาน, ทิ้งทำนองนั้นไว้เบื้องหลัง, ก้าวเท้าย่ำหิมะที่สะสมอยู่ดังเสียงเร่งรีบกว่าเสียงลม.\nแต่ไม่ว่าคุณจะเดินเร็วแค่ไหน, เสียงดนตรีอันโศกเศร้านั้นก็ยังคงติดตามคุณมาอย่างไม่ยอมห่าง.\nคุณหนีไม่พ้น——มันคือลมหายใจของเทือกเขาหิมะแห่งนี้, และคุณ, เป็นเพียงผู้ฟังตัวเล็กๆ ที่บังเอิญผ่านมา."
  },
  Event_146326_Name = {
    Text = "เพลงมนต์แห่งธรรมชาติ"
  },
  Event_146327_ChoiceDesc1 = {
    Text = "【จงรับฟังเถิด】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146327_ChoiceDesc2 = {
    Text = "【ไม่ต้องใส่ใจ】สำหรับผู้ปลุกตื่นแต่ละคนที่มีค่าอาลีมัส 50 ขึ้นไป จะได้รับรอยดำ 15"
  },
  Event_146327_ChoiceDesc3 = {
    Text = "【บังคับออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_146327_Desc = {
    Text = "ในสายลมมีเสียงร้องเพลงที่แว่วมาแต่ไกล.\nเสียงเพลงราวกับมาจากทุกทิศทาง, หรือจากใต้พื้นดิน.\nไม่ว่าคุณจะหันไปทางไหนเพื่อตามหามัน, มันก็ก้องอยู่ในหูด้วยความเข้มข้นเดิม."
  },
  Event_146327_Name = {
    Text = "บทเพลงแห่งทะเลสาบน้ำแข็ง"
  },
  Event_146328_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146328_Desc = {
    Text = "「ดาวมรณะเอ๋ย, บัดนี้มิใช่เวลาของเจ้าที่จะส่องแสง.」\n「การเดินทางของข้ายังมีจุดหมายที่ยังไม่ถึง.」\n「ขอเจ้าจงดับแสงลงชั่วคราว, เพื่อให้ท้องฟ้าคืนคืนนี้กลับสู่ความสงบ.」"
  },
  Event_146328_Name = {
    Text = "ลางมรณะใกล้มาถึง"
  },
  Event_146329_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146329_Desc = {
    Text = "ความเสียใจที่ไร้ประโยชน์พลุ่งขึ้นมา.\nคนเราต้องจำยอมเก็บกวาดความยุ่งเหยิงที่ตัวเองในอดีตทิ้งไว้เสมอ."
  },
  Event_146329_Name = {
    Text = "แผนซ้อนแผน"
  },
  Event_146330_ChoiceDesc1 = {
    Text = "【เคี้ยว】ปลุกตื่นผู้ถูกปลุกสุ่ม 1 ตน, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_146330_ChoiceDesc2 = {
    Text = "【ปฏิเสธ】ได้รับสูงสุด 3 ออริซอน"
  },
  Event_146330_Desc = {
    Text = "ในห้วงลึกของหมอกหิมะ มีร่างกายที่ผอมโซจนกระดูกโผล่ซุ่มอยู่, ซี่โครงค้ำยันถุงหนังที่แห้งแตก, เขาสองข้างที่แห้งกิ่งดั่งกิ่งไม้ตายแทงทะลุหมอก.\nท้องของมันส่งเสียงครวญครางอันว่างเปล่า.\nในขณะที่เจ้าสบตากับมัน, ในเบ้าตาที่ลึกหลุมนั้นก็ปั่นป่วนด้วยภาพที่แตกสลาย——นั่นคือความทรงจำของเจ้า. มันได้ลิ้มรสแล้ว.\n「ยังไม่พอ, ยังไม่พอเลย...」มันครวญเสียงแหบ, เหยียดมือแห้งแล้งออกมาหาเจ้า, ท่าทางนั้นแฝงไว้ซึ่งการวิงวอน."
  },
  Event_146330_Name = {
    Text = "ผู้ตะกละ"
  },
  Event_146332_ChoiceDesc1 = {
    Text = "【ฝังศพสวรรค์】รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_146332_ChoiceDesc2 = {
    Text = "【ขับไล่】ได้รับ 75 ตราดำ, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146332_Desc = {
    Text = "แร้งเครา Lammergeier ร่อนวนอยู่บนฟ้าสูงด้วยกระแสลมอุ่น, ลาดตระเวนอาณาเขต.\nในหมู่นักปีนเขา, นี่ถือเป็นลางร้ายมาโดยตลอด.\n「พวกมันกำลังหาอาหาร. แร้งสามารถดมกลิ่นความตายที่ใกล้เข้ามาได้.」"
  },
  Event_146332_Name = {
    Text = "ลางมรณะใกล้มาถึง"
  },
  Event_146333_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146333_Desc = {
    Text = "เชื่อมั่นในสองขาของตัวเอง.\nเจ้าจะพิชิตยอดสูงสุดได้."
  },
  Event_146333_Name = {
    Text = "แตะถึงจุดสูงสุด"
  },
  Event_146334_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146334_Desc = {
    Text = "ในขณะที่ความคิดอาลัยอาวรณ์พุ่งขึ้นมาในสมอง, เจ้าก็ตระหนักว่าตนเองไม่มีแรงต้านทานอีกต่อไปแล้ว, ได้แต่ยอมให้มันบุกเข้าสู่คลังความทรงจำที่ถูกปิดผนึกมานานของเจ้า.\nเขี้ยวขาวซีดแทงเข้าขมับของเจ้า, ภาพทีละเฟรมถูกถอนรากถอนโคน."
  },
  Event_146334_Name = {
    Text = "คำสาปจิตใต้สำนึก"
  },
  Event_146335_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146335_Desc = {
    Text = "มันโน้มตัวเข้าหาเจ้า, ปลายจมูกแทบจะแตะหน้าผากของเจ้า, มันหลงใหลอย่างลึกซึ้ง ราวกับกำลังดมกลิ่นน้ำตาล.\nอารมณ์ที่ปั่นป่วนเหล่านั้นถูกเลียกินจนหมดสิ้น.\nมันฮัมเพลงอย่างพึงพอใจแล้วถอยออกไป, ดวงตาเปล่งแสงยั่วยวน.\nหัวใจของเจ้าว่างเปล่าไปส่วนหนึ่ง, แต่กลับรู้สึกแปลกประหลาด...โล่งขึ้นมาก."
  },
  Event_146335_Name = {
    Text = "ผู้ตะกละ"
  },
  Event_146336_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146336_Desc = {
    Text = "「ระวังเท้าด้วย, ย่ำให้มั่นทุกก้าว,」เสียงของนารากาดังขึ้นข้างหู, 「อย่าหวังพึ่งคนอื่นมารองรับคุณตลอดเวลา.」"
  },
  Event_146336_Name = {
    Text = "ผู้ถูกมองข้าม"
  },
  Event_146337_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146337_Desc = {
    Text = "มนุษย์ควรได้สัมผัสท้องฟ้า.\nเป้าหมายทำให้ลืมความอันตราย.\nท้องฟ้ากว้างใหญ่กำลังรอคอยเจ้าอยู่เบื้องบน."
  },
  Event_146337_Name = {
    Text = "แตะถึงจุดสูงสุด"
  },
  Event_146338_ChoiceDesc1 = {
    Text = "【ขับไล่ความทรงจำ】รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146338_ChoiceDesc2 = {
    Text = "【ดักจับภาพลวงตา】รับสิ่งประดิษฐ์ทองคำ 1 ใบจาก 3 ตัวเลือก，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_146338_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_146338_Desc = {
    Text = "ฆาตกรผู้สังหารวิลเลียม, บัดนี้อยู่ต่อหน้าเจ้า.\nภายในเต็นท์ของอาลัน, ในอากาศที่น่าขยะแขยง, ใบหน้าซีดเซียวของวิลเลียม, ร่างกายที่ลอยอยู่, และโคมไฟเล็กที่ถูกผ่าชำแหละบนโต๊ะ, ผุดขึ้นมาในความทรงจำของเจ้าอีกครั้ง."
  },
  Event_146338_Name = {
    Text = "มาจากฝั่งโน้น"
  },
  Event_146339_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146339_Desc = {
    Text = "เชือกนิรภัยขาดสะบั้น.\nคุณกระแทกลงในกองหิมะอย่างหนัก, อวัยวะภายในส่งสัญญาณเตือนถึงอันตรายท่ามกลางความเจ็บปวดทื่อๆ.\nฝืนเปิดตาท่ามกลางอาการวิงเวียน, โครงกระดูกนิรนามจ้องมองคุณอยู่.\nในดวงตาที่ว่างเปล่าของมัน, มีบางอย่างกำลังระยิบระยับ."
  },
  Event_146339_Name = {
    Text = "ร่วงหล่นอย่างเงียบงัน"
  },
  Event_146340_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146340_Desc = {
    Text = "หนีไม่พ้นแล้ว.\nเธอกัดฟัน แล้วพุ่งตัวออกวิ่งอย่างรวดเร็ว หวังจะใช้ความเร็วเขย่าผู้เฝ้าติดตามให้หลุดออกไป.\nอีกาส่งเสียงร้องแหบแห้ง กระพือปีก แล้วติดตามอยู่เหนือพวกเธออย่างสบายๆ แม้แต่จะวนเป็นวงกลมก็ยังทำได้อย่างง่ายดาย.\nความสิ้นหวังอันเย็นชาซึมเข้าสู่ร่างกายผ่านสายตาของมัน.\nพวกเธอหนีไม่รอดหรอก."
  },
  Event_146340_Name = {
    Text = "ความฝันเก่า II"
  },
  Event_146341_ChoiceDesc1 = {
    Text = "【ความดีความชั่วมีผล】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_146341_ChoiceDesc2 = {
    Text = "【ความเท่าเทียมอย่างแท้จริง】เพิ่ม Arg1 จุด Max HP ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_146341_Desc = {
    Text = "เจ้าแขวนอยู่บนหน้าผา แต่ในหัวกลับผุดคำถามที่ไม่เกี่ยวข้องขึ้นมา: ความยุติธรรมคืออะไร?"
  },
  Event_146341_Name = {
    Text = "ความยุติธรรมที่ไร้สาระ"
  },
  Event_146342_ChoiceDesc1 = {
    Text = "【Leave】การติดเชื้อ「(Skill.Arg1)」 ได้รับ 50 รอยดำ"
  },
  Event_146342_Desc = {
    Text = "「ฉันยังตายไม่ได้!」\nภูเขาร้องไห้คร่ำครวญ, ภูเขาโหยหวน.\nภูเขาทนไม่ไหว, มันสูญเสียความเป็นไปได้ของวันพรุ่งนี้เพราะความโลภ."
  },
  Event_146342_Name = {
    Text = "ความลับของภูเขา"
  },
  Event_146343_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_146343_Desc = {
    Text = "เจ้าก้มตัวลงจนแก้มแตะพื้นน้ำแข็ง.\nความหนาวเย็นที่แทงถึงกระดูกซึมผ่านผิวหนังเข้าสู่ไขกระดูก เจ้าอดไม่ได้ที่จะสั่นสะท้าน.\nบางสิ่งที่แยกแยะไม่ออกกำลังหมุนวนช้าๆ ใต้ชั้นน้ำแข็งที่แข็งตัว จะเป็นกระแสน้ำหรือสิ่งมีชีวิตบางอย่าง?\nไม่ว่าจะเป็นอะไร ก็ไม่เกี่ยวข้องกับการเดินทางของเจ้า."
  },
  Event_146343_Name = {
    Text = "เงาสะท้อนใต้ทะเลสาบ"
  },
  Event_148532_ChoiceDesc1 = {
    Text = "【รับพร】หลังจากการต่อสู้เริ่มต้น, สร้าง 「ผลแห่งการเปลี่ยนแปลง」แบบสุ่ม 1 ใบใส่ในสำรับไพ่."
  },
  Event_148532_Desc = {
    Text = "ทุ่งหิมะกว้างไกลสุดสายตา สายลมหนาวไม่อาจพัดพาเสียงใดมาได้ เงาลางเลือนที่ไม่อาจบอกได้ว่ามาจากไหนค่อยๆ ปรากฏขึ้น ยื่นผลไม้อุ่นๆ มาให้.\nกลิ่นหวานหอมปนหมอกโชยเข้าสู่รูจมูกที่แข็งชาของนักเดินทาง. \nดินแดนหิมะแห่งนี้ถูกความตายซึมซาบจนทั่ว อากาศเต็มไปด้วยกลิ่นเน่าเหม็นและความหนาวเย็นที่น่าขยะแขยง มีเพียงผลไม้เม็ดนี้ในอุ้งมือที่อวบอิ่มชุ่มฉ่ำ ดั่งคำสัญญาอันล่อตาล่อใจของหญิงสาว."
  },
  Event_148532_Name = {
    Text = "ภาพลวงตาเหนือขอบฟ้า"
  },
  Event_20778_ChoiceDesc1 = {
    Text = "【มอบให้เธอเถอะ】ทุกร่างกายที่ตื่นขึ้นฟื้นคืนพลังคลั่ง Arg1"
  },
  Event_20778_ChoiceDesc2 = {
    Text = "【ต้องการสนับสนุน】เลือก 2 ร่างกายที่ถูกปลุกให้ตื่นรู้"
  },
  Event_20778_Desc = {
    Text = "「นี่คือการติดต่อจากมหาวิทยาลัยมิซากะ ตรวจพบการเปลี่ยนแปลงของดัชนีนอร์สที่ผิดปกติในร่างกายที่ปลุกตื่น ต้องการสนับสนุนหรือไม่?」"
  },
  Event_20778_Name = {
    Text = "การสื่อสารสนับสนุน"
  },
  Event_20779_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_20779_Desc = {
    Text = "「ได้ให้ความช่วยเหลือฉุกเฉินแก่คุณแล้ว กรุณาตรวจสอบและกดเข็มกลัดสามครั้งเพื่อยืนยัน」"
  },
  Event_20779_Name = {
    Text = "การสื่อสารสนับสนุน"
  },
  Event_20780_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_20780_Desc = {
    Text = "ภาพลวงตาจากอนาคตอันไกลโพ้น ซ่อนตัวอยู่ในช่องเขาของเอลวอส。"
  },
  Event_20780_Name = {
    Text = "ภาพลวงตาของภูเขาไฟ"
  },
  Event_20781_ChoiceDesc1 = {
    Text = "【ภาพลวงตาแห่งการมองไกล】ร่างกายที่ตื่นขึ้นทั้งหมดฟื้นคืนความคลั่ง Arg1"
  },
  Event_20781_ChoiceDesc2 = {
    Text = "【ใกล้ภาพลวงตา】เลือกการตื่น 2 ร่างกายที่ตื่นขึ้น"
  },
  Event_20781_Desc = {
    Text = "ดูเหมือนไกลออกไปจะมีภูเขาไฟปะทุ ควันเป็นรูปมนุษย์พุ่งขึ้นในฟ้าลมร้าย \nที่นี่คือแอลวอร์ธ ที่แอลวอร์ธมีเพียงหิมะสูงตระหง่านและถ้ำหินปูนที่กัดเซาะอย่างไม่จบสิ้น \nหรือเหตุการณ์ประหลาดเป็นวันที่ทำให้จิตของเจ้าสับสนไปหรือเปล่า?"
  },
  Event_20781_Name = {
    Text = "ภาพลวงตาของภูเขาไฟ"
  },
  Event_20782_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_20782_Desc = {
    Text = "ภาพลวงตาโบกมือให้คุณแล้วหายไป ทิ้งไว้เพียงแค่หิมะที่หนาวเย็นและภูเขาที่สูงตระหง่าน。"
  },
  Event_20782_Name = {
    Text = "ภาพลวงตาของภูเขาไฟ"
  },
  Event_20783_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_20783_Desc = {
    Text = "「รับทราบ เราจะทำการส่งมอบทรัพยากรพื้นฐาน กรุณาตรวจสอบและรับทราบด้วย」"
  },
  Event_20783_Name = {
    Text = "การสื่อสารสนับสนุน"
  },
  Event_21398_ChoiceDesc1 = {
    Text = "【หยิบรูปภาพ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_21398_Desc = {
    Text = "เครื่องจักรถูกถอดแยกออก ความจริงถูกเปิดเผย\nชีวิตที่เต็มไปด้วยความวุ่นวายได้สลายหายไปอย่างไร้ร่องรอย ทิ้งไว้เพียงความพึงพอใจจากการทราบความจริงที่ชัดเจน。"
  },
  Event_21398_Name = {
    Text = "คำให้การของพยาน"
  },
  Event_21399_ChoiceDesc1 = {
    Text = "【หยิบรูปภาพ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_21399_ChoiceDesc2 = {
    Text = "【ตรวจสอบฟิล์ม】ติดเชื้อ「(Skill.Arg1)」，เปลี่ยนการแกะสลักที่ได้รับจากตัวเลือก 1 สามารถใช้งานได้อีกครั้งหนึ่ง"
  },
  Event_21399_Desc = {
    Text = "ความอยากรู้อยากเห็นผลักดันคุณให้หันไปมองที่บ่อน้ำพิมพ์\nภาพเหล่านั้นแช่อยู่ในน้ำยาสีแดงเข้ม และผู้กระทำผิดที่เต็มไปด้วยคราบสกปรกสีดำมีใบหน้าที่เหมือนกับคุณอย่างชัดเจน。"
  },
  Event_21399_Name = {
    Text = "คำให้การของพยาน"
  },
  Event_21400_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_21400_Desc = {
    Text = "เครื่องจักรถูกถอดออก ความจริงถูกเปิดเผย。\nชีวิตที่พลุกพล่านหายไปในความไร้รูปร่าง ทิ้งไว้ให้คุณได้พบกับความจริงที่ชัดเจน。"
  },
  Event_21400_Name = {
    Text = "คำให้การของพยาน"
  },
  Event_21811_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_21811_Desc = {
    Text = "“ยี่สิบห้าปี... ใช่ เธอทำให้ฉันหลับไปเป็นเวลายี่สิบห้าปี”\nสาวตอบคุณด้วยน้ำเสียงมืดมนและซึมเศร้า\nเพียงแค่ตื่นขึ้นมา คนรับใช้ที่ดูแลเธอตั้งแต่เด็ก กลับกลายเป็นผู้เหยียบทะเลอย่างเต็มตัวตามกาลเวลา\nไม่มีใครเข้าใจความทุกข์ของเธออีกต่อไป ไม่มีใครสนใจความเจ็บปวดของเธอ ทำให้เธออยู่โดดเดี่ยวในกลุ่มศาสนา\nเธอเลือกที่จะหลับไปในวันก่อนที่จะเกิดขึ้น นั่นคือ “เวลาที่ดวงดาวอยู่ในตำแหน่งปกติ”"
  },
  Event_21811_Name = {
    Text = "ชีวิตที่ถูกกักขัง"
  },
  Event_22058_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22058_Desc = {
    Text = "「ไม่ ฉันไม่ได้หิว。」\nคุณปฏิเสธคำเชิญอย่างสุภาพสำหรับงานเฉลิมฉลองนี้.\nราคาที่ต้องจ่ายเพื่อแย่งชิงจิตวิญญาณ คุณไม่เคยยินยอมที่จะจำนองในเรื่องนี้。"
  },
  Event_22058_Name = {
    Text = "การเฉลิมฉลองของร่างกาย"
  },
  Event_22059_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22059_Desc = {
    Text = "คุณกัดกินสกอนที่มีเลือดไหลออกมาอย่างไม่เป็นระเบียบ กลิ่นของหัวใจที่หมักด้วยพริกไทยและแป้งอบผสมกัน คุณได้กลิ่นที่คุ้นเคย。\n「การได้รับพละกำลังนั้นต้องแลกมาด้วยราคาที่ต้องจ่าย。」\nคุณดื่มเลือดสดคำสุดท้าย。"
  },
  Event_22059_Name = {
    Text = "การเฉลิมฉลองของร่างกาย"
  },
  Event_22060_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22060_Desc = {
    Text = "คุณกลืนซุปขาวและเนื้อสับลงไปอย่างรวดเร็ว เช็ดรอยที่มุมปากด้วยแขนเสื้อของคุณ\nเนื้อมีความนุ่มลื่น น้ำซุปมีกลิ่นหอม สำหรับมันเคยเป็นของใคร? \nเพียงแค่ยอดภูเขาน้ำแข็งของสิ่งที่คุณสูญเสียไปเท่านั้น。"
  },
  Event_22060_Name = {
    Text = "การเฉลิมฉลองของร่างกาย"
  },
  Event_22061_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22061_Desc = {
    Text = "คุณตรวจสอบตราประทับโบราณที่สลักอยู่บนกระดิ่งลมอย่างละเอียด \n พวกมันบิดเบือนในระดับที่คนธรรมดาไม่สามารถจินตนาการได้ ดูเหมือนว่าพวกมันไม่ได้ตั้งใจให้ใครเข้าใจ \n ไม่ถูกเข้าใจ ก็จะไม่ถูกรบกวน。"
  },
  Event_22061_Name = {
    Text = "ระฆังลมสนิม"
  },
  Event_22062_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22062_Desc = {
    Text = "「ดีมาก คุณระมัดระวัง」\nเสียงที่ห่างไกลดังขึ้นจากระฆังลม\n「ความระมัดระวังจะนำมาซึ่งรางวัลเล็กน้อย แต่ก็แค่นั้นแหละ」"
  },
  Event_22062_Name = {
    Text = "ระฆังลมสนิม"
  },
  Event_22063_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22063_Desc = {
    Text = "คุณลูบไปที่ตราประทับโบราณที่สลักอยู่บนกระดิ่งลม\nพวกมันบิดเบือนในระดับที่คนธรรมดาไม่สามารถจินตนาการได้ ดูเหมือนว่าพวกมันไม่ได้ตั้งใจให้ใครเข้าใจ\nไม่ถูกเข้าใจ ก็จะไม่ถูกรบกวน。"
  },
  Event_22063_Name = {
    Text = "ระฆังลมสนิม"
  },
  Event_22064_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22064_Desc = {
    Text = "「อา น่าเสียดายจริงๆ... งั้นฉันคงต้องเล่นเดี่ยวคนเดียวต่อไป」 คุณไม่รู้ว่าเมื่อไหร่ที่กีตาร์และมือหายไป แต่เสียงกีตาร์ที่ไหลเหมือนสายน้ำจะอยู่ในใจของคุณตลอดไป。"
  },
  Event_22064_Name = {
    Text = "ผีข้างเปียโน"
  },
  Event_22065_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22065_Desc = {
    Text = "「อ้า การมีเพื่อนแบบนี้ ถือเป็นเกียรติอย่างยิ่ง!」 มือคู่นั้นตื่นเต้นขึ้นมา คุณไม่สามารถตามทันความเร็วของมันได้เลย จนกระทั่งการแสดงจบลงนานแล้ว เสียงที่กระตุ้นใจนั้นยังคงทำให้คุณรู้สึกตื่นเต้นอยู่。"
  },
  Event_22065_Name = {
    Text = "ผีข้างเปียโน"
  },
  Event_22175_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22175_Desc = {
    Text = "แผ่นไม้ทำนายเคลื่อนที่อย่างมั่นใจ ดวงตาของคุณก็สอดส่ายไปมาเช่นกัน\nอย่างไรก็ตาม พระองค์เพิ่งชี้ไปที่ตัวอักษรสองตัว ก็กลายเป็นของเหลวสีดำข้นในเสียงหวีดร้องที่น่าสังเวช。"
  },
  Event_22175_Name = {
    Text = "บอร์ดสื่อสารวิญญาณ"
  },
  Event_22176_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22176_Desc = {
    Text = "「คณิตศาสตร์! คณิตศาสตร์!!」\nเสียงผู้หญิงพูดอย่างโกรธเคือง แผ่นไม้กระดานเคลื่อนผ่านตัวเลขอย่างรวดเร็ว เกิดเสียงไม้เสียดสีกันอย่างแสบแก้วหู。\n「เอาคณิตศาสตร์ของแกออกไปให้พ้นหน้าฉัน!」"
  },
  Event_22176_Name = {
    Text = "บอร์ดสื่อสารวิญญาณ"
  },
  Event_22177_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22177_Desc = {
    Text = "「เดี๋ยวๆ เดี๋ยว!!」\n「ถามฉันสิ! ทำไมเธอไม่ถาม!」"
  },
  Event_22177_Name = {
    Text = "บอร์ดสื่อสารวิญญาณ"
  },
  Event_22178_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22178_Desc = {
    Text = "มันไม่เคยเต้นแรงเท่าในช่วงเวลานี้มาก่อน แต่ในทางกลับกัน ความว่างเปล่าภายในกำลังถูกฉีกออก.."
  },
  Event_22178_Name = {
    Text = "คำสาปกระหาย"
  },
  Event_22179_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22179_Desc = {
    Text = "จิตวิญญาณและจิตใจเต็มไปด้วยปอดของคุณ ในความเงียบ คุณค่อยๆ ลอยขึ้น \n เสียงของโลกดังขึ้นทีละเสียง บรรเลงซิมโฟนีแห่งชีวิต。"
  },
  Event_22179_Name = {
    Text = "น้ำแห่งอดีต"
  },
  Event_22180_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22180_Desc = {
    Text = "ทุกอย่างยังคงเกิดขึ้นตามปกติ การล่มสลายมาถึงตามกำหนด เศษซากที่ยังไม่ถูกเผาไหม้ซ่อนอยู่ภายในสิ่งมีค่า จมอยู่ในเงาและเปล่งประกายเจิดจ้า。"
  },
  Event_22180_Name = {
    Text = "นอกเหนือจากปลายเข็ม"
  },
  Event_22181_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22181_Desc = {
    Text = "พบกัน ลาจาก และผ่านพ้นไป"
  },
  Event_22181_Name = {
    Text = "เสียงของดาวและดวงจันทร์"
  },
  Event_22182_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22182_Desc = {
    Text = "หัวใจที่เคยเต้นแรงเริ่มช้าลง แต่บางที 「มโนธรรม」 อาจได้รับการปลอบโยนเล็กน้อยแล้ว.."
  },
  Event_22182_Name = {
    Text = "คำสาปกระหาย"
  },
  Event_22183_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22183_Desc = {
    Text = "คุณหลับตาลงและเพลิดเพลินกับช่วงเวลาที่หายากนี้ของสุญญตาและเสรีภาพ ค่อยๆ คุณรู้สึกว่าโลกกำลังฟักออกมาจากความเงียบและชีวิตกำลังเบ่งบานอย่างเงียบงันในความเงียบ。"
  },
  Event_22183_Name = {
    Text = "น้ำแห่งอดีต"
  },
  Event_22184_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22184_Desc = {
    Text = "คุณหยุดเข็มที่พุ่งมา เศษเงินสะท้อนแสงตัดผ่านฝ่ามือนุ่มนวล การทำลายล้างยังไม่มาถึง แต่เงาใต้ฝ่าเท้าของคุณกลับถูกความมืดเข้มกลืนหายไป。"
  },
  Event_22184_Name = {
    Text = "นอกเหนือจากปลายเข็ม"
  },
  Event_22185_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22185_Desc = {
    Text = "「คุณหนีไม่พ้น ไม่มีใครสามารถต้านทานความชั่วร้ายภายในได้」\nความคิดชั่วร้ายฉีกกระชากเส้นประสาท พยายามดึงคุณลงไปในเหว แต่ความเจ็บปวดกลับทำให้จิตใจของคุณรู้สึกชัดเจนอย่างไม่เคยเป็นมาก่อน\nความคิดชั่วร้ายไม่สามารถเป็นเจ้าของคุณได้ คุณจะเป็นเพียงตัวของตัวเองเท่านั้น。"
  },
  Event_22185_Name = {
    Text = "ความคิดที่ไม่มีมูล"
  },
  Event_22186_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22186_Desc = {
    Text = "「ทำไมจะไม่ได้ล่ะ?」\nเพียงแค่ยอมรับความคิดที่น่ากลัวเหล่านั้น ทุกปัญหาก็จะถูกคลี่คลาย และจะไม่มีสิ่งที่เรียกว่าความขัดแย้งทาง 「จริยธรรม」 ในโลกนี้อีกต่อไป。"
  },
  Event_22186_Name = {
    Text = "ความคิดที่ไม่มีมูล"
  },
  Event_22187_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22187_Desc = {
    Text = "ม่านแสงสีเงินวาบผ่านหน้าไป สายลมหนักอึ้งพัดพาเสียงทั้งหมดหายไป"
  },
  Event_22187_Name = {
    Text = "ความคิดที่ไม่มีมูล"
  },
  Event_22188_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22188_Desc = {
    Text = "เปลี่ยนแปลงง่าย เย็นชา ไกลแต่ไม่ลืม"
  },
  Event_22188_Name = {
    Text = "เสียงของดาวและดวงจันทร์"
  },
  Event_22189_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22189_Desc = {
    Text = "ขยายตัว หดตัว พร้อมจะระเบิด"
  },
  Event_22189_Name = {
    Text = "เสียงของดาวและดวงจันทร์"
  },
  Event_22190_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22190_Desc = {
    Text = "แม้จะดูหุนหันพลันแล่นไปบ้าง แต่ทำไมจะไม่ล่ะ? \n ทำลายกำแพงทุกอย่างและพุ่งไปยังเส้นชัย \n แม้ว่าจะทำให้ทะเลสาบแห่งความคิดเกิดคลื่นยักษ์ หรือแม้จะกลายเป็นอิคารัสที่ไล่ตามดวงอาทิตย์ แต่คุณก็อย่างน้อยได้บรรลุเป้าหมายใช่ไหม?"
  },
  Event_22190_Name = {
    Text = "เขาวงกตแห่งความคิด"
  },
  Event_22191_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22191_Desc = {
    Text = "สมองของคุณคือเขาวงกต และคุณคืออารีอัดเน่ \n ในจักรวาลนี้ ไม่มีใครที่เข้าใจวิธีออกจากเขาวงกตได้ดีกว่าคุณ \n ไม่มีใครเลย。"
  },
  Event_22191_Name = {
    Text = "เขาวงกตแห่งความคิด"
  },
  Event_22192_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22192_Desc = {
    Text = "ภายใต้การปรับจูนที่ถูกต้อง ระยะเสียงที่ไม่กลมกลืนก็อ่อนลงเล็กน้อย \n แต่บางที คุณอาจยังทำอะไรได้อีก。"
  },
  Event_22192_Name = {
    Text = "เสียงไม่ประสาน"
  },
  Event_22193_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22193_Desc = {
    Text = "คุณคืออาจารย์ดนตรี และก็เป็นคนที่มีทักษะดนตรีธรรมดา \n โน้ตดนตรีทำหน้าที่ของตนภายใต้การควบคุมของความคิดคุณ ชีวิตที่ไหลเวียนในที่สุดก็เริ่มบรรเลงในดินแดนลับแล。"
  },
  Event_22193_Name = {
    Text = "เสียงไม่ประสาน"
  },
  Event_22194_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22194_Desc = {
    Text = "เสียงของคุณจมหายไปในความเงียบ ความเงียบดังขึ้นเรื่อย ๆ จนแตกสลาย ทิ้งซากไว้เบื้องหลัง"
  },
  Event_22194_Name = {
    Text = "น้ำแห่งอดีต"
  },
  Event_22195_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22195_Desc = {
    Text = "คุณไม่ได้หลงกลง่ายๆ หมุนตัวอย่างรวดเร็วและเด็ดขาด จากไปโดยไม่ลังเล"
  },
  Event_22195_Name = {
    Text = "รอยร้าวคลาน"
  },
  Event_22293_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22293_Desc = {
    Text = "เมื่อยกปากกาขึ้น กระดาษเขียนจดหมายก็ถูกเผาไหม้ในดินแดนลับแล เถ้าถ่านร่วงหล่นลงบนมือ \n เมื่อหันกลับมา มีบางสิ่งที่หายไปพร้อมกับกระดาษเขียนจดหมาย。"
  },
  Event_22293_Name = {
    Text = "การสารภาพเดียวดาย"
  },
  Event_22294_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22294_Desc = {
    Text = "ในช่วงที่กระดาษเขียนจดหมายหายไปในดินแดนลับแล คุณได้ยินความห่วงใยที่อ่อนโยนและอ่อนแอ\n「การที่คุณนึกถึงฉันในสถานการณ์แบบนี้ เป็นเกียรติของฉันในฐานะครู\nแต่การที่ฉันเดินทางในดินแดนลับแลครั้งสุดท้าย มันก็เป็นเรื่องที่นานมากแล้ว ตอนนี้ฉันช่วยคุณได้แค่เพียงเท่านี้...」"
  },
  Event_22294_Name = {
    Text = "การสารภาพเดียวดาย"
  },
  Event_22295_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22295_Desc = {
    Text = "ในช่วงที่กระดาษเขียนจดหมายหายไปในดินแดนลับแล คุณได้ยินเสียงตะโกนด้วยความเร่งรีบ\n「ผู้พิทักษ์ ถ้ามีอะไรไม่สบายใจ โปรดแจ้งให้ฉันทราบ\nในฐานะคู่หู ฉันจะช่วยคุณอย่างเต็มที่」"
  },
  Event_22295_Name = {
    Text = "การสารภาพเดียวดาย"
  },
  Event_22296_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22296_Desc = {
    Text = "ในช่วงที่กระดาษเขียนจดหมายหายไปในดินแดนลับแล คุณได้ยินเสียงถอนหายใจอย่างเย็นชา\n「ถ้าคุณสามารถขอความช่วยเหลือได้อย่างกระตือรือร้นแบบนี้เมื่อสอบไม่ผ่านก็ดีสิ。」"
  },
  Event_22296_Name = {
    Text = "การสารภาพเดียวดาย"
  },
  Event_22397_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22397_Desc = {
    Text = "การปรากฏตัวของคุณทำให้เงามองหน้ากันอย่างงงงวย แสงดาวหนึ่งพุ่งผ่านปลายรองเท้าของคุณ จากนั้นฝูงชนก็หายไปอย่างกะทันหัน เหลือไว้เพียงเงาที่แน่นหนาที่สุดในมือของคุณ。"
  },
  Event_22397_Name = {
    Text = "สัญญาของดวงดาวและพระจันทร์"
  },
  Event_22398_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_22398_Desc = {
    Text = "เสียงกระซิบที่วุ่นวายเงียบลงอย่างกะทันหัน เงาที่ดำสนิทเหมือนหมึกหันมาทางคุณและจ้องมองคุณ จากใบหน้าที่ไม่มีอวัยวะบนใบหน้านั้น คุณกลับอ่านออกถึงความเย้ยหยันบางอย่าง……"
  },
  Event_22398_Name = {
    Text = "สัญญาของดวงดาวและพระจันทร์"
  },
  Event_22399_ChoiceDesc1 = {
    Text = "【สังเกตอย่างใจเย็น】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_22399_ChoiceDesc2 = {
    Text = "【สอบถามเสียง】รับได้ 25 รอยดำ"
  },
  Event_22399_Desc = {
    Text = "ท่ามกลางการพาดผ่านระหว่างดวงดาวและดวงจันทร์ เสียงกระซิบกระซาบไม่ขาดสาย\n「คนนี้ใช่ไหม? @4 ของคน...」\n「ด้วยร่างมนุษย์ สุดท้ายก็ยังคงเป็น @3 …」"
  },
  Event_22399_Name = {
    Text = "สัญญาของดวงดาวและพระจันทร์"
  },
  Event_22411_ChoiceDesc1 = {
    Text = "【สำเร็จแล้ว】"
  },
  Event_22411_Desc = {
    Text = "กับดักราคาถูกแต่ใช้งานได้ดี!"
  },
  Event_22411_Name = {
    Text = "ทำกับดัก"
  },
  Event_24254_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_24254_Desc = {
    Text = "พายุแห่งความรู้ทางจิตวิญญาณล้อมรอบตูรูไว้ คุณสบตาเขาแวบหนึ่ง ก่อนจะตามกันเข้าไปในเงามืดทีละก้าว"
  },
  Event_24254_Name = {
    Text = "จากทะเล"
  },
  Event_24255_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_24255_Desc = {
    Text = "พายุแห่งความรู้ทางจิตวิญญาณโอบล้อมตูรูไว้ และความเศร้าและผิดที่ไม่จางก็แผ่ซ่านไปในอากาศ"
  },
  Event_24255_Name = {
    Text = "เผชิญหน้ากับเหว"
  },
  Event_24256_ChoiceDesc1 = {
    Text = "【สัมผัสอย่างแน่นหนา】ยอมรับความช่วยเหลือจากตูรู"
  },
  Event_24256_Desc = {
    Text = "อำนาจของเขาเหมือนกับสิ่งมหึมาที่ตกลงสู่ทะเล ก่อให้เกิดคลื่นในดินแดนลับแลเบื้องหน้า\nพละกำลังนั้นโบราณ ช้านาน และเพียงพอที่จะก้าวข้ามขีดจำกัดเกินกว่าหมื่นปี\nโชคดีที่คุณจะไม่เป็นศัตรูกับเขา อย่างน้อยในขณะนี้。"
  },
  Event_24256_Name = {
    Text = "จากทะเล"
  },
  Event_24257_ChoiceDesc1 = {
    Text = "【คว้าสัมผัส】เดินทางพร้อมกับตูรู"
  },
  Event_24257_Desc = {
    Text = "ธูลูลึกหายใจเข้าหนึ่งครั้ง มองมิลียาห์มจากระยะไกล ราวกับกำลังระลึกถึงประวัติศาสตร์ เพื่อนเก่า และชีวิตของตัวเอง... สีหน้าที่ซับซ้อนบนใบหน้าของเขาอยู่เพียงชั่วครู่ ก่อนที่เขาจะหันเหความสนใจออกจากใบหน้าของมิลียาห์ม 「ไปเถอะ ออกจากที่นี่เธอ」"
  },
  Event_24257_Name = {
    Text = "เผชิญหน้ากับเหว"
  },
  Event_24277_ChoiceDesc1 = {
    Text = "【ปิดประตูห้อง】"
  },
  Event_24277_Desc = {
    Text = "ราโมน่าจับนักเรียนที่บุกเข้ามาจากข้างนอกไว้ได้\nผู้พิทักษ์ที่กล้าหาญและแข็งแกร่ง แม้จะดูยุ่งเหยิงแต่ก็ไม่มีอะไรผิดปกติ เงาของเธอในดวงตาสีฟ้าภายใต้เลนส์ดูเหมือนจะพร่าเบลอ\nจนกระทั่งในช่วงเวลาที่จับมือไว้ ราโมน่าจึงสามารถยืนยันได้ว่าพวกคุณได้พบกันอีกครั้ง。"
  },
  Event_24277_Name = {
    Text = "การพบกันด้วยความยินดี"
  },
  Event_24278_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_24278_Desc = {
    Text = "รามอน่าไม่ให้โอกาสคุณได้อธิบาย เธอดึงคุณเข้าไปในห้องที่สลัวแล้วปิดประตูอย่างระมัดระวัง.."
  },
  Event_24278_Name = {
    Text = "การพบกันด้วยความยินดี"
  },
  Event_24540_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_24540_Desc = {
    Text = "「เธอคือโล่ที่แข็งแกร่งของคุณ คือดาบในมือของคุณ \n เธอคือเพื่อนร่วมทางของคุณ คู่หูของคุณ เพื่อนที่คุณไว้วางใจ——ไม่ว่าเธอจะกลายเป็นเช่นไร」"
  },
  Event_24540_Name = {
    Text = "การมีอยู่ที่แปลกแต่คุ้นเคย"
  },
  Event_24541_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_24541_Desc = {
    Text = "「เป็นคุณ...... ไม่ มันเป็นไปไม่ได้ คุณในวัฏจักรนี้ได้...... ฉันก็ได้......」\nเสียงค่อยๆ หายไปพร้อมกับเงา มีเพียงความเศร้ายังคงวนเวียนอยู่ในหมอกน้ำ.。"
  },
  Event_24541_Name = {
    Text = "รูปร่างที่คุ้นเคยแต่แปลกตา"
  },
  Event_24542_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_24542_Desc = {
    Text = "「เพื่อโลก เพื่อมนุษย์ เพื่อทุกสิ่งที่เราหวงแหน\nและเหนือสิ่งอื่นใด——เธอทำเพื่อคุณ」"
  },
  Event_24542_Name = {
    Text = "การมีอยู่ที่แปลกแต่คุ้นเคย"
  },
  Event_24543_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_24543_Desc = {
    Text = "คุณยังไม่ทันเข้าใกล้เงาร่างนั้นก็สังเกตเห็นคุณแล้ว ร่างของเขาหยุดชะงัก ดูเหมือนตกใจ และเหมือนถูกความเศร้าโศกอย่างใหญ่หลวงครอบงำทันที \nยังไม่ทันที่คุณจะพูดอะไร เขาก็หายไปพร้อมกับหมอก。"
  },
  Event_24543_Name = {
    Text = "รูปร่างที่คุ้นเคยแต่แปลกตา"
  },
  Event_24544_ChoiceDesc1 = {
    Text = "【เธอเป็นใคร？】สุ่มการ์ดคำสั่ง 3 ใบจากกองการ์ด เลือก 1 ใบเพื่อทำการคัดลอก"
  },
  Event_24544_ChoiceDesc2 = {
    Text = "【ทำไมเธอถึงกลายเป็นแบบนี้?】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」,     ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_24544_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_24544_Desc = {
    Text = "อีกหนึ่งหมอก อีกหนึ่งเงา แตกต่างจากครั้งก่อน ครั้งนี้คุณมองเห็นเขาอย่างชัดเจน \n รูปร่างเหมือนคุณ เสื้อผ้าเหมือนคุณ และใบหน้าก็เหมือนคุณ \n 「คุณรู้ไหมว่าทำไมคุณถึงอยู่ที่นี่」คนนั้นพูดว่า 「เหมือนกับที่คุณรู้ว่าเธอทำไมถึงกลายเป็นแบบนั้น」"
  },
  Event_24544_Name = {
    Text = "การมีอยู่ที่แปลกแต่คุ้นเคย"
  },
  Event_24545_ChoiceDesc1 = {
    Text = "【กล่าวคำปลอบ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ถูกผลกระทบ「(Skill.Arg2)」"
  },
  Event_24545_ChoiceDesc2 = {
    Text = "【พยายามเข้าใกล้】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」 ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_24545_ChoiceDesc3 = {
    Text = "【หันหลังเดินจากไป】ได้รับ 25 รอยดำ"
  },
  Event_24545_Desc = {
    Text = "หมอกปกคลุมเส้นทางที่คุณเดินไป \n เงาร่างปรากฏขึ้นในแสงที่พร่ามัว คุณขยิบตา แต่กลับมองไม่เห็นโฉมหน้าของเขาเลยได้ยินแต่เสียงกระซิบที่ขาดหายไป \n 「ทำไม...... ทำไมไม่สามารถช่วย...... ชะตากรรมจริงๆ ไม่สามารถเปลี่ยนแปลงได้เหรอ......」"
  },
  Event_24545_Name = {
    Text = "รูปร่างที่คุ้นเคยแต่แปลกตา"
  },
  Event_35039_ChoiceDesc1 = {
    Text = "【ขอความช่วยเหลือจากหุ้นส่วน】รับการแกะสลักขั้นสูงแบบเลือก 1 จาก 3"
  },
  Event_35039_ChoiceDesc2 = {
    Text = "【จัดการการถ่ายทำ】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_35039_ChoiceDesc3 = {
    Text = "【กระตุ้นความคลั่งไคล้ระดับปรากฏการณ์】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_35039_Desc = {
    Text = "“ใน《คู่มือการถ่ายทำของมาสเตอร์ฮูดินี》ได้ระบุไว้อย่างชัดเจนว่า คาเซียห์ ซึ่งก็คือตัวฉันเอง ในฐานะผู้ผลิตและผู้กำกับ มีหน้าที่และอำนาจรับผิดชอบต่อภาพยนตร์ทั้งเรื่อง ดังนั้น คาเซียห์ ลูกจ้างผู้กล้าหาญของฉัน โปรดเลือกกำหนดการดำเนินการถัดไปของคุณซะ!”\n“กำหนดการ? เดี๋ยวสิ ฉันกลายเป็นลูกจ้างของคุณเมื่อไหร่กัน?!”\n“โอกาสที่ไม่ควรพลาดจะไม่กลับมาอีกแล้ว อย่าลังเลอีกต่อไป!”"
  },
  Event_35039_Name = {
    Text = "ความลึกลับของผู้ผลิต"
  },
  Event_35103_ChoiceDesc1 = {
    Text = "【รับสาย】ตอบกลับ Arg2 จุดชีวิต [ExDesc1] [ExDesc2]。"
  },
  Event_35103_ChoiceDesc2 = {
    Text = "【การตื่นรู้】เลือกปลุกผู้ตื่น 1 ตน。"
  },
  Event_35103_ChoiceDesc3 = {
    Text = "【กำจัด】ลบการ์ดอาการได้สูงสุด 3 ใบ ได้รับ Arg2 รอยดำ。"
  },
  Event_35103_Desc = {
    Text = "คุณกำลังสำรวจในหมอกจางๆ อยู่ดีๆ ตราสัญลักษณ์ที่หน้าอกก็ปล่อยแสงสีเงินอ่อนๆ ออกมา ใครกำลังเรียกคุณจากเครื่องสื่อสารอยู่?"
  },
  Event_35103_Name = {
    Text = "จุดติดต่อ"
  },
  Event_35103_Tips3 = {
    Text = "ขณะนี้คุณยังไม่มีการ์ดอาการ"
  },
  Event_35165_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35165_Desc = {
    Text = "คุณลังเลอยู่ครู่หนึ่ง แล้วส่งคำขอการสื่อสารไปยังผู้สนับสนุนลึกลับ\n“เรื่องมันถึงจุดนี้แล้ว ไม่สามารถถอยกลับได้ ขอให้ลอร์ดใจดีช่วยเหลือด้วย...”\nเครื่องสื่อสารเงินใจฝั่งตรงข้ามดังเสียงหัวเราะที่เต็มไปด้วยความเอื้อเฟื้อ และฝ่ายนั้นก็ยอมรับคำขอของคุณอย่างยิ้มแย้ม\n“อ้อ ยังมีอีกเรื่อง... กรุณาเก็บเรื่องนี้ให้เป็นความลับกับราโมน่าด้วย”"
  },
  Event_35165_Name = {
    Text = "ความลึกลับของผู้ผลิต"
  },
  Event_35236_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35236_Desc = {
    Text = "ผู้ประสานงานบนเซ็ตทำอะไรอยู่? คุณหยิบเอกสารกองหนึ่งที่คาเซียห์ไม่รู้ว่าเมื่อไหร่ได้แอบใส่ไว้ในเครื่องถ่ายโอนความรู้ทางจิตวิญญาณออกมาอ่านอย่างตั้งใจ \nแล้วคุณก็เริ่มปวดหัว \nค่าใช้จ่ายที่โลทันทำให้เกิดความเสียหายในระหว่างการจัดเซ็ต, ขนมขบเคี้ยวที่ออริตากับบราวน์กินไป, คำร้องขอเบิกเงินสำหรับลูกบอลเวทมนตร์ที่คาเซียห์ซื้อมาทำ... จำนวนเงินที่ต้องชำระถูกวางอยู่ตรงหน้าคุณ คุณจึงต้องนั่งกุมหัวของตัวเองเพื่อทำการคำนวณอย่างทุกข์ทรมาน \nพูดถึงคาเซียห์ ลูกบอลเวทมนตร์ของเธอคืออะไรนะ?"
  },
  Event_35236_Name = {
    Text = "ความลึกลับของผู้ผลิต"
  },
  Event_35259_ChoiceDesc1 = {
    Text = "【ขจัดภาพลวง】อาการติดเชื้อ[ExDesc1][ExDesc2]。"
  },
  Event_35259_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_35259_Desc = {
    Text = "ใบหน้าที่เลือนรางปรากฏขึ้นอย่างกะทันหัน พวกมันล้อมรอบคุณไว้ ใช้สายเสียงที่ไม่มีอยู่จริงคร่ำครวญอย่างสิ้นหวัง。"
  },
  Event_35259_Name = {
    Text = "ภาพลวง"
  },
  Event_35497_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35497_Desc = {
    Text = "เบื้องหลังความคลั่งไคล้ระดับปรากฏการณ์นั้นต้องการผู้ผลักดัน และเมื่อพูดถึง \"ผู้ผลักดัน\" เงาของสาวผมสั้นสีเขียวคนหนึ่งก็ผุดขึ้นในหัวของฉัน \n \"ผู้จัดการอันดับหนึ่งของมหาวิทยาลัยมิซากะ ฮันนา พีสลี ยินดีให้บริการคุณ!\" \n \"ถ้าหากเป็นความต้องการในการบริการครั้งแรกของผู้พิทักษ์ เพียงแค่จ่ายค่าตอบแทนเป็นชุดข้าวแกงในโรงอาหาร 3 มื้อเท่านั้น!\""
  },
  Event_35497_Name = {
    Text = "ความลึกลับของผู้ผลิต"
  },
  Event_35887_ChoiceDesc1 = {
    Text = "【เดินหน้า】"
  },
  Event_35887_Desc = {
    Text = "คุณยกใบเรือขึ้น แต่กลับพบว่าข้างล่างว่างเปล่า เมื่อคุณได้สติอีกครั้ง ใบเรือก็หายไปแล้ว\nใบเรือขาวบริสุทธิ์และใบหน้าของสาวน้อยที่เลือนราง กลายเป็นข้อความที่เตือนคุณว่าไม่ว่าหนทางข้างหน้าจะเป็นอย่างไร คุณก็ไม่อยู่คนเดียว。"
  },
  Event_35887_Name = {
    Text = "ใบเรือสีขาวบริสุทธิ์"
  },
  Event_35888_ChoiceDesc1 = {
    Text = "【ยกใบเรือ】"
  },
  Event_35888_Desc = {
    Text = "ที่นี่ไม่มีวายุ แต่มีเรือใบสีขาวบริสุทธิ์ลำหนึ่ง ใบเรือของมันพุ่งสูงขึ้นอย่างเต็มที่ ยืนหยัดอยู่บนผิวน้ำทะเลสีฟ้าสดใส\nคุณเห็นใบหน้าของสาวน้อยอย่างเลือนราง เธอมีอวัยวะที่ไม่ชัดเจน เหมือนอยู่ผ่านม่านหมอกบางๆ หรือผิวน้ำที่เคลื่อนที่ เธอดูเหมือนจะถูกแยกออกจากทุกสิ่งรอบตัว แต่กลับเป็นจุดศูนย์กลางของฉากนี้\nแม้ว่าเงาของเธอจะเปลี่ยนแปลงไปในความคลุมเครือและความชัดเจน แต่ไม่ต้องสงสัยเลย คุณรู้ว่าเธอคือใคร。"
  },
  Event_35888_Name = {
    Text = "ใบเรือสีขาวบริสุทธิ์"
  },
  Event_35894_ChoiceDesc1 = {
    Text = "【ตกลงไปด้านล่าง】ได้รับ 35 รอยดำ, ติด「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_35894_ChoiceDesc2 = {
    Text = "【ออกห่างไปไกล】"
  },
  Event_35894_Desc = {
    Text = "เสียงของหญิงสาวกระจายไปในอากาศ พร่ามัวและไกลโพ้นราวฟองสบู่ที่เลือนลาง"
  },
  Event_35894_Name = {
    Text = "เส้นทางระหว่างชีวิตและความตาย"
  },
  Event_35895_ChoiceDesc1 = {
    Text = "【ซ้ำไปซ้ำมา】ได้รับ 30 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, ดำเนินการเลือกต่อไป"
  },
  Event_35895_ChoiceDesc2 = {
    Text = "【ออกห่างไปไกล】"
  },
  Event_35895_Desc = {
    Text = "ร่างกายหนักอึ้งผิดปกติ หมอกควันหนาแน่นพันธนาการร่างกายที่อ่อนแอ"
  },
  Event_35895_Name = {
    Text = "เส้นทางระหว่างชีวิตและความตาย"
  },
  Event_35896_ChoiceDesc1 = {
    Text = "【อ่านทางของผู้มาก่อน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_35896_ChoiceDesc2 = {
    Text = "【เขียนเส้นทางของตนเอง】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_35896_ChoiceDesc3 = {
    Text = "【จ้องมองความมืด】ได้รับ 25 รอยดำ"
  },
  Event_35896_Desc = {
    Text = "ถ้าคุณเดินทางในดินแดนลับแลคนเดียว คุณจะไม่มั่นใจในเส้นทางข้างหน้าของคุณอย่างนี้แน่นอน\nรอยเท้าในดินแดนลับแลถูกแบ่งออกเป็นสามเส้น ทุกรอยเท้าที่ทิ้งไว้ล้วนเขียนถึงอนาคตที่มองไม่เห็น。"
  },
  Event_35896_Name = {
    Text = "ทางออก"
  },
  Event_35897_ChoiceDesc1 = {
    Text = "【ช่วยพยุงเธอ】"
  },
  Event_35897_ChoiceDesc2 = {
    Text = "【มองเธอ】"
  },
  Event_35897_Desc = {
    Text = "เธอกระซิบอยู่ และหยุดลงตรงหน้าคุณ \n ไม่รู้ว่าใครรบกวนการนอนหลับของเธอ ความรู้สึกของเธอถูกการใช้ชีวิตผูกมัด แต่จิตวิญญาณของเธอกลับยังคงอยู่ในอาณาจักรที่สูญเสีย。"
  },
  Event_35897_Name = {
    Text = "ภาพลวงตาที่หายไป"
  },
  Event_35898_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35898_Desc = {
    Text = "ในความมืดที่เคออสและไม่สามารถแยกแยะได้นี้ รอยเท้าที่ไม่ชัดเจนทอดยาวออกไป เหมือนกับผู้เดินทางในยามค่ำคืนที่ทิ้งร่องรอยลึกไว้บนทะเลทรายที่มองไม่เห็น。"
  },
  Event_35898_Name = {
    Text = "ทางออก"
  },
  Event_35899_ChoiceDesc1 = {
    Text = "【จากไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_35899_Desc = {
    Text = "ภาพของประภาคารที่อยู่ไกลโพ้นสะท้อนในดวงตาของคุณ มันตั้งตระหง่านเดี่ยวโดดอยู่ที่ขอบความมืด เปล่งประกายแสงเล็กน้อยแต่มั่นคง ราวกับเป็นไกด์ในทะเลยามค่ำคืน เรียกร้องจิตวิญญาณที่ลังเลให้มุ่งหน้าไปหาความสงบที่ฝั่งตรงข้าม \nคุณไม่สามารถต้านทานได้ จึงวิ่งตามไป แต่จู่ๆ พื้นใต้เท้าก็ไม่มั่นคงอีกต่อไป \nคุณเหยียบลงไปในน้ำที่ซ่อนอยู่ใต้เงามืด ผิวน้ำอ่อนนุ่มเหมือนไหมและดูดซับก้าวของคุณอย่างไร้เสียง。"
  },
  Event_35899_Name = {
    Text = "กระพริบ"
  },
  Event_35900_ChoiceDesc1 = {
    Text = "【ฟังเธอ】"
  },
  Event_35900_ChoiceDesc2 = {
    Text = "【ละเลยเธอ】"
  },
  Event_35900_Desc = {
    Text = "คุณมองเห็นแหล่งกำเนิดของแสงไฟอย่างชัดเจน นั่นคือบุคคลที่มีรูปร่างเป็นผู้หญิง\nแสงที่สลัวไหลออกมาจากหัวที่แปลกประหลาด สร้างเส้นทางไปสู่สิ่งที่ไม่รู้จัก\n「กลับไปยัง... ลิ@2อา...」"
  },
  Event_35900_Name = {
    Text = "ไฟส่องสว่างตลอดกาล"
  },
  Event_35901_ChoiceDesc1 = {
    Text = "【ใกล้กับประภาคาร】"
  },
  Event_35901_ChoiceDesc2 = {
    Text = "【ห่างไกลจากประภาคาร】"
  },
  Event_35901_Desc = {
    Text = "เลี้ยวเข้ามุมที่ความจริงและความฝันสลับกัน ในช่วงเวลาที่ผ่านไปอย่างรวดเร็วตรงนั้น ภาพที่น่าสะพรึงกลัวของพายุปรากฏขึ้นต่อหน้า \n เหมือนถูกมือที่มองไม่เห็นขนาดใหญ่ยกขึ้น ลมพัดกรรโชกเหมือนสัตว์ร้ายคำราม พัดพาเอาเถ้าถ่านและความหวังขึ้นไป ท้องฟ้ามืดมิด กดดันอย่างที่สุด \n ในใจกลางของพายุ ประภาคารที่ไม่ควรมีตั้งอยู่ ดูเหมือนจะเป็นผลผลิตของจินตนาการ หรืออาจจะเป็นซากของตำนานโบราณ มันเปล่งแสงอ่อน ๆ อย่างโดดเดี่ยวและแข็งแกร่งบนเวทีที่ลมพัดกระหน่ำ。"
  },
  Event_35901_Name = {
    Text = "ศูนย์กลางพายุ"
  },
  Event_35902_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_35902_Desc = {
    Text = "「ในดินแดนลับแล ไฟสว่างไสวและเงาที่มีหนวด…」\nธูลูหลับตาคิดทบทวน หลังจากนั้นครู่หนึ่งก็ถอนหายใจยาวออกมา。\n「ผู้รักษาประตูแห่งลีมูเรีย… หนึ่งในเซิร์ฟแวนท์ของฉัน เธอก็ไม่สามารถหลบหนีจากความหลงใหลได้」"
  },
  Event_35902_Name = {
    Text = "การจมของโซนานิร"
  },
  Event_35903_ChoiceDesc1 = {
    Text = "【สัมผัสแสงเงิน】ได้รับ 25 รอยดำ"
  },
  Event_35903_ChoiceDesc2 = {
    Text = "【บทสนทนา】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_35903_Desc = {
    Text = "เครื่องส่งสัญญาณที่เชื่อมอัดแน่นนั้นถูกแง้มออกเล็กน้อย แสงที่เลือนลางแทรกออกมาจากรอยแยก นี่อาจจะเป็นครั้งแรกที่แกนเงินซึ่งถูกผนึกในศูนย์กลางของเครื่องส่งสัญญาณได้สื่อสารกับโลกภายนอก。"
  },
  Event_35903_Name = {
    Text = "อนุสาวรีย์มิธริล"
  },
  Event_35904_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับของสร้าง「(RelicConfig.Arg1)」"
  },
  Event_35904_Desc = {
    Text = "「ผู้หญิงที่มีศีรษะเปล่งแสง?」เอลตันแสดงสีหน้าแปลกใจอย่างชัดเจน เขาเห็นข่าวลือเกี่ยวกับเงาที่ปรากฏในดินแดนลับแลของเรือบรรทุกสินค้า แต่—\n「คืนที่เรือโซนาเนียลจม... ก็คืนที่ฉันปลุกตื่นเซเลสเท ฉันเคยเห็นเงาแบบนั้นในพายุ」\n「ฉันมั่นใจว่าฉันไม่ผิด」"
  },
  Event_35904_Name = {
    Text = "การจมของโซนานิร"
  },
  Event_35905_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35905_Desc = {
    Text = "ดินแดนลับแลข้างหน้าเต็มไปด้วยอันตราย ลึกเกินคาดเดา。\nตาของคุณจ้องมองไปที่เคออสที่มองไม่เห็นอย่างแน่วแน่ แต่ก่อนที่คุณจะถูกเคออสกลืนกิน ราโมน่าก็จับคุณไว้ได้อย่างรวดเร็วแล้วพาคุณไปยังอีกด้านหนึ่ง。"
  },
  Event_35905_Name = {
    Text = "ทางออก"
  },
  Event_35906_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35906_Desc = {
    Text = "นั่นคือผลไม้ที่วิญญาณลึกลับของคุณกำเนิดขึ้นหรือเปล่า? ทุกสิ่งที่คุณกำลังประสบอยู่ตอนนี้คือการปะทะกันระหว่างตัวตนของคุณกับอัตตาสูงสุดหรือ? \nยิ่งคิดมาก เสียงรบกวนในหัวของคุณก็ยิ่งดังและใสขึ้น สายตาของคุณบุกเข้าไปในหมอกหนา ในขณะที่คุณเกือบจะมองเห็นคนในหมอกในวินาทีนั้น วิญญาณของคุณกลับปฏิเสธคุณ。"
  },
  Event_35906_Name = {
    Text = "ชะตากรรมที่ผิดเพี้ยน"
  },
  Event_35907_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35907_Desc = {
    Text = "มันเคลื่อนไหวอยู่ภายในร่างกาย กลายเป็นพละกำลังที่ไม่กลัวอะไร ช่วยคุณฝ่าหมอก, ทำลายความกลัว"
  },
  Event_35907_Name = {
    Text = "ตามแสง"
  },
  Event_35908_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35908_Desc = {
    Text = "เมื่อจิตใจเริ่มมีสมาธิและความสงบ จินตภาพที่โกลาหลเริ่มค่อยๆ ละลายออกไป สุดท้ายก็เหมือนน้ำที่ลดลง \n ในที่สุด เสียงรบกวนในสมองก็หายไปอย่างไร้ร่องรอย——เพียงแต่ คุณจะพลาดอะไรไปบ้าง? ไม่มีใครรู้ได้。"
  },
  Event_35908_Name = {
    Text = "คำเตือนในอนาคต"
  },
  Event_35909_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35909_Desc = {
    Text = "จิตวิญญาณถูกสูญหายอย่างสิ้นเชิงในเสียงหูอื้อ คุณพยายามอย่างหนักที่จะหลุดพ้น พยายามที่จะตีความความเจ็บปวดนี้ แต่ไม่ว่าจะทำอย่างไร คุณก็แค่วนเวียนอยู่ที่ขอบของสติสัมปชัญญะ..."
  },
  Event_35909_Name = {
    Text = "เส้นทางระหว่างชีวิตและความตาย"
  },
  Event_35910_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์ทองคำ 3 ตัวเลือก 1，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_35910_Desc = {
    Text = "คุณสามารถรู้สึกถึงจุดแสงแต่ละจุดที่ส่งออกมาจากประภาคาร พวกมันเผาไหม้และกระโดดอยู่ในพายุ ราวกับเสียงเพรียกจากส่วนลึกของจิตวิญญาณ แม้ในความกลัวที่รุนแรงที่สุด ก็ไม่เคยปล่อยวางภารกิจในการชี้นำเส้นทางกลับ。"
  },
  Event_35910_Name = {
    Text = "ศูนย์กลางพายุ"
  },
  Event_35911_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักขั้นสูง เลือก 1 จาก 3"
  },
  Event_35911_Desc = {
    Text = "เป็นสัญลักษณ์ของความหวังหรือเป็นสัญญาณของการทำลาย? \nคุณไม่มองมันอีกต่อไป ราวกับว่าการมีอยู่ของมันเป็นเพียงความฝันที่ถูกจัดฉากอย่างประณีต。"
  },
  Event_35911_Name = {
    Text = "ศูนย์กลางพายุ"
  },
  Event_35912_ChoiceDesc1 = {
    Text = "【หลงลืมในห้วงฝัน】ได้รับ 20 รอยดำ ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_35912_ChoiceDesc2 = {
    Text = "【ออกห่างไปไกล】"
  },
  Event_35912_Desc = {
    Text = "จากนั้น เปลือกตาของคุณก็ถูกปกคลุมด้วยผ้าคลุมสีเทาที่ผิดปกติ หลังจากนั้นไม่นาน คุณก็รู้ว่ามันคือเปลือกตาบนของคุณที่โปร่งใส。"
  },
  Event_35912_Name = {
    Text = "เส้นทางระหว่างชีวิตและความตาย"
  },
  Event_35913_ChoiceDesc1 = {
    Text = "【การจากไป】การตื่นรู้แบบสุ่มของร่างกายหนึ่งที่ตื่นขึ้น ติดเชื้อ 「(Skill.Arg1)」"
  },
  Event_35913_Desc = {
    Text = "ในใจของคุณเกิดการสะท้อนบางอย่างที่ไม่อาจอธิบายได้ \nแต่สติบอกคุณว่า：เมินเธอ"
  },
  Event_35913_Name = {
    Text = "ไฟส่องสว่างตลอดกาล"
  },
  Event_35914_ChoiceDesc1 = {
    Text = "【จากไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_35914_Desc = {
    Text = "ภาษาของเธอไม่เคยถูกจารึกลงบนจารึกที่รู้จักใดๆ แต่กลับกลายเป็นความสารภาพและเสียงเพรียกที่ลึกซึ้งในอากาศ เหมือนกับลอยมาจากอีกฟากของกาลเวลา ข้ามผ่านการสะสมของปีที่ผ่านมา นำพาความรักอันลึกซึ้งต่อบ้านที่อยู่ห่างไกล。"
  },
  Event_35914_Name = {
    Text = "ไฟส่องสว่างตลอดกาล"
  },
  Event_35915_ChoiceDesc1 = {
    Text = "【จับมือเธอ】สิ่งสร้างเงิน 1 ชิ้นจะได้รับการอัปเกรดเป็นสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_35915_ChoiceDesc2 = {
    Text = "【เอ่ยถามด้วยความห่วงใย】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」ได้รับผลจาก「(Skill.Arg2)」"
  },
  Event_35915_ChoiceDesc3 = {
    Text = "【มองดูเธอ】ได้รับ 25 รอยดำ"
  },
  Event_35915_Desc = {
    Text = "เมอร์ฟี่อยู่ท้ายแถว เธอเดินเคียงข้างเซเลสเท.\nคุณอดไม่ได้ที่จะหันไปมองเธอหลายครั้ง แต่เมอร์ฟี่ยังคงก้มหน้ามองปลายรองเท้าของตัวเอง ซ่อนสีหน้าของเธอไว้ในความไม่รู้จัก."
  },
  Event_35915_Name = {
    Text = "การจัดการความปวด"
  },
  Event_35915_Tips1 = {
    Text = "ยังไม่มีสิ่งสร้างเงิน"
  },
  Event_35916_ChoiceDesc1 = {
    Text = "【ไม่สามารถถอนตัวได้】ได้รับ 40 รอยดำ ติดเชื้อ“(Skill.Arg2)” เลือกต่อไป"
  },
  Event_35916_ChoiceDesc2 = {
    Text = "【กอดความจริง】ได้รับ 25 รอยดำ"
  },
  Event_35916_Desc = {
    Text = "@1@1ได้รับการฟื้นฟูอีกครั้ง วิญญาณข้ามผ่านขอบเขตของ @2 แต่ยังไม่ได้โอบกอดร่างกายอย่างเต็มที่\nคำพูดที่เป็นห่วงของเมอร์ฟี่ค่อยๆ ห่างออกจากสติของคุณ เหมือนเสียงร้องทุกข์ของอีกา ที่ดังก้องอยู่ข้างหู แต่กลับถูกกำแพงของจิตใจขวางกั้นไว้ที่หน้าต่าง。"
  },
  Event_35916_Name = {
    Text = "เส้นทางระหว่างชีวิตและความตาย"
  },
  Event_35917_ChoiceDesc1 = {
    Text = "【ออก】เลือกคัดลอกการ์ดคำสั่ง 1 ใบ ได้รับผลกระทบจาก 「(Skill.Arg1)」"
  },
  Event_35917_Desc = {
    Text = "เธอเป็นเพียงเงาแห่งอดีตที่เหลืออยู่ในโลกความจริง บทเรื่องราวโบราณที่ไม่อาจสัมผัสได้ แต่ยากจะลืมเลือน"
  },
  Event_35917_Name = {
    Text = "ภาพลวงตาที่หายไป"
  },
  Event_35918_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_35918_Desc = {
    Text = "ในชั่วขณะนั้น คุณได้ยินเสียงแตกละเอียดจากส่วนลึกของจิตวิญญาณ เหมือนกับควันที่ค่อยๆ จางหาย รูปร่างของเธอเริ่มเบลอและดูไม่เป็นจริงมากขึ้นเรื่อยๆ \nเธอไม่ได้มีอยู่ที่นี่ นี่เป็นเพียงการโปรเจ็กชันของความทรงจำของกัปตันเอลตัน \nแต่สิ่งที่อยู่ในใจคือ ความสูญเสียและความสับสนของเธอ ที่ไม่เหมือนการปลอมแปลง。"
  },
  Event_35918_Name = {
    Text = "ภาพลวงตาที่หายไป"
  },
  Event_35919_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35919_Desc = {
    Text = "ในชั่วขณะที่ปลายนิ้วสัมผัสกัน ความรู้สึกที่ซับซ้อนก็พุ่งขึ้นมาในใจอย่างกะทันหัน——มันทั้งร้อนระอุและเย็นเฉียบ。\nวิญญาณที่ถูกลืมในโลกกำลังเห่าหอนเพื่อค้นหาความเป็นนิรันดร์。"
  },
  Event_35919_Name = {
    Text = "อนุสาวรีย์มิธริล"
  },
  Event_35920_ChoiceDesc1 = {
    Text = "【ถือไฟลุกโชน】เพิ่มพลังชีวิตสูงสุด Arg1 หน่วย"
  },
  Event_35920_ChoiceDesc2 = {
    Text = "【เผชิญหน้ากับจิตใจ】การ์ดคำสั่งสุ่ม 2 ใบรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ 2 ใบ「(Skill.Arg2)」"
  },
  Event_35920_Desc = {
    Text = "ในการล่าที่มีเสียงดังกึกก้องนี้ การไล่ล่าของโกไลแอทเหมือนสัตว์ร้ายในยามค่ำคืน พยายามกลืนกินแสงแห่งความหวังทั้งหมด อย่างไรก็ตาม การไล่ล่าที่ไร้ความปรานีนี้ไม่ได้ทำให้คุณแช่แข็ง แต่กลับจุดประกายไฟภายในใจลึก ๆ ของคุณ มันแพร่กระจายและเผาไหม้ในอกของคุณ ทำให้ร้อนแรงขึ้นเรื่อย ๆ。"
  },
  Event_35920_Name = {
    Text = "ตามแสง"
  },
  Event_35921_ChoiceDesc1 = {
    Text = "【ตีความมัน】สุ่มได้รับการ์ดคำสั่ง 3 ใบจากกองการ์ด เลือกคัดลอก 1 ใบ"
  },
  Event_35921_ChoiceDesc2 = {
    Text = "【กลายเป็นมัน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_35921_ChoiceDesc3 = {
    Text = "【ละเลยมัน】ได้รับ 25 รอยดำ"
  },
  Event_35921_Desc = {
    Text = "ในช่วงเวลาที่คุณก้าวออกไป ความสั่นสะเทือนที่มองไม่เห็นได้ดึงจิตสำนึกของคุณอย่างรุนแรง บังคับให้ดวงตาของคุณมองไปที่ขอบเขตของดินแดนลับแลเคออสสุญญตา。"
  },
  Event_35921_Name = {
    Text = "คำเตือนในอนาคต"
  },
  Event_35922_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35922_Desc = {
    Text = "บางครั้งเป็นสีสันหลากหลายที่เต้นรำอยู่ตรงหน้า บางครั้งเป็นเสียงกระซิบเบาๆ ที่ข้างหู หรือบางครั้งเป็นฉากที่พริบผ่านและใบหน้าที่พร่ามัว ทั้งหมดนั้นปะติดปะต่อกัน ราวกับกำลังเล่าเรื่องราวที่ไม่เคยรู้จักครั้งแล้วครั้งเล่า ภาพเหล่านี้ทำให้คุณรู้สึกเหมือนค่อยๆ แยกตัวออกจากความจริงและตกเข้าสู่ความฝันที่ทั้งคุ้นเคยและแปลกประหลาดไปพร้อมกัน。"
  },
  Event_35922_Name = {
    Text = "คำเตือนในอนาคต"
  },
  Event_35923_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35923_Desc = {
    Text = "การสั่นสะเทือนไม่ได้มาจากเสียงรบกวนภายนอกหรือการสั่นสะเทือนทางสัมผัส แต่เป็นความรู้สึกที่ไม่สามารถอธิบายได้จากภายในลึก ๆ เหมือนกับเสียงเรียกจากอนาคตที่กระตุ้นการรับรู้ของคุณ。"
  },
  Event_35923_Name = {
    Text = "คำเตือนในอนาคต"
  },
  Event_35924_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35924_Desc = {
    Text = "เธอไม่รู้ตัวว่ามือของตัวเองไปสัมผัสที่หน้าอก พยายามควบคุมความรู้สึกที่ทำให้หายใจไม่ออกนั้น \n ความกลัวนี้ทำให้เธอกัดฟันแน่น บังคับตัวเองให้มองข้ามความเจ็บปวดที่รุมเร้าอยู่ในอก \n ทุกครั้งที่ใบหน้าของมอร์ฟี่บิดเบี้ยวเล็กน้อยถูกเธอปิดบังอย่างรวดเร็ว ด้วยการปลอมแปลงที่ไม่ชำนาญเพื่อซ่อนความเจ็บปวด \n —— จนกระทั่งคุณจับมือของเธอ ความประหลาดใจจึงกลายเป็นสีหน้าของเธอ。"
  },
  Event_35924_Name = {
    Text = "การจัดการความปวด"
  },
  Event_35925_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35925_Desc = {
    Text = "「มอร์ฟี่? คุณเป็นอย่างไรบ้าง?」\n——เธอไม่มีการตอบสนองต่อคุณ。\nการกัดกร่อนที่มีรูปแบบทำให้หัวใจของเธอแทบหายใจไม่ออก。"
  },
  Event_35925_Name = {
    Text = "การจัดการความปวด"
  },
  Event_35926_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35926_Desc = {
    Text = "คุณไม่ลังเลอีกต่อไป ก้าวเข้าไปในความมืดที่ไม่รู้จัก สถานที่ที่คุณเดินไปนั้น ได้วาดแผนที่เส้นทางที่ยืดออกไปยังแสงสว่างเล็กน้อย。"
  },
  Event_35926_Name = {
    Text = "ทางออก"
  },
  Event_35927_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35927_Desc = {
    Text = "มีไฟที่กระโดดอยู่ตรงหน้าคุณ。\nมันร้อนแรงและมีชีวิตชีวา ห่อหุ้มด้วยเปลวไฟเย็นที่แกว่งไกว ส่องสว่างไล่เสียงที่ไม่ประสานออกไป。\nคุณกลับมามีสติและพบว่าเป็นมอร์ฟี่ที่หันมามองคุณด้วยความสงสัย—\n「คุณยังเป็นอย่างไรบ้างจริงๆ?」"
  },
  Event_35927_Name = {
    Text = "เส้นทางระหว่างชีวิตและความตาย"
  },
  Event_35928_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35928_Desc = {
    Text = "คุณรู้สึกว่าจิตสำนึกเริ่มแยกตัว ค่อยๆ ถูกดึงออกจากร่างกาย。\nราวกับเห็นวิญญาณของตัวเองกำลังเต้นรำกับเงินใจที่เหลืออยู่ แล้วตกลงไปในเหวที่มองไม่เห็นอย่างหนักหน่วง...\nที่นั่นคือสุญญตาอย่างแท้จริง。"
  },
  Event_35928_Name = {
    Text = "อนุสาวรีย์มิธริล"
  },
  Event_35929_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 25 รอยดำ"
  },
  Event_35929_Desc = {
    Text = "ยังไม่ทันที่คุณจะได้สอบสวนแหล่งกำเนิดของแสงไฟ มันก็สั่นสะเทือนอย่างรุนแรงแล้วแตกสลายในอากาศ \n แสงไฟในดินแดนลับแลเกิดคลื่นกระเพื่อมซ้อนกันออกไปทั่ว \n จากนั้นก็ไม่เหลืออะไรเลย。"
  },
  Event_35929_Name = {
    Text = "กระพริบ"
  },
  Event_35930_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35930_Desc = {
    Text = "แล้วทำไมถึงเป็นคุณได้ล่ะ?\nถ้าเป็นคุณ ทำไมเมื่อความเศร้ามาถึง พระองค์ถึงไม่ช่วยคุณไถ่บาป?\nถ้าเป็นคุณ ทำไมเมื่อประสบทุกข์ พระองค์ถึงไม่ช่วยคุณ?\nดังนั้น ทั้งหมดจึงเป็นภาพลวงตา。"
  },
  Event_35930_Name = {
    Text = "ชะตากรรมที่ผิดเพี้ยน"
  },
  Event_35931_ChoiceDesc1 = {
    Text = "【สอบถามกัปตัน】"
  },
  Event_35931_ChoiceDesc2 = {
    Text = "【สอบถามตูรู】"
  },
  Event_35931_Desc = {
    Text = "อีกครั้ง คุณเห็นเงาลึกลับนั้นเดินเข้าไปในผนังห้องและหายไปอย่างไร้ร่องรอย ผมยาวเรืองแสงเริ่มจากที่ใดที่หนึ่ง กลายเป็นหนวดสัมผัสที่ตกลงสู่พื้น \n คุณรู้ดีว่าเธอแม้ไม่ได้เป็นหนึ่งในผู้เหยียบทะเล แต่ตัวตนของเธอก็ต้องเกี่ยวข้องกับอาณาจักรที่สูญหายอย่างแน่นอน。"
  },
  Event_35931_Name = {
    Text = "การจมของโซนานิร"
  },
  Event_35932_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35932_Desc = {
    Text = "คุณกำลังกลัว ทุกอย่างเป็นเพราะอะดรีนาลีนกำลังเล่นงานคุณอยู่。\nคุณกลัวว่าการตัดสินใจของคุณจะทำร้ายจิตวิญญาณที่แบ่งปันความมืดกับคุณ。"
  },
  Event_35932_Name = {
    Text = "ตามแสง"
  },
  Event_35933_ChoiceDesc1 = {
    Text = "【ไม่มีที่หลบหนี】ได้รับ 25 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_35933_ChoiceDesc2 = {
    Text = "【ออกห่างไปไกล】"
  },
  Event_35933_Desc = {
    Text = "เส้นประสาททุกเส้นกำลังครวญครางด้วยความปรารถนาต่อ@2"
  },
  Event_35933_Name = {
    Text = "เส้นทางระหว่างชีวิตและความตาย"
  },
  Event_35934_ChoiceDesc1 = {
    Text = "【ไล่ตาม】"
  },
  Event_35934_ChoiceDesc2 = {
    Text = "【ละเลยมัน】"
  },
  Event_35934_Desc = {
    Text = "ในดินแดนลับแลที่ห่างไกล มีแสงเรืองรองจางๆ ที่ดึงดูดใจปรากฏขึ้น \n มันเปล่งประกายเหมือนแสงแดดที่สะท้อนบนผิวน้ำ ราวกับแสงดาวที่สั่นไหว หรือแสงของเทียนเล็กๆ ... \n ในขณะที่คุณคิดที่จะเข้าใกล้มัน แสงนั้นกลับหายไปอย่างกะทันหัน \n มันดูเหมือนจะดึงดูดคุณ เหมือนกับการดึงดูดของแมลงเม่าที่ใช้สัญชาตญาณในการมีชีวิตอยู่。"
  },
  Event_35934_Name = {
    Text = "กระพริบ"
  },
  Event_35935_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_35935_Desc = {
    Text = "ไปขบคิดเรื่องพวกนี้ มีประโยชน์อะไรล่ะ?\nคุณเป็นใบไม้ที่ลอยอยู่กลางอากาศ วายุแห่งชะตากรรมกำลังพาคุณไป แค่นั้นเอง。"
  },
  Event_35935_Name = {
    Text = "ชะตากรรมที่ผิดเพี้ยน"
  },
  Event_35936_ChoiceDesc1 = {
    Text = "【เยาะตัวเอง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_35936_ChoiceDesc2 = {
    Text = "【ถามจนถึงที่สุด】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」,「(Skill.Arg3)」"
  },
  Event_35936_ChoiceDesc3 = {
    Text = "【ไม่ต้องการคิดอีกแล้ว】ได้รับ 25 รอยดำ"
  },
  Event_35936_Desc = {
    Text = "ลมแห่งชีวิตพัดผ่านวิญญาณของคุณ ทำให้คุณถูกกวนในวังวนแห่งความเป็นจริง ถูกดึงเข้าสู่ความไม่รู้ที่เต็มไปด้วยหมอกหนา。\nคุณไม่สามารถต้านทานการตั้งคำถามกับเสียงในหัวของคุณได้ว่า：「นั่นคือฉันใช่ไหม?」"
  },
  Event_35936_Name = {
    Text = "ชะตากรรมที่ผิดเพี้ยน"
  },
  Event_36146_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36146_Desc = {
    Text = "เมอร์ฟี่ finalmente สังเกตเห็นสายตาของคุณ บางที มันอาจจะร้อนเกินไปจริงๆ \n เธอหายใจเข้าลึกหลายครั้ง และส่งเสียง 「ฮึ」 ออกมาจากจมูก สุดท้าย เธอได้จับมือกับเซเลสเทและตามมาที่หลังคุณอย่างแน่นหนา。"
  },
  Event_36146_Name = {
    Text = "การจัดการความปวด"
  },
  Event_36722_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36722_Desc = {
    Text = "ในชั่วขณะที่ปลายนิ้วสัมผัสกัน ความรู้สึกที่ซับซ้อนอย่างหนึ่งพลันแล่นเข้ามาในใจ—มันทั้งร้อนระอุและเย็นยะเยือก。\nวิญญาณที่ถูกลืมเลือนในโลก กำลังเห่าหอนเพื่อแสวงหาความเป็นนิรันดร์。"
  },
  Event_36722_Name = {
    Text = "อนุสาวรีย์แห่งความรู้ทางจิตวิญญาณ"
  },
  Event_36723_ChoiceDesc1 = {
    Text = "【แตะที่มัน】การตื่นรู้แบบสุ่ม 1 ร่างกายที่ปลุก ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_36723_ChoiceDesc2 = {
    Text = "【เข้าร่วมการหมุน】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_36723_Desc = {
    Text = "ในช่วงเวลาที่คุณก้าวออกไป ส่วนลึกของจิตใจได้แตกออกเป็นรอยแยกอย่างเงียบๆ กลิ่นอายลึกซึ้งที่ไม่สามารถบรรยายได้ลอยผ่านรอยแยก ทำให้จิตใจของคุณสั่นสะท้าน \nคุณรู้สึกว่าดาวเคราะห์เคออสสีเงินกำลังหมุนวนและเจริญเติบโตอยู่ภายในใจของคุณอย่างเงียบๆ。"
  },
  Event_36723_Name = {
    Text = "อนุสาวรีย์แห่งความรู้ทางจิตวิญญาณ"
  },
  Event_36724_ChoiceDesc1 = {
    Text = "【ตามทันพวกมัน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ส่งผล「(Skill.Arg2)」"
  },
  Event_36724_ChoiceDesc2 = {
    Text = "【ลูบพวกมัน】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」，「(Skill.Arg3)」"
  },
  Event_36724_ChoiceDesc3 = {
    Text = "【ไม่ไปรบกวน】ได้รับ 25 รอยดำ"
  },
  Event_36724_Desc = {
    Text = "หลังจากเลี้ยวเข้ามุมที่ไม่คาดคิด ภาพที่แปลกประหลาดได้ปรากฏขึ้นในมุมมองของคุณ\nเงาของแมวจำนวนหนึ่ง ปรากฏขึ้นและหายไป ล่องลอยอยู่ข้างผนังห้องที่เย็นชา."
  },
  Event_36724_Name = {
    Text = "แมวเรือ"
  },
  Event_36725_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36725_Desc = {
    Text = "「ความทรงจำ」ไม่ตอบสนอง พวกเขาแนบตัวอยู่กับผนังห้อง จ้องมองคุณราวกับถูกสะกด จนกว่าคุณจะเดินผ่านมุมถัดไป"
  },
  Event_36725_Name = {
    Text = "เจ้าของเรือโซนาเนียร์"
  },
  Event_36726_ChoiceDesc1 = {
    Text = "【เลี่ยงเส้นทาง】ลบการ์ดคำสั่ง 1 ใบ ได้รับรอยดำ Arg1"
  },
  Event_36726_ChoiceDesc2 = {
    Text = "【สอบถามเหตุผลที่จม】คัดลอกการ์ดคำสั่ง 1 ใบ ส่งผลกระทบ「(Skill.Arg1)」"
  },
  Event_36726_ChoiceDesc3 = {
    Text = "【ทักทายเพื่อนร่วมเรือ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_36726_Desc = {
    Text = "เดินอยู่บนทางไปยังห้องเครื่อง คุณได้พบกับบางอย่างที่ถูกตรึงอยู่ในดินแดนลับแลอีกครั้ง นั่นคือ「ความทรงจำ」\nพวกเขาไม่ใช่ผี แต่เป็นความห่วงใยของกัปตันเอลตันต่อสมาชิกลูกเรือที่จากไป。"
  },
  Event_36726_Name = {
    Text = "เจ้าของเรือโซนาเนียร์"
  },
  Event_36727_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36727_Desc = {
    Text = "「ความทรงจำ」หลุดออกจากผนังห้อง เขาบิดเบือนใบหน้าและส่งเสียงโหยหวนออกจากลำคอ\n——ประภาคาร.\n——ประภาคารที่โดดเดี่ยว นำพวกเขาเข้าสู่พายุ。"
  },
  Event_36727_Name = {
    Text = "เจ้าของเรือโซนาเนียร์"
  },
  Event_36728_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36728_Desc = {
    Text = "คุณเลือกที่จะติดตาม ตามเส้นทางที่จิตวิญญาณอันอ่อนโยนและเป็นอิสระได้วาดขึ้น แม้ข้างหน้าจะเป็นกับดักที่ความมืดทิ้งไว้ก็ตาม。"
  },
  Event_36728_Name = {
    Text = "แมวเรือ"
  },
  Event_36729_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36729_Desc = {
    Text = "อย่ารบกวนผู้ที่จากไป อย่ากวนความทรงจำที่หลับลึก。"
  },
  Event_36729_Name = {
    Text = "เจ้าของเรือโซนาเนียร์"
  },
  Event_36730_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36730_Desc = {
    Text = "คุณรู้สึกว่าจิตสำนึกเริ่มแยกตัว ค่อยๆ ถูกดึงออกจากร่างกาย.\nราวกับเห็นวิญญาณของตัวเองกำลังเต้นรำกับดาวเคราะห์ แล้วตกลงไปในเหวที่มองไม่เห็นอย่างหนักหน่วง...\nที่นั่นคือสุญญตาอย่างแท้จริง。"
  },
  Event_36730_Name = {
    Text = "อนุสาวรีย์แห่งความรู้ทางจิตวิญญาณ"
  },
  Event_36731_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36731_Desc = {
    Text = "ในฐานะที่เป็นสิ่งมีชีวิตที่อ่อนโยน พวกมันคือความปรารถนาที่ดินแดนลับแลนี้ไม่อนุญาต มันเป็นเพียงภาพลวงตาเท่านั้น \n แม้ว่าคุณจะเข้าใจสิ่งนี้ แต่ในใจของคุณยังคงมีคลื่นความอบอุ่นเกิดขึ้นเล็กน้อย。"
  },
  Event_36731_Name = {
    Text = "แมวเรือ"
  },
  Event_36732_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36732_Desc = {
    Text = "เงาของพวกมันมัวหมองราวกับภาพวาดที่ถูกกระแสเวลาและอวกาศซัดสาด จุดดำลึกดูเหมือนเมฆที่ลอยอยู่ในท้องฟ้ายามค่ำคืน แต่ดวงตาของพวกมันกลับเหมือนแสงระยิบระยับจากดวงดาวที่ห่างไกล เปล่งประกายความลี้ลับและลึกซึ้ง \nคุณไม่สามารถต้านทานเสน่ห์ของพวกมันได้ ยื่นมือไปสัมผัสกับความว่างเปล่า。"
  },
  Event_36732_Name = {
    Text = "แมวเรือ"
  },
  Event_36733_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36733_Desc = {
    Text = "คุณรู้ว่าคุณต้องก้าวไปข้างหน้า แม้จะเซหรือล้มก็ตาม"
  },
  Event_36733_Name = {
    Text = "ความเจ็บปวดทางร่างกาย"
  },
  Event_36734_ChoiceDesc1 = {
    Text = "【อัญเชิญเขา】เพิ่ม Arg1 HP"
  },
  Event_36734_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_36734_Desc = {
    Text = "ที่นี่เต็มไปด้วยความปรารถนาที่ซ่อนเร้นและความกลัวที่ไม่เคยสัมผัส เป็นภาพวาดที่อุดมไปด้วยความฝันและความทรงจำของเขาที่ถักทอเข้าด้วยกัน。"
  },
  Event_36734_Name = {
    Text = "การเปลี่ยนแปลงวิวัฒนาการ"
  },
  Event_36735_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36735_Desc = {
    Text = "「ผู้พิทักษ์ หากคุณไม่สามารถทนได้อีกต่อไป อย่าทนอยู่คนเดียว」\nคุณจะไม่หลีกหนีจากความเจ็บปวด เพราะมันเป็นส่วนหนึ่งของชีวิตที่แวบผ่านไป\nคุณจะไม่หลบหลีกจากเงามืดในยามค่ำคืน เพราะคุณไม่กลัวที่จะถูกความมืดนั้นกลืนกิน。"
  },
  Event_36735_Name = {
    Text = "ความเจ็บปวดทางร่างกาย"
  },
  Event_36736_ChoiceDesc1 = {
    Text = "【เรียกเขาต่อไป】เพิ่มชีวิต Arg1 และติดเชื้อ \"(Skill.Arg2)\""
  },
  Event_36736_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_36736_Desc = {
    Text = "ภาพวาดที่ไร้เดียงสาประกอบกันเป็นโลกนี้"
  },
  Event_36736_Name = {
    Text = "การเปลี่ยนแปลงวิวัฒนาการ"
  },
  Event_36737_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36737_Desc = {
    Text = "การสวดมนต์ของผู้เหยียบทะเลดังก้องอยู่ข้างหู บ้าคลั่งและขาดอากาศ\nแต่พวกมันจะไม่ส่งผลกระทบต่อเจตจำนงของคุณอย่างแน่นอน。"
  },
  Event_36737_Name = {
    Text = "จากทะเล"
  },
  Event_36738_ChoiceDesc1 = {
    Text = "【หยิบรูปภาพ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_36738_Desc = {
    Text = "การจ้องมองเหล่านี้มีความลึกซึ้งและใสสะอาด เหมือนแสงในมหาสมุทรลึก สว่างและอบอุ่น \n พวกมันไม่พูดจาและไม่ปรากฏตัว แต่คุณสามารถรู้สึกถึงการมีอยู่ของพวกมัน เหมือนกับสายลมที่พัดเบาๆ ในคืนฤดูร้อนที่ให้ความรู้สึกสบายใจ。"
  },
  Event_36738_Name = {
    Text = "การสอดแนมด้วยความดี"
  },
  Event_36739_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36739_Desc = {
    Text = "คุณบังคับตัวเองให้มุ่งความสนใจไปที่วิกฤตที่อยู่ตรงหน้า และบังคับตัวเองให้ละเลยความเจ็บปวดเหล่านั้นอย่างเด็ดขาด。"
  },
  Event_36739_Name = {
    Text = "ความเจ็บปวดทางร่างกาย"
  },
  Event_36740_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36740_Desc = {
    Text = "นั่นคือดั้งพริ้นท์ของชีวิต เป็นการพิสูจน์การมีอยู่ มันเล่าเรื่องราว แต่ท่ามกลางการทำลายล้างของพายุ มันค่อยๆ สูญเสียเสียงไป。"
  },
  Event_36740_Name = {
    Text = "ลาก่อน, อิคารัส"
  },
  Event_36741_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36741_Desc = {
    Text = "การจ้องมองเหล่านี้ลึกซึ้งและใสสะอาด เหมือนกับแสงในมหาสมุทรลึก สว่างและอบอุ่น \n พวกมันไม่พูดและไม่ปรากฏตัว แต่คุณสามารถรู้สึกถึงการมีอยู่ของพวกมัน เหมือนกับการปลอบประโลมของลมเบาๆ ในคืนฤดูร้อน。"
  },
  Event_36741_Name = {
