  },
  Event_36742_ChoiceDesc1 = {
    Text = "【การเรียกครั้งสุดท้าย】เพิ่มชีวิต Arg1 หน่วย ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_36742_ChoiceDesc2 = {
