  },
  Event_36742_Desc = {
    Text = "รอยร้าวของความทุกข์เป็นส่วนประกอบของโลกใบนี้"
  },
  Event_36742_Name = {
    Text = "การเปลี่ยนแปลงวิวัฒนาการ"
  },
  Event_36743_ChoiceDesc1 = {
    Text = "【โอบกอดความเจ็บปวด】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_36743_ChoiceDesc2 = {
    Text = "【ปฏิเสธความเจ็บปวด】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」และ「(Skill.Arg3)」"
