  Event_36743_ChoiceDesc3 = {
    Text = "【ละเลยความเจ็บปวด】ได้รับรอยดำ 25"
  },
  Event_36743_Desc = {
    Text = "ความเจ็บปวดเหมือนหินแข็งที่ฝังลึกในสมอง ความทุกข์ที่แพร่กระจายออกมาเหมือนเถาวัลย์ พันรอบทุกอณูของเส้นประสาท ทำให้จิตสำนึกของคุณบิดเบือน。"
  },
  Event_36743_Name = {
    Text = "ความเจ็บปวดทางร่างกาย"
  },
  Event_36744_ChoiceDesc1 = {
    Text = "【เรียกเขาอย่างแน่วแน่】เพิ่มชีวิต Arg1 ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_36744_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_36744_Desc = {
    Text = "ความปรารถนาที่จะได้รับการยอมรับสร้างโลกนี้ขึ้น"
  },
  Event_36744_Name = {
    Text = "การเปลี่ยนแปลงวิวัฒนาการ"
  },
  Event_36745_ChoiceDesc1 = {
    Text = "【จ้องมองพวกมัน】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_36745_ChoiceDesc2 = {
    Text = "【ขอความช่วยเหลือจากพวกมัน】ติดเชื้อ「(Skill.Arg1)」，เปลี่ยนการแกะสลักที่ได้รับจากตัวเลือก 1 ใช้ได้ 2 ครั้ง"
  },
  Event_36745_Desc = {
    Text = "ในสีสันที่ไหลเวียนในดินแดนลับแล คุณรู้สึกถึงการจ้องมองที่ลึกลับ มันคือดวงตาที่มองไม่เห็นซึ่งซ่อนอยู่ในรอยพับที่ลึกลับของดินแดนลับแลนี้ \n ในช่วงเวลาที่พวกมันมองมาที่คุณ ความปรารถนาที่รุนแรงก็พลุ่งพล่านขึ้นในใจของคุณ。"
  },
  Event_36745_Name = {
    Text = "การสอดแนมด้วยความดี"
  },
  Event_36746_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36746_Desc = {
    Text = "ถ้าคุณไม่พยายามเข้าใจมัน คุณจะไม่สามารถออกจากนรกที่วุ่นวายนี้ได้ \n เมื่อดวงดาวสะท้อนบนผิวน้ำ ความปรารถนาและคำขอที่กระตุ้นใจเหล่านั้น คำอธิษฐานก็เหมือนฟองสบู่ ค่อยๆ ลอยขึ้นสู่ผิวน้ำ แต่กลับถูกความมืดกลืนกินโดยไม่รู้ตัว。"
  },
  Event_36746_Name = {
    Text = "จากทะเล"
  },
  Event_36747_ChoiceDesc1 = {
    Text = "【เรียกหาเขาด้วยความร้อนใจ】เพิ่มชีวิต Arg1 หน่วย ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_36747_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_36747_Desc = {
    Text = "คำพูดที่ชั่วร้ายประกอบขึ้นเป็นโลกนี้"
  },
  Event_36747_Name = {
    Text = "การเปลี่ยนแปลงวิวัฒนาการ"
  },
  Event_36748_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36748_Desc = {
    Text = "เธอยืนอยู่ตรงหน้าเขา มองเห็นวิญญาณของเขาถูกความทรงจำประหลาดกลืนกิน"
  },
  Event_36748_Name = {
    Text = "การเปลี่ยนแปลงวิวัฒนาการ"
  },
  Event_36749_ChoiceDesc1 = {
    Text = "【นั่นคือน้ำตา】ลบการ์ด 1 ใบ"
  },
  Event_36749_ChoiceDesc2 = {
    Text = "【นั่นคือเลือด】ได้รับ「(RelicConfig.Arg1)」และติดเชื้อ「(Skill.Arg2)」"
  },
  Event_36749_Desc = {
    Text = "หยดของเหลวไม่กี่หยดกระจายไปบนดาดฟ้าอย่างไร้ขีดจำกัด ไหลตามรอยแยกของดาดฟ้าอย่างเงียบงัน\nรอยเหล่านั้นเบาและมุ่งมั่น ทุกๆ รอยเปียกมีความหมายที่เด็ดขาด ในเสียงคำรามของลมทะเลและเสียงครวญครางของเรือใบ สร้างภาพที่ผสมผสานระหว่างชีวิตและความตาย ความสงบและความวุ่นวาย。"
  },
  Event_36749_Name = {
    Text = "ลาก่อน, อิคารัส"
  },
  Event_36750_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36750_Desc = {
    Text = "คุณจ้องมองจุดที่ค่อยๆ แพร่กระจาย พยายามที่จะจำแนกเอกลักษณ์ของมัน แต่ในขอบเขตที่โลกและฟ้าประสานกัน ความแตกต่างระหว่างน้ำฝนและเลือดกลับกลายเป็นไม่ชัดเจน\nพวกมันคือ น้ำฝนใช่ไหม? หรือเป็นน้ำตาของมหาสมุทร? \nคุณไม่รู้。"
  },
  Event_36750_Name = {
    Text = "ลาก่อน, อิคารัส"
  },
  Event_36751_ChoiceDesc1 = {
    Text = "【ปฏิเสธความถี่เดียวกัน】ได้รับสิ่งประดิษฐ์เงิน เลือก 1 จาก 3"
  },
  Event_36751_ChoiceDesc2 = {
    Text = "【เข้าร่วมความถี่เดียวกัน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」，ติดเชื้อซ้ำสองครั้ง「(Skill.Arg3)」"
  },
  Event_36751_Desc = {
    Text = "เสียงกระซิบของผู้เหยียบทะเลและจังหวะการเต้นของหัวใจของ「เด็กศักดิ์สิทธิ์」ประสานกันเป็นซิมโฟนีที่ซ่อนเร้น ทุกการสั่นสะเทือนทำให้จักรวาลของเหลวอันไร้ขอบเขตเกิดเสียงเห่าหอนขึ้น。"
  },
  Event_36751_Name = {
    Text = "จากทะเล"
  },
  Event_36752_ChoiceDesc1 = {
    Text = "【หยิบรูปภาพ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_36752_ChoiceDesc2 = {
    Text = "【ตรวจสอบฟิล์ม】ติดเชื้อ「(Skill.Arg1)」，เปลี่ยนการแกะสลักที่ได้รับจากตัวเลือก 1 สามารถใช้งานได้อีกครั้งหนึ่ง"
  },
  Event_36752_Desc = {
    Text = "พวกมันไม่มีเจตนาร้าย ความรู้สึกนี้เหมือนสัญชาตญาณ ฝังลึกอยู่ในกระดูกและเลือดของคุณ \n ดังนั้นคุณจึงปล่อยความระมัดระวังและพยายามขอความช่วยเหลือจากผู้เฝ้าดูที่ซ่อนเร้นเหล่านี้: บอกเล่าความสับสนและความปรารถนาของคุณให้กับสิ่งที่เลือนรางนั้น เหมือนกับการพูดคุยกับเพื่อนเก่าอย่างจริงใจ。"
  },
  Event_36752_Name = {
    Text = "การสอดแนมด้วยความดี"
  },
  Event_36874_ChoiceDesc1 = {
    Text = "【เล่าเรื่องสนุกๆ ของโรงเรียน】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」"
  },
  Event_36874_ChoiceDesc2 = {
    Text = "【ไม่เคยไปโรงเรียน】ได้รับ 75 รอยดำ, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_36874_Desc = {
    Text = "เมื่อเดินผ่านซากปรักหักพัง ออรีตาก็สดใสขึ้นมาทันที\n「คุณยายบอกว่าสถานที่นี้เคยเป็นโรงเรียน แต่เพราะไม่มีนักเรียน มันจึงถูกทิ้งร้างไปนานแล้ว!」\n「ออรีตาไม่เคยไปโรงเรียน แล้วเพื่อนล่ะ? คุณเคยไปโรงเรียนไหม?」"
  },
  Event_36874_Name = {
    Text = "ความสุขที่สูญเสียไป"
  },
  Event_36875_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36875_Desc = {
    Text = "เมื่อได้คำตอบปฏิเสธจากคุณ ออริตาก็ส่ายหัวอย่างไม่พอใจ\n「ที่แท้ โลกข้างนอกก็ไม่มีนักเรียน... แล้วทำไมถึงสร้างโรงเรียนขึ้นมาตั้งแต่แรก?」"
  },
  Event_36875_Name = {
    Text = "ความสุขที่สูญเสียไป"
  },
  Event_36876_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36876_Desc = {
    Text = "「บ้านคนจน หนูตัวเล็ก หุ่นขี้ผึ้ง... เยี่ยมเลย! การผจญภัย การผจญภัย!」\nออรีตาพูดพร้อมกับมีเครื่องหมายคำถามล่องลอยอยู่เหนือศีรษะ\n「แต่คุณยายบอกว่าโรงเรียนเป็นสถานที่ที่จะทำให้ออรีตาฉลาดขึ้น แต่...」\nก่อนที่ออรีตาจะคิดต่อ คุณจึงผลักเธอเดินผ่านมุมอีกมุมหนึ่ง。"
  },
  Event_36876_Name = {
    Text = "ความสุขที่สูญเสียไป"
  },
  Event_36877_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36877_Desc = {
    Text = "「ทำไม,ทำไมกัน?」\nออริตาตกใจจากคุณ ทำหน้าตึงแล้วสั่งคุณต่อไป。\n「ที่นี่คือบ้านของออริตา ออริตารู้ว่า จัตุรัส——อยู่ข้างในนั่น!」"
  },
  Event_36877_Name = {
    Text = "ความมืดที่มองไม่เห็น"
  },
  Event_36878_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36878_Desc = {
    Text = "「ฉันไม่อยากเดินทางนี้ ออรีตารู้วิธีอื่นไปยังจัตุรัสไหม?」\nออรีตาทำหน้าบึ้ง รู้สึกงงๆ แต่สุดท้ายก็จับผ้าคลุมของคุณแล้วสั่งให้ไปทางอื่น。"
  },
  Event_36878_Name = {
    Text = "ความมืดที่มองไม่เห็น"
  },
  Event_36879_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_36879_Desc = {
    Text = "นี่คือความฝัน นี่เป็นเพียงความฝัน\nคุณบอกตัวเองซ้ำแล้วซ้ำเล่า หรือพูดอีกอย่างคือปลอบใจตัวเอง นำออรีตาเข้าไปในความมืดที่มองไม่เห็น。"
  },
  Event_36879_Name = {
    Text = "ความมืดที่มองไม่เห็น"
  },
  Event_36880_ChoiceDesc1 = {
    Text = "【ทำตามเธอ】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_36880_ChoiceDesc2 = {
    Text = "【คัดค้านเธอ】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น และติดเชื้อทักษะ「(Skill.Arg1)」"
  },
  Event_36880_ChoiceDesc3 = {
    Text = "【พูดคุยกับเธอ】ได้รับ 25 รอยดำ"
  },
  Event_36880_Desc = {
    Text = "ออรีตาจับผ้าคลุมของคุณและก้าวเดินตามรอยเท้าของคุณไปข้างหน้า\n「อ๊ะ……ผิดแล้ว! จัตุรัสอยู่ทางนั้น!」\nคุณหันไปมองทิศทางที่ออรีตาชี้ไป ในดินแดนลับแลนั้นซอยต่างๆ กลับมืดมิดอย่างเห็นได้ชัด เมือก D และมิวแทนต์กำลังขยับตัวพันกันอย่างยุ่งเหยิง ดึงเอาโลกแห่งความเป็นจริงลงไปสู่เหวลึกที่ล่มสลาย。"
  },
  Event_36880_Name = {
    Text = "ความมืดที่มองไม่เห็น"
  },
  Event_37983_ChoiceDesc1 = {
    Text = "【รับเงินทุน】ได้รับ Arg1 รอยดำ。"
  },
  Event_37983_ChoiceDesc2 = {
    Text = "【รับเงินทุน】ได้รับ Arg1 รอยดำ[ExDesc1]。"
  },
  Event_37983_Desc = {
    Text = "「ไม่มีเจ้านายคนไหนจะปล่อยให้คนแปลกหน้าที่ไม่รู้ที่มาหมดไป โดยเฉพาะอย่างยิ่งนักพรต」\nราชินีนั่งอยู่บนบัลลังก์สูงสุด สายตาของเธอแวบไปด้วยความโหดร้าย\n「พิสูจน์ว่าคุณยังมีประโยชน์อย่างอื่น มิฉะนั้น...」\nประโยชน์อื่น? คุณมองออกไปยังทุ่งนาที่แห้งแล้ง ข้อคิดหนึ่งผุดขึ้นในใจ: บางทีอาจจะใช้ความรู้ด้านเศรษฐศาสตร์ที่เรียนมา ช่วยวานด้าจัดการฟาร์ม? \nคุณพยายามขุดค้นในสมองที่แห้งแล้งและเรียบง่าย—ต้องรู้ว่าในมิซากะ เศรษฐศาสตร์เป็นเพียงวิชาเลือกที่ไม่เด่น\nความอดทนหมดลง ราชินีหาวออกมา\n「น่าผิดหวัง ปล่อย—」\nในวินาทีที่มีดหล่นลง อดัม สมิธ, มัลธัส, ดาวิด ริคาร์โด และวิญญาณผู้ยิ่งใหญ่หลายคนต่างก็ปรากฏขึ้นในสมองเล็กๆ ของคุณ\nการแบ่งงาน! การเก็บภาษี! ประชากร, ประชากรที่น่าสะอิดสะเอียน!\nคุณอาจจะ, อาจจะนึกออกแล้ว。"
  },
  Event_37983_Name = {
    Text = "คำสั่งลับแทนหน้าที่"
  },
  Event_37984_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_37984_Desc = {
    Text = "คุณกัดฟันออกคำสั่งทางการ。\nราชินีมองผ่านๆ อย่างรวดเร็วแล้วเผยยิ้มเย็นชา：\n「ถ้าไม่มีประโยชน์ คุณรู้ไหมว่าจะเกิดอะไรขึ้น。」"
  },
  Event_37984_Name = {
    Text = "คำสั่งลับแทนหน้าที่"
  },
  Event_37985_ChoiceDesc1 = {
    Text = "【ออกคำสั่ง】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」"
  },
  Event_37985_ChoiceDesc2 = {
    Text = "【ออกคำสั่ง】ได้รับสิ่งสาปสร้าง「(RelicConfig.Arg1)」"
  },
  Event_37985_ChoiceDesc3 = {
    Text = "【ออกคำสั่ง】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_37985_Desc = {
    Text = "「รับเงินของฉันแล้ว ก็ต้องทำงานแทนฉัน」\nราชินีวางมือข้างหนึ่งบนคาง มองคุณอย่างไม่ใส่ใจ\nไม่ว่าจะยอมรับหรือไม่ เธอก็มีความอยากรู้เกี่ยวกับเรื่องนี้จริงๆ\n「งั้น บอกแผนของคุณให้ฉันฟังหน่อยสิ นักปฏิวัติใหญ่」"
  },
  Event_37985_Name = {
    Text = "คำสั่งลับแทนหน้าที่"
  },
  Event_38700_ChoiceDesc1 = {
    Text = "【เชื่อมต่อ】ฟื้นฟูพลังชีวิตจำนวน Arg2 หน่วย[ExDesc1]。"
  },
  Event_38700_ChoiceDesc2 = {
    Text = "【การตื่นรู้】เลือกปลุกผู้ตื่น 1 ตน。"
  },
  Event_38700_ChoiceDesc3 = {
    Text = "【กำจัด】ลบการ์ดอาการได้สูงสุด 3 ใบ ได้รับ Arg2 รอยดำ。"
  },
  Event_38700_Desc = {
    Text = "คุณกำลังสำรวจในหมอก มันกะทันหัน ตราสัญลักษณ์ที่หน้าอกปล่อยแสงสีเงินอ่อนๆ ใครกันที่เรียกคุณจากเครื่องสื่อสาร?"
  },
  Event_38700_Name = {
    Text = "จุดติดต่อ"
  },
  Event_38700_Tips3 = {
    Text = "ขณะนี้คุณยังไม่มีการ์ดอาการ"
  },
  Event_38707_ChoiceDesc1 = {
    Text = "【ขจัดภาพลวง】อาการติดเชื้อ。"
  },
  Event_38707_ChoiceDesc2 = {
    Text = "【ดูดซึมภาพลวง】สูญเสียArg1ชีวิต ได้รับArg2รอยดำ"
  },
  Event_38707_ChoiceDesc3 = {
    Text = "【ออกจาก】"
  },
  Event_38707_Desc = {
    Text = "ใบหน้าที่เลือนรางปรากฏขึ้นอย่างกะทันหัน มันล้อมรอบคุณอยู่ ใช้สายเสียงที่ไม่มีอยู่จริงคร่ำครวญอย่างสิ้นหวัง。"
  },
  Event_38707_Name = {
    Text = "ภาพลวง"
  },
  Event_38715_ChoiceDesc1 = {
    Text = "【ออกคำสั่ง】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」"
  },
  Event_38715_ChoiceDesc2 = {
    Text = "【ออกคำสั่ง】ได้รับสิ่งสาปสร้าง「(RelicConfig.Arg1)」"
  },
  Event_38715_ChoiceDesc3 = {
    Text = "【ออกคำสั่ง】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_38715_Desc = {
    Text = "「รับเงินของฉันแล้ว ก็ต้องทำงานให้ฉัน」\nราชินีวางมือข้างหนึ่งบนคาง มองคุณอย่างไม่ใส่ใจ\nไม่ว่าจะยอมรับหรือไม่ เธอก็มีความสนใจในเรื่องนี้\n「แล้ว บอกแผนของคุณให้ฉันฟังหน่อยสิ นักปฏิรูปใหญ่」"
  },
  Event_38715_Name = {
    Text = "คำสั่งลับแทนหน้าที่"
  },
  Event_40452_ChoiceDesc1 = {
    Text = "【ถามถึงตัวตน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_40452_ChoiceDesc2 = {
    Text = "【ออก】การ์ดคำสั่ง 3 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_40452_Desc = {
    Text = "วิญญาณสามตนขวางทางเดินหน้าไว้\nพวกเขาล้อมรอบโต๊ะพนัน ตั้งใจจดจ้องไปที่การเคลื่อนไหวของลูกเต๋า\n「กลิ้ง กลิ้ง」\nลูกเต๋าถูกโยนขึ้นและตกลงนับครั้งไม่ถ้วน\nนี่คือเกมการพนันที่ไม่มีที่สิ้นสุด。"
  },
  Event_40452_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_40453_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_40453_Desc = {
    Text = "「สวัสดีครับ เราคือสามีคนที่หนึ่ง คนที่สอง และคนที่สามของวานด้า」\n「อะไรนะ คุณถามว่าสามีคนที่สี่อยู่ไหนเหรอ?\nอืม... เอาจริงๆ จอห์นขาดอารมณ์ขันนิดหน่อย ดังนั้นเลยถูกคุณนายเปลี่ยนเป็นพนักงานตาบอด」\n「พวกเรารู้สึกเสียดายที่สูญเสียเขา แน่นอน แค่เล็กน้อยเท่านั้น」"
  },
  Event_40453_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_40454_ChoiceDesc1 = {
    Text = "【จับมือกับมัน】สุ่มการตื่นรู้ร่างกายที่ตื่นขึ้น 1 ราย ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_40454_ChoiceDesc2 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_40454_Desc = {
    Text = "ขณะเดินผ่านกรง แขนหนึ่งยื่นออกมาจากด้านใน\n「อย่าไปจากฉัน รีเบคกา...」\nเสียงฟังดูแก่และแห้งเหี่ยว เหมือนกับพัดลมเก่าที่ชำรุด。"
  },
  Event_40454_Name = {
    Text = "นักโทษ"
  },
  Event_40455_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_40455_Desc = {
    Text = "ฝ่ามือสัมผัสได้ถึงความเหนียวหนืด——เป็นเมือก D\nเจ้าของเสียงไม่รู้ว่าเมื่อไหร่ได้หายไปแล้ว ซ่อนตัวอยู่ในมุมมืดที่เต็มไปด้วยความซึมเศร้า。"
  },
  Event_40455_Name = {
    Text = "นักโทษ"
  },
  Event_40456_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_40456_Desc = {
    Text = "คุณจากไปอย่างไม่สนใจ จึงพลาดเรื่องราวที่เต็มไปด้วยละครเบื้องหลังของกระดาษเขียนจดหมายแผ่นนั้น \n แต่จะมีความสำคัญอะไรล่ะ? \n มหาสมุทรอันกว้างใหญ่ รุ่งอรุณและพระอาทิตย์ตก ทะเลทรายเส้นศูนย์สูตร... \n คุณจะได้พบเจอมากขึ้น และก็จะพลาดมากขึ้นเช่นกัน。"
  },
  Event_40456_Name = {
    Text = "แด่ภรรยาที่รัก"
  },
  Event_40457_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_40457_Desc = {
    Text = "ในแง่หนึ่ง คุณก็ไม่ต่างอะไรจากนักโทษคนนี้ \n ตอนนี้ยังไม่ถึงเวลาที่จะทำให้พวกมันตกใจ \n คุณเมินคำวิงวอนของนักโทษแล้วหันหลังเดินจากไป。"
  },
  Event_40457_Name = {
    Text = "นักโทษ"
  },
  Event_40458_ChoiceDesc1 = {
    Text = "【ฉีกกระดาษ】เลือกสิ่งสร้าง 1 ชิ้นเปลี่ยนเป็นสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」"
  },
  Event_40458_ChoiceDesc2 = {
    Text = "【ละเว้นจดหมาย】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อทางเวทมนตร์「(Skill.Arg2)」"
  },
  Event_40458_ChoiceDesc3 = {
    Text = "【จดหมายตอบกลับ】ได้รับ 25 รอยดำ"
  },
  Event_40458_Desc = {
    Text = "Ⅰ.จดหมาย  จอห์น แคมเบรียน ถึงแวนด้า (ยุคก่อนคัมเบรียน @2 ปี)\n\nสามีมีสิทธิ์ในการจัดการกับภรรยาของตัวเอง อย่างน้อยที่สุดในยุคแคมเบรียน\nแต่ดูเหมือนฉันจะประเมินความวิกลจริตของเธอต่ำเกินไป ตอนนี้ตาของฉันแทบจะมองไม่เห็น และแขนขาก็กำลังจะถูกตัดขาดในไม่ช้า\nลูกสาวของปีศาจ ลูกสาวของปีศาจ... ไม่ เธอคือตัวปีศาจเอง\nฉันสาปแช่งเธอ@1 สาปแช่งเธอ@2 สาปแช่งเธอ สาปแช่งเธอ..."
  },
  Event_40458_Name = {
    Text = "แด่ภรรยาที่รัก"
  },
  Event_40459_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_40459_Desc = {
    Text = "คุณใช้วิธีที่เรียบง่ายที่สุดในการคลายคำสาป \n ไม่มีอะไรเกิดขึ้น กระดาษแผ่นนั้นตกลงสู่พื้นอย่างไร้ชีวิตชีวา \n คุณยกไหล่แล้วจากไป แต่ในใจกลับรู้สึกว่ามีบางอย่างไม่ชอบมาพากล。"
  },
  Event_40459_Name = {
    Text = "แด่ภรรยาที่รัก"
  },
  Event_40460_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_40460_Desc = {
    Text = "คุณเดินผ่านโต๊ะเดิมพันอย่างไม่สนใจอะไร \n ก่อนจะจากไป ผีทั้งหลายพูดพร้อมกันว่า: \n「กรุณาส่งคำทักทายถึงอดีตภรรยาของเราทั้งสองคน คุณวานด้า」"
  },
  Event_40460_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_40461_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_40461_Desc = {
    Text = "คุณเขียนจดหมายตอบกลับอย่างเรียบร้อยที่ปลายกระดาษเขียนจดหมาย：\n「ได้รับคำสาปแล้ว ขอให้ทุกอย่างเป็นไปด้วยดี。」\nในช่วงเวลาที่ปากกาลงหมึกสุดท้าย กระดาษเขียนจดหมายก็เกิดไฟสีฟ้าที่เต็มไปด้วยความโกรธขึ้นมา。\nคุณได้เก็บเกี่ยวเถ้าถ่าน。"
  },
  Event_40461_Name = {
    Text = "แด่ภรรยาที่รัก"
  },
  Event_44187_ChoiceDesc1 = {
    Text = "【เผชิญหน้ากับความมืด】[ExDesc1][ExDesc2]"
  },
  Event_44187_ChoiceDesc2 = {
    Text = "【เผชิญหน้ากับความมืด】[ExDesc1][ExDesc2]"
  },
  Event_44187_ChoiceDesc3 = {
    Text = "【หลีกเลี่ยงความมืด】ได้รับสิ่งสร้างทองคำแบบสุ่ม"
  },
  Event_44187_Desc = {
    Text = "วิญญาณตรงหน้าคุณมืดมัวและแปดเปื้อน——แสงสว่างและความมืดมีอยู่ในตัวมันพร้อมกัน ทั้งสองฝ่ายชิงชัยกันเพื่อความเป็นใหญ่ ขณะที่วิญญาณกลับตกอยู่ในความสับสน \n「ฉันรู้สึกเห็นใจพวกเขา คนที่สูญเสียทุกอย่าง แต่โลกนี้ไม่เป็นเช่นนั้นหรือ? \n「เมื่อมีคนได้ ก็ต้องมีคนสูญเสีย \n「หรือว่าต้องยอมสละความสุขของตัวเองเพื่อความสุขของคนอื่น?」"
  },
  Event_44187_Name = {
    Text = "ความมืดในใจ"
  },
  Event_44188_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_44188_Desc = {
    Text = "「นี่คือบาปของข้า คือภาระของข้า ข้าจะช่วยให้ท่านรอดได้อย่างไร วิญญาณที่ขัดแย้งของข้า?」"
  },
  Event_44188_Name = {
    Text = "ความมืดในใจ"
  },
  Event_44299_ChoiceDesc1 = {
    Text = "【ขอพรจากบิชอป】ชำระล้างสิ่งสร้างที่มีความผิด หากไม่มีสิ่งสร้างที่มีความผิด จะได้รับสิ่งประดิษฐ์ทองคำแบบสุ่ม。"
  },
  Event_44299_Desc = {
    Text = "「ฉันได้หลอกลวงและชิงทรัพย์ จนได้ชีวิตที่ต้องการ——เงินกลายเป็นแค่ตัวเลข อาหารเลิศรสกลายเป็นอาหารบ้านๆ ในการทำธุรกิจฉันพูดแล้วต้องทำตาม ในการเมืองฉันมีอำนาจที่เข้มแข็ง แต่ทำไม ทำไมฉันถึงลืมคนเหล่านั้นไม่ได้ คนที่ฉันแย่งชิงทุกสิ่งจากพวกเขา? ทำไมฉันถึงลืมความสิ้นหวังบนใบหน้าของพวกเขาไม่ได้? \n「แอลกอฮอล์ให้การหลบหนีเพียงชั่วคราว วิญญาณของฉันกำลังถูกฉีกออก และความเจ็บปวดเกือบจะกลืนกินฉันไป \n「ฉันควรทำอย่างไรดี?」"
  },
  Event_44299_Name = {
    Text = "ความรู้สึกผิดและการอภัย"
  },
  Event_44301_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_44301_Desc = {
    Text = "「ท่านเดินอยู่บนเส้นทางแห่งความทุกข์ ท่านได้หลงทางจากพระสิริของพ่อพระ。\n「กลับมาเถิด ลูกแกะที่หลงทาง จงฟังคำสอนของพ่อพระ และเดินไปบนเส้นทางที่ถูกต้อง」"
  },
  Event_44301_Name = {
    Text = "ความรู้สึกผิดและการอภัย"
  },
  Event_44395_ChoiceDesc1 = {
    Text = "【ขอสิ่งภายนอก】 พระสงฆ์จะรับการติดเชื้ออาการ 1 ใบ หากไม่มีอาการจะได้รับสัญลักษณ์ดำโดยตรง Arg1"
  },
  Event_44395_ChoiceDesc2 = {
    Text = "【การขอเลือด】บิชอปยอมรับอาการ ๒ ใบของคุณ คุณได้รับการแกะสลัก「(EnchantConfig.Arg1)」。"
  },
  Event_44395_ChoiceDesc3 = {
    Text = "【ขอเพิ่มเติม】บิชอปยอมรับอาการมากขึ้น (อย่างน้อย 4 ใบ)"
  },
  Event_44395_Desc = {
    Text = "วิญญาณที่ไม่เป็นจริงปรากฏเป็นรูปร่างที่เลือนลาง มันคุกเข่าต่อหน้าบิชอป แสดงให้เห็นร่างกายที่ชำรุดและจิตใจที่เต็มไปด้วยความมืดมน \n「ท่านได้มอบคำชี้แนะให้แก่ข้า มอบการอภัยให้แก่ข้า มอบการไถ่บาปให้แก่ข้า แต่บิชอปผู้ทรงเมตตา นี่มันยังไม่เพียงพอ \n「ข้าถูกความยากจนและโรคภัยรุมเร้า ชีวิตของข้าตกอยู่ในอันตราย และท่านคือการไถ่บาปเพียงหนึ่งเดียวของข้า ช่วยฉันด้วยเถอะ บิชอป ให้ข้าพ้นจากความทุกข์นี้」"
  },
  Event_44395_Name = {
    Text = "พรของพระสังฆราช"
  },
  Event_44396_ChoiceDesc1 = {
    Text = "【โค้งคำนับและจากไป】"
  },
  Event_44396_Desc = {
    Text = "บิชอปถอดแหวนออกและถอดเข็มกลัดออก อัญมณีสีน้ำเงินที่เป็นสัญลักษณ์ของพ่อพระถูกวางลงในมือของวิญญาณทีละชิ้น บิชอปโน้มตัวลงและจับมือของวิญญาณที่น่าสงสารไว้\n「เอาเงินทองจากตัวฉันไป เอาทรัพย์สินทั้งหมดของฉันไป——ขอแค่สิ่งนั้นคือสิ่งที่เธอต้องการ ฉันมีคำสอนของพ่อพระก็เพียงพอสำหรับการดำรงชีวิต」"
  },
  Event_44396_Name = {
    Text = "พรของพระสังฆราช"
  },
  Event_44400_ChoiceDesc1 = {
    Text = "【จมอยู่ในนั้น】ติดเชื้อ「(Skill.Arg1)」，การตื่นรู้ปลุกร่างกายที่ตื่นขึ้นแบบสุ่ม"
  },
  Event_44400_ChoiceDesc2 = {
    Text = "【ยอมแพ้】"
  },
  Event_44400_Desc = {
    Text = "วิญญาณที่หลงทางไม่ยอมปล่อยความมืด。\nคุณรู้ว่าอะไรที่รออยู่สำหรับมัน ชีวิตที่ไร้สาระกำลังจะเริ่มขึ้น และคุณคือผู้ชมเพียงคนเดียว。"
  },
  Event_44400_Name = {
    Text = "ความมืดในใจ"
  },
  Event_44401_ChoiceDesc1 = {
    Text = "【มือไวตาไว】ได้รับ Arg1 รอยดำ"
  },
  Event_44401_ChoiceDesc2 = {
    Text = "【การยึดครองอย่างไม่ยั้ง】ได้รับการแกะสลักขั้นสูง เลือก 1 จาก 3，ติดเชื้อ「(Skill.Arg1)」。"
  },
  Event_44401_Desc = {
    Text = "ตราดำที่ค้นพบในดินแดนลับแล สามารถบูชายัญให้กับรอยละลายเพื่อแลกเปลี่ยนเรลิกและการสะท้อนทางจิตวิญญาณอื่น ๆ จะหายไปเป็นลาวาสีดำอย่างรวดเร็วหลังจากออกจากพื้นที่ปัจจุบัน。"
  },
  Event_44401_Name = {
    Text = "รอยดำ"
  },
  Event_44407_ChoiceDesc1 = {
    Text = "【ขจัดภาพลวง】อาการติดเชื้อ。"
  },
  Event_44407_ChoiceDesc2 = {
    Text = "【โอบกอดความหลอกลวง】ได้รับการ์ดอาการสุ่ม 2 ใบ และได้รับรอยดำ Arg1"
  },
  Event_44407_ChoiceDesc3 = {
    Text = "【ออกจาก】"
  },
  Event_44407_Desc = {
    Text = "ใบหน้าที่เลือนลางปรากฏขึ้นอย่างกะทันหัน มันล้อมรอบคุณอยู่ ใช้สายเสียงที่ไม่มีอยู่จริงคร่ำครวญอย่างสิ้นหวัง。"
  },
  Event_44407_Name = {
    Text = "ภาพลวง"
  },
  Event_44445_ChoiceDesc1 = {
    Text = "【ออก】ค้นหาไฟส่องสว่าง"
  },
  Event_44445_ChoiceDesc2 = {
    Text = "【บุกเข้าหมอก】เสียชีวิต Arg2 จุด"
  },
  Event_44445_ChoiceDesc3 = {
    Text = "【ละทิ้งสิ่งภายนอก】หัก 5 รอยดำ ได้รับ 1 ใบ「แรงบันดาลใจ」"
  },
  Event_44445_Desc = {
    Text = "ข้างหน้าคือหมอกสีดำหนาแน่น การเข้าไปโดยไม่ระวังจะนำมาซึ่งภัยพิบัติ。\nบางทีคุณควรหาฟ้าส่องสว่างเพื่อขับไล่หมอกออกไป。"
  },
  Event_44445_Name = {
    Text = "ไม่รู้จัก"
  },
  Event_44469_ChoiceDesc1 = {
    Text = "【การขอเนื้อหนัง】บิชอปยอมรับอาการของคุณ 4 ใบ คุณได้รับสิ่งประดิษฐ์ทองคำแบบเลือก 1 ใน 3+"
  },
  Event_44469_ChoiceDesc2 = {
    Text = "【ขอรับพร】บิชอปยอมรับอาการ 6 ใบของคุณ คุณได้รับลูกตุ้มเวลาแบบเลือก 3 ต่อ 1。"
  },
  Event_44469_ChoiceDesc3 = {
    Text = "【กลับ】"
  },
  Event_44469_Desc = {
    Text = "วิญญาณที่หลอกลวงก่อตัวเป็นรูปร่างที่คลุมเครือ มันคุกเข่าต่อหน้าบิชอปแสดงให้เห็นร่างกายที่แตกสลายและจิตใจที่เต็มไปด้วยสีดำ \n「ท่านได้มอบคำชี้แนะให้ข้า มอบการอภัยให้ข้า มอบการไถ่บาปให้ข้า แต่บิชอปผู้ทรงเมตตา อันนี้ยังไม่เพียงพอ \n「ข้าตกอยู่ในความยากจน โรคภัยรุมเร้า ชีวิตของข้าตกอยู่ในอันตราย และท่านคือการไถ่บาปเพียงหนึ่งเดียวของข้า ช่วยฉันด้วย บิชอป ให้ข้าหมดทุกข์เสียที」"
  },
  Event_44469_Name = {
    Text = "พรของพระสังฆราช"
  },
  Event_44474_ChoiceDesc1 = {
    Text = "【คำขอ】รับพรจากบิชอป"
  },
  Event_44474_ChoiceDesc2 = {
    Text = "【คำขอ】รับพรจากบิชอป"
  },
  Event_44474_ChoiceDesc3 = {
    Text = "【ออกจาก】"
  },
  Event_44474_Desc = {
    Text = "「นี่คือบาปของข้า คือภาระของข้า ข้าจะช่วยให้ท่านรอดได้อย่างไร วิญญาณที่ขัดแย้งของข้า?」"
  },
  Event_44474_Name = {
    Text = "ความมืดในใจ"
  },
  Event_44911_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_44911_Desc = {
    Text = "「ทุกสิ่ง ทุกอย่าง... ใช่ ฉันต้องการทุกสิ่ง...!」\nวิญญาณยื่นมือออกไป พยายามอย่างไร้ประโยชน์ที่จะคว้าในอากาศ.\nมันได้รับอะไรบางอย่าง แต่ก็ไม่ได้อะไรเลย。"
  },
  Event_44911_Name = {
    Text = "คุณได้รับอะไร"
  },
  Event_44913_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_44913_Desc = {
    Text = "「ดังนั้นเพียงแค่สิ่งที่สำคัญที่สุด สิ่งที่สำคัญที่สุด...」\nวิญญาณย่อตัวลง ขุดค้นความปรารถนาที่สดใสจากดินที่ว่างเปล่าและถือมันไว้ในมือ。"
  },
  Event_44913_Name = {
    Text = "คุณได้รับอะไร"
  },
  Event_44916_ChoiceDesc1 = {
    Text = "【คว้าทุกอย่าง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_44916_ChoiceDesc2 = {
    Text = "【เรียนรู้ที่จะปล่อยวาง】การ์ดคำสั่ง 3 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_44916_Desc = {
    Text = "วิญญาณที่มืดมนตกอยู่ในความเจ็บปวด。\nมันวนเวียนอยู่ที่เดิม สับสนกับทางเลือกและผลลัพธ์ที่เป็นไปได้ทั้งหมด。\n「ฉันควรเลือกอย่างไร?」มันกระซิบเบาๆ，「ฉันควรทำอย่างไร?」\n「ฉันจะทำอย่างไรให้ได้ทุกสิ่งทุกอย่าง?」"
  },
  Event_44916_Name = {
    Text = "คุณได้รับอะไร"
  },
  Event_44919_ChoiceDesc1 = {
    Text = "【การไตร่ตรองตนเอง】สุ่มการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_44919_ChoiceDesc2 = {
    Text = "【มองคนอื่น】ได้รับการแกะสลักหนึ่งในสาม"
  },
  Event_44919_Desc = {
    Text = "วิญญาณที่ลอยอยู่ตกอยู่ในสภาวะที่ลำบากใจ。\nมันหยุดเดิน ชะงักระหว่างความปรารถนา。\n「ฉันควรเลือกอย่างไร?」มันกระซิบเบาๆ，「ฉันควรทำอย่างไร?」\n「สุดท้ายแล้ว อะไรคือสิ่งที่ฉันต้องการจริงๆ?」"
  },
  Event_44919_Name = {
    Text = "คุณต้องการอะไร"
  },
  Event_44920_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_44920_Desc = {
    Text = "「คุณพูดถูก ฉันต้องดู ฉันต้องดู...」\nมันก้มหน้าลง มือทั้งสองข้างแหย่เข้าไปในอก แล้วดึงหัวใจที่ไม่มีตัวตนออกมาจากข้างใน: ครึ่งหนึ่งดำสนิทเหมือนหมึก อีกครึ่งหนึ่งสว่างเหมือนดาว.。"
  },
  Event_44920_Name = {
    Text = "คุณต้องการอะไร"
  },
  Event_44921_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_44921_Desc = {
    Text = "「ก็ใช่ ก็ใช่... คนบอกว่าคนอื่นสามารถเป็นกระจก... ฉันต้องดู...」\nมันยื่นหน้าเข้ามาใกล้คุณ มองคุณด้วยใบหน้าที่ไม่มีอวัยวะ\n「ทำไมเธอถึงไม่รู้สึกลำบากใจ? อิจฉาจัง อิจฉาจัง...」"
  },
  Event_44921_Name = {
    Text = "คุณต้องการอะไร"
  },
  Event_44998_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_44998_Desc = {
    Text = "「พวกเขาบอกว่า ความทุกข์ในตอนนี้เป็นเพียงชั่วคราว หลังความตายเราจะได้อยู่ในอ้อมกอดของพ่อพระและมีความสุขตลอดไป。\n「ฉันไม่อยากรอจนกว่าตาย。」\nเงามืดกลืนกินทุกสิ่งอย่างโลภ โดนวิญญาณที่มืดมนจางลง จนแทบกลายเป็นหนึ่งเดียวกับความมืดรอบตัว。\nคุณอยากทำอะไร แต่กลับไม่มีความสามารถ。"
  },
  Event_44998_Name = {
    Text = "ความมืดในใจ"
  },
  Event_45000_ChoiceDesc1 = {
    Text = "【โค้งคำนับและจากไป】"
  },
  Event_45000_Desc = {
    Text = "บิชอปใช้คมดาบกรีดฝ่ามือ หยดเลือดที่ตกลงบนกระดานหินกลายเป็นแสงสีน้ำเงินที่รักษา เติมเต็มเลือดที่ขาดหายไปในวิญญาณ\n「เอาเลือดของฉันไป เติมเต็มชีวิตของเธอ——ขอแค่สิ่งนั้นคือสิ่งที่เธอต้องการ นี่คือสิ่งที่พ่อพระหวังให้ฉันทำ」"
  },
  Event_45000_Name = {
    Text = "พรของพระสังฆราช"
  },
  Event_45001_ChoiceDesc1 = {
    Text = "【โค้งคำนับและจากไป】"
  },
  Event_45001_Desc = {
    Text = "บิชอปได้ดึงวิญญาณของตนออกมาจากส่วนลึกของอก แสงอ่อนนุ่มหลอมรวมเข้ากับกระดานหิน กลายเป็นแสงสีน้ำเงินที่รักษา เติมเต็มรอยแตกทั้งหมดในวิญญาณ\n「จงรับไป นี่คือของขวัญจากพ่อพระ เป็นหลักฐานแห่งความรักของพระองค์ ขอให้ร่างกายของเจ้าแข็งแรง วิญญาณของเจ้าเต็มเปี่ยม ไม่ต้องทนทุกข์อีกต่อไป」"
  },
  Event_45001_Name = {
    Text = "พรของพระสังฆราช"
  },
  Event_45002_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_45002_Desc = {
    Text = "คุณเดินไปหาใบหน้าที่เหล่านั้น เมื่อคุณลืมตาขึ้นอีกครั้ง เบื้องหน้ากลับกลายเป็นความมืด มีเพียงเสียงหัวเราะที่ไม่รู้แหล่งที่มาดังก้องอยู่รอบๆ。"
  },
  Event_45002_Name = {
    Text = "ภาพลวง"
  },
  Event_45036_ChoiceDesc1 = {
    Text = "【ลบสิ่งสร้างทั้งหมด】"
  },
  Event_45036_Desc = {
    Text = "「นี่คือบาปของข้า คือภาระของข้า ข้าจะช่วยให้ท่านรอดได้อย่างไร วิญญาณที่ขัดแย้งของข้า?」"
  },
  Event_45036_Name = {
    Text = "ความมืดในใจ"
  },
  Event_45196_ChoiceDesc1 = {
    Text = "【โค้งคำนับและจากไป】"
  },
  Event_45196_Desc = {
    Text = "บิชอปใช้คมดาบกรีดกระดูกและเนื้อ ขาวซีดของกระดูกกับสีชาดของเนื้อผสมเข้ากับกระดานหิน กลายเป็นแสงสีน้ำเงินที่รักษา เติมเต็มกระดูกที่หักในวิญญาณ\n「เอากระดูกและเนื้อของฉันไป เติมเต็มร่างกายที่ขาดหายของเธอ——ขอแค่สิ่งนั้นคือสิ่งที่เธอต้องการ นี่คือสิ่งที่พ่อพระหวังให้ฉันทำ」"
  },
  Event_45196_Name = {
    Text = "พรของพระสังฆราช"
  },
  Event_46144_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์เงิน 3 ตัวเลือก 1, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_46144_Desc = {
    Text = "เงาที่เลือนลางค่อยๆ ชัดเจนขึ้น นั่นไม่ใช่ร่างหลอมละลายและไม่ใช่ภัยพิบัติ แต่คือคลีเมนไทน์ที่ไม่มีปีกและสีหน้าเหมือนปกติ \n「บังเอิญจังนะ คุณก็มาที่นี่เพื่อชื่นชมแสงจันทร์เหรอ?」เธอพูดพร้อมกับยิ้ม แต่คุณกลับรู้สึกมึนงง，「ในคืนหมอกหนา ต้องระมัดระวังให้มากนะ \n「เจ้าตัวน้อยที่นี่ไม่ค่อยสงบเท่าไหร่」。"
  },
  Event_46144_Name = {
    Text = "รูปร่างในหมอก"
  },
  Event_46145_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์ทองคำ 3 ตัวเลือก 1，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_46145_Desc = {
    Text = "คุณไม่แสดงอาการอะไร คุณหญิงคนหนึ่งวิ่งขึ้นไปบนเวทีอย่างกระทันหัน \n เธอเปิดปากเด็กชายอย่างบ้าคลั่งและแทงไม้ในมือของเธอเข้าไปอย่างแรง \n 「พูดสิ พูดกับฉัน」 \n เด็กชายมีเลือดสีดำไหลออกจากปาก เขาพยายามพูดออกมาอย่างไม่ชัดเจน \n 「เพลงที่มอบให้แม่...」"
  },
  Event_46145_Name = {
    Text = "พิธีปิดฉาก Ⅲ"
  },
  Event_47309_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47309_Desc = {
    Text = "ถึงวันนั้น พระเจ้าจะใช้ดาบใหญ่ที่แข็งแกร่งและทรงพลังในการลงโทษชาวฟิลิสติน，\nจากความผิดที่พวกเขาก่อขึ้นจากการฆ่าฟัน。\nอะไรนะ คุณบอกว่านี่ไม่ยุติธรรม? \nไม่ นี่แหละคือชะตากรรมของนักล่า。"
  },
  Event_47309_Name = {
    Text = "เพลงเรือเล็ก"
  },
  Event_47310_ChoiceDesc1 = {
    Text = "【ดำเนินการต่อ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」，ได้รับการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_47310_ChoiceDesc2 = {
    Text = "【จากไป】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_47310_Desc = {
    Text = "พระเจ้าตรัสว่า: จงเรียกเขาว่าฟิลิสเตีย. \nจงให้เขาแบกรับหน้าที่ฆ่าฟัน และจงให้เขาแบกรับคำสาปของความโลภ. \nจงให้ทางเดินของเขาส่องสว่าง ทำให้คนคิดถึงเหวลึกเหมือนกับผมขาว. \nในท้องทะเลอันกว้างใหญ่ ไม่มีปลาฉลามตัวใดที่จะยิ่งใหญ่ไปกว่านี้. \nจงให้เขาเป็นที่กลัวและเคารพของสิ่งมีชีวิตทั้งมวล, \nจนกระทั่งถึงเวลาของการพิพากษา.。"
  },
  Event_47310_Name = {
    Text = "เพลงเรือเล็ก"
  },
  Event_47311_ChoiceDesc1 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_47311_ChoiceDesc2 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_47311_ChoiceDesc3 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_47311_Desc = {
    Text = "เด็กชายเป็นทาสที่ต่ำต้อย。\nนายท่านดูแลเขาเหมือนบิดา แต่กลับถูกแทงตายบนเตียง。\n「ผมรักท่านครับ พ่อ ผมแค่ไม่ต้องการเป็นทาสอีกต่อไป。」\nต่อมา เด็กชายยืนอยู่หน้าหลุมศพของ「พ่อ」นึกถึงคำพูดของนักบวช：\n<Small:อย่าจากไปจากแผ่นดินที่ให้กำเนิดคุณ。\nเมื่อถึงตอนนั้น มือของคุณจะเปื้อนเลือดสด และคุณจะตายอย่างไร้ศักดิ์ศรี。\nสุนัขจิ้งจอก นกอีแร้ง และปลาทะเลต่างก็จะดูถูกคุณ。>\nเด็กชายที่ชื่อเกลนในที่สุดก็จากไป。\nเขาจะเขียนเรื่องราวที่น่าอับอายของตนเอง。"
  },
  Event_47311_Name = {
    Text = "เด็กในถังไม้"
  },
  Event_47312_ChoiceDesc1 = {
    Text = "【เลื่อนหน้าไปข้างหน้า】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，เลือกให้ติดเชื้ออาการ 1 ครั้ง"
  },
  Event_47312_ChoiceDesc2 = {
    Text = "【เลื่อนหน้าต่อไป】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_47312_ChoiceDesc3 = {
    Text = "【ทิ้ง】ได้รับ 25 รอยดำ"
  },
  Event_47312_Desc = {
    Text = "คุณเก็บหนังสือเล่มหนึ่งที่ทำจากกระดาษกก：\n……\nเด็กชายซ่อนตัวอยู่ในบาร์เรล ขณะที่ลอยไปยังเกาะของฟิลิสติน.\nเขาอ่อนแอ ต่ำช้า และมีความทะเยอทะยาน.\nเมื่อความรุ่งโรจน์ของยักษ์อมตะทำให้ทุกคนต้องทึ่ง,\nมีเพียงเด็กชายที่ซ่อนอยู่ในเงามืด ไม่ให้แสงนั้นเข้ามาใกล้ตัวเขาแม้แต่น้อย.\nต่อมา เขาถูกโกไลแอทมอบหมายให้ทำหน้าที่สำคัญ.\nส่วนเหตุผลนั้น——"
  },
  Event_47312_Name = {
    Text = "เด็กในถังไม้"
  },
  Event_47313_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47313_Desc = {
    Text = "ยักษ์พูดต่อไปว่า：\n「ฉันวางเขาไว้ข้างฉัน เพราะเขาทั้งเศร้าสร้อยและตลก \nและเขาจะไม่มีวันฆ่าฉันได้」"
  },
  Event_47313_Name = {
    Text = "เด็กในถังไม้"
  },
  Event_47314_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47314_Desc = {
    Text = "คุณไม่ได้ยินส่วนที่อยู่ด้านหลัง แต่เนื้อเพลงของมันทำให้คุณนึกถึงอีกเพลงหนึ่ง: \n「ฉลามยักษ์ที่หายากนี้ โผล่ขึ้นมาในพายุและฝนตก \nมหาสมุทรคือบ้านของมัน \nเมื่ออำนาจคือหลักการ มันคือยักษ์แห่งอำนาจ \nเป็นราชาแห่งมหาสมุทรที่ไม่มีที่สิ้นสุด。」"
  },
  Event_47314_Name = {
    Text = "เพลงเรือเล็ก"
  },
  Event_47315_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47315_Desc = {
    Text = "ตอนนี้ไม่ใช่เวลาที่ดีในการอ่านหนังสือ \nคุณรีบวางหนังสือทิ้งไปโดยไม่เห็นเนื้อหาสุดท้าย: \n…… \nเขาที่ซ่อนอยู่ในเงาไม่ใช่เพราะความอิจฉา \nแต่เป็นเพราะความกลัวล้วนๆ \nเมื่อยืนอยู่ในแสง วิญญาณที่ต่ำต้อยจะถูกกลืนหายไปอย่างสิ้นเชิง \nแม้แต่เถ้าถ่านก็จะไม่มีเหลืออยู่เลย。"
  },
  Event_47315_Name = {
    Text = "เด็กในถังไม้"
  },
  Event_47463_ChoiceDesc1 = {
    Text = "【เข้าสู่ภวังค์】กำหนดให้ผู้ปลุกตื่น 1 ตัว เพื่อทำให้มันแยกส่วนทางจิตใจและสูญเสียการ์ดคำสั่งเริ่มต้น 4 ใบ。"
  },
  Event_47463_Desc = {
    Text = "หมอเงยหน้าขึ้นจากหนังสือที่มีมากมาย：\n「คุณเป็นตัวอย่างที่หายาก ดังนั้นฉันจะไม่คิดค่าบริการจากคุณ。\nแต่ฉันต้องการการตอบแทนอื่น：การสะกดจิตครั้งหนึ่ง。\nนี่เป็นวิธีการรักษาแบบใหม่ที่นำมาซึ่งสติสัมปชัญญะที่ไม่มีการปิดบังและเปลือยเปล่าอย่างสมบูรณ์。\nเป็นยังไงบ้าง คุณพร้อมที่จะลองไหม?」"
  },
  Event_47463_Name = {
    Text = "งูสะกดจิต"
  },
  Event_47464_ChoiceDesc1 = {
    Text = "【ความทรงจำที่เปล่งประกาย】[ExDesc1][ExDesc2]"
  },
  Event_47464_ChoiceDesc2 = {
    Text = "【ความทรงจำที่เลือนลาง】อัปเกรดการแกะสลักประสานในสำรับเป็นการแกะสลักประสานขั้นสูง"
  },
  Event_47464_Desc = {
    Text = "เธอล่องลอยอยู่บนชายหาดของทะเลแห่งจิตสำนึก \n ชายกระโปรงของคลื่นทะเลเลียไปที่เท้าของเธอ ส่งความทรงจำที่กระจัดกระจายมาที่ริมฝั่ง \n บางอันมีประกายบางอันมืดมิด และบางอันมีกลิ่นเหมือนกับฤดูฝนของลอนดีเนี่ยน \n คุณเลือกที่จะเก็บความทรงจำไหน? เธอล่องลอยอยู่บนชายหาดของทะเลแห่งจิตสำนึก。"
  },
  Event_47464_Name = {
    Text = "「การหลอมรวมหลัก」"
  },
  Event_47465_ChoiceDesc1 = {
    Text = "【ปฏิเสธที่จะลอง】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_47465_ChoiceDesc2 = {
    Text = "【ทุบสารละลาย】ขจัดสิ่งสร้างที่เป็นโทษ"
  },
  Event_47465_ChoiceDesc3 = {
    Text = "【ยอมรับการทดลอง】ได้รับลูกตุ้มเวลา ๑ อัน「(RelicConfig.Arg1)」"
  },
  Event_47465_Desc = {
    Text = "หมอส่ายขวดสารละลายสีเขียวด้วยความตื่นเต้นพร้อมบอกเธอว่า: \n「ดื่มเข้าไปอีกสักครั้ง แล้วเจ้าจะเข้าสู่โลกแห่งความฝันที่ตื่นตัวได้ \nมันคือลักษณะการแสดงผลของจิตใต้สำนึกส่วนรวม \nตอนนี้เจ้าจะได้แบ่งปันทะเลแห่งจิตสำนึกเดียวกันกับสิ่งมีชีวิตนับพันนับหมื่น \nอยากลองดูไหม?」"
  },
  Event_47465_Name = {
    Text = "「ลูซิดดรีม」"
  },
  Event_47466_ChoiceDesc1 = {
    Text = "【เสียงตอบรับ】ได้รับการ์ดคำสั่ง 1 ใบของร่างกายที่ตื่นขึ้นจากโรคจิตเภท"
  },
  Event_47466_Desc = {
    Text = "ร่างกายคือกรงขัง ที่กักขังบุคลิกที่แตกแยกออกเป็นหลายส่วน \n คุกที่ชื่อว่า「24」ตอนนี้เต็มไปด้วยผู้คน \n 「อย่าหลับใหล อย่าใจเย็น」 \n ในความมืด มีเสียงหนึ่งพูดเบาๆ。"
  },
  Event_47466_Name = {
    Text = "「การรู้แจ้งในธรรมชาติแท้」"
  },
  Event_47848_ChoiceDesc1 = {
    Text = "【ปิดตาทั้งสอง】ได้รับสิ่งประดิษฐ์ทองคำ เลือก 1 จาก 3"
  },
  Event_47848_ChoiceDesc2 = {
    Text = "【ชำเลืองมอง】เลือกการตื่นรู้ 2 ร่างกายที่ปลุก และลดการใช้พลังการคำนวณของการ์ดการตื่นรู้ลง 1."
  },
  Event_47848_ChoiceDesc3 = {
    Text = "【ลืมตาตื่น】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」, 「(RelicConfig.Arg2)」, 「(RelicConfig.Arg3)」"
  },
  Event_47848_Desc = {
    Text = "ก่อนที่จะเข้าสู่ภาวะสะกดจิต หมอพูดว่า：\n「ห้ามลืมตาโดยไม่ได้รับอนุญาตจากฉัน」\nเธอจึงหลับตาแน่น สูดหายใจเข้า... หายใจออก...\nในระหว่างที่หลับตาครึ่งหลับครึ่งตื่น เธอรู้สึกว่าได้ยินเสียงหายใจ「ซ่าๆ」\nจากนั้นเธอก็ถูกมองด้วยสายตาเย็นชา——\nมีบางสิ่งกำลังมองเธออยู่\nควรจะลืมตาขึ้นมามองดูหรือไม่?"
  },
  Event_47848_Name = {
    Text = "งูสะกดจิต"
  },
  Event_47876_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47876_Desc = {
    Text = "เธอก้มตัวเก็บความทรงจำที่เปล่งประกาย。\n หนึ่ง สอง ... ความสุขนับไม่ถ้วนหลั่งไหลเข้ามา，\n เธอเปิดแขนออกและหมุนรอบพวกมัน。"
  },
  Event_47876_Name = {
    Text = "「การหลอมรวมหลัก」"
  },
  Event_47877_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47877_Desc = {
    Text = "เธอก้มลงเก็บความทรงจำที่จางหาย.\nหนึ่ง, สอง... ความทุกข์ยากนับไม่ถ้วนหลั่งไหลมา,\nเธอกางแขนออก โอบกอดพวกมันทั้งหมดไว้ในอ้อมอก."
  },
  Event_47877_Name = {
    Text = "「การหลอมรวมหลัก」"
  },
  Event_47878_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47878_Desc = {
    Text = "คุณปฏิเสธที่จะเป็นเหยื่อของสารละลายแปลกๆ เหล่านี้。\nหมอรู้สึกผิดหวังเล็กน้อย แต่เขาไม่ได้บังคับคุณ。\n「ฉันให้อภัยความขี้ขลาดและการมองการณ์ไกลของมนุษย์。」"
  },
  Event_47878_Name = {
    Text = "「ลูซิดดรีม」"
  },
  Event_47879_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47879_Desc = {
    Text = "เสียงดังแป๊ะ! คุณทุบขวดแตก\nสารละลายสีเขียวกัดกร่อนพื้นอย่างรวดเร็ว\n「ดีมาก ความรู้สึกที่ไม่รู้ตัว แต่ฉันหวังว่าจะไม่มีครั้งหน้า\nไม่อย่างนั้นฉันจะต้องเสียใจและน้ำตาไหล」"
  },
  Event_47879_Name = {
    Text = "「ลูซิดดรีม」"
  },
  Event_47880_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47880_Desc = {
    Text = "คุณกลืนมันลงไปในคำเดียว \n กึกกึก... สมองของคุณและลำคอเกิดฟองสบู่มากมายพร้อมกัน \n เหมือนกับดอกไม้ไฟเล็กๆ ที่ดังเปรี๊ยะเปรี๊ยะ \n「ขอชมเชยคุณ มนุษย์ผู้กล้าหาญ คุณจะมีโอกาสได้สัมผัสกับความไม่มีที่สิ้นสุด \n และฉัน จะเป็นพยานต่อความไม่มีที่สิ้นสุด」"
  },
  Event_47880_Name = {
    Text = "「ลูซิดดรีม」"
  },
  Event_47881_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47881_Desc = {
    Text = "เธอลืมตาขึ้น แล้วพูดว่า：\n「ใช่ ทุกอย่างนี้มันไม่ถูกต้อง」\n「ควรจะต้องร้องไห้ ควรจะต้องต่อต้าน」\nในความมืดมีเสียงกระซิบกระซาบดังขึ้น เธอได้รับการตอบสนองที่มีน้ำใจ。"
  },
  Event_47881_Name = {
    Text = "「การรู้แจ้งในธรรมชาติแท้」"
  },
  Event_47900_ChoiceDesc1 = {
    Text = "【เห็นงู】ได้รับสิ่งสร้างทองคำ+「(RelicConfig.Arg1)」"
  },
  Event_47900_ChoiceDesc2 = {
    Text = "【เห็นคุณ】ได้รับสิ่งสร้างที่เต็มไปด้วยความผิด「(RelicConfig.Arg1)」"
  },
  Event_47900_Desc = {
    Text = "ป๊าป。\nเสียงนิ้วโป้งเบาๆ เสียงหนึ่งดึงเธอกลับสู่ความเป็นจริง。\nหมอไม่รู้ว่าเมื่อไรได้โน้มหน้าเข้ามา ดวงตาสีฟ้าที่สดใสเต็มไปด้วยความตื่นเต้น。\n「บอกฉันสิ ว่าเมื่อกี้คุณเห็นอะไรบ้าง?」"
  },
  Event_47900_Name = {
    Text = "งูสะกดจิต"
  },
  Event_47901_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47901_Desc = {
    Text = "เธอลืมตาขึ้น \n ในแสงเงาที่พร่ามัว เธอดูเหมือนจะเห็นงูยักษ์สีขาวที่สงบอยู่ในความมืด กำลังเคลื่อนไหวอย่างช้าๆ \n โอ้ และดวงตาของมัน— \n นั่นคือสีทองที่บริสุทธิ์จนไม่ผสมปนเปกับสิ่งใด \n ไม่มีความเศร้า ไม่มีความสุข ไม่มีการตัดสินใดๆ \n เพียงพอที่จะทำให้กระรอกนอนหลับตื่นจากฝันร้ายในฤดูร้อน。"
  },
  Event_47901_Name = {
    Text = "งูสะกดจิต"
  },
  Event_47909_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47909_Desc = {
    Text = "เธอลืมตาข้างหนึ่งอย่างเงียบๆ \n สิ่งที่เห็นคือแสงสีขาวพร่ามัวที่กำลังเคลื่อนไหวช้าๆ ในความมืด \n สีทองอ่อนๆ ส่องประกายในแสงนั้น ราวกับกำลังเตือนเธอเกี่ยวกับการทำผิด \n เธอไม่กล้าดูต่อไปอีกแล้ว。"
  },
  Event_47909_Name = {
    Text = "งูสะกดจิต"
  },
  Event_47910_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47910_Desc = {
    Text = "เธอปฏิบัติตามคำสั่งของหมออย่างเคร่งครัด ไม่เคยเปิดตาขึ้นเลยสักครั้ง \nลมหายใจเย็นเฉียบพัดผ่านอากาศรอบตัวเธอ ค้างอยู่บนใบหน้าของเธอนานแสนนาน \nไม่รู้ว่าเวลาผ่านไปนานแค่ไหน ทุกอย่างกลับสู่สภาพปกติ \nราวกับว่าไม่มีอะไรเกิดขึ้น。"
  },
  Event_47910_Name = {
    Text = "งูสะกดจิต"
  },
  Event_47911_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47911_Desc = {
    Text = "「ฉันเห็น...งูตัวหนึ่งที่สวยงามมาก」\nหมอหยุดมือที่ถือปากกาไปชั่วขณะหนึ่ง\n「งูแบบไหน?」\n「สวยมาก! ทั้งตัวมีสีขาว และมีลวดลายสีทองอยู่บนตัว...」\nหมอไม่พูดอะไรอีก ยิ้มมุมปากอย่างเบาๆ\n「ขอบคุณ」"
  },
  Event_47911_Name = {
    Text = "งูสะกดจิต"
  },
  Event_47912_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47912_Desc = {
    Text = "เธอมองตรงไปยังดวงตาสีฟ้าเข้มของหมอ\n「ฉันเห็นคุณกลายเป็นงู」\n「โอ้ ทำไมคุณถึงมั่นใจว่านั่นคือฉัน?」\nเพราะมันลึกลับ นิ่งสงบ และซับซ้อน\nและ...\nมันดูเหนื่อยล้า ราวกับเพิ่งตื่นจากการจำศีลนานนับพันปี。"
  },
  Event_47912_Name = {
    Text = "งูสะกดจิต"
  },
  Event_47992_ChoiceDesc1 = {
    Text = "【เชื่อมต่อ】คืนค่า Arg2 จุดชีวิต。"
  },
  Event_47992_ChoiceDesc2 = {
    Text = "【การตื่นรู้】เลือกปลุกผู้ตื่น 1 ตน。"
  },
  Event_47992_ChoiceDesc3 = {
    Text = "【กำจัด】ลบการ์ดอาการได้สูงสุด 3 ใบ ได้รับ Arg2 รอยดำ。"
  },
  Event_47992_Desc = {
    Text = "คุณกำลังสำรวจในหมอก จู่ๆ เข็มกลัดที่หน้าอกก็เปล่งแสงเงินอ่อนๆ ขึ้น ใครกันที่เรียกคุณอยู่ที่ปลายสายของเครื่องสื่อสาร?"
  },
  Event_47992_Name = {
    Text = "จุดติดต่อ"
  },
  Event_47992_Tips3 = {
    Text = "ขณะนี้คุณยังไม่มีการ์ดอาการ"
  },
  Event_47993_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_47993_ChoiceDesc2 = {
    Text = "【ออกจาก】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg1)」และสร้างสำเนาการ์ดต้นฉบับ 1 ใบ"
  },
  Event_47993_Desc = {
    Text = "คุณรับคำขอติดต่อจากโรงเรียน เสียงที่คุ้นเคยทำให้จิตใจของคุณสงบ คุณรวบรวมกำลังใจและก้าวเดินต่อไป"
  },
  Event_47993_Name = {
    Text = "จุดติดต่อ"
  },
  Event_48225_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_48225_Desc = {
    Text = "วิฬารที่มีความสุขเลียหลังมือของคุณเบาๆ \n「ขอบคุณค่ะ ไม่ต้องเป็นห่วงฉันนะเมี๊ยว \nที่นี่บุคลิกภาพกำลังตายและเกิดใหม่ตลอดเวลา \nฉันจะกลับมาแน่นอน! \nเมี๊ยว เมี๊ยว เมี๊ยว!」"
  },
  Event_48225_Name = {
    Text = "คำสั่งสุดท้าย"
  },
  Event_48226_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_48226_Desc = {
    Text = "วิฬารคิดว่าคุณไม่เข้าใจความหมายของมัน จึงขยับตัวไปถูกหลังมือของคุณอย่างน่ารัก \n「แค่คุณยอมรับคำขอของเมี๊ยว เมี๊ยวจะมอบของว่างที่ซ่อนไว้ทั้งหมดให้คุณ \nมันถูกเก็บรักษาอย่างดีที่หมายเลข 2 ย่านแคมเบรย์...」"
  },
  Event_48226_Name = {
    Text = "คำสั่งสุดท้าย"
  },
  Event_48227_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_48227_Desc = {
    Text = "คุณได้แสดงความขอโทษอย่างจริงใจต่อจอร์จ。\n「ฮึ่ม คุณยังถือเป็นคนที่รู้จักมารยาทอยู่บ้าง。\nจอร์จจะพิจารณาลดความแรงของการสาปแช่งลง 10%，\nสูงสุด 15%——นี่คือขีดจำกัดของจอร์จ。」"
  },
  Event_48227_Name = {
    Text = "วิญญาณของจอร์จ"
  },
  Event_48228_ChoiceDesc1 = {
    Text = "【ยืนยัน】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_48228_ChoiceDesc2 = {
    Text = "【ปฏิเสธมัน】เลือก 1 จาก 3 สิ่งประดิษฐ์ทองคำ，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_48228_ChoiceDesc3 = {
    Text = "【รักษาความเงียบ】ได้รับ สิ่งประดิษฐ์เงิน 「(RelicConfig.Arg1)」"
  },
  Event_48228_Desc = {
    Text = "「แมวจรจัด24」ได้รับบาดเจ็บอย่างหนัก มันดิ้นรนที่จะบอกคุณว่า: \n「เหมียว เหมียวชีวิตฉันใกล้จะถึงที่สิ้นสุด\nฉันมีเพื่อนคนหนึ่ง เป็นปลาค๊อดเงินเหมียว\nถ้าสักวันคุณพบมัน โปรดบอกมันว่าฉันออกเดินทางไกลเหมียว\nฉันจะไปนานและนานมากเหมียว\nฉันจะนำมันกลับมาพร้อมเฟรนช์ฟรายส์ที่ไม่มีปลาทอดเหมียว\nต้องบอกมันด้วยนะเหมียว!」"
  },
  Event_48228_Name = {
    Text = "คำสั่งสุดท้าย"
  },
  Event_48229_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_48229_Desc = {
    Text = "วิฬารรู้สึกผิดหวังเล็กน้อย。\nแต่มันก็เป็นวิฬารที่เชื่อฟังและว่าง่ายมาตลอด ไม่เคยบังคับผู้อื่นเลย。\nสุดท้ายมันก็ปิดตาลงด้วยความเสียดาย。"
  },
  Event_48229_Name = {
    Text = "คำสั่งสุดท้าย"
  },
  Event_48230_ChoiceDesc1 = {
    Text = "【ขอโทษมัน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，สถานะ「(Skill.Arg2)」"
  },
  Event_48230_ChoiceDesc2 = {
    Text = "【เยาะเย้ยมัน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」, ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_48230_ChoiceDesc3 = {
    Text = "【ละเลยมัน】ได้รับ 25 รอยดำ"
  },
  Event_48230_Desc = {
    Text = "ผีหนึ่ง ดวงวิญญาณของจอร์จกำลังวนเวียนอยู่เหนือพวกคุณ。\n「จอร์จตายอย่างไม่มีศักดิ์ศรี。\nแต่ไม่เป็นไร จอร์จจะจดจำความอัปยศในครั้งนี้ตลอดไป。\nผู้พิทักษ์ คุณจะโชคร้ายมาก ฮึฮึฮึ……」"
  },
  Event_48230_Name = {
    Text = "วิญญาณของจอร์จ"
  },
  Event_48231_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_48231_Desc = {
    Text = "「ฮึฮึ กล้าล้อเลียนจอร์จ。\nสบายใจเถอะ ในขณะที่คุณกินข้าว นอนหลับ ร้องเพลง...\nจอร์จจะลอยไปลอยมาอยู่ข้างๆ เตือนคุณ ทรมานคุณ。\nเพื่อให้คุณจดจำบาปของตัวเองตลอดไป。\nคุณจะจับผีไม่ได้ตลอดไป ลาลาลา~」"
  },
  Event_48231_Name = {
    Text = "วิญญาณของจอร์จ"
  },
  Event_48232_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_48232_Desc = {
    Text = "คุณก้าวเดินไปข้างหน้า ทิ้งคำสาปของจอร์จไว้เบื้องหลัง\nเบื้องหลังท่าน เสียงสะอึกสะอื้นดังขึ้น จอร์จกลับร้องไห้ออกมา\n「ฮือฮือ...ฉันที่น่ารักเช่นนี้ กลับถูกก้นของนาย—\nน่าขยะแขยง! น่าขยะแขยง!\nจอร์จยอมตายใต้แส้ของแพนเดีย!」"
  },
  Event_48232_Name = {
    Text = "วิญญาณของจอร์จ"
  },
  Event_49055_ChoiceDesc1 = {
    Text = "【ปลุกร่างกายที่ตื่นขึ้น】หักค่าความคลั่ง 100 จากทุกร่างกายที่ตื่นขึ้น และลบการ์ดอาการ 1 ใบ"
  },
  Event_49055_ChoiceDesc2 = {
    Text = "【พยายามดิ้นรน】ฟื้นฟู Arg1 จุดชีวิต เพิ่มการติดตั้ง 2 ใบ「(Skill.Arg2)」"
  },
  Event_49055_ChoiceDesc3 = {
    Text = "【ใส่กุญแจเงิน】ล้างพลังกุญแจเงิน"
  },
  Event_49055_Desc = {
    Text = "บ่ออาบเลือดที่พร่ามัวปรากฏตัวขึ้นในขณะที่คุณเหยียบลงไป \n เลือดสีแดงดำยื่นแขนที่นับไม่ถ้วนออกมา พันรอบข้อเท้าของคุณ และดึงขึ้นไปข้างบนอย่างต่อเนื่อง โดยมีเจตนาที่จะลากคุณลงไปสู่เหวที่ไม่อาจคาดเดาได้。"
  },
  Event_49055_Name = {
    Text = "บ่อน้ำเลือด"
  },
  Event_49097_ChoiceDesc1 = {
    Text = "【เดินหน้า】"
  },
  Event_49097_Desc = {
    Text = "ในช่องท้องเกิดความปั่นป่วน หลังจากนั้นไม่กี่วินาทีกลับสงบลงอย่างอัศจรรย์ ไม่รู้ทำไม คุณรู้สึกเหมือนได้ยินเสียงการเต้นของหัวใจอีกดวงภายในร่างกายของคุณ…"
  },
  Event_49097_Name = {
    Text = "มารดาแห่งการสร้าง"
  },
  Event_49098_ChoiceDesc1 = {
    Text = "【ดื่มให้หมด】เลือกการ์ดคำสั่ง [ExDesc3][ExDesc4] ใบ เพื่อให้ได้รับตราประทับ：「(EnchantConfig.Arg1)」[ExDesc1][ExDesc2]"
  },
  Event_49098_Desc = {
    Text = "หม้อดินเก่าคร่ำคร่ามองคุณอยู่ในรอยแยกของผนังหินต่ำ\nแหล่งน้ำเป็นทรัพยากรที่มีค่าที่สุดในทะเลทราย แอลกอฮอล์คือยาที่นำเข้าสู่โลกแห่งความบ้าคลั่งและภาพลวงตา\nในพื้นที่แห้งแล้งนี้ คนที่ยังคงมีสติสัมปชัญญะยากที่จะปฏิเสธคำเชิญชวนของมัน。"
  },
  Event_49098_Name = {
    Text = "มารดาแห่งการสร้าง"
  },
  Event_49312_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49312_Desc = {
    Text = "กุญแจเงินส่องประกายกระพริบ แขนของพวกเขาดูเหมือนจะถูกพละกำลังบางอย่างทำให้ตกใจ จึงค่อยๆ จมหายไปในน้ำของสระ แล้วหายไป。"
  },
  Event_49312_Name = {
    Text = "บ่อน้ำเลือด"
  },
  Event_49313_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49313_Desc = {
    Text = "คุณพยายามดิ้นรนอย่างเต็มที่ แต่กลับลึกลงไปเรื่อยๆ เสียงพึมพำที่เหมือนคำสาปดังก้องในหัวของคุณ \n เมื่อคุณฟื้นคืนสติ แขนขาสีเลือดกลับพอใจและถอยห่างออกไป คุณกลับรู้สึกสบายตัว แต่เหมือนว่าจะสูญเสียอะไรบางอย่างไปในความมืดมน..."
  },
  Event_49313_Name = {
    Text = "บ่อน้ำเลือด"
  },
  Event_49314_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49314_Desc = {
    Text = "ผู้ปลุกตื่นที่เข้ามาทันทีไม่ลังเลแม้แต่วินาทีเดียวก็ฉุดคุณออกจากบ่อน้ำเลือด แขนที่เชื่อมต่อกับคุณถูกฉีกขาด น้ำโคลนขุ่นกระเด็นออกไป ในสายน้ำมีสิ่งมีชีวิตนับไม่ถ้วนที่ตาเปล่าแทบแยกไม่ออกกำลังขยับเขยื้อน เหมือนว่าพวกมันกำลังกระหายและกลืนกินอะไรบางอย่าง。"
  },
  Event_49314_Name = {
    Text = "บ่อน้ำเลือด"
  },
  Event_49867_ChoiceDesc1 = {
    Text = "เพิ่มความคลั่ง 50 ให้กับร่างกายที่ตื่นขึ้น"
  },
  Event_49867_Name = {
    Text = "เหตุการณ์"
  },
  Event_49907_ChoiceDesc1 = {
    Text = "【สอบถามความจริงหรือเท็จ】"
  },
  Event_49907_ChoiceDesc2 = {
    Text = "【ขอร้องให้ลูบ】"
  },
  Event_49907_Desc = {
    Text = "「คุณมักจะจ้องมองที่มุมของฉันด้วยความอยากรู้ มีปัญหาอะไรหรือเปล่า?」\nไทอีสเข้าใกล้ไหล่ของคุณอย่างกระทันหัน ลูกปัดสีทองน้ำผึ้งสั่นไหวเบาๆ สัมผัสที่แก้มของคุณ。"
  },
  Event_49907_Name = {
    Text = "คนที่มีเขา"
  },
  Event_49908_ChoiceDesc1 = {
    Text = "【มองขึ้นไป】"
  },
  Event_49908_ChoiceDesc2 = {
    Text = "【เดินไปยังไทอีส】"
  },
  Event_49908_Desc = {
    Text = "ฝุ่นควันฟุ้งกระจายในซากปรักหักพัง ที่หน้าต่างแตกในมุมหนึ่ง เงาของทาอิสปรากฏขึ้นอย่างกะทันหัน. เธอโน้มตัวลงบนขอบหน้าต่างที่เต็มไปด้วยฝุ่นอย่างไม่แคร์ใคร แล้วชี้ขึ้นไปที่คานหลังคาอย่างลึกลับ."
  },
  Event_49908_Name = {
    Text = "คนเดินทางลับ"
  },
  Event_49909_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_49909_Desc = {
    Text = "คุณเงยหน้าขึ้น ท่อทองแดงที่เป็นสนิมเต็มไปหมดแพร่กระจายออกไปเหมือนกับใยแมงมุมขนาดใหญ่ที่ปกคลุมอยู่เหนือศีรษะ เงาหนึ่งพุ่งผ่านไป เป็นแมวป่าที่ออกตามหามื้ออาหารหรือมอนสเตอร์ที่ซ่อนอยู่ในเงา? \n หันกลับไปอีกครั้ง ไทอีสก็ไม่เห็นร่องรอยแล้ว。"
  },
  Event_49909_Name = {
    Text = "คนเดินทางลับ"
  },
  Event_49910_ChoiceDesc1 = {
    Text = "【จ้องมองเธอ】"
  },
  Event_49910_ChoiceDesc2 = {
    Text = "【เรียกหาเธอ】"
  },
  Event_49910_Desc = {
    Text = "คุณได้พบกับ「ภาพลวงตา」อีกครั้ง。\nครั้งนี้คุณรู้ชื่อของเธอแล้ว。\nทาอิสยืนอยู่ใต้ต้นแม่ที่อยู่ห่างไกล สวดมนต์อย่างเคร่งศรัทธาต่อไม้。\nเงาร่างของเธอเลือนลางคล้ายคลึงกับภาพลวงตาของต้นแม่。"
  },
  Event_49910_Name = {
    Text = "ผู้ขอพร"
  },
  Event_49911_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_49911_Desc = {
    Text = "คุณมองไปยังเงาร่างของไทอีส เธอมีรูปร่างดุจยอดเขาศักดิ์สิทธิ์ในพายุที่เหมือนวันสิ้นโลก แม้พายุทรายจะโหมกระหน่ำก็ไม่สามารถลดทอนอำนาจของเธอลงได้แม้แต่น้อย \nการก้าวเดินของเธอช้าและมั่นคง รูปร่างของเธอสูงส่งและไม่อาจละเมิดได้ ทำให้คุณติดใจมองดู。"
  },
  Event_49911_Name = {
    Text = "คนอมตะ"
  },
  Event_49912_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบ"
  },
  Event_49912_Desc = {
    Text = "「คุณเดาล่ะ?」\nเธอ「ชูว์」เสียงหนึ่ง ย่อตัวเข้ามาใกล้ คุณรู้สึกว่าปลายมุมของเธอสัมผัสที่แก้มของคุณแล้ว มีความรู้สึกเย็นและคันเล็กน้อย..."
  },
  Event_49912_Name = {
    Text = "คนที่มีเขา"
  },
  Event_49913_ChoiceDesc1 = {
    Text = "【จากไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_49913_Desc = {
    Text = "「อยากสัมผัสก็พูดออกมาซิ ฉันจะปฏิเสธคุณเหรอ?」\nเธอหัวเราะเบาๆ ขณะที่จับมือคุณ นิ้วมือสัมผัสรู้สึกอุ่นและลื่น ทำให้คุณแทบอยากจะติดอยู่ลึกในนั้น..."
  },
  Event_49913_Name = {
    Text = "คนที่มีเขา"
  },
  Event_49914_ChoiceDesc1 = {
    Text = "【ออกจาก】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น ลดค่าใช้จ่ายของการ์ดการตื่นรู้ลง 1 และติดเชื้อ「(Skill.Arg1)」"
  },
  Event_49914_Desc = {
    Text = "คุณทรุดลงกับพื้นพร้อมกับทุกคน。\n「ฉันรู้ ฉันรู้ ราชินี พระนางทรงคุ้มครองเราเสมอ!」\nเสียงกรีดร้องด้วยความดีใจและเสียงเพรียกอันยาวนานผสมกับเสียงเห่าหอนของวายุ สะท้อนเข้ามาในสมองของคุณ。\nในความพร่ามัว มีความคิดสำคัญบางอย่างผุดขึ้นมา แต่ไม่สามารถจับมันได้。"
  },
  Event_49914_Name = {
    Text = "คนอมตะ"
  },
  Event_49915_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์เงิน 3 ตัวเลือก 1, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_49915_Desc = {
    Text = "คุณโบกมือให้เธอ。\n「คุณทำอะไรอยู่?」รามอน่ามองคุณด้วยความสงสัย。\n「ที่นั่น……」\nพูดยังไม่ทันจบ ผู้หญิงคนนั้นก็หายไปจากสายตาแล้ว。\nหรือว่าเป็นภาพลวงตา?"
  },
  Event_49915_Name = {
    Text = "คนรดน้ำ"
  },
  Event_49916_ChoiceDesc1 = {
    Text = "【ตอบกลับเธอ】"
  },
  Event_49916_ChoiceDesc2 = {
    Text = "【ลังเล】"
  },
  Event_49916_Desc = {
    Text = "มองไปไกล ๆ มีผู้หญิงคนหนึ่งกำลังตักน้ำอยู่ที่ริมแม่น้ำ。\nดูเหมือนว่าเธอจะสังเกตเห็นสายตาของคุณ เธอจึงหันหลังและโบกมือให้คุณ。\nคุณสังเกตเห็นว่า วิธีที่เธอหันตัวดูเหมือนจะมีอะไรแปลก ๆ。"
  },
  Event_49916_Name = {
    Text = "คนรดน้ำ"
  },
  Event_49917_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก「(EnchantConfig.Arg1)」"
  },
  Event_49917_Desc = {
    Text = "ในขณะที่คุณลังเล ผู้หญิงคนหนึ่งได้หันหลังแล้วกระโดดเข้าสูโอเอซิสจนหายไป \n คุณไม่กล้าจะเชื่อในสิ่งที่เห็น... เธอดูเหมือนจะมีกีบเหมือนแกะ?"
  },
  Event_49917_Name = {
    Text = "คนรดน้ำ"
  },
  Event_49918_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก「(EnchantConfig.Arg1)」"
  },
  Event_49918_Desc = {
    Text = "「โอ้ต้นไม้เอย โปรดรับฟังความปรารถนาของ@1 ข้าจะได้รับการชำระล้างด้วยน้ำนมของท่านและเกิดใหม่ กลายเป็นผู้ดำเนินการของท่าน เดินแทนท่านท่ามกลางผืนทราย ให้รากของท่านสัมผัสทุกมุมของเลมวาฮิ...」\n\nเสียงสวดภาวนาอ่อนเยาว์ที่สะท้อนก้องสลับกันไปมาในพื้นที่นั้น."
  },
  Event_49918_Name = {
    Text = "ผู้ขอพร"
  },
  Event_49919_ChoiceDesc1 = {
    Text = "【ออกจาก】การตื่นรู้แบบสุ่มของร่างกายที่ตื่นขึ้น"
  },
  Event_49919_Desc = {
    Text = "สายตาที่คลุมเครือและไม่ชัดเจนของไทอีสทำให้คุณสนใจ มีพละกำลังบางอย่างที่แปลกประหลาดทำให้คุณรู้สึกมึนงง คุณเหมือนถูกดึงดูดให้เดินไปหาเธอโดยไม่สามารถต้านทานได้ \n「จริงๆ แล้ว สิ่งที่มองไม่เห็นก็ยังคงมีอยู่」\nเธอกระซิบเบาๆ ข้างหูคุณ คุณรู้สึกเหมือนเข้าใจบางอย่าง แต่ก็เหมือนถูกคลุมด้วยผ้าขาว ทำให้มองไม่เห็นอย่างชัดเจน \nนี่คือคำทำนายบางอย่างหรือเปล่า? พลัน ไทอีสก็หายไปจากสายตา。"
  },
  Event_49919_Name = {
    Text = "คนเดินทางลับ"
  },
  Event_49920_ChoiceDesc1 = {
    Text = "【มองออกไป】"
  },
  Event_49920_ChoiceDesc2 = {
    Text = "【คุกเข่า】"
  },
  Event_49920_Desc = {
    Text = "เท้าสีดำของแกะเหยียบลงบนโลกาที่เต็มไปด้วยลมและทราย。\nทาอิสสวดมนต์บทอธิษฐานที่ไม่รู้จัก ชาวอัลลันนับไม่ถ้วนคุกเข่าลงในทิศทางที่เธอเดินมาบนทราย。"
  },
  Event_49920_Name = {
    Text = "คนอมตะ"
  },
  Event_49921_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์ทองคำ 3 ตัวเลือก 1，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_49921_Desc = {
    Text = "ต้นไม้ใหญ่ยื่นกิ่งก้านอันแข็งแกร่งออกมาเหมือนกับหนวดที่พันกัน รัดข้อมือและข้อเท้าของไทอีสแน่นหนา ไม่สนใจการดิ้นรนขัดขืนของเธอ อย่างดื้อรั้นนำร่างของเธอเข้าไปในโพรงท้องของลำต้นที่ขยายตัว...\n\nแม้จะเป็นเพียงภาพลวงตาที่อยู่ห่างไกล ความเจ็บปวดของเธอก็ยังส่งผ่านคลื่นน้ำมาถึงใจของคุณได้อย่างชัดเจน。"
  },
  Event_49921_Name = {
    Text = "ผู้ขอพร"
  },
  Event_49922_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับของสร้าง「(RelicConfig.Arg1)」"
  },
  Event_49922_Desc = {
    Text = "ร่างกายที่อ่อนแรงไหลไปตามน้ำยาของต้นไม้บนกิ่งก้าน เธอพยายามดิ้นรนอย่างสุดกำลัง แต่ร่างกายกลับเหมือนกับหนอนที่โซเซบิดเบือนไม่ฟังคำสั่ง\n「โครงกระดูกได้ละลายไปหมดแล้ว」 ขอบตาและขมับของทาอิสถูกความเศร้าปกคลุม 「เธอได้กลายเป็นส่วนหนึ่งของต้นไม้ไปแล้ว」\n「เราต้องการพละกำลังในการย้อนกลับ...พละกำลังที่ก้าวข้ามขีดจำกัดของเวลา」"
  },
  Event_49922_Name = {
    Text = "คนกัดกร่อน"
  },
  Event_49923_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_49923_Desc = {
    Text = "「และที่สำคัญ 「ดวงตาไร้หนังตาที่ถูกแขวนกลับหัว」ไม่ทราบทำไม กลับมีแรงดึงดูดอย่างแรงจากภายในจิตใจ……」\n「โอ้ ที่พูดถึงเรื่องของฉันเหรอ?」\n「มีดิเนทกำลังสรรเสริญความสามารถในเรื่องราวของคุณอยู่เลย。」\n\nคืนที่กองไฟลุกโชนอย่างเงียบ ๆ เธอเคยเติมเหล้าให้คุณ。"
  },
  Event_49923_Name = {
    Text = "คนกัดกร่อน"
  },
  Event_49924_ChoiceDesc1 = {
    Text = "【ผ่าก้อนเนื้อในต้นไม้】"
  },
  Event_49924_ChoiceDesc2 = {
    Text = "【ความทรงจำ】"
  },
  Event_49924_Desc = {
    Text = "ก้อนเนื้อในต้นไม้หนึ่งก้อน。\nมันเต้นอย่างชั่วร้ายและบวมเป่ง ผิวหนังสีเลือดที่โปร่งใสอ่อนแอเผยให้เห็นใบหน้าที่บิดเบี้ยวและเจ็บปวด ราวกับว่าจะมีการคลี่คลายออกมาได้ทุกเมื่อ。\n「เมดินาเตท」ไทอีสแสดงสีหน้าเศร้าโศกและเรียกชื่อใบหน้านั้นอย่างอ่อนโยน。"
  },
  Event_49924_Name = {
    Text = "คนกัดกร่อน"
  },
  Event_49939_ChoiceDesc1 = {
    Text = "【เชื่อเลค】ร่างกายที่ตื่นขึ้นทั้งหมดเพิ่มความคลั่ง Arg1"
  },
  Event_49939_ChoiceDesc2 = {
    Text = "【เลค】เลือกการตื่น 2 ร่างกายที่ตื่นขึ้น"
  },
  Event_49939_Desc = {
    Text = "「เชื่อในโชคดีของฉันเถอะนะ」"
  },
  Event_49939_Name = {
    Text = "นักสืบโชคดี"
  },
  Event_49940_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49940_Desc = {
    Text = "ไรเกอร์ทำได้เพียงสามอย่างเท่านั้น: การสืบสวน, การฟัง, การโยนลูกเต๋า.\nพูดอีกอย่างก็คือ เขาไม่ชำนาญในการต่อสู้.\nความกังวลในใจของคุณยากที่จะยับยั้ง การเจริญเติบโตอย่างบ้าคลั่ง。"
  },
  Event_49940_Name = {
    Text = "นักสืบโชคดี"
  },
  Event_49941_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49941_Desc = {
    Text = "หัวใจที่เชื่อมั่นคือเวทมนตร์ เขาจะเอาชนะอุปสรรคทั้งหมดที่อยู่ตรงหน้าได้อย่างแน่นอน"
  },
  Event_49941_Name = {
    Text = "นักสืบโชคดี"
  },
  Event_49943_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49943_Desc = {
    Text = "คุณรู้สึกอายมาก แต่ก็ยังมองไปรอบๆ ราโมน่าที่ยังป่วยอยู่ด้วยความหวัง \n “ให้ฉันทำเถอะ” \n เธอหน้าแดงก่ำ หยิบขวดเก็บตัวอย่างใหม่เอี่ยมจากกระเป๋าถือที่มีความจุไม่จำกัดออกมา แล้วปิดมันด้วยความเร็ว。"
  },
  Event_49943_Name = {
    Text = "แมงมุมพิษ"
  },
  Event_49944_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49944_Desc = {
    Text = "ไรเกอร์ดีดนิ้ว แล้วยื่นนิ้วชี้ที่เต็มไปด้วยขนไปยังแมงมุมขนาดใหญ่ที่ยกเท้าหน้าอยู่สูง \n สัตว์ประเภทนี้ที่มีลวดลายสีสันสดใสมักจะมีพิษร้ายแรง คุณเพิ่งจะตั้งใจเตือนเขาให้ระวัง แต่แมงมุมที่เมื่อกี้เต็มไปด้วยความเป็นศัตรูกลับกระโดดขึ้นไปที่ข้อของเขาอย่างคล่องแคล่วและห่อหุ้มตัวเอง \n ช่างเถอะ แต่ละคนก็มีชะตากรรมของตัวเอง。"
  },
  Event_49944_Name = {
    Text = "แมงมุมพิษ"
  },
  Event_49945_ChoiceDesc1 = {
    Text = "【มองไปที่รามอน่า】ได้รับการแกะสลักแบบเลือกหนึ่งในสาม"
  },
  Event_49945_ChoiceDesc2 = {
    Text = "【มองไปที่เลค】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_49945_Desc = {
    Text = "ตาแบบซ้ำซ้อนหลายคู่จ้องมองคุณอยู่。\nเจ้าของตาแบบซ้ำซ้อนถอยหลังไปครึ่งก้าว ขู่คุณด้วยการข่วนฟันและยกแขนขึ้นมา。\nจากการยกขาและอวัยวะที่ใช้ในการเคลื่อนที่ รวมถึงขาของมันที่ใช้พยุงร่างกาย ดูเหมือนว่านี่จะเป็นสิ่งมีชีวิตในกลุ่มสัตว์ขาปล้องที่หายากจริงๆ。\nก่อนออกเดินทาง ชอร์ทได้เตือนคุณว่า “ภารกิจเพิ่มเติม โปรดเก็บตัวอย่างพันธุ์ท้องถิ่นและเก็บไว้ที่สถานีสำรวจท้องถิ่น。”\nคุณเขย่าขวดเก็บตัวอย่างในกระเป๋าเป้ของคุณ หลังจากเดินทางหลายสัปดาห์ ข้างในเต็มไปด้วยแมลงมากมาย。"
  },
  Event_49945_Name = {
    Text = "แมงมุมพิษ"
  },
  Event_49946_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49946_Desc = {
    Text = "「ความโลภที่ไม่คำนึงถึงจังหวะเวลาเป็นโรคชนิดหนึ่ง。」"
  },
  Event_49946_Name = {
    Text = "คำตอบของคุณ"
  },
  Event_49947_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49947_Desc = {
    Text = "「การพูดตามตำราไม่สามารถทำให้คุณได้รับความนิยมหรอก เด็กน้อย.」"
  },
  Event_49947_Name = {
    Text = "คำตอบของคุณ"
  },
  Event_49948_ChoiceDesc1 = {
    Text = "【กุญแจทอง】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_49948_ChoiceDesc2 = {
    Text = "【กุญแจเหล็ก】ได้รับสิ่งสร้างทองคำ เลือก 1 จาก 3 ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_49948_ChoiceDesc3 = {
    Text = "【กุญแจเงิน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_49948_Desc = {
    Text = "ตอนเที่ยงวัน หมอกควันจากแม่น้ำศักดิ์สิทธิ์ก่อตัวเป็นภาพลวงตาสองภาพ \n เสียงจากภาพลวงตาที่พร่ามัวถามคุณว่า นี่คือกุญแจทอง กุญแจเงิน หรือกุญแจเหล็กที่คุณทำหาย?"
  },
  Event_49948_Name = {
    Text = "คำตอบของคุณ"
  },
  Event_49949_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_49949_Desc = {
    Text = "「ความซื่อสัตย์มักให้ผลลัพธ์ที่มั่นคง แต่บางทีคุณอาจพลาดบางอย่างไป」"
  },
  Event_49949_Name = {
    Text = "คำตอบของคุณ"
  },
  Event_50013_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50013_Desc = {
    Text = "คุณพยายามมองให้ชัดเจน แต่ใบหน้าของคนนั้นกลับลอยไปตามคลื่นน้ำ มันเบลอและไม่ชัดเจน \n\nยิ่งคุณจ้องมองลึกเข้าไป การหายใจก็ยิ่งช้าลง ความรู้สึกเหมือนขาดอากาศหายใจเริ่มเข้ามาในสมอง จนกระทั่งได้ยินเสียงของรามอน่าที่เรียกคุณ ทำให้คุณกลับสู่ความเป็นจริงอย่างยากลำบาก \nแสงแดดที่สะท้อนบนผิวน้ำส่องแสงจ้าเกินไป แต่ใต้ผิวน้ำดูเหมือนมีสิ่งที่ระยิบระยับอยู่。"
  },
  Event_50013_Name = {
    Text = "ภูติแห่งความตาย"
  },
  Event_50014_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50014_Desc = {
    Text = "ภาพลวงตาแตกสลายเมื่อสัมผัส มือของคุณว่างเปล่า มีเพียงความเจ็บปวดอย่างรุนแรงที่พุ่งขึ้นจากขมับ \n แสงแดดที่สะท้อนบนผิวน้ำเจิดจ้าจนแสบตา แต่ดูเหมือนว่ามีบางสิ่งเปล่งประกายอยู่ใต้ผิวน้ำ。"
  },
  Event_50014_Name = {
    Text = "ภูติแห่งความตาย"
  },
  Event_50015_ChoiceDesc1 = {
    Text = "【พยายามจำให้ได้】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50015_ChoiceDesc2 = {
    Text = "【ยื่นมือสัมผัส】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50015_ChoiceDesc3 = {
    Text = "【ขยี้ตา】ได้รับ 25 รอยดำ"
  },
  Event_50015_Desc = {
    Text = "คุณถูกนูเบียผลักจนขาอีกข้างจมหายไปในแม่น้ำศักดิ์สิทธิ์\nคุณพยายามตั้งหลัก แต่กลับเห็นภาพสะท้อนที่ไม่ควรเห็นในระลอกน้ำที่สั่นไหว\nนั่นคือชายหนุ่มร่างสูงในชุดนักเรียนมิซากะ ซึ่งร่างกายเขาพลิ้วไหวและอ่อนแรงอยู่ในกระแสแม่น้ำศักดิ์สิทธิ์。"
  },
  Event_50015_Name = {
    Text = "ภูติแห่งความตาย"
  },
  Event_50016_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50016_Desc = {
    Text = "ความตื่นตระหนกกัดกร่อนจิตใจของคุณ ความเจ็บปวดทำให้สติของคุณมัวหมอง คุณพยายามฉีกออก แต่เถาวัลย์กลับรัดแน่นขึ้นเรื่อยๆ น้ำมูกที่มีกลิ่นแปลกซึมซาบเข้าสู่โพรงจมูก ทุกครั้งที่หายใจเต็มไปด้วยความสิ้นหวังที่เหนียวหนึบ。\nราโมน่าฟันลงไปด้วยดาบ นูเบียขาหักหนีไป คุณดึงหนวดที่ติดอยู่ข้างใบหน้าส่วนสุดท้ายออกมา บนมันมีเลือดและเนื้อที่เบลออยู่ชั้นหนึ่ง。"
  },
  Event_50016_Name = {
    Text = "ลมพัดเข้าหน้า"
  },
  Event_50017_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50017_Desc = {
    Text = "แสงสีเงินพุ่งเข้าใส่ร่างของนูเบีย ความรู้สึกของเนื้อและเลือดแตกกระจายถูกส่งผ่านไปยังปลายนิ้วและข้อมือของคุณผ่านกุญแจเงิน。\nหนวดที่บิดเบือนของนูเบียยกสูงขึ้นสู่ท้องฟ้า แผดเสียงร่ำร้องอย่างสยองขวัญและเศร้าโศก กลายเป็นของเหลวที่หนืดและไม่ทราบชนิด。"
  },
  Event_50017_Name = {
    Text = "ลมพัดเข้าหน้า"
  },
  Event_50018_ChoiceDesc1 = {
    Text = "【ฉีกกระชาก】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50018_ChoiceDesc2 = {
    Text = "【ทะลวง】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_50018_Desc = {
    Text = "หนวดพันกันของนูเบียบิดเบือนและเต้นรำอย่างดุเดือด ช่วงชิงโอกาสพุ่งเข้าหาแก้มของคุณ และบุกเข้าไปในปากและจมูกของคุณอย่างโกรธา。"
  },
  Event_50018_Name = {
    Text = "ลมพัดเข้าหน้า"
  },
  Event_50019_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50019_Desc = {
    Text = "ผิวน้ำมีเพียงแสงสะท้อนระยิบระยับเท่านั้น \n คุณดึงขาเปียกชื้นออกและเทกรวดที่เปียกชื้นออกจากรองเท้า \n ภาพเมื่อสักครู่ยังคงวนเวียนอยู่ในหัวของคุณ ไม่สามารถลบออกไปได้。"
  },
  Event_50019_Name = {
    Text = "ภูติแห่งความตาย"
  },
  Event_50029_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50029_Desc = {
    Text = "「เขาจะกลับมาไหม? หรือจะทิ้งคุณไว้ในทะเลทรายที่ไร้ขอบเขตนี้ตลอดไป?」\n「เขาจะหาคุณเจอไหม? หรือจะหลงเส้นทางของคุณไปเพราะทิศทางลมและการเปลี่ยนแปลงของเนินทราย?」\n「ความหวังที่คุณฝากไว้กับผู้อื่นนั้น มันเชื่อถือได้จริงหรือ?」"
  },
  Event_50029_Name = {
    Text = "พื้นที่ทรายสูญหาย"
  },
  Event_50030_ChoiceDesc1 = {
    Text = "【การขอความช่วยเหลือ】การตื่นขึ้นแบบสุ่ม 1 ร่างกายที่ตื่นขึ้น ได้รับการติดเชื้อ「(Skill.Arg1)」"
  },
  Event_50030_ChoiceDesc2 = {
    Text = "【ก้าวไปด้วยกัน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_50030_Desc = {
    Text = "เสียงที่มาจากไกลผสมผสานกับเสียงน้ำไหลถามคุณว่า \n「คุณสูญหายในทะเลทรายสีเหลืองอันกว้างใหญ่」 \n「คุณมีทางเลือกสองทางอยู่ตรงหน้าคุณ เพื่อนของคุณเดินเร็วกว่า ให้เขานำอาหารและน้ำไปขอความช่วยเหลือ และคุณจะอยู่ที่เดิมโดยใช้ทรัพยากรน้อยที่สุด」 \n「หรือคุณจะแบ่งปันทุกอย่างและเดินหน้าต่อไป」"
  },
  Event_50030_Name = {
    Text = "พื้นที่ทรายสูญหาย"
  },
  Event_50031_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50031_Desc = {
    Text = "「พวกคุณอาจจะเดินไปได้ไม่ไกล แต่จิตวิญญาณและเนื้อหนังของพวกคุณแนบแน่นกัน และได้รับพละกำลังในการปลุกใจซึ่งกันและกัน。」\n「นี่คือการเลือกของคุณ。」\n กล่าวจบ ดวงอาทิตย์ที่ร้อนระอุในอากาศสูงได้ปิดตาลง。"
  },
  Event_50031_Name = {
    Text = "พื้นที่ทรายสูญหาย"
  },
  Event_50064_ChoiceDesc1 = {
    Text = "【ตัดริบบิ้นแดง】ลบการ์ดคำสั่ง 1 ใบ ได้รับรอยดำ Arg1"
  },
  Event_50064_ChoiceDesc2 = {
    Text = "【ต่อสู้】คัดลอกการ์ดคำสั่ง 1 ใบ แพร่เชื้อ「(Skill.Arg1)」"
  },
  Event_50064_ChoiceDesc3 = {
    Text = "【เรียกรามอน่า】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_50064_Desc = {
    Text = "คาเซียสะบัดผ้าแพรสีแดง พันที่กระเป๋าของคุณในพริบตา"
  },
  Event_50064_Name = {
    Text = "ผ้าไหมพันกัน"
  },
  Event_50065_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50065_Desc = {
    Text = "เสียงเคาะที่ใสและดังสลับกันไปมาดังก้องอยู่ระหว่างท่อที่พาดอยู่เหนือศีรษะของพวกคุณ ราวกับวิญญาณที่เต้นรำอยู่ตามลำพัง ส่ายแขนที่อ่อนแรงในพื้นที่ที่เงียบสงัดนี้\nความคิดนี้กระตุ้นความรู้สึกหนาวเหน็บที่เข้มข้นของความกลัวโบราณในใจของคุณ。"
  },
  Event_50065_Name = {
    Text = "สเกลประหลาด"
  },
  Event_50066_ChoiceDesc1 = {
    Text = "【สำรวจที่ปากถ้ำ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_50066_ChoiceDesc2 = {
    Text = "【สำรวจถ้ำลึก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50066_Desc = {
    Text = "「ที่นี่มีถ้ำอยู่。」\nทาอิสหันตัวไปข้างๆ และส่งคำเชิญถึงคุณ。\n「อยากเข้าไปดูไหม?」\nถ้ำแคบและมืดมิดลึกซึ้ง เหมือนปากยักษ์ของปีศาจที่ยื่นออกไปยังความมืดที่ไม่มีที่สิ้นสุด ใครก็ตามที่ก้าวเข้าสู่ดินแดนรกร้างนี้ จะไม่สามารถหลีกหนีจากลางสังหรณ์ที่น่าสะพรึงกลัวที่ผุดขึ้นจากส่วนลึกของไขสันหลังได้ เหมือนกับว่าในทุกมุมของถ้ำนี้มีสิ่งมีชีวิตโบราณที่ไม่กล้ามองแสงอาทิตย์ซ่อนตัวอยู่ รอคอยการมาถึงของผู้บุกรุก。"
  },
  Event_50066_Name = {
    Text = "ถ้ำมืด"
  },
  Event_50067_ChoiceDesc1 = {
    Text = "【โจมตีทีละเป้าหมาย】สุ่มอัปเกรดสิ่งสร้างเงิน 1 ชิ้นเป็นสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_50067_ChoiceDesc2 = {
    Text = "【ล้อมรอบสองคน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50067_ChoiceDesc3 = {
    Text = "【แอบฟังการสนทนา】ได้รับ 25 รอยดำ"
  },
  Event_50067_Desc = {
    Text = "ชาวอัลลันสองคนเฝ้าประตูโรงงานอยู่ \n หนึ่งในนั้นเดินไปเดินมาอย่างไร้จุดหมาย พยายามพูดคุยกับอีกคน \n 「มีคนพูดว่า ท่านจูเลียตกำลังนับจำนวนทีมที่พยายามฝ่ากำแพงพายุอีกครั้ง」 \n 「ฉันขออย่าให้ถูกเลือกเลย」"
  },
  Event_50067_Name = {
    Text = "ผู้รักษาประตูที่ว่างเว้น"
  },
  Event_50067_Tips1 = {
    Text = "ยังไม่มีสิ่งสร้างเงิน"
  },
  Event_50068_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50068_Desc = {
    Text = "ไม่มอง ไม่ฟัง ไม่คิด \n ไม่สนใจเสียงแปลกๆ ที่ดังมา คุณตรงไปยังซากของต้นแม่"
  },
  Event_50068_Name = {
    Text = "สเกลประหลาด"
  },
  Event_50069_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50069_Desc = {
    Text = "ราโมน่าฟันดาบไปที่คาเซียห์ที่กำลังสะบัดผ้าแพรสีแดง คาเซียห์รีบหลบและผ้าแพรสีแดงที่พันอยู่กับคุณก็หลุดออกในทันที。"
  },
  Event_50069_Name = {
    Text = "ผ้าไหมพันกัน"
  },
  Event_50070_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50070_Desc = {
    Text = "พวกคุณแยกกันเป็นสองทาง คุณและราโมน่าไปทางซ้าย ส่วนไรเกอร์ไปทางขวา ทำการโจมตีจากทั้งสองด้าน \n คุณยกมือขึ้นเป็นสัญญาณ ราโมน่าและไรเกอร์จึงร่วมมือกันโจมตี ทหารรักษาการณ์ของอาลานสองคนล้มลงอย่างเงียบๆ。"
  },
  Event_50070_Name = {
    Text = "ผู้รักษาประตูที่ว่างเว้น"
  },
  Event_50071_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50071_Desc = {
    Text = "ช่วงนี้ไม่ควรเข้าไปในกับดัก คุณแค่เดินวนอยู่ที่ปากถ้ำก็เกือบจะรู้สึกถึงการเต้นของความชั่วร้ายที่ซ่อนอยู่ในจังหวะของหินแล้ว。"
  },
  Event_50071_Name = {
    Text = "ถ้ำมืด"
  },
  Event_50072_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50072_Desc = {
    Text = "ตามสัญญาณของคุณ ไรเกอร์ใช้ลูกเต๋าทำให้ผู้คุมอาลานที่เงียบงันหมดสติ จากนั้นเขาก็ค่อย ๆ เข้าใกล้ชายคนหนึ่งที่ยังคงพูดไม่หยุดอยู่\n「เฮ้ น้อง ถ้าท่านจูเลียตนั่นเป็นคนหลอกลวง คุณคิดว่าจะทำยังไงดี?」\n「ฉันก็ไม่รู้ว่าจะทำยังไงดี」\nไรเกอร์ยิ้มกว้าง ผู้คุมตัวสั่นและกำลังจะกรีดร้อง แต่ไรเกอร์ปิดปากจมูกเขาไว้。"
  },
  Event_50072_Name = {
    Text = "ผู้รักษาประตูที่ว่างเว้น"
  },
  Event_50073_ChoiceDesc1 = {
    Text = "【รับฟังอย่างตั้งใจ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50073_ChoiceDesc2 = {
    Text = "【ปิดหู】ทุกครั้งที่มีตัวปลุกที่มีค่าความคลั่ง 50 ขึ้นไป ได้รับ 15 รอยดำ"
  },
  Event_50073_ChoiceDesc3 = {
    Text = "【ดู】ได้รับตัวเลือกการแกะสลัก เลือก 1 จาก 3"
  },
  Event_50073_Desc = {
    Text = "เมื่อพวกคุณเข้าไปในชั้นที่มีซากศพ เสียงติ๊งต๊องที่ไพเราะดังขึ้นอย่างกะทันหันในโรงงานร้างที่ว่างเปล่า ความรู้สึกของเสียงเปียโนที่ใสสะอาดไม่เข้ากับซากเหล็กสนิม。"
  },
  Event_50073_Name = {
    Text = "สเกลประหลาด"
  },
  Event_50074_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50074_Desc = {
    Text = "「เฮ้ น้องชาย ถ้าคุณยูลีเอตเป็นคนหลอกลวง คุณจะทำยังไง?」\n「อย่าพูดมั่ว ตั้งแต่คุณยูลีเอตมาที่นี่ ทุกอย่างก็ถูกจัดการอย่างเป็นระเบียบเรียบร้อย เธอเป็นคนหลอกลวง ทำไมถึงช่วยชาวอาลานมากมายขนาดนี้?」\nในขณะที่พวกเขาพูดคุยกัน ไรเกอร์ก็เลือกตำแหน่งซุ่มโจมตีอย่างเงียบๆ และโยนลูกเต๋าสองลูกออกไป ปัง ปัง ทำให้ทั้งสองล้มลงกับพื้น。"
  },
  Event_50074_Name = {
    Text = "ผู้รักษาประตูที่ว่างเว้น"
  },
  Event_50075_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50075_Desc = {
    Text = "คุณรวบรวมความกล้าแล้วจ้องมองกลับไป \n ดวงตาขนาดใหญ่ของม่านบิดเบือนและยิ้มเหี้ยมเกรียม การต่อต้านอย่างแข็งแกร่งของคุณเริ่มสั่นคลอนและพ่ายแพ้。"
  },
  Event_50075_Name = {
    Text = "ตาเวทมนตร์"
  },
  Event_50076_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50076_Desc = {
    Text = "คุณฉีกม่านด้วยความแน่วแน่และไม่ลังเล \n ดวงตาขนาดใหญ่ในฝ่ามือของคุณกลายเป็นเศษผ้าที่ไร้มิติและแหลกสลาย"
  },
  Event_50076_Name = {
    Text = "ตาเวทมนตร์"
  },
  Event_50077_ChoiceDesc1 = {
    Text = "【จ้องกลับ】ได้รับสิ่งประดิษฐ์ทองคำ 「(RelicConfig.Arg1)」 ได้รับผลกระทบจาก 「(Skill.Arg2)」"
  },
  Event_50077_ChoiceDesc2 = {
    Text = "【ฉีกม่าน】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_50077_Desc = {
    Text = "ม่านเปิดออกเผยให้เห็นตาขนาดใหญ่ที่บิดเบี้ยวจำนวนมาก \n สิ่งมีชีวิตขนาดใหญ่ที่ซ่อนอยู่เบื้องหลังนัยน์ตานั้นแสดงถึงความกระหายที่ผิดปกติและกำลังเคลื่อนไหวอย่างกระตือรือร้น。"
  },
  Event_50077_Name = {
    Text = "ตาเวทมนตร์"
  },
  Event_50078_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50078_Desc = {
    Text = "ดั้งเดิมคือชิ้นส่วนยาวที่ถูกทิ้งร้างถูกการเคลื่อนไหวของพวกคุณทำให้สั่นสะเทือน และกระทบกับท่อเหล็กอย่างโยกเยก。"
  },
  Event_50078_Name = {
    Text = "สเกลประหลาด"
  },
  Event_50079_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50079_Desc = {
    Text = "ทาอิสก้าวเข้าไปในถ้ำอย่างมั่นใจ ขณะที่คุณตามหลังไปสำรวจอย่างระมัดระวัง \n「ระวังนะ!」คุณถูกดึงออกอย่างกะทันหัน จนล้มลงในอ้อมกอดที่นุ่มนวล \n ข้างหน้าคุณ สัตว์ยักษ์สีดำสนิทพุ่งออกมาจากถ้ำอย่างรวดเร็ว \n「มองที่นี่สิ」ในขณะที่คุณยังคงตกใจไม่หาย ทาอิสได้พูดขึ้น ดวงตาของเธอส่องแสงเรืองรองในความมืด 「อาจจะเป็นสมบัติของมันก็ได้นะ。」"
  },
  Event_50079_Name = {
    Text = "ถ้ำมืด"
  },
  Event_50080_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50080_Desc = {
    Text = "คุณพยายามอย่างยิ่งที่จะจับหูจับของกระเป๋าถือเอาไว้ ต่อต้านกับผ้าแพรสีแดง \n แต่ผ้าแพรสีแดงนั้นมีพลังมหาศาล กระเป๋าถือของคุณหลุดมือ และของใช้กระจายเต็มพื้น。"
  },
  Event_50080_Name = {
    Text = "ผ้าไหมพันกัน"
  },
  Event_50081_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50081_Desc = {
    Text = "คุณเกลียดความรู้สึกที่ถูกผูกมัด。\nคุณจับผ้าแพรสีแดงแล้วฉีกมันออกเป็นสองส่วนด้วยเสียงดังแฉลบ。\nผ้าแพรสีแดงที่เหลืออยู่ครึ่งหนึ่งเคลื่อนที่เหมือนงูสีแดง。"
  },
  Event_50081_Name = {
    Text = "ผ้าไหมพันกัน"
  },
  Event_50276_ChoiceDesc1 = {
    Text = "【กำจัดเครื่องบูชายัญ】ได้รับสิ่งมีชีวิตแห่งคำสาป \"(RelicConfig.Arg1)\"，ติดเชื้อ \"(Skill.Arg2)\""
  },
  Event_50276_ChoiceDesc2 = {
    Text = "【แก้เชือก】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_50276_ChoiceDesc3 = {
    Text = "【เดินหน้าต่อไป】ได้รับ 50 รอยดำ"
  },
  Event_50276_Desc = {
    Text = "ชาวอัลลันสามคนถูกมัดอยู่บนแท่นสูง \n ร่างกายของพวกเขาปรากฏลวดลายสีเข้มคล้ายเปลือกไม้ที่คุณเคยเห็นบนตัวทารก และพวกเขาก็กำลังพร่ำพูดอะไรบางอย่าง。"
  },
  Event_50276_Name = {
    Text = "สามของสังเวย"
  },
  Event_50277_ChoiceDesc1 = {
    Text = "【จ้องมอง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อไวรัส「(Skill.Arg2)」"
  },
  Event_50277_ChoiceDesc2 = {
    Text = "【ละเลย】ได้รับการแกะสลักแบบเลือกได้ 1 ใน 3"
  },
  Event_50277_Desc = {
    Text = "ชาวอาลันคุกเข่าลงในพายุทราย。\nพายุโหมกระหน่ำร่างกายของพวกเขา เม็ดทรายพัดพาใจศรัทธาของพวกเขาไป。\nในวังวนของฝุ่นทราย ดูเหมือนจะมีดวงตาใหญ่ไม่รู้จบ眺มองโลกาที่บิดเบือน。"
  },
  Event_50277_Name = {
    Text = "กิจันต์ทรายและฝุ่น"
  },
  Event_50278_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50278_Desc = {
    Text = "ภาพที่คุณไม่ต้องการนึกถึงปรากฏขึ้นอีกครั้งตรงหน้า\nหนวดที่สั่นไหว รอยเลือดที่ถูกตัดด้วยเศษกระจก...\nคุณรู้สึกคลื่นไส้。"
  },
  Event_50278_Name = {
    Text = "กู๋ลู่Ⅱ"
  },
  Event_50279_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50279_Desc = {
    Text = "เธอไม่ได้อยู่ที่นี่ เธอไม่ได้อยู่ในกระแสอันตรายที่สุด \nแค่นี้ก็น่าจะทำให้คุณรู้สึกโล่งใจขึ้นบ้างแล้ว"
  },
  Event_50279_Name = {
    Text = "การเดินทางคนเดียวⅠ"
  },
  Event_50280_ChoiceDesc1 = {
    Text = "【จู่โจม】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_50280_ChoiceDesc2 = {
    Text = "【โจมตี】การ์ดคำสั่ง 3 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50280_Desc = {
    Text = "นูเบียตัวหนึ่งกำลังดิ้นรนอยู่ในพายุทรายอย่างรุนแรง。\nขาของมันฝังลึกอยู่ในทรายเหลือง พยายามอย่างเต็มที่เพื่อหลีกเลี่ยงการถูกดูดเข้าไปในวังวน。"
  },
  Event_50280_Name = {
    Text = "พายุทรายธรรมชาติ"
  },
  Event_50281_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50281_Desc = {
    Text = "คุณเดินเข้ามาอย่างเด็ดเดี่ยว ขณะที่เสียงร้องอุทานของชาวอัลลันดังขึ้น คุณได้ดึงเชือกออก \n นักรบอาลานคนหนึ่งค่อยๆ เข้าใกล้ คุณแย่งหอกในมือเขามาและชี้ไปยังฝูงชนที่มืดมิด。"
  },
  Event_50281_Name = {
    Text = "สามของสังเวย"
  },
  Event_50282_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50282_Desc = {
    Text = "เหตุผลบอกคุณว่า เขาจะไม่มาแล้ว\nใช่แล้ว ใครจะคาดหวังว่านักพนันจะรักษาสัญญาล่ะ?\nคุณมีแต่ความโดดเดี่ยว คุณมีแต่ความโดดเดี่ยว。"
  },
  Event_50282_Name = {
    Text = "การเดินทางเพียงลำพัง III"
  },
  Event_50283_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50283_Desc = {
    Text = "อาการไข้สูงที่ผิดปกติจะรุนแรงขึ้นตามการฟื้นฟูของต้นแม่ไหม?\nราโมน่าจะดูแลตัวเองได้ดีไหมเมื่ออยู่คนเดียวอยู่นอกกำแพงพายุ?\nตอนนี้ไม่ใช่เวลาที่จะวอกแวก แต่คุณไม่สามารถหยุดกังวลเกี่ยวกับคู่หูของคุณได้。"
  },
  Event_50283_Name = {
    Text = "การเดินทางคนเดียวⅠ"
  },
  Event_50284_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50284_Desc = {
    Text = "คุณมุ่งมั่นที่จะเผชิญหน้ากับมัน นูเบียกลับเหมือนพบจุดยืนที่หาได้ยาก กระโดดขึ้นไปเกาะที่ศีรษะของคุณ \n คุณติดอยู่ในความยุ่งเหยิงของพายุทรายและนูเบีย \n 「การมีความกล้าหาญเพียงอย่างเดียวไม่ใช่หนทางสู่ชัยชนะ」 เสียงเย็นชาของวิลเลียมฟังดูเหมือนพระพรจากสวรรค์สำหรับคุณที่ถูกปิดหู 「จงเรียนรู้ที่จะคว้าโอกาส」"
  },
  Event_50284_Name = {
    Text = "พายุทรายธรรมชาติ"
  },
  Event_50285_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50285_Desc = {
    Text = "ตอนนี้ไม่ใช่เวลาอ่านหนังสือพิมพ์อย่างสบายใจ"
  },
  Event_50285_Name = {
    Text = "คำเตือนของเธอ"
  },
  Event_50286_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50286_Desc = {
    Text = "คุณไม่ต้องคิด คุณไม่ต้องระลึกถึง \n คุณไม่อยากคิด คุณไม่อยากระลึกถึง \n ตำนานของมิซากะจะสิ้นสุดลง แต่การเดินทางของมิซากะจะไม่หยุดลง \n คุณต้องเดินต่อไป คุณต้องเดินต่อไป。"
  },
  Event_50286_Name = {
    Text = "กู๋ลู่Ⅱ"
  },
  Event_50287_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50287_Desc = {
    Text = "「เรียน ผู้พิทักษ์：\nหวังว่าคุณสบายดี \nขอโทษที่ในทริปเลมวาฮีครั้งนี้ ฉันไม่สามารถอยู่เคียงข้างคุณได้เพราะดูแลร่างกายตัวเองไม่ดี \nแต่ในช่วงเวลาสำคัญ โปรดเชื่อใจผู้ช่วยคนเดียวของคุณ \nเมื่อคุณต้องการฉัน ฉันจะอยู่เสมอ」\nเพราะเหตุผลด้านเวลา คุณจึงไม่สามารถอ่านต่อไปได้ \nแต่ลายมือที่คุ้นเคยกลับมอบความรู้สึกสงบและมั่นคงให้กับคุณ。"
  },
  Event_50287_Name = {
    Text = "คำเตือนของเธอ"
  },
  Event_50288_ChoiceDesc1 = {
    Text = "【เขาจะมาอีก】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_50288_ChoiceDesc2 = {
    Text = "【เขาจะไม่มาแล้ว】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_50288_Desc = {
    Text = "คนสุดท้ายที่ออกไปคือไรเกอร์。\nเพื่อหยุดคาเซียห์ เขาเลือกที่จะอยู่ในเต็นท์。\nเขาเคยสัญญากับคุณว่าในที่สุดจะต้องบุกเข้าไปในพิธีเพื่อเผาต้นแม่ เขาก็จะอยู่เคียงข้างคุณแน่นอน。\nแต่ตอนนี้เขายังไม่มาหาคุณเลย。\nเหลือเพียงคุณคนเดียว。"
  },
  Event_50288_Name = {
    Text = "การเดินทางเพียงลำพัง III"
  },
  Event_50289_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50289_Desc = {
    Text = "กรุ๊งกริ๊ง สามสิ่งกลมๆ ที่น่าสยดสยองกำลังกลิ้งอยู่ในสถานที่จัดพิธี \n คุณรู้สึกว่าตัวเองไม่เหมือนเดิม บรรยากาศพิธีที่บ้าคลั่งและผิดปกติได้ดึงคุณเข้าสู่สุญญตาที่ไม่สามารถอธิบายได้。"
  },
  Event_50289_Name = {
    Text = "สามของสังเวย"
  },
  Event_50290_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50290_Desc = {
    Text = "ความเชื่อมั่นของชาวอาลานนั้นจริงจังยิ่งนัก ยินดีที่จะถูกฝังอยู่ใต้ทรายเหลืองซ้ำแล้วซ้ำเล่า。\nแต่เมื่อคุณเงยหน้าขึ้นมอง ในพายุไม่มีสุริยันเลย。"
  },
  Event_50290_Name = {
    Text = "กิจันต์ทรายและฝุ่น"
  },
  Event_50291_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50291_Desc = {
    Text = "ขอให้ทะเลทรายตอบรับความศรัทธาของพวกเขาค่ะ"
  },
  Event_50291_Name = {
    Text = "กิจันต์ทรายและฝุ่น"
  },
  Event_50292_ChoiceDesc1 = {
    Text = "【หลุดพ้นจากอดีต】สุ่มเพิ่มระดับคุณภาพการแกะสลักของการ์ด 1 ใบ"
  },
  Event_50292_ChoiceDesc2 = {
    Text = "【จับภาพความทรงจำ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50292_Desc = {
    Text = "คนที่สองที่จากไปคือวิลเลียม。"
  },
  Event_50292_Name = {
    Text = "กู๋ลู่Ⅱ"
  },
  Event_50293_ChoiceDesc1 = {
    Text = "【วางใจ】ได้รับ 25 รอยดำ"
  },
  Event_50293_ChoiceDesc2 = {
    Text = "【กังวล】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_50293_Desc = {
    Text = "คุณนึกถึงวันที่เริ่มต้นการเดินทางขึ้นมาอย่างกะทันหัน \n รามอน่าคอยเตือนคุณให้จัดกระเป๋า วิลเลียมเตรียมคู่มือการบันทึกระหว่างทางให้คุณ ไรเกอร์แอบใส่วิสกี้หนึ่งขวดลงในกระเป๋าของคุณ \n ตอนนี้พวกเขาได้จากไปแล้ว \n\n คนแรกที่จากไปคือรามอน่า พละกำลังของทาวิลและอำนาจของกำแพงพายุขัดแย้งกัน เธอจึงล้มเหลวจากไข้สูงระหว่างทาง。"
  },
  Event_50293_Name = {
    Text = "การเดินทางคนเดียวⅠ"
  },
  Event_50294_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50294_Desc = {
    Text = "คุณโจมตีเท้าของนูเบียอย่างลับๆ มันยืนไม่มั่นคง หนวดพันกันหลายเส้นเต้นรำอย่างรีบเร่งและยุ่งเหยิงในอากาศ สุดท้ายถูกดูดเข้าไปในพายุฝุ่น。"
  },
  Event_50294_Name = {
    Text = "พายุทรายธรรมชาติ"
  },
  Event_50295_ChoiceDesc1 = {
    Text = "【อ่าน】ลบการ์ด 1 ใบ"
  },
  Event_50295_ChoiceDesc2 = {
    Text = "【เก็บ】ได้รับ「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_50295_Desc = {
    Text = "ติ๊ด ติ๊ด。\nใต้แท่นบูชาที่คลุ้มคลั่งนี้ เสียงกลองหนักๆ ดังมาจากลมทรายที่พัดมา ในเสียงร้องที่ไม่ขาดสาย คุณกลับได้ยินเสียงเบาๆ ของเครื่องพิมพ์ดีด นั่นคือเสียงเพรียกจากมิซากะ ที่ปลอบประโลมจิตใจที่ไม่สงบของคุณ。"
  },
  Event_50295_Name = {
    Text = "คำเตือนของเธอ"
  },
  Event_50296_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50296_Desc = {
    Text = "เลคเป็นผู้ที่มีโชคดีเกินกว่าโลกีย์\nสิ่งที่เขาสัญญาไว้กับคุณ เขาจะทำตามนั้นแน่นอน\nอย่างแน่นอน"
  },
  Event_50296_Name = {
    Text = "การเดินทางเพียงลำพัง III"
  },
  Event_50297_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_50297_Desc = {
    Text = "ไม่เกี่ยวกับคุณ \n สิ่งที่คุณต้องทำทันทีคือรีบเข้าไปสัมผัสและทำลายซากของต้นแม่"
  },
  Event_50297_Name = {
    Text = "สามของสังเวย"
  },
  Event_52373_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_52373_Desc = {
    Text = "คุณรอดชีวิต คุณเห็นกองดินที่ถูกสร้างขึ้นมากมาย ร่างกายที่ถูกเผาไหม้\nดูเหมือนว่าคุณจะเผาบางสิ่งบางอย่างเช่นกัน แต่เรื่องนั้นไม่มีความสำคัญอีกต่อไปแล้ว\nคุณได้ยินเสียงระฆังแห่งอาณาจักรเทพที่ดังขึ้น。"
  },
  Event_52373_Name = {
    Text = "การบุกโจมตีของกาฬโรค"
  },
  Event_52374_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_52374_Desc = {
    Text = "คุณรอดชีวิต คุณเห็นกองดินที่ถูกสร้างขึ้นมากมาย ร่างกายที่ถูกเผาไหม้\nคุณพยายามปกป้องสิ่งที่คุณให้ความสำคัญอย่างสุดความสามารถ และเพื่อสิ่งนั้น คุณก็ต้องจ่ายในราคาที่ต้องจ่ายที่เจ็บปวด แต่เรื่องนั้นไม่มีความสำคัญอีกต่อไปแล้ว\nคุณได้ยินเสียงระฆังแห่งอาณาจักรเทพที่ดังขึ้น。"
  },
  Event_52374_Name = {
    Text = "การบุกโจมตีของกาฬโรค"
  },
  Event_52375_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_52375_Desc = {
    Text = "ความโกรธของยักษ์ได้สงบลงชั่วคราว เมฆจางหาย ฝนหยุดตก ลมสงบ ทะเลเหมือนกับแม่ผู้มีความรักนิรันดร์ คลื่นอ่อนๆ ค่อยๆ ลูบไล้หลังของลีมูเรีย ทิ้งไว้เพียงซากศพและซากปรักหักพังบนร่างของลีมูเรีย \nคุณพยายามปกป้องสิ่งที่คุณให้ความสำคัญอย่างสุดความสามารถ และเพื่อสิ่งนั้น คุณก็ต้องจ่ายในราคาที่ต้องจ่ายที่เจ็บปวด แต่เรื่องนั้นไม่มีความสำคัญอีกต่อไปแล้ว \nในมหาสมุทร คุณได้มองลับไปยังรูปร่างของประเทศเทพ。"
  },
  Event_52375_Name = {
    Text = "เสียงคำรามของมหาสมุทร"
  },
  Event_52376_ChoiceDesc1 = {
    Text = "【ถวายของบูชาเพิ่มเติม】ลบการ์ดคำสั่ง 1 ใบ และเพิ่ม「ภาพลวงตาแห่งสวรรค์」3 ชนิดอย่างละ 1 ใบเข้าไปในสำรับไพ่。"
  },
  Event_52376_Desc = {
    Text = "ยืนอยู่ต่อหน้าบัลลังก์ที่ลีมูเรียถล่ม คุณได้ถวายเครื่องบูชาครั้งสุดท้าย \n หุบเหวที่ไม่มีที่สิ้นสุดเปิดเผยต่อหน้าคุณ คุณคุกเข่า ยิ้ม และน้ำตาไหลอาบแก้ม \n “ดูสิ พ่อ เดบอรา ดูสิ พระราชาของข้าผู้สูงส่ง—ประเทศเทพ ได้ปรากฏตัวต่อหน้าข้าแล้ว!”"
  },
  Event_52376_Name = {
    Text = "ต้อนรับเถอะ，สวรรค์"
  },
  Event_52377_ChoiceDesc2 = {
    Text = "【ปกป้องสิ่งที่รัก】สูญเสียชีวิตจำนวน Arg1，ได้รับการ์ดอาการแบบสุ่ม 1 ใบ。"
  },
  Event_52377_Desc = {
    Text = "โลกา โลกาที่เงียบสงบ โลกาที่มั่นคง โลกาที่รองรับมนุษยชาติ โลกาที่เป็นอมตะ แต่โลกากลับสั่นสะเทือน มันแตกออกเป็นรอยแยกที่ลึกไม่รู้จบ สิ่งที่มันรองรับอยู่ในสภาพไม่มั่นคง \nท่านฝากความหวังทั้งหมดไว้ที่โลกา เมื่อโลกาเริ่มสั่นสะเทือน ท่านจะไปที่ไหน? \nจงบูชายัญเถิด ประชากรลีมูเรียเรียกหา ท่านจงบูชายัญทุกสิ่งของท่าน ให้ประเทศเทพที่ปราศจากภัยพิบัติมาปรากฏตัว。"
  },
  Event_52377_Name = {
    Text = "การสั่นไหวของแผ่นดิน"
  },
  Event_52378_ChoiceDesc2 = {
    Text = "【ปกป้องสิ่งที่รัก】สูญเสียชีวิตจำนวน Arg1，ได้รับการ์ดอาการแบบสุ่ม 1 ใบ。"
  },
  Event_52378_Desc = {
    Text = "มหาสมุทร มหาสมุทรเป็นแม่ที่ให้กำเนิดลีมูเรีย เป็นชีวิตของคุณ เป็นศรัทธาของคุณ และในขณะนี้ มหาสมุทรยืนขึ้นเหมือนยักษ์ใหญ่ผู้โกรธแค้นในตำนาน พระองค์ตะโกนและเรียกร้อง ก่อให้เกิดน้ำทะเลที่อ่อนนุ่มกลายเป็นหินยักษ์แข็งและเหล็กแหลม ฟาดฟันทุกสิ่งที่อยู่เบื้องหน้า พระองค์มองดูลีมูเรียที่สั่นสะเทือนอยู่ใต้ฝ่าเท้าอย่างเฉยเมย มองดูชาวลีมูเรียที่วิ่งหนีเหมือนแมลง พระองค์จะทำลายลีมูเรีย ซึ่งไม่เกี่ยวข้องกับลีมูเรีย \n บูชายัญเถอะ ประชากรลีมูเรียกำลังเรียกหาคุณ ให้ถวายทุกสิ่งของคุณ เพื่อประเทศเทพที่ปราศจากภัยจะปรากฏขึ้น。"
  },
  Event_52378_Name = {
    Text = "เสียงคำรามของมหาสมุทร"
  },
  Event_52379_ChoiceDesc2 = {
    Text = "【ปกป้องสิ่งที่รัก】สูญเสียชีวิตจำนวน Arg1，ได้รับการ์ดอาการแบบสุ่ม 1 ใบ。"
  },
  Event_52379_Desc = {
    Text = "โรคระบาด โรคระบาดอยู่ทุกหนทุกแห่ง โรคระบาดคือบ่าวที่ไร้ยางอายที่สุด เมื่อการลงโทษของเทพเจ้าแห่งแผ่นดินและมหาสมุทรผ่านพ้นไป มันจึงเป็นผู้ประกาศการตายที่ไม่สามารถเอ่ยออกมาได้ของเทพเจ้า การฝังศพของญาติ การเผาศพของญาติ การสวดมนต์ให้กับผู้ที่ตายเพื่อปกป้องตนเองให้ห่างไกลออกไป ชีวิตและมนุษยธรรมไม่อาจต้านทานต่อโรคระบาดได้ \nพลีชีพเถอะ ประชากรลีมูเรียกำลังเรียกร้องหาคุณ พลีชีพทุกสิ่งของคุณ เพื่อให้ประเทศเทพที่ปราศจากภัยพิบัติได้มาถึง。"
  },
  Event_52379_Name = {
    Text = "การบุกโจมตีของกาฬโรค"
  },
  Event_52380_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_52380_Desc = {
    Text = "การสั่นสะเทือนอย่างรุนแรงได้สงบลง ถนนเต็มไปด้วยรอยเลือดสีแดงเข้ม ใต้ซากบ้านที่พังทลาย มีผู้คนจำนวนมากถูกฝังไว้\nคุณพยายามปกป้องสิ่งที่คุณให้ความสำคัญอย่างสุดความสามารถ และเพื่อสิ่งนั้น คุณก็ต้องจ่ายในราคาที่ต้องจ่ายที่เจ็บปวด แต่เรื่องนั้นไม่มีความสำคัญอีกต่อไปแล้ว\nสิ่งที่สำคัญเพียงอย่างเดียวคือ คุณได้เข้าใกล้ประเทศเทพอีกหนึ่งก้าว。"
  },
  Event_52380_Name = {
    Text = "การสั่นไหวของแผ่นดิน"
  },
  Event_52381_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_52381_Desc = {
    Text = "ยืนอยู่ต่อหน้าบัลลังก์ที่ลีมูเรียถล่ม คุณได้สวดมนต์ครั้งสุดท้าย \n หุบเหวที่ไม่มีที่สิ้นสุดเปิดเผยต่อหน้าคุณ คุณคุกเข่า ยิ้ม และน้ำตาไหลอาบแก้ม \n “ดูสิ พ่อ เดบอรา ดูสิ พระราชาของข้าผู้สูงส่ง—ประเทศเทพ ได้ปรากฏตัวต่อหน้าข้าแล้ว!”"
  },
  Event_52381_Name = {
    Text = "ต้อนรับเถอะ，สวรรค์"
  },
  Event_52382_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_52382_Desc = {
    Text = "การสั่นสะเทือนอย่างรุนแรงได้สงบลง ถนนเต็มไปด้วยรอยเลือดสีแดงเข้ม ใต้ซากบ้านที่พังทลาย มีผู้คนจำนวนมากถูกฝังไว้\nดูเหมือนว่าบางสิ่งบางอย่างของคุณก็ถูกฝังอยู่ใต้ซากปรักหักพังเช่นกัน แต่เรื่องนั้นไม่มีความสำคัญอีกต่อไปแล้ว\nสิ่งที่สำคัญเพียงอย่างเดียวคือ คุณได้เข้าใกล้ประเทศเทพอีกหนึ่งก้าว。"
  },
  Event_52382_Name = {
    Text = "การสั่นไหวของแผ่นดิน"
  },
  Event_52383_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_52383_Desc = {
    Text = "ไฟแห่งความโกรธของยักษ์ได้สงบลงชั่วคราว เมฆจางฝนหยุด พายุสงบ น้ำทะเลเหมือนมารดาผู้มีความรักนิรันดร์ ค่อยๆ ลูบไล้แผ่นหลังของลีมูเรียด้วยคลื่นอ่อนโยน เหลือไว้เพียงซากศพและซากปรักหักพังบนร่างของลีมูเรีย \n บางสิ่งของคุณดูเหมือนจะจมอยู่ในมหาสมุทร แต่ตอนนี้มันไม่สำคัญอีกต่อไป \n ในมหาสมุทร คุณได้มองเห็นภาพเงาของประเทศเทพ。"
  },
  Event_52383_Name = {
    Text = "เสียงคำรามของมหาสมุทร"
  },
  Event_52384_ChoiceDesc1 = {
    Text = "【สวดมนต์อย่างจริงจัง】เปลี่ยนการ์ดอาการธรรมดาในสำรับไพ่ทุกใบเป็น「ภาพลวงตาแห่งสวรรค์」และรับการ์ด「ภาพลวงตาแห่งสวรรค์」เพิ่มอีก 2 ใบ。"
  },
  Event_52384_ChoiceDesc2 = {
    Text = "【การสวดอ้อนวอนอย่างจริงใจ】เปลี่ยนการ์ดอาการธรรมดาในสำรับทุกใบให้เป็นการ์ด「ภาพลวงตาของราชอาณาจักรเทพเจ้า」และได้รับการ์ด「ภาพลวงตาของราชอาณาจักรเทพเจ้า」เพิ่มเติม 2 ใบ。"
  },
  Event_52384_Desc = {
    Text = "โลกาไม่สั่นสะเทือนอีกต่อไป มหาสมุทรไม่ส่งเสียงคำรามอีกต่อไป โรคระบาดไม่เข้าโจมตีอีกต่อไป ภัยพิบัติได้ทำลายลีมูเรีย ทิ้งไว้เพียงคุณ คุณเงยหน้ามองรอบตัว เห็นแต่ความเสียหาย คุณก้มมองที่มือ เปล่าเปล่า \n แต่จะเป็นอย่างไรล่ะ คุณหัวหน้าพิธีกรที่เคารพ? ย่ำไปบนซากปรักหักพังและศพของลีมูเรีย แล้วเดินหน้าต่อไปเถอะ \n คุณห่างจากประเทศเทพ เพียงหนึ่งก้าวเท่านั้น。"
  },
  Event_52384_Name = {
    Text = "ต้อนรับเถอะ，สวรรค์"
  },
  Event_53140_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_53140_Desc = {
