  Event_55782_ChoiceDesc1 = {
    Text = "【ตัดหนาม】ในการต่อสู้ครั้งถัดไป ชีวิตของศัตรูเพิ่มขึ้น 30% ความเสียหายเพิ่มขึ้น 15% ได้รับ Arg1 ภาพ「(Skill.Arg2)」。"
  },
  Event_55782_ChoiceDesc2 = {
    Text = "【ตัดหนาม】ในการต่อสู้ครั้งถัดไป ชีวิตของศัตรูเพิ่มขึ้น 30% ความเสียหายเพิ่มขึ้น 15% ได้รับ Arg1 ภาพ「(Skill.Arg2)」。"
  },
  Event_55782_ChoiceDesc3 = {
    Text = "【ฝ่าม่านหนาม】ติดเชื้อ「(Skill.Arg3)」แล้วใส่การ์ด「(Skill.Arg2)」จำนวน Arg1 ใบลงในสำรับ"
  },
  Event_55782_ChoiceDesc4 = {
    Text = "【ฝ่าม่านหนาม】ติดเชื้อ「(Skill.Arg3)」แล้วใส่การ์ด「(Skill.Arg2)」จำนวน Arg1 ใบลงในสำรับ"
  },
  Event_55782_ChoiceDesc5 = {
    Text = "【ออกจากหนาม】「ออร์ล่าปากกาและหมึก」ได้รับชั้นที่ Arg1 「บีม่อ」。"
  },
  Event_55782_Desc = {
    Text = "บางสิ่งบางอย่างกระตุ้นให้ใจคุณสั่นไหว คุณหยุดเดินและมองไปที่มุมสวน ใต้พุ่มหนามที่ซ้อนกันอยู่ จุดแสงเล็กๆ กำลังเต้นรำ พยายามที่จะปลดปล่อยตัวเองจากการผูกมัด\nนั่นคืออะไร? ผีเสื้อ? นกที่บิน? คุณเข้าใกล้มัน。"
  },
  Event_55782_Name = {
    Text = "พรของมูซัส"
  },
  Event_55782_Tips1 = {
    Text = "การต่อสู้ครั้งถัดไปศัตรูได้รับการเสริมพลังแล้ว ไม่สามารถเลือกใหม่ได้"
  },
  Event_55783_ChoiceDesc1 = {
    Text = "【การสร้างบทกวี】เลือกการ์ด「ภาพพจน์」จำนวน 3 ใบ เพื่อให้ออร์ล่าร่าย「บทกวี」ให้คุณ"
  },
  Event_55783_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_55783_Desc = {
    Text = "คุณมายังเรือนดอกไม้ที่สวยงาม ก่อนหน้าต่าง คุณมองเข้าไปในเรือนดอกไม้ แต่คุณมองไม่เห็นอะไรเลย \n ลมพัดผ่านมา กลีบดอกไม้และใบไม้ในเรือนดอกไม้ถูกลมพัดพาไป ปลิวไปปลิวมา รวมตัวกัน ในดอกไม้และใบไม้ คุณเห็นเงาของสาวน้อยคนหนึ่ง \n “อ๊ะ! มีแขกมาในสวนดอกไม้แล้ว!” สาวน้อยมองคุณด้วยความตื่นเต้นและตึงเครียด “ขอโทษนะ โคเลตต์ออกไปข้างนอก... ถ้าจะซื้อดอกไม้ ฉันไม่ค่อยรู้ราคาของดอกไม้พวกนี้...” \n สาวน้อยหยุดชะงักแล้วเข้ามาใกล้คุณเพื่อสังเกตดูสองสามครั้ง “อ๊ะ แขกท่านนี้ ฉันรู้สึกถึงอารมณ์ของบทกวีจากตัวคุณ... อาจจะ เราสามารถสร้างสรรค์บทกวีด้วยกันได้ไหม?”"
  },
  Event_55783_Name = {
    Text = "ของขวัญฤดูใบไม้ผลิ"
  },
  Event_55783_Tips1 = {
    Text = "จำนวน「สัญลักษณ์」น้อยกว่า 3 ใบ ไม่สามารถรวมได้"
  },
  Event_55799_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_55799_Desc = {
    Text = "พุ่มหนามที่กลับมีชีวิตดูเหมือนจะมีความไม่สงบ แต่ราคาที่ต้องจ่ายนั้นไม่สำคัญ——ในจุดแสงนั้น คุณได้ยินเสียงเพรียกของมิวส์。"
  },
  Event_55799_Name = {
    Text = "พรของมูซัส"
  },
  Event_55819_ChoiceDesc1 = {
    Text = "【ตามการจำของร่างกาย】ข้ามการต่อสู้และชนะทันที แต่จะสูญเสียค่าพลังชีวิต Arg1 คะแนน。"
  },
  Event_55819_ChoiceDesc2 = {
    Text = "【ออกจาก】เข้าสู่การต่อสู้"
  },
  Event_55819_Desc = {
    Text = "เมื่อเผชิญกับศัตรูที่คุ้นเคย การต่อสู้ครั้งต่อไปคุณเข้าใจมันอย่างสมบูรณ์แล้ว。"
  },
  Event_55819_Name = {
    Text = "ความทรงจำของกล้ามเนื้อ"
  },
  Event_55997_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_55997_Desc = {
    Text = "จากภาพพจน์ที่เก็บรวบรวมมา คุณได้เลือกบางส่วนส่งให้สาวน้อยในมือของเธอ \n“ภาพพจน์นี้สวยงามมาก! ท่านแขก กรุณารอสักครู่... นี่คือกลอนอุทิศที่ฤดูใบไม้ผลินำมามอบให้คุณ!” \nบทกวีหนึ่งปรากฏขึ้นในมือของคุณ ราวกับดอกไม้ที่บานเพื่อคุณโดยเฉพาะ \nคุณอยากขอบคุณสาวน้อย แต่เมื่อคุณเงยหน้าขึ้น สาวน้อยก็หายไปแล้ว ในบ้านดอกไม้ที่โดดเดี่ยว มีเพียงดอกไม้และใบไม้ที่เหี่ยวเฉาร่วงหล่นอยู่เต็มพื้น \n—— นั่นคือเถ้าถ่านที่เหลือหลังฤดูใบไม้ผลิได้เผาผลาญหมดสิ้น。"
  },
  Event_55997_Name = {
    Text = "ของขวัญฤดูใบไม้ผลิ"
  },
  Event_55999_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_55999_Desc = {
    Text = "พุ่มหนามหนาแน่นทำให้คุณลังเล คุณออกห่างจากจุดแสง แต่การจ้องมองที่สั้นเพียงแค่ครู่หนึ่งก็ยังทำให้ใจของคุณเต็มไปด้วยแรงบัลดาลใจใหม่——ในจุดแสงนั้น คุณได้ยินเสียงเพรียกของมิวส์。"
  },
  Event_55999_Name = {
    Text = "พรของมูซัส"
  },
