  },
  Event_56151_Tips1 = {
    Text = "ปัจจุบันไม่มี「ภาพลักษณ์」การ์ด"
  },
  Event_57738_ChoiceDesc1 = {
    Text = "【บุกฝ่า】ร่างกายที่ตื่นขึ้นทั้งหมดได้รับ 30 ความคลั่ง แต่จะสอดไพ่สองใบ 「(Skill.Arg1)」 เข้าไปในสำรับ"
  },
  Event_57738_ChoiceDesc2 = {
    Text = "【การปลดอาวุธ】ในการต่อสู้ครั้งถัดไป ชีวิตของศัตรูจะเพิ่มขึ้น 60% และความเสียหายจะเพิ่มขึ้น 30%。"
  },
  Event_57738_ChoiceDesc3 = {
    Text = "【การซุ่มโจมตี】ใช้ความคลั่งของร่างกายที่ถูกปลุกทั้งหมด ได้รับ 30 รอยดำ และลบล้างภัยคุกคามจากผู้พิทักษ์。"
  },
  Event_57738_Desc = {
    Text = "คุณกำลังมองลับออกไปจากจุดบอดมุมที่มุมหนึ่ง นักสืบจากคณะกรรมการตรวจสอบกำลังเฝ้าสังเกตในทิศทางอื่น และไม่ได้สังเกตเห็นการมีอยู่ของคุณ \nภาพเหตุการณ์จากการฝึกฝนก่อนหน้านี้ผุดขึ้นมาในหัวของคุณทีละภาพ สำหรับศัตรูที่ขวางทางที่คุณต้องผ่าน คุณคิดออกอย่างรวดเร็วว่าจะจัดการกับมันอย่างไร。"
  },
  Event_57738_Name = {
    Text = "นักสืบคณะกรรมการตรวจสอบ"
  },
  Event_57738_Tips3 = {
    Text = "สิ่งมีชีวิตที่ฟื้นคืนทั้งหมดในขณะนี้ไม่มีความคลั่ง"
  },
  Event_57739_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_57739_Desc = {
    Text = "คุณกำลังสังเกตอย่างละเอียด นักสืบจากคณะกรรมการตรวจสอบได้ขวางทางที่คุณต้องผ่าน และกำลังเฝ้าสังเกตพื้นที่ตรงหน้าคุณอย่างจริงจัง \nเมื่อเผชิญหน้ากับศัตรูจำนวนมาก คุณไม่สามารถต่อสู้กับพวกเขาได้ \nจะเข้าไปหรือถอยกลับดี?"
  },
  Event_57739_Name = {
    Text = "จุดกักตัว"
  },
  Event_57776_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_57776_ChoiceDesc2 = {
    Text = "【ยอมแพ้หลอก】หลังจากสำรวจพื้นที่นี้แล้ว ให้ส่งตัวไปยังจุดคุมขัง และรับการ์ด「อาการ」แบบสุ่ม 2 ใบ。"
  },
  Event_57776_ChoiceDesc3 = {
    Text = "【บุกรุก】หลังจากสำรวจพื้นที่นี้แล้ว ทำการเคลื่อนย้ายไปยังจุดคุมขัง สูญเสีย Arg1 ชีวิต。"
  },
  Event_57776_Desc = {
    Text = "คุณกำลังสังเกตอย่างละเอียด นักสืบจากคณะกรรมการตรวจสอบได้ปิดกั้นเส้นทางที่คุณต้องผ่าน และกำลังเฝ้าสังเกตพื้นที่ตรงหน้าคุณอย่างตั้งใจ \nเมื่อเผชิญหน้ากับศัตรูจำนวนมาก คุณไม่สามารถต่อสู้กับพวกเขาได้ \nจะเลือกเดินหน้าหรือถอยหลังดี?"
  },
  Event_57776_Name = {
    Text = "จุดตรวจสอบ"
  },
  Event_57776_Tips3 = {
    Text = "ชีวิตปัจจุบันไม่เพียงพอ"
  },
  Event_59193_ChoiceDesc1 = {
    Text = "【พรของอลิสเตอร์】เพิ่มการ์ด「แสงราตรี」ลงในสำรับ"
  },
  Event_59193_Desc = {
    Text = "ใบรับรองการเข้าศึกษานี้ถูกกดทับอยู่ที่ก้นกระเป๋าถือของคุณ คุณลูบกรอบที่ประณีตซึ่งเหมือนถูกเคลือบด้วยแสงดาว และสูดดมกลิ่นหมึกอ่อนๆ ที่เป็นเอกลักษณ์ของกระดาษ โลโก้ของมิซากะดูเหมือนประตูแห่งแสงสว่างที่นำไปสู่อนาคต ดึงดูดดวงตาที่กระหายของคุณ——เหมือนวันนั้น เหมือนวันนี้。"
  },
  Event_59193_Name = {
    Text = "พิธีเปิดเรียน"
  },
  Event_59527_ChoiceDesc1 = {
    Text = "เลือกการ์ดใบหนึ่งเพื่อเข้าใจและแกะสลัก「หลักแห่งปัญญา」.「หลักแห่งปัญญา」: หลังจากเล่นออกไป จั่ว 2 ใบ พลังประมวลผลที่ใช้ลดลงเท่ากับพลังประมวลผลจริงที่การ์ดแกะสลักใช้ มีผลเพียง 1 ครั้งต่อการต่อสู้."
  },
  Event_59527_Desc = {
    Text = "ตราประทับที่เป็นสัญลักษณ์ของปัญญาถูกประทับลงบนเอกสารของคุณ。\nความคิดของทาวีหลั่งไหลเข้าสู่จิตใจของคุณ ในความเป็นไปได้ที่ไม่มีที่สิ้นสุด คุณกำลังเดินไปสู่เส้นทางที่ถูกต้องเพียงหนึ่งเดียว。"
  },
  Event_59527_Name = {
    Text = "พิธีเปิดเรียน"
  },
  Event_59528_ChoiceDesc1 = {
    Text = "เลือกการ์ดใบหนึ่งเพื่อเรียนรู้และแกะสลัก「หลักแห่งความสุข」.「หลักแห่งความสุข」: หลังจากเล่นออกไป ทิ้งการ์ดทั้งหมดนอกเหนือจากร่างตื่นนี้ ได้รับการ์ดสุ่มที่ไม่ใช่ร่างตื่น 5 ใบ มีผลเพียง 1 ครั้งต่อการต่อสู้."
  },
  Event_59528_Desc = {
    Text = "ตราประทับที่เป็นสัญลักษณ์ของความปิติถูกประทับลงบนเอกสารของคุณ。\n ผ่านตราประทับ N กำลังมองคุณอยู่ พระองค์ตั้งตารอให้คุณนำมาซึ่งจุดจบที่ไม่เคยพูดถึงมาก่อน。"
  },
  Event_59528_Name = {
    Text = "พิธีเปิดเรียน"
  },
  Event_59529_ChoiceDesc1 = {
    Text = "เลือกการ์ดใบหนึ่งเพื่อเข้าใจและแกะสลัก「หลักแห่งการขยายพันธุ์」.「หลักแห่งการขยายพันธุ์」: หลังจากเล่นออกไป จะได้รับสำเนาต้นฉบับ 3 ใบที่มี「เก็บไว้」และ「บริโภค」แนบมา มีผลเพียง 1 ครั้งต่อการต่อสู้."
  },
  Event_59529_Desc = {
    Text = "ตราประทับที่เป็นสัญลักษณ์ของการสืบพันธุ์ถูกประทับลงบนเอกสารของคุณ。\nทาอิสได้ฝากความหวังของพระองค์ไว้ที่คุณ พระองค์จะอยู่ร่วมกับคุณในทุกโลก。"
  },
  Event_59529_Name = {
    Text = "พิธีเปิดเรียน"
  },
  Event_59566_ChoiceDesc1 = {
    Text = "【เช็ดน้ำตาเลือด】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_59566_ChoiceDesc2 = {
    Text = "【การรักษาการลืมตาไว้】การ์ดคำสั่ง 3 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_59566_Desc = {
    Text = "ความปรารถนานับไม่ถ้วนของคุณรวมเป็นหนึ่ง เคยมีที่มาร่วมกัน ตอนนี้คุณมีร่างกายเดียวกัน\nดวงตาจำนวนนับไม่ถ้วนเปิดออกพร้อมกัน เพื่อต้องเผชิญหน้ากับรูม่านตาขนาดใหญ่\nดวงตาจำนวนนับไม่ถ้วนแตกสลาย รินน้ำตาแห่งความเจ็บปวดและเลือดที่แห้งเหือด。"
  },
  Event_59566_Name = {
    Text = "การฟิวชันของฉัน"
  },
  Event_59567_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59567_Desc = {
    Text = "คุณพยายามโต้เถียงกับเสียงที่บ้าคลั่งนั้น แย้งแนวคิดที่เป็นสุญญตา。“ทุกสิ่งจะนำไปสู่ความตาย ชีวิตเองจะไม่มีความหมายเลยหรือ?” คุณยืนยันอย่างหนักแน่น แต่เสียงหัวเราะนั้นกลับไม่ลดน้อยลงเลย เหมือนกับกำลังเย้ยหยันความโง่เขลาของคุณ。"
  },
  Event_59567_Name = {
    Text = "ลูกแกะรอความตาย"
  },
  Event_59568_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59568_Desc = {
    Text = "คุณจ้องมองไปที่ประตูนั้น ไม่อยากทนทุกข์ทรมานจากความไม่รู้ต่อไปอีกแล้ว \n คุณต้องการเห็นภาพเบื้องหลังประตู \n ประตูมายากลสั่นไหวอย่างหลอนประสาท คุณเห็นเงาของโลกนับไม่ถ้วนพุ่งผ่านไป \n ไม่มีเวลาที่จะมองให้ชัดเจน ข้อมูลมากมายทำให้จิตใจของคุณพังทลาย สมองของคุณเต็มไปด้วยเสียงรบกวนที่โกลาหล。"
  },
  Event_59568_Name = {
    Text = "หลังประตู"
  },
  Event_59569_ChoiceDesc1 = {
    Text = "【คำสั่งแน่วแน่】สุ่มปลุกร่างกายที่ตื่นขึ้น 1 ราย ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_59569_ChoiceDesc2 = {
    Text = "【การหารือร่วมกัน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：(EnchantConfig.Arg1)"
  },
  Event_59569_Desc = {
    Text = "ทุกอย่างเกิดขึ้นอย่างกะทันหัน คุณรู้สึกว่ารอบตัวถูกปกคลุมไปด้วยหมอกที่พร่าเบลอ คุณพยายามมองไปรอบๆ แต่ไม่สามารถมองเห็นอะไรได้เลย。\nร่างกายที่ตื่นขึ้นกำลังรอคำสั่งจากคุณอยู่。\nตอนนี้คุณโดดเดี่ยวและไม่มีใครช่วยได้ ต้องพึ่งพาพละกำลังของตัวเองเท่านั้น。"
  },
  Event_59569_Name = {
    Text = "ตาแห่งความไม่รู้"
  },
  Event_59570_ChoiceDesc1 = {
    Text = "【แลกเปลี่ยนด้วยการเสียสละ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」และติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59570_ChoiceDesc2 = {
    Text = "【ด้วยความกล้าหาญ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_59570_ChoiceDesc3 = {
    Text = "【มองตรง】ได้รับ 50 รอยดำ"
  },
  Event_59570_Desc = {
    Text = "คุณนับไม่ถ้วนยืนอยู่ในโลกนับไม่ถ้วน ไหล่ชนไหล่ มือจับมือ เหมือนพี่น้องที่ใกล้ชิดกันราวกับเป็นหนึ่งเดียว \n ตอนนี้พวกคุณยืนอยู่ใต้เงาขนาดใหญ่ เงยหน้าขึ้น ไม่ถอยหลังแม้แต่ก้าวเดียว \n จะทำอย่างไร? \n จะทำอย่างไรเพื่อเอาชนะตัวตนที่สูงสุดนั้น?"
  },
  Event_59570_Name = {
    Text = "คำตอบของฉัน"
  },
  Event_59571_ChoiceDesc1 = {
    Text = "【ค้นหาคำตอบ】ได้รับรอยดำ Arg1，ติดเชื้อ「(Skill.Arg2)」，เลือกต่อไป"
  },
  Event_59571_ChoiceDesc2 = {
    Text = "【ยอมแพ้】ได้รับ 25 รอยดำ แล้วออก"
  },
  Event_59571_Desc = {
    Text = "ภาพลวงตาผ่านประตู นับไม่ถ้วนสิ่งที่คุณประสบผ่านเข้ามาในหัวของคุณ \n บางคนตาย บางคนบ้าคลั่ง บางคนยืนหยัด บางคนตกต่ำ \n เส้นทางนับไม่ถ้วน ตัวเลือกนับไม่ถ้วนปรากฏขึ้นต่อหน้าคุณ คุณรู้สึกเหมือนว่าครั้งหนึ่งคุณได้ใช้ชีวิตที่ยาวนานและไม่มีที่สิ้นสุด \n ตอนนี้มีจิตใจมากมาย ปากมากมายทำงานพร้อมกัน \n คุณพยายามข้ามกาลเวลาและพูดคุยกับตัวเองนับไม่ถ้วน ดึงคำตอบจากความทรงจำที่ไม่มีที่สิ้นสุด。"
  },
  Event_59571_Name = {
    Text = "การถามตัวเองของฉัน"
  },
  Event_59572_ChoiceDesc1 = {
    Text = "【แลกเปลี่ยนพละกำลัง】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_59572_ChoiceDesc2 = {
    Text = "【แลกเปลี่ยนโชคดี】เพิ่มพลังชีวิตสูงสุด Arg1 ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_59572_Desc = {
    Text = "ทุกการเลือกมีต้นทุน \n ชีวิต จิตใจ อารมณ์ ความทรงจำ...\n คุณต้องการแลกเปลี่ยนอะไรกับชะตากรรม และเลือกจะวางอะไรลงบนตาชั่ง?"
  },
  Event_59572_Name = {
    Text = "การเลือกชะตากรรม"
  },
  Event_59573_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59573_Desc = {
    Text = "คนจะไม่มีหัวใจได้อย่างไร?\nคุณตื่นตระหนกมองหาทั่วไป หายใจของคุณเริ่มถี่ขึ้น ความกลัวต่อความตายปกคลุมอยู่ในสมองของคุณ.\n“หายใจไม่ออกแล้ว... หัวใจจะหยุดเต้นแล้ว...”\nเดี๋ยวนะ คุณดูเหมือนจะไม่ต้องการการเต้นของหัวใจอีกต่อไป.\nคุณรู้สึกเหมือนตื่นจากความฝัน ยิ้มอย่างมีความสุข。"
  },
  Event_59573_Name = {
    Text = "ร่องอกว่าง"
  },
  Event_59574_ChoiceDesc1 = {
    Text = "【จ้องมอง】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59574_ChoiceDesc2 = {
    Text = "【หลบหนี】 ปลุก 2 ผู้ปลุกเสกแบบสุ่ม, ติดเชื้อสองครั้ง「(Skill.Arg1)」"
  },
  Event_59574_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_59574_Desc = {
    Text = "คุณรู้สึกว่ามีบางสิ่งในความว่างเปล่าที่กำลังจ้องมองคุณอยู่。\nไม่ว่าคุณจะเดินไปที่ไหน สายตานั้นก็ตามติดคุณเหมือนเงา。\nคุณรู้สึกเหมือนเป็นเหยื่อที่ถูกจับตามอง ตัวของคุณเริ่มรู้สึกเจ็บปวดเหมือนถูกเข็มทิ่มแทงที่หลัง。"
  },
  Event_59574_Name = {
    Text = "พระท่านมอง"
  },
  Event_59575_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59575_Desc = {
    Text = "คุณไม่หวั่นไหวกับการบรรเลงที่คลั่งไคล้ ยังคงยืนหยัดในจังหวะของตัวเองอย่างเงียบๆ。\n การโจมตีและการล่อใจของฝ่ายตรงข้ามไม่มีผลต่อคุณ เสียงดนตรีสองทำนองถูกบรรเลงบนเปียโนพร้อมกัน ใครที่ยืนหยัดจนถึงที่สุด ก็จะสามารถควบคุมทุกตัวโน้ตได้。"
  },
  Event_59575_Name = {
    Text = "เพลงปาร์ตี้วันสิ้นโลก"
  },
  Event_59576_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59576_Desc = {
    Text = "คุณรวบรวมความกล้าทั้งหมด ไม่ว่าจะเจออะไร คุณจะก้าวไปพร้อมกับเพื่อนร่วมทีม"
  },
  Event_59576_Name = {
    Text = "อนาคตหยุดนิ่ง"
  },
  Event_59577_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59577_Desc = {
    Text = "“ตอนนี้คุณอยู่ที่ไหน?”\n“คุณครูมีแผนการอะไร?”\n“ต่อไปฉันควรทำอย่างไร?”\nคุณตั้งคำถามอย่างเร่งรีบ อยากพึ่งพิงสิ่งที่เชื่อถือได้เหมือนเคย\nอุปกรณ์ติดต่อเหมือนหยุดชะงักและไม่มีปฏิกิริยา คุณเขย่าเครื่องจักร และตัวอักษรบนจดหมายกลับกลายเป็นฝูงผีเสื้อที่บิดเบี้ยว ปีกกระพือเข้าที่ใบหน้าของคุณ\nคุณขยี้ตาและพบว่าทุกอย่างเป็นเพียงภาพหลอนของคุณ\nกระดาษจดหมายไม่มีตัวอักษรแม้แต่คำเดียว。"
  },
  Event_59577_Name = {
    Text = "เสียงสะท้อนมายา"
  },
  Event_59578_ChoiceDesc1 = {
    Text = "【หาอย่างรีบร้อน】เพิ่มพลังชีวิตสูงสุด Arg1"
  },
  Event_59578_ChoiceDesc2 = {
    Text = "【พยายามเติมเต็ม】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59578_Desc = {
    Text = "คุณรู้สึกว่าภายในช่องอกกลายเป็นความว่างเปล่าและเบา คุณก้มลงมอง พบว่าหน้าอกเปิดกว้างเป็นรูปรูดอกกุญแจ \n หัวใจของคุณหายไปอย่างลึกลับ。"
  },
  Event_59578_Name = {
    Text = "ร่องอกว่าง"
  },
  Event_59579_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59579_Desc = {
    Text = "คุณตะโกนถามจุดประสงค์ของเขาเสียงดังลั่น แต่กลับได้รับเพียงรอยยิ้มที่ไม่เปลี่ยนแปลงเลย\n\nเขาได้หันหลังให้กับโลกมานานแล้ว คนที่ไม่มีพันธะอะไรก็ไม่จำเป็นต้องรับผิดชอบสิ่งใด\nคุณทำได้เพียงต่อต้านอย่างไร้ผล。"
  },
  Event_59579_Name = {
    Text = "บ้าคลั่งเจนเทิลแมน"
  },
  Event_59580_ChoiceDesc1 = {
    Text = "【รบกวนจังหวะ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_59580_ChoiceDesc2 = {
    Text = "【รักษาตัวตน】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_59580_Desc = {
    Text = "คุณดูเหมือนจะเล่นเปียโนร่วมกับคนบ้าคลั่งคนหนึ่ง เธอผูกมัดคุณไว้ที่คีย์เปียโนและดึงคุณเข้าสู่งานเพลงที่บ้าคลั่งของเธอ \n คุณพยายามบรรเลงอย่างยากลำบากตามจังหวะของเธออย่างเซไปเซมา \n คุณพยายามต่อสู้กับเธออย่างยากลำบาก พยายามควบคุมทำนองของเพลง。"
  },
  Event_59580_Name = {
    Text = "เพลงปาร์ตี้วันสิ้นโลก"
  },
  Event_59581_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59581_Desc = {
    Text = "คุณหวังว่าตนเองจะมีพละกำลังที่ไม่มีใครเทียบได้ สามารถทำลายพันธนาการและอุปสรรคทั้งหมดได้。\nแต่พลังของมนุษย์มีขีดจำกัด การท้าทายเทพเจ้าด้วยร่างที่เล็กน้อย ย่อมจะเผาผลาญชีวิตของตนเองเหมือนกับไม้ขีดไฟ。"
  },
  Event_59581_Name = {
    Text = "การเลือกชะตากรรม"
  },
  Event_59582_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59582_Desc = {
    Text = "“หมดไปแล้ว... หมดไปแล้ว...”\nความรู้สึกว่างเปล่ามันไม่ดีเลย คุณหยิบเรือนเวลา แอปเปิ้ล และเสื้อคลุมโรงเรียนขึ้นมา พยายามเติมเต็มช่องว่างในอกของคุณ\nหน้าอกของคุณกลับเต็มไปด้วยความรู้สึกที่มากเกินไปเพียงเล็กน้อย\nไม่เป็นไร ชีวิตมักจะไม่สมบูรณ์แบบเสมอไป。"
  },
  Event_59582_Name = {
    Text = "ร่องอกว่าง"
  },
  Event_59583_ChoiceDesc1 = {
    Text = "【โน้มน้าว】ได้รับ 25 รอยดำ"
  },
  Event_59583_ChoiceDesc2 = {
    Text = "【การซักถาม】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_59583_Desc = {
    Text = "รองเท้าหนังของ N หยุดอยู่ตรงหน้าคุณ คุณเห็นรอยยิ้มที่เกินจริงบนใบหน้าดำมืดนั้น.\nเขามักแต่งกายสุภาพเรียบร้อย แต่คุณรู้ดีว่าใต้ภาพลักษณ์ของสุภาพบุรุษนั้นมีเพียงความบ้าคลั่งที่บริสุทธิ์ที่สุด.\nเขาไม่มีเพื่อน และแทบไม่มีศัตรู.\nเพราะผู้คนเหล่านั้นจะหายไปอย่างสิ้นเชิงด้วยวิธีที่ดราม่าที่สุด.\n\nน่าเสียดายที่ตอนนี้คุณถูกเขาเลือกให้เป็นตัวละครหลักคนต่อไปในละครนี้.\nโปรดเตรียมบทเปิดตัวของคุณไว้ จะทำอย่างไรถึงจะทำให้ผู้ชมที่เจ้าอารมณ์ที่สุดนี้พอใจได้?"
  },
  Event_59583_Name = {
    Text = "บ้าคลั่งเจนเทิลแมน"
  },
  Event_59584_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59584_Desc = {
    Text = "ผู้ปลุกตื่นไม่ได้รู้เรื่องราวมากไปกว่าคุณ แต่พวกเขาเป็นเพื่อนที่ซื่อสัตย์ที่สุดของคุณ เพื่อนร่วมรบ และเป็นกำลังใจให้คุณ \n คุณได้หารือกับผู้ปลุกตื่นเกี่ยวกับกลยุทธ์ แม้ว่าคุณจะยังรู้สึกสับสนในใจ แต่คุณก็มีความกล้าที่จะเริ่มต้นใหม่แล้ว。"
  },
  Event_59584_Name = {
    Text = "ตาแห่งความไม่รู้"
  },
  Event_59585_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59585_Desc = {
    Text = "เหมือนกับว่าคุณได้ตัดสินใจแน่วแน่ คุณตอบกลับอย่างมั่นใจด้วยเสียงดัง \n เสียงของคุณก้องอยู่ระหว่างฟองสบู่มากมาย เหมือนกับว่ามีคุณมากมายร่วมกันสาบาน \n คุณได้เตรียมตัวพร้อมที่จะเผชิญหน้ากับทุกสิ่งแล้ว。"
  },
  Event_59585_Name = {
    Text = "การซักถามของพระองค์"
  },
  Event_59586_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59586_Desc = {
    Text = "คุณไม่ขยับเขยื้อน เพียงแค่จ้องมองไปที่ตัวอักษรบนจดหมายตอบกลับ \n ใต้การจ้องมองของคุณ ตัวอักษรเหล่านั้นค่อยๆ เบลอและบิดเบือน สุดท้ายกลายเป็นผีเสื้อจำนวนมากบินว่อนเข้ามาบนใบหน้าของคุณ \n คุณโบกมือไล่ผีเสื้อ และเมื่อหันกลับไปมอง กระดาษจดหมายตอบกลับกลับว่างเปล่าไม่มีตัวอักษรเลย \n แน่นอน ความฝันที่งดงามเกินไปมักจะเป็นเพียงภาพลวงตา。"
  },
  Event_59586_Name = {
    Text = "เสียงสะท้อนมายา"
  },
  Event_59587_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59587_Desc = {
    Text = "คุณเกลียดเส้นด้ายที่ต่ำช้าเหล่านี้ \n คุณดึงมันอย่างรุนแรง บางเส้นขาดและเส้นอื่นๆ ก็พันเข้ามาใหม่ไม่รู้จบ \n คุณใช้พละกำลังทั้งหมดของคุณต่อสู้กับมันอย่างต่อเนื่อง。"
  },
  Event_59587_Name = {
    Text = "มือที่ถูกบังคับ"
  },
  Event_59588_ChoiceDesc1 = {
    Text = "【สังหารเงามนุษย์】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59588_ChoiceDesc2 = {
    Text = "【บดขยี้ตัวอ่อน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59588_ChoiceDesc3 = {
    Text = "【ปิดตา】ได้รับ 25 รอยดำ"
  },
  Event_59588_Desc = {
    Text = "คุณเห็นผู้คนที่เคยพบในอาลานเข้ามาหาคุณในขณะที่คุณรู้สึกมึนงง \n พวกเขาหัวเราะและเชิญชวนให้คุณดื่ม เต้นรำ และชิมอาหาร \n จากนั้นเนื้อและเลือดของพวกเขาก็ถูกลอกออกเป็นชั้นๆ ขณะที่สิ่งที่ตกลงบนพื้นกำลังขยับและงอกขึ้นเป็นตัวอ่อนใหม่ \n พวกเขายื่นมือออกมา เชิญชวนให้คุณเข้าร่วมในงานฉลองของเนื้อและเลือดกับการเกิดใหม่."
  },
  Event_59588_Name = {
    Text = "เงาของวันเก่า"
  },
  Event_59589_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59589_Desc = {
    Text = "ก่อนที่คุณจะยื่นมือออกไป คุณนึกขึ้นได้ว่าคุณไม่เคยเลี้ยงแมวแบบนี้มาก่อน。\nคุณจ้องมองแมวผ่านอากาศ แมวกระพริบตาให้คุณ。\nแมวไม่สนใจความเฉยเมยของคุณ มันดูเหมือนจะรักคุณเหมือนเดิม。"
  },
  Event_59589_Name = {
    Text = "ความล่อแหลมของแมว"
  },
  Event_59590_ChoiceDesc1 = {
    Text = "【การฝัง】เลือกสิ่งสร้าง 1 ชิ้นเปลี่ยนเป็นสิ่งสร้างที่ถูกสาป「(RelicConfig.Arg1)」"
  },
  Event_59590_ChoiceDesc2 = {
    Text = "【กลืน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59590_ChoiceDesc3 = {
    Text = "【เก็บ】ได้รับ 25 รอยดำ"
  },
  Event_59590_Desc = {
    Text = "พลังของพลาสมิดสามตัวในร่างกายกำลังผสมผสานกัน คุณพยายามอย่างยากลำบากในการควบคุมพลังอันมหาศาลนี้ \n พื้นที่จิตกำลังขยายตัวอย่างต่อเนื่อง และเกิดทางช้างเผือกที่นี่ \n เผชิญหน้ากับศัตรูที่เข้ามาอย่างไม่หยุดหย่อน คุณตั้งใจอธิษฐานต่อท้องฟ้าดวงดาวนี้ ขอให้พลังนี้ช่วยเหลือคุณ \n ดวงดาวดวงหนึ่งหล่นลงมาจากทางช้างเผือกสู่ฝ่ามือของคุณ เปล่งประกายแสงที่ดึงดูดใจ。"
  },
  Event_59590_Name = {
    Text = "ดาวอธิษฐาน"
  },
  Event_59591_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59591_Desc = {
    Text = "คุณก็ตอบด้วยความเงียบ พวกคุณไม่ได้สื่อสารกัน ความเงียบคือคำตอบของทุกอย่าง。\nคุณได้เตรียมพร้อมที่จะเผชิญกับทุกสิ่งแล้ว。"
  },
  Event_59591_Name = {
    Text = "การซักถามของพระองค์"
  },
  Event_59592_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59592_Desc = {
    Text = "แมวตัวนั้นเป็นคนหลอกลวงหรือเปล่า?\nคุณเริ่มสงสัยในดวงตาสีฟ้าผืนน้ำนั้น เสียงหัวเราะในหูยังคงดังก้องอยู่.\n“หลอกลวง หลอกลวง คุณโดนหลอกแล้ว!”\nในใจของคุณเกิดความวิตกกังวลขึ้นมา。"
  },
  Event_59592_Name = {
    Text = "ความลับกระซิบ"
  },
  Event_59593_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59593_Desc = {
    Text = "คุณเหมือนคนที่เฝ้าดูเงียบ ๆ มองดูอารมณ์ที่ค่อย ๆ กลายเป็นสิ่งแปลกปลอม \n คุณยับยั้งความปรารถนาทุกอย่างที่มีต่อความผูกพัน รู้สึกว่าวิญญาณของคุณค่อย ๆ กลายเป็นความเย็นชา \n นี่คือชะตากรรมของคุณ นี่คือทางที่คุณต้องเดินผ่านไป。"
  },
  Event_59593_Name = {
    Text = "Kristal อารมณ์"
  },
  Event_59594_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59594_Desc = {
    Text = "ใบหน้ายิ้มแย้มไม่แสดงอารมณ์ คุณไม่สามารถใช้การสื่อสารด้วยเหตุผลหรืออารมณ์ทำให้เขาเคลื่อนไหวได้ \n ความปรารถนาทุกอย่างของมนุษย์ไม่เกี่ยวข้องกับเขา \n คำพูดของคุณสามารถก้าวข้ามจินตนาการของมนุษย์ได้หรือไม่?"
  },
  Event_59594_Name = {
    Text = "บ้าคลั่งเจนเทิลแมน"
  },
  Event_59595_ChoiceDesc1 = {
    Text = "【ตอบกลับ】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59595_ChoiceDesc2 = {
    Text = "【ความเงียบ】การตื่นรู้แบบสุ่ม 2 ร่างกายที่ตื่นขึ้น ได้รับผล「(Skill.Arg1)」สองครั้ง"
  },
  Event_59595_Desc = {
    Text = "ฟองอากาศนับไม่ถ้วนเหมือนกับดวงตากลมๆ นับไม่ถ้วน มันมองคุณอย่างเงียบๆ ราวกับเป็นคำถามที่ไม่มีเสียง \n คุณพร้อมแล้วหรือยัง? \n พร้อมที่จะละทิ้งทุกสิ่งหรือยัง? \n พร้อมที่จะรับผิดชอบทุกอย่างหรือยัง?"
  },
  Event_59595_Name = {
    Text = "การซักถามของพระองค์"
  },
  Event_59596_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59596_Desc = {
    Text = "ในขณะที่ฝ่ายตรงข้ามเริ่มโจมตี คุณก็เริ่มตอบโต้ทันที \n คุณได้แยกแยะพวกเขาออกมาอย่างชาญฉลาด ว่าพวกเขาคือกลุ่มสัตว์ร้ายที่แสดงเขี้ยวออกมา \n คุณโชคดีที่ชนะ \n ตอนนี้รีบหนีไปเถอะ ห้ามให้พวกเขาจับคุณได้。"
  },
  Event_59596_Name = {
    Text = "จมลงสู่เหว"
  },
  Event_59597_ChoiceDesc1 = {
    Text = "【ค้นหาคำตอบ】ได้รับรอยดำ Arg1，ติดเชื้อ「(Skill.Arg2)」，เลือกต่อไป"
  },
  Event_59597_ChoiceDesc2 = {
    Text = "【ละทิ้ง】ออก"
  },
  Event_59597_Desc = {
    Text = "คุณควรทำอย่างไร? \n คุณมองไปที่ตัวเองนับไม่ถ้วน ใบหน้าจำนวนนับไม่ถ้วนที่เหมือนกับคุณกำลังจ้องมองมาที่คุณ ปากของพวกเขาเปิดปิดอยู่ \n ราวกับคว้าหวังไว้ที่ก้านฟาง คุณพยายามค้นหาและฟัง หวังว่าจะได้รับคำตอบสุดท้าย。"
  },
  Event_59597_Name = {
    Text = "การถามตัวเองของฉัน"
  },
  Event_59598_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59598_Desc = {
    Text = "ยังไม่ถึงเวลา คุณต้องอดทนรอคอย \n คุณกลืนความไม่พอใจและความเกลียดชัง รอคอยช่วงเวลาที่จะต้องลงเดิมพันทั้งหมด。"
  },
  Event_59598_Name = {
    Text = "มือที่ถูกบังคับ"
  },
  Event_59599_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59599_Desc = {
    Text = "คุณรู้สึกถึงการดึงดูดบางอย่างที่อยู่เหนือธรรมชาติ คุณต้องการมองให้ชัดเจนถึงแหล่งที่มาของสายตานั้น \n คุณจ้องมองไปยังความว่างเปล่าอย่างหลงใหล รู้สึกเหมือนว่าคุณเห็นอะไรบางอย่าง \n สายตาของคุณถูกปกคลุมด้วยความพร่ามัวเหมือนหิมะในชั่วพริบตา โลกในดวงตาของคุณดูเหมือนมีบางสิ่งที่แตกต่างออกไป \n คุณขยี้ตา พบว่ามีเลือดน้ำตาไหลออกมาจากมุมตา。"
  },
  Event_59599_Name = {
    Text = "พระท่านมอง"
  },
  Event_59600_ChoiceDesc1 = {
    Text = "【พยายามนึกย้อน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59600_ChoiceDesc2 = {
    Text = "【สัมผัสความเศร้า】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59600_ChoiceDesc3 = {
    Text = "【ยอมรับอย่างสงบ】ได้รับ 25 รอยดำ"
  },
  Event_59600_Desc = {
    Text = "ราวกับกำลังผ่านการผ่าตัดสมองที่ละเอียดอ่อนที่สุด คุณรู้สึกได้อย่างชัดเจนว่าแต่ละความทรงจำที่คุณหวงแหนกำลังถูกดึงออกจากสมองของคุณ สมองของคุณกลายเป็นภาพมัว ๆ คล้ายกับว่ากำลังจะละลาย\nคุณสั่นสะท้านด้วยความเจ็บปวด กดตัวเองเพื่อหยุดมือที่พยายามจะหยุดการกระทำ\nน้ำตาใส ๆ ไหลจากหางตา แต่ พวกมันก็ไหลมาทำไมกันนะ?\nคุณรู้สึกเหมือนคุณจำอะไรบางอย่างไม่ได้\nคุณรู้สึกเศร้าสร้อยอย่างไร้เหตุผล。"
  },
  Event_59600_Name = {
    Text = "ความจำแยกส่วน"
  },
  Event_59601_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59601_Desc = {
    Text = "ความสัมพันธ์ระหว่างคุณกับวิฬารนั้นไม่มีข้อสงสัย คุณโบกมือแล้วเดินต่อไปโดยไม่หันกลับไปมอง \n “คนโง่! คนโง่!” \n เสียงที่ดังอยู่ข้างหูเต็มไปด้วยความโมโห。"
  },
  Event_59601_Name = {
    Text = "ความลับกระซิบ"
  },
  Event_59602_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59602_Desc = {
    Text = "คุณตัดสินใจอย่างแน่วแน่ ไม่ว่าจะต้องจ่ายราคาที่ต้องจ่ายใด คุณจะสู้จนถึงวินาทีสุดท้ายพร้อมกับความหวังของทุกคน。"
  },
  Event_59602_Name = {
    Text = "อนาคตหยุดนิ่ง"
  },
  Event_59603_ChoiceDesc1 = {
    Text = "【ควบคุม】ได้รับของขวัญเงิน「(RelicConfig.Arg1)」"
  },
  Event_59603_ChoiceDesc2 = {
    Text = "【จ้องมอง】ได้รับสิ่งประดิษฐ์ทองคำ 「(RelicConfig.Arg1)」 ได้รับผลกระทบจาก 「(Skill.Arg2)」"
  },
  Event_59603_Desc = {
    Text = "หลังประตูที่ทาวีเฝ้ารักษา คือโลกอันไม่มีที่สิ้นสุดและความจริงอันไม่มีที่สิ้นสุด。\nคุณไม่รู้ว่าเธอเห็นอะไรหลังประตู แต่คุณรู้ว่าเธอรู้ทุกอย่าง。\nขณะนี้ประตูบานนี้เปิดออกต่อหน้าคุณ ความจริงทั้งหมดกำลังส่งเสียงเชิญชวนอย่างเงียบงันอยู่หลังประตู。"
  },
  Event_59603_Name = {
    Text = "หลังประตู"
  },
  Event_59604_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59604_Desc = {
    Text = "ควรมีความเคารพต่อการมีอยู่ที่ไม่รู้จัก และการหลีกเลี่ยงความแหลมคมเป็นทางเลือกที่ระมัดระวัง。\nคุณก้มหน้าลง กำกุญแจเงินที่หน้าอกแน่น รู้สึกได้รับความสบายใจเล็กน้อย。\nอย่างน้อยคุณยังมีพละกำลัง ยังมีผู้ปลุกตื่น。\nคุณพยายามเพิกเฉยต่อสายตานั้น มุ่งเน้นไปที่ทางข้างหน้า。\nแต่สายตานั้นหายไปจริงๆ หรือ? คุณรู้ดีอยู่แก่ใจ。"
  },
  Event_59604_Name = {
    Text = "พระท่านมอง"
  },
  Event_59605_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59605_Desc = {
    Text = "หากวิธีการต้านทานเทพเจ้าทุกอย่างเป็นเพียงแค่เพลี้ยไต่ต้นไม้ ความกล้าที่จะไม่ยอมแพ้คือสิ่งเดียวที่คุณสามารถยืนหยัดได้ \n เมื่อการทำลายล้างอันไม่มีที่สิ้นสุดถาโถมลงมาจากฟ้า คุณจะกลายเป็นคนที่ยืนอยู่ข้างหน้า。"
  },
  Event_59605_Name = {
    Text = "คำตอบของฉัน"
  },
  Event_59606_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59606_Desc = {
    Text = "คุณนิ่งงันสัมผัสน้ำตาที่ไหลรินอย่างต่อเนื่อง ค่อยๆ รำลึกถึงความเศร้าที่ไม่รู้ที่มานั้น \n รู้สึกเหมือนว่ามีสิ่งที่มีค่ามากมายถูกคุณทิ้งไปด้วยมือของตัวเอง แต่คุณกลับนึกไม่ออกว่ามันคืออะไร \n น่าเสียดายจริงๆ \n คุณเช็ดน้ำตาอย่างไร้เรี่ยวแรง ในขณะที่น้ำตาไหลออกมา คุณก็เผยรอยยิ้มที่ขมขื่น。"
  },
  Event_59606_Name = {
    Text = "ความจำแยกส่วน"
  },
  Event_59607_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59607_Desc = {
    Text = "คุณเมินเสียงของพวกเขาไป。\nคุณไม่สนใจว่าแมวจะเป็นคนโกหกหรือไม่ คุณเชื่อในพละกำลังของตัวเองเท่านั้น。\nเสียงที่ข้างหูเริ่มถอนหายใจ。"
  },
  Event_59607_Name = {
    Text = "ความลับกระซิบ"
  },
  Event_59608_ChoiceDesc1 = {
    Text = "【ค้นหาคำตอบ】ได้รับรอยดำ Arg1，ติดเชื้อ「(Skill.Arg2)」，เลือกต่อไป"
  },
  Event_59608_ChoiceDesc2 = {
    Text = "【ละทิ้ง】ออก"
  },
  Event_59608_Desc = {
    Text = "มีคนหัวเราะอย่างบ้าคลั่ง \n การดิ้นรนที่ตนเองเห็นว่าไร้ประโยชน์นั้น ควรยอมแพ้แต่เนิ่นๆ ดีกว่า \n คุณขมวดคิ้ว คนที่คุณหันไปยิ้มอย่างกะทันหันพูดว่า การจบชีวิตของทุกคนด้วยมือของตนเองดีกว่าปล่อยให้ผู้คนต้องประสบกับความทุกข์ \n คุณโบกมือไล่เสียงนั้นออกไป ยึดมั่นในความเชื่อของตนเอง。"
  },
  Event_59608_Name = {
    Text = "การถามตัวเองของฉัน"
  },
  Event_59609_ChoiceDesc1 = {
    Text = "【ติดตามสอบถาม】ลบการ์ด 2 ใบ"
  },
  Event_59609_ChoiceDesc2 = {
    Text = "【เจาะ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59609_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ Arg1 รอยดำ"
  },
  Event_59609_Desc = {
    Text = "ในระหว่างการรอคอยที่ยาวนาน คุณได้เปิดเครื่องติดต่ออีกครั้ง บางทีความคิดถึงและการสวดมนต์ของคุณอาจมีผล คุณเห็นกระดาษตอบกลับที่มีข้อความที่คุ้นเคยและอบอุ่นของเธอไหลออกมาอย่างต่อเนื่อง \n ตอนนี้เธอปลอดภัยมาก อาจารย์มีการจัดการไว้ล่วงหน้า การดำเนินการของมิซากะเป็นไปอย่างราบรื่น... \n คุณมองข่าวดีที่บินมาด้วยความเหมือนหิมะแล้วใจไม่อาจสงบได้。"
  },
  Event_59609_Name = {
    Text = "เสียงสะท้อนมายา"
  },
  Event_59610_ChoiceDesc1 = {
    Text = "【จับดวงดาว】อัปเกรดสิ่งสร้างเงิน 1 ชิ้นเป็นสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_59610_ChoiceDesc2 = {
    Text = "【บดดาว】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」และ「(Skill.Arg3)」"
  },
  Event_59610_ChoiceDesc3 = {
    Text = "【ดูอย่างเงียบๆ】ได้รับ 25 รอยดำ"
  },
  Event_59610_Desc = {
    Text = "อารมณ์ของคุณถูกดึงออกไปพร้อมกับความทรงจำ คุณรู้สึกว่ากำลังกลายเป็นสิ่งมีชีวิตที่ยิ่งใหญ่บางอย่าง เหมือนกับมอนสเตอร์ที่กลับไปยังรังโบราณและอบอุ่นของมัน \n ความสุข ความโกรธ ความเศร้า และความกลัวนับไม่ถ้วนถูกบีบให้กลายเป็นดวงดาวที่เปล่งประกาย หล่นลงมาเป็นฝนส่องแสงในมิติทางจิตของคุณ \n ร่องรอยแห่งการมีชีวิตของคุณกลายเป็นดาวตกและหายไป \n คุณเงียบงันมองดู และหยิบดวงดาวที่อยู่ข้างหน้าขึ้นมา เสียงหัวเราะที่เต็มไปด้วยความสุขของคุณแว่วมาในนั้น \n ดังนั้นคุณจึงหัวเราะออกมา คุณหวานเหมือนน้ำผึ้ง。"
  },
  Event_59610_Name = {
    Text = "Kristal อารมณ์"
  },
  Event_59611_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59611_Desc = {
    Text = "คุณรู้ว่าสิ่งเหล่านี้เป็นเพียงเงาแห่งอดีต คุณกำลังสังหารผู้ที่เคยสนทนากับคุณด้วยความไร้อารมณ์\nเสียงหัวเราะและน้ำตาของพวกเขาแตกสลายไปในมือของคุณ คุณไม่สามารถหยุดชั่วขณะได้เลย\nหากนี่เป็นการทดสอบที่จำเป็น คุณจะเป็นเพชฌฆาตผู้ไร้ความปรานีที่สุด。"
  },
  Event_59611_Name = {
    Text = "เงาของวันเก่า"
  },
  Event_59612_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59612_Desc = {
    Text = "ขนที่นุ่มนวลและดวงตาที่ใสของมันทำให้คุณรู้สึกไว้วางใจโดยธรรมชาติ\nคุณเดินเข้าใกล้แมว แมวมายังคุณด้วย\nพวกคุณไม่มีคำพูดต่อกัน แต่หางของมันตั้งสูงขึ้น。"
  },
  Event_59612_Name = {
    Text = "ความล่อแหลมของแมว"
  },
  Event_59613_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59613_Desc = {
    Text = "คุณควบคุมความอยากรู้ไว้ คุณรู้ว่าประตูนี้ไม่ควรเปิด \n ความจริงมากเกินไปบางครั้งก็เป็นคำสาป \n คุณจับกุญแจเงินที่หน้าอกแน่นขึ้น ตัดสินใจที่จะปิดประตูนี้ตลอดไป。"
  },
  Event_59613_Name = {
    Text = "หลังประตู"
  },
  Event_59614_ChoiceDesc1 = {
    Text = "【Courage】สุ่มอัปเกรดผลของการแกะสลัก 2 การ์ด"
  },
  Event_59614_ChoiceDesc2 = {
    Text = "【การตัดสินใจ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_59614_Desc = {
    Text = "คำพูดของทาวีดังก้องอยู่ในหัวของคุณ。\nในบรรดาสิ้นสุดนับไม่ถ้วน มีเพียงเส้นทางเดียวที่ถูกต้อง。\nในความมึนงง คุณเห็นภาพลวงตาของโลกมากมายผ่านเข้ามาในสายตาของคุณเหมือนกับแผ่นฟิล์มที่กระพริบไปมา รอคอยช่วงเวลาที่จะกดปุ่มหยุดไว้。\nหลังจากวินาทีนี้ โลกจะพบกับจุดจบแบบไหนกันแน่?"
  },
  Event_59614_Name = {
    Text = "อนาคตหยุดนิ่ง"
  },
  Event_59615_ChoiceDesc1 = {
    Text = "【ละเลยความสงสัย】ได้รับ 50 รอยดำ"
  },
  Event_59615_ChoiceDesc2 = {
    Text = "【เผด็จการ】ได้รับ 75 รอยดำ ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_59615_Desc = {
    Text = "เมื่อเสียงหัวเราะของ N ดังขึ้น คุณเริ่มสงสัยในทุกคนที่เคยพบเจอ \n ว่าคนไหนคือการปรากฏตัวของเขา คนไหนคือเพื่อนที่คุณไว้ใจจริง ๆ ? \n เงาของเขาเปลี่ยนแปลงอยู่ตลอดเวลา ดูเหมือนจะมีใบหน้ามากมายที่กำลังยิ้มให้คุณ。"
  },
  Event_59615_Name = {
    Text = "หน้ากากเงาหนึ่งร้อยใบ"
  },
  Event_59616_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59616_Desc = {
    Text = "ถ้าทุกคนสามารถทรยศได้ ก็อย่าไปพึ่งพาใครเลย \n ในความมืด คุณสามารถยืนยันความจริงเพียงอย่างเดียว \n อย่างน้อยคุณยังมีตัวเอง—ตัวเองที่ซื่อสัตย์ที่สุดที่คุณสามารถไว้วางใจ。"
  },
  Event_59616_Name = {
    Text = "หน้ากากเงาหนึ่งร้อยใบ"
  },
  Event_59617_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59617_Desc = {
    Text = "คุณบีบมันอย่างแรง แก้วผลึกที่เปล่งประกายแตกเป็นผงในปลายนิ้วของคุณ \n คุณสูดอารมณ์จากอดีตเข้าไปอย่างโลภ \n ในชั่วพริบตาความสุขอันเข้มข้นไหลบ่ามายังสมองของคุณ และจากนั้นภาพหลอนก็เริ่มค่อยๆ จางหายไป \n มุมปากของคุณยกสูงขึ้น แต่ค่อยๆ ลดลง \n ใบหน้าของคุณค่อยๆ นิ่งสงบไร้คลื่นลม。"
  },
  Event_59617_Name = {
    Text = "Kristal อารมณ์"
  },
  Event_59618_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59618_Desc = {
    Text = "คุณรู้ว่าทุกสิ่งมีราคาที่ต้องจ่าย หากราคาที่ต้องจ่ายเพื่อช่วยชีวิตคือการเสียสละ ก็ให้ราคาที่ต้องจ่ายนั้นเป็นของตัวเองทั้งหมด \n คุณพร้อมที่จะให้ทุกอย่างตลอดเวลา。"
  },
  Event_59618_Name = {
    Text = "คำตอบของฉัน"
  },
  Event_59619_ChoiceDesc1 = {
    Text = "【ค้นหาคำตอบ】ได้รับรอยดำ Arg1，ติดเชื้อ「(Skill.Arg2)」，เลือกต่อไป"
  },
  Event_59619_ChoiceDesc2 = {
    Text = "【ละทิ้ง】ออก"
  },
  Event_59619_Desc = {
    Text = "มีใครบางคนกำลังตะโกน。\nคนที่อยากหนีอย่างเร่งรีบ, เขาพูดว่าการต่อสู้ถูกกำหนดให้ล้มเหลว。\nมีเพียงการหนีที่ไม่มีที่สิ้นสุดเท่านั้นที่จะสามารถชะลอการทำลายล้างในที่สุดได้。\nคุณจะเชื่อหรือไม่เชื่อ。"
  },
  Event_59619_Name = {
    Text = "การถามตัวเองของฉัน"
  },
  Event_59620_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59620_Desc = {
    Text = "คุณรู้ถึงความน่ากลัวของความเร็วในการเจริญเติบโตของตัวอ่อนแล้วหรือ ที่นี่การเกิดใหม่เป็นคำสาปเหมือนตั๊กแตน \n คุณบดขยี้พวกมันก่อนที่ทารกแรกเกิดจะส่งเสียงคร่ำครวญ \n ผู้คนที่ทำจากเนื้อและเลือดมองคุณด้วยความเคียดแค้น สอบถามว่าทำไมคุณถึงดูหมิ่นชีวิตที่ศักดิ์สิทธิ์ \n คุณตอบสนองด้วยการสังหารอย่างไม่มีที่สิ้นสุด。"
  },
  Event_59620_Name = {
    Text = "เงาของวันเก่า"
  },
  Event_59621_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59621_Desc = {
    Text = "ในขณะนี้คุณหวังว่าตัวเองจะเป็นคนที่โชคดีที่สุด และได้รับผลลัพธ์ที่สมบูรณ์แบบที่สุด。\n แต่ราคาที่ต้องจ่ายของโชคดีบางครั้งก็โหดร้ายยิ่งกว่า โชคดีและโชคร้ายมักจะมาคู่กัน เมื่อคุณได้รับในขณะนั้น อย่าลืมตรวจสอบว่าคุณสูญเสียอะไรไป。"
  },
  Event_59621_Name = {
    Text = "การเลือกชะตากรรม"
  },
  Event_59622_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59622_Desc = {
    Text = "คุณดูเหมือนจะกำลังแย่งพวงมาลัยรถยนต์กับใครสักคน มือของคุณขยับไปมาอย่างเต็มกำลัง พยายามควบคุมจังหวะของเพลง。\nในความขัดแย้งอย่างยากลำบาก คุณกดลงหนักๆ บนแถวคีย์เปียโน。\nการบรรเลงที่คลั่งไคล้ถูกคุณทำให้หยุดชะงัก คุณยิ้มออกมาที่มุมปาก ตกอยู่ในความบ้าคลั่งและการต่อสู้ที่บ้าคลั่งมากยิ่งขึ้น。"
  },
  Event_59622_Name = {
    Text = "เพลงปาร์ตี้วันสิ้นโลก"
  },
  Event_59623_ChoiceDesc1 = {
    Text = "【สนิทสนม】ได้รับ 25 รอยดำ"
  },
  Event_59623_ChoiceDesc2 = {
    Text = "【จ้องมอง】มีโอกาส 50% ได้รับ 50 รอยดำ， มีโอกาส 50% ไม่ได้อะไรเลย"
  },
  Event_59623_Desc = {
    Text = "มีแมวอยู่ข้างๆ คุณ ขนของมันนุ่มนวลและสะอาด ตีนหน้าของมันขาวเหมือนหิมะ \n แมวอยู่เคียงข้างคุณตลอดเวลา เดินตามคุณไปทุกย่างก้าว ราวกับเป็นบริวารที่ซื่อสัตย์ที่สุดของคุณ \n ความสับสนและความรู้สึกไร้ความช่วยเหลือ ความเจ็บปวดและความไม่สบายใจในใจของคุณทั้งหมดถูกปลอบประโลมจนเรียบเรียบแล้ว。"
  },
  Event_59623_Name = {
    Text = "ความล่อแหลมของแมว"
  },
  Event_59624_ChoiceDesc1 = {
    Text = "【ปฏิเสธ】ติดเชื้อ「(Skill.Arg1)」, ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg2)」"
  },
  Event_59624_ChoiceDesc2 = {
    Text = "【โต้แย้ง】ติดเชื้อสองครั้ง「(Skill.Arg1)」，ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」และ「(RelicConfig.Arg3)」"
  },
  Event_59624_ChoiceDesc3 = {
    Text = "【ความเงียบงัน】ได้รับสิ่งประดิษฐ์จากเงิน「(RelicConfig.Arg1)」"
  },
  Event_59624_Desc = {
    Text = "คุณจมอยู่ในภาพลวงตาของสุญญตา \n คุณเห็นผู้คนมากมายเงียบอยู่ใต้เงาของวันสิ้นโลก ตัวเล็กน้อยเหมือนฝุ่น \n พวกเขาไร้ชีวิตชีวา มืดมน และสูญเสียความหวัง \n คุณได้ยินเสียงหัวเราะที่แหลมคมของใครบางคน \n “ดูสิ นี่คือผลลัพธ์ที่คุณยึดมั่น” \n “โลกนี้ไม่มีวันสิ้นสุด ทุกสิ่งทุกอย่างไม่มีความหมาย”"
  },
  Event_59624_Name = {
    Text = "ลูกแกะรอความตาย"
  },
  Event_59625_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59625_Desc = {
    Text = "ไม่ นี่ไม่ถูกต้อง นี่ไม่ใช่เรื่องจริง。\nคุณปฏิเสธเสียงที่บ้าคลั่งนั้นอย่างต่อเนื่อง แต่เงาคนสีเทาก็ไม่มีปฏิกิริยา เหมือนกับยืนยันถึงจุดจบของสุญญตา。\nเสียงหัวเราะนั้นดังขึ้นเรื่อย ๆ ยุ่วยุความไร้เรี่ยวแรงของคุณ。"
  },
  Event_59625_Name = {
    Text = "ลูกแกะรอความตาย"
  },
  Event_59626_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59626_Desc = {
    Text = "คุณรู้สึกถึงความเสียใจและความไม่อยากจากไปอย่างมาก คุณพยายามนึกถึงสิ่งที่ผ่านมาอย่างหมดแรง พยายามค้นหาภาพเงาของอดีตในชิ้นส่วนของความทรงจำ \n เงาที่ไม่ชัดเจนเหล่านั้นถอยหลังไปอย่างรวดเร็ว คุณพยายามยื่นมือออกไปคว้า แต่กลับเห็นภาพเหล่านั้นไหลผ่านนิ้วมือไป \n คุณตระหนักว่าคุณกำลังจะไม่มีอะไรเลย。"
  },
  Event_59626_Name = {
    Text = "ความจำแยกส่วน"
  },
  Event_59627_ChoiceDesc1 = {
    Text = "【สนิทสนม】ได้รับ 25 รอยดำ"
  },
  Event_59627_ChoiceDesc2 = {
    Text = "【จ้องมอง】มีโอกาส 50% ได้รับ 50 รอยดำ， มีโอกาส 50% ไม่ได้อะไรเลย"
  },
  Event_59627_Desc = {
    Text = "มีแมวอยู่ข้างๆ คุณ ขนของมันเรียบลื่นและสะอาด ตีนหน้าของมันขาวเหมือนหิมะ \n แมวคอยอยู่เคียงข้างคุณเสมอ เดินตามไปตามคุณเหมือนเป็นบริวารที่ภักดีที่สุด \n ความสับสนและความรู้สึกไร้ความช่วยเหลือ รวมถึงความเจ็บปวดและความไม่สบายใจในใจคุณถูกปลอบประโลมจนเรียบง่าย。"
  },
  Event_59627_Name = {
    Text = "ความล่อแหลมของแมว"
  },
  Event_59628_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59628_Desc = {
    Text = "คุณพบกับตัวตนสุดท้ายของคุณที่นี่ การต่อสู้ที่ทำลายโลกทั้งใบ แท้จริงแล้วเป็นเพียงการสบตาระหว่างพวกคุณ \n เมื่อพระองค์มองมาที่คุณ คุณต้องมองพระองค์กลับไปอย่างมุ่งมั่น จนกว่าจะถึงช่วงเวลาที่สายตาใดสายตาหนึ่งหายไป。"
  },
  Event_59628_Name = {
    Text = "คำตอบของฉัน"
  },
  Event_59629_ChoiceDesc1 = {
    Text = "【การหายใจ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อไวรัส「(Skill.Arg2)」"
  },
  Event_59629_ChoiceDesc2 = {
    Text = "【การโต้กลับ】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ถูกโจมตีด้วย「(Skill.Arg2)」，「(Skill.Arg3)」"
  },
  Event_59629_ChoiceDesc3 = {
    Text = "【ดิ้นรน】ได้รับ 25 รอยดำ"
  },
  Event_59629_Desc = {
    Text = "เสียงเท้าดังขึ้นอย่างหนาแน่น กลุ่มนักสืบจากคณะกรรมการตรวจสอบได้ขวางทางคุณไว้ \n “กรุณาร่วมมือกับการสอบสวนของเรา” \n เสียงที่เย็นชานั้นแฝงไปด้วยเจตนาร้าย \n พลั่ก เสียงน้ำที่เงียบสงบถูกทำลาย พวกเขาโยนคุณลงไปในบ่อน้ำลึก。"
  },
  Event_59629_Name = {
    Text = "จมลงสู่เหว"
  },
  Event_59630_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59630_Desc = {
    Text = "คุณดิ้นรนอย่างสุดกำลัง \n ขยับไปข้างหน้าอีกนิด \n ไม่ว่าจะต้องจ่ายราคาที่ต้องจ่ายใด คุณต้องปกป้องทุกอย่างนี้ให้ได้ \n คุณพยายามยื่นมือออกไป เส้นด้ายบาดเข้าไปในเนื้อของคุณ แต่คุณไม่รู้สึกตัวเลย。"
  },
  Event_59630_Name = {
    Text = "มือที่ถูกบังคับ"
  },
  Event_59631_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59631_Desc = {
    Text = "คุณส่ายหัวอย่างแรง ปล่อยความทรงจำที่ยุ่งเหยิงออกจากสมองของคุณ。\n เสียงที่วุ่นวายค่อยๆ หายไป คุณจึงกลับมามีสติเป็นอิสระอีกครั้ง。\n คุณไม่สามารถได้รับความช่วยเหลือจากอดีตที่ล้มเหลวได้ มีเพียงการมุ่งเน้นไปที่ปัจจุบันเท่านั้นที่จะช่วยให้คุณค้นพบความหวัง。"
  },
  Event_59631_Name = {
    Text = "การถามตัวเองของฉัน"
  },
  Event_59632_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_59632_Desc = {
    Text = "ก่อนที่คุณจะยื่นมือออกไป คุณก็จำได้ทันทีว่า คุณไม่ได้เลี้ยงแมวแบบนี้มาก่อน\nคุณสบตากับแมวผ่านอากาศ แมวกระพริบตาให้คุณ\nแมวไม่สนใจความเย็นชาของคุณ มันยังดูเหมือนรักคุณเหมือนเดิม。"
  },
  Event_59632_Name = {
    Text = "ความล่อแหลมของแมว"
  },
  Event_59633_ChoiceDesc1 = {
    Text = "【ตามหาคำตอบ】 ได้รับ Arg1 สัญลักษณ์ดำ, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_59633_ChoiceDesc2 = {
    Text = "【ละทิ้ง】ออก"
  },
  Event_59633_Desc = {
    Text = "มีคนเศร้าและน้ำตาไหล \n ใบหน้าของเขาเต็มไปด้วยความเศร้าโศก อยากจะกอดคนที่รักที่สุด \n ช่วงเวลาที่ล่มสลาย เขาไม่ได้อยู่กับคนที่เขาห่วงใย นั่นคือความเสียใจที่ยิ่งใหญ่ที่สุดของเขา \n คุณรู้สึกเจ็บปวดในใจ และไม่สามารถหยุดความเศร้าได้。"
  },
  Event_59633_Name = {
    Text = "การถามตัวเองของฉัน"
  },
  Event_59634_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59634_Desc = {
    Text = "คุณมองไปที่เงาคนสีเทานับไม่ถ้วน โดยเพิกเฉยต่อเสียงหัวเราะที่ยุ่วยุ \n จะทำอย่างไรถึงจะช่วยโลกที่กำลังล่มสลายได้? \n คุณคิดอย่างต่อเนื่องในความเงียบของการทำลายล้าง。"
  },
  Event_59634_Name = {
    Text = "ลูกแกะรอความตาย"
  },
  Event_59635_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59635_Desc = {
    Text = "อากาศในถุงลมค่อยๆ หายไป คุณพยายามหายใจใต้น้ำ \n มันเป็นการกระทำที่โง่เขลา แต่คุณทำได้สำเร็จ \n ถุงลมของคุณกลับเต็มอีกครั้ง คุณสามารถหายใจออกได้อย่างสบาย \n แต่สิ่งที่คุณดูดเข้าไปคืออะไรกันแน่?"
  },
  Event_59635_Name = {
    Text = "จมลงสู่เหว"
  },
  Event_59636_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59636_Desc = {
    Text = "คุณจมลงไปในของเหลวที่เหนียวหนึบ。\nแม้ว่าคุณจะพยายามดิ้นรนอย่างสุดความสามารถ แต่ก็ยิ่งจมลงไปลึกขึ้น。\nคุณไม่สามารถหลบหนีจากบึงนี้ได้คนเดียว。"
  },
  Event_59636_Name = {
    Text = "จมลงสู่เหว"
  },
  Event_59637_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59637_Desc = {
    Text = "คุณบังคับตัวเองให้ลืมข้อสงสัยเหล่านี้ \n คุณรู้ดีว่าขณะนี้การสงสัยเป็นสิ่งที่ไร้ประโยชน์ที่สุด คุณจึงทำได้เพียงพยายามเชื่อ \n ก่อนที่กล่องที่ปิดสนิทจะถูกเปิด คุณไม่สามารถรู้ความจริงภายในกล่องได้ \n บางครั้ง การเป็นคนโง่เขลาจะทำให้คุณได้รับความสงบมากขึ้น。"
  },
  Event_59637_Name = {
    Text = "หน้ากากเงาหนึ่งร้อยใบ"
  },
  Event_59638_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59638_Desc = {
    Text = "ทุกสายตาจับจ้องไปที่คุณ คุณต้องทำหน้าที่เป็นผู้นำของทุกคน ไม่สามารถแสดงความอ่อนแอออกมาได้ \n “ไปที่สระดำ ทุกอย่างจะดีขึ้นเอง” \n คุณออกคำสั่งอย่างสงบ พร้อมกับสัญญาที่คุณเองยังไม่แน่ใจ。"
  },
  Event_59638_Name = {
    Text = "ตาแห่งความไม่รู้"
  },
  Event_59639_ChoiceDesc1 = {
    Text = "【สงสัย】ติดเชื้อ「(Skill.Arg1)」, ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg2)」"
  },
  Event_59639_ChoiceDesc2 = {
    Text = "【หยิ่ง】ติดเชื้อสองครั้ง「(Skill.Arg1)」 ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」 และ「(RelicConfig.Arg3)」"
  },
  Event_59639_ChoiceDesc3 = {
    Text = "【เพิกเฉย】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_59639_Desc = {
    Text = "มีเงาคนสามคนยืนอยู่ข้างหน้า พวกเขาพูดคุยกันอย่างไม่แน่ใจ \n คุณโน้มตัวไปใกล้เพื่อฟัง เสียงคำพูดและลมหายใจเริ่มชัดเจนขึ้น \n “อย่าเชื่อแมวตัวนั้น มันเป็นคนหลอกลวง” \n คุณหันกลับไปอย่างรวดเร็ว แต่กลับพบว่าข้างเคียงว่างเปล่า。"
  },
  Event_59639_Name = {
    Text = "ความลับกระซิบ"
  },
  Event_59640_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59640_Desc = {
    Text = "ดวงดาราดูเหมือนอร่อยมาก คุณมองหาพละกำลังของมันและกลืนมันลงไปในคำเดียว \n อึก \n คุณรู้สึกถึงความสดชื่นอย่างไม่เคยมีมาก่อน มีแสงสว่างระยิบระยับในมุมมองของคุณ \n เมื่อคุณก้มลงมอง ดวงดารายังคงส่องแสงอยู่ในกระเพาะของคุณ。"
  },
  Event_59640_Name = {
    Text = "ดาวอธิษฐาน"
  },
  Event_59641_ChoiceDesc1 = {
    Text = "【พยายามต่อไป】ลบการ์ดคำสั่ง 1 ใบ รับสัญลักษณ์ดำ Arg1"
  },
  Event_59641_ChoiceDesc2 = {
    Text = "【ตัดสายใย】คัดลอกการ์ดคำสั่ง 1 ใบ ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_59641_ChoiceDesc3 = {
    Text = "【อดทนไม่แสดงออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_59641_Desc = {
    Text = "ตลอดเส้นทางคุณถูกผลักดันให้เดินหน้า ทุกการเลือกของคุณถูกควบคุมโดยเส้นด้ายที่มองไม่เห็น \n คุณพยายามดิ้นรนด้วยมือทั้งสองเพื่อจับสิ่งที่คุณให้ความสำคัญ \n ชะตากรรมของโลกแขวนอยู่ที่ปลายนิ้วของคุณ \n เส้นด้ายจำนวนมากพันธนาการคุณไว้ทั่วทั้งร่างกาย。"
  },
  Event_59641_Name = {
    Text = "มือที่ถูกบังคับ"
  },
  Event_59642_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59642_Desc = {
    Text = "คุณเช็ดเลือดและน้ำตาที่มุมตาออกไป แต่เลือดและน้ำตานับไม่ถ้วนกลับไหลลงมาไม่หยุด\nสีแดงกระจายไปทั่วมุมมองของคุณ ราวกับเป็นการบอกใบ้ถึงการเสียสละที่เต็มไปด้วยเลือด\nคุณยังคงเช็ดอยู่เรื่อย ๆ ความเจ็บปวดทำให้คุณสั่นเทา แต่ไม่สามารถทำให้คุณรู้สึกกลัวแม้แต่น้อย。"
  },
  Event_59642_Name = {
    Text = "การฟิวชันของฉัน"
  },
  Event_59643_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59643_Desc = {
    Text = "คุณลูบไล้ก้อนอัญมณีวิเศษนี้ และฝังมันลงบนกุญแจเงิน \nแสงของดวงดาวส่องประกายมาที่คุณ \nคุณรู้สึกตะลึงงัน"
  },
  Event_59643_Name = {
    Text = "ดาวอธิษฐาน"
  },
  Event_59644_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59644_Desc = {
    Text = "คุณไม่สนใจอะไร ยังคงลืมตาไว้ ความมุ่งมั่นในใจกลายเป็นเสียงคำรามที่ดื้อรั้น。\nแม้ว่าจะต้องแตกสลายไป คุณก็จะไม่ถอยหลังแม้แต่ก้าวเดียว。"
  },
  Event_59644_Name = {
    Text = "การฟิวชันของฉัน"
  },
  Event_59645_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59645_Desc = {
    Text = "มีใครบางคนเงียบ ไม่พูดอะไร \n มองไปที่ใบหน้าที่เงียบงันอย่างสิ้นหวังของเขา คุณรู้ว่าพวกเขาทุกคนไม่ได้ไปถึงที่สุด \n คุณคือคนที่เดินไปได้ไกลที่สุดในตัวคุณเอง เพียงแค่คำตอบของคุณเท่านั้นที่เป็นความหวังสุดท้าย。"
  },
  Event_59645_Name = {
    Text = "การถามตัวเองของฉัน"
  },
  Event_59646_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59646_Desc = {
    Text = "คุณยื่นมือออกไป จับต้องดวงดาวตกนับไม่ถ้วน แก้วผลึกที่เปล่งประกายไหลผ่านปลายนิ้วของคุณ \n ความสุข ความเศร้า ความโกรธ ความกลัว... \n คุณแย่งชิงอารมณ์แต่ละเส้นอย่างโลภ และมองดูมันหายไปจากมือของคุณอย่างไม่สามารถทำอะไรได้ \n แสงสว่างที่สดใสส่องประกายไปยังใบหน้าของคุณ ดวงตาของคุณค่อยๆ กลายเป็นสีดำและลึกซึ้ง。"
  },
  Event_59646_Name = {
    Text = "Kristal อารมณ์"
  },
  Event_59657_ChoiceDesc1 = {
    Text = "【เรียก】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」"
  },
  Event_59657_ChoiceDesc2 = {
    Text = "【สัมผัส】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_59657_Desc = {
    Text = "คุณได้เห็นตุ๊กตาตกอยู่ในสภาพคราช。\nเธอเคยเป็นสิ่งมีชีวิตที่มีเหตุผลที่สุด และเป็นผู้ช่วยที่ซื่อสัตย์ที่สุด รักษาข้อมูลทั้งหมดที่พวกคุณได้รับอย่างตั้งใจ。\nแต่ตอนนี้เธอดูเหมือนจะไม่จำทุกอย่างที่พวกคุณเคยอยู่ด้วยกันอีกต่อไป。\nคุณเห็นน้ำตาใสไหลออกจากมุมตาของตุ๊กตา。"
  },
  Event_59657_Name = {
    Text = "น้ำตาตุ๊กตา"
  },
  Event_59658_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59658_Desc = {
    Text = "คุณไม่ยอมแพ้ พยายามเข้าถึงพลังงานของเธอ \n เพียงแค่เป็นเครื่องจักร การรีสตาร์ทต้องซ่อมได้แน่ๆ \n แต่ตุ๊กตาที่ไร้ความรู้สึกกลับไม่ให้โอกาสที่ไร้เดียงสาของคุณ \n การหยุดมือของคุณไม่ได้ทำให้ตุ๊กตาใจอ่อน คุณจึงต้องต่อสู้ด้วยกำลังทั้งหมด。"
  },
  Event_59658_Name = {
    Text = "น้ำตาตุ๊กตา"
  },
  Event_59659_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_59659_Desc = {
    Text = "คุณไม่ต้องการทำลายเพื่อนเก่าของคุณเลย \n คุณพยายามเรียกชื่อของเธออย่างสุดความสามารถ รายงานคำสั่งทั้งหมด แต่ไม่มีผลใดๆ \n ตัวตุ๊กตาได้หักหลังพวกคุณ กลับสู่ความเย็นชาของสิ่งไม่มีชีวิต。"
  },
  Event_59659_Name = {
    Text = "น้ำตาตุ๊กตา"
  },
  Event_60944_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_60944_Desc = {
    Text = "เวลาที่เหลือให้คุณไม่มากนัก คุณเลือกวิธีการจัดการที่ตรงไปตรงมาและฝ่าฝืนการปิดล้อม ผู้ปลุกตื่นได้รับแรงบันดาลใจและเริ่มรู้สึกกระตุ้นขึ้น \n ส่วนศัตรูที่ตื่นตัวมากขึ้นนั้นไม่ใช่เรื่องที่ต้องกังวล。"
  },
  Event_60944_Name = {
    Text = "นักสืบคณะกรรมการตรวจสอบ"
  },
  Event_60945_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_60945_Desc = {
    Text = "ก่อนที่นักสืบคนนั้นจะตอบสนอง คุณได้ล้อมไปที่ด้านหลังของเขาและยึดอาวุธของเขา ก่อนที่การสนับสนุนจะมาถึง คุณได้หนีออกจากที่นี่สำเร็จ \n น่าเสียดายที่ข่าวได้แพร่กระจายออกไปแล้ว ศัตรูที่ตามมามีการเตรียมพร้อม อาจทำให้การรับมือยากขึ้น เตรียมตัวให้พร้อมนะ。"
  },
  Event_60945_Name = {
    Text = "นักสืบคณะกรรมการตรวจสอบ"
  },
  Event_60946_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_60946_Desc = {
    Text = "นักสืบถูกเสียงหวูดดึงดูดเดินเข้ามาที่ที่ซ่อนของพวกคุณ ในขณะที่เขาเข้าใกล้ ร่างที่ถูกปลุกตื่นที่รอคอยมานานก็พร้อมใจกันโจมตี \n การโจมตีที่สมบูรณ์แบบ วิกฤตที่นี่ถูกแก้ไขอย่างถาวร。"
  },
  Event_60946_Name = {
    Text = "นักสืบคณะกรรมการตรวจสอบ"
  },
  Event_60947_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_60947_Desc = {
    Text = "เมื่อเผชิญหน้ากับศัตรูจำนวนมาก คุณไม่สามารถต่อสู้กับพวกเขาได้ คุณได้เดินเข้าไปในมุมมองของพวกเขาโดยไม่ได้ทำการต่อต้าน \n คุณรู้ว่าคุณกำลังจะถูกส่งไปยังจุดกักตัว ซึ่งเป็นส่วนหนึ่งของแผน \n คุณจะหนีจากที่นั่นและค้นหาเส้นทางใหม่。"
  },
  Event_60947_Name = {
    Text = "จุดตรวจสอบ"
  },
  Event_60948_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_60948_Desc = {
    Text = "เมื่อเผชิญหน้ากับศัตรูจำนวนมาก คุณไม่สามารถต่อสู้กับพวกเขาได้ หลังจากต่อสู้เพียงช่วงสั้นๆ คุณก็ยอมแพ้ในการต่อต้าน \n คุณรู้ว่าคุณกำลังจะถูกส่งไปยังจุดกักตัว ซึ่งเป็นส่วนหนึ่งของแผน \n คุณจะหนีจากที่นั่นและค้นหาเส้นทางใหม่。"
  },
  Event_60948_Name = {
    Text = "จุดตรวจสอบ"
  },
  Event_60949_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_60949_Desc = {
    Text = "เมื่อเผชิญหน้ากับศัตรูจำนวนมาก คุณไม่สามารถต่อสู้กับพวกเขาได้ \n คุณเลือกที่จะออกจากที่นี่ชั่วคราวเพื่อค้นหาเส้นทางใหม่。"
  },
  Event_60949_Name = {
    Text = "จุดตรวจสอบ"
  },
  Event_61058_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61058_Desc = {
    Text = "คุณจ้องมองไปที่มือของตัวเอง ร่างกายของคุณ เต็มไปด้วยความหวังและความมุ่งมั่น \n หากทั้งหมดนี้เป็นการจัดเตรียมของโชคชะตา คุณก็พร้อมที่จะเผชิญหน้ากับทุกสิ่งแล้ว \n หากในช่วงเวลาสุดท้ายมีประตูที่นำไปสู่สวรรค์หรือนรกจริงๆ ก็ให้คุณเป็นผู้เปิดประตูนี้ด้วยมือของคุณเองเพื่อโลก。"
  },
  Event_61058_Name = {
    Text = "มองลับ"
  },
  Event_61059_ChoiceDesc1 = {
    Text = "【เตรียมต่อสู้】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_61059_ChoiceDesc2 = {
    Text = "【สังเกตต่อไป】ติดเชื้อ「(Skill.Arg1)」，การแกะสลักใหม่，ทำได้มากที่สุด 1 ครั้ง"
  },
  Event_61059_Desc = {
    Text = "คุณไม่ได้รีบร้อนที่จะต่อสู้ แต่พยายามทำให้สถานการณ์ชัดเจนอย่างใจเย็น ผู้ dirigent ที่ปรากฏตัวขึ้นอย่างกะทันหันเหมือนศัตรูหรือเพื่อน คุณไม่แน่ใจว่าเขากำลังเตรียมทำอะไร อย่างไรก็ตาม คุณตัดสินใจที่จะเตรียมความพร้อมอย่างเต็มที่ ต้อนรับความท้าทายของเขาก่อน แล้วค่อยสังเกตว่าเขาต้องการทำอะไรจริงๆ。"
  },
  Event_61059_Name = {
    Text = "ผู้กำกับปีศาจ"
  },
  Event_61060_ChoiceDesc1 = {
    Text = "【ฟัง】ได้รับ การแกะสลักขั้นสูง เลือก 1 จาก 3"
  },
  Event_61060_ChoiceDesc2 = {
    Text = "【ตะโกน】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_61060_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_61060_Desc = {
    Text = "ตั้งแต่เกิดเหตุไม่คาดคิด คุณก็ไม่ได้รับข่าวจากคู่หูอีกเลย\nการติดต่อมากมายที่ส่งออกไปเหมือนกับหินที่ตกลงในทะเลลึก ไม่มีเสียงตอบกลับ\nในขณะที่คุณเริ่มหมดหวัง เครื่องสื่อสารก็ส่งเสียงขึ้นมาอย่างกะทันหัน\nคุณเปิดกระเป๋าเดินทางและนำโทรศัพท์แนบเข้ากับหู\n“ผู้พิทักษ์…”\nในความมึนงง คุณได้ยินเสียงที่คิดถึงมาตลอด เหมือนเสียงที่สะท้อนอยู่ห่างไกลผ่านความว่างเปล่าหลายชั้น。"
  },
  Event_61060_Name = {
    Text = "เสียงสะท้อนความคิดถึง"
  },
  Event_61061_ChoiceDesc1 = {
    Text = "【ยอมรับความมืด】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_61061_ChoiceDesc2 = {
    Text = "【พยายามว่ายน้ำ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_61061_ChoiceDesc3 = {
    Text = "【เรียกดวงวิญญาณ】ได้รับ 25 รอยดำ"
  },
  Event_61061_Desc = {
    Text = "คุณวิ่งไปข้างหน้า แต่พื้นดินใต้เท้ากลับเปลี่ยนเป็นทะเลที่ไม่สามารถเดินผ่านได้\nคุณตกลงสู่ผืนดิน\nเหมือนกับว่ามีวิญญาณในสุสานปรากฏขึ้นพร้อมกัน ความมืดเหนียวหนึบล้อมรอบตัวคุณ เข้าสู่ปากและจมูกด้วยความโลภ。"
  },
  Event_61061_Name = {
    Text = "จมลงใต้พื้นดิน"
  },
  Event_61062_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61062_Desc = {
    Text = "คุณเบิกตากว้าง พยายามค้นหาทุกเบาะแส \n ตาเกือบร้อยคู่หมุนไปพร้อมกัน คุณเห็นกรงเล็บของสุนัขที่วิ่งอยู่ข้างหน้า คุณเห็นเส้นทางของไม้ที่ฮาเมลน์กำลังโบกอยู่เบื้องหลัง \n คุณสังเกตทุกอย่างอย่างโลภ \n จู่ๆ คุณเห็นลูกตาที่คุ้นเคยกลิ้งตกลงบนพื้น \n มันเหมือนกับตาของคุณเอง。"
  },
  Event_61062_Name = {
    Text = "ความโลภในการแสวงหาความรู้"
  },
  Event_61063_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61063_Desc = {
    Text = "ไม่ถูกต้อง คุณไม่สามารถเห็นสิ่งต่าง ๆ ได้มากมายขนาดนี้ \n คุณมีแค่... มีแค่ตาไม่กี่คู่เท่านั้น \n คุณรีบหลับตาและยื่นมือไปสัมผัสที่ใบหน้า \n หนึ่ง สอง... \n เมื่อคุณลืมตาอีกครั้ง มุมมองของคุณกลับแคบและขาดความรู้ \n แท้จริงแล้วคุณมีเพียงสองตาเท่านั้น น่าเสียดาย น่าเสียดาย。"
  },
  Event_61063_Name = {
    Text = "ความโลภในการแสวงหาความรู้"
  },
  Event_61064_ChoiceDesc1 = {
    Text = "【ค้นหา】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_61064_ChoiceDesc2 = {
    Text = "【หลับตา】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_61064_Desc = {
    Text = "เบาะแสที่เพิ่มขึ้นเรื่อยๆ ถูกพันกันอย่างยุ่งเหยิง คุณรู้สึกกระวนกระวาย สับสน และโกรธ เคืองตัวเองว่าทำไมถึงไม่รู้อะไรเลย。\nแรงกดดันมหาศาลทำให้จิตใจของคุณตึงเครียดเหมือนเส้นด้ายเส้นเล็ก。\nทันใดนั้น คุณรู้สึกถึงหนังศีรษะที่ผ่อนคลายลง และคุณสามารถมองเห็นภาพทั้งหมดรอบตัวได้ เห็นเงาที่แกว่งไกวอยู่ในความว่างเปล่า。\nยังมีอีก คุณยังต้องการเห็นอีกมากมาย……"
  },
  Event_61064_Name = {
    Text = "ความโลภในการแสวงหาความรู้"
  },
  Event_61065_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61065_Desc = {
    Text = "คุณว่ายน้ำอยู่ในดิน จินตนาการว่าตัวเองเป็นปลาที่คล่องแคล่วที่สุด \n หากต้องการกลายเป็นปลา คุณต้องสละขาของมนุษย์ \n นี่คือราคาที่ต้องจ่ายของการแลกเปลี่ยน \n ไม่นาน คุณรู้สึกถึงความสบายอย่างที่ไม่เคยมีมาก่อน คุณกลายเป็นสิ่งที่มีอิสระที่สุดในใต้ดิน \n คุณว่ายกลับขึ้นมาที่ผิวดิน แต่กลับลืมวิธีการเดินไปแล้ว。"
  },
  Event_61065_Name = {
    Text = "จมลงใต้พื้นดิน"
  },
  Event_61066_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61066_Desc = {
    Text = "ปลายนิ้วของคุณสัมผัสกับความรู้สึกที่คุ้นเคยของกุญแจเงิน นั่นคือแกนกลางของแสงทั้งหมด \n นี่คือการสังเคราะห์ชีวิตของคุณ นี่คือการเป็นตัวแทนของชะตากรรมของคุณ \n ประสบการณ์ในอดีตผ่านเข้ามาในสายตาทีละฉาก \n การเลือกของคุณได้ผูกพันแน่นกับการเลือกของโลกนี้แล้ว \n ชะตากรรมของคุณได้เชื่อมโยงแน่นกับผู้คนมากมายแล้ว。"
  },
  Event_61066_Name = {
    Text = "มองลับ"
  },
  Event_61067_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61067_Desc = {
    Text = "คุณรู้สึกมีหลายสิ่งที่เป็นมิตรล้อมรอบคุณอยู่ \n คุณพยายามตะโกนเรียกวิญญาณที่อาจไม่มีอยู่ \n ปาฏิหาริย์เกิดขึ้น คุณกลับมายืนอยู่บนพื้นดินอีกครั้ง \n สุสานนับไม่ถ้วนยังคงเงียบงัน。"
  },
  Event_61067_Name = {
    Text = "จมลงใต้พื้นดิน"
  },
  Event_61068_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61068_Desc = {
    Text = "คุณไม่มีเวลามานั่งคร่ำครวญ คุณแค่ต้องการช่วยชีวิตทุกอย่างที่กำลังพังทลายให้เร็วที่สุด \n หากคุณกลายเป็นดาว คุณก็จงกลายเป็นดาวตกเถอะ \n ขอแค่สามารถส่องแสงในคืนที่มืดมิด แม้ว่าสุดท้ายจะต้องตกลงมาก็ตาม。"
  },
  Event_61068_Name = {
    Text = "มองลับ"
  },
  Event_61069_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61069_Desc = {
    Text = "คุณแนบหูแน่นขึ้น เก็บเสียงเล็กน้อยทั้งหมดไว้ในหัวของคุณ \n“ฉัน……” \n“คุณต้อง……” \nคุณได้ยินเพียงประโยคที่ไม่สมบูรณ์ ไม่สามารถแยกแยะความหมายใดๆ ได้ \nแต่คุณไม่กล้าที่จะส่งเสียง กลัวว่าจะพลาดทุกคำ \nแต่โชคชะตากลับไม่ให้ความเมตตาแก่คุณมากไปกว่านี้ \nเสียงที่เหลืออยู่เพียงเล็กน้อยก็หายไปเช่นกัน รอบข้างกลับคืนสู่ความเงียบ。"
  },
  Event_61069_Name = {
    Text = "เสียงสะท้อนความคิดถึง"
  },
  Event_61070_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61070_Desc = {
    Text = "คุณไม่ได้ครุ่นคิดต่อไป แต่สั่งให้เหล่าร่างที่ถูกปลุกเรียงแถว เพื่อรับมือกับความท้าทายของเขา"
  },
  Event_61070_Name = {
    Text = "ผู้กำกับปีศาจ"
  },
  Event_61071_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61071_Desc = {
    Text = "คุณเรียกชื่อเธออย่างต่อเนื่อง พยายามส่งต่ออารมณ์แม้เพียงเล็กน้อย。\nคุณไม่รู้ว่าเธอได้ยินหรือไม่ คุณพยายามแยกแยะเสียงที่ไม่ชัดเจนจากไมโครโฟน。\nมันดูเหมือนเป็นการตอบสนองของเธอ หรืออาจเป็นชิ้นส่วนมากมายจากอดีตที่กำลังเล่นซ้ำ。\nเล่นเรื่องราวของความเศร้าและความสุขที่พวกคุณเคยประสบร่วมกัน。"
  },
  Event_61071_Name = {
    Text = "เสียงสะท้อนความคิดถึง"
  },
  Event_61072_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_61072_Desc = {
    Text = "อาจจะความมืดนี้คือโลกที่แท้จริง การเข้าร่วมกับมันจะมีอะไรไม่ดี? \nคุณได้ยอมรับความมืดอย่างเต็มที่ ความมืดก็ไม่ปฏิเสธคุณอีกต่อไป คุณสามารถหายใจได้อย่างสบายใจ \nในวินาทีถัดไป คุณกลับมาบนพื้นดิน อาจมีบางสิ่งที่อยู่ในใต้ดินตลอดไป แต่สิ่งนั้นก็ไม่สำคัญอีกต่อไปแล้ว。"
  },
  Event_61072_Name = {
    Text = "จมลงใต้พื้นดิน"
  },
  Event_61073_ChoiceDesc1 = {
    Text = "【จ้องมองแสง】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，สถานะติดเชื้อ「(Skill.Arg2)」"
  },
  Event_61073_ChoiceDesc2 = {
    Text = "【แตะที่หน้าอก】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น และปลูกฝัง「(Skill.Arg1)」"
  },
  Event_61073_ChoiceDesc3 = {
    Text = "【วิ่งต่อไป】ได้รับ 25 รอยดำ"
  },
  Event_61073_Desc = {
    Text = "คุณรู้สึกสับสนในใจ จึงต้องวิ่งอย่างเต็มที่ ไม่มีเวลาคิดมากมาย \n จู่ๆ คุณรู้สึกว่าหน้าอกว่างเปล่า \n คุณก้มลงมอง พบว่าบริเวณที่เคยมีหัวใจเกิดเป็นแสงในรูปกุญแจ \n แสงนั้นสว่างขึ้นเรื่อยๆ และค่อยๆ แพร่กระจายไปทั่วร่างกาย \n คุณเห็นว่าตัวเองกลายเป็นดาวดวงหนึ่ง \n คุณจึงเข้าใจทันที ว่านี่อาจจะเป็นภารกิจที่คุณต้องทำมาตลอด。"
  },
  Event_61073_Name = {
    Text = "มองลับ"
  },
  Event_61074_ChoiceDesc1 = {
    Text = "【เตรียมต่อสู้】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_61074_ChoiceDesc2 = {
    Text = "【สังเกตอย่างละเอียด】ติดเชื้อ「(Skill.Arg1)」，การแกะสลักใหม่，มากที่สุด 2 ครั้ง"
  },
  Event_61074_Desc = {
    Text = "「เฮ้... เดี๋ยวก่อน! เกิดอะไรขึ้นกันแน่...」\n「กำลังซ้อม。」\nชายหนุ่มมองคุณด้วยสีหน้านิ่งเฉย。\n「การใช้เสียงดนตรีเพื่อรักษาลิงก์ร่างกายที่ตื่นขึ้น เป็นการลองใหม่ที่น่าสนใจ ต้องมั่นใจในระดับของวงดนตรี เพื่อให้การแสดงสมบูรณ์แบบ。」\nเขายกไม้คฑาขึ้นอย่างชัดเจนและกวัดแกว่งลงในอากาศ วาดเป็นสัญลักษณ์เริ่มต้นที่มีเสน่ห์。\n「เล่นเถอะ ผู้พิทักษ์。ให้ฉันได้เห็นว่า คุณสามารถทำอะไรได้บ้าง。」"
  },
  Event_61074_Name = {
    Text = "ผู้กำกับปีศาจ"
  },
  Event_61075_ChoiceDesc1 = {
    Text = "【เตรียมต่อสู้】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_61075_Desc = {
    Text = "ไม่ว่าเขาจะมีจุดประสงค์อะไร อย่างน้อยเขาก็ช่วยคุณออกจากการโจมตีของคณะกรรมการตรวจสอบ หากเขาต้องการทำร้ายคุณจริงๆ เขาก็ไม่จำเป็นต้องช่วยคุณเลย คุณใจเย็นลงและเตรียมตัวให้พร้อมสำหรับสิ่งสุดท้าย。"
  },
  Event_61075_Name = {
    Text = "ผู้กำกับปีศาจ"
  },
  Event_65400_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65400_Desc = {
    Text = "ผู้ประสานงานได้สื่อสารคำมั่นสัญญาในการช่วยเหลือจากภายนอกต่อพวกคุณ เมื่อได้ยินว่าทีมกู้ภัยกำลังหาวิธีเข้าไปในภูเขา ทุกคนก็กลับมามีความหวังอีกครั้ง。"
  },
  Event_65400_Name = {
    Text = "จุดติดต่อ"
  },
  Event_65401_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65401_Desc = {
    Text = "สมาชิกของคณะสำรวจวิทยาศาสตร์ทั้งหมดไม่มีใครออกจากภูเขาหิมะได้ ในเผชิญหน้ากับภัยพิบัติ คุณเลือกตัวเองเสมอ ชีวิตของคนธรรมดาในสายตาของคุณไม่มีค่าอะไรเลย คุณละทิ้งมนุษยธรรมและเดินทางไปจนถึงจุดหมายอย่างปลอดภัย \n ทีมกู้ภัยมองคุณด้วยความซับซ้อน คุณไม่แสดงอาการใด ๆ หันหลังกลับเข้าไปในพายุหิมะ อาจจะในคืนที่คุณฝันถึง เหล่าวิญญาณที่เสียชีวิตเพราะความเฉยเมยของคุณจะล้อมรอบที่ข้างเตียงของคุณและมองคุณอย่างเงียบ ๆ。"
  },
  Event_65401_Name = {
    Text = "จุดอพยพที่ปลอดภัย"
  },
  Event_65402_ChoiceDesc1 = {
    Text = "【ประชาชนอพยพ】นำออกสิ่งสร้าง「กองสำรวจ」ตามจำนวนสมาชิกของกองสำรวจ จะได้รับ「เหรียญกู้ภัย」ในระดับต่างๆ"
  },
  Event_65402_Desc = {
    Text = "คุณได้นำทีมสำรวจวิทยาศาสตร์ไปยังจุดอพยพอย่างปลอดภัย ทีมกู้ภัยได้เข้ามาดูแลทุกอย่าง ผู้ที่ได้รับการช่วยเหลือหมดแรงล้มลงกับพื้น ราวกับว่าอยู่ในอีกโลกหนึ่ง \n แต่คุณรู้ ว่าภัยคุกคามที่แท้จริงยังไม่ถูกแก้ไข สัตว์ประหลาดตัวนั้นยังคงอยู่ในภูเขา รอคอยด้วยความหิวโหย。"
  },
  Event_65402_Name = {
    Text = "จุดอพยพที่ปลอดภัย"
  },
  Event_65403_ChoiceDesc1 = {
    Text = "【แลกเปลี่ยนเสบียง】ได้รับ 25 รอยดำ ทุกๆ 1 คนในทีมสำรวจจะได้รับเพิ่มอีก 1 รอยดำ (Arg1)。"
  },
  Event_65403_ChoiceDesc2 = {
    Text = "【คำมั่นสัญญาการช่วยเหลือ】เลือกรับการแกะสลัก ๑ ชิ้น เติมเต็มเจ้าหน้าที่กองสำรวจ ๒ คน"
  },
  Event_65403_ChoiceDesc3 = {
    Text = "【ประสิทธิภาพสูงสุด】สูญเสียสมาชิกทีมวิจัย 10 คน เลือกที่จะได้รับทองคำ+สิ่งสร้างหนึ่งชิ้น。"
  },
  Event_65403_Desc = {
    Text = "พวกคุณเดินฝ่าพายุหิมะอย่างยากลำบาก ตามแสงไฟที่สว่างดับไปมาในจุดติดต่อฉุกเฉินที่อยู่ไกลออกไป\n    ○ ในที่สุด หลังจากการสวดมนต์นับไม่ถ้วน พวกคุณก็เห็นกระท่อมเล็กๆ ที่เต็มไปด้วยความหวัง。"
  },
  Event_65403_Name = {
    Text = "จุดติดต่อ"
  },
  Event_65403_Tips3 = {
    Text = "จำนวนสมาชิกในทีมสำรวจไม่เพียงพอ"
  },
  Event_65404_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65404_Desc = {
    Text = "พวกคุณได้ทราบรหัสผ่านของคลังจากผู้ประสานงาน และพบว่าวัสดุสำหรับทุกคนมีอยู่สองวัน ขอแสดงความยินดีที่พวกคุณจะไม่ต้องอดตายบนภูเขาหิมะอย่างน้อยก็ในตอนนี้。"
  },
  Event_65404_Name = {
    Text = "จุดติดต่อ"
  },
  Event_65415_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_65415_Desc = {
    Text = "ภูเขาหิมะได้เสร็จสิ้นการกินในพริบตา มีผู้คนสองคนหายไปตลอดกาลในรอยแยกน้ำแข็งที่ไม่สามารถมองเห็นก้นบึ้งได้ ขณะที่พวกคุณไม่รู้อะไรเกี่ยวกับเรื่องนี้เลย。"
  },
  Event_65415_Name = {
    Text = "ภาพลวง"
  },
  Event_65416_ChoiceDesc1 = {
    Text = "【ออก】ค้นหาไฟส่องสว่าง"
  },
  Event_65416_ChoiceDesc2 = {
    Text = "【บุกเข้าไปในหิมะใหญ่】สูญเสียสมาชิกทีมวิจัย 2 คน"
  },
  Event_65416_Desc = {
    Text = "บนภูเขาหิมะเกิดลมพายุพัดขึ้นอย่างกะทันหัน เสียงลมที่หวีดหวิวข้างหูเหมือนเสียงร้องแผดของสัตว์ยักษ์ หมอกหิมะขาวโพลนทำให้พวกคุณมองไม่เห็นในทันที ราวกับมีบางสิ่งกำลังเคลื่อนผ่านในหมอกขาวไม่สิ้นสุด \nพวกคุณถูกบังคับให้หยุดเดิน พยายามฝังขาทั้งสองข้างลงไปในหิมะเพื่อป้องกันไม่ให้ตัวเองกลิ้งลงไปตามทางลาด。"
  },
  Event_65416_Name = {
    Text = "ไม่รู้จัก"
  },
  Event_65417_ChoiceDesc1 = {
    Text = "【การหายไปอย่างเงียบเชียบ】สูญเสียสมาชิกทีมวิจัย 2 คน"
  },
  Event_65417_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_65417_Desc = {
    Text = "เสียงคำรามดังกึกก้องจากท้องภูเขาหิมะ ราวกับสัตว์ร้ายที่หิวโหยส่งเสียงคำรามอย่างไม่พอใจ แผ่นดินสั่นสะเทือน ชั้นน้ำแข็งที่อยู่ใต้หิมะเริ่มแตกออกอย่างเงียบ ๆ ราวกับว่าภูเขาหิมะกำลังอ้าปาก \nเมื่อแรงสั่นสะเทือนของแผ่นดินหยุดลง ผู้คนมองไปรอบ ๆ อย่างงุนงง และคุณหันกลับไปตรวจสอบกลุ่มของคุณ。"
  },
  Event_65417_Name = {
    Text = "ภาพลวง"
  },
  Event_65468_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65468_Desc = {
    Text = "เพื่อรับประกันความสามารถในการเคลื่อนไหวของทีม คุณได้ละทิ้งคนที่มีความยากลำบากในการดำเนินการ และทิ้งพวกเขาไว้ในกระท่อมที่โดดเดี่ยวแห่งนี้ อาจจะช่วยเพิ่มอัตราการรอดชีวิตของคนที่เหลืออยู่ แต่เมื่อมองไปที่สายตาที่เต็มไปด้วยความไม่ยอมแพ้และความแค้นเหล่านั้น คุณไม่มีความรู้สึกใดๆ เลยหรือ?"
  },
  Event_65468_Name = {
    Text = "จุดติดต่อ"
  },
  Event_65483_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65483_Desc = {
    Text = "คุณช่วยคนไว้ได้บางส่วน แต่มีคนจำนวนมากที่ยังคงอยู่บนภูเขาหิมะตลอดไป ไม่ว่าจะอย่างไร คุณก็ได้พยายามอย่างน้อยที่สุดแล้ว。\n ทีมกู้ภัยกล่าวว่าความพยายามของคุณจะได้รับการยกย่องในภายหลัง คุณโบกมือแล้วหันหลังเดินเข้าสู่พายุหิมะ。"
  },
  Event_65483_Name = {
    Text = "จุดอพยพที่ปลอดภัย"
  },
  Event_65484_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65484_Desc = {
    Text = "คุณไม่มีเวลาให้ใครนอกจากตัวเอง เพื่อที่จะออกจากภูเขาหิมะ คุณเลือกวิธีการที่มีประสิทธิภาพที่สุด ในสายตาของผู้รอดชีวิตคนสุดท้าย คุณอาจดูเหมือนปีศาจ \n ทีมกู้ภัยกล่าวว่าความพยายามของคุณจะได้รับการยกย่องในภายหลัง คุณโบกมือแล้วหันหลังเดินเข้าสู่พายุหิมะ。"
  },
  Event_65484_Name = {
    Text = "จุดอพยพที่ปลอดภัย"
  },
  Event_65485_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65485_Desc = {
    Text = "ภายใต้การปกป้องอย่างสุดความสามารถของคุณ ทีมสำรวจวิทยาศาสตร์ทั้งหมดไม่มีผู้บาดเจ็บหรือเสียชีวิต การได้พบคุณคือโชคที่ยิ่งใหญ่ที่สุดในความโชคร้ายของพวกเขา คุณคือผู้ช่วยชีวิตที่แท้จริงของพวกเขา。\nคุณสร้างปาฏิหาริย์ในวิกฤติโดยมีเรื่องเล่าของฮีโร่บนภูเขาหิมะที่อาจจะถูกเผยแพร่ไปทั่วในไม่ช้า ทีมกู้ภัยได้แสดงความเคารพว่าความพยายามอันยอดเยี่ยมของคุณจะได้รับการยกย่องในภายหลัง คุณยิ้มและโบกมือ ก่อนที่จะเดินกลับเข้าสู่พายุหิมะ。"
  },
  Event_65485_Name = {
    Text = "จุดอพยพที่ปลอดภัย"
  },
  Event_65486_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65486_Desc = {
    Text = "คุณใส่ใจชีวิตของผู้คนอย่างแท้จริง ผู้คนส่วนใหญ่ได้รับการช่วยชีวิตจากคุณ และผู้คนต่างร่ำไห้และขอบคุณคุณอย่างต่อเนื่องสำหรับการปกป้องตลอดเส้นทางของคุณ。\n ทีมกู้ภัยได้แสดงความเคารพว่าความพยายามอันยอดเยี่ยมของคุณจะได้รับการยกย่องในภายหลัง คุณยิ้มและโบกมือ ก่อนที่จะเดินกลับเข้าสู่พายุหิมะ。"
  },
  Event_65486_Name = {
    Text = "จุดอพยพที่ปลอดภัย"
  },
  Event_65487_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_65487_Desc = {
    Text = "คุณต่อสู้กับภัยพิบัติที่ไม่แน่นอน และช่วยผู้คนจากมือของความตาย หลังจากความพยายามของคุณ ผลลัพธ์ที่น่าเศร้าก็ได้เปลี่ยนแปลงไปเล็กน้อย \n ทีมกู้ภัยได้แสดงความเคารพว่าความพยายามอันมีค่าของคุณจะได้รับการยกย่องในภายหลัง คุณยิ้มและโบกมือ ก่อนที่จะเดินกลับเข้าสู่พายุหิมะ。"
  },
  Event_65487_Name = {
    Text = "จุดอพยพที่ปลอดภัย"
  },
  Event_6817_ChoiceDesc1 = {
    Text = "【พอดี】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_6817_ChoiceDesc2 = {
    Text = "【อ่านต่อไป】การ์ดคำสั่งสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6817_Desc = {
    Text = "บนชั้นหนังสือไม้ที่สูงที่สุด มีหนังสือปกสีทองเล่มหนึ่งวางอยู่ จากมุมมองของพื้นดินไม่สามารถมองเห็นชื่อหนังสือได้.\nไม่ทราบทำไม คุณเกิดความปรารถนาที่จะอ่านมันขึ้นมา... ความปรารถนานี้ขยายใหญ่ขึ้นอย่างควบคุมไม่ได้ในชั่วพริบตา คุณไม่สนใจความเสี่ยงที่จะรบกวนผู้อื่น ปีนบันไดไม้ข้างชั้นหนังสือและหยิบหนังสือเล่มนั้นลงมา อ่านอย่างกระวนกระวาย...\nภาพลางๆ เกิดขึ้นในทะเลความคิดของคุณ คุณจมอยู่ในมหาสมุทรแห่งภาพลวง..."
  },
  Event_6817_Name = {
    Text = "กระดาษม้วนสีเหลือง"
  },
  Event_6818_ChoiceDesc1 = {
    Text = "【รับฟัง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6818_ChoiceDesc2 = {
    Text = "【การบรรเลงร่วม】สำหรับทุกร่างกายที่ตื่นขึ้นซึ่งมีค่าความคลั่ง 50 หรือมากกว่า จะได้รับ 15 รอยดำ"
  },
  Event_6818_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_6818_Desc = {
    Text = "เสียงเปียโนดังขึ้นอย่างกระทันหันในหูของคุณ นิ้วมือสีเขียวเข้มกระโดดไปมาบนคีย์เปียโน เสียงอันสง่างามไหลราวกับน้ำในลำธาร \n「เพื่อนที่รัก อยากจะเล่นเพลงกับฉันไหม?」\n มือไม่สามารถพูดได้ แต่มันถามคุณด้วยเสียงเปียโน。"
  },
  Event_6818_Name = {
    Text = "ผีข้างเปียโน"
  },
  Event_6819_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6819_Desc = {
    Text = "รามอนนาหันไปทางต้นเสียง แต่ทันได้เห็นเพียงเงาลางๆ ที่ค่อยๆ จางหายไป ดูเหมือนเครื่องเล่นแผ่นเสียงที่ละลายอยู่ในผนัง。"
  },
  Event_6819_Name = {
    Text = "หูของผู้อื่น"
  },
  Event_6820_ChoiceDesc1 = {
    Text = "【เครื่องพิมพ์ดีด】ลบการ์ดคำสั่ง 1 ใบ, ได้รับ 25 รอยดำ"
  },
  Event_6820_ChoiceDesc2 = {
    Text = "【พยายามระบุตัวอักษร】คัดลอกการ์ดใบหนึ่งจากสำรับ ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6820_Desc = {
    Text = "เครื่องพิมพ์ดีดในกระเป๋าเดินทางพ่นหมึกข้นหนาออกมาอย่างกะทันหัน ขณะรถไฟสั่นสะเทือนทำให้หมึกกระเซ็นเป็นสายตกลงมา。"
  },
  Event_6820_Name = {
    Text = "เสียงกระซิบของเครื่องพิมพ์ดีด"
  },
  Event_6821_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6821_Desc = {
    Text = "ในชั่วขณะที่หมัดปัดเป่าภาพลวงตา ความทรงจำพุ่งเข้ามาในสมองของคุณอย่างรุนแรง นึกถึงช่วงเวลาที่กระทบกระเทือนจิตวิญญาณ ทำให้เกิดความเจ็บปวดที่อัดอั้น。"
  },
  Event_6821_Name = {
    Text = "ฟ้ามอร์กานา"
  },
  Event_6822_ChoiceDesc1 = {
    Text = "【กำจัดกระดาษจดหมาย】ลบการ์ด 1 ใบ"
  },
  Event_6822_ChoiceDesc2 = {
    Text = "【เก็บไว้ใกล้ตัว】ได้รับ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6822_Desc = {
    Text = "ดึงกระดาษเขียนจดหมายที่ถูกดูดเข้าไปในเครื่องพิมพ์ดีดออกมา ตัวอักษรที่เปียกชื้นปล่อยกลิ่นหมึกที่เข้มข้นออกมา คุณสแกนเนื้อหาของจดหมายและย่นคิ้วโดยไม่รู้ตัว \n เนื้อหาของจดหมายส่วนใหญ่ถูกปิดบังไปแล้ว ส่วนที่เหลือก็ไม่เป็นประโยค ไม่มีอะไรให้อ่านเหลืออยู่เลย。"
  },
  Event_6822_Name = {
    Text = "จดหมายที่ขีดฆ่า"
  },
  Event_6823_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6823_Desc = {
    Text = "คุณพยายามที่จะอ่านตัวอักษรที่เบลออยู่บนกระดาษ มันบิดเบือนอยู่ตลอดเวลา แล้วปรากฏเป็นเนื้อหาที่แตกต่างออกไปโดยสิ้นเชิง \n「@2ฉันคิดว่าคุณน่าจะเห็นข่าวนั้นจากหนังสือพิมพ์แล้ว \nใช่แล้ว คุณพ่อของคุณได้ตัดคุณออกจากลำดับการสืบทอดแล้ว... เราก็ไม่อยากจะ@2 \nปีศาจ ปีศาจ... \nกรุณาหยุดการติดต่อกับคุณเฮอร์เบิร์ตทันที มิฉะนั้นฉันจะหยุดการช่วยเหลือทางการเงินของคุณ...」"
  },
  Event_6823_Name = {
    Text = "เหมือนได้พบกัน"
  },
  Event_6824_ChoiceDesc1 = {
    Text = "【จับกุญแจเงิน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」 ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_6824_ChoiceDesc2 = {
    Text = "【ปิดตาทั้งสอง】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6824_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_6824_Desc = {
    Text = "คุณถูกดึงดูดด้วยความไร้สาระอันมหาศาล ร่างกายบิดเบี้ยวคลานอยู่บนพื้น ราวกับถูกควบคุมโดย@2จากมิติอื่น \n「ไม่...ไม่...」\nความมีสติของคุณพังทลายลงทีละน้อย รอยยิ้มที่บ้าคลั่งและเสียงกรีดร้องที่ไม่มีสติผสมกัน ราวกับเป็นตาข่ายขนาดใหญ่ที่พันธนาการจิตสำนึกของคุณ ไหลออกมาจากปากเป็นเพียงเสียงคร่ำครวญที่ไม่ชัดเจน。"
  },
  Event_6824_Name = {
    Text = "ตาที่จ้องมอง"
  },
  Event_6825_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6825_Desc = {
    Text = "ให้มันเป็นไปตามการจัดการของผู้พิทักษ์เถอะ，ไม่รู้ว่าจะปลุกสิ่งมีชีวิตแบบใด。"
  },
  Event_6825_Name = {
    Text = "ใจเงินเหงา"
  },
  Event_6826_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6826_Desc = {
    Text = "ทำนองเศร้าไหลเข้าสู่หู ความทุกข์และความเจ็บปวดเต็มไปด้วยสมองและจิตวิญญาณ เมื่อรู้สึกตัวอีกครั้ง มุมตาของใครบางคนก็เปียกชื้นแล้ว。"
  },
  Event_6826_Name = {
    Text = "เสียงไม่รู้ชื่อ"
  },
  Event_6827_ChoiceDesc1 = {
    Text = "【ผลักประตูด้านซ้าย】ได้รับของขวัญเงิน「(RelicConfig.Arg1)」"
  },
  Event_6827_ChoiceDesc2 = {
    Text = "【ผลักประตูด้านขวา】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6827_Desc = {
    Text = "ประตู。ประตู。ประตูนับไม่ถ้วน。\nจำนวนประตูดูเหมือนจะมากกว่าที่คุณและราโมน่าได้ตรวจสอบไว้มากมาย。\nพวกคุณยืนอยู่ในทางเดิน เตรียมที่จะผลักประตูถัดไป。\nประตูด้านซ้ายเงียบสงบ รอคอยการมาเยือนของพวกคุณอย่างแอบแฝง。\nประตูด้านขวามีเสียงสนทนาที่ไม่ชัดเจนดังออกมา。"
  },
  Event_6827_Name = {
    Text = "ประตูไม่รู้จบ"
  },
  Event_6828_ChoiceDesc1 = {
    Text = "【ฟังอย่างตั้งใจ】ได้รับสิ่งประดิษฐ์เงิน 「(RelicConfig.Arg1)」, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_6828_ChoiceDesc2 = {
    Text = "【ปิดหู】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_6828_Desc = {
    Text = "คุณได้ยินเพียงเสียงเคาะคีย์เปียโนที่คลั่งไคล้ ราวกับพายุฝนที่โหมกระหน่ำ ราวกับเสียงของอุกกาบาตที่กระแทกพื้น ทำให้เปียโนสั่นสะเทือน\nฆ้องไม้ที่ตีสายส่งเสียงดังเอี๊ยดอ๊าด เปลือกของเหยียบที่กระโดดอยู่ส่งเสียงคร่ำครวญอย่างเจ็บปวด\nในเสียงเพลงที่กลอุบาย เสียงทำนองที่คุ้นเคยถูกดึงเข้าไป ขูดขีดผ่านเยื่อแก้วหูของคุณ。"
  },
  Event_6828_Name = {
    Text = "ข้อห้ามของเสียง"
  },
  Event_6829_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6829_Desc = {
    Text = "「นักสืบวิลเลียมได้จัดส่งวัสดุฉุกเฉินให้คุณแล้ว กรุณาตรวจสอบและกดเข็มกลัดสามครั้งเพื่อยืนยัน」"
  },
  Event_6829_Name = {
    Text = "การสื่อสารสนับสนุน"
  },
  Event_6830_ChoiceDesc1 = {
    Text = "【ผลักประตูด้านซ้าย】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_6830_ChoiceDesc2 = {
    Text = "【ผลักประตูด้านขวา】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_6830_Desc = {
    Text = "ประตู ประตู มากมายประตู \nดูเหมือนจำนวนประตูน่าจะมีมากกว่าตอนที่คุณและราโมน่าเดินตรวจสอบมาก่อนหน้า \nพวกคุณหยุดยืนอยู่ที่ทางเดิน เตรียมพร้อมที่จะผลักประตูบานต่อไป \nด้านหลังประตูทางซ้ายเงียบสงบ ไม่มีเสียงใด ๆ ราวกับกำลังรอคอยการมาเยือนของพวกคุณอย่างสุภาพ \nทางด้านหลังประตูขวาได้ยินเสียงพูดคุยเบา ๆ ที่ฟังไม่ชัดเจน。"
  },
  Event_6830_Name = {
    Text = "ประตูไม่มีที่สิ้นสุด"
  },
  Event_6831_ChoiceDesc1 = {
    Text = "【อ่านจดหมาย】ลบการ์ดคำสั่ง 1 ใบ ได้รับ Arg1 รอยดำ"
  },
  Event_6831_ChoiceDesc2 = {
    Text = "【ปิดกล่องให้ดี】"
  },
  Event_6831_Desc = {
    Text = "กระเป๋าเดินทางสั่นสะเทือนไม่หยุด ราวกับมีชีวิตบางอย่างกำลังกัดเปลือกไข่และใกล้จะหลุดออกมา\nคุณเปิดกระเป๋าอย่างควบคุมไม่ได้ กระดาษเขียนจดหมายพุ่งออกมาเหมือนผีเสื้อที่ถูกปล่อยออก。"
  },
  Event_6831_Name = {
    Text = "จดหมายไม่ทันรู้เรื่อง"
  },
  Event_6832_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6832_Desc = {
    Text = "เสียงระฆังเร่งรีบทำให้ใจร้อน คุณหยิบโทรศัพท์ขึ้นมาวางไว้บนโต๊ะ เสียงระฆังเหมือนถูกจับที่คอแล้วหยุดลงอย่างกระทันหัน ทิ้งไว้เพียงเสียงสะท้อนที่เหลืออยู่ในหัวของคุณ。"
  },
  Event_6832_Name = {
    Text = "การโทรจากรถไฟ"
  },
  Event_6833_ChoiceDesc1 = {
    Text = "【หยิบรูปภาพ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_6833_ChoiceDesc2 = {
    Text = "【ตรวจสอบฟิล์ม】ติดเชื้อ「(Skill.Arg1)」，เปลี่ยนการแกะสลักจากตัวเลือก 1 ใช้ได้ 2 ครั้ง"
  },
  Event_6833_Desc = {
    Text = "มุมหนึ่งของสตูดิโอมีการวางกล้องเก่าๆ สองสามม้วนฟิล์มและภาพถ่ายที่กระจัดกระจายอยู่ มันบันทึกการทำงานและสุนทรียศาสตร์ของช่างทำหุ่นขี้ผึ้งอย่างซื่อสัตย์。"
  },
  Event_6833_Name = {
    Text = "บันทึกอย่างซื่อสัตย์"
  },
  Event_6834_ChoiceDesc1 = {
    Text = "【สอบสวนต่อ】เพิ่มพลังชีวิตสูงสุด Arg1 จุด"
  },
  Event_6834_ChoiceDesc2 = {
    Text = "【จับเงา】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6834_Desc = {
    Text = "เงาได้สวดมนต์ในฝุ่นทองคำว่า：\n「ผู้ที่รู้ความจริงนั้น...\nด้วยอำนาจของกุญแจ จะชี้นำผู้คนไปสู่เส้นทาง」\nนี่คือคำพังเพยโบราณ \nสัญชาตญาณบอกคุณว่ามันใกล้กับความจริงที่คุณค้นหาอยู่มาก \nและสัญชาตญาณของคุณมักจะแม่นยำเสมอ。"
  },
  Event_6834_Name = {
    Text = "ผู้ใช้กุญแจเงิน"
  },
  Event_6835_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6835_Desc = {
    Text = "คุณไม่ปิดบังความเห็นด้วยกับเสียงพึมพำที่บ้าคลั่งเลย ใต้การล่อลวงที่บ้าคลั่งของอีกฝ่าย คุณเกือบถูกผูกติดอยู่ที่โต๊ะอาหารของผู้มีอยู่。"
  },
  Event_6835_Name = {
    Text = "พิธีกรรมน้ำ"
  },
  Event_6836_ChoiceDesc1 = {
    Text = "【เรียกอีกา】ได้รับ 30 รอยดำ ติดเชื้อ「(Skill.Arg2)」 เลือกต่อไป"
  },
  Event_6836_ChoiceDesc2 = {
    Text = "【ออกห่างไปไกล】"
  },
  Event_6836_Desc = {
    Text = "คุณไม่จากไป พวกเขาก็ไม่เคยจากไปเช่นกัน。\nเชือกอันแปลกประหลาดเชื่อมโยงจิตวิญญาณของพวกคุณไว้ พวกเขาดูเหมือนมีบางอย่างที่อยากจะบอกคุณ。"
  },
  Event_6836_Name = {
    Text = "กุยบินโดดเดี่ยว"
  },
  Event_6837_ChoiceDesc1 = {
    Text = "【ยอมแพ้ต่อสู้】ลบการ์ดคำสั่ง 1 ใบ ได้รับ Arg1 รอยดำ"
  },
  Event_6837_ChoiceDesc2 = {
    Text = "【ดึงมือกลับ】"
  },
  Event_6837_Desc = {
    Text = "หนึ่งตัว สองตัว สามตัว……\nบนใบหน้า บนปลายนิ้ว ผีเสื้อกลุ่มหนึ่งเหมือนกับดอกไม้ไฟที่บานสะพรั่งอยู่ในอากาศ เปล่งประกายแสงเหมือนอัญมณีในความมืด \nเครื่องพิมพ์ดีดนี้ไม่มีประโยชน์ใช้สอยใดๆ แต่กลับเชี่ยวชาญในการสร้างสรรค์ความงาม。"
  },
  Event_6837_Name = {
    Text = "แรงบันดาลใจพุ่งพล่าน"
  },
  Event_6838_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6838_Desc = {
    Text = "สิ่งที่สำคัญกว่าอยู่ตรงหน้าคุณแล้ว คุณตั้งใจปิดกล่องและไม่สนใจมัน และเครื่องพิมพ์ดีดก็ค่อยๆ เงียบลง"
  },
  Event_6838_Name = {
    Text = "คำเตือนที่ไม่ได้รับเชิญ"
  },
  Event_6839_ChoiceDesc1 = {
    Text = "【ฟังเสียงดวงจันทร์】ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6839_ChoiceDesc2 = {
    Text = "【ฟังเสียงดาวแคระ】ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6839_ChoiceDesc3 = {
    Text = "【การฟังเสียงดาวตก】สูญเสียรอยดำ 25"
  },
  Event_6839_Desc = {
    Text = "กระตือรือร้น สว่างไสว ไม่มีวันสิ้นสุด"
  },
  Event_6839_Name = {
    Text = "เสียงของดาวและดวงจันทร์"
  },
  Event_6840_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6840_Desc = {
    Text = "ศูนย์กลางของความแวววับคือเงินใจที่ตรึงนิ่ง แต่เหตุผลบอกคุณว่า มันไม่ได้เปล่งแสง \n สายตาตามล่าหาแหล่งกำเนิดของแสง แต่กลับชนเข้ากับกับดักของความมืดและไม่รู้จัก……"
  },
  Event_6840_Name = {
    Text = "แสงนีออนยามค่ำคืน"
  },
  Event_6841_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_6841_Desc = {
    Text = "ทางออกด้านเหนือ!\nเหมือนที่รามอน่าตัดสินใจไว้ ข้างหน้าต้องมีทางออกแน่นอน"
  },
  Event_6841_Name = {
    Text = "ไปทางเหนือ"
  },
  Event_6842_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6842_Desc = {
    Text = "โอ้...สีเงินไร้ที่ติ แสดงถึงเรื่องตลกที่วิญญาณเล่นกับคุณ \nแล้ว การเลือกครั้งต่อไปของคุณคืออะไร?"
  },
  Event_6842_Name = {
    Text = "การแสดงกำลังเริ่มต้น"
  },
  Event_6843_ChoiceDesc1 = {
    Text = "【จากไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6843_Desc = {
    Text = "คุณส่ายหัว ปล่อยเสียงนั้นให้หลุดลอยไป\nเสียงถอนหายใจเบาๆ ที่ดูเหมือนจะมีอยู่จริง ส่งมาช่วยเหลือบางอย่าง。"
  },
  Event_6843_Name = {
