  },
  Event_6844_ChoiceDesc2 = {
    Text = "【ทางแยก】ได้รับ 25 รอยดำ"
  },
  Event_6844_Desc = {
    Text = "แสงจันทร์เลือนลาง ถูกทางเดินกลืนกิน เหลือเพียงประตูที่ส่อถึงบรรยากาศลางร้ายอยู่ตรงหน้า"
  },
