  Event_6845_Name = {
    Text = "ห้องโถงเงียบสงัด"
  },
  Event_6846_ChoiceDesc1 = {
    Text = "【ทางเดินลึก】ติดเชื้อ「(Skill.Arg1)」ยังคงจะเดินหน้าต่อหรือไม่"
  },
  Event_6846_ChoiceDesc2 = {
    Text = "【ทางแยก】ได้รับ 25 รอยดำ"
  },
  Event_6846_Desc = {
    Text = "ประตูทางซ้ายส่งเสียงหัวเราะเย็นยะเยือกออกมา มันสั่นไหวเล็กน้อย ปลดปล่อยความชั่วร้ายออกมาเป็นสาย ๆ"
  },
  Event_6846_Name = {
    Text = "ห้องโถงเงียบสงัด"
  },
  Event_6847_ChoiceDesc1 = {
    Text = "【ทางเดินลึก】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ยังต้องการก้าวไปข้างหน้าอีกหรือไม่"
  },
  Event_6847_ChoiceDesc2 = {
    Text = "【ทางแยก】ได้รับ 25 รอยดำ"
  },
  Event_6847_Desc = {
    Text = "ประตูด้านขวาเปิดออก เลือดไหลเป็นร่องรอยที่กำหนดไว้ล่วงหน้าบนพื้น"
  },
  Event_6847_Name = {
    Text = "ห้องโถงเงียบสงัด"
  },
  Event_6848_ChoiceDesc1 = {
    Text = "【ไม่มีอะไรเหลือแล้ว คุณถอยออกมา】"
  },
  Event_6848_Desc = {
    Text = "ใครบอกว่าต้องพุ่งชนอย่างเดียว? ถอยหลังหนึ่งก้าว บางทีอาจจะเห็นท้องฟ้างดงามกว่าที่คิด"
  },
  Event_6848_Name = {
    Text = "ห้องโถงเงียบสงัด"
  },
  Event_6849_ChoiceDesc1 = {
    Text = "【ซ่อมแซมหุ่นขี้ผึ้ง】เลือกการ์ดและลดการใช้พลังการคำนวณลง 1"
  },
  Event_6849_Desc = {
    Text = "การซ่อมแซมหุ่นขี้ผึ้งกำลังดำเนินต่อไป \n คุณไม่ใช่ช่างทำหุ่นขี้ผึ้งมืออาชีพ และไม่เคยได้รับการศึกษาด้านความงามอย่างเป็นระบบ \n แต่คุณยังคงเริ่มทำการหล่อ สร้างรูป และลงสีได้อย่างคล่องแคล่ว \n เหมือนกับว่าคุณเกิดมาเพื่อถือมีดแกะสลัก \n เหมือนกับว่ามันเกิดมาเพื่อมีข้อบกพร่อง เพียงเพื่อรอการแกะสลักจากคุณ。"
  },
  Event_6849_Name = {
    Text = "หุ่นขี้ผึ้งที่ยังไม่เสร็จ"
  },
  Event_6850_ChoiceDesc1 = {
    Text = "【ซ่อมแซมหุ่นขี้ผึ้ง】เลือกการ์ดและลดการใช้พลังการคำนวณลง 1"
  },
  Event_6850_Desc = {
    Text = "กาลาเทีย กาลาเทีย......\nคุณตามเสียงเรียกไปพบหุ่นขี้ผึ้งที่ยังไม่เสร็จอีกครั้ง.\nเธอดูสมบูรณ์แบบมาก จนทำให้รู้สึกไม่สบายใจ.\n「ความน่าเกลียดคือรอยแยกที่ฉีกความสมบูรณ์แบบออกมา。」\nในช่วงเวลาสุดท้าย คุณตัดสินใจทำอะไรบางอย่าง.。"
  },
  Event_6850_Name = {
    Text = "หุ่นขี้ผึ้งที่ยังไม่เสร็จ"
  },
  Event_6851_ChoiceDesc1 = {
    Text = "【ยอมรับภาพหลอน】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6851_ChoiceDesc2 = {
    Text = "【ปฏิเสธภาพหลอน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_6851_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_6851_Desc = {
    Text = "ใต้สะพานเหล็กที่มืดทึบและหนักหน่วง บนชายฝั่งแม่น้ำที่เงียบสงบซึ่งมีต้นอ้อขึ้นรก อยู่ๆ ก็มีผีเสื้อที่เปล่งประกายบินออกมา\nผีเสื้อเบาๆ ลงบนฝ่ามือของคุณ เสียงร้องโหยหวนที่น่าขนลุกหยุดลง แทนที่ด้วยเสียงคำรามของรถไฟที่ทับเหล็กขึ้นสนิม เสียงป๊อกป๊อกของถ่านที่เผาไหม้ และเสียงโลหะที่เสียดสีกันของเพลาล้อ……"
  },
  Event_6851_Name = {
    Text = "ภาพลวงตาทางรถไฟ"
  },
  Event_6852_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6852_Desc = {
    Text = "ใช่แล้ว หนีไปเถอะ คุณกำลังถูกสิ่งมีชีวิตบางอย่างไล่ตาม สัญชาตญาณการเอาชีวิตรอดทำให้คุณวิ่งอย่างบ้าคลั่ง จนไม่มีทางหนีอีกต่อไป ไม่สิ ควรจะไม่มีทางหนีอีกต่อไป... ไม่ใช่สุนัขแห่งนรกหรอกหรือ?"
  },
  Event_6852_Name = {
    Text = "วิ่ง"
  },
  Event_6853_ChoiceDesc1 = {
    Text = "【นี่ไม่ใช่เรื่องจริง】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」"
  },
  Event_6853_ChoiceDesc2 = {
    Text = "【ตกลงอย่างต่อเนื่อง...】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_6853_Desc = {
    Text = "กระจกที่ตกลงพื้นมีกรอบที่ประณีต กรอบนั้นมีกรอบอีก กรอบนั้นมีกรอบอีก...\nอาลิซกระโดดลงไปในโพรงกระต่ายที่ไม่มีที่สิ้นสุดและตกลงไปเรื่อยๆ เธอเห็นกระจกหนึ่งแล้วอีกหนึ่ง กระต่ายหนึ่งแล้วอีกหนึ่งที่ติดอยู่ที่นี่ แต่กลับไม่เห็นตัวเองเลย。"
  },
  Event_6853_Name = {
    Text = "กระจกในกระจก"
  },
  Event_6854_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6854_Desc = {
    Text = "คุณมองลงไปที่ภูเขาหิมะผ่านผ้ากรองลมและหิมะ มีมดสีดำจำนวนมากไล่ตามมดสีดำตัวหนึ่ง...\nความคิดของคุณถูกขัดจังหวะ。"
  },
  Event_6854_Name = {
    Text = "ความทรงจำภูเขาไฟ"
  },
  Event_6855_ChoiceDesc1 = {
    Text = "【เข้าไปจับ】ได้รับ 25รอยดำ"
  },
  Event_6855_ChoiceDesc2 = {
    Text = "【การตอบสนองที่เป็นมิตร】โอกาส 50% ได้รับ 50 รอยดำ โอกาส 50% ไม่ได้อะไรเลย"
  },
  Event_6855_Desc = {
    Text = "วิฬารตัวหนึ่งนั่งอยู่ระหว่างเมือก D โดยไม่ทราบมาจากที่ใด รูปร่างที่ไม่ชัดเจนบ่งบอกว่ามันน่าจะเป็นผู้อาศัยในมิติทางจิตวิญญาณ。\nเงาที่มองไม่เห็นใบหน้านี้ใช้ความสนใจอันชาญฉลาดมองไปที่ราโมน่า มันยกอุ้งเท้าหน้าสีขาวสะอาดขึ้น คล้ายกับการโบกมือเพื่อเรียกเธอ。"
  },
  Event_6855_Name = {
    Text = "ผู้อยู่อาศัยที่เดินทาง"
  },
  Event_6856_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6856_Desc = {
    Text = "ภาพหมู่ที่เต็มไปด้วยความสุข\nหุ่นขี้ผึ้งแต่งตัวอย่างสวยงาม นั่งเรียงกันอย่างเป็นระเบียบบนเก้าอี้ พร้อมกับยิ้มที่เกินจริงเหมือนกัน\nพวกมันมีความกลมกลืนกันราวกับที่คุณสามารถเห็นได้ในโรงพยาบาลจิตเวชแห่งใดแห่งหนึ่ง\n\nลงชื่อ: อัลลูวิ 305 ปี, @2 โรเจอร์ส"
  },
  Event_6856_Name = {
    Text = "ห้องแสดงภาพเหมือน"
  },
  Event_6857_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6857_Desc = {
    Text = "คุณค่อยๆ หยิบชิ้นส่วนขึ้นมา ตรวจสอบอย่างละเอียด มันก็หยุดเคลื่อนไหวอีกครั้ง \n「ทำตัวไม่ดี อย่าขยับนะ」ดอลล์เคาะเบาๆ ที่ท้ายทอยของคุณ「ในช่วงเวลาสั้นๆ นี้ฉันคงไม่สามารถทำชิ้นที่สองให้คุณได้」"
  },
  Event_6857_Name = {
    Text = "ไม้พิณที่ไม่สงบ"
  },
  Event_6858_ChoiceDesc1 = {
    Text = "【ใช้กุญแจ】"
  },
  Event_6858_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_6858_Desc = {
    Text = "ประตูบานหนึ่งขวางทางคุณไว้ คุณได้ลองทุกวิธีแล้ว แต่มันก็ยังไม่ขยับแม้แต่น้อย"
  },
  Event_6858_Name = {
    Text = "ประตูที่เป็นสนิม"
  },
  Event_6858_Tips1 = {
    Text = "จำเป็นต้องได้รับ「กุญแจที่เป็นสนิม」"
  },
  Event_6859_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6859_Desc = {
    Text = "คุณรู้สึกอับอายกับความเด็ดขาดของตัวเอง \n ผู้พิทักษ์ที่มีคุณสมบัติเหมาะสมต้องมีความระมัดระวัง คุณไม่ควรตัดสินอย่างไม่รอบคอบว่ามันไม่ใช่ 「สินค้าระดับสูง」 \n ดังนั้นคุณจึงตัดสินใจที่จะสังเกตมันอย่างละเอียด \n ผ่านไปห้านาที ผ่านไปสิบนาที... \n โอเค ตอนนี้คุณสามารถตัดสินได้แล้ว— \n มันเป็นของเสียจริงๆ。"
  },
  Event_6859_Name = {
    Text = "วิญญาณที่ถูกผูกมัด"
  },
  Event_6860_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6860_Desc = {
    Text = "คุณและเพื่อนของคุณวางอาวุธลง \n นี่ไม่ใช่ความใจดีอย่างยิ่ง แต่เป็นเพราะคุณเข้าใจว่าร่างกายที่ไม่มั่นคงของพวกมันไม่สามารถทนได้อีกนาน \n จริง ๆ แล้วการตัดสินใจของคุณนั้นถูกต้อง。"
  },
  Event_6860_Name = {
    Text = "แบบฝึกหัด"
  },
  Event_6861_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6861_Desc = {
    Text = "「มาไล่ฉันสิ!」\n「มาเถอะ ไอ้โง่!」\n「ถ้ามีความสามารถก็จับพวกเราซิ!」\nเสียงของเด็กๆ เต็มไปด้วยความภาคภูมิใจ。\n「ไอ้สารเลว! ยืนอยู่ที่นั่น!」\nเสียงของผู้ใหญ่หอบหายใจ。"
  },
  Event_6861_Name = {
    Text = "ความทรงจำของเรา"
  },
  Event_6862_ChoiceDesc1 = {
    Text = "【เข้า】ผ่านหมอก ไปสู่ปลายทางอีกด้าน。"
  },
  Event_6862_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_6862_Desc = {
    Text = "นี่คือคนที่คุณตามหา คุณได้ทำภารกิจสำเร็จแล้ว 。"
  },
  Event_6862_Name = {
    Text = "ทางลับเดี่ยว 26"
  },
  Event_6863_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_6863_Desc = {
    Text = "อ๊ะ! ขาดไปนิดเดียว! เดี๋ยวก่อน ทำไมลูกเต๋าสามลูกถึงทอยได้สิบแต้ม!\nลูกเต๋านอนอยู่ตรงหน้าคุณอย่างสงบ ดูเหมือนจะเชื่อฟังและไร้เดียงสา。"
  },
  Event_6863_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_6864_ChoiceDesc1 = {
    Text = "【ออก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_6864_Desc = {
    Text = "ชิบ! ไม่ใช่หกโมง แต่ก็ยังพอได้กำไรอยู่บ้าง \n แล้วมันกี่โมงแน่?"
  },
  Event_6864_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_6865_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_6865_Desc = {
    Text = "ถึงแม้จะไม่ได้เดาถูก แต่ก็ยอมรับได้\nอ้าว พวกมันทอยลูกเต๋าได้กี่แต้มกันแน่?"
  },
  Event_6865_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_6866_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6866_Desc = {
    Text = "คุณก้มหน้าคัดเลือกชิ้นส่วนปูนปลาสเตอร์ทีละชิ้น แล้วประกอบกลับไปยังร่างกายของเธอทีละส่วน จนบางส่วนของร่างกายเธอเริ่มมีรูปทรงขึ้นในมือของคุณ。"
  },
  Event_6866_Name = {
    Text = "ประกอบซาก"
  },
  Event_6867_ChoiceDesc1 = {
    Text = "【หยิบกุญแจ】"
  },
  Event_6867_Desc = {
    Text = "ชุดกุญแจที่เต็มไปด้วยสนิม สามารถใช้ไขประตูได้。"
  },
  Event_6867_Name = {
    Text = "กุญแจที่เป็นสนิม"
  },
  Event_6868_ChoiceDesc1 = {
    Text = "【ด้านหน้า】มีโอกาส 50% ที่จะได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」 และมีโอกาส 50% ที่จะติดเชื้อ「(Skill.Arg3)」"
  },
  Event_6868_ChoiceDesc2 = {
    Text = "【ด้านลบ】มีโอกาส 50% ได้รับรอยดำ 75 ดวง และมีโอกาส 50% ได้รับผลกระทบจาก 「(Skill.Arg3)」"
  },
  Event_6868_ChoiceDesc3 = {
    Text = "【กรุณาให้ฝ่ายตรงข้ามเลือกก่อน】มีโอกาส 50% ที่จะได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg2)」และมีโอกาส 50% ที่จะติดเชื้อ「(Skill.Arg3)」"
  },
  Event_6868_Desc = {
    Text = "แค่เกมเดิมพันเท่านั้น คุณจะไม่แพ้หรอก。\nเหรียญที่แกะสลักลวดลายถูกโยนขึ้นสูง แล้วตกลงมาอย่างรวดเร็ว ถูกฝ่ามือของคุณทำให้ร้อนขึ้น。"
  },
  Event_6868_Name = {
    Text = "นักพนันชื่อดัง"
  },
  Event_6869_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_6869_Desc = {
    Text = "「ผู้ที่ฝากความหวังไว้กับชะตากรรม ก็จะถูกชะตากรรมพลิกผัน」\nคุณเลือกที่จะออกจากไป。"
  },
  Event_6869_Name = {
    Text = "นักพนันชื่อดัง"
  },
  Event_6870_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6870_Desc = {
    Text = "「ผู้พิทักษ์。」\nเสียงของรามอน่าทำให้คุณฟื้นคืนสติ แต่ความรู้สึกเหมือนกำลังตกลงไปยังไม่หายไป"
  },
  Event_6870_Name = {
    Text = "กระจกในกระจก"
  },
  Event_6871_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6871_Desc = {
    Text = "มีการกล่าวกันว่า เซเรนาท เป็นเพลงที่มีต้นกำเนิดมาจากความรัก \n ในคืนฤดูร้อน ที่หน้าต่างของคู่รัก ผู้คนได้เล่นเพลงที่มีความหวานซึ้งนี้ร่วมกัน \n เป็นเพลงที่ไม่เป็นระเบียบและตื้นเขิน ไม่ตรงตามอ aesthetic ของโรเจอร์ส แต่ยังคงเป็นเพลงที่เขาเก็บรักษาไว้ \n คงมีเพียงเขาเท่านั้นที่จะรู้เหตุผล。"
  },
  Event_6871_Name = {
    Text = "รสนิยมที่แย่"
  },
  Event_6872_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6872_Desc = {
    Text = "คุณปฏิเสธที่จะถูกล่อลวงด้วยการพึมพำของพวกมัน \n คุณพูดว่า:「โกหกทั้งเพ! พวกคุณติดอยู่ในค่ำคืนที่มืดมิดตลอดกาล จะเดินทางข้ามจักรวาลได้อย่างไร?」 \n ดวงตาหลายดวงหัวเราะขึ้นมา เสียงหัวเราะนับไม่ถ้วนรวมกันเป็นคลื่นเสียงขนาดใหญ่ และหัวใจของคุณก็สั่นสะเทือนตาม \n ดวงตาพูดว่า:「ผ่านการปล้นดวงตาอื่น ๆ ทุกดวงตาคือจักรวาล เมื่อคุณมีดวงตาพันดวง คุณจะเริ่มต้นการเดินทางผ่านเวลาและอวกาศอย่างแท้จริง」"
  },
  Event_6872_Name = {Text = "ตา"},
  Event_6873_ChoiceDesc1 = {
    Text = "【รับ】ได้รับสิ่งประดิษฐ์ทองคำ เลือก 1 จาก 3"
  },
  Event_6873_Desc = {
    Text = "โอใช่ เงาที่น่ารังเกียจนั้นก็คือคุณเอง \n ความชั่วร้ายที่พุ่งออกมานั้นผสมรวมกับน้ำดำใต้เท้าของคุณ บิดเบี้ยวเต้นรำไปด้วยกัน หากไม่รังเกียจ มันก็อยากปีนขึ้นไปบนบ่าของคุณ。"
  },
  Event_6873_Name = {
    Text = "ใต้ผิวกระจก"
  },
  Event_6874_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6874_Desc = {
    Text = "ไม่นาน การผูกมัดก็หลุดออกอย่างกะทันหัน ทำให้คุณเซไปเซมา。\nคุณหันหลังไปมองเส้นใยที่เงียบสงบ—「ห้ามรบกวนทรายไหล」 คำนี้อาจใช้ได้ในดินแดนลับแลเช่นกัน。"
  },
  Event_6874_Name = {
    Text = "ติดอยู่ลึก"
  },
  Event_6875_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6875_Desc = {
    Text = "ความรู้ทางจิตวิญญาณลุกโชนขึ้น เผาผลาญพันธนาการทั้งมวลจนหมดสิ้น——\nอย่างน้อย นั่นคือสิ่งที่คุณคิด"
  },
  Event_6875_Name = {
    Text = "ติดอยู่ลึก"
  },
  Event_6876_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6876_Desc = {
    Text = "พยายามหลุดพ้นจากการผูกมัดอย่างสุดกำลัง เส้นด้ายฉีกเสื้อผ้า ทิ้งรอยเลือดเล็กๆ บนผิวหนัง\nแม้ว่าจะมีอะไรบางอย่างที่ใยแมงมุมทิ้งไว้เป็นค่าผ่านทาง แต่ความรู้สึกก็ยังคลายความกดดัน——คุณเป็นอิสระแล้ว。"
  },
  Event_6876_Name = {
    Text = "ติดอยู่ลึก"
  },
  Event_6877_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6877_Desc = {
    Text = "กระดาษเขียนจดหมายที่เกิดจากสิ่งมีชีวิตที่ถูกหลอมกร่อน ข้อมูลที่เกิดขึ้นส่วนใหญ่ก็จะถูกลบล้างไปเช่นกัน。\nคุณไม่ได้รับข้อมูลที่มีค่าใดๆ จากกระดาษเขียนจดหมาย จึงฉีกกระดาษทิ้งแล้วปล่อยให้มันร่วงหล่น。"
  },
  Event_6877_Name = {
    Text = "บทผีเสื้อ"
  },
  Event_6878_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6878_Desc = {
    Text = "แม้ข้อความจะถูกลบออกอย่างตั้งใจ แต่คุณยังคงสามารถรับรู้ได้อย่างชัดเจน——คุณค่าของจดหมาย。"
  },
  Event_6878_Name = {
    Text = "บทผีเสื้อ"
  },
  Event_6879_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6879_Desc = {
    Text = "ปลอดภัยไว้ก่อน \n รามอน่าก้มตัวกลับไปที่ทางเดินแล้วแอบเข้าไปในห้องถัดไป。"
  },
  Event_6879_Name = {
    Text = "การสะท้อนในหน้าต่าง"
  },
  Event_6880_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6880_Desc = {
    Text = "คุณส่งเสียงกรีดร้องที่เต็มไปด้วยความสิ้นหวัง\nฝูงอีกาดูเหมือนจะถูกเสียงของคุณหลอกลวง ไม่นานก็หายไปหมด ทิ้งร่องรอยสีดำไว้อยู่เบื้องหลัง。"
  },
  Event_6880_Name = {
    Text = "เพลงของฝูงอีกา"
  },
  Event_6881_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6881_Desc = {
    Text = "คุณหดตัวลงพยายามทำให้ตัวเองกลายเป็นจุดดำ\nเพื่อที่พวกเขาจะได้ไม่สังเกตเห็นคุณ\nไม่รู้ว่าเวลาผ่านไปนานแค่ไหน คุณลืมตาขึ้น\nคุณเห็นแสง。"
  },
  Event_6881_Name = {
    Text = "เพลงของฝูงอีกา"
  },
  Event_6882_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6882_Desc = {
    Text = "เงาไหลผ่านร่องนิ้วอย่างแผ่วเบา ทิ้งฝุ่นสีทองทั่วพื้น"
  },
  Event_6882_Name = {
    Text = "ผู้ใช้กุญแจเงิน"
  },
  Event_6883_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6883_Desc = {
    Text = "คุณขยี้ผมของคุณอย่างไม่เป็นระเบียบ จินตนาการและความคิดอันบ้าคลั่งแข่งขันกันผุดขึ้นในหัวของคุณ ก้อนที่ถูกห่อหุ้มด้วยเมือกสีดำซ่อนอยู่ในที่ลึก \n หากผ่าออก มันจะให้ของขวัญอะไรแก่คุณ?"
  },
  Event_6883_Name = {
    Text = "กวนสมอง"
  },
  Event_6884_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6884_Desc = {
    Text = "คราบน้ำมันสีรุ้งค่อยๆ แผ่ซ่านเต็มสายตา ความรู้สึกของคุณจมอยู่ในวังวนแห่งความโกลาหล"
  },
  Event_6884_Name = {
    Text = "กวนสมอง"
  },
  Event_6885_ChoiceDesc1 = {
    Text = "【เก็บเข้ากระเป๋า】"
  },
  Event_6885_Desc = {
    Text = "สารสีเงินที่ใกล้เคียงกับปรอท สกัดจากน้ำเมือกการย่อยสลาย มีพลังจิตที่เข้มแข็ง มักใช้ในพิธีกรรมเพื่อลิงก์กับผู้ปลุกตื่นมากขึ้น。"
  },
  Event_6885_Name = {
    Text = "เงินใจ"
  },
  Event_6886_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6886_Desc = {
    Text = "เสียงหัวเราะที่มีความสุขหลั่งไหลออกมาจากกล่อง หลังจากที่แสงเรืองรองอบอุ่นหายไป คุณเห็นการ์ดใบหนึ่งที่มีภาพวาดของคนไม้ขีดสามคน: คุณ, ราโมน่าผมเงิน, โอเกียร์ผมทอง ข้างๆ ยังมีข้อความหนึ่งบรรทัด。\n「ขอบคุณพวกคุณ!」"
  },
  Event_6886_Name = {
    Text = "ของขวัญแห่งความดี"
  },
  Event_6887_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6887_Desc = {
    Text = "ร่างกายของคุณหลบหนีจากฝูงผีเสื้อ แต่พวกมันไม่สูญเสียเป้าหมายของตัวเอง ขึ้นไปในกระเป๋าถือของคุณ และดูดดื่มน้ำหมึกจากเครื่องพิมพ์ดีดอย่างโลภ。"
  },
  Event_6887_Name = {
    Text = "การพุ่งพล่านของความหลงผิด"
  },
  Event_6888_ChoiceDesc1 = {
    Text = "【ชี้ให้เห็นข้อผิดพลาด】เลือก 1 ใบการ์ดคำสั่งเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6888_ChoiceDesc2 = {
    Text = "【หลังจากฟังการบรรเลง】ทุกครั้งที่มีร่างกายที่ตื่นขึ้นที่มีค่าความคลั่ง 50 ขึ้นไป จะได้รับ 15 รอยดำ"
  },
  Event_6888_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_6888_Desc = {
    Text = "เด็กชายหุ่นขี้ผึ้งนั่งอยู่หน้เปียโนเล่นบทฝึกซ้อม。\nครูของเขา——ซึ่งเป็นหุ่นขี้ผึ้งเช่นกัน กำลังให้คำแนะนำอยู่ข้างๆ。\n133，355，244……\nผิดแล้ว ทุกโน้ตผิดหมด。"
  },
  Event_6888_Name = {
    Text = "บทเรียนเปียโน"
  },
  Event_6889_ChoiceDesc1 = {
    Text = "【ยอมแพ้ต่อสู้】ลบการ์ดคำสั่ง 1 ใบ ได้รับ Arg1 รอยดำ"
  },
  Event_6889_ChoiceDesc2 = {
    Text = "【ดึงมือกลับ】"
  },
  Event_6889_Desc = {
    Text = "คุณไม่สามารถต้านทานแรงกระตุ้นในใจได้ \nปลายนิ้วเหมือนกับเด็กที่หลงทางในป่า กำลังเดินเล่นและเล่นสนุกอยู่บนแป้นพิมพ์…… \nค่อยๆ มีผีเสื้อบินออกมาจากเครื่องพิมพ์ดีด \nหนึ่งตัว สองตัว สามตัว…… \nบนใบหน้า บนปลายนิ้ว กลุ่มผีเสื้อเหมือนกับดอกไม้ไฟที่บานสะพรั่งอยู่ในอากาศ เปล่งประกายแสงเหมือนอัญมณีในความมืด \nเครื่องพิมพ์ดีดนี้ไม่มีประโยชน์ใช้สอยใดๆ แต่กลับเชี่ยวชาญในการสร้างสรรค์ความงาม。"
  },
  Event_6889_Name = {
    Text = "แรงบันดาลใจพุ่งพล่าน"
  },
  Event_6890_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6890_Desc = {
    Text = "คุณยกเอกสารขึ้นใต้แสงไฟแดงเข้ม หวั่นว่าจะพลาดรายละเอียดใดๆ \n นี่คือรายงานผลการตรวจสุขภาพ ผู้ที่ถูกตรวจคือคุณเมสัน \n 「น้ำหนัก 40 กก. ความเข้มข้นของออกซิเจนในเลือดปกติ อัตราการประสาน 30% การสะท้อน...」 \n คุณยังอยากดูต่อไป แต่ตัวอักษรก็ค่อยๆ หายไป \n สะอาดเหมือนไม่มีอะไรเกิดขึ้น。"
  },
  Event_6890_Name = {
    Text = "เครื่องพิมพ์ดีด"
  },
  Event_6891_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6891_Desc = {
    Text = "ใช่แล้ว คุณไม่ได้หนีไป คุณกำลังไล่ตามเป้าหมายที่แน่นอน—สุนัขแห่งนรกที่วิ่งไปมาท่ามกลางซอยแคบๆ ที่ชื้นแฉะและมีหิมะตก คุณจะไม่ลืมเรื่องนี้ เหมือนกับที่คุณจะไม่ลืมใบหน้าของคนที่ดึงคุณขึ้นจากซากปรักหักพังในวันนั้นที่ตงกุส... ใครกันนะ?"
  },
  Event_6891_Name = {
    Text = "วิ่ง"
  },
  Event_6892_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6892_Desc = {
    Text = "ในพื้นที่นอกเหนือจากเขตแยกตัวนี้ สิ่งเดียวที่คุณพึ่งพาได้คือตัวคุณเอง"
  },
  Event_6892_Name = {
    Text = "ผู้เดินฝันร้าย"
  },
  Event_6893_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6893_Desc = {
    Text = "วิกฤตและความเสี่ยงอยู่เคียงข้างกัน ในช่วงขณะที่สัมผัสกับล็อกเหล็กของเหลวกัดกร่อนทำให้ฝ่ามือของคุณเจ็บปวด หวังว่าเรลิกที่อยู่หลังประตูจะมีคุณค่า。"
  },
  Event_6893_Name = {
    Text = "หลังประตูเหล็ก"
  },
  Event_6894_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6894_Desc = {
    Text = "ในโลกที่ยังไม่เคยสัมผัส คุณพุ่งชนไปมา จิตใจที่ไม่มั่นคงของคุณยังไม่ถอยหลังไปถึงจุดที่สูญเสียสติ \nความน่ากลัวของสิ่งที่ไม่รู้จัก คุณเห็นด้วยอย่างลึกซึ้ง。"
  },
  Event_6894_Name = {
    Text = "ผู้เดินฝันร้าย"
  },
  Event_6895_ChoiceDesc1 = {
    Text = "【ตะโกนดัง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6895_ChoiceDesc2 = {
    Text = "【สัมผัสความเงียบ】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」ได้รับผลกระทบ「(Skill.Arg2)」, 「(Skill.Arg3)」"
  },
  Event_6895_ChoiceDesc3 = {
    Text = "【ผุดขึ้น】ได้รับ 25 รอยดำ"
  },
  Event_6895_Desc = {
    Text = "คุณได้ยินความเงียบ \n ความเงียบที่ถูกขยายออกมา เหมือนเสียงคลื่นทะเลที่เติมเต็มทั้งพื้นที่ \n\n คุณเงยหน้าขึ้น เหมือนจุดเล็กๆ ที่จ้องมองท้องฟ้าที่เต็มไปด้วยดาว。"
  },
  Event_6895_Name = {
    Text = "น้ำแห่งอดีต"
  },
  Event_6896_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6896_Desc = {
    Text = "คุณตั้งใจฟังเสียง และตามหาที่มาของเสียง พยายามที่จะจับคนร้ายที่ก่อกวนนี้ \n แต่เหมือนกับว่ามีเจตนาล้อเล่น เมื่อคุณคิดว่ากดดันคนให้จนมุมแล้ว มักจะชนกับกำแพงที่วนเวียนกลับมา คุณกลับมายังจุดเดิมอีกครั้ง \n คุณรู้สึกท้อแท้เตะที่กำแพงอิฐ แต่กลับมีอิฐหลุดออกจากกำแพง และมีช่องว่างที่ซ่อนเร้นแวววับอยู่ในกำแพง。"
  },
  Event_6896_Name = {
    Text = "เส้นทางเสียงลึกลับ"
  },
  Event_6897_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6897_Desc = {
    Text = "ต้องเป็นปัญหาที่การเล่นเพลง แน่นอนว่าต้องเป็นแบบนี้ \n คุณไม่เชื่อในโชคชะตา จึงหมุนกลับเข็มเสียงและอดทนฟังเสียงดนตรีที่ไม่พึงประสงค์ในช่วงแรกอย่างยากลำบาก แต่เสียงเคาะที่อยู่ในความทรงจำกลับไม่ดังขึ้น \n ข้างหลังคุณที่ว่างเปล่า เงาดำน้อยๆ บนพื้นกำลังเลื่อนออกไปอย่างเงียบๆ。"
  },
  Event_6897_Name = {
    Text = "เส้นทางเสียงลึกลับ"
  },
  Event_6898_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6898_Desc = {
    Text = "คุณไม่ได้อยู่คนเดียว ความลับที่เคาะต้องซ่อนอยู่ภายในกลไกของเครื่องเล่นแผ่นเสียง\n ด้วยความมั่นใจในความสามารถในการตัดสินใจของตัวเอง คุณจึงถอดเครื่องเล่นแผ่นเสียงเก่าออก\n นอกจากชิ้นส่วนโลหะที่เกิดการผุกร่อนภายในและฝุ่นหนาๆ คุณไม่ได้พบอะไรเลย\n มีเพียงเสียงหัวเราะเบาๆ ที่กระจายอยู่ในหมอก ดูเบาเหมือนอยู่ในความฝัน"
  },
  Event_6898_Name = {
    Text = "เส้นทางเสียงลึกลับ"
  },
  Event_6899_ChoiceDesc1 = {
    Text = "【สารสีขาวของคนโง่】ฟื้นฟู Arg1 จุดชีวิต"
  },
  Event_6899_ChoiceDesc2 = {
    Text = "【หัวใจของคนบ้า】การ์ดคำสั่งแบบสุ่มหนึ่งใบได้รับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_6899_ChoiceDesc3 = {
    Text = "【ปฏิเสธรับประทาน】รับ 25 รอยดำ"
  },
  Event_6899_Desc = {
    Text = "「เนื้อขาวของคนโง่มีรสชาติอร่อยเหมือนซุปปลาที่ต้มเดือด ขณะที่หัวใจของคนบ้าถูกอบจนกลายเป็นสกอนที่ร้อนและมีเลือดไหลออกมา。」\nเงาดำยิ้มเหี้ยมเกรียม ส่งจานอาหารที่มีวัตถุดิบที่ไม่รู้จักมาให้คุณ.\nคุณสูดหายใจเข้าลึก กลิ่นหอมที่ลอยออกมาพุ่งเข้าจมูกของคุณอย่างบ้าคลั่ง ต่อมสร้างน้ำลายที่ไม่เคยมีศักดิ์ศรีของคุณยอมแพ้ก่อน ในขณะที่กระเพาะและลำไส้ของคุณเกิดอาการชักอย่างน่าสงสาร ส่งเสียงครวญครางที่เต็มไปด้วยความต้องการ。"
  },
  Event_6899_Name = {
    Text = "การเฉลิมฉลองของร่างกาย"
  },
  Event_6900_ChoiceDesc1 = {
    Text = "【สัมผัสกระดิ่งลม】ได้รับผลกระทบ「(Skill.Arg1)」，การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg2)」"
  },
  Event_6900_ChoiceDesc2 = {
    Text = "【สังเกตกระดิ่งลม】ติดเชื้อ「(Skill.Arg1)」, การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg2)」"
  },
  Event_6900_ChoiceDesc3 = {
    Text = "【ไม่ทำอะไรเลย】การ์ดคำสั่งแบบสุ่มใบหนึ่งได้รับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_6900_Desc = {
    Text = "ติ๊งติ๊ง ติ๊งติ๊ง...\nนี่คือกระดิ่งลมที่ขึ้นสนิม เสียงดนตรีที่ไม่คล่องแคล่วล่องลอยออกมาจากช่องว่าง"
  },
  Event_6900_Name = {
    Text = "ระฆังลมสนิม"
  },
  Event_6901_ChoiceDesc1 = {
    Text = "【เฝ้าดูอย่างรอบคอบ】พยายามอยู่รอด"
  },
  Event_6901_ChoiceDesc2 = {
    Text = "【แกว่งอาวุธ】พยายามหาทางออกไป"
  },
  Event_6901_ChoiceDesc3 = {
    Text = "【คว้ามือ】ได้รับ 25 รอยดำ"
  },
  Event_6901_Desc = {
    Text = "พื้นดินใต้เท้าของคุณจู่ๆ ก็เกิดเป็นหนองน้ำสีดำ มีมือไม่นับไม่ถ้วนพุ่งออกมาจากนั้น \n มือเหล่านั้นมีสีผิว รูปแบบ และลวดลายที่หลากหลาย สีเขียวอมฟ้า มีเกล็ด และมีตา ดูเหมือนมาจากมิติและอวกาศนับไม่ถ้วน กำลังพยายามดึงคนโชคร้ายคนถัดไปเข้าสู่ครอบครัวใหญ่ของพวกมัน \n คุณตัดสินใจ——"
  },
  Event_6901_Name = {
    Text = "บึงมืด"
  },
  Event_6902_ChoiceDesc1 = {
    Text = "【กดปุ่มนี้ค้างไว้】สุ่มการ์ดคำสั่ง 3 ใบจากกองการ์ด เลือก 1 ใบเพื่อทำการคัดลอก"
  },
  Event_6902_ChoiceDesc2 = {
    Text = "【เขย่าดูสักหน่อย】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6902_ChoiceDesc3 = {
    Text = "【ไม่ทำอะไร】ได้รับ 25 รอยดำ"
  },
  Event_6902_Desc = {
    Text = "ติ๊งติ๊ง ติ๊งติ๊ง...\nนี่คือกระดิ่งลมที่ขึ้นสนิม เสียงดนตรีที่ไม่คล่องแคล่วล่องลอยออกมาจากช่องว่าง"
  },
  Event_6902_Name = {
    Text = "ระฆังลมเล็กๆ"
  },
  Event_6903_ChoiceDesc1 = {
    Text = "【โต้กลับพวกมัน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，เลือกติดเชื้ออาการ 1 ครั้ง"
  },
  Event_6903_ChoiceDesc2 = {
    Text = "【เห็นด้วยกับพวกมัน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6903_ChoiceDesc3 = {
    Text = "【เสนอแนวคิดใหม่】ได้รับ 25 รอยดำ"
  },
  Event_6903_Desc = {
    Text = "「กรุณารักษาระยะห่างกับพวกเรา」\nหนูจำนวนมากล้อมรอบคุณอยู่ตรงกลาง โดยรักษาระยะห่างอย่างน้อยห้าฟุต\n「พวกเราพยายามสืบพันธุ์ พวกเราผลิดอกออกผล พวกเราไม่เลือกกิน—ดังนั้นเราจึงนำโรค ความวิตกกังวล และความทุกข์มาให้มนุษย์」\n「พวกเรากับมนุษย์ไม่ควรเข้าใกล้กันเกินไป ที่นี่ไม่ใช่ที่ที่คุณควรมา」\nเพื่อทำให้หนูเหล่านั้นผ่อนคลายคุณจึงตัดสินใจ—"
  },
  Event_6903_Name = {
    Text = "พิษระบาด"
  },
  Event_6904_ChoiceDesc1 = {
    Text = "【ตกลงไปเรื่อยๆ】ติดเชื้อ「(Skill.Arg1)」，คุณต้องการตกลงไปอีกหรือไม่"
  },
  Event_6904_ChoiceDesc2 = {
    Text = "【ถอนตัวออก】ได้รับ 25 รอยดำ"
  },
  Event_6904_Desc = {
    Text = "「คุณ」กำลังเชิญชวนคุณอยู่.\nในความลึกของเกลียวลม อดีตและอนาคตของ「คุณ」ได้ส่งมอบ「ของขวัญ」จากมิติที่แตกต่างกันมาให้คุณ."
  },
  Event_6904_Name = {
    Text = "เหววน"
  },
  Event_6905_ChoiceDesc1 = {
    Text = "【กดค้างที่นกอีกา】ได้รับ 40 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_6905_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】ได้รับ 25 รอยดำ，แล้วจากไป"
  },
  Event_6905_Desc = {
    Text = "อีกาที่โดดเดี่ยวส่งเสียงแหบพร่า ดึงขนสีดำของตัวเองออกทีละเส้น \n มันเจ็บจนตัวสั่น ร้องตะโกนเสียงสูง แต่ก็หยุดการเคลื่อนไหวที่เร็วขึ้นเรื่อยๆ ไม่ได้ \n「ก๊า——ก๊า——」 \n น้ำตาสีน้ำเงินที่มีน้ำดำไหลออกจากตาของมัน นอกจากคุณ ไม่มีใครได้เห็น。"
  },
  Event_6905_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_6906_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6906_Desc = {
    Text = "สีแดง เต็มไปด้วยความร้อนแรง ความมีชีวิตชีวา และความงดงาม ฉันบังเอิญรู้จักสาวสวยคนหนึ่งเช่นนั้น ในไม่ช้าคุณจะได้พบเธอแน่นอน \n แล้วการเลือกครั้งถัดไปของคุณคืออะไร?"
  },
  Event_6906_Name = {
    Text = "การแสดงกำลังเริ่มต้น"
  },
  Event_6907_ChoiceDesc1 = {
    Text = "【เสียงเชียร์ดัง】"
  },
  Event_6907_ChoiceDesc2 = {
    Text = "【ง่วงนอน】"
  },
  Event_6907_Desc = {
    Text = "คุณฝันไปนานมาก \n ในความฝัน คุณนั่งอยู่ในที่นั่งผู้ชม มองดูเด็กชายที่ร้องเพลงบนเวที \n「ลุงชาร์ลีมีแมวขนลายที่เขารักมาก ๆ \n เมื่อเธอหายไปโดยไม่มีสาเหตุ เขาจึงออกตามหา」\n…… \n เสียงที่แห้งแล้งและว่างเปล่าซ้ำไปซ้ำมาอย่างไร้จุดหมายและไม่มีที่สิ้นสุด……"
  },
  Event_6907_Name = {
    Text = "พิธีปิดฉาก Ⅳ"
  },
  Event_6908_ChoiceDesc1 = {
    Text = "【คลี่คลายกิ่งก้านด้านบน】"
  },
  Event_6908_ChoiceDesc2 = {
    Text = "【คลี่คลายกิ่งก้านด้านล่าง】"
  },
  Event_6908_Desc = {
    Text = "ความรู้ทางจิตวิญญาณที่เหลืออยู่ในดินแดนลับแลเชื่อมโยงกันและกัน สร้างความไม่เสถียรของสนามพลังงานขึ้นมา。\nบางที คุณอาจสามารถคลายบ่วงรัดของจิตวิญญาณ เพื่อจัดระเบียบเส้นทางไปข้างหน้าของคุณได้。"
  },
  Event_6908_Name = {
    Text = "ทางที่พันกัน"
  },
  Event_6909_ChoiceDesc1 = {
    Text = "【ออกจาก】เลือกการตื่นรู้ 2 ร่าง"
  },
  Event_6909_Desc = {
    Text = "คุณลุกขึ้นแล้ววิ่งไปที่ประตูทันที。\n 「คุณเปิดผ้าคลุมออก...\n ความลับ คุณค้นพบความลับ...」\n เสียงคลื่นรวมตัวกันเป็นมหาสมุทรที่วุ่นวาย พื้นสั่นสะเทือนอย่างรุนแรงในความสั่นสะเทือนที่น่ากลัว。\n คุณไม่กล้าหันหลังหนีไปอย่างรวดเร็วที่สุด。"
  },
  Event_6909_Name = {
    Text = "พิธีจงมู่หลี่Ⅴ"
  },
  Event_6910_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6910_Desc = {
    Text = "คุณไม่ต่อต้าน และแน่นอนว่าคุณก็ไม่เลือกที่จะจมอยู่ในความหลัง"
  },
  Event_6910_Name = {
    Text = "ลูกลูกในกะโหลก"
  },
  Event_6911_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6911_Desc = {
    Text = "คุณไม่ต่อต้านอีกต่อไป ปล่อยให้ความสกปรกกลืนกินร่างกายและจิตใจ หลังจากหลับใหลอย่างยาวนาน แสงสีเงินตกลงมาอยู่ในมือที่คุณจับไว้。"
  },
  Event_6911_Name = {
    Text = "ลูกลูกในกะโหลก"
  },
  Event_6912_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6912_Desc = {
    Text = "ยิ่งดิ้นรนมากเท่าไหร่ ความสกปรกในสมองก็จะยิ่งลึกลงไปเท่านั้น และในส่วนลึกที่สุดของสมองที่เต็มไปด้วยบาปนั้น มีของขวัญที่ไม่รู้ที่มาซ่อนอยู่。"
  },
  Event_6912_Name = {
    Text = "ลูกลูกในกะโหลก"
  },
  Event_6913_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6913_Desc = {
    Text = "เมื่อตาข่ายแตก มีบางสิ่งผ่านเข้ามาในความคิดของคุณแวบหนึ่ง คล้ายกับใบหน้าที่ยิ้มแย้มของเด็กๆ หลายคน"
  },
  Event_6913_Name = {
    Text = "เครือข่ายหลงทาง"
  },
  Event_6914_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_6914_Desc = {
    Text = "แมวพยักหน้าด้วยความพึงพอใจ จากนั้นก็กลายเป็นเงาและหายไปในที่เดิม ทิ้งวัตถุทรงกลมสีดำไว้บางชิ้น"
  },
  Event_6914_Name = {
    Text = "ผู้อยู่อาศัยที่เดินทาง"
  },
  Event_6915_ChoiceDesc1 = {
    Text = "【อ่านจดหมาย】ลบการ์ดคำสั่ง 1 ใบ ได้รับ Arg1 รอยดำ"
  },
  Event_6915_ChoiceDesc2 = {
    Text = "【ปิดกล่องให้ดี】"
  },
  Event_6915_Desc = {
    Text = "กระดาษจดหมายที่ปลิวว่อนปกคลุมทั่วท้องฟ้า ดูเหมือนการเร่งรัดอย่างเงียบงัน"
  },
  Event_6915_Name = {
    Text = "จดหมายไม่ทันรู้เรื่อง"
  },
  Event_6916_ChoiceDesc1 = {
    Text = "【เข้า】ผ่านหมอก ไปสู่ปลายทางอีกด้าน。"
  },
  Event_6916_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_6916_Desc = {
    Text = "บนถนนข้างหน้าปรากฏอุโมงค์ลับ อุโมงค์นั้นเต็มไปด้วยหมอกดำ และไม่มีใครรู้ว่ามันนำไปสู่ที่ใด"
  },
  Event_6916_Name = {
    Text = "อุโมงค์"
  },
  Event_6917_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6917_Desc = {
    Text = "คุณตัดสินใจที่จะสิ้นสุดความทุกข์ของมัน จึงยื่นมือไปจับร่างอ่อนนุ่มของมัน บีบแน่นขึ้น แล้วบีบแน่นขึ้นอีก...\nมันดิ้นรนอย่างสิ้นหวังในฝ่ามือของคุณ สุดท้ายก็ระเบิดกลายเป็นน้ำอุ่น ๆ。"
  },
  Event_6917_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_6918_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6918_Desc = {
    Text = "ไม่ต้องกังวล นี่เป็นเพียงความทรงจำของผู้อื่นที่แตกสลายในมิติ คุณมีเงา แค่เงาที่อยู่ในนั้น คนที่อยู่ในเงานั้นยังเป็นคุณจริงๆ หรือเปล่า?"
  },
  Event_6918_Name = {
    Text = "ชิ้นส่วนความทรงจำ·เบียร์"
  },
  Event_6919_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6919_Desc = {
    Text = "คุณใช้แรงดึงจงอยปากแหลมของอีกาที่พยายามกัดขนของมัน แต่เจ้ามันกลับไม่ยอมแพ้ บิดตัวไปมา แรงของมันมากถึงขนาดทำให้กระดูกของคุณสั่นสะเทือนดังกร๊อบแก๊บ \n ใบหน้าของคุณแดงก่ำ เต็มไปด้วยความพยายาม จนในที่สุดคุณก็สามารถควบคุมร่างกายของอีกาได้ หยุดการกระทำที่บ้าคลั่งของมัน \n ขณะที่คุณถอนหายใจด้วยความโล่งอก คอของอีกาที่เกือบจะไม่มีขนแล้วก็พลิกกลับอย่างแรง ร่างของมันอ่อนแรงลงและกลายเป็นน้ำดำข้นในมือของคุณ。"
  },
  Event_6919_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_6920_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6920_Desc = {
    Text = "คุณเพิกเฉยต่อเสียงระฆังที่เต็มไปด้วยความสิ้นหวังอย่างไม่ใส่ใจ \n แม้ว่าในอีกวินาทีหนึ่งคุณอาจถูกระเบิดกลับไปยังโลกดั้งเดิม แม้ว่าอุดมการณ์ที่ยิ่งใหญ่ของคุณจะต้องถูกฝังร่วมกัน \n โทรศัพท์ที่ไม่ควรรับ ก็คือไม่ควรรับ \n คุณรู้ดีถึงความจริงที่เรียบง่ายนี้。"
  },
  Event_6920_Name = {
    Text = "กรุณารับโทรศัพท์"
  },
  Event_6921_ChoiceDesc1 = {
    Text = "【ก้มลงมอง】ได้รับ 25 รอยดำ"
  },
  Event_6921_ChoiceDesc2 = {
    Text = "【ฉันจะต้องหาให้เจอโดยเร็ว】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_6921_Desc = {
    Text = "คุณวิ่งตามเงาดำไปข้างหน้า จู่ๆ ก็เหยียบเข้าไปในน้ำตื้น ของเหลวที่มองไม่เห็นสีท่วมถึงพื้นรองเท้า ส่งผ่านความเย็นเยียบเล็กน้อย \n เสียงหนึ่งในน้ำพูดว่า:「คุณจะไม่อยากพบเจอ」"
  },
  Event_6921_Name = {
    Text = "คุณจะไม่อยากพบเจอ"
  },
  Event_6922_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6922_Desc = {
    Text = "ทางเลือกที่ปลอดภัย。"
  },
  Event_6922_Name = {
    Text = "หลังกองฟาง"
  },
  Event_6923_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ Arg1 รอยดำ ติดเชื้อ「(Skill.Arg2)」 โปรดเลือกต่อ"
  },
  Event_6923_ChoiceDesc2 = {
    Text = "【ละเลย】ได้รับรอยดำ 25，แล้วจากไป"
  },
  Event_6923_Desc = {
    Text = "ในห้องของสถานพักฟื้นทำไมถึงมีอีกา? \n แต่คุณได้ยินเสียงหัวเราะที่น่าสยดสยองของอีกาจริง ๆ ในเงามืดมีอำนาจบางอย่างที่ยังไม่ขึ้นเวที กำลังมองคุณจากดวงตาที่ว่างเปล่าของนกเหล่านั้น สิ่งมีชีวิตสีดำสนิทเหล่านั้นบิดคอ ยืนอยู่บนโคมไฟที่ปากซอย มองคุณด้วยสายตาที่เต็มไปด้วยความชั่วร้าย หัวที่เหมือนเงานั้นดูเหมือนจะแบ่งปันร่างเดียวกันที่จมอยู่ในเมือก D。"
  },
  Event_6923_Name = {
    Text = "โคมไฟหงส์ดำ"
  },
  Event_6924_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6924_Desc = {
    Text = "อย่ากลัวสิ่งสกปรก เพราะสิ่งที่คุณได้รับจากมันลึกซึ้งกว่าสิ่งที่คุณสูญเสีย"
  },
  Event_6924_Name = {
    Text = "หลังกองฟาง"
  },
  Event_6925_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6925_Desc = {
    Text = "พายุแห่งความรู้ทางจิตวิญญาณล้อมรอบตูรูไว้ คุณสบตาเขาแวบหนึ่ง ก่อนจะตามกันเข้าไปในเงามืดทีละก้าว"
  },
  Event_6925_Name = {
    Text = "คำสัญญาของผู้แทน"
  },
  Event_6926_ChoiceDesc1 = {
    Text = "【เข้า】ผ่านหมอก ไปสู่ปลายทางอีกด้าน。"
  },
  Event_6926_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_6926_Desc = {
    Text = "คุณตกลงไปในความมืด \n ที่ปลายสายตาของคุณ มีเพียงแสงเล็กๆ ที่ส่องออกมาจากรอยแยกที่แคบเหมือนรูของกุญแจ \n กุญแจเงินปล่อยแสงเรืองน้อยๆ เหมือนการหายใจ นำทางคุณให้ก้าวเข้าสู่ทางลับนั้น。"
  },
  Event_6926_Name = {
    Text = "ทางลับเดี่ยว"
  },
  Event_6927_ChoiceDesc1 = {
    Text = "【ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้าง：「(RelicConfig.Arg2)」】"
  },
  Event_6927_ChoiceDesc2 = {
    Text = "【เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」】"
  },
  Event_6927_Desc = {
    Text = "เหตุการณ์203 (กำลังพัฒนา), ยังไม่ใช่เวอร์ชันสุดท้าย"
  },
  Event_6927_Name = {
    Text = "เหตุการณ์ 203（กำลังพัฒนา）"
  },
  Event_6928_ChoiceDesc1 = {
    Text = "【การรวม】ลบการ์ดคำสั่ง 1 ใบ และรับสิ่งสร้าง：「(RelicConfig.Arg1)」"
  },
  Event_6928_ChoiceDesc2 = {
    Text = "【ลูบ】ลบการ์ดโจมตี/การ์ดป้องกันหนึ่งใบ ได้รับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_6928_ChoiceDesc3 = {
    Text = "【ขยะแขยง】ได้รับ 25 รอยดำ"
  },
  Event_6928_Desc = {
    Text = "「คุณชอบร่างที่บกพร่องของฉันไหม? ถ้าเป็นไปได้ ช่วยประกอบร่างกายให้ฉันหน่อยได้ไหม?」\nรูปปั้นปูนปลาสเตอร์ที่เหลือเพียงครึ่งตัวเคลื่อนไหวริมฝีปาก เสียงอันอ่อนหวานเหมือนผ้าละเอียดที่ร่วงหล่นข้างหู หลั่งไหลออกมาจากริมฝีปากที่ควรจะเย็นเฉียบและแข็งแกร่งของเธอ。"
  },
  Event_6928_Name = {
    Text = "ประกอบซาก"
  },
  Event_6929_ChoiceDesc1 = {
    Text = "【ทิ้งซองจดหมาย】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก : 「(EnchantConfig.Arg1)」"
  },
  Event_6929_ChoiceDesc2 = {
    Text = "【ใส่เข้าไปในอก】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้าง：「(RelicConfig.Arg2)」"
  },
  Event_6929_Desc = {
    Text = "นี่คือจดหมายขอความช่วยเหลือ ผู้เขียนพยายามอย่างยิ่งที่จะรักษาความสงบ แต่ลายมือที่เอียงซึ่งบางครั้งกลับทำให้ความกลัวที่ซ่อนอยู่ของเขาเผยออกมาอย่างไม่ต้องสงสัย \n「สิ่งนี้ทั้งหมดเกินความคาดหมายของฉันไปโดยสิ้นเชิง หากตอนนี้มีใครพูดว่าฉันถูกคำสาป ฉันสาบานว่าฉันจะเชื่ออย่างไม่มีข้อสงสัย」\n「มีคนบอกว่าฉันเป็นคนบ้า เขาพูดถูกแค่ครึ่งเดียว ฉันกำลังอยู่บนขอบของความบ้า」\n「แต่ฉันเห็นมันจริงๆ! มันกำลังเปลี่ยนแปลงและสลายไป วัตถุดำที่หนืดเหนียวกำลังพยายามปีนขึ้นไปทั่วร่างกายของฉัน!」\n「ฉันหนีไปแล้ว! หนีอย่างรวดเร็ว แต่สายตาที่จ้องมองไม่เคยละจากตัวฉัน ฉันมีลางสังหรณ์ว่ามันจะต้องตามหาฉันแน่! โคลนดำที่น่าสะอิดสะเอียนนั้นจะกลับเข้ามาในกะโหลกของฉันอีกครั้ง ไม่ว่าสิ่งใดจะได้รับจดหมายนี้ ขอร้องเธอ ช่วยฉันด้วย——」"
  },
  Event_6929_Name = {
    Text = "จดหมายขอความช่วยเหลือ"
  },
  Event_6930_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6930_Desc = {
    Text = "「ใจเย็นๆ」ราโมน่าตบที่หัวคุณ，「แค่เศษเสี้ยวของอดีต ไม่รู้ว่าใครทิ้งไว้ในช่องทางมิตินี้。」\nจริงๆ แล้ว มันมีกลิ่นอายของความคิดถึง。"
  },
  Event_6930_Name = {
    Text = "การสื่อสารฉุกเฉิน"
  },
  Event_6931_ChoiceDesc1 = {
    Text = "【การ์ดคำสั่งแบบสุ่ม 1 ใบได้รับการแกะสลัก 「(EnchantConfig.Arg1)」】"
  },
  Event_6931_ChoiceDesc2 = {
    Text = "【การ์ดคำสั่งแบบสุ่ม 1 ใบได้รับการแกะสลัก 「(EnchantConfig.Arg1)」】"
  },
  Event_6931_ChoiceDesc3 = {
    Text = "【การ์ดคำสั่งแบบสุ่ม 1 ใบได้รับการแกะสลัก 「(EnchantConfig.Arg1)」】"
  },
  Event_6931_Desc = {
    Text = "เหตุการณ์ 205 (ในระหว่างการพัฒนา)，ไม่ใช่ผลสุดท้าย"
  },
  Event_6931_Name = {
    Text = "เหตุการณ์ 205 (ในระหว่างการพัฒนา)"
  },
  Event_6932_ChoiceDesc1 = {
    Text = "【ได้รับสิ่งสร้าง：(「(RelicConfig.Arg1)」】"
  },
  Event_6932_ChoiceDesc2 = {
    Text = "【ได้รับสิ่งสร้าง：(「(RelicConfig.Arg1)」】"
  },
  Event_6932_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_6932_Desc = {
    Text = "เหตุการณ์ 204 (อยู่ระหว่างการพัฒนา)，ไม่ใช่ผลสุดท้าย"
  },
  Event_6932_Name = {
    Text = "เหตุการณ์204 (กำลังพัฒนา)"
  },
  Event_6933_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6933_Desc = {
    Text = "ดวงจันทร์อันโดดเดี่ยวแขวนอยู่บนท้องฟ้า แต่คุณสามารถได้ยินคำสวดอันอวยพรจากมันได้ ท่วงทำนองที่แปลกประหลาด คล้ายเสียงซุบซิบอันน่ารังเกียจ\nคำสวดหยุดลง ขณะที่คุณกำลังจะจากไป ด้านหลังกลับปรากฏเงาสีขาว\n「ผู้ที่จ้องมองชะตากรรมและหมิ่นประมาทการอวยพร จะได้รับทั้งพรและราคาที่ต้องจ่ายตามสัญญา」"
  },
  Event_6933_Name = {
    Text = "ชิ้นส่วนดวงจันทร์เงิน"
  },
  Event_6934_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6934_Desc = {
    Text = "ด้านหลังดังขึ้นด้วยเสียงแตกที่ใสกังวาน คุณหยุดคิดสักครู่ ก่อนจะหันหลังแล้วจากไป"
  },
  Event_6934_Name = {
    Text = "ชิ้นส่วนดวงจันทร์เงิน"
  },
  Event_6935_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6935_Desc = {
    Text = "แสงจันทร์ที่ถูกอุ้มนิ้วมือหนึ่งถูกโปรยลงบนหลุมศพ\nมีคนถูกฝังอยู่ใต้โคลนหนาแน่น กลุ่มคนที่มองอยู่กล่าวว่า บุคคลนี้ได้พบกับการตายตามธรรมชาติ และจะได้หลับใหลอยู่ใต้ดิน\nแต่โคลนที่ถูกฝังนั้นกลับเคลื่อนไหว ในเสียงกรีดร้อง กลับมีดวงจันทร์ที่อ่อนแรงปีนออกมา。"
  },
  Event_6935_Name = {
    Text = "ชิ้นส่วนดวงจันทร์เงิน"
  },
  Event_6936_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6936_Desc = {
    Text = "ก็แค่สิ่งมีชีวิตที่ดิ้นรนเพื่อเอาตัวรอด หวังหาเพียงไม้ลอยให้หยุดพัก...\nคุณถอนหายใจครั้งหนึ่ง ปล่อยให้ยางดำไหลจากปลายหางของผีเสื้อออกมา.。"
  },
  Event_6936_Name = {
    Text = "สิ่งที่ไม่ควรมีอยู่"
  },
  Event_6937_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6937_Desc = {
    Text = "นี่คือกับดักที่ถูกเปิดเผยล่วงหน้า และคุณรู้ดีถึงอันตรายของมัน。\nเมื่อเปรียบเทียบกับเครื่องประดับ ตัวคุณเอง—ชัดเจนว่าเป็นอัญมณีที่มีค่ามากกว่า。"
  },
  Event_6937_Name = {
    Text = "กลับกล้ามปีศาจ"
  },
  Event_6938_ChoiceDesc1 = {
    Text = "【ใส่กุญแจเงิน】"
  },
  Event_6938_Desc = {
    Text = "ดูเหมือนว่าเมือก D ที่อิ่มตัวเกินไปจะซ่อนสารบางอย่างไว้... ใช้กุญแจเงินในการสังเกต และเปลี่ยนมันเป็นพละกำลังของตนเองเถอะ。"
  },
  Event_6938_Name = {
    Text = "จุดแยก"
  },
  Event_6939_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6939_Desc = {
    Text = "คุณตอบรับคำขอ แต่ก็เจอปัญหาเล็กน้อย.\n「หุ่นขี้ผึ้งนั้น... เป็นยังไงบ้าง?」\n「นั่นคือร่างครึ่งของฉัน แน่นอนว่ามันเหมือนฉันเป๊ะๆ。」\n「แต่...」\n「ใบหน้าของท่าน มันเน่าเปื่อยไปหมดแล้ว ท่านไม่รู้เหรอ?」"
  },
  Event_6939_Name = {
    Text = "ร่างครึ่งของฉัน"
  },
  Event_6940_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6940_Desc = {
    Text = "คุณบีบมือของเพื่อนที่อยู่ข้างๆ อย่างแน่นหนา รามอน่าหันมามองคุณด้วยความสงสัย แต่สุดท้ายเธอก็ยอมรับความไม่สุภาพของคุณ。"
  },
  Event_6940_Name = {
    Text = "คำอธิษฐานแห่งความฝัน"
  },
  Event_6941_ChoiceDesc1 = {
    Text = "【ถามว่ามันคือใคร】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6941_ChoiceDesc2 = {
    Text = "【จ้องมองมัน】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น ได้รับผลกระทบจาก「(Skill.Arg1)」"
  },
  Event_6941_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_6941_Desc = {
    Text = "ความรู้สึกเหมือนถูกจ้องมองอย่างแรงทำให้คุณหยุดเดิน\n「ใครกัน?」 คุณมองไปในหมอกหนาทะลุทะลาย ，「เจนกินส์，เป็นคุณหรือเปล่า?」\nหมอกแสนเข้มข้น และเสียงกรีดร้องจากสิ่งที่หลอมละลายได้ดังลอยมาจากลานลึก คุณไม่พบอะไรเลยนอกจากต้องหันกลับมา และเกือบชนเข้ากับดวงตาที่ลอยอยู่กลางอากาศอันมืดมิด。"
  },
  Event_6941_Name = {
    Text = "มองอย่างบอด"
  },
  Event_6942_ChoiceDesc1 = {
    Text = "【ไม่แตะเหรียญ】การ์ดคำสั่งแบบสุ่ม 1 ใบได้รับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_6942_ChoiceDesc2 = {
    Text = "【แตะเหรียญ】เพิ่มพลังชีวิตสูงสุด Arg1 ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_6942_Desc = {
    Text = "คุณหยิบเหรียญโบราณที่ติดอยู่ในโคลนสีดำขึ้นมา \n ด้านหนึ่งแกะสลักเส้นเลือดสีแดงและสีเขียวอย่างประณีต อีกด้านหนึ่งมีภาพพิมพ์ของใบหน้าที่ขาวบริสุทธิ์—ดยุคสาวที่ไร้ที่ติยิ้มให้คุณ สายตาของเธอจ้องมองไปที่ลูกตาที่ซีดจางของคุณ เคลื่อนไหวในชั่วขณะ ก่อนที่จะเริ่มหมุนไปมาอย่างสับสน。"
  },
  Event_6942_Name = {
    Text = "เหรียญโบราณสองด้าน"
  },
  Event_6943_ChoiceDesc1 = {
    Text = "【หมุนตัว】ได้รับ 25 รอยดำ"
  },
  Event_6943_ChoiceDesc2 = {
    Text = "【เดินหน้าต่อ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6943_Desc = {
    Text = "เสียงฝีเท้านั้นกลับมาอีกครั้ง \n มันตามติดอยู่ด้านหลังคุณ จากห้องทำงานไปยังห้องของผู้ดูแล จากห้องของผู้ดูแลไปยังชั้นใต้ดิน \n คุณรู้ว่านั่นคือคนที่ระมัดระวัง \n เขารักษาระยะห่างระหว่างคุณสองคนอย่างระมัดระวัง ไม่ให้ไกลเกินไป แต่ก็ไม่ทำให้รู้สึกอึดอัด \n แต่คุณยังคงรู้สึกไม่สบายใจอย่างลึกซึ้ง。"
  },
  Event_6943_Name = {
    Text = "เสียงเท้า"
  },
  Event_6944_ChoiceDesc1 = {
    Text = "【ดูมัน】จะได้รับ 25 รอยดำ"
  },
  Event_6944_ChoiceDesc2 = {
    Text = "【ลูบมัน】50% โอกาสได้รับ 50 รอยดำ，50% โอกาสไม่ได้อะไรสักอย่าง"
  },
  Event_6944_Desc = {
    Text = "แมวสีดำตัวหนึ่งโผล่ออกมาจากตรอกอย่างกะทันหัน มันเข้ามาพันรอบขาของพวกคุณอย่างอบอุ่น ดวงตาแนวตั้งสีเขียวมรกตของมันกระพริบประกายที่ทำให้รู้สึกหนาวสั่น เหมือนกับว่ามันกำลังพูดว่า「อย่าไล่ตามเลย มาหาเล่นกับฉันสักพักเถอะ」\n「คุณได้เห็นพระองค์แล้ว พระองค์อยู่ข้างๆ คุณ เงาที่ถูกมลพิษบ้าคลั่งและหลงใหลเหล่านั้น... อย่ามองตรงไปที่รูปทรงของพระองค์」"
  },
  Event_6944_Name = {
    Text = "เอลฟ์แห่งราตรี"
  },
  Event_6945_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6945_Desc = {
    Text = "ร่างกายที่ตื่นขึ้นกำลังรอคอยคำสั่งของคุณ คุณไม่มีเวลาให้เสียไป"
  },
  Event_6945_Name = {
    Text = "จากมุม"
  },
  Event_6946_ChoiceDesc1 = {
    Text = "【ตรวจสอบฟิล์ม】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg2)」"
  },
  Event_6946_ChoiceDesc2 = {
    Text = "【ตรวจสอบกล้อง】ได้รับ 50 รอยดำ"
  },
  Event_6946_Desc = {
    Text = "เหมือนกับการดึงอวัยวะภายในออกมา ฟิล์มในท้องกล้องถูกฉีกขาดและทิ้งไว้ที่นี่อย่างไม่ใส่ใจ ไม่มีใครสนใจ \n แสงขาวจ้าส่องเข้ามา กล้องที่ถูกทิ้งไว้ที่มุมถนนเอียงไปมา ชัตเตอร์ถูกกดขึ้นโดยไม่มีเหตุผล \n 「คลิก——」\n สีหน้าที่ตกตะลึงและงุนงงของคุณถูกบันทึกไว้อย่างซื่อสัตย์บนฟิล์มในกล้อง.。"
  },
  Event_6946_Name = {
    Text = "บันทึกความบริสุทธิ์"
  },
  Event_6947_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6947_Desc = {
    Text = "แค่เสียงลมพัดสะบัดกุญแจเหล็กเท่านั้น ไม่มีอะไรต้องใส่ใจหรอก ปล่อยผ่านไปได้เลย"
  },
  Event_6947_Name = {
    Text = "หลังประตูเหล็ก"
  },
  Event_6948_ChoiceDesc1 = {
    Text = "【เลือก】ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6948_ChoiceDesc2 = {
    Text = "【เลือก】ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6948_ChoiceDesc3 = {
    Text = "【เลือก】ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6948_Desc = {
    Text = "「ฉัน」เป็นตัวของฉันเองที่ไม่เหมือนใคร ในจักรวาลนับล้าน ไม่มีใครเหมือนฉัน."
  },
  Event_6948_Name = {
    Text = "การสั่นสะเทือนของวิญญาณ"
  },
  Event_6949_ChoiceDesc1 = {
    Text = "【รับ】เลือกสิ่งสร้างเงิน 1 ชิ้น"
  },
  Event_6949_Desc = {
    Text = "นั่นอาจจะเป็น「ฉัน」。\nข้ามเงาเวลา ข้ามกำแพงมิติ ผ่านช่องว่างเล็กๆ เพื่อสบตา「ตัวฉันเอง」。"
  },
  Event_6949_Name = {
    Text = "การสั่นสะเทือนของวิญญาณ"
  },
  Event_6950_ChoiceDesc1 = {
    Text = "【ระบุปัญหา】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_6950_ChoiceDesc2 = {
    Text = "【กลืนความสงสัย】ติดเชื้อ「(Skill.Arg1)」, การแกะสลักใหม่, ยังสามารถทำได้อีก 1 ครั้ง"
  },
  Event_6950_Desc = {
    Text = "นี่เป็นเรื่องที่ไม่สามารถพูดออกมาได้สำหรับสาวน้อยคนนี้เช่นกัน \n คุณกลืนคำถามลงไป แต่เธอก็ลูบที่อกแล้วเล่าเรื่องราวของห้วงฝันอันยาวนานที่เกิดขึ้นเป็นเวลา 25 ปี พูดถึงความโดดเดี่ยวของเธอหลังจากตื่นจากความฝัน。"
  },
  Event_6950_Name = {
    Text = "ชีวิตที่ถูกกักขัง"
  },
  Event_6951_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6951_Desc = {
    Text = "คุณโยนกระดาษและเศษไม้ลงไปในเปลวไฟ เปลวไฟที่เต็มไปด้วยความโลภได้กลืนกินมันเข้าไปในท้อง และผงะออกมาด้วยความอิ่มหนำ มันเตรียมพร้อมที่จะไปล่มสลายโลกแล้ว ก่อนจากไปไม่ลืมที่จะให้พรแก่คุณสักนิด。"
  },
  Event_6951_Name = {
    Text = "ไฟสลัว"
  },
  Event_6952_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6952_Desc = {
    Text = "คุณเหยียบย่ำประกายไฟแห่งความแค้นที่เหลืออยู่โดยปราศจากความปรานี ความเกลียดชังและความไม่พอใจที่ลอยอยู่รอบๆ ดูเหมือนจะลดน้อยลง。"
  },
  Event_6952_Name = {
    Text = "ไฟสลัว"
  },
  Event_6953_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับรอยดำ Arg1 ส่งผลให้เกิดการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6953_ChoiceDesc2 = {
    Text = "【ละเว้น】ออก"
  },
  Event_6953_Desc = {
    Text = "คุณต้องการจับอีกา แต่มันกลับบินจากมุมห้องนอนด้านนี้ไปยังมุมห้องนอนด้านนั้น แล้วยังคงส่งเสียงร้องแปลกประหลาด อีกาที่บินจากไปทำให้เมือกสีดำที่หยดลงกลายเป็นรอยดำ。"
  },
  Event_6953_Name = {
    Text = "โคมไฟหงส์ดำ"
  },
  Event_6954_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，รับสถานะ「(Skill.Arg2)」"
  },
  Event_6954_Desc = {
    Text = "「คุณจับจุดสำคัญได้ดีมาก」ผู้ชายยิ้มแย้มกล่าว「นั่นคืออาหารที่อร่อยที่สุดในโลก คุ้มค่าที่จะให้ทุกคนที่เป็นทาออเทียดูแลอย่างระมัดระวังและลิ้มรสอย่างพิถีพิถัน」\n「น่าเสียดายที่ครั้งนี้ไม่สามารถให้คุณลองได้ สำหรับการชดเชย ฉันมีอาหารอร่อยอื่นๆ บนตัวฉัน ก็ให้คุณไปเถอะ」\nพูดจบ ผู้ชายก็โยนเนื้อสีแดงอ่อนนุ่มชิ้นหนึ่งลงไป เนื้ออ่อนนุ่มตกลงบนสะพานและหนวดเหนียวๆ ก็กระตุกไปมาอย่างบิดเบี้ยว เมื่อคุณเงยหน้าขึ้นไปมองอีกครั้ง รูปร่างของผู้ชายก็หายไปแล้วในความยุ่งเหยิงของโครงเหล็ก ไม่มีร่องรอยให้เห็น。"
  },
  Event_6954_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅵ"
  },
  Event_6955_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6955_Desc = {
    Text = "แกะรอบบางออกทีละชั้นอย่างเชี่ยวชาญ นี่คือความสามารถเด็ดของคุณ\nแวววับแห่งแรงบันดาลใจทำให้สมองปลอดโปร่งเป็นพิเศษ คุณสามารถมองเห็นความเป็นจริงของสถานการณ์ในตอนนี้ได้ชัดเจน——\nไม่ว่าจะเป็นใครที่อยู่เบื้องหลังในการบงการหุ่นเชิด ออกไปจากที่นี่ รอดชีวิตให้ได้。"
  },
  Event_6955_Name = {
    Text = "แรงบันดาลใจพุ่งพล่าน"
  },
  Event_6956_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6956_Desc = {
    Text = "ผีเสื้อแตกสลายอยู่ในฝ่ามือของคุณ ราวกับเพดานกระจกที่ถูกตีแตกอย่างรุนแรง เศษเสี้ยวที่แตกออกตกลงสู่แรงโน้มถ่วง ตกลง ตกลง——"
  },
  Event_6956_Name = {
    Text = "ภาพลวงตาทางรถไฟ"
  },
  Event_6957_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6957_Desc = {
    Text = "เห็นรามอน่าไม่ยอมเข้ามา แมวจึงส่ายหัวแล้วกลายเป็นเงาจางหายไป"
  },
  Event_6957_Name = {
    Text = "ผู้อยู่อาศัยที่เดินทาง"
  },
  Event_6958_ChoiceDesc1 = {
    Text = "【ให้คำมั่น】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6958_ChoiceDesc2 = {
    Text = "【ปฏิเสธ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6958_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_6958_Desc = {
    Text = "「นั่นเป็นความทรงจำที่ไม่อาจลืมเลือน。 \nหัวและแขนขาของฉันถูกกดลงไปในปูนอย่างแรง。\nความขาดอากาศและภาพหลอนแห่งความตายล้อมรอบฉันอย่างลึกซึ้ง และดึงฉันขึ้นอย่างรุนแรง ทิ้งฉันไว้ที่ชายฝั่งความมืด。\nฉันมองมัน รู้สึกว่ามีบางส่วนของตัวเองถูกพรากไปด้วย。 \nจิตวิญญาณอีกครึ่งที่หายไปนั้น ตั้งแต่นั้นมาก็อาศัยอยู่ในหุ่นขี้ผึ้งเล็กๆ ที่เริ่มต้น。 \nดังนั้น... คุณช่วยฉันหาร่างครึ่งของฉันได้ไหม?」"
  },
  Event_6958_Name = {
    Text = "ร่างครึ่งของฉัน"
  },
  Event_6959_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักขั้นสูง เลือก 1 จาก 3"
  },
  Event_6959_Desc = {
    Text = "คุณเป็นผู้สังเกตความทรงจำ ได้แต่เฝ้ามองสาวน้อยตกลงสู่ทะเลที่ไม่มีแสง \n กระแสน้ำดันกระโปรงขึ้น แต่เธอกลับจมลงไป เหมือนดอกไม้ที่ยังไม่บาน。"
  },
  Event_6959_Name = {
    Text = "จมลงในทะเล"
  },
  Event_6960_ChoiceDesc1 = {
    Text = "【ใส่กุญแจเงิน】"
  },
  Event_6960_Desc = {
    Text = "ดูเหมือนว่าเมือก D ที่เกินความอิ่มตัวนั้นมีสารบางอย่างซ่อนอยู่... ใช้กุญแจเงินในการสังเกต แล้วเปลี่ยนมันให้กลายเป็นพละกำลังของตัวเองเถอะ。"
  },
  Event_6960_Name = {
    Text = "จุดแยก"
  },
  Event_6961_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6961_Desc = {
    Text = "อย่าหลงเชื่อการล่อของศัตรู อาจจะเป็นกับดัก。"
  },
  Event_6961_Name = {
    Text = "นกกาถูกสาป"
  },
  Event_6962_ChoiceDesc1 = {
    Text = "(ช่วยเขา)"
  },
  Event_6962_ChoiceDesc2 = {
    Text = "【เย็นชาเฝ้าดู】"
  },
  Event_6962_Desc = {
    Text = "เด็กชายยืนอยู่บนเวที แสงไฟสีขาวซีดสาดส่องไปที่ใบหน้าของเขา。\n「มอบให้...」\nเด็กชายหน้าแดง เขาอ้าปาก แต่ไม่สามารถเปล่งเสียงออกมาได้。\nปากที่มืดมิดอ้ากว้างขึ้นเรื่อยๆ กว้างขึ้นเรื่อยๆ..."
  },
  Event_6962_Name = {
    Text = "พิธีปิดฉาก Ⅲ"
  },
  Event_6963_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6963_Desc = {
    Text = "「น่ารำคาญ น่ารำคาญจริงๆ!」เหมือนกับถูกคุณสัมผัสที่สวิตช์บางอย่าง แมวดำจึงแสดงท่าทีก้าวร้าวออกมา กัดเข้าที่แขนของคุณ โชคดีที่คุณหลบได้ทัน ทำให้มันกัดขาดแค่ชายเสื้อส่วนหนึ่ง แมวดำกระโดดไปที่มุมถนน หายไปในท่อระบายน้ำของตรอก。"
  },
  Event_6963_Name = {
    Text = "เอลฟ์แห่งราตรี"
  },
  Event_6964_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6964_Desc = {
    Text = "ถูกพัดพาไปด้วยของเหลวที่ซัดซาอยู่ในสมอง คุณผลักประตูและก้าวเข้าสู่เส้นทางที่ไม่มีวันหวนกลับ \n แสงสีขาวที่ร้อนแรงด้านนอกประตู เป็นการไถ่บาป หรือเป็นการล่มสลาย?"
  },
  Event_6964_Name = {
    Text = "นอกประตูใหญ่"
  },
  Event_6965_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6965_Desc = {
    Text = "คุณรวบรวมความกล้าแล้วเดินเข้าไปดู ทันใดนั้นเมือกบนโต๊ะก็ปริออก เผยสิ่งที่ซ่อนอยู่ข้างใต้"
  },
  Event_6965_Name = {
    Text = "นอกประตูใหญ่"
  },
  Event_6966_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6966_Desc = {
    Text = "กลืนลายลิ้น กดความสงสัยลง และมุ่งมั่นเผชิญหน้าศัตรู。\nให้ผีเสื้อหยุดอยู่ชั่วคราวในร่างกายของคุณ แม้ว่าการกระพือปีกของมันจะทำให้อวัยวะภายในของคุณแตกละเอียด。"
  },
  Event_6966_Name = {
    Text = "เอฟเฟกต์ผีเสื้อ"
  },
  Event_6967_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_6967_Desc = {
    Text = "แมวพยักหน้าด้วยความพึงพอใจ จากนั้นก็กลายเป็นเงาและหายไปในที่เดิม ทิ้งวัตถุทรงกลมสีดำไว้บางชิ้น"
  },
  Event_6967_Name = {
    Text = "ผู้อยู่อาศัยที่เดินทาง"
  },
  Event_6968_ChoiceDesc1 = {
    Text = "【ใส่กุญแจเงิน】"
  },
  Event_6968_Desc = {
    Text = "ดูเหมือนว่าเมือก D ที่มีความอิ่มตัวเกินไปจะซ่อนสารบางอย่างไว้... ใช้กุญแจเงินในการสังเกต และแปลงมันให้กลายเป็นพละกำลังของตนเองเถอะ。"
  },
  Event_6968_Name = {
    Text = "จุดแยก"
  },
  Event_6969_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้างทองคำแบบสุ่ม 1 ชิ้น ได้รับผลกระทบจาก「(Skill.Arg1)」"
  },
  Event_6969_Desc = {
    Text = "เมื่อเห็นคุณยังลังเล คุมก็พุ่งไปที่กองดิน ใช้กรงหน้าทั้งสองข้างขุดอะไรบางอย่างออกมาอย่างรวดเร็ว แล้วผลักมันไปข้างหน้าคุณ。"
  },
  Event_6969_Name = {
    Text = "วัตถุฝังลึก"
  },
  Event_6970_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6970_Desc = {
    Text = "ที่ด้านบนของกระดาษพิมพ์ว่า「เมอรีเม」ไม่มีเมสันอยู่จริงๆ \n ความระแวงมากเกินไปไม่ใช่สัญญาณที่ดีนะ ผู้พิทักษ์。"
  },
  Event_6970_Name = {
    Text = "เครื่องพิมพ์ดีด"
  },
  Event_6971_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์ทองคำ 3 ตัวเลือก 1，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6971_Desc = {
    Text = "กองดินได้ปกคลุมความชั่วร้ายของสมาคมนักประติมากรรมไว้。"
  },
  Event_6971_Name = {
    Text = "วัตถุฝังลึก"
  },
  Event_6972_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6972_Desc = {
    Text = "นกมีระเบียบของมันเอง พวกมันไม่ได้ทำตามความต้องการของคุณ และคุณก็ไม่มีสิทธิ์เข้าไปยุ่งเกี่ยวกับกฎธรรมชาติ。"
  },
  Event_6972_Name = {
    Text = "กุยบินโดดเดี่ยว"
  },
  Event_6973_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์ทองคำ 3 ตัวเลือก 1，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6973_Desc = {
    Text = "ทำไมล่ะ ทำไมถึงจมล่ะ?\nวันนั้นไม่มีฟ้าร้อง ไม่มีพายุ คืนฟ้าปลอดโปร่งเหมือนถูกล้าง ไม่มีดาวเลย ดวงจันทร์เต็มดวงต่ำต้อยอยู่เหนือระดับน้ำทะเล ราวกับดวงอาทิตย์ที่เย็นชา。"
  },
  Event_6973_Name = {
    Text = "จมลงในทะเล"
  },
  Event_6974_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6974_Desc = {
    Text = "「หัวหน้าขบวนรถไฟ! เราโดนโจมตีโดยผู้ก่อการร้าย!... ซ่า...」\nดูเหมือนว่าจะเป็นสายโทรแจ้งจากคนขับรถไฟ คุณตั้งใจที่จะวางสายไปแล้ว.\n「โปรดกล่าวอีกครั้ง นี่คือทีมปฏิบัติการพิเศษที่ 4 มิซากะ เรากำลังโดยสารรถไฟด่วนพิเศษกลางคืนสายเหนือเพื่อคุ้มครองและช่วยเหลือตัวประกัน และระหว่างทางเราโดน... อ่าห์!」\nน้ำเสียงในโทรศัพท์เปลี่ยนเป็นเสียงกระซิบหยาบกร้าน รวมไปถึงเสียงกรีดร้องที่น่าขนลุก.\n「พิธีศักดิ์สิทธิ์นี้เสร็จสิ้นแล้ว ลูกแกะที่หลงทางเอ๋ย ขอให้การอาบน้ำศักดิ์สิทธิ์นี้ชำระล้างจิตวิญญาณของเจ้า...」"
  },
  Event_6974_Name = {
    Text = "การโทรจากรถไฟ"
  },
  Event_6975_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6975_Desc = {
    Text = "การรวบรวมเงินใจก็เป็นหนึ่งในงานของผู้พิทักษ์ \n วิญญาณที่ล่องลอยอยู่ในผลึกสีขาวบริสุทธิ์ จะกลับมาสู่โลกในรูปลักษณ์ใหม่ในอนาคต。"
  },
  Event_6975_Name = {
    Text = "วิญญาณที่ถูกผูกมัด"
  },
  Event_6976_ChoiceDesc1 = {
    Text = "【การตกต่อไป】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg1)」，คุณต้องการให้การตกต่อเนื่องหรือไม่"
  },
  Event_6976_ChoiceDesc2 = {
    Text = "【ถอนตัวออก】ได้รับ 25 รอยดำ"
  },
  Event_6976_Desc = {
    Text = "「คุณ」กำลังเชิญชวนคุณอยู่.\nในความลึกของเกลียวลม อดีตและอนาคตของ「คุณ」ได้ส่งมอบ「ของขวัญ」จากมิติที่แตกต่างกันมาให้คุณ."
  },
  Event_6976_Name = {
    Text = "เหววน"
  },
  Event_6977_ChoiceDesc1 = {
    Text = "【ก้มตัวตรวจสอบ】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」"
  },
  Event_6977_ChoiceDesc2 = {
    Text = "【ยกเลิกการดู】ได้รับ 50 รอยดำ"
  },
  Event_6977_Desc = {
    Text = "ด้านล่างของเตียงผ่าตัดดูเหมือนมีฟิล์มม้วนหนึ่งถูกหนีบไว้。"
  },
  Event_6977_Name = {
    Text = "ความทรงจำของแสงและเงา"
  },
  Event_6978_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6978_Desc = {
    Text = "ปฏิเสธสิ่งรบกวน จดจ่ออยู่กับสิ่งที่อยู่ตรงหน้า \n คุณยังมีสิ่งสำคัญกว่าที่ต้องทำ"
  },
  Event_6978_Name = {
    Text = "ร่างครึ่งของฉัน"
  },
  Event_6979_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6979_Desc = {
    Text = "ศาสนวัตถุที่สูญหาย มรดกที่มีค่าหมายถึงเครื่องมือในการทำให้ความปรารถนาเป็นจริง...\n บางทีมีเพียงสมบัติเท่านั้นที่มีเสน่ห์เช่นนี้。"
  },
  Event_6979_Name = {
    Text = "วิธีการป้อนข้อมูลลึกลับ"
  },
  Event_6980_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6980_Desc = {
    Text = "「คุณเป็น『แม่』ของลิลลี่ แต่กลับใช้เธอเป็นเครื่องมือในการศึกษาและการต่อสู้」 คุณตอบ，「เด็กเล็กๆ อาจจะเชื่อฟังแม่ แต่คุณไม่ควรเป็น『แม่』ของลิลลี่」"
  },
  Event_6980_Name = {
    Text = "การเลือกของเธอ"
  },
  Event_69813_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_69813_Desc = {
    Text = "กุญแจเงินส่องประกายกระพริบ แขนต่างๆ ดูเหมือนจะถูกพละกำลังบางอย่างทำให้หวาดกลัว จึงค่อยๆ หายเข้าไปในน้ำแล้วหายไป。"
  },
  Event_69813_Name = {
    Text = "บ่อน้ำเลือด"
  },
  Event_69814_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_69814_Desc = {
    Text = "คุณจมดิ่งลึกเข้าไปในความมืด เสียงกระซิบที่โกลาหลของความประสงค์สูงสุดดังก้องในหัวของคุณ คุณหลับตาลง เรียกใช้อำนาจภายในตัวเอง\nทันใดนั้น เสียงทั้งหมดและความรู้สึกผิดปกติหายไป คุณยืนอยู่หลังประตู ข้างกายไม่มีเงาของหนวดเลือดเลย ราวกับว่าไม่เคยมีอยู่\nคุณรู้สึกสดชื่นเต็มที่ คุณเข้าใจว่าคุณต้องจ่ายราคาที่ต้องจ่าย แต่ราคาที่ต้องจ่ายนั้นไม่มีความสำคัญ—คุณจะเผชิญหน้ากับสิ่งที่สูงสุดในรูปแบบที่แข็งแกร่งยิ่งขึ้น。"
  },
  Event_69814_Name = {
    Text = "บ่อน้ำเลือด"
  },
  Event_69815_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_69815_Desc = {
    Text = "ผู้ปลุกตื่นที่ถูกสร้างขึ้นจากความทรงจำของคุณไม่มีความลังเลแม้แต่วินาทีเดียว ดึงคุณออกจากบ่อน้ำเลือด ขาที่เชื่อมต่อกับแขนของคุณถูกฉีกขาด น้ำโคลนขุ่นกระเด็นขึ้น สัตว์นับไม่ถ้วนที่ตาเปล่ามองไม่เห็นกำลังขยับตัวอยู่ในน้ำ ผู้สร้างที่ดั้งเดิมและผู้ทำลายกำลังกระหายที่จะกลืนกิน。"
  },
  Event_69815_Name = {
    Text = "บ่อน้ำเลือด"
  },
  Event_69816_ChoiceDesc1 = {
    Text = "【ปลุกร่างกายที่ตื่นขึ้น】หักค่าความคลั่ง 100 จากทุกร่างกายที่ตื่นขึ้น และลบการ์ดอาการ 1 ใบ"
  },
  Event_69816_ChoiceDesc2 = {
    Text = "【ดูดซึมบ่อเลือด】เพิ่มพลังชีวิตสูงสุด Arg1 จุด และแพร่เชื้อ 2 ใบ「(Skill.Arg2)」"
  },
  Event_69816_ChoiceDesc3 = {
    Text = "【ใส่กุญแจเงิน】ล้างพลังกุญแจเงิน"
  },
  Event_69816_Desc = {
    Text = "อำนาจแห่งชีวิตปรากฏในรูปแบบของความตายในสายตาแห่งความเป็นต้นกำเนิด เมื่อคุณก้าวเข้าสู่ดินแดนที่ลางสังหรณ์นี้ บ่อน้ำเลือดที่มีกลิ่นคาวก็ปรากฏตัวขึ้นทันที \n เลือดสีแดงเข้มยื่นแขนออกมาอย่างนับไม่ถ้วน ยึดติดกับข้อเท้าของคุณ และพยายามปีนขึ้นไปเรื่อยๆ ตั้งใจจะลากคุณลงสู่เหวที่ไม่อาจคาดเดาได้。"
  },
  Event_69816_Name = {
    Text = "บ่อน้ำเลือด"
  },
  Event_6981_ChoiceDesc1 = {
    Text = "【หยิบกุญแจ】"
  },
  Event_6981_Desc = {
    Text = "ชุดกุญแจที่เต็มไปด้วยสนิม สามารถใช้ไขประตูได้。"
  },
  Event_6981_Name = {
    Text = "กุญแจที่เป็นสนิม"
  },
  Event_6982_ChoiceDesc1 = {
    Text = "【ออก】เลือกคัดลอกการ์ดคำสั่ง 1 ใบ ได้รับผลกระทบจาก 「(Skill.Arg1)」"
  },
  Event_6982_Desc = {
    Text = "ภายใต้เพลงเรือและการชี้นำของเซเลสเท คุณมองไปยังความลึกของห้องโดยสารที่มืดมิด—ชีวิตของพวกคุณจะอยู่ในความมืดที่ไม่มีที่สิ้นสุดนั้นหรือไม่?"
  },
  Event_6982_Name = {
    Text = "เพลงเรือ"
  },
  Event_6983_ChoiceDesc1 = {
    Text = "【ออกจากที่นี่ด้วยกัน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_6983_ChoiceDesc2 = {
    Text = "【ปฏิเสธที่จะจากไป】ได้รับ 75 รอยดำ, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6983_Desc = {
    Text = "นี่คือภาพหลอนหรือเปล่า? คุณเห็นอีกากำลังโฉบอยู่บนฟ้า ร้องเพลงที่คุ้นเคยว่า: \n「แล้วไปด้วยกันเถอะ ฉันกับคุณ \nในขณะที่ค่ำคืนเพิ่งจะเริ่มต้น \nเหมือนคนเมาใกล้ตายล้มอยู่บนถนน」"
  },
  Event_6983_Name = {
    Text = "เสียงฝูงกา"
  },
  Event_6984_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6984_Desc = {
    Text = "พลังการย้อนรอยไม่สามารถค้นหาจุดติดต่อให้คุณได้อีกในระยะเวลาสั้นๆ แต่คุณอย่างน้อยก็ได้รับความปลอบโยนชั่วคราว。"
  },
  Event_6984_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_6985_ChoiceDesc1 = {
    Text = "【ตกลงสู่เกลียว】มองไปยังจุดจบของเกลียว"
  },
  Event_6985_ChoiceDesc2 = {
    Text = "【ถอนตัวออก】ได้รับ 25 รอยดำ"
  },
  Event_6985_Desc = {
    Text = "นอกหน้าต่างเรือไม่สามารถมองเห็นผิวน้ำทะเลได้อีกแล้ว。\nกระจกสะท้อนใบหน้าที่ซีดเซียวของคุณ และในม่านตาของคุณ，「คุณ」ก็จ้องมองไปที่หน้าต่างเรือเช่นกัน。\nความเป็นจริงและดินแดนลับแลซ้อนทับและผสมผสานกัน สุดท้ายบิดเบือนกลายเป็นเกลียวหลายชั้นที่สลับซับซ้อน。"
  },
  Event_6985_Name = {
    Text = "เหววน"
  },
  Event_6986_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6986_Desc = {
    Text = "คุณรับคำขอติดต่อจากโรงเรียน เสียงที่คุ้นเคยทำให้จิตใจของคุณสงบ คุณรวบรวมกำลังใจและก้าวเดินต่อไป"
  },
  Event_6986_Name = {
    Text = "จุดติดต่อ"
  },
  Event_6987_ChoiceDesc1 = {
    Text = "【แสดงความเห็นด้วย】"
  },
  Event_6987_ChoiceDesc2 = {
    Text = "【ปฏิเสธ】"
  },
  Event_6987_ChoiceDesc3 = {
    Text = "【ไม่ยืนยันไม่ปฏิเสธ】"
  },
  Event_6987_Desc = {
    Text = "「นานไม่เจอกันนะเพื่อนๆ」พวกคุณหลุดพ้นจากการต่อสู้กับผู้ศรัทธาแห่งโคมไฟ ได้รับโอกาสพักหายใจเล็กน้อย และจู่ๆ ก็พบว่าชายผมยาวคนนั้นปรากฏขึ้นอีกครั้งข้างถนน ยิ้มทักทายพวกคุณเหมือนกับการต่อสู้เมื่อครู่ไม่เคยเกิดขึ้นมาก่อน\n「เมื่อเปรียบเทียบกับครั้งที่แล้วที่เจอกัน กลิ่นของเคอร์เบรอสจากตัวเธอเข้มข้นขึ้นมาก ในช่วงเวลานี้เธอคงไปที่ไหนสักแห่งไกลๆ ใช่ไหม?」\n"
  },
  Event_6987_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅴ"
  },
  Event_6988_ChoiceDesc1 = {
    Text = "【ถามทางเขา】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6988_ChoiceDesc2 = {
    Text = "【ออกไปจากมัน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6988_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_6988_Desc = {
    Text = "เงายืนอยู่ใต้โคมไฟที่สูงและเรียว。\n「ขอไฟยืมหน่อยได้ไหมครับ」\nคุณไม่มีนิสัยใช้@2 แต่คุณไม่รังเกียจที่จะใช้「เวทมนตร์」เล็กน้อย。\nด้วยความช่วยเหลือของคุณ เงาจะจุด@2 ลงไปในวังวนสีดำที่มองไม่เห็นก้น。\nไม่นาน คุณก็เห็นควันสีขาวพวยพุ่งออกมา。\n「อา——」\nเงาออกเสียงถอนหายใจอย่างมีความสุข。"
  },
  Event_6988_Name = {
    Text = "รูปเงาใต้ไฟถนน"
  },
  Event_6989_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_6989_Desc = {
    Text = "บนกระดานหมากรุก สิ่งที่เห็นไม่ใช่ความจริง\n\nสิ่งที่ขวางทางการเดินหน้าของคุณอาจไม่ใช่กำแพง แต่เป็นความอยากรู้ที่หมดสิ้นไปของคุณ。"
  },
  Event_6989_Name = {
    Text = "พื้นที่ภาพลวงตา"
  },
  Event_6990_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6990_Desc = {
    Text = "「ฉันเจ็บมาก เจ็บมากเลย... พี่สาวซาร่า...」\nคุณมองไปที่ซาร่า เธอทำท่าทางตื่นตระหนกปกป้องเด็กสองคน ดูเหมือนจะไม่ได้ยินอะไร\nเสียงค่อยๆ หายไป。"
  },
  Event_6990_Name = {
    Text = "「พี่สาวซาซา」"
  },
  Event_6991_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_6991_Desc = {
    Text = "คุณลุกขึ้นปรบมือให้กับเด็กชาย \n ดูเหมือนจะรู้สึกถึงกำลังใจของคุณ เด็กชายจึงยืดอกเล็กๆ ของเขา \n เลือดสีดำไหลทะลักออกจากปากอย่างต่อเนื่อง แต่ไม่สามารถหยุดเสียงร้องได้อีกต่อไป。"
  },
  Event_6991_Name = {
    Text = "พิธีปิดฉาก Ⅳ"
  },
  Event_6992_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6992_Desc = {
    Text = "ความเศร้าส่วนหนึ่งค่อยๆ จางหายไป แต่น้ำตากลับยังคงไหลไม่หยุด สู่ดินแดนแห่งอดีตกาลของชีเจว์"
  },
  Event_6992_Name = {
    Text = "น้ำตาของชายหาดมืดมน"
  },
  Event_6993_ChoiceDesc1 = {
    Text = "【บีบคอผู้ขับร้อง】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg2)」"
  },
  Event_6993_ChoiceDesc2 = {
    Text = "【ทำให้การเต้นรำล้มลง】ติดเชื้อสองครั้ง「(Skill.Arg1)」ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」และ「(RelicConfig.Arg3)」"
  },
  Event_6993_ChoiceDesc3 = {
    Text = "【ออกเส้นทาง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_6993_Desc = {
    Text = "คุณถูกเงาของคนสามคนขวางทางไว้\nเงาหนึ่งกำลังร้องเพลง เสียงแหบแห้ง เนื้อเพลงแปลกประหลาด คุณต้องเอามือปิดหูแล้วหลีกเลี่ยงมัน\nเงาหนึ่งกำลังเต้นรำ ท่าทางแข็งทื่อ ก้าวย่างลังเล คุณหลับตาแล้วหลบมัน\nเงาหนึ่งกำลังท่องบทกวี จังหวะขาดๆ เกินๆ ประโยคไม่ต่อเนื่อง คุณทนไม่ไหว จึง——"
  },
  Event_6993_Name = {
    Text = "ผู้ร้ายบนทางแคบ"
  },
  Event_6994_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_6994_Desc = {
    Text = "ความโกรธบางส่วนกำลังเดือดพล่าน แต่น้ำตาก็ยังคงไหลไม่หยุดไปยังยุคโบราณที่ไม่อาจหยั่งรู้"
  },
  Event_6994_Name = {
    Text = "น้ำตาของชายหาดมืดมน"
  },
  Event_6995_ChoiceDesc1 = {
    Text = "【เมินเฉย】ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_6995_ChoiceDesc2 = {
    Text = "【หันหลังแล้วจากไป】สุ่มปลุกร่างกายที่ตื่นขึ้น 1 ตน"
  },
  Event_6995_Desc = {
    Text = "โชคชะตาที่โหดร้ายคลานอยู่ใต้เท้าของผู้เดินทาง เส้นทางนั้นแวววาวราวกับกระจก ข้างหลังมีเสียงแตกที่เบาๆ \n ใครกันแน่ที่เหยียบย่ำโชคชะตาใต้เท้า? มันคือความหลอกลวง เป็นกับดัก หรือเพียงแค่พึมพำ เป็นคำพูดที่ไม่จริง... \n ต่อหน้าคุณ มีรอยแตกที่ค่อยๆ คลานออกมา \n <Italic:เหมือนว่ามันจะจมลงสำหรับการตื่นรู้ทางจิตวิญญาณ.>"
  },
  Event_6995_Name = {
    Text = "รอยร้าวคลาน"
  },
  Event_6996_ChoiceDesc1 = {
    Text = "【เข้าร่วมการทดสอบ】ติดเชื้อ「(Skill.Arg1)」，ชัยชนะได้รับสิ่งสร้างทองคำ 1 ชิ้น，ความล้มเหลวได้รับ 50 รอยดำ"
  },
  Event_6996_ChoiceDesc2 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_6996_Desc = {
    Text = "คุณได้เห็นความลับบางอย่างจากน้ำดำที่สะท้อนเหมือนกระจกใต้เท้าของคุณ \n ขอบของมันเบลอและล้อมรอบด้วยหมอกดำที่ไม่อาจขจัดออกไปได้ คุณรู้สึกคุ้นเคยอย่างแปลกประหลาด แต่ก็ไม่สามารถบอกได้ว่ามันคืออะไร。"
  },
  Event_6996_Name = {
    Text = "ใต้ผิวกระจก"
  },
  Event_6997_ChoiceDesc1 = {
    Text = "【เลียนเสียงแมว】50% โอกาสได้รับ 125 รอยดำ, 50% โอกาสติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6997_ChoiceDesc2 = {
    Text = "【ให้อาหาร】มีโอกาส 75% ได้รับ 100 รอยดำ มีโอกาส 25% ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6997_ChoiceDesc3 = {
    Text = "【วิ่งหนี】ได้รับ ๕๐ รอยดำ"
  },
  Event_6997_Desc = {
    Text = "คุณหลงเข้าไปในอาณาเขตของแมวดำ \n ดวงตานับไม่ถ้วนในความมืดเปิดขึ้นอย่างรวดเร็ว เต็มไปด้วยการสำรวจ การพิจารณา และการระวังภัย... ที่ขาดเพียงความมีน้ำใจ \n สีเขียวมรกต สีเหลืองอำพัน สีฟ้าหมายเลข... \n คุณรู้สึกเหมือนอยู่ท่ามกลางทะเลแห่งอัญมณีที่เปล่งประกาย \n เพื่อที่จะหลบหนี คุณ——"
  },
  Event_6997_Name = {
    Text = "เมืองแมว"
  },
  Event_6998_ChoiceDesc1 = {
    Text = "【เกี่ยวกับดาฟเดล】การ์ดคำสั่ง 2 ใบแบบสุ่มจะได้รับการแกะสลัก：「(EnchantConfig.Arg1)」，「(EnchantConfig.Arg2)」"
  },
  Event_6998_ChoiceDesc2 = {
    Text = "【เกี่ยวกับสุนัขแห่งนรก】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」"
  },
  Event_6998_ChoiceDesc3 = {
    Text = "【เกี่ยวกับลิลลี่】ติด「(Skill.Arg1)」"
  },
  Event_6998_Desc = {
    Text = "「นี่คือเวลาแนะนำของดาฟเดล.」"
  },
  Event_6998_Name = {
    Text = "เวลาเตือน"
  },
  Event_6999_ChoiceDesc1 = {
    Text = "【ปล่อยให้เข็มชี้】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ได้รับการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6999_ChoiceDesc2 = {
    Text = "【กดค้างที่ตัวชี้】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_6999_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_6999_Desc = {
    Text = "แกร๊ก แชะ แกร๊ก——\nเข็มนาฬิกาของโชคชะตาขยับไปทีละนิด เสียงคลิกของกลไกเย็นชาค่อยๆ เคลื่อนตัวไปในทิศทางที่คุณไม่อยากเห็นอย่างแน่นอน。"
  },
  Event_6999_Name = {
    Text = "นอกเหนือจากปลายเข็ม"
  },
  Event_7000_ChoiceDesc1 = {
    Text = "【ทำเป็นหูทวนลม】สุ่มได้รับการ์ดคำสั่ง 3 ใบจากกองไพ่ เลือกการ์ด 1 ใบเพื่อลบ และได้รับรอยดำ 75 อัน"
  },
  Event_7000_ChoiceDesc2 = {
    Text = "【ตรวจสอบอย่างระมัดระวัง】สุ่มเลือกการ์ดคำสั่ง 3 ใบจากสำรับ，เลือกสำเนาต้นฉบับของการ์ด 1 ใบเข้าสู่สำรับ และได้รับรอยดำ 25 อัน"
  },
  Event_7000_ChoiceDesc3 = {
    Text = "【เดินจากไปอย่างเงียบๆ】ได้รับ 50 รอยดำ"
  },
  Event_7000_Desc = {
    Text = "โชคชะตาที่โหดร้ายคลานอยู่ใต้เท้าของผู้เดินทาง เส้นทางนั้นแวววาวราวกับกระจก ข้างหลังมีเสียงแตกที่เบาๆ \n ใครกันแน่ที่เหยียบย่ำโชคชะตาใต้เท้า? มันคือความหลอกลวง เป็นกับดัก หรือเพียงแค่พึมพำ เป็นคำพูดที่ไม่จริง... \n ต่อหน้าคุณ มีรอยแตกที่ค่อยๆ คลานออกมา。"
  },
  Event_7000_Name = {
    Text = "รอยร้าวคลาน"
  },
  Event_7001_ChoiceDesc1 = {
    Text = "【เรียกอีกา】ได้รับ 25 รอยดำ ส่งผลให้「(Skill.Arg2)」 เลือกต่อไป"
  },
  Event_7001_ChoiceDesc2 = {
    Text = "【ออกห่างไปไกล】"
  },
  Event_7001_Desc = {
    Text = "กรงเล็บกรีดผ่านผ้าคลุมไหล่และจมลึกเข้าที่ไหล่"
  },
  Event_7001_Name = {
    Text = "กุยบินโดดเดี่ยว"
  },
  Event_7002_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7002_Desc = {
    Text = "ความกลัวบางครั้งไม่ได้มาจากสิ่งที่มีตัวตน。\nในที่ที่「สุนัขแห่งนรก」ผ่านไป จะมีหยดสีแดงหลงเหลืออยู่ สะท้อนรูปร่างของคุณออกมา。"
  },
  Event_7002_Name = {
    Text = "ภาพสะท้อนไร้รูปทรง"
  },
  Event_7003_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7003_Desc = {
    Text = "พร้อมกับกระแสไฟฟ้าเบาๆ คุณได้ยินเสียงกระซิบของผู้หญิงคนหนึ่ง \n เธอร้องไห้และเล่าประสบการณ์ของเธออย่างไม่หยุดหย่อน \n หนึ่งชั่วโมงผ่านไป หนึ่งวันผ่านไป... จนกระทั่งคุณลืมไปแล้วว่าเธอเสียใจเพราะอะไร \n สุดท้ายเธอก็วางสายอย่างมีความสุข และสัญญาว่าจะมอบของขวัญชิ้นใหญ่ให้คุณ \n คุณรับของขวัญนั้นมา ไม่ว่ายังไง ของขวัญก็ทำให้รู้สึกดีเสมอ。"
  },
  Event_7003_Name = {
    Text = "กรุณารับโทรศัพท์"
  },
  Event_7004_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7004_Desc = {
    Text = "คุณก้มศีรษะลงคุกเข่าข้างเดียวในสายตาที่ไม่เข้าใจของเพื่อนๆ และยกมือขวาที่กำหมัดขึ้นวางบนหน้าผาก \n ดีมาก แบบนี้ก็จะสามารถปิดบังใบหน้าของคุณได้อย่างสมบูรณ์แบบ。"
  },
  Event_7004_Name = {
    Text = "ทำให้ของปลอมดูเหมือนจริง"
  },
  Event_7005_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7005_Desc = {
    Text = "「เธอได้สวมผ้าคลุมให้ฉันแล้ว」\nหุ่นขี้ผึ้งยิ้มให้คุณอย่างสงบ\n「ฉันจะมอบความจริงให้คุณ เป็นรางวัลจากการทำงานหนัก」\nท้องของเธอไหลออกมาด้วยของเหลวสีดำหนืด พันรอบตัวคุณอย่างแน่นหนา\nโลกมืดมิด แต่กลับอบอุ่นอย่างมาก\nคุณหดตัวและหาว ปรากฏตัวเข้าสู่ความฝันเป็นครั้งที่@1……"
  },
  Event_7005_Name = {
    Text = "หุ่นขี้ผึ้งที่ยังไม่เสร็จ"
  },
  Event_7006_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_7006_Desc = {
    Text = "คุณไม่พบอะไรเลยในหมอก"
  },
  Event_7006_Name = {
    Text = "หมอกความวุ่นวาย"
  },
  Event_7007_ChoiceDesc1 = {
    Text = "【รับโทรศัพท์】ได้รับการแกะสลักขั้นสูง เลือก 1 จาก 3"
  },
  Event_7007_ChoiceDesc2 = {
    Text = "【ละเลยเสียงกระดิ่ง】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7007_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7007_Desc = {
    Text = "「ติ๊งลิ๊งลิ๊ง……」\nเสียงโทรศัพท์ที่ดังแหลมมาจากมุมห้อง เสียงเร่งรีบและวุ่นวาย เสียงหนึ่งดังขึ้นสูงกว่าเสียงก่อนหน้า เกือบทำให้คุณรู้สึกเหมือนกับว่า: ถ้าคุณไม่รับสาย มันจะบ้าและระเบิดทันที แล้วทำลายโลก。"
  },
  Event_7007_Name = {
    Text = "กรุณารับโทรศัพท์"
  },
  Event_7008_ChoiceDesc1 = {
    Text = "【เข้าใกล้ภาพลวงตา】ได้รับสิ่งประดิษฐ์เงิน เลือก 1 จาก 3"
  },
  Event_7008_ChoiceDesc2 = {
    Text = "【ทำลายภาพลวงตา】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」，ติดเชื้อสองครั้ง「(Skill.Arg3)」"
  },
  Event_7008_Desc = {
    Text = "นี่คือฟ้ามอร์กานาในดินแดนลับแลหรือ? หรือเป็นความทรงจำที่ไม่สามารถลบเลือนได้อีกครั้ง? \nคุณขยี้ตาของคุณ เงาในระยะไกลเข้ามาหาคุณ——เป็นตลาดที่มีเสียงดังครึกโครม เป็นพิพิธภัณฑ์หุ่นขี้ผึ้งที่หายไปในกระบวนการย่อยสลาย เป็นโรงพยาบาลคนบ้าที่มีหิมะและลมพัดแรง หรือเป็นอาร์คต์ที่ทิวทัศน์เลือนรางไปแล้ว?"
  },
  Event_7008_Name = {
    Text = "ฟ้ามอร์กานา"
  },
  Event_7009_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7009_Desc = {
    Text = "ราวกับถูกน้ำร้อนลวก คุณปิดหูทันทีด้วยสัญชาตญาณ เพื่อไม่ให้เสียงเพลงที่ชั่วร้ายนั้นแทรกซึมเข้ามา"
  },
  Event_7009_Name = {
    Text = "ข้อห้ามของเสียง"
  },
  Event_7010_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7010_Desc = {
    Text = "เสียงดนตรีจังหวะสดใสได้ขับไล่ความตึงเครียดและความกลัว คุณเต็มไปด้วยความกระตือรือร้น คุณกำลังรอคอยที่จะเบ่งบาน คุณมีความสุขและตื่นเต้น คุณก้าวเดินอย่างรวดเร็วทอดทิ้งราโมน่าไว้เบื้องหลัง——「ผู้พิทักษ์?! อย่าเดินเร็วขนาดนั้น!」"
  },
  Event_7010_Name = {
    Text = "เสียงไม่รู้ชื่อ"
  },
  Event_7011_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7011_Desc = {
    Text = "「หยุดเดิน!!! สัตว์ประหลาดการหลอมกร่อนที่คลานอยู่ยังรู้จักอวัยวะสี่ของตัวเองดีกว่าคุณ!」\nปล่อยผู้ชมไป...\nคุณอธิษฐานในใจแบบนี้。"
  },
  Event_7011_Name = {
    Text = "ผู้ร้ายบนทางแคบ"
  },
  Event_7012_ChoiceDesc1 = {
    Text = "【ถอนตัวออกไป】"
  },
  Event_7012_Desc = {
    Text = "นี่เป็นเพียงดินแดนลับแลเท่านั้น \n สิ่งที่คุณต้องการปกป้องและหลบหนีคือความเป็นจริงที่ไม่เหมือนใคร。"
  },
  Event_7012_Name = {
    Text = "เหววน"
  },
  Event_7013_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7013_Desc = {
    Text = "\"คนอย่างเจ้าช่างน่าชังที่สุด”\nเจ้าฉีกกระดาษร่างให้เป็นชิ้นเล็กชิ้นน้อย ทิ้งให้ลมพัดปลิวกระจายล่องลอยราวเกสรดอกไม้\nกวีเงยหน้ามองตัวอักษรที่ปลิวในสายลม มุมปากเผยรอยยิ้มหลงใหล\n\"ช่างงดงามเหลือเกิน...\""
  },
  Event_7013_Name = {
    Text = "ผู้ร้ายบนทางแคบ"
  },
  Event_7014_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7014_Desc = {
    Text = "คุณดึงโปสเตอร์ทั้งแผ่นออกมา พบว่าด้านหลังบันทึกค่าใช้จ่ายต่าง ๆ ของพิพิธภัณฑ์หุ่นขี้ผึ้งอย่างลวก ๆ\nลายมือเจ้าของดูเหมือนไม่ค่อยมีความอดทนหรือพรสวรรค์ด้านคณิตศาสตร์เลย บัญชีเหล่านี้จึงดูไม่สมดุลแบบใด ๆ\nคุณมองผ่าน ๆ ค่าใช้จ่ายที่มากที่สุดดูเหมือนจะเป็น 「การบำรุงรักษาและทำความสะอาดหุ่นขี้ผึ้ง」\nค่าใช้จ่ายสำหรับพนักงานน้อยนิดอย่างน่าสงสาร โดยล่าสุดคือค่าซื้อแส้ม้าขน 12 ด้าม ราคาโดยประมาณ 20 ฟาง\nยังมีค่าใช้จ่ายพิเศษอีกหนึ่งรายการ คือ 「อาหารของพวกมัน」\n「พวกมัน」 หมายถึงใครกันแน่?"
  },
  Event_7014_Name = {
    Text = "เสียงหัวเราะในความมืด"
  },
  Event_7015_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7015_Desc = {
    Text = "「เจ้าเล่ห์... และคำตอบที่ถูกต้อง。」\nเจ้าของเสียงสนใจคำตอบนี้มาก สิ่งของสีเงินถูกโยนออกจากผิวน้ำ。\n「จงจำไว้ว่าทุกสิ่งมีราคาที่ต้องจ่าย」"
  },
  Event_7015_Name = {
    Text = "เสียงจากอีกฟาก"
  },
  Event_7016_ChoiceDesc1 = {
    Text = "【จับผีเสื้อตัวที่สอง】ลบการ์ดคำสั่ง 1 ใบ ได้รับ Arg1 รอยดำ"
  },
  Event_7016_ChoiceDesc2 = {
    Text = "【ไม่ผูกพันอีกต่อไป】"
  },
  Event_7016_Desc = {
    Text = "พวกเขาคือผู้อยู่อาศัยในมิติแห่งจิตวิญญาณหรือ? หรือเป็นชีวิตที่เกิดจากการย่อยสลาย \n ด้วยความสงสัย คุณเดินเข้าสู่พายุของผีเสื้อ。"
  },
  Event_7016_Name = {
    Text = "พายุความรู้ทางจิตวิญญาณ"
  },
  Event_7017_ChoiceDesc1 = {
    Text = "【สังเกตผีเสื้อตัวที่สาม】ลบการ์ดคำสั่ง 1 ใบออก ได้รับรอยดำ Arg1"
  },
  Event_7017_ChoiceDesc2 = {
    Text = "【ไม่ผูกพันอีกต่อไป】"
  },
  Event_7017_Desc = {
    Text = "ความเจ็บปวดที่นิ้วรุนแรง คุณปล่อยมือทันที"
  },
  Event_7017_Name = {
    Text = "พายุความรู้ทางจิตวิญญาณ"
  },
  Event_7018_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 25 รอยดำ, ติดเชื้อ 「(Skill.Arg1)」"
  },
  Event_7018_Desc = {
    Text = "「พวกเจ้ามนุษย์ไม่มีคำตอบอื่นอีกแล้วหรือ?」\nเจ้าของเสียงส่งเสียงคำรามอย่างไม่พอใจ ทำให้พื้นที่ทั้งหมดสั่นสะเทือน.\n「ความโลภและความไม่รู้... นี่แหละคือเหตุผลที่ฉันเบื่อหน่ายพวกเจ้า。」"
  },
  Event_7018_Name = {
    Text = "เสียงจากอีกฟาก"
  },
  Event_7019_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7019_Desc = {
    Text = "「วางใจเถอะ ฉันแค่เล่นสนุกนิดหน่อยกับลูกค้าขี้โลภนั่นเอง ช่วยไม่ได้เลย ฉันไม่ชอบดื่มเบียร์นี่นา~」"
  },
  Event_7019_Name = {
    Text = "ชิ้นส่วนความทรงจำ·เบียร์"
  },
  Event_7020_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7020_Desc = {
    Text = "「อย่าร้องอีกแล้ว——」\nคุณเตือนนักร้องที่เสียงเพี้ยน อย่าได้หวังจะมาทำลายโสตประสาทของคุณอีก"
  },
  Event_7020_Name = {
    Text = "ผู้ร้ายบนทางแคบ"
  },
  Event_7021_ChoiceDesc1 = {
    Text = "【ออกจาก】เลือกการตื่นรู้ 2 ร่าง"
  },
  Event_7021_Desc = {
    Text = "คุณหันหลังจากไป แต่กลับสูญหายในทางเดินยาวเหยียด \n ทางเดินที่ไม่มีที่สิ้นสุดแทบจะทำให้คุณหมดความอดทน จนกระทั่งคุณค้นพบเวทีเก่าขนาดเล็กแห่งหนึ่ง \n คุณกระพริบตา และเวทีก็หายไป。"
  },
  Event_7021_Name = {
    Text = "พิธีปิดฉากⅡ"
  },
  Event_7022_ChoiceDesc1 = {
    Text = "【หยิบแก้วไวน์】ได้รับการ์ด"
  },
  Event_7022_Desc = {
    Text = "แก้วหนึ่งที่ใสสะอาดราวกับแสงสีทองของพระอาทิตย์ตก สั่นไหวเหมือนกับคลื่นของข้าวสาลีในฤดูใบไม้ร่วง มีกลิ่นหอมหวานชวนหลงใหลเหมือนน้ำผึ้ง มันคืออะไร? ใครวางมันไว้ที่นี่? ทำไมไม่มีใครดูแล? \n ก่อนที่คำถามเหล่านี้จะได้รับคำตอบ ความคิดลึกลับหนึ่งได้แทรกซึมเข้ามาในหัวของคุณ: คุณต้องดื่มมันทันที! \n ในขณะนี้ คุณกลายเป็นผีเสื้อที่ถูกไฟล่อใจ เป็นแมลงที่ถูกหม้อดักจับ ไม่สามารถต้านทานได้หยิบแก้วไวน์หวานนั้นขึ้นมา——"
  },
  Event_7022_Name = {
    Text = "ไวน์หวานจากผึ้ง"
  },
  Event_7023_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7023_Desc = {
    Text = "คุณพยายามตรวจสอบประตูบานนี้ เมื่อสัมผัสแล้ว ประตูบานนั้นกลับหายไป เสียงบางอย่างที่ถูกเปิดดังมาจากที่ไกลๆ"
  },
  Event_7023_Name = {
    Text = "ประตูประหลาด"
  },
  Event_7024_ChoiceDesc1 = {
    Text = "【ปล่อยไว้เฉยๆ】"
  },
  Event_7024_ChoiceDesc2 = {
    Text = "【เช็ดรอยฝ่ามือ】"
  },
  Event_7024_Desc = {
    Text = "สำนักงานของฟรานซิสเย็นและเรียบร้อย แสดงให้เห็นถึงความใส่ใจของเจ้าของ\nในกล่องมุมหนึ่ง คุณพบรอยฝุ่นขนาด 5 นิ้วที่มีลักษณะแปลกๆ\nรูปแบบของรอยมือมีความแปลกประหลาด—เส้นขอบด้านนอกดูเหมือนรอยเท้าของสัตว์ร้าย ในขณะที่ตรงกลางกลับมีรอยมือของเด็กหญิงตัวเล็กๆ ประดับอยู่ เหมือนกับว่ามีรอยมือของมนุษย์ก่อน แล้วจึงมีมือขนาดใหญ่ของสัตว์ร้ายปกคลุมไว้\nแน่นอนว่าคุณสามารถจินตนาการถึงภาพที่อบอุ่น เช่น สัตว์ร้ายที่เชื่องซึ่งวางกรงเล็บไว้บนหลังมือของเด็กหญิง เพื่อมอบการปลอบประโลมอย่างอ่อนโยน\nแต่คุณรู้ความจริง—นั่นเป็นรอยที่ทิ้งไว้โดยมอนสเตอร์ที่ถูกทดลองอย่างโหดร้ายจนกลายเป็นหนึ่งเดียวกัน。"
  },
  Event_7024_Name = {
    Text = "รอยเท้าสัตว์ยักษ์"
  },
  Event_7025_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7025_Desc = {
    Text = "ร่างทดลองที่เร่ร่อนไปมาได้ทำให้คุณรู้สึกเหนื่อยล้าแล้ว การหายใจอย่างสั้นๆ ก็เหมือนกับน้ำฝนในทะเลทรายที่แห้งแล้ง。"
  },
  Event_7025_Name = {
    Text = "ประตูไม่รู้จบ"
  },
  Event_7026_ChoiceDesc1 = {
    Text = "【เจ้าของ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7026_ChoiceDesc2 = {
    Text = "【พาสิ่งนั้นไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7026_ChoiceDesc3 = {
    Text = "【แกะมันออก】ได้รับ 50 รอยดำ"
  },
  Event_7026_Desc = {
    Text = "คุณกำลังเดินไปข้างหน้า ขากรรเชียงได้เตะโดนสิ่งของอย่างหนึ่ง\nนั่นคือเข็มทิศที่มีฝาแก้วแตกไปแล้ว ส่วนที่เหลือยังเปื้อนเมือก D คุณค่อยๆ พลิกมันกลับไป และเห็นตราสัญลักษณ์ของมหาวิทยาลัยมิซากะที่แกะสลักอยู่ด้านหลังอย่างไม่ชัดเจน。"
  },
  Event_7026_Name = {
    Text = "การเลือกของเธอ"
  },
  Event_7027_ChoiceDesc1 = {
    Text = "【อ่านจดหมาย】ลบการ์ดคำสั่ง 1 ใบ ได้รับ Arg1 รอยดำ"
  },
  Event_7027_ChoiceDesc2 = {
    Text = "【ปิดกล่องให้ดี】"
  },
  Event_7027_Desc = {
    Text = "หนึ่งฉบับ สองฉบับ อีกหนึ่งฉบับ。\nกระดาษเขียนจดหมายเต็มไปด้วยอดีตของคุณ และยังบรรยายถึงอนาคตของคุณอีกด้วย ด้วยความหลงใหลที่แปลกประหลาด คุณไม่สามารถหยุดการฉีกขาดและกลืนกินกระดาษเขียนจดหมายได้。\n「เฮ้? คุณกำลังบ้าทำไมอีกแล้ว? ดื่มอากาศ?」\nเมอร์ฟี่เตะคุณออกจากภาพหลอน ทำให้คุณกลับมาสู่สติ และเมื่อหันไปดูข้างหน้า ก็ไม่มีอะไรอยู่ตรงนั้นเลย。"
  },
  Event_7027_Name = {
    Text = "จดหมายไม่ทันรู้เรื่อง"
  },
  Event_7028_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_7028_Desc = {
    Text = "เมื่อได้ยินเสียงคุณ เงาคนนั้นก็หยุดลง เสียงของคลีเมนไทน์ทะลุผ่านม่านหมอกน้ำมาถึง.\n「เป็นคุณนี่เอง,」เสียงของเธอพร่าเลือน ราวกับแสงจันทร์ที่ละลายในน้ำ,「ไม่ต้องกังวล คุณจะไม่เป็นอะไร เขาคิดอยากทำ แต่เขาทำไม่ได้.」\n「เมื่อคุณจบการงานที่นี่แล้ว เราจะพบกันอีกครั้ง.」"
  },
  Event_7028_Name = {
    Text = "รูปร่างในหมอก"
  },
  Event_7029_ChoiceDesc1 = {
    Text = "【ผู้รับ：แผนกการเรียนการสอน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_7029_ChoiceDesc2 = {
    Text = "【ผู้รับ：พาร์ทเนอร์】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_7029_Desc = {
    Text = "ในขณะที่คุณเขียนชื่อผู้รับ กระดาษเขียนจดหมายก็ลอยขึ้นพร้อมกับควันหนา มือที่มองไม่เห็นทะลุผ่านอากาศและแย่งกระดาษเขียนจดหมายจากมือคุณอย่างรุนแรง——\nเสียงที่คล้ายกับการเคี้ยวดังขึ้น และร่างกายของคุณก็รู้สึกหนักหน่วงขึ้นในทันที。\nแต่สิ่งที่อยู่ในมือบอกคุณว่า การเดินทางในครั้งนี้ก็ไม่ใช่ว่าจะไม่ได้รับผลตอบแทนอะไรเลย。"
  },
  Event_7029_Name = {
    Text = "การสารภาพเดียวดาย"
  },
  Event_7030_ChoiceDesc1 = {
    Text = "【ใส่กุญแจเงิน】"
  },
  Event_7030_Desc = {
    Text = "ในเมือก D ที่อิ่มตัวเกินไปดูเหมือนจะซ่อนสารบางอย่าง... ใช้กุญแจเงินในการสังเกต แล้วเปลี่ยนมันให้กลายเป็นพละกำลังของตนเองเถอะ。"
  },
  Event_7030_Name = {
    Text = "จุดแยก"
  },
  Event_7031_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7031_Desc = {
    Text = "รอให้พวกเขาปรากฏตัวจากเงามืดนั่นแหละ"
  },
  Event_7031_Name = {
    Text = "โคมไฟหงส์ดำ"
  },
  Event_7032_ChoiceDesc1 = {
    Text = "【เรียกอีกา】ได้รับ 35 รอยดำ ได้รับผล「(Skill.Arg2)」 เลือกต่อไป"
  },
  Event_7032_ChoiceDesc2 = {
    Text = "【ออกห่างไปไกล】"
  },
  Event_7032_Desc = {
    Text = "นกสีดำสนิทได้รับการเรียกร้อง ร่างกายของพวกมันขยายตัว และคายบางสิ่งลงในมือของคุณ \n พวกมันโบกปีกกลับไปยังเสาอย่างรวดเร็ว จ้องมองคุณด้วยสายตาที่ร้อนแรง。"
  },
  Event_7032_Name = {
    Text = "กุยบินโดดเดี่ยว"
  },
  Event_7033_ChoiceDesc1 = {
    Text = "【เข้าถ้ำ】"
  },
  Event_7033_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7033_Desc = {
    Text = "「เฮก, เฮก...」\nเสียงคุ้นเคยมาก...นึกออกแล้ว!\nเมื่อมนุษย์ป่วยหรือใกล้ตายจะส่งเสียงแบบนี้!\nรีบไปดูเถอะ!"
  },
  Event_7033_Name = {
    Text = "ความลึกของถ้ำ"
  },
  Event_7034_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7034_Desc = {
    Text = "คุณเคยเรียนรู้เกี่ยวกับความรู้ทั้งหมดเกี่ยวกับเงินใจ รวมถึงวิธีการระบุระดับของมัน \n ชัดเจนว่า เงินใจเหล่านี้ไม่สามารถตอบสนองความต้องการพื้นฐานในการกลั่นได้ \n คุณจำเป็นต้องปล่อยพวกมัน รวมถึงวิญญาณที่อาจติดอยู่ในนั้นด้วย \n การเรียนรู้ที่จะปล่อยวางก็เป็นบทเรียนที่จำเป็นสำหรับผู้พิทักษ์ด้วยเช่นกัน。"
  },
  Event_7034_Name = {
    Text = "วิญญาณที่ถูกผูกมัด"
  },
  Event_7035_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7035_Desc = {
    Text = "นี่คือทางเดินทางเดียว คุณไม่สามารถกลับไปยังทางเข้าได้"
  },
  Event_7035_Name = {
    Text = "ทางผ่าน"
  },
  Event_7036_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7036_Desc = {
    Text = "เสร็จเร็ว ใจก็สบายเร็ว นักสืบจากมิซากะไม่เคยกลัวอันตราย"
  },
  Event_7036_Name = {
    Text = "ประตูไม่รู้จบ"
  },
  Event_7037_ChoiceDesc1 = {
    Text = "【กรุณาหลีกทางให้หน่อย ผมมีเรื่องด่วน】"
  },
  Event_7037_ChoiceDesc2 = {
    Text = "【ยินดีรับฟังรายละเอียด】"
  },
  Event_7037_Desc = {
    Text = "「นักเรียนท่านนี้ กรุณาหยุดก่อน ดูจากสีหน้าของพวกคุณดูเคร่งเครียดและรีบร้อน อาจจะตกอยู่ในสถานการณ์ที่ลำบากบางอย่างใช่ไหม \n แต่ชีวิตไม่ควรที่จะยอมแพ้ต่อมุมมองทั้งหมดและสติที่เย็นชาด้วยเหตุการณ์ที่เกิดขึ้นในขณะนี้ \n เช่นเดียวกับที่ฉันได้คิดอย่างจริงจังในช่วงไม่กี่วันที่ผ่านมา ในตำนานของเคอร์เบรอสมีหลายจุดที่ไม่ตรงกับสถานการณ์ปัจจุบัน」"
  },
  Event_7037_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅱ"
  },
  Event_7038_ChoiceDesc1 = {
    Text = "【รับของขวัญ】"
  },
  Event_7038_ChoiceDesc2 = {
    Text = "【ปฏิเสธอย่างสุภาพ】"
  },
  Event_7038_Desc = {
    Text = "เด็กชายนั่งอยู่ที่ขอบหน้าต่างมองคุณ เขารอคุณมานานแล้ว \n「การแสดงประสบความสำเร็จ ขอบคุณนะ」 \n「ฉันจะต้องไปแล้ว... นี่คือของขวัญสำหรับคุณ」 \nเด็กชายยื่นมือออกมาให้คุณ \nคุณเห็นกล่องของขวัญที่ห่ออย่างสวยงาม เลือดไหลออกมาจากกล่อง ทำให้มือของเด็กชายเปื้อนแดง。"
  },
  Event_7038_Name = {
    Text = "พิธีปิดฉาก Ⅵ"
  },
  Event_7039_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7039_Desc = {
    Text = "ขอให้คุณมีความมั่นใจแบบนี้ตลอดไป"
  },
  Event_7039_Name = {
    Text = "ภาพสะท้อนไร้รูปทรง"
  },
  Event_7040_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7040_Desc = {
    Text = "คุณรับเอาหูเล็กๆ ที่นุ่มนิ่มนี้ไว้\nมันถูกห่อหุ้มอยู่ในน้ำมันขี้ผึ้งเหนียวๆ นอนอยู่กลางฝ่ามือของคุณอย่างเงียบๆ\nในใจของคุณเกิดความรู้สึกรับผิดชอบอย่างรุนแรง\nอันดับแรก บาร์ไม่สามารถไปได้ตามสบาย ที่นั่นมีเสียงดนตรีที่ยุ่งเหยิงเกินไป\nอันดับสอง โรงละครวิลลิงตันก็ไม่สามารถไปได้ ที่นั่นมีวงออเคสตร้าที่เก่าแก่แล้ว\nแล้ว...\nคุณและเพื่อนๆ ของคุณยอมรับความจริงที่ว่าคุณมีสัตว์เลี้ยงตัวเล็กเพิ่มขึ้นอย่างดี。"
  },
  Event_7040_Name = {
    Text = "เอียงหูฟัง"
  },
  Event_7041_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7041_Desc = {
    Text = "「ศาสตราจารย์อลิสเตอร์เป็นเสาหลักของมิซากะ ถ้าไม่มีเขา ระบบทั้งหมดของมิซากะจะหยุดทำงาน」\n คุณจำได้เลือนรางว่าในชั้นเรียนที่ทำให้คุณง่วงนอนนั้น ชอร์ททำหน้าตึงเครียดและเคาะกระดานดำพูดประโยคนี้ออกมา\n ถ้าเสาหลักนี้พังทลายเป็นชิ้นเล็กชิ้นน้อย คุณจะอยู่ยังไง? ความกลัวอันมหาศาลปกคลุมคุณ\n 「เธอจะไปไหน?」เสียงเรียกของราโมน่าดึงคุณกลับสู่ความเป็นจริง\n นั่นคืออดีตหรืออนาคต เป็นความจริงหรือจินตนาการ หรือเป็นความฝันจากมิติอีกมิติหนึ่ง? คุณก็ไม่รู้แล้ว\n ในมือของคุณ มี「ของขวัญ」ปรากฏขึ้น。"
  },
  Event_7041_Name = {
    Text = "เสียงครวญของความวุ่นวาย"
  },
  Event_7042_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7042_Desc = {
    Text = "「เก้าอี้รถเข็นนี้คือขาอีกข้างของฉัน ฉันคงจะไม่สามารถแยกจากมันได้ในชีวิตนี้」 ศาสตราจารย์อลิสเตอร์ยิ้มอย่างขมขื่น「น่าเสียดายที่มันทำให้ฉันตัวเตี้ยลงมาก」 \n\n ดังนั้น นี่จึงไม่อาจเป็นศาสตราจารย์อลิสเตอร์ตัวจริงได้。"
  },
  Event_7042_Name = {
    Text = "เสียงครวญของความวุ่นวาย"
  },
  Event_7043_ChoiceDesc1 = {
    Text = "【ใครกำลังพูด?】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7043_ChoiceDesc2 = {
    Text = "【วิสกี้อะไรนั่น ให้ฉันลองชิมด้วย】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7043_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7043_Desc = {
    Text = "「คุณไม่ลองชิมสักคำเหรอ? นี่คือวิสกี้ชั้นดีนะ ถ้าไม่ใช่เพราะเจ้าของบาร์ใจดีให้ฉันทั้งขวด ฉันคงไม่ยอมแบ่งแม้แต่หยดเดียวให้เธอดื่มหรอก」\n「ดังนั้น เธอช่วยเขาขับไล่ผู้ชายที่ผอมแห้ง ร่างกายตึงเหมือนยาง และดื่มแต่ Bloody Mary ออกไป นี่คือค่าตอบแทนทั้งหมดที่เจ้าของบาร์ให้เธอ สำหรับการสอบสวนครั้งนั้น เธอใช้เวลาไปหนึ่งเดือน เยี่ยมชมสามสิบบ้าน และถูกปฏิเสธสิบเอ็ดครั้ง ใช้กระสุนปืนลูกโม่ไปสิบเจ็ดนัด หนึ่งขวดวิสกี้ เธอไม่สามารถได้เงินคืนเลย」\n「เอาล่ะ เอาล่ะ ไม่ต้องคิดมากขนาดนั้นหรอก อย่างน้อยตอนนี้ เราก็มีวิสกี้ขวดนี้ใช่ไหม?」"
  },
  Event_7043_Name = {
    Text = "เศษความทรงจำ·วิสกี้"
  },
  Event_7044_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7044_Desc = {
    Text = "คุณจับหนวดสัมผัสของร่างที่ถูกปลุก เขาหันกลับมามองคุณ สายตาของเขาเปล่งประกายแสงที่ไม่ชัดเจน\nเขาไม่ได้พูดอะไร แต่คุณกลับเข้าใจคำพูดที่เขาซ่อนอยู่——\n「การละเมิด」"
  },
  Event_7044_Name = {
    Text = "เอฟเฟกต์ผีเสื้อ"
  },
  Event_7045_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7045_Desc = {
    Text = "เครื่องโทรเลขเสียหายไปอย่างสิ้นเชิง คุณสามารถจินตนาการถึงความสิ้นหวังของเจ้าของเครื่องโทรเลขในพายุได้หรือไม่... เพราะตอนนี้คุณก็เป็นเช่นนั้น。"
  },
  Event_7045_Name = {
    Text = "ของพื้นเพของผู้ล่วงลับ"
  },
  Event_7046_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7046_Desc = {
    Text = "ชื่อ：ลีห์\nอายุ：20\nภาวะแทรกซ้อน：โรคกระหายนองเลือดพร้อมกับฮิสทีเรียอย่างรุนแรง\nสิ่งแปลกปลอม：หนวดสีแดงเข้ม@2อวัยวะปาก\nอวัยวะที่ปลูกถ่าย：เนื้อเยื่ออวัยวะที่เป็นญาติสายตรง@3\nเหตุผลในการโอน：ไม่มีเหตุผลพิเศษอะไร ฉันไม่ชอบเธอ\n(เนื้อหาหลังจากนี้ถูกขีดฆ่า)"
  },
  Event_7046_Name = {
    Text = "การลงทะเบียนอวัยวะ"
  },
  Event_7047_ChoiceDesc1 = {
    Text = "【เลือก「รับพร」】สูญเสียรอยดำทั้งหมด ได้รับสิ่งสร้างทองคำ 1 ชิ้น。"
  },
  Event_7047_Desc = {
    Text = "ก้อนโคลนดำปรากฏขึ้นต่อหน้าคุณ สั่นเทาๆ ส่งเอกสารมาให้\n「ตอนนี้ฉันไม่สะดวกออกมา... แต่คุณสามารถทำความรู้จักกับบริการที่เราปรับแต่งได้...」\nเสียงหญิงลอยออกมาจากทรวงอกของโคลนดำ ฟังดูตื่นตระหนกเล็กน้อย เหมือนกำลังหลบหลีกอะไรบางอย่าง\n「พรจากนางฟ้าใช้ได้ตามระดับสมาชิก รับรองว่าไม่มีการโกง」\n「เซ็นเร็วๆ!」"
  },
  Event_7047_Name = {
    Text = "พรแห่งนางฟ้า"
  },
  Event_7048_ChoiceDesc1 = {
    Text = "【ฟังอย่างตั้งใจ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」, ถูกโจมตีด้วย「(Skill.Arg2)」"
  },
  Event_7048_ChoiceDesc2 = {
    Text = "【ตรวจสอบ】ร่างกายที่ตื่นขึ้นทั้งหมดฟื้นฟูความคลั่ง 50，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7048_ChoiceDesc3 = {
    Text = "【ออกจากที่ตรงนี้ทันที】เลือก 1 การแกะสลักจากทั้งหมด 3 แบบ"
  },
  Event_7048_Desc = {
    Text = "「คุณรู้ไหม?」ในขณะที่รามอน่ากำลังมองหาตัวตนของคนลึกลับ เสียงหนึ่งก็ดังขึ้นอย่างกะทันหัน เหมือนมีใครบางคนกำลังพูดคุยกันเบาๆ，「คุณรู้เรื่องนั้นไหม? เรื่องใหญ่ๆ นั่นน่ะ?」"
  },
  Event_7048_Name = {
    Text = "หูของผู้อื่น"
  },
  Event_7049_ChoiceDesc1 = {
    Text = "【โฟกัส】ลบการ์ดอาการได้สูงสุด 2 ใบ。"
  },
  Event_7049_ChoiceDesc2 = {
    Text = "【การตื่นรู้】เลือกปลุกผู้ตื่น 1 ตน。"
  },
  Event_7049_ChoiceDesc3 = {
    Text = "【เชื่อมต่อ】คืนค่า Arg2 จุดชีวิต。"
  },
  Event_7049_Desc = {
    Text = "คุณกำลังสำรวจในหมอกหนา ทันใดนั้น เข็มกลัดที่หน้าอกก็ปล่อยแสงสีเงินอ่อนๆ อะไรคือเสียงที่เรียกคุณจากอีกฝั่งของเครื่องสื่อสาร?"
  },
  Event_7049_Name = {
    Text = "จุดติดต่อ"
  },
  Event_7050_ChoiceDesc1 = {
    Text = "【ระมัดระวัง】เพิ่มพลังชีวิตสูงสุด Arg1 หน่วย"
  },
  Event_7050_ChoiceDesc2 = {
    Text = "【ก้าวเข้าหา】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7050_Desc = {
    Text = "เงาที่เกิดจากดินแดนลับแลยื่นมือออกมาหาคุณ รูปร่างดูพร่ามัว。\nคุณจำได้ว่ามีนักสืบมิซากะคนหนึ่งขึ้นมาอยู่บนเรือลำนี้ จะเป็นเขาหรือเปล่า?\nหรือว่าแค่ความทรงจำที่น่าสงสารอีกหนึ่งที่ถูกตรึงอยู่ในดินแดนลับแล。"
  },
  Event_7050_Name = {
    Text = "ผู้ใช้กุญแจเงิน"
  },
  Event_7051_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7051_Desc = {
    Text = "「ดูสิ เพราะคำพูดเล่นๆ ของฉัน ทำให้มองข้ามสถานการณ์ที่เร่งด่วนที่สุด เรื่องนี้ไม่ดีเลย \n ถ้าชักช้าไปอีกเหยื่อของพวกคุณก็จะหนีไปไกลแล้ว \n เพื่อแสดงความขอโทษ สิ่งเหล่านี้ก็ขอมอบให้พวกคุณนะ」 \n\n ผู้ชายพูดคนเดียวแล้วเปลี่ยนเรื่อง ส่งของบางอย่างให้พวกคุณ。"
  },
  Event_7051_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅱ"
  },
  Event_7052_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7052_Desc = {
    Text = "「ขอให้คุณสมหวังในสิ่งที่ปรารถนา。」\n ชายคนนั้นไม่ได้สนใจมากนัก และขยับตัวเพื่อหลีกทาง。"
  },
  Event_7052_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅱ"
  },
  Event_7053_ChoiceDesc1 = {
    Text = "【เก็บเข้ากระเป๋า】"
  },
  Event_7053_Desc = {
    Text = "สารสีเงินที่มีลักษณะใกล้เคียงกับปรอท สกัดจากน้ำเมือกการย่อยสลาย มีพลังจิตที่เข้มแข็ง ใช้หลักในการลิงก์ผู้ปลุกตื่นมากขึ้นในพิธีกรรม。"
  },
  Event_7053_Name = {
    Text = "เงินใจ"
  },
  Event_7054_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7054_Desc = {
    Text = "คุณได้เดินเข้าสู่ทางแยกใหม่อีกครั้ง \n ดวงอาทิตย์ขึ้นตามปกติ มนุษย์ตายตามปกติ และคุณหลงทางตามปกติ \n ไม่มีอะไรที่แปลกใหม่。"
  },
  Event_7054_Name = {
    Text = "เขาวงกตของตา"
  },
  Event_7055_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7055_Desc = {
    Text = "นั่นดูเหมือนเป็นเงาที่บิดเบี้ยวเพราะแสงหักเห"
  },
  Event_7055_Name = {
    Text = "วัตถุลอยในถัง"
  },
  Event_7056_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7056_Desc = {
    Text = "คุณหันหลังกลับไป เพียงเห็นรองเท้าหนังคู่หนึ่งที่โดดเดี่ยว \n「ขอโทษนะ ฉันไม่มีเจตนาร้าย」\n「ถ้าคุณเห็นร่างกายของฉัน กรุณาช่วยบอกให้มันรู้ว่าคู่หูที่ซื่อสัตย์ที่สุดกำลังรออยู่ที่ตู้แสดงหมายเลข 45 ในห้องนิทรรศการหมายเลข 1」\n「——จำไว้ว่าคู่นั้นทำจากหนังวัว ไม่ใช่หนังแพะ」"
  },
  Event_7056_Name = {
    Text = "รองเท้าออกซฟอร์ด"
  },
  Event_7057_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7057_Desc = {
    Text = "ต้องเป็นรุ่นพี่แน่ๆ——คุณยื่นแขนออกไปหาเขา แต่สิ่งที่ตามมาก็คือความเจ็บปวดที่น่าสยดสยอง\nเมื่อความเจ็บปวดหายไป แขนขากลับมีพลังมากขึ้นอย่างที่ไม่เคยมีมาก่อน。"
  },
  Event_7057_Name = {
    Text = "ผู้ใช้กุญแจเงิน"
  },
  Event_7058_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7058_Desc = {
    Text = "คุณรู้สึกว่าหมอกตรงหน้าดูจางลงแล้ว\n\nคุณรู้สึกว่าในการกระทำต่อไป ทัศนวิสัยของคุณจะคมชัดขึ้น"
  },
  Event_7058_Name = {
    Text = "การทดสอบซูรา"
  },
  Event_7059_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7059_Desc = {
    Text = "ภาพลวงตาก็เข้ามาหาคุณ，ความทรงจำกลับมาอย่างฉับพลัน，ทุกอย่างตรงหน้าชัดเจน。"
  },
  Event_7059_Name = {
    Text = "ฟ้ามอร์กานา"
  },
  Event_7060_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7060_Desc = {
    Text = "สิ่งที่ไม่รู้ตัวของพระองค์ยังคงเปลี่ยนแปลงบางสิ่งในความลึกลับ"
  },
  Event_7060_Name = {
    Text = "การจ้องมองของพระองค์"
  },
  Event_7061_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7061_Desc = {
    Text = "สถานการณ์วิกฤต ตอนนี้ไม่ใช่เวลาที่จะสะสมเงินใจ。"
  },
  Event_7061_Name = {
    Text = "การพิสูจน์การมีอยู่"
  },
  Event_7062_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์เงิน 3 ตัวเลือก 1, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7062_Desc = {
    Text = "ร่างเงามัวค่อยๆ ชัดเจนขึ้น นั่นไม่ใช่ตัวดูดซับหรือตัวภัยพิบัติ แต่มันคือเคลเมนไทน์ที่ไม่มีปีกและแสดงสีหน้าสงบนิ่ง\n「บังเอิญจริงๆ นะ คุณก็มาเดินชื่นชมแสงจันทร์เหมือนกันเหรอ?」เธอกล่าวด้วยรอยยิ้ม แต่มันทำให้คุณรู้สึกเวียนหัวอย่างไร้เหตุผล\n「ในค่ำคืนที่เต็มไปด้วยหมอกหนา ยังไงก็ควรระวังตัวให้มากเถอะ\n「พวกตัวเล็กๆ ที่อยู่แถวนี้ ไม่ค่อยจะอยู่นิ่งเท่าไหร่」"
  },
  Event_7062_Name = {
    Text = "รูปร่างในหมอก"
  },
  Event_7063_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7063_Desc = {
    Text = "เสียงแตกของชิ้นส่วนปูนปลาสเตอร์ที่ตกลงสู่พื้นทำให้ร่างกายของเธอแตกสลาย เสียงคำรามที่ไม่ยอมแพ้เต็มไปด้วยหัวใจของคุณ แต่โชคดีที่คุณหยุดทันเวลา。"
  },
  Event_7063_Name = {
    Text = "เสริมสร้างร่างกายที่เสียหาย"
  },
  Event_7064_ChoiceDesc1 = {
    Text = "【รับฟังความเศร้า】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7064_ChoiceDesc2 = {
    Text = "【เพลิดเพลินกับความสุข】ทุกครั้งที่มีร่างกายที่ตื่นขึ้นที่มีค่าความคลั่ง 50 หรือมากกว่า จะได้รับ 15 รอยดำ"
  },
  Event_7064_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_7064_Desc = {
    Text = "เสียงเพลงที่ไพเราะ อ่อนหวาน เต็มไปด้วยความสุข และความเศร้า... ทำนองดังก้องอยู่ในดินแดนลับแล ยากที่จะบอกได้ว่ามันมาจากไหน \n นี่คือซิมโฟนีที่ไหลออกมาจากเรือผี หรือว่าเป็นความเพ้อฝันในยามค่ำคืนที่ถูกผูกมัดอยู่ในดินแดนลับแล?"
  },
  Event_7064_Name = {
    Text = "เสียงไม่รู้ชื่อ"
  },
  Event_7065_ChoiceDesc1 = {
    Text = "【พวกเขาอยู่ในระหว่างการตามหาใครบางคน】ลบการ์ดคำสั่ง 1 ใบ รับ 25 รอยดำ"
  },
  Event_7065_ChoiceDesc2 = {
    Text = "【พวกเขากำลังค้นหาบางสิ่ง】คัดลอกการ์ดจากกอง เพิ่มสถานะ 「(Skill.Arg1)」"
  },
  Event_7065_Desc = {
    Text = "ทำไมผู้ศรัทธาแห่งโคมไฟถึงปรากฏตัวขึ้นอย่างกะทันหันที่เมืองเล็ก ๆ ของลาอี? ที่นี่มีปริศนามากมายเกินไป。\nสุนัขแห่งนรกเคอร์เบรอส，ผู้อำนวยการโรงพยาบาลจิตเวชลาอีฟรานซิส，สมาคมนักประติมากรรม，โบสถ์แห่งตะเกียง……\nต้องมีแหล่งที่มาบางอย่างที่รวมพวกเขาไว้ในเมืองเล็ก ๆ ที่ไม่ค่อยมีผู้คนนี้。\nเครื่องพิมพ์ดีดจู่ ๆ ก็พ่นหมึกออกมาเอง ราวกับว่าชวนให้คุณไปพิมพ์อะไรบางอย่าง。"
  },
  Event_7065_Name = {
    Text = "วิธีการป้อนข้อมูลลึกลับ"
  },
  Event_7066_ChoiceDesc1 = {
    Text = "【หลับตาแน่น】"
  },
  Event_7066_ChoiceDesc2 = {
    Text = "【หลบหนีจากที่เกิดเหตุ】"
  },
  Event_7066_Desc = {
    Text = "การแสดงหยุดลงอย่างกระทันหัน คุณมองไปรอบ ๆ และพบว่ามีผู้ชมเต็มไปหมดที่นั่งข้าง ๆ คุณ \n พวกเขามีใบหน้าที่เหมือนกับเด็กชาย กำลังจ้องมองคุณอย่างพร้อมเพรียง \n อา—— \n พวกเขาเปิดปากดำมืดออกมาอย่างเงียบ ๆ。"
  },
  Event_7066_Name = {
    Text = "พิธีจงมู่หลี่Ⅴ"
  },
  Event_7067_ChoiceDesc1 = {
    Text = "【หยิบรูปภาพ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_7067_ChoiceDesc2 = {
    Text = "【ตรวจสอบฟิล์ม】ติดเชื้อ「(Skill.Arg1)」，เปลี่ยนการแกะสลักที่ได้รับจากตัวเลือก 1 สามารถใช้งานได้อีกครั้งหนึ่ง"
  },
  Event_7067_Desc = {
    Text = "คุณวางฟิล์มไว้ใต้แสงไฟสีแดงสลัว ฐานฟิล์มกึ่งโปร่งใสเผยให้เห็นภาพที่เลือนราง \nมือ เท้า ลูกตา อวัยวะภายใน... รวมถึงอวัยวะในร่างกายทั้งหมดที่คุณสามารถจินตนาการได้และไม่สามารถจินตนาการได้ ถูกบันทึกไว้อย่างซื่อสัตย์ในฟิล์ม \nพวกมันถูกล้างอย่างพิถีพิถัน จัดเรียงอย่างเป็นระเบียบ ราวกับบทกวีที่คุณเขียนขึ้นเป็นครั้งแรก。"
  },
  Event_7067_Name = {
    Text = "บันทึกอย่างซื่อสัตย์"
  },
  Event_7068_ChoiceDesc1 = {
    Text = "【องครักษ์ของเจ้าหญิง】การตื่นรู้แบบสุ่ม 1 ร่างกายที่ตื่นขึ้น ได้รับผลกระทบ「(Skill.Arg1)」"
  },
  Event_7068_ChoiceDesc2 = {
    Text = "【ผู้ครุ่นคิด】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7068_Desc = {
    Text = "「ตุบ ตุบ ตุบ......」\nเสียงฝีเท้าจากไกลเข้ามาใกล้ขึ้นเรื่อยๆ เห็นว่าใครบางคนกำลังจะผลักประตูสตูดิโอเปิดออก \nพวกคุณไม่มีทางถอยแล้ว นอกจากจะอิงแสงสลัวๆ แกล้งทำเป็นหุ่นขี้ผึ้ง หวังว่าจะหลบเลี่ยงสายตาที่กำลังตรวจสอบ。"
  },
  Event_7068_Name = {
    Text = "ทำให้ของปลอมดูเหมือนจริง"
  },
  Event_7069_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7069_Desc = {
    Text = "「เยี่ยมมาก เยี่ยมมาก！」เสียงเต็มไปด้วยความยินดี 「ในที่สุดเธอก็กลายเป็นเหมือนฉันแล้ว คุณพี่สาวซาซา！」"
  },
  Event_7069_Name = {
    Text = "「พี่สาวซาซา」"
  },
  Event_7070_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7070_Desc = {
    Text = "บางทีอาจมีใครสักคนพาพวกเขามาที่นี่ \n เมื่อคุณค้นหาต่อไป ตัวตนของคนคนนั้นจะเผยออกมาในที่สุด"
  },
  Event_7070_Name = {
    Text = "วิธีการป้อนข้อมูลลึกลับ"
  },
  Event_7071_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7071_Desc = {
    Text = "เสร็จเร็ว ใจก็สบายเร็ว นักสืบจากมิซากะไม่เคยกลัวอันตราย"
  },
  Event_7071_Name = {
    Text = "ประตูไม่มีที่สิ้นสุด"
  },
  Event_7072_ChoiceDesc1 = {
    Text = "【เลือกศีลธรรม】ฟื้นฟูพลังชีวิต Arg1 หน่วย"
  },
  Event_7072_ChoiceDesc2 = {
    Text = "【เลือกชีวิต】ฟื้นฟูพลังชีวิตทั้งหมด ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7072_Desc = {
    Text = "คุณอาจเคยมีหัวใจที่เหมือนทองคำสักดวงหนึ่ง \n มันเต้นไม่หยุดตลอดทั้งวันทั้งคืน เพื่อชีวิตและการมีชีวิตของคุณอย่างสุดความสามารถ...อบอุ่น ร้อนแรง และเต็มไปด้วยความหวัง \n แต่ไม่รู้ว่าเมื่อไหร่ มันกลับเริ่มช้าลง เหมือนกับชีวิตและจริยธรรม มันสามารถรับภาระได้เพียงหนึ่งเดียวเท่านั้น..."
  },
  Event_7072_Name = {
    Text = "คำสาปกระหาย"
  },
  Event_7073_ChoiceDesc1 = {
    Text = "【หยิบรูปภาพ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_7073_ChoiceDesc2 = {
    Text = "【ตรวจสอบฟิล์ม】ติดเชื้อ「(Skill.Arg1)」，เปลี่ยนการแกะสลักจากตัวเลือก 1 ใช้ได้ 2 ครั้ง"
  },
  Event_7073_Desc = {
    Text = "「ดังนั้น คุณได้บันทึกทุกอย่างอย่างซื่อสัตย์」\n「ใช่ ฟิล์มคือความจริง」\nเสียงสนทนาหยุดชะงักลง ตาไร้รูปร่างนับไม่ถ้วนจ้องมาที่คุณพร้อมกัน ราวกับกำลังรอคำตัดสินสุดท้ายจากคุณ。"
  },
  Event_7073_Name = {
    Text = "คำให้การของพยาน"
  },
  Event_7074_ChoiceDesc1 = {
    Text = "【ออก】เพิ่ม Arg1 จุดชีวิต และได้รับ 25 รอยดำ"
  },
  Event_7074_Desc = {
    Text = "เสียงเรียกของคุณถูกเสียงเห่าหอนของวายุกลืนกิน。\n「คุณไม่จำเป็นต้องรู้จักฉัน」 เสียงซ่าๆ ที่แทรกอยู่ในประโยคชัดเจนขึ้นเรื่อยๆ，「เฮอร์เบิร์ต เฮอร์เบิร์ตคือคนที่พวกคุณกำลังตามหา ปล่อยให้เจ้าคนนั้นตกลงไปจากภาพลวงตาที่ผิดๆ สู่ความเป็นจริงที่โหดร้ายและเย็นชา」\n「ฉันจะพรให้พวกคุณ พรให้พวกคุณได้ลิ้มรสสิ่งที่อร่อยที่สุดในโลกนี้...」"
  },
  Event_7074_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅵ"
  },
  Event_7075_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，รับสถานะ「(Skill.Arg2)」"
  },
  Event_7075_Desc = {
    Text = "「ใช่แล้ว ผู้สูญหายที่น่าสงสาร ผู้มีพละกำลังแต่ไม่สามารถรู้จักตัวเองได้。\nคุณจะช่วยเหลือเขาหรือจะยกอาวุธขึ้นต่อสู้กับพระองค์?」\nผู้ชายกระโดดลงไปในกระแสน้ำที่เชี่ยวกราก ในช่วงที่เขากระโดดลง คุณได้สบตากับเขาอย่างพอดี นั่นคือดวงตารูปทรงกลมสีทองเหมือนน้ำผึ้งที่หยดลง ซึ่งเป็นของงู。\nและที่ตำแหน่งที่เขายืนอยู่เมื่อสักครู่ มีโคมไฟเล็กๆ ที่ปล่อยควันสีม่วงอยู่。"
  },
  Event_7075_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅵ"
  },
  Event_7076_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7076_Desc = {
    Text = "「ความระมัดระวังเป็นคุณธรรม แต่ความระมัดระวังที่มากเกินไปกลับเป็นสิ่งที่ไม่เหมาะสม」 เสียงที่เรียบเฉยและไม่เปลี่ยนแปลงแฝงไปด้วยความไม่พอใจ 「การเคลื่อนที่ของดวงดาวจะรบกวนต้นกำเนิดของผู้ปลุกตื่นที่กำลังหลับไหล และช่วงเวลาที่เหมาะสมสามารถทำให้ความอาลีมัสของพวกเขาขยายตัวอย่างรวดเร็วเหมือนกับการเป่าบอลลูน สรุปแล้ว ตอนนี้ยังมีเวลาในการคว้าหางของดาวหาง ครั้งหน้าจงจำไว้ว่าให้ปรับปรุงความเร็วในการตอบสนองของคุณที่ไม่ต่างอะไรกับเต่าด้วย」"
  },
  Event_7076_Name = {
    Text = "มุมยก"
  },
  Event_7077_ChoiceDesc1 = {
    Text = "【ตอบกลับ】ความเครียดในปัจจุบันลดลงครึ่งหนึ่ง。"
  },
  Event_7077_Desc = {
    Text = "คุณสัมผัสกับห้องปรับความดัน สามารถฟื้นฟูค่าความดันปัจจุบันได้"
  },
  Event_7077_Name = {
    Text = "จุดเสถียรภาพความดัน"
  },
  Event_7078_ChoiceDesc1 = {
    Text = "【ปลอบใจเธอ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7078_ChoiceDesc2 = {
    Text = "【ตำหนิเธอ】การ์ดคำสั่ง 3 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7078_Desc = {
    Text = "「ฉันคือเงาของนักสืบที่ตายไป โจรคือกุญแจเงินดอกนั้น。」\nหญิงสาวเจ็บปวดทำท่าหยุดหัวของเธอไว้ ผมของเธอหนาแน่น มีดวงตาแวววาวนับไม่ถ้วนกระพริบอยู่...\n「พวกเขามักพูดว่า: ไม่ได้หรอก ชาร์ล็อตต์! อ่า ชาร์ล็อตต์!\nดังนั้นฉันจึงคิดว่า ถ้าฉันสามารถเชื่อมโยงผู้ปลุกตื่นได้หลายคนในครั้งเดียว ทุกคนคงจะเงียบไป」\n「แล้ว...ฉันก็ไม่รู้ว่าเกิดอะไรขึ้น เมื่อตื่นขึ้นมาฉันก็กลายเป็นแบบนี้ อ่า!」"
  },
  Event_7078_Name = {
    Text = "เงาของนักสืบ"
  },
  Event_7079_ChoiceDesc1 = {
    Text = "【ข้ามกำแพงสูง】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7079_ChoiceDesc2 = {
    Text = "【เข้าไปในเขาวงกต】การ์ด 1 ใบแบบสุ่มได้รับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7079_Desc = {
    Text = "สมองของคุณคือเขาวงกต.\nความคิดมากมายพันกันอยู่ภายใน ทางออกอยู่ในระยะที่สายตาเอื้อมถึง แต่กำแพงสูงแห่งความคิดตั้งตระหง่านขวางกั้นระหว่างคุณกับมัน."
  },
  Event_7079_Name = {
    Text = "เขาวงกตแห่งความคิด"
  },
  Event_7080_ChoiceDesc1 = {
    Text = "【มองภาพลวงตา】ได้รับสิ่งประดิษฐ์เงิน โดยเลือก 1 จาก 3"
  },
  Event_7080_ChoiceDesc2 = {
    Text = "【เข้าใกล้ภาพลวงตา】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」，ถูกโจมตีสองครั้ง「(Skill.Arg3)」"
  },
  Event_7080_Desc = {
    Text = "ดูเหมือนไกลออกไปจะมีภูเขาไฟปะทุ ควันเป็นรูปมนุษย์พุ่งขึ้นในฟ้าลมร้าย \nที่นี่คือแอลวอร์ธ ที่แอลวอร์ธมีเพียงหิมะสูงตระหง่านและถ้ำหินปูนที่กัดเซาะอย่างไม่จบสิ้น \nหรือเหตุการณ์ประหลาดเป็นวันที่ทำให้จิตของเจ้าสับสนไปหรือเปล่า?"
  },
  Event_7080_Name = {
    Text = "ภาพลวงตาของภูเขาไฟ"
  },
  Event_7081_ChoiceDesc1 = {
    Text = "【ฉันเห็นอะไร】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」"
  },
  Event_7081_ChoiceDesc2 = {
    Text = "【ฉันไม่เห็นอะไรเลย】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7081_Desc = {
    Text = "ของเหลวซึมออกจากเบ้าตาของคุณ ความรู้สึกเหนียวแน่นทำให้คุณตกใจ。\nสุดท้ายแล้ว มันเกิดจากสิ่งที่คุณเห็น แต่คุณ——จริงๆ แล้วไม่ได้เห็นอะไรเลยใช่ไหม?"
  },
  Event_7081_Name = {
    Text = "ไม่ควรดูโดยตรง"
  },
  Event_7082_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7082_Desc = {
    Text = "คุณจะมีความสุขและเศร้า แต่ในขณะนี้สิ่งที่จมอยู่ในใจคุณไม่ใช่อารมณ์ของคุณ คุณปิดหูของคุณ กุญแจเงินกระพริบแสงที่เจิดจ้า \n ในที่สุด คุณก็สามารถหายใจได้แล้ว。"
  },
  Event_7082_Name = {
    Text = "การติด"
  },
  Event_7083_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7083_Desc = {
    Text = "ผู้ถือมีดสั้นส่งเสียงร้อง เหมือนนกที่ส่งเสียงโศกระหว่างเที่ยงคืนในสุสาน \n เสียงนั้นหายไปในทันที และผู้เหยียบทะเลอีกสองคนก็หายไปด้วย... ที่แท้เป็นเพียงภาพลวงที่สะท้อนออกมาจากดินแดนลับแล。"
  },
  Event_7083_Name = {
    Text = "ไล่ล่าอย่างไม่ย่อท้อ"
  },
  Event_7084_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7084_Desc = {
    Text = "มันก็แค่ลอยอยู่ในอากาศอย่างเงียบๆ ไม่กระพริบตา สายตาเต็มไปด้วยความหวัง เหมือนกับต้องการบอกอะไรคุณ \n ดวงตาอาจจะเก็บซ่อนวิญญาณ แต่ถ้าไม่มีคำพูด คุณก็แค่รู้สึกถึงความเร่งรีบเล็กน้อยและความเศร้า \n มันก็หายไปอย่างไร้ร่องรอย。"
  },
  Event_7084_Name = {
    Text = "มองอย่างบอด"
  },
  Event_7085_ChoiceDesc1 = {
    Text = "【แสดงความเห็นด้วย】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7085_ChoiceDesc2 = {
    Text = "【ของขวัญ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ถูกทำให้ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7085_ChoiceDesc3 = {
    Text = "【หันหลังเดินจากไป】ได้รับ 25 รอยดำ"
  },
  Event_7085_Desc = {
    Text = "「ถ้าหากวันหนึ่งฉันต้องตกลงไป ฉันหวังว่าจะตกลงในน้ำ。\nน้ำที่ไหลผ่านโพรงจมูกเหมือนความฝันเก่าอันอบอุ่น，\nของเหลวที่ฉันจมลงไป，\nคือถ้วยที่@2ปรารถนามากที่สุด。」"
  },
  Event_7085_Name = {
    Text = "พิธีกรรมน้ำ"
  },
  Event_7086_ChoiceDesc1 = {
    Text = "【ต้านภาพหลอน】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ถูกโจมตีด้วย「(Skill.Arg2)」"
  },
  Event_7086_ChoiceDesc2 = {
    Text = "【ดูดซึมความคลั่ง】การปลุกแบบสุ่ม 2 ร่างกายที่ตื่นขึ้น ติดเชื้อสองครั้ง「(Skill.Arg1)」"
  },
  Event_7086_Desc = {
    Text = "มิติที่บกพร่องค่อยๆ พังทลายลง，ภาพหลอนจากมิติอื่นไหลทะลักเข้ามาในห้องที่เต็มไปด้วยความผิดปกติ。"
  },
  Event_7086_Name = {
    Text = "มิติลวงตา"
  },
  Event_7087_ChoiceDesc1 = {
    Text = "【ออกจาก】การตื่นรู้แบบสุ่มของร่างกายที่ตื่นขึ้น"
  },
  Event_7087_Desc = {
    Text = "เด็กสาวสะดุ้งเล็กน้อย ยกมือลูบไปที่ขอบกระโปรง \n「ที่ฉันพอจะทำให้เธอน่ะ... ก็แค่นี้แหละ」"
  },
  Event_7087_Name = {
    Text = "สาวในชุดขาว"
  },
  Event_7088_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7088_Desc = {
    Text = "ใครกำลังพูดอยู่?\nคุณก้มหน้าลง เห็นเพียงเงาสะท้อนที่พร่ามัว——มันสวมเสื้อผ้าเหมือนกับคุณทุกประการ แต่มือถือมีดอยู่ และกำลังยิ้มให้คุณ."
  },
  Event_7088_Name = {
    Text = "คุณจะไม่อยากพบเจอ"
  },
  Event_70892_ChoiceDesc1 = {
    Text = "【ตามการจำของร่างกาย】ข้ามการต่อสู้และชนะทันที แต่จะสูญเสียค่าพลังชีวิต Arg1 คะแนน。"
  },
  Event_70892_ChoiceDesc2 = {
    Text = "【ออกจาก】เข้าสู่การต่อสู้"
  },
  Event_70892_Desc = {
    Text = "แม้ว่าศัตรูจะแข็งแกร่งผิดปกติ แต่คุณคุ้นเคยกับวิธีเอาชนะพวกมันแล้ว"
  },
  Event_70892_Name = {
    Text = "ความทรงจำของกล้ามเนื้อ"
  },
  Event_7089_ChoiceDesc1 = {
    Text = "【ลากรัม】"
  },
  Event_7089_ChoiceDesc2 = {
    Text = "【โจมตีตัวทดลอง】"
  },
  Event_7089_Desc = {
    Text = "คุมกัดที่หลังคอของร่างทดลองหนึ่ง กำลังเตรียมจะเหวี่ยง แต่ร่างทดลองนั้นกลับหมุนหัว 180° เหมือนนกฮูก และจิ้มไปที่ใบหน้าของคุม。"
  },
  Event_7089_Name = {
    Text = "โคลอสเซียม"
  },
  Event_7090_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7090_Desc = {
    Text = "คุณกำกุญแจเงินให้มั่น ในกระแสที่มืดมิดของมิติรู้สึกถึงเสียงเพรียกของต้นกำเนิด \n เพื่อที่จะต่อสู้กับสุนัขแห่งนรกที่มีสภาพไม่ชัดเจน คุณต้องยืมพละกำลังที่เป็นไปได้ทุกอย่างให้มากที่สุด。"
  },
  Event_7090_Name = {
    Text = "มิติลวงตา"
  },
  Event_7091_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7091_Desc = {
    Text = "「เกี่ยวกับนักสืบคนนั้น ท่านผู้อำนวยการมีแผนที่จะสอบถามด้วยตนเอง……\nให้เหลือผู้รอดชีวิต……」\nเสียงค่อยๆ อ่อนลง และในที่สุดก็หายไปในความมืด.。"
  },
  Event_7091_Name = {
    Text = "ผนังมีหู"
  },
  Event_7092_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7092_Desc = {
    Text = "ความรู้สึกไร้น้ำหนักทำให้คุณตื่นขึ้นอย่างกระทันหัน พื้นใต้เท้าของคุณแข็งแรงและเชื่อถือได้ ข้างเท้าของคุณมี กระจกสี่เหลี่ยมที่ประณีตนอนอยู่。"
  },
  Event_7092_Name = {
    Text = "กระจกในกระจก"
  },
  Event_7093_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7093_Desc = {
    Text = "คุณไม่เคยโต้เถียงกับผู้ที่จมอยู่กับความบ้าคลั่งและไม่มีทางรักษาได้ เพราะมันจะทำให้จิตวิญญาณของคุณถูกกลืนกินอย่างสิ้นเชิงในคำถามยามเที่ยงคืน ปล่อยคุณไปเถอะ!"
  },
  Event_7093_Name = {
    Text = "พิธีกรรมน้ำ"
  },
  Event_7094_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7094_Desc = {
    Text = "ใบหน้าของหุ่นขี้ผึ้งควรจะเป็นอย่างไรนะ? \nคุณหลับตาลง ภาพใบหน้าที่พร่ามัวนับล้านผุดขึ้นมาในหัวของคุณ \nพวกมันเหมือนเทียนไขที่ลากไฟสีซีดอยู่ในกระแสน้ำมืดมิด ค่อยๆ อุบัติและหายไป... \nคุณเดินไปตามกระแสน้ำจนถึงที่สุด ที่นั่นมีหุ่นขี้ผึ้งตัวเดียว ตัวสุดท้ายยืนอยู่ \nเมื่อใกล้ถึง คุณเห็นว่า...@2。"
  },
  Event_7094_Name = {
    Text = "หุ่นขี้ผึ้งที่ยังไม่เสร็จ"
  },
  Event_7095_ChoiceDesc1 = {
    Text = "【ผู้ถือมีดสั้นที่โจมตี】ติดเชื้อ \"(Skill.Arg1)\"，ได้รับสิ่งมีชีวิตแห่งคำสาป \"(RelicConfig.Arg2)\""
  },
  Event_7095_ChoiceDesc2 = {
    Text = "【ผู้ซุ่มโจมตีดาบ】ติดเชื้อสองครั้ง 「(Skill.Arg1)」 ได้รับสิ่งประดิษฐ์เงิน 「(RelicConfig.Arg2)」 และ 「(RelicConfig.Arg3)」"
  },
  Event_7095_ChoiceDesc3 = {
    Text = "【ทำให้ผู้ถือหอกสะดุด】ได้รับสิ่งประดิษฐ์จากเงิน「(RelicConfig.Arg1)」"
  },
  Event_7095_Desc = {
    Text = "ผู้เหยียบทะเลสามคนกัดไม่ปล่อยคุณอย่างแน่นหนา ดวงตาที่บ้าคลั่งและร้อนแรงเกือบจะจุดไฟให้เสื้อคลุมของคุณ \nเมื่อหันกลับไปมอง คุณสังเกตเห็นว่าทั้งสามคนมีความแตกต่างกัน \nผู้เหยียบทะเลที่ถือดาบใหญ่ตะโกนเสียงดังกว่าคนอื่น แต่การกระทำของเขากลับดูไม่ใส่ใจ \nผู้เหยียบทะเลที่ถือหอกเดินตามอย่างระมัดระวัง ราวกับเด็กน้อยที่เพิ่งเริ่มพูด \nผู้เหยียบทะเลที่ถือมีดสั้นอยู่ท้ายสุด คำสวดมนต์ที่เขาพูดออกมาพิสูจน์ถึงความบ้าคลั่งของเขา。"
  },
  Event_7095_Name = {
    Text = "ไล่ล่าอย่างไม่ย่อท้อ"
  },
  Event_7096_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，รับสถานะ「(Skill.Arg2)」"
  },
  Event_7096_Desc = {
    Text = "คุณรับของขวัญอย่างระมัดระวังและค่อยๆ แกะออก \n ลูกตาคู่หนึ่งนอนอยู่ในกล่องของขวัญอย่างเงียบๆ \n「ฉันมอบดวงตาของฉันให้กับคุณ」 \n「เหมือนที่เขาเคยทำกับฉัน」"
  },
  Event_7096_Name = {
    Text = "พิธีปิดฉาก Ⅵ"
  },
  Event_7097_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7097_Desc = {
    Text = "ยื่นมือผ่านกลางแสงสว่าง คุณเก็บเงินใจที่ตรึงนิ่งหนึ่งหยดขึ้นมา หยดนี้เป็นตัวกลางที่มีค่าของความทรงจำและจิตวิญญาณ ร้อนแรงอย่างยิ่ง สะท้อนสีสันที่แปลกประหลาด \n ก่อนที่มันจะบิดเบือนและผสมผสานแสงทั้งหมด ความเจ็บปวดร้อนแรงทำให้คุณอดไม่ได้ที่จะโยนมันกลับไปในความมืดอีกครั้ง。"
  },
  Event_7097_Name = {
    Text = "แสงนีออนยามค่ำคืน"
  },
  Event_7098_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7098_Desc = {
    Text = "คุณปฏิเสธของขวัญจากเด็กชาย \n เด็กชายมองคุณด้วยเบ้าตาที่ว่างเปล่า เขาถอนหายใจเบาๆ \n 「แล้วลาก่อน」 \n เด็กชายพูดจบแล้วทำท่าทางเหมือนการลา แล้วล้มตัวไปทางหน้าต่าง \n เขาหายไป เหมือนกับผีเสื้อที่ร่ายรำอย่างงดงาม หรือเหมือนกับสายลม。"
  },
  Event_7098_Name = {
    Text = "พิธีปิดฉาก Ⅵ"
  },
  Event_7099_ChoiceDesc1 = {
    Text = "เลือกการแกะสลักทั่วไป"
  },
  Event_7100_ChoiceDesc1 = {
    Text = "【รับหู】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7100_ChoiceDesc2 = {
    Text = "【ปฏิเสธร้องขอ】ได้รับการแกะสลัก โดยเลือก 1 จาก 3"
  },
  Event_7100_Desc = {
    Text = "เสียงโน้ตที่หรูหราหลายเสียงไหลออกจากปลายนิ้วของเขา \n นักเปียโนหุ่นขี้ผึ้งที่เศร้าหมองนั่งอยู่คนเดียวที่หน้าต่าง \n ตั้งแต่เขามีสติ หุ่นขี้ผึ้งจึงเป็นโลกทั้งหมดของเขา \n เขาอยู่ในสภาพที่ปิดกั้นมานาน และอยากฟังสิ่งที่แตกต่างออกไป โดยเฉพาะอย่างยิ่ง… ดนตรีที่เรียกว่าแจ๊ส \n สุดท้ายเขาได้ฉีกหูข้างหนึ่งของตัวเองออกมา และขอให้คุณนำมันไป \n 「ให้ฉันได้ฟังดนตรีข้างนอกหน่อย... แค่ใส่มันลงในกระเป๋า」"
  },
  Event_7100_Name = {
    Text = "เอียงหูฟัง"
  },
  Event_7101_ChoiceDesc1 = {
    Text = "【เชื่อมต่อ】ฟื้นฟู Arg2 จุดชีวิต。[ExDesc1]"
  },
  Event_7101_ChoiceDesc2 = {
    Text = "【การตื่นรู้】เลือกปลุกร่างกายที่ตื่นขึ้น 1 หน่วย。[ExDesc1]"
  },
  Event_7101_ChoiceDesc3 = {
    Text = "【กำจัด】ลบการ์ดอาการได้สูงสุด 3 ใบ ได้รับ Arg2 รอยดำ。"
  },
  Event_7101_Desc = {
    Text = "คุณกำลังสำรวจในหมอก จู่ๆ ตราสัญลักษณ์ที่หน้าอกก็ปล่อยแสงเงินอ่อนๆ ออกมา ใครกันที่เรียกคุณจากเครื่องสื่อสาร?"
  },
  Event_7101_Name = {
    Text = "จุดติดต่อ"
  },
  Event_7101_Tips3 = {
    Text = "ขณะนี้คุณยังไม่มีการ์ดอาการ"
  },
  Event_7102_ChoiceDesc1 = {
    Text = "【รับคำท้า】"
  },
  Event_7102_ChoiceDesc2 = {
    Text = "【ต่อยพระองค์หนึ่งที】ได้รับรอยดำ 25 จุด"
  },
  Event_7102_Desc = {
    Text = "ร่างที่ผอมแห้งปรากฏขึ้นจากเงา ขวางทางคุณไว้ \n ความทรงจำที่ถูกผูกมัดตลอดกาลได้บุกเข้ามาในดินแดนลับแล โดยเรียกตนเองว่า「N」 เงาที่กำลังเล่นชิปในมือด้วยเสียงคร่ำครวญที่ไม่ชัดเจนเชิญชวนคุณเข้าร่วมเกมของเขา \n ชิปสามสีถูกวางอยู่ตรงหน้าคุณ หากไม่เล่น「เกม」กับเขาสักรอบ เขาคงไม่ปล่อยคุณไปง่ายๆ。"
  },
  Event_7102_Name = {
    Text = "การแสดงกำลังเริ่มต้น"
  },
  Event_7103_ChoiceDesc1 = {
    Text = "【ใส่กุญแจเงิน】"
  },
  Event_7103_Desc = {
    Text = "ดูเหมือนว่าในเมือก D ที่อิ่มตัวเกินไปจะมีสารบางอย่าง... ใช้กุญแจเงินในการสังเกต และเปลี่ยนมันให้กลายเป็นพละกำลังของตนเองเถอะ。"
  },
  Event_7103_Name = {
    Text = "จุดแยก"
  },
  Event_7104_ChoiceDesc1 = {
    Text = "【ดิ้นรนตื่นขึ้น】 เพิ่มพลังชีวิตสูงสุดอีก Arg1 หน่วย"
  },
  Event_7104_ChoiceDesc2 = {
    Text = "【ปล่อยตัวเองหลับใหล】การ์ดคำสั่งสุ่ม 2 ใบรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ 2 ใบ「(Skill.Arg2)」"
  },
  Event_7104_Desc = {
    Text = "คุณกอดสมบัติที่แวววาวไว้ในอ้อมแขน \n มันแผ่ขยายจากหน้าอกไปทั่วร่างกายของคุณ ความทรงจำอันอบอุ่นที่เปล่งประกายเหมือนแสงเทียน ถูกเติมเข้ามาในสมองของคุณในที่สุด \n เสียงของถ่านที่แตกและเสียงดัง ฟังดูอบอุ่นจากเก้าอี้ที่มีผ้าห่มอยู่ข้างเตาผิง ชาอุ่นหอมกรุ่น และท้องแมวที่นอนอยู่ข้างเท้าของคุณ... \n ในความง่วงอันสะดวกสบายนี้ คุณรู้สึกมึนงงและตกลงไปในความนุ่มนวล。"
  },
  Event_7104_Name = {
    Text = "จมอยู่ในวันเก่า"
  },
  Event_7105_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7105_Desc = {
    Text = "คุณดึงฟิล์มอีกครึ่งหนึ่งออกมาอย่างไม่ปรานีปราศรัย มันซ่อนอยู่ในท้องของกล้อง ถูกดึงออกมาอย่างกะทันหัน แต่ภาพที่ปรากฏทำให้คุณพูดไม่ออกเป็นเวลานาน \n ฟิล์มที่ยังไม่ได้ล้างบันทึกภาพอย่างซื่อสัตย์——คุณล้มอยู่ในโคลนสีดำ.。"
  },
  Event_7105_Name = {
    Text = "บันทึกความบริสุทธิ์"
  },
  Event_7106_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7106_Desc = {
    Text = "คุณตรวจสอบกล้องอย่างเรียบร้อย หนังและทองคำดำถูกฝังอยู่ในตัวเครื่อง สะท้อนแสงเงางามเล็กน้อย \n เลนส์ของมันจ้องมองคุณ เหมือนกำลังจ้องมอง สอดแนม..."
  },
  Event_7106_Name = {
    Text = "บันทึกความบริสุทธิ์"
  },
  Event_7107_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7107_Desc = {
    Text = "แสงจันทร์ที่ถูกตักขึ้นด้วยฝ่ามือถูกโปรยลงบนหลุมศพ\nมีคนถูกฝังอยู่ใต้โคลนหนาแน่น กลุ่มคนที่มองอยู่กล่าวว่า บุคคลนี้ได้พบกับการตายตามธรรมชาติ จะได้นอนหลับอยู่ใต้ดิน\nแต่โคลนที่ถูกฝังนั้นเคลื่อนไหว และในเสียงกรีดร้อง มีแสงจันทร์ที่อ่อนแรงโผล่ขึ้นมา。"
  },
  Event_7107_Name = {
    Text = "ชิ้นส่วนดวงจันทร์เงิน"
  },
  Event_7108_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7108_Desc = {
    Text = "คุณสัมผัสปีกสีดำบางเบาของผีเสื้ออย่างนุ่มนวล ผีเสื้อกระพือปีกอย่างเบาๆ แล้วกลายเป็นหยดน้ำสีดำสนิท ตกลงบนฝ่ามือของคุณ。"
  },
  Event_7108_Name = {
    Text = "สิ่งที่ไม่ควรมีอยู่"
  },
  Event_7109_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7109_Desc = {
    Text = "ดวงจันทร์อันโดดเดี่ยวแขวนอยู่บนท้องฟ้า แต่คุณสามารถได้ยินคำสวดอันอวยพรจากมันได้ ท่วงทำนองที่แปลกประหลาด คล้ายเสียงซุบซิบอันน่ารังเกียจ\nคำสวดหยุดลง ขณะที่คุณกำลังจะจากไป ด้านหลังกลับปรากฏเงาสีขาว\n「ผู้ที่จ้องมองชะตากรรมและหมิ่นประมาทการอวยพร จะได้รับทั้งพรและราคาที่ต้องจ่ายตามสัญญา」"
  },
  Event_7109_Name = {
    Text = "ชิ้นส่วนดวงจันทร์เงิน"
  },
  Event_7110_ChoiceDesc1 = {
    Text = "【สามจุด】"
  },
  Event_7110_ChoiceDesc2 = {
    Text = "【หกโมง】"
  },
  Event_7110_ChoiceDesc3 = {
    Text = "【จุดเดียว】"
  },
  Event_7110_Desc = {
    Text = "ดูเหมือนว่าโชคของคุณในวันนี้จะดีมากนะ\nลูกเต๋าสั่นสะเทือนและส่งเสียงฮัมที่กระตุ้นอารมณ์\nคุณตัดสินใจที่จะทายหมายเลขหนึ่ง"
  },
  Event_7110_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_7111_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7111_Desc = {
    Text = "เกมเดิมพันนี้คือการหลอกลวงครั้งใหญ่!\nคุณลุกขึ้นอย่างรวดเร็ว แต่กลับรู้สึกเวียนศีรษะ\nลูกเต๋าส่งเสียงฮัมที่ดังและวุ่นวาย เสียงที่เต็มไปด้วยเสน่ห์ยังคงวนเวียนอยู่ในหัวของคุณ：\n「เพียงหนึ่งครั้ง... ครั้งสุดท้าย...」"
  },
  Event_7111_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_7112_ChoiceDesc1 = {
    Text = "【ใช้เงินใจ】อัปเกรดสิ่งประดิษฐ์เงิน 1 ชิ้นเป็นสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7112_ChoiceDesc2 = {
    Text = "【เก็บเงินใจ】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」 การติดเชื้อ「(Skill.Arg2)」และ「(Skill.Arg3)」"
  },
  Event_7112_ChoiceDesc3 = {
    Text = "【ใส่คืนในลิ้นชัก】ได้รับ 25 รอยดำ"
  },
  Event_7112_Desc = {
    Text = "ในลิ้นชักที่สองด้านขวาของโต๊ะทำงาน มีเงินใจที่ถูกขึ้นรูปวางอยู่โดดเดี่ยว เมื่อสัมผัสเบาๆ คุณได้ยินเสียงเห่าหอนของพายุ ผสมผสานกับเสียงการเสียดสีของเกล็ดหิมะที่แตกละเอียด และเสียงฟลูตที่สะอื้น..."
  },
  Event_7112_Name = {
    Text = "ใจเงินเหงา"
  },
  Event_7113_ChoiceDesc1 = {
    Text = "【ฟังอย่างตั้งใจ】ได้รับผลกระทบจาก「(Skill.Arg1)」，ได้รับสิ่งมีชีวิตแห่งคำสาป-「(RelicConfig.Arg2)」"
  },
  Event_7113_ChoiceDesc2 = {
    Text = "【ทำการเปลี่ยนแปลง】เลือกทำลายสิ่งสร้าง ๑ ชิ้น เพื่อรับรางวัล ๑ รายการ"
  },
  Event_7113_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7113_Desc = {
    Text = "ไม่ใช่ว่าทุกบทเพลงจะไพเราะ \nเสียงที่ไม่กลมกลืนอย่างแท้จริงได้สร้างเสียงครวญครางขึ้นมา"
  },
  Event_7113_Name = {
    Text = "เสียงไม่ประสาน"
  },
  Event_7114_ChoiceDesc1 = {
    Text = "【หยิบมันขึ้นมา】ติดเชื้อ「(Skill.Arg1)」, ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」"
  },
  Event_7114_ChoiceDesc2 = {
    Text = "【ละทิ้งมัน】ได้รับ 25 รอยดำ。"
  },
  Event_7114_Desc = {
    Text = "ในมุมที่ซ่อนเร้นและเหม็นของกองฟาง ภายในรอยหลอมกร่อนที่แตกออก สิ่งหนึ่งถูกวางอยู่อย่างเงียบสงบ"
  },
  Event_7114_Name = {
    Text = "หลังกองฟาง"
  },
  Event_7115_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7115_Desc = {
    Text = "เงาร่างนั้นไม่ได้เข้ามาใกล้กว่าเดิม หลังจากจ้องมองคุณชั่วขณะ ก็กลายเป็นกองทรายสีเงินเล็กน้อย"
  },
  Event_7115_Name = {
    Text = "ผู้ใช้กุญแจเงิน"
  },
  Event_7116_ChoiceDesc1 = {
    Text = "【สัมผัสอย่างแน่นหนา】ยอมรับความช่วยเหลือจากตูรู"
  },
  Event_7116_Desc = {
    Text = "หลังจากเสียงถอนหายใจ ตูรูตามมาอย่างรวดเร็ว\nหนวดที่หนักอึ้งและเย็นเฉียบจับคุณไว้ ปิดกั้นความคิดที่อยากจะพุ่งเข้าไปในแนวข้าศึก\n「ข้าจะเป็นแรงสนับสนุนของเจ้า แค่ในช่วงเวลานี้」"
  },
  Event_7116_Name = {
    Text = "คำสัญญาของผู้แทน"
  },
  Event_7117_ChoiceDesc1 = {
    Text = "【ได้รับกุญแจ】"
  },
  Event_7117_Desc = {
    Text = "1,2,3……\nแจนกินห่างจากโต๊ะเขียนหนังสือเพียง 10 ฟุต\nนี่เป็นระยะทางที่สั้นมาก แต่กลับยาวเหมือนทั้งชีวิตของเธอ\nเธอนึกถึงริบบิ้นนุ่มๆ นึกถึงกระดาษห่อทองคำรูปผีเสื้อ และนึกถึงน้ำตาของแม่\nเธอยังนึกอะไรอีกมากมาย มากมาย...\nร่างผอมบางล่องลอยผ่านแม่น้ำสีดำ ค่อยๆ เข้าใกล้โต๊ะเขียนหนังสือ\nกุญแจอยู่ในลิ้นชัก ค่าใช้จ่ายที่ต้องใช้ในการได้มาก็ง่ายดาย: ความกล้า ความคล่องแคล่ว และอีกเล็กน้อยคือโชค\nนอกจากโชค แจนกินไม่ขาดอะไรเลย。"
  },
  Event_7117_Name = {
    Text = "กุญแจสุดท้าย"
  },
  Event_7118_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7118_Desc = {
    Text = "แค่เกมเดิมพันเท่านั้น คุณจะไม่แพ้หรอก。\nเหรียญที่มีลวดลายถูกโยนขึ้นสูง แล้วตกลงมาอย่างรวดเร็ว ถูกฝ่ามือของคุณสัมผัสและอุ่นขึ้น。"
  },
  Event_7118_Name = {
    Text = "นักพนันชื่อดัง"
  },
  Event_7119_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7119_Desc = {
    Text = "แค่เกมเดิมพันเท่านั้น คุณจะไม่แพ้หรอก。\nเหรียญที่มีลวดลายถูกโยนขึ้นสูงแล้วตกลงมาอย่างรวดเร็ว ถูกฝ่ามือของคุณทำให้ร้อนขึ้น。"
  },
  Event_7119_Name = {
    Text = "นักพนันชื่อดัง"
  },
  Event_7120_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7120_Desc = {
    Text = "แค่เกมเดิมพันเท่านั้น คุณจะไม่แพ้หรอก.\nเหรียญที่มีลวดลายถูกโยนขึ้นสูง แล้วตกลงมาอย่างรวดเร็ว ถูกฝ่ามือของคุณซึมซับความอบอุ่น。"
  },
  Event_7120_Name = {
    Text = "นักพนันชื่อดัง"
  },
  Event_7121_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7121_Desc = {
    Text = "คุณไม่ได้ตั้งใจเข้าร่วมบทเรียนเปียโนที่จริงจังนี้ \n ทุกครั้งที่เล่นจบหนึ่งท่อน นักเรียนก็จะต้องบิดหัวอย่างยากลำบาก ทำท่าฟัง \n และอาจารย์ของเขาก็จะก้มหัวเล็กน้อย ปากพูดไปมา ดวงตากลมโตมองไปที่โน้ตเพลงที่ไม่มีอยู่จริง \n พวกเขาชัดเจนว่าไม่รู้ว่ากำลังทำอะไร และจะไม่มีวันเข้าใจว่าทำไมมนุษย์ถึงใช้เวลาหลายปีในการฝึกซ้อมที่เป็นกลไกเช่นนี้ \n พวกเขาแค่เลียนแบบเท่านั้น。"
  },
  Event_7121_Name = {
    Text = "บทเรียนเปียโน"
  },
  Event_7122_ChoiceDesc1 = {
    Text = "【ใส่กุญแจเงิน】"
  },
  Event_7122_Desc = {
    Text = "ดูเหมือนว่าในเมือก D ที่เกินความอิ่มตัวจะมีสารบางอย่าง... ใช้กุญแจเงินในการสังเกต แล้วเปลี่ยนมันให้กลายเป็นพละกำลังของตนเองเถอะ。"
  },
  Event_7122_Name = {
    Text = "จุดแยก"
  },
  Event_7123_ChoiceDesc1 = {
    Text = "【จดจำเนื้อร้อง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7123_ChoiceDesc2 = {
    Text = "【ร้องเพลงเบาๆ】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_7123_Desc = {
    Text = "เพลงเรือโบราณดังก้องอยู่ในดินแดนลับแล。\nความทรงจำที่ติดอยู่ในดินแดนลับแลใช้ภาษาที่คุณไม่เคยได้ยิน ร้องเพลงเกี่ยวกับคลื่นทะเล ท้องฟ้า และสุราแรง。"
  },
  Event_7123_Name = {
    Text = "เพลงทะเล"
  },
  Event_7124_ChoiceDesc1 = {
    Text = "【เรียกอีกา】ได้รับ 20 รอยดำ ได้รับผล「(Skill.Arg2)」"
  },
  Event_7124_ChoiceDesc2 = {
    Text = "【ออกห่างไปไกล】"
  },
  Event_7124_Desc = {
    Text = "นกสีดำสนิทจ้องมองคุณอยู่นานมาก หลังจากผ่านไปนาน บางสิ่งก็ตกลงมาจากขนของพวกมัน.."
  },
  Event_7124_Name = {
    Text = "กุยบินโดดเดี่ยว"
  },
  Event_7125_ChoiceDesc1 = {
    Text = "【เข้าไปจับ】ได้รับ 25รอยดำ"
  },
  Event_7125_ChoiceDesc2 = {
    Text = "【การตอบสนองที่เป็นมิตร】โอกาส 50% ได้รับ 50 รอยดำ โอกาส 50% ไม่ได้อะไรเลย"
  },
  Event_7125_Desc = {
    Text = "วิฬารตัวหนึ่งนั่งอยู่ท่ามกลางเมือก D โดยไม่รู้ว่ามาจากที่ใด รูปร่างที่เลือนรางบ่งบอกว่ามันน่าจะเป็นผู้อาศัยในมิติทางจิต \n เงาสะท้อนที่ไม่สามารถมองเห็นใบหน้าตัวเองได้ มองไปที่ราโมน่าด้วยสายตาที่ชาญฉลาด มันยกอุ้งเท้าขาวสะอาดขึ้น ทำท่าทางเหมือนเรียกเธอ。"
  },
  Event_7125_Name = {
    Text = "ผู้อยู่อาศัยที่เดินทาง"
  },
  Event_7126_ChoiceDesc1 = {
    Text = "【วิ่งสุดชีวิตไปเหนือ】"
  },
  Event_7126_ChoiceDesc2 = {
    Text = "【ละเว้นเสียง】"
  },
  Event_7126_Desc = {
    Text = "การโจมตีของศัตรูตกลงมาราวกับฝนตกหนักจากด้านหลัง ใบมีดเฉือนผ่านเสื้อคลุมหลายครั้ง ทำให้ฝูงนกนางนวลที่อยู่บนท่าเรือตกใจ \n「ไปทางเหนือ... หรือขึ้นเรือ...」\nแม้แต่คนที่โง่เขลาก็ยังสามารถตระหนักได้ว่ามีบางพลังที่ช่วยเหลือคุณในความมืด。"
  },
  Event_7126_Name = {
    Text = "ไปทางเหนือ"
  },
  Event_7127_ChoiceDesc1 = {
    Text = "【ฟังดวงอาทิตย์】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」"
  },
  Event_7127_ChoiceDesc2 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7127_Desc = {
    Text = "ในความผสมผสานระหว่างความเป็นจริงและความหลอกลวง ดาวเคราะห์หมุนเวียนตลอดกาลตามเส้นทางที่กำหนดไว้ \nการผ่านไปมานับไม่ถ้วนได้บรรเลงบทเพลงแปลกประหลาดและกลอุบายออกมาอีกครั้งอีกครั้ง……"
  },
  Event_7127_Name = {
    Text = "เสียงของดาวและดวงจันทร์"
  },
  Event_7128_ChoiceDesc1 = {
    Text = "【จากไปพร้อมกับความเศร้า】การ์ดที่ถูกคัดลอก หากคัดลอกการ์ดอาการ จะได้รับ 75 รอยดำ"
  },
  Event_7128_ChoiceDesc2 = {
    Text = "【จากไปพร้อมความโกรธ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7128_Desc = {
    Text = "ของเหลวพุ่งออกมาจากรูม่านตา ความเย็นและรุนแรงได้พรากวิญญาณบางส่วนไป"
  },
  Event_7128_Name = {
    Text = "น้ำตาของชายหาดมืดมน"
  },
  Event_7129_ChoiceDesc1 = {
    Text = "【ทางเดินลึก】"
  },
  Event_7129_ChoiceDesc2 = {
    Text = "【ทางแยก】ได้รับ 25 รอยดำ"
  },
  Event_7129_Desc = {
    Text = "แสงจันทร์สีขาวซีดไม่สนใจการไหลเวียนของเวลา สาดส่องลงบนห้องโถงเงียบสงัด。\nช่องประตูภายใต้แสงจันทร์เปล่งประกายแปลกประหลาด。"
  },
  Event_7129_Name = {
    Text = "ห้องโถงเงียบสงัด"
  },
  Event_7130_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7130_Desc = {
    Text = "คุณตัดสินใจที่จะซ่อมหุ่นขี้ผึ้งนี้。\nรอบๆ หุ่นขี้ผึ้งมีเครื่องมือบางอย่างกระจัดกระจายอยู่ คุณเลือกสีชนิดหนึ่งที่ชื่อว่า「ฟ้าปรัสเซีย」 \nมันสีน้ำเงินเหมือนกับโรคชนิดหนึ่ง。"
  },
  Event_7130_Name = {
    Text = "หุ่นขี้ผึ้งที่ยังไม่เสร็จ"
  },
  Event_7131_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7131_Desc = {
    Text = "พุพองส่งเสียงหวีดร้องแหลมและน่าขนลุก เสียงลมที่ไม่ควรมีดังขึ้นที่หู เสียงขลุ่ยที่เหมือนภาพหลอน และเสียงต้องห้ามของของเหลวพุพองที่เคลื่อนไหว \n พุพองขยับตัวแปลกๆ สักพัก แล้วก็แข็งทื่อจมลงสู่ความเงียบสงัด เมื่อเห็นภาพนี้ ผู้ปลุกตื่นข้างๆ คุณดูเหมือนจะได้รับการเรียกร้องบางอย่าง。"
  },
  Event_7131_Name = {
    Text = "Pustula ประหลาด"
  },
  Event_7132_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7132_Desc = {
    Text = "ปลายนิ้วของคุณสัมผัสกับรูปปั้น แต่ความรู้สึกกลับมีรอยบุ๋มที่นุ่มนวลอย่างไม่คาดคิด คุณมักคิดว่านี่เป็นภาพลวงตา.。"
  },
  Event_7132_Name = {
    Text = "ประกอบซาก"
  },
  Event_7133_ChoiceDesc1 = {
    Text = "【ร้องไห้เพื่อเธอ】"
  },
  Event_7133_ChoiceDesc2 = {
    Text = "【การสวดมนต์ถึงเธอ】"
  },
  Event_7133_Desc = {
    Text = "ทันทีที่ร่างกายสัมผัสกับขอบเรือ ความทรงจำที่ไม่ใช่ของเธอก็หลั่งไหลเข้าสู่สมอง \nผู้คนได้เปลี่ยนชุดสีขาวบริสุทธิ์ให้กับเธอ ตกแต่งด้วยอัญมณีอย่างประณีตและงดงาม ผู้คนยกเธอขึ้นไปบนแท่นบูชาสูงๆ ชาวบ้านในเมืองเล็กๆ คุกเข่าลงที่เท้าของเธอ \nนั่นคือดวงตาที่เต็มไปด้วยความหวัง: นักเดินเรือหวังว่าเธอจะคุ้มครองการเดินเรือ ชาวประมงหวังว่าฤดูตกปลาจะไร้คลื่นลม และชาวบ้านอีกมากมายหวังว่าจะได้รับโชคดีตลอดทั้งปี \nในฝูงชนที่คุกเข่า มีเพื่อนเล่นในวัยเด็กของเธอ รวมถึงพ่อแม่และพี่น้องที่อยู่เคียงข้างกัน \nเธอไม่ต้องการอะไรทั้งนั้น เธอไม่รู้ว่าตนต้องการอะไร \nการตอบสนองต่อความปรารถนาอย่างเฉื่อยชา ดูเหมือนจะเป็นหน้าที่เดียวในชีวิตของเธอ。"
  },
  Event_7133_Name = {
    Text = "พิธีก่อนบิน"
  },
  Event_7134_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7134_Desc = {
    Text = "ร่างกายที่บกพร่องนั้นม่านตาซีดขยับช้าๆ จ้องมองเงาร่างของคุณที่กำลังจากไป แล้วเผยยิ้มเศร้าๆ"
  },
  Event_7134_Name = {
    Text = "ประกอบซาก"
  },
  Event_7135_ChoiceDesc1 = {
    Text = "【เผชิญหน้าอย่างแข็งขัน】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」ได้รับการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7135_ChoiceDesc2 = {
    Text = "【ยอมแพ้】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7135_ChoiceDesc3 = {
    Text = "【รีบเผ่น】ได้รับ 50 รอยดำ"
  },
  Event_7135_Desc = {
    Text = "หุ่นขี้ผึ้งดินหลายตัวขวางทางคุณอยู่。\nพวกมันเอียงไปเอียงมา หน้าตาดูหยาบกร้าน ไม่เหมือนกับมาตรฐานการผลิตที่ควรจะเป็นของโรเจอร์ส。\n「คำสั่ง... คำสั่งของท่าน...」"
  },
  Event_7135_Name = {
    Text = "แบบฝึกหัด"
  },
  Event_7136_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7136_Desc = {
    Text = "คุณเลือกที่จะมองตาอย่างกล้าหาญ \n พวกมันเป็นดวงดาวที่ส่องประกาย ในความมืดที่เปล่งประกาย \n หลังจากนั้นพวกมันก็หัวเราะ แล้วเปลี่ยนเป็นพระจันทร์โค้งนับไม่ถ้วน \n 「คุณไม่กลัวสายตา คุณไม่ควรกลัว... \n นานมากแล้วที่ไม่ได้พบกัน, @2」 \n ก่อนที่จะหายไป พวกมันมอบของขวัญเล็ก ๆ ให้คุณ เป็น「การพบกันอีกครั้ง」。"
  },
  Event_7136_Name = {Text = "ตา"},
  Event_7137_ChoiceDesc1 = {
    Text = "【เปิดปุ่ม】ขยายขอบเขตการมองเห็นปัจจุบัน[ExDesc1]。"
  },
  Event_7137_Desc = {
    Text = "อุปกรณ์ส่องสว่างที่เหลืออยู่จากคนรุ่นก่อน สามารถขับไล่หมอกสีดำรอบๆ ได้。\nหมอกที่อยู่รอบๆ มันไหวอย่างเป็นระเบียบ ราวกับถูกการหายใจของมันรบกวน。"
  },
  Event_7137_Name = {
    Text = "ไฟส่องสว่าง"
  },
  Event_7138_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7138_Desc = {
    Text = "ปีกใสของคุณแผ่ออก โฉบไปรอบๆ อย่างล่องลอย พร้อมกับฝูงกา ไหลสู่ก้นทะเลที่เงียบสงบ"
  },
  Event_7138_Name = {
    Text = "เสียงฝูงกา"
  },
  Event_7139_ChoiceDesc1 = {
    Text = "【กำจัดมัน】ได้รับ「หัวใจวิปริต」"
  },
  Event_7139_Desc = {
    Text = "พุพองที่ถูกทอดทิ้งข้างทางโดยไม่รู้จักใคร มีผิวที่เปล่งประกายสีเขียวมันแปดเปื้อน ขณะนี้กำลังเคลื่อนไหวอย่างไม่สบายใจและเปลี่ยนรูปอยู่ \n เมื่อเปรียบเทียบกับมอนสเตอร์ มันดูเหมือนไอศกรีมที่ถูกเผาไหม้อยู่กลางแดดอันร้อนแรง และจะละลายกลายเป็นน้ำขุ่นเหนียวๆ ในไม่ช้า แล้วหายไปในอากาศ。"
  },
  Event_7139_Name = {
    Text = "Pustula ประหลาด"
  },
  Event_7140_ChoiceDesc1 = {
    Text = "【ปล่อยมือที่ปิดหูลง】ติดเชื้อ「(Skill.Arg1)」เลือกรับรางวัลหนึ่ง"
  },
  Event_7140_ChoiceDesc2 = {
    Text = "【จับอีกาได้หนึ่งตัว】ได้รับ「(Skill.Arg1)」 เลือกรับของรางวัลหนึ่งชิ้น"
  },
  Event_7140_ChoiceDesc3 = {
    Text = "【ปิดตาทั้งสอง】ได้รับ 50 รอยดำ"
  },
  Event_7140_Desc = {
    Text = "แผดเสียงร่ำร้อง เสียงแผดร้องที่ไม่มีที่สิ้นสุด——\nนักขับร้องอีกาสวมขนสีดำเงางาม ปากแหลมของมันมีแสงเย็นแข็งแกร่งส่องประกาย เสียงคร่ำครวญที่ดังสนั่นหลายครั้งทำให้แก้วหูของคุณแตกสลาย。\nปล่อยมือที่ปิดหูของคุณเถอะ!\nฝูงอีกาที่ส่งเสียงร้องในยามค่ำคืนต้องการดื่มด่ำกับร่างที่หดตัวของคุณ ซึ่งเต็มไปด้วยความสั่นสะเทือนที่ยังไม่ได้ผ่านการกลั่นกรอง。\n"
  },
  Event_7140_Name = {
    Text = "เพลงของฝูงอีกา"
  },
  Event_7141_ChoiceDesc1 = {
    Text = "【ออกจาก】ไม่มีการค้นพบใดๆ"
  },
  Event_7141_Desc = {
    Text = "ไม่ใช่คนที่คุณกำลังมองหา"
  },
  Event_7141_Name = {
    Text = "2_6ชั่วคราว"
  },
  Event_7142_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7142_Desc = {
    Text = "คุณเลือกที่จะก้าวต่อไป \n เมื่อเปรียบเทียบกับความเสียหายทางจิตใจและร่างกายที่เกิดจากศิลปะหุ่นขี้ผึ้งที่เลวร้ายเหล่านั้น สิ่งรบกวนเล็กน้อยนี้ถือว่าไม่เป็นอะไรเลย \n คุณยังมีภารกิจที่ยิ่งใหญ่กว่าที่ต้องทำให้สำเร็จ。"
  },
  Event_7142_Name = {
    Text = "เสียงเท้า"
  },
  Event_7143_ChoiceDesc1 = {
    Text = "【ระบุปัญหา】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7143_Desc = {
    Text = "「ทำไม! ชอบจิ้มบาดแผลของคนอื่นขนาดนี้เหรอ!」\n「ใช่แล้ว! ตอนนี้ฉันอายุเพิ่มขึ้นมาอีกยี่สิบห้าปีโดยไม่มีเหตุผล! ตอนนี้เธอต้องเรียกฉันว่าพี่สาวมอร์ฟี่!」"
  },
  Event_7143_Name = {
    Text = "ชีวิตที่ถูกกักขัง"
  },
  Event_7144_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์เงิน 3 ตัวเลือก 1, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7144_Desc = {
    Text = "ใบหน้าของสาวน้อยสงบเหมือนแสงจันทร์ในคืนนี้ เธอไม่ได้ตอบคุณ แต่ยกเข็มทิศในมือสูงขึ้น——เธอสั่นเทา ยกเข็มทิศเล็กๆ ขึ้นเหมือนกับว่าใช้พลังชีวิตทั้งหมดของเธอ。"
  },
  Event_7144_Name = {
    Text = "สาวในชุดขาว"
  },
  Event_7145_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7145_Desc = {
    Text = "「อร่อย！อร่อย！」อีกาหัวเราะอย่างบ้าคลั่ง กลิ่นเหม็นเน่ากระจายไปยังจมูกของคุณเมื่อมันกางปีกออก"
  },
  Event_7145_Name = {
    Text = "นกกาถูกสาป"
  },
  Event_7146_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7146_Desc = {
    Text = "ถ้าจะให้พูด เสียงดังนั้นแน่นอนว่าเป็นแบบอย่างของยุคใหม่ \nพวกมันเดินย่ำบนจังหวะที่ไร้ระเบียบและทำนองที่ทำให้เกิดความล้มเหลวในโลกอย่างรุนแรง \nไม่มีความสงสาร ไม่มีการสั่นคลอน และไม่มีการประนีประนอม \nเกลียดความเป็นระเบียบ ปฏิเสธหัวข้อ เสียงดังไม่เคยทำให้ใครพอใจ—\nแน่นอนว่านี่รวมถึงช่างปั้นหุ่นขี้ผึ้งของเราด้วย。"
  },
  Event_7146_Name = {
    Text = "รสนิยมที่แย่"
  },
  Event_7147_ChoiceDesc1 = {
    Text = "【นำทาง】"
  },
  Event_7147_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7147_Desc = {
    Text = "มีคนดึงชายเสื้อคุณเบาๆ \n เป็นเด็กชายที่เพิ่งเห็นเมื่อกี้ เขานั่งยองอยู่มุมหนึ่งมองคุณด้วยความเหงา \n「ฉันจะเข้าร่วมการแสดงของวิทยาลัย \n แต่ฉันหาทางไปเวทีไม่เจอ」"
  },
  Event_7147_Name = {
    Text = "พิธีปิดฉากⅡ"
  },
  Event_7148_ChoiceDesc1 = {
    Text = "【ค้นหาต่อ】 เพิ่ม Arg1 คะแนนชีวิต, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7148_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7148_Desc = {
    Text = "ปลายจมูกได้กลิ่นหอมที่คุ้นเคย เป็นกลิ่นที่เรียบง่ายและทำให้รู้สึกพอใจ เมื่อคุณอยากดมกลิ่นหอมจากโรงอาหารอีกครั้ง กลิ่นหอมที่ลอยอยู่กลับหายไปหมดสิ้น。"
  },
  Event_7148_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7149_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7149_Desc = {
    Text = "พวกเขาคือสีที่อบอุ่น。\nร้อนแรง，นุ่มนวล，เต็มไปด้วยความรัก。\nพวกเขามอบอ้อมกอดที่น่าจดจำให้กับเด็กหญิง，เหมือนกับลมที่หายไป。"
  },
  Event_7149_Name = {
    Text = "สีที่ทำให้นึกถึง"
  },
  Event_7150_ChoiceDesc1 = {
    Text = "【คุณเป็นใครกันแน่?】"
  },
  Event_7150_ChoiceDesc2 = {
    Text = "【จะเปลี่ยนวิธีคิดได้อย่างไร?】"
  },
  Event_7150_Desc = {
    Text = "ผู้ชายที่มีผมยาวขวางทางพวกคุณอีกครั้ง ด้วยประสบการณ์จากครั้งก่อน สีหน้าของรามอน่าดูไม่ดีนัก \n「ใจเย็นๆ เพื่อนของฉัน」 ผู้ชายพูดช้าๆ เสียงของเขามีเสน่ห์และดึงดูด เหมือนเสียงลมที่ไหลผ่านทางเดินแคบๆ พร้อมกับเสียงเสียดสีเบาๆ \n「ฉันได้สังเกตมาพอสมควรแล้ว การเปลี่ยนแนวคิดจะทำให้คุณเข้าใกล้เป้าหมาย」"
  },
  Event_7150_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅲ"
  },
  Event_7151_ChoiceDesc1 = {
    Text = "【ฉันกำลังค้นหา】เพิ่ม Arg1 คะแนน พลังชีวิตสูงสุด"
  },
  Event_7151_ChoiceDesc2 = {
    Text = "【ฉันกำลังหลีกเลี่ยง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7151_Desc = {
    Text = "「ฉันเห็นใครบางคนกำลังตามหา ตามหาสิ่งที่ไม่สามารถตามหาได้ สิ่งที่เป็นความจริงอย่างน่าเศร้า \nฉันเห็นใครบางคนกำลังหลบหนี หลบหนีจากสิ่งที่ไม่สามารถหลบหนีได้ สิ่งที่ถูกซ่อนเร้นอย่างโหดร้าย สิ่งที่เรียกว่าความจริง \nคุณคือคนไหน?」"
  },
  Event_7151_Name = {
    Text = "วัตถุที่ถูกไล่ล่า"
  },
  Event_7152_ChoiceDesc1 = {
    Text = "【ตรวจสอบอย่างละเอียด】อัปเกรดสิ่งประดิษฐ์เงิน 1 ชิ้นเป็นสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7152_ChoiceDesc2 = {
    Text = "【พยายามฟัง】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」และ「(Skill.Arg3)」"
  },
  Event_7152_ChoiceDesc3 = {
    Text = "【ระวังเก็บให้ดี】ได้รับ 25 รอยดำ"
  },
  Event_7152_Desc = {
    Text = "หมอกข้างหน้าถูกสิ่งเล็กๆ ชิ้นหนึ่งทำให้สว่างขึ้น ดูเหมือนจะเป็นเศษแก้วหรือผลึก ที่มีสีสันมากมายทั้งเด่นชัดและจางๆ เคลื่อนไหวอยู่ภายใน。"
  },
  Event_7152_Name = {
    Text = "ความทรงจำของเรา"
  },
  Event_7153_ChoiceDesc1 = {
    Text = "【ยอมรับความท้าทาย】ชัยชนะได้รับสิ่งประดิษฐ์เงิน แพ้ได้รับอาการ ไม่ว่าจะชนะหรือแพ้ก็ไม่ส่งผลกระทบต่อต่อการสอบสวนในอนาคต。"
  },
  Event_7153_ChoiceDesc2 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7153_Desc = {
    Text = "คนในเงาคือใคร?\nเขามีลมหายใจที่ตรงกับคุณและจังหวะหัวใจเดียวกัน แบ่งปันความคิดที่แปลกประหลาดเดียวกัน.\nเป็นการหลอกลวงจากดินแดนลับแลหรือเงาที่ข้ามมิติ?\nดูเหมือนว่านี่จะเป็นคำเชิญท้าทายที่เลือนลาง?"
  },
  Event_7153_Name = {
    Text = "การสั่นสะเทือนของวิญญาณ"
  },
  Event_7154_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7154_Desc = {
    Text = "สายตาก้าวข้ามประวัติศาสตร์และเวลา อาจจะไม่เป็นเชิงเส้น อาจกำลังจ้องมองคุณจากความเคออสก่อนที่ดาวเคราะห์จะถือกำเนิด \n หรือบางที มันอาจรอคุณอยู่ในวันหนึ่งในอนาคต。"
  },
  Event_7154_Name = {
    Text = "มองลับ"
  },
  Event_7155_ChoiceDesc1 = {
    Text = "【รับ】ได้รับ 50 รอยดำ"
  },
  Event_7155_Desc = {
    Text = "ที่นั่นว่างเปล่า ของเหลวสีดำไหลอยู่บนพื้น ไม่สะท้อนอะไรเลย \n นี่เป็นเพียงภาพลวงตาของคุณหรือเปล่า? คุณรู้สึกว่าบางสิ่งกำลังหลุดลอยผ่านซอกนิ้วของคุณ。"
  },
  Event_7155_Name = {
    Text = "ใต้ผิวกระจก"
  },
  Event_7156_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7156_Desc = {
    Text = "「คุณเป็นคนดีที่ใจดีมาก ขอให้วันนี้ พรุ่งนี้ และมะรืนนี้ของคุณเป็นไปตามที่หวัง」\n「เอ่อ บอกไว้ก่อนว่าเรานี่เป็นการซื้อขายแบบครั้งเดียว......」\nนางฟ้าพอใจทำเสียงจิ๊บจ๊อยก่อนจะกล่าวลาอย่างเสียดาย。"
  },
  Event_7156_Name = {
    Text = "พรแห่งนางฟ้า"
  },
  Event_7157_ChoiceDesc1 = {
    Text = "【คืนกระเป๋าเงินให้ฉัน！】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_7157_ChoiceDesc2 = {
    Text = "【ลังเล】การ์ดคำสั่งสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7157_Desc = {
    Text = "「มาเถอะ มาเอากระเป๋าสตางค์ของเธอกลับมา!」เด็กๆ จากไกลโบกมือเรียก。\nคุณวิ่งไปข้างหน้า ในขณะที่ยื่นมือออกไป เสียงดังและยุ่งเหยิงก็ดังขึ้นในหัวทันที。\n「เด็กสกปรกมาจากไหน!」\n「มันคือหนูจากถนน ทำไมกล้าสัมผัสกระโปรงผ้าของดยุคหญิง!」\n「ไล่มันออกไปเร็ว!」\n「คุณมีเหรียญไหม? ถ้าไม่มีเหรียญ อย่าหวังว่าจะได้ขนมปังดำแม้แต่ชิ้นเดียว!」"
  },
  Event_7157_Name = {
    Text = "หนังสือของความว่างเปล่า"
  },
  Event_7158_ChoiceDesc1 = {
    Text = "【ตามหาเสียงเพลง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_7158_ChoiceDesc2 = {
    Text = "【ร้องเพลงตาม】ติดเชื้อ「(Skill.Arg1)」，การแกะสลักใหม่，ทำได้มากที่สุด 2 ครั้ง"
  },
  Event_7158_Desc = {
    Text = "เสียงเพลงที่ห่างไกลถูกทำลายเป็นผงดาวเล็ก ๆ :\n「ฉันสาปแช่งน้ำโสโครกในซอยยามค่ำคืน ดอกไม้เน่าเปื่อยที่ติดอยู่ที่โคนกำแพงที่พังทลาย โซ่ตรวนเกาะเกี่ยวกับสมองจนตกลงไปในโคลน ก่อนที่หมอกหนาจะลบการมีอยู่ของฉัน สีสันยามค่ำคืนจะจมลงสู่@2 ที่ลึกที่สุด.」"
  },
  Event_7158_Name = {
    Text = "คำสาปสารขาว"
  },
  Event_7159_ChoiceDesc1 = {
    Text = "【ทิ้งการเครื่องบูชาไว้】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7159_ChoiceDesc2 = {
    Text = "【พาพระองค์ออกไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7159_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7159_Desc = {
    Text = "เมื่อคุณเข้าใกล้ วิญญาณแห่งความวุ่นวายที่ไม่มีระเบียบก็ปรากฏขึ้นจากโคลนอย่างกระทันหัน \n แขนสีดำพันรัดคุณแน่น ขณะที่พระองค์ร้องไห้และอธิษฐานว่า—\n ขอให้ถวายของเครื่องบูชา หรือพาพระองค์ออกไป。"
  },
  Event_7159_Name = {
    Text = "วิญญาณแห่งความวุ่นวาย"
  },
  Event_7160_ChoiceDesc1 = {
    Text = "【เหลือไว้เพื่อเป็นเครื่องบูชา】สุ่มเพิ่มคุณภาพการแกะสลักของการ์ด 1 ใบ"
  },
  Event_7160_ChoiceDesc2 = {
    Text = "【พามันออกไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7160_Desc = {
    Text = "เมื่อคุณเข้าใกล้ วิญญาณแห่งความวุ่นวายที่ไม่เป็นระเบียบก็ปรากฏขึ้นจากโคลนอย่างกะทันหัน \n แขนสีดำยึดติดกับคุณแน่น ขณะพระองค์ร้องไห้และอ้อนวอน—\n เสนอของถวาย หรือพาพระองค์ออกไป。"
  },
  Event_7160_Name = {
    Text = "วิญญาณแห่งความวุ่นวาย"
  },
  Event_7161_ChoiceDesc1 = {
    Text = "【โบกมือไล่】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7161_ChoiceDesc2 = {
    Text = "【ปล่อยให้พัก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_7161_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7161_Desc = {
    Text = "ปีกของผีเสื้อที่กระพือสะบัดมีน้ำยางสีดำติดอยู่ โยกไปมาและบินผ่านไป ชั้นของน้ำยางสีดำที่ไหลออกมาจากปีก เมื่อแห้งแล้วจะถูกลมพัดหลุดออกมา\nมันบินจนเหนื่อยแล้ว หยุดอยู่ที่ปลายจมูกของคุณ。"
  },
  Event_7161_Name = {
    Text = "ผีเสื้อน้ำดำ"
  },
  Event_7162_ChoiceDesc1 = {
    Text = "【โบกมือไล่】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7162_ChoiceDesc2 = {
    Text = "【คงอยู่โดยไม่เคลื่อนไหว】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับการติดตั้ง「(Skill.Arg2)」"
  },
  Event_7162_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7162_Desc = {
    Text = "ปีกของผีเสื้อกระพือไปมา ลากเอายางดำเหนียวไปด้วย โยกเยกไปมาในอากาศ ชั้นของยางดำที่ไหลออกมาจากปีก ถูกลมพัดจนแห้งและหลุดออกไป\nมันบินจนเหนื่อยแล้ว หยุดอยู่ที่ปลายจมูกของคุณ。"
  },
  Event_7162_Name = {
    Text = "ผีเสื้อน้ำดำ"
  },
  Event_7163_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7163_Desc = {
    Text = "「ฉันเห็นความกล้าหาญ เห็นเจตจำนง เห็นจิตวิญญาณที่ส่องแสงเจิดจรัสเหมือนดวงดาว เดินไปข้างหน้าสู่ความทรงจำที่ถูกผนึกด้วยขี้ผึ้ง คุณจะต้องได้สิ่งที่ปรารถนา」"
  },
  Event_7163_Name = {
    Text = "วัตถุที่ถูกไล่ล่า"
  },
  Event_7164_ChoiceDesc1 = {
    Text = "【ปล่อยให้อยู่】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7164_ChoiceDesc2 = {
    Text = "【โบกมือไล่】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ถูกทำให้ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7164_ChoiceDesc3 = {
    Text = "【ต้อนรับผีเสื้อ】รับ 25 รอยดำ"
  },
  Event_7164_Desc = {
    Text = "พวกคุณเดินวนเวียนอยู่ในสถานพักฟื้นที่มีลมหนาวพัดแรง ผีเสื้อสีดำตัวหนึ่งบินโฉบมาอย่างสง่างามซึ่งไม่ควรมีอยู่ในฤดูกาลนี้\nปีกของผีเสื้อที่กระพือสะบัดมีน้ำยางสีดำติดอยู่ โยกไปมาและบินผ่านไป ชั้นของน้ำยางสีดำที่ไหลออกมาจากปีก เมื่อแห้งแล้วจะถูกลมพัดหลุดออกมา\nมันบินจนเหนื่อยแล้ว หยุดอยู่ที่ปลายนิ้วของคุณ。"
  },
  Event_7164_Name = {
    Text = "สิ่งที่ไม่ควรมีอยู่"
  },
  Event_7165_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์เงิน 3 ตัวเลือก 1, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7165_Desc = {
    Text = "คุณเริ่มรู้สึกเหนื่อยล้า。\nจิตสำนึกดึงคุณไป ข้ามบ่อ ข้ามภูเขา，\nบินไปนอกดวงอาทิตย์ บินไปนอกปีแสง，\nบินไปยัง...เตียงนอนในจักรวาลที่ไม่เหมือนใคร。"
  },
  Event_7165_Name = {
    Text = "พิธีปิดฉาก Ⅳ"
  },
  Event_7166_ChoiceDesc1 = {
    Text = "【ลองหาดูอีกครั้ง】"
  },
  Event_7166_Desc = {
    Text = "เงาขนาดใหญ่ได้คลุมคุณอย่างสมบูรณ์ น้ำลายที่มีกลิ่นคาวได้ทำให้คุณเปียกโชกเหมือนไก่ที่ถูกฝน.\n「หนูน้อย รีบมาเถอะ แค่สักครู่...」\n「ฉันสาบาน ฉันไม่ได้ตั้งใจจะกินคุณเลย...」\n「ฉันจะไม่มองท้องที่อวบอ้วนและฉ่ำของคุณแม้แต่ครั้งเดียว!」"
  },
  Event_7166_Name = {
    Text = "วัสดุหมายเลข 12"
  },
  Event_7167_ChoiceDesc1 = {
    Text = "【ลองหาดูอีกครั้ง】"
  },
  Event_7167_Desc = {
    Text = "หุ่นขี้ผึ้งที่แห้งเหี่ยวของนักปรัชญากำลังสูบยาสูบ ถูกปกคลุมด้วยม่านควันที่ขาว。\n「โลกอีกฝั่งมีอยู่แต่ไม่สามารถรู้ได้ ดังนั้นโลกอีกฝั่งจึงไม่อาจรู้จัก。」\n「ลองจินตนาการถึงโลกนี้ว่าเป็นเกม...\nสิ่งที่คุณกำลังมองหา อาจอยู่ที่อีกด้านของแผนที่。」"
  },
  Event_7167_Name = {
    Text = "วัสดุหมายเลข 45"
  },
  Event_7168_ChoiceDesc1 = {
    Text = "【ลองหาดูอีกครั้ง】"
  },
  Event_7168_Desc = {
    Text = "「ขอโทษ ไม่มีเจตนาที่จะทำให้รู้สึกไม่ดี...」\n「ฉันไม่ชอบหนู หนูมีปัญหาคือพวกมันไม่เคยกลัวมนุษย์...」\nชายชราเคราเผละนอนอยู่มุมห้อง ดวงตาที่เศร้าหมองของเขาจ้องมองมาที่คุณอย่างตั้งใจ。\n「แน่นอนว่าพวกคุณมีความมุ่งมั่นมาก」\n「นั่นดี แต่ยังไม่เพียงพอที่จะช่วยให้พวกคุณหลีกเลี่ยงภัยพิบัติ...」"
  },
  Event_7168_Name = {
    Text = "วัสดุหมายเลข 4"
  },
  Event_7169_ChoiceDesc1 = {
    Text = "【แสดงคำสาปแช่ง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7169_ChoiceDesc2 = {
    Text = "【ปฏิเสธรอก】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_7169_ChoiceDesc3 = {
    Text = "【ละเลย】"
  },
  Event_7169_Desc = {
    Text = "อีกาที่มีหลายหัวที่ดำมืดและมีอาการป่วยบินออกมาจากผ้าคลุมสีดำของผู้ศรัทธาแห่งโคมไฟ และลงบนไหล่ของคุณ \n「เห็นหัวของฉันไหม? แค่ลองชิมคำสาป ฉันก็จะมีหัวใหม่ขึ้นมา ให้ฉันดูสิ คำสาปของคุณ!」"
  },
  Event_7169_Name = {
    Text = "นกกาถูกสาป"
  },
  Event_7170_ChoiceDesc1 = {
    Text = "【ตอบสนองต่อเสียงเรียก】ลบการ์ดคำสั่ง 1 ใบ และเพิ่มชีวิต Arg1 หน่วย"
  },
  Event_7170_ChoiceDesc2 = {
    Text = "【ฉันไม่ได้กำลังหลบหนี】ได้รับสิ่งสร้างทองคำ 「(RelicConfig.Arg1)」，ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7170_Desc = {
    Text = "คุณวิ่งอย่างรวดเร็วในซอย อะดรีนาลีนถูกกระตุ้น กรดแลคติกถูกสร้างขึ้น กลูโคสถูกใช้จ่าย... เคออสกัดกร่อนสมองของคุณ ยึดครองความคิดของคุณ ในภาพลวงตาที่มีสีสันสดใสเร่งให้คุณหนีไปยังเส้นชัย \n ใช่แล้ว หนีไป ถ้าคุณไม่ได้หนีจริงๆ แล้วสิ่งที่รอคุณอยู่ทำไมถึงเป็นเคออสและสุญญตา ไม่มีอะไรเลยและจบลงอย่างไร้ผลล่ะ?"
  },
  Event_7170_Name = {
    Text = "วิ่ง"
  },
  Event_7171_ChoiceDesc1 = {
    Text = "【ย้อนรอยต้นเสียง】"
  },
  Event_7171_ChoiceDesc2 = {
    Text = "【เรียกลิลลี่และคูม】"
  },
  Event_7171_Desc = {
    Text = "เสียงต่ำและหนักจากช่องทางมิติในระยะไกลดังขึ้น ผสมผสานด้วยความกลัว ความหวัง และความไม่แน่นอน ราวกับกำลังเรียกหาพวกคุณ ตามมาด้วยเสียงกระซิบที่ไม่ชัดเจนของเด็กหญิง แล้วเสียงทั้งสองก็เริ่มเบาลงเรื่อยๆ。"
  },
  Event_7171_Name = {
    Text = "เสียงนำทาง"
  },
  Event_7172_ChoiceDesc1 = {
    Text = "【เก็บเข้ากระเป๋า】"
  },
  Event_7172_Desc = {
    Text = "สารสีเงินที่มีลักษณะใกล้เคียงกับปรอท สกัดจากน้ำเมือกการย่อยสลาย มีพลังจิตที่เข้มแข็ง ใช้หลักในการลิงก์ผู้ปลุกตื่นจำนวนมากขึ้นในพิธีกรรม。"
  },
  Event_7172_Name = {
    Text = "เงินใจ"
  },
  Event_7173_ChoiceDesc1 = {
    Text = "【กรุณาให้เขาหลีกทาง】"
  },
  Event_7173_ChoiceDesc2 = {
    Text = "【สอบถามตัวตน】"
  },
  Event_7173_Desc = {
    Text = "พวกคุณก้าวเข้าสู่ห้องโดยสารที่มืดมิด ความรู้สึกแปลกประหลาดลอยขึ้นมาในใจ \n ในห้องโดยสารนี้ว่างเปล่า ผู้โดยสารได้หนีไปแล้ว บนพื้นมีซากศพของมอนสเตอร์กระจายอยู่ กำลังค่อยๆ จางหายไป \n ที่กลางห้องโดยสาร มีผู้ชายคนหนึ่งยืนอยู่ \n 「ฉันเชื่อว่ามีโชคชะตาในโลก และก็เป็นโชคชะตาที่ทำให้เรานั่งรถไฟใต้ดินขบวนเดียวกัน」"
  },
  Event_7173_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅳ"
  },
  Event_7174_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7174_Desc = {
    Text = "「ดวงตาของคุณสวยมาก เหมือนดวงดารา」\nชาร์ล็อตต์หัวเราะอย่างมีความสุข ผมที่บ้าคลั่งของเธอลงมาอย่างเรียบร้อย\n「คุณต้องเป็นที่นิยมมากในโรงเรียนใช่ไหม ฉันก็ชอบคุณเหมือนกัน」\nก่อนที่จะจากไป เธอจูบที่หน้าผากของคุณ\nคุณรู้สึกอุ่นร่างกาย มีบางอย่างดูเหมือนจะเปลี่ยนไป。"
  },
  Event_7174_Name = {
    Text = "เงาของนักสืบ"
  },
  Event_7175_ChoiceDesc1 = {
    Text = "【อ่าน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7175_ChoiceDesc2 = {
    Text = "【เก็บในกระเป๋า】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้าง：「(RelicConfig.Arg2)」"
  },
  Event_7175_Desc = {
    Text = "กระดาษแผ่นหนึ่งที่มีสีเหลืองร่วงหล่นจากใต้ผ้าคลุมของผู้ศรัทธาแห่งโคมไฟ\nบนกระดาษมีข้อความแปลกๆ ที่เขียนแน่นหนา รูปร่างแปลกประหลาด บางอย่างดูเหมือนอักษรภาพ บางอย่างมีลักษณะแปลกๆ ยกขึ้น และบางตัวอักษรก็ทับซ้อนกันอยู่ มีเพียงไม่กี่คำที่สามารถอ่านออกได้。"
  },
  Event_7175_Name = {
    Text = "รหัสลับ·บน"
  },
  Event_7176_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7176_Desc = {
    Text = "คุณพูดว่า:「อุ๊ย ชาร์ล็อตต์! ไม่ได้!」\nผมของชาร์ล็อตต์หมุนวนอย่างบ้าคลั่ง เธอโกรธแล้ว\n「ฉันจะพิสูจน์ให้คุณเห็น! ดูความสามารถของฉัน!」"
  },
  Event_7176_Name = {
    Text = "เงาของนักสืบ"
  },
  Event_7177_ChoiceDesc1 = {
    Text = "【ติดเชื้อ「(Skill.Arg1)」, ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」】"
  },
  Event_7177_ChoiceDesc2 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7177_Desc = {
    Text = "เหตุการณ์302 (กำลังพัฒนา), ยังไม่ใช่เวอร์ชันสุดท้าย"
  },
  Event_7177_Name = {
    Text = "เหตุการณ์ 302（กำลังพัฒนา）"
  },
  Event_7178_ChoiceDesc1 = {
    Text = "【รับคำขอ】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」"
  },
  Event_7178_ChoiceDesc2 = {
    Text = "【ไม่รับคำขอ】ได้รับ 25 รอยดำ"
  },
  Event_7178_Desc = {
    Text = "ขากรรไกรดังกรอดๆ เสียงมีจังหวะตามแบบแผน และเพื่อนร่วมทางของคุณพอดีมีความรู้ด้านการเข้ารหัส\nข้อความที่ถอดรหัสแล้วมีดังนี้:\n「สวัสดีครับ กรุณาเรียกผมว่า @2 ดร. ผมเคยเป็นนักสะสม นักธรรมชาติวิทยา……\n(ส่วนนี้เป็นการแนะนำอาชีพและตำแหน่งที่ยาวเหยียด ขอโทษที่ข้ามไป)\nสรุปแล้ว คุณช่วยหาครึ่งหนึ่งของผมได้ไหม? มันคือขากรรไกรบนขนาดเล็กชิ้นหนึ่ง\nหากสามารถหามันเจอ คลังสมบัติส่วนตัวของผมจะเปิดประตูต้อนรับคุณ」"
  },
  Event_7178_Name = {
    Text = "เสียงครืดคราด"
  },
  Event_7179_ChoiceDesc1 = {
    Text = "【ลงทุนหนึ่งร้อยฟัง】ติดเชื้อ「(Skill.Arg1)」, ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」"
  },
  Event_7179_ChoiceDesc2 = {
    Text = "【ใส่ชิ้นส่วนห้าชิ้น】ได้รับ 25 รอยดำ"
  },
  Event_7179_Desc = {
    Text = "กระเป๋าเงินปักลายกำลังคลานเข้าหาคุณ พร้อมอ้าปากขนาดใหญ่สีดำสนิท\nตั้งแต่จากเจ้าของหญิงผู้มั่งคั่งไป มันหิวโหยมาเป็นเวลาหลายสิบปี รอคอยที่จะเติมเต็มท้อง\nคุณแอบมองเข้าไปในกระเป๋าเงิน ข้างในกลับว่างเปล่า มีเพียงความมืดที่ลึกจนมองไม่เห็นก้นบึ้ง。"
  },
  Event_7179_Name = {
    Text = "กระเป๋าเงินหิวกระหาย"
  },
  Event_7180_ChoiceDesc1 = {
    Text = "【เป็นความมุ่งมั่นที่แน่วแน่】ลบการ์ดคำสั่ง 1 ใบ และฟื้นฟูชีวิต Arg1 หน่วย"
  },
  Event_7180_ChoiceDesc2 = {
    Text = "【ความทะเยอทะยานสู่ความสำเร็จ】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」ปลดล็อกทักษะ「(Skill.Arg2)」"
  },
  Event_7180_Desc = {
    Text = "「สองคนที่ดื้อดึง บ้านคนจนกำลังมีอันตรายอยู่แล้ว」เสียงของดอลล์ดังออกมาจากเครื่องสื่อสารอย่างกระทันหัน「พวกคุณมีแผนจะทำอะไรต่อไป ช่วยเธอเย็บหัวให้ไหม?」\n「ตอนนี้ไม่ใช่เวลาพูดจาไร้สาระนะ ดอลล์!」\n「ฉันรู้ ฉันฟังออก」ดอลล์กล่าว「ใจเย็นๆ รู้ไหมว่ากุญแจสู่ความสำเร็จคืออะไร?」"
  },
  Event_7180_Name = {
    Text = "กฎของโรแกน"
  },
  Event_7181_ChoiceDesc1 = {
    Text = "【ติดเชื้อ「(Skill.Arg1)」, ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」】"
  },
  Event_7181_ChoiceDesc2 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7181_Desc = {
    Text = "เหตุการณ์304（กำลังพัฒนา），ยังไม่ใช่เวอร์ชันสุดท้าย"
  },
  Event_7181_Name = {
    Text = "เหตุการณ์304（ในระหว่างการพัฒนา）"
  },
  Event_7182_ChoiceDesc1 = {
    Text = "【ติดเชื้อ「(Skill.Arg1)」, ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」】"
  },
  Event_7182_ChoiceDesc2 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7182_Desc = {
    Text = "เหตุการณ์305 (กำลังพัฒนา)，ยังไม่ใช่ผลลัพธ์สุดท้าย"
  },
  Event_7182_Name = {
    Text = "เหตุการณ์305（กำลังพัฒนา）"
  },
  Event_7183_ChoiceDesc1 = {
    Text = "【วางสาย】ได้รับการแกะสลักขั้นสูง เลือก 1 จาก 3"
  },
  Event_7183_ChoiceDesc2 = {
    Text = "【รับโทรศัพท์】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ถูกโจมตีด้วย「(Skill.Arg2)」"
  },
  Event_7183_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7183_Desc = {
    Text = "พวกคุณผ่านห้องพักของหัวหน้าพนักงานรถไฟ ในมุมลับตา เสียงโทรศัพท์ดังขึ้นอย่างเฉียบพลัน"
  },
  Event_7183_Name = {
    Text = "การโทรจากรถไฟ"
  },
  Event_7184_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7184_Desc = {
    Text = "ความแวววับจางลง แต่ยังคงมีอยู่จริง \n เงินใจที่จางเช่นนี้ยากที่จะอัญเชิญผู้ปลุกตื่น แต่ว่าใช้ในการเสริมสร้างนั้นถือว่าเยี่ยมยอด——ที่เรียกว่าเทคโนโลยีซิลเวอร์คอร์ ก็เป็นเช่นนี้แหละ。"
  },
  Event_7184_Name = {
    Text = "การพิสูจน์การมีอยู่"
  },
  Event_7185_ChoiceDesc1 = {
    Text = "【ภาพเหมือนสุภาพสตรี】สุ่มเพิ่มระดับคุณภาพการแกะสลักของการ์ด 1 ใบ"
  },
  Event_7185_ChoiceDesc2 = {
    Text = "【ภาพถ่ายครอบครัวหุ่นขี้ผึ้ง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7185_Desc = {
    Text = "พิพิธภัณฑ์หุ่นขี้ผึ้งยังมีการสะสมผลงานศิลปะมากมายในเวลาเดียวกัน\nบุคคล ทิวทัศน์ ของตกแต่งบ้าน ซึ่งมีทั้งแบบสมจริงและแบบนามธรรม...\nพวกมันตกแต่งผนังที่เดิมทีน่าเบื่อให้ดูน่าสนใจมากขึ้น\nความสนใจของคุณถูกดึงดูดไปยังหนึ่งในนั้น มันคือภาพวาดหนึ่ง—"
  },
  Event_7185_Name = {
    Text = "ห้องแสดงภาพเหมือน"
  },
  Event_7186_ChoiceDesc1 = {
    Text = "【ดำเนินการต่อ】สุ่มการ์ดคำสั่ง 1 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7186_ChoiceDesc2 = {
    Text = "【ออกจาก】เพิ่มพลังชีวิตสูงสุด Arg1 หน่วย และติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7186_Desc = {
    Text = "ตาชั่งที่ใช้สำหรับชั่งน้ำหนัก。\nเบื้องหลังมันมีอวัยวะนับไม่ถ้วนแช่อยู่ในฟอร์มาลินสีแดง。\nพวกมันถูกจัดเรียงอย่างเป็นระเบียบบนชั้นเก็บของ。\nคุณหยิบสมุดบันทึกข้างๆ ขึ้นมาเปิดอ่าน：\n「หัวใจ：8 ออนซ์，สมอง：50 ออนซ์……」"
  },
  Event_7186_Name = {
    Text = "การลงทะเบียนอวัยวะ"
  },
  Event_7187_ChoiceDesc1 = {
    Text = "【เปิดของขวัญ】ได้รับการ์ดหายาก"
  },
  Event_7187_Desc = {
    Text = "เงาของเด็กเล็กๆ พลิ้วไหวอยู่ตรงหน้าคุณ คุณไม่สามารถแยกแยะได้ว่านั่นคือเด็กตัวจริงหรือการสะท้อนของจิตวิญญาณบางอย่างในดินแดนลับแล แต่—คุณมองไปที่กล่องที่หลงเหลืออยู่บนพื้น ซึ่งเขียนคำว่า「ของขวัญ」ด้วยตัวอักษรที่เรียบง่าย。"
  },
  Event_7187_Name = {
    Text = "ของขวัญแห่งความดี"
  },
  Event_7188_ChoiceDesc1 = {
    Text = "【เรียกอีกา】ได้รับ 40 รอยดำ, ได้รับผลกระทบ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_7188_ChoiceDesc2 = {
    Text = "【หนีไปไกลๆ】ได้รับรอยดำ 25 อัน"
  },
  Event_7188_Desc = {
    Text = "นกนางนวลขาวหยุดอยู่บนเสาธง เสาธงถูกปกคลุมด้วยน้ำค้างสีขาว。\nท่อเสียงสั่นสะเทือนพร้อมกัน พวกมันขับไล่การมีอยู่สีดำ และยังขับไล่นกสีดำที่ไม่ใช่ของทะเลลึกอีกด้วย。"
  },
  Event_7188_Name = {
    Text = "กุยบินโดดเดี่ยว"
  },
  Event_7189_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7189_Desc = {
    Text = "คุณได้ยินว่าเพลงนั้นถูกดัดแปลงมาจากเพลงรัก\nที่ปลายเพลงรักนั้น กวีพูดว่า:\n「จนกระทั่งเสียงของมนุษย์ปลุกเรา เราก็จมน้ำตาย」\nไม่ใช่ตอนนี้ คุณคิดในใจ\nคุณยังคงเฝ้ารอให้มนุษย์ปลุกคุณ。"
  },
  Event_7189_Name = {
    Text = "เสียงฝูงกา"
  },
  Event_7190_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7190_Desc = {
    Text = "ฟิล์มม้วนหนึ่งที่เต็มไปด้วยฝุ่น แต่ในบ้านนี้ไม่มีเครื่องฉาย และตอนนี้ก็ไม่ใช่เวลาที่จะนั่งพักผ่อนกับคฤหาสน์ ฟิล์ม และน้ำชายามบ่าย \n บางทีคุณอาจต้องรอนานกว่าจะมีโอกาสรู้เนื้อหาของฟิล์ม。"
  },
  Event_7190_Name = {
    Text = "ความทรงจำของแสงและเงา"
  },
  Event_7191_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักขั้นสูง เลือก 1 จาก 3，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7191_Desc = {
    Text = "คุณเดินตามหลังเด็กชาย ไม่ไกลและไม่ใกล้เกินไป \nตุบ ตุบ ตุบ…… เด็กชายหยุดที่มุมถนน \nคุณเห็นแสงสีแดงที่ไม่มั่นคงอยู่เบื้องหลังเขา สัญชาตญาณบอกคุณว่าพิพิธภัณฑ์หุ่นขี้ผึ้งอยู่ข้างหน้า \nเด็กชายหันกลับมามอง เขาไม่มีตา เบ้าตาของเขามืดมิด \nเขายิ้มให้คุณ。"
  },
  Event_7191_Name = {
    Text = "พิธีสุดท้ายⅠ"
  },
  Event_7192_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7192_Desc = {
    Text = "คุณตบไหล่เขาเบาๆ \n เด็กชายหันกลับมา เขาไม่มีตา เบ้าตาของเขามืดมิด \n 「สวัสดีตอนเย็น ฉันกำลังมองหาทางไปพิพิธภัณฑ์หุ่นขี้ผึ้ง」 \n เด็กชายชี้ไปข้างหน้า คุณเห็นแสงสีแดงที่ไม่มั่นคงอยู่เบื้องหลังเขา \n สัญชาตญาณบอกคุณว่าพิพิธภัณฑ์หุ่นขี้ผึ้งอยู่ที่นั่น \n เมื่อหันกลับมา เด็กชายก็จากไปแล้ว เหลือไว้เพียงเงาที่ยาวเหยียดจากโคมไฟถนน。"
  },
  Event_7192_Name = {
    Text = "พิธีสุดท้ายⅠ"
  },
  Event_7193_ChoiceDesc1 = {
    Text = "【กดค้างที่อีกา】ได้รับ 35 รอยดำ, ติดเชื้อ (Skill.Arg2), เลือกต่อไป"
  },
  Event_7193_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_7193_Desc = {
    Text = "อีกาที่โดดเดี่ยวส่งเสียงแหบ ๆ ดึงขนสีดำของตัวเองออกทีละเส้น \n มันเจ็บจนตัวสั่น ร้องเสียงแหลมสูง แต่ก็หยุดการเคลื่อนไหวที่เร็วขึ้นเรื่อย ๆ ไม่ได้ \n 「กา——กา——」 \n น้ำตาสีน้ำเงินที่มีสีดำไหลออกจากดวงตาของมัน นอกจากคุณ ไม่มีใครเห็น。"
  },
  Event_7193_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_7194_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7194_Desc = {
    Text = "ความรู้ล้ำค่าไหลเข้ามาในจิตใจของคุณ แล้วกลายเป็นหมอกควัน... เมื่อคุณตื่นขึ้นมาอีกครั้ง หนังสือปกเหลืองที่แปลกประหลาดเล่มนั้นก็ได้หายไปอย่างไร้ร่องรอย..."
  },
  Event_7194_Name = {
    Text = "กระดาษม้วนสีเหลือง"
  },
  Event_7195_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7195_Desc = {
    Text = "คุณจัดการกับหุ่นขี้ผึ้งเหล่านี้ได้อย่างง่ายดาย มันก้มศีรษะลงอยู่ตรงหน้าคุณ。\nที่ฐานของหุ่นขี้ผึ้งดูเหมือนจะมีการเขียนข้อความอยู่ไม่กี่บรรทัด。\n「อัลลูวิ@2ปี11เดือน\nผลิตโดยโรเจอร์สที่@2วิทยาลัย」\nคุณจำได้ว่าโรเจอร์สเคยศึกษาที่วิทยาลัยศิลปะในสาขาประติมากรรม หุ่นขี้ผึ้งที่งุ่มง่ามเหล่านี้คงเป็นแบบฝึกหัดในสมัยนั้นของเขาแน่ๆ。"
  },
  Event_7195_Name = {
    Text = "แบบฝึกหัด"
  },
  Event_7196_ChoiceDesc1 = {
    Text = "【ทำไมล่ะ】"
  },
  Event_7196_ChoiceDesc2 = {
    Text = "【ตกลงสู่ทะเลลึก】"
  },
  Event_7196_Desc = {
    Text = "「คนหลอกลวง! เอาลูกชายของฉันกลับมา!」\n「เจ้าไม่ใช่นักบวชแห่งเรือหรือ? หน้าที่ของเจ้าคือการปกปักเรือไม่ใช่หรือ? ทำไมมีเพียงเรือลำเดียวที่กลับมา, พูดสิ, พูดสิ!」\n「จงจบชีวิตเธอด้วยการจมน้ำ! ความทุกข์ทรมานที่พ่อของฉันต้องเจอ, เธอก็ต้องเผชิญเหมือนกัน!」\n「จงจบชีวิตเธอด้วยการจมน้ำ, จงจบชีวิตเธอด้วยการจมน้ำ!」\n「จงจบชีวิตคนหลอกลวงนี้ด้วยการจมน้ำ! มัดเธอไว้กับก้อนหิน!」\nน้ำทะเลพัดเข้าสู่ปากและจมูก, อากาศถูกบีบออกจากทุกซอกมุมของหลอดลมของเธอ, เธอยังคงสวมใส่ชุดกระโปรงสีขาวหรูหราและสะอาดบริสุทธิ์นั่นอยู่。\nความคิดแรกหลังจากที่เธอเป็นนักบวช ผุดขึ้นมาจากมุมที่ดำมืดที่สุดของสมอง ก่อนที่จะช้ารู้ตัว。\n「ใช่แล้ว, เรือลำนั้น, ทำไมมันถึงจมหละ?」"
  },
  Event_7196_Name = {
    Text = "จมลงในทะเล"
  },
  Event_7197_ChoiceDesc1 = {
    Text = "【กดค้างที่อีกา】ได้รับ 30 รอยดำ, ได้รับผล「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_7197_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_7197_Desc = {
    Text = "อีกาที่โดดเดี่ยวส่งเสียงแหบพร่า ดึงขนสีดำของตัวเองออกทีละขน \n มันเจ็บจนตัวสั่น ร้องเสียงแหลม แต่ไม่สามารถหยุดการเคลื่อนไหวที่เร็วขึ้นเรื่อยๆ \n 「ก๊าบ——ก๊าบ——」 \n น้ำตาสีน้ำเงินที่มีน้ำดำไหลออกจากตาของมัน นอกจากคุณ ไม่มีใครได้เห็น。"
  },
  Event_7197_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_7198_ChoiceDesc1 = {
    Text = "【ค้นหาต่อ】 เพิ่ม Arg1 คะแนนชีวิต, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7198_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7198_Desc = {
    Text = "ดูเหมือนว่าจะมีมือสองข้างวางอยู่บนไหล่ของคุณ ทั้งแข็งแกร่งและมั่นคง แต่เมื่อคุณหันกลับไปหาที่มา สัมผัสที่เคยรู้สึกได้อย่างชัดเจนกลับกลายเป็นล่องลอยและยากที่จะหาเจอ。"
  },
  Event_7198_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7199_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7199_Desc = {
    Text = "สะพานรถไฟ หลอดเลือดและเส้นประสาทของลอนดีเนี่ยน เชื่อมต่อหัวใจและอวัยวะสี่ส่วนของเมือง โรงพยาบาลจิตไรอยู่ที่ปลายอวัยวะสี่ส่วน รอการส่งเลือดและสัญญาณอย่างเงียบ ๆ."
  },
  Event_7199_Name = {
    Text = "ภาพลวงตาทางรถไฟ"
  },
  Event_7200_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7200_Desc = {
    Text = "คุณวางกระเป๋าเดินทางลงบนพื้นแล้วเหยียบลงไปแรงๆ สักสองสามครั้ง เพื่อยืนยันว่ามันไม่สั่นไหวอีกแล้วจึงค่อยหยิบขึ้นมาใหม่ \n ปัดฝุ่นที่อยู่บนกระเป๋า ขณะที่มอร์ฟี่มองด้วยสายตาสงสัย คุณทั้งคู่จึงเดินต่อไป。"
  },
  Event_7200_Name = {
    Text = "จดหมายไม่ทันรู้เรื่อง"
  },
  Event_7201_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7201_Desc = {
    Text = "อันตรายกำลังจ้องเขม็งคุณอยู่อีกฝั่งของประตูไม้ ไม่เหมาะที่จะเสียเวลาไปมากนัก ใส่มันลงในกล่องเก็บของซะ"
  },
  Event_7201_Name = {
    Text = "กระดาษม้วนสีเหลือง"
  },
  Event_7202_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ Arg1 รอยดำ ติดเชื้อ「(Skill.Arg2)」 โปรดเลือกต่อ"
  },
  Event_7202_ChoiceDesc2 = {
    Text = "【ละเว้น】ออก"
  },
  Event_7202_Desc = {
    Text = "มัน หรือจะเรียกว่าพวกมัน ก็กำลังโฉบไปมาในห้องนอน ชนกับโคมไฟจนดังโครมคราม"
  },
  Event_7202_Name = {
    Text = "โคมไฟหงส์ดำ"
  },
  Event_7203_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7203_Desc = {
    Text = "ที่นี่คือมิติแห่งจิตวิญญาณ เป็นโลกของความรู้ทางจิตวิญญาณ \n นอกจากการกวนสมองของคุณ พวกเขาก็ทำอะไรไม่ได้เลย。"
  },
  Event_7203_Name = {
    Text = "พายุความรู้ทางจิตวิญญาณ"
  },
  Event_7204_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7204_Desc = {
    Text = "กะโหลกศีรษะ: แฮงค์ ทีลินฮาร์สท์ A.F.186-A.F.203 เกาะครีโอล\nกระดูกสันหลัง: แอนดี้ คลอว์ฟอร์ด A.F.177-A.F.203 นารากันเซ็ท\n……ไม่สามารถคิดมากได้。"
  },
  Event_7204_Name = {
    Text = "ป้ายชื่อ"
  },
  Event_7205_ChoiceDesc1 = {
    Text = "【ตรวจสอบชิ้นส่วน】สุ่มได้รับการ์ดคำสั่ง 3 ใบจากกองไพ่，เลือกการ์ด 1 ใบเพื่อลบ และได้รับรอยดำ 75 อัน"
  },
  Event_7205_ChoiceDesc2 = {
    Text = "【สอบถามดอลล์】สุ่มเลือกการ์ดคำสั่ง 3 ใบจากสำรับ，เลือกสำเนาต้นฉบับของการ์ด 1 ใบเข้าสู่สำรับ และได้รับรอยดำ 25 อัน"
  },
  Event_7205_ChoiceDesc3 = {
    Text = "【ละเว้น】ได้รับรอยดำ 50"
  },
  Event_7205_Desc = {
    Text = "ชิ้นส่วนโลหะที่ดอร์ให้คุณไว้นั้นกระเพื่อมอย่างไม่สงบที่หน้าอกของคุณ เหมือนกับผีเสื้อที่ถูกรบกวน"
  },
  Event_7205_Name = {
    Text = "ไม้พิณที่ไม่สงบ"
  },
  Event_7206_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7206_Desc = {
    Text = "「พระองค์รออย่างเงียบสงบที่ปลายทาง ไม่ว่าคุณจะกำหนดปลายทางไว้ที่ไหน—ลองมองไปที่ผู้จัดการสาวคนนั้น การหลบหนีของเธอในที่สุดก็ส่งผลให้เกิดความบ้าคลั่ง」"
  },
  Event_7206_Name = {
    Text = "วัตถุที่ถูกไล่ล่า"
  },
  Event_7207_ChoiceDesc1 = {
    Text = "【ออกจาก】ไม่มีการค้นพบใดๆ"
  },
  Event_7207_Desc = {
    Text = "กำลังพัฒนา, เหตุการณ์พิเศษ"
  },
  Event_7207_Name = {
    Text = "2_16 ชั่วคราว"
  },
  Event_7208_ChoiceDesc1 = {
    Text = "【ปลอบมัน】เพิ่มพลังชีวิตสูงสุด Arg1 หน่วย"
  },
  Event_7208_ChoiceDesc2 = {
    Text = "【ละเลยมัน】การ์ดคำสั่งสุ่ม 2 ใบรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ 2 ใบ「(Skill.Arg2)」"
  },
  Event_7208_Desc = {
    Text = "ลิงก์อบอุ่นอวัยวะที่ยังเป็นหัวใจของมนุษย์อยู่ \n มันเลียนแบบจังหวะการหายใจของลิงก์และกระตุ้นอยู่เสมอ เหมือนกับว่าการกระทำเช่นนี้จะทำให้มันไม่ถูกทอดทิ้ง และมันมีสิทธิ์ที่จะเดินเคียงข้างลิงก์ตลอดไป。"
  },
  Event_7208_Name = {
    Text = "ห้องหัวใจซ้าย"
  },
  Event_7209_ChoiceDesc1 = {
    Text = "การแกะสลักขั้นสูงแบบสุ่ม"
  },
  Event_7210_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7210_Desc = {
    Text = "ความเย็นชาของคุณทำให้เจ้าของเสียงรู้สึกเสียใจอยู่ไม่น้อย ผิวน้ำกระเพื่อมเล็กน้อยแล้วสงบลง"
  },
  Event_7210_Name = {
    Text = "เสียงจากอีกฟาก"
  },
  Event_7211_ChoiceDesc1 = {
    Text = "【เลือกการ์ด 1 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」】ทดลองการแกะสลัก"
  },
  Event_7211_ChoiceDesc2 = {
    Text = "【เลือกการ์ดหนึ่งใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」】ทดสอบแพ็คเกจที่หล่น"
  },
  Event_7211_Desc = {
    Text = "ทดสอบการแกะสลักเฉพาะ"
  },
  Event_7211_Name = {
    Text = "ชุดทดสอบการแกะสลัก1"
  },
  Event_7212_ChoiceDesc1 = {
    Text = "【ออกจาก】เลือกการตื่นรู้ 1 ชื่อของร่างกายที่ตื่นขึ้น"
  },
  Event_7212_Desc = {
    Text = "คุณลูบหัวเด็กชาย นำทางเขาให้พูดตามคุณต่อไป \n「เพลงที่มอบให้แม่——」 \n เสียงเหมือนผีเสื้อกลางคืนลอยออกจากเวทีที่ว่างเปล่า \n ค่อยๆ ลงสู่ที่นั่งผู้ชมที่มืดมิด。"
  },
  Event_7212_Name = {
    Text = "พิธีปิดฉาก Ⅲ"
  },
  Event_7213_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์ทองคำ 3 ตัวเลือก 1，ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7213_Desc = {
    Text = "คุณไม่แสดงอาการอะไร หญิงสาวผู้มีฐานะสูงส่งคนหนึ่งก็วิ่งขึ้นไปบนเวทีอย่างกะทันหัน \n เธอใช้ความบ้าคลั่งบีบปากเด็กชายแล้วเสียบไม้ที่อยู่ในมือของเธอเข้าไปอย่างแรง \n 「พูดสิ พูดกับฉัน」 \n เด็กชายมีเลือดสีดำไหลออกจากปาก เขาพยายามพูดต่อไปอย่างไม่ชัดเจน \n 「เพลงที่มอบให้แม่...」"
  },
  Event_7213_Name = {
    Text = "พิธีปิดฉาก Ⅲ"
  },
  Event_7215_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7215_Desc = {
    Text = "นั่นไม่ใช่หน้าต่าง แต่เป็นกระจก ในกระจกสะท้อนใบหน้าที่ตึงเครียดของราโมน่า \n ทำไมในห้องนี้ถึงไม่มีหน้าต่าง มีเพียงกระจกขนาดใหญ่แขวนอยู่บนผนัง?"
  },
  Event_7215_Name = {
    Text = "การสะท้อนในหน้าต่าง"
  },
  Event_7216_ChoiceDesc1 = {
    Text = "【จับกุญแจเงิน】การตื่นรู้ร่างกายที่ตื่นขึ้นสุ่ม 1 คน ติดเชื้อ 「(Skill.Arg1)」"
  },
  Event_7216_ChoiceDesc2 = {
    Text = "【ปิดตาทั้งสอง】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_7216_Desc = {
    Text = "คุณถูกแรงดึงดูดที่ยิ่งใหญ่และไร้สาระฉีกขาด ร่างกายบิดเบี้ยวคลานอยู่บนพื้น ราวกับถูก@2จากมิติอื่นควบคุม.\n「ไม่...ไม่...」\nความมีสติของคุณพังทลายทีละนิด เสียงหัวเราะที่บ้าคลั่งและเสียงกรีดร้องที่ไม่ชัดเจนผสมกัน เหมือนกับใยแมงมุมขนาดใหญ่ที่ผูกมัดจิตสำนึกของคุณ ไหลออกมาจากปากเป็นเพียงเสียงคร่ำครวญที่ไม่ชัดเจนเท่านั้น。"
  },
  Event_7216_Name = {
    Text = "ตาที่จ้องมอง"
  },
  Event_7217_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7217_Desc = {
    Text = "สีสันของทางช้างเผือกเปลี่ยนแปลง สร้างลวดลายที่ไม่สามารถอธิบายได้ใต้เท้าของคุณ งดงามราวกับทับทิม แต่บวมเป่งเหมือนแมงกะพรุน แสงสีแดงเริ่มส่องออกมาจากกระเป๋าเดินทาง…"
  },
  Event_7217_Name = {
    Text = "ทางแยกของดวงดาว"
  },
  Event_7218_ChoiceDesc1 = {
    Text = "【ลบภาพลวง】ความเครียด+10。"
  },
  Event_7218_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7218_Desc = {
    Text = "ใบหน้าที่เลือนรางปรากฏขึ้นอย่างกระทันหัน พวกมันล้อมรอบคุณอยู่ ใช้สายเสียงที่ไม่มีอยู่จริงถอนหายใจอย่างสิ้นหวัง。"
  },
  Event_7218_Name = {
    Text = "ภาพลวง"
  },
  Event_7221_ChoiceDesc1 = {
    Text = "【รับ】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」"
  },
  Event_7221_ChoiceDesc2 = {
    Text = "【ก้มลงดู】ได้รับ 75 รอยดำ, ติด「(Skill.Arg2)」"
  },
  Event_7221_Desc = {
    Text = "อีกากำลังโฉบอยู่ในท้องฟ้าที่ถูกซอยเป็นบล็อกเล็ก ๆ โดยซอยเล็ก ๆ ส่งเสียงร้องที่ทำให้รู้สึกไม่สบายใจ \n ฝูงกากระสับกระส่ายขึ้นทันที ราวกับว่าธรรมชาติที่ผิดปกติอย่างหนึ่งถูกบิดเบือนหรือถูกปลุกขึ้น พวกมันตื่นตระหนกและดุร้าย ไล่ตีกันและฉีกกัน จนมีบางสิ่งตกลงมา。"
  },
  Event_7221_Name = {
    Text = "ฝูงอีกาสับสน"
  },
  Event_7222_ChoiceDesc1 = {
    Text = "【ปฏิบัติตามคำสั่ง】เพิ่ม Arg1 คะแนนชีวิต"
  },
  Event_7222_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7222_Desc = {
    Text = "คุณพยายามใช้พลังการย้อนรอยของกุญแจเงินเพื่อค้นหาจุดติดต่อที่ใกล้ที่สุด แต่ข้อมูลที่ได้รับกลับมีความผิดปกติที่ยากจะตรวจจับเหมือนถูกขัดขวาง。"
  },
  Event_7222_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7223_ChoiceDesc1 = {
    Text = "【มอบให้ดอร์】สุ่มการ์ดคำสั่ง 1 ใบได้รับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7223_ChoiceDesc2 = {
    Text = "【อ่านป้าย】เพิ่มพลังชีวิตสูงสุด Arg1 ได้รับผลของ「(Skill.Arg2)」"
  },
  Event_7223_Desc = {
    Text = "จากร่างทดลองของสมาคมนักประติมากรรมที่คุณเอาชนะมา ป้ายชื่อกรอบโลหะหนึ่งชิ้นหล่นลงมา กุญแจเงินรับรู้ถึงป้ายชื่อและเปล่งแสงสว่างเล็กน้อย。"
  },
  Event_7223_Name = {
    Text = "ป้ายชื่อ"
  },
  Event_7224_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7224_Desc = {
    Text = "ผู้ถือมีดส่งเสียงร้องยาว เหมือนเสียงดังที่สามารถตัดขาดภูเขาและทะเลได้ \n เสียงนั้นหายไปในทันที และผู้เหยียบทะเลอีกสองคนก็หายไปด้วย... ที่แท้เป็นเพียงภาพลวงที่สะท้อนออกมาจากดินแดนลับแล。"
  },
  Event_7224_Name = {
    Text = "ไล่ล่าอย่างไม่ย่อท้อ"
  },
  Event_7225_ChoiceDesc1 = {
    Text = "【ซ่อมแซมหุ่นขี้ผึ้ง】เลือกการ์ดและลดการใช้พลังการคำนวณลง 1"
  },
  Event_7225_Desc = {
    Text = "คุณถือเทียนไข เดินผ่านหมอกที่มืดมัว มายืนอยู่ต่อหน้าเธอ \nนี่คือหุ่นขี้ผึ้งที่ยังไม่เสร็จ \nใบหน้าที่งดงามถูกแบ่งออกเป็นสองส่วน หนึ่งส่วนยิ้ม อีกหนึ่งส่วน@1 \nจงเป็นเทพเจ้าของเธอ \nมอบความงามให้เธอ มอบน้ำตาให้เธอ \nแกะสลักเธอ หรือทำลายเธอ。"
  },
  Event_7225_Name = {
    Text = "หุ่นขี้ผึ้งที่ยังไม่เสร็จ"
  },
  Event_7226_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7226_Desc = {
    Text = "「แน่นอน ฉันเคยเห็นการสูญสลายด้วยตาตัวเอง」คุณตอบกลับ。\nใช่ นั่นเป็นเพียงความตายอันน่าสลดของหนูตัวเล็ก การเน่าเปื่อยของหัวใจ และงานศพของดอกไอริสที่จมอยู่ในความมืดของยามราตรี。"
  },
  Event_7226_Name = {
    Text = "สวรรค์ที่สาบสูญ"
  },
  Event_7227_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7227_Desc = {
    Text = "「ประเทศเทพ……สูญสลาย……หัวข้อที่ไม่มีตัวตน……ข้าไม่ทราบว่าอย่างไรถึงจะเรียกว่าสูญสลาย。」\nเงาสองเงาได้หัวเราะเบาๆ รอบกายเปล่งประกายแสงสีขาวบริสุทธิ์. \n「ดังนั้นในขณะนี้ ท่านกำลังจะเป็นพยานในการสูญสลายที่แท้จริงครั้งหนึ่ง。」"
  },
  Event_7227_Name = {
    Text = "สวรรค์ที่สาบสูญ"
  },
  Event_7228_ChoiceDesc1 = {
    Text = "【รวมกระดาษ】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7228_ChoiceDesc2 = {
    Text = "【อ่าน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7228_ChoiceDesc3 = {
    Text = "【ทิ้งมันไป】ได้รับ 50 รอยดำ"
  },
  Event_7228_Desc = {
    Text = "กระดาษแผ่นหนึ่งที่มีสีเหลืองร่วงหล่นจากใต้ผ้าคลุมของผู้ศรัทธาแห่งโคมไฟ\nบนกระดาษมีข้อความแปลกๆ ที่เขียนแน่นหนา บางอย่างดูเหมือนอักษรภาพ บางอย่างมีลักษณะแปลกๆ ยกขึ้น และบางตัวอักษรก็ทับซ้อนกันอยู่ มีเพียงไม่กี่คำที่สามารถอ่านออกได้\nหัวข้อคือ《@2 การถือกำเนิดของบุตรศักดิ์สิทธิ์》"
  },
  Event_7228_Name = {
    Text = "รหัสลับ·ลง"
  },
  Event_7229_ChoiceDesc1 = {
    Text = "【ดิ้นรน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7229_ChoiceDesc2 = {
    Text = "【จม】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7229_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7229_Desc = {
    Text = "「ฉันเจ็บปวดมาก เจ็บปวดจริงๆ...」\n「ทำไมเป็นฉัน ทำไมฉันต้องประสบกับสิ่งนี้?」\n「พ่อพระที่มีเมตตา ฉันทำผิดอะไรไปกันแน่?」\nความเศร้า ความเจ็บปวด ความโกรธ ความไม่ยอมรับ... อารมณ์ของ「ผู้ป่วย」ถาโถมเข้ามาอย่างหนักหน่วง ทำให้คุณกุมหน้าอกของตัวเอง หายใจไม่ออก。"
  },
  Event_7229_Name = {
    Text = "การติด"
  },
  Event_7230_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7230_Desc = {
    Text = "สายตาฝ่าผิวหนังไปจนถึงจอประสาทตาของผู้ที่มาก่อน ถูกตราประทับเอาไว้ \nไม่มีใครสามารถหนีไปได้ เช่นเดียวกับที่ไม่มีใคร@2"
  },
  Event_7230_Name = {
    Text = "มองลับ"
  },
  Event_7231_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7231_Desc = {
    Text = "มุ่งมั่นจิตใจ แยกแยะเนื้อเพลง จากนั้นถูกคำพูดที่ยุ่งเหยิงกระทบหลังศีรษะของคุณ。\nนั่นไม่ใช่คำที่มนุษย์จะเข้าใจได้。"
  },
  Event_7231_Name = {
    Text = "เพลงทะเล"
  },
  Event_7232_ChoiceDesc1 = {
    Text = "【เข้าร่วมการทดสอบ】ติดเชื้อ「(Skill.Arg1)」，ชัยชนะได้รับสิ่งประดิษฐ์ทองคำ，ความล้มเหลวได้รับ 50 รอยดำ"
  },
  Event_7232_ChoiceDesc2 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7232_Desc = {
    Text = "คุณได้เห็นความลับบางอย่างจากน้ำดำที่สะท้อนเหมือนกระจกใต้เท้าของคุณ \n ขอบสะท้อนของมันเบลอ และมีหมอกดำที่ไม่สามารถขจัดออกไปได้ล้อมรอบ คุณรู้สึกคุ้นเคยอย่างประหลาด แต่กลับไม่สามารถบอกได้ว่ามันคืออะไร。"
  },
  Event_7232_Name = {
    Text = "ใต้ผิวกระจก"
  },
  Event_7233_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7233_Desc = {
    Text = "คุณไม่สนใจจดหมายลึกลับที่ไร้ชื่อ และจุดไฟเผามันทิ้ง กระดาษจดหมายกลายเป็นเถ้าถ่านปลิวไปกับสายลม"
  },
  Event_7233_Name = {
    Text = "อีกจดหมายขอความช่วยเหลือ"
  },
  Event_7234_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7234_Desc = {
    Text = "คุณตรวจสอบเนื้อหาของจดหมาย พบว่าที่ปากซองมีของเหลวเหนียวๆ ดูเหมือนจะเป็นการผสมระหว่างเลือดกับน้ำดำ มีเส้นผมบางเส้นติดอยู่ที่ปากซอง。"
  },
  Event_7234_Name = {
    Text = "อีกจดหมายขอความช่วยเหลือ"
  },
  Event_7235_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7235_Desc = {
    Text = "เมื่อคุณเดินตามทิศทางที่จดหมายปลิวไป ตรงมุมกำแพงหลังจากเลี้ยว คุณเหลือบเห็นบางอย่างแวบวาว"
  },
  Event_7235_Name = {
    Text = "อีกจดหมายขอความช่วยเหลือ"
  },
  Event_7236_ChoiceDesc1 = {
    Text = "【ค้นหาต่อ】 เพิ่ม Arg1 คะแนนชีวิต, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7236_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7236_Desc = {
    Text = "แสงเรืองรองปรากฏขึ้นเบื้องหน้า สดใสและอบอุ่น เมื่อพยายามก้าวตามแสงนั้น มันกลับหายวับไปอย่างกะทันหัน。"
  },
  Event_7236_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7237_ChoiceDesc1 = {
    Text = "【ออกไป】ผู้ปลุกเสกทั้งหมดจะฟื้นฟูความบ้าคลั่ง Arg1 คะแนน"
  },
  Event_7237_Desc = {
    Text = "คุณกลัวจนต้องหลับตาแน่น。\n「คุณเปิดผ้าคลุมออก...\nความลับ คุณค้นพบความลับ...」\nเสียงคลื่นรวมตัวกันเป็นมหาสมุทรที่วุ่นวาย พื้นสั่นสะเทือนอย่างรุนแรงในความสั่นสะเทือนที่น่ากลัว。\nคุณทนไม่ไหว ลืมตาขึ้นทันที แต่กลับพบว่ารอบข้างว่างเปล่า。"
  },
  Event_7237_Name = {
    Text = "พิธีจงมู่หลี่Ⅴ"
  },
  Event_7238_ChoiceDesc1 = {
    Text = "【ค้นหาต่อ】 เพิ่ม Arg1 คะแนนชีวิต, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7238_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7238_Desc = {
    Text = "ปลายจมูกได้กลิ่นที่คุ้นเคย สบายๆ และน่าพอใจ เมื่อคุณอยากจะดมกลิ่นหอมของโรงอาหารอีกครั้ง กลิ่นหอมที่ลอยอยู่กลับหายไปจนหมดสิ้น.。"
  },
  Event_7238_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7239_ChoiceDesc1 = {
    Text = "【ค้นหาต่อ】 เพิ่ม Arg1 คะแนนชีวิต, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7239_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7239_Desc = {
    Text = "ข้างหูได้ยินเสียงพูดที่คุ้นเคย อบอุ่นและทำให้รู้สึกปลอดภัย เมื่อคุณต้องการตามเสียงไปหา เสียงนั้นกลับหยุดลงทันที。"
  },
  Event_7239_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7240_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7240_Desc = {
    Text = "พลังย้อนรอยไม่สามารถค้นหาจุดติดต่อให้คุณได้อีกในระยะเวลาสั้นๆ แต่คุณอย่างน้อยก็ได้รับความปลอบโยนชั่วคราว。"
  },
  Event_7240_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7241_ChoiceDesc1 = {
    Text = "【ค้นหาต่อ】 เพิ่ม Arg1 คะแนนชีวิต, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7241_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7241_Desc = {
    Text = "ดูเหมือนว่ามีมือคู่หนึ่งสัมผัสลงบนไหล่ของคุณ หนักแน่นและมั่นคง แต่เมื่อคุณหันไปมองหา ความรู้สึกที่เคยชัดเจนนั้นกลับกลายเป็นเลือนรางจนยากจะหาเจอ。"
  },
  Event_7241_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7242_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7242_Desc = {
    Text = "เงาของ「N」ถูกลมหมัดทำให้กระจายออกไป เม็ดสีดำและหมอกหนาของดินแดนลับแลรวมเป็นหนึ่ง ยากที่จะสืบร่องรอย。\n「น่าเบื่อ แต่เป็นคนที่น่าสนใจ ฉันตั้งตารอที่จะได้พบกับคุณอย่างแท้จริง...」"
  },
  Event_7242_Name = {
    Text = "การแสดงกำลังเริ่มต้น"
  },
  Event_7243_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7243_Desc = {
    Text = "「เด็กดี แต่ยังไงก็ต้องลงโทษเล็กน้อยนะ。」\nเสียงหัวเราะเบาๆ ของ ดาฟเดล จางหายไปในรอยแยกมิติ。"
  },
  Event_7243_Name = {
    Text = "เวลาเตือน"
  },
  Event_7244_ChoiceDesc1 = {
    Text = "【ด้านหน้า】มีโอกาส 50% ที่จะได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」 และมีโอกาส 50% ที่จะติดเชื้อ「(Skill.Arg3)」"
  },
  Event_7244_ChoiceDesc2 = {
    Text = "【ด้านลบ】มีโอกาส 50% ได้รับรอยดำ 75 ดวง และมีโอกาส 50% ได้รับผลกระทบจาก 「(Skill.Arg3)」"
  },
  Event_7244_ChoiceDesc3 = {
    Text = "【ชิปสีดำ】มีโอกาส 50% ที่จะได้รับคำสาป「(RelicConfig.Arg2)」 และมีโอกาส 50% ที่จะติดเชื้อ「(Skill.Arg3)」"
  },
  Event_7244_Desc = {
    Text = "ดีมาก...ดีมาก...\nงั้นเลือกชิปที่คุณต้องการเลย"
  },
  Event_7244_Name = {
    Text = "การแสดงกำลังเริ่มต้น"
  },
  Event_7245_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7245_Desc = {
    Text = "「โอเค โอเค เจ้าคนนั้น ชอบพันผูกกับสิ่งมีชีวิตที่ข้ามมิติอยู่เสมอ ฉันก็ต้องใช้ความพยายามพอสมควรถึงจะสามารถเดินทางผ่านรูโหว่ในมิติเหล่านี้ได้อย่างคล่องแคล่ว อา นั่นคงเป็นเรื่องเมื่อสามพันปีก่อนใช่ไหม?」"
  },
  Event_7245_Name = {
    Text = "เวลาเตือน"
  },
  Event_7246_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7246_Desc = {
    Text = "เชื่อว่าผู้อำนวยการฝ่ายวิจัยจะไม่ติดตั้งระเบิดไว้ที่กลางหน้าอกของคุณ"
  },
  Event_7246_Name = {
    Text = "ไม้พิณที่ไม่สงบ"
  },
  Event_7247_ChoiceDesc1 = {
    Text = "【ออก】ลบการ์ดคำสั่ง 1 ใบ, ได้รับรอยดำ 25 อัน"
  },
  Event_7247_Desc = {
    Text = "「เป็นผู้สัญจรที่มีน้ำใจ ช่วยชี้นำผู้หลงทางไปในทางที่ถูกต้อง」เขายิ้มอย่างไม่เป็นมิตร「เดินทางอย่างเบาๆ เคอร์เบรอสกำลังรอพวกคุณอยู่」\nอุปกรณ์ชี้นำในมือสั่นสะท้านอย่างกะทันหัน。"
  },
  Event_7247_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅲ"
  },
  Event_7248_ChoiceDesc1 = {
    Text = "【ค่อยๆ เคลื่อนที่】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7248_ChoiceDesc2 = {
    Text = "【นอนราบ】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7248_Desc = {
    Text = "「เมื่อเจอกับบึง อย่าต่อสู้เด็ดขาด。」\nคุณจดจำกฎการอยู่รอดนี้ไว้ให้ดี ยืนอยู่เฉยๆ เหมือนกับรูปปั้นที่เกาะอีสเตอร์.\nห้านาที สิบนาที หนึ่งชั่วโมง……โคลนดำในที่สุดก็หมดความอดทนและหายไปจากเท้าของคุณ。"
  },
  Event_7248_Name = {
    Text = "บึงมืด"
  },
  Event_7249_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7249_Desc = {
    Text = "คุณสังเกตเห็นมือที่แตกต่างจากคนอื่น มันนุ่มนวลและขาวผ่อง แสดงความสงบตลอดเวลา \n ที่สำคัญกว่านั้น—คุณจำได้ว่ามือนั้นเป็นมือของคุณเอง \n คุณจับมันเบาๆ \n มือที่นั้นก็จับมือคุณกลับ คุณรู้สึกถึงความเย็นยะเยือกและความว่างเปล่า จากนั้นหนองน้ำก็หายไป。"
  },
  Event_7249_Name = {
    Text = "บึงมืด"
  },
  Event_7250_ChoiceDesc1 = {
    Text = "【ตัดข้อมือ】 เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับคำอธิษฐาน:「(EnchantConfig.Arg1)」"
  },
  Event_7250_ChoiceDesc2 = {
    Text = "【ปลอบโยนพวกมัน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก: (EnchantConfig.Arg1)"
  },
  Event_7250_Desc = {
    Text = "คุณถือดาบคมในมือ ฟันมันทีละอัน \n เลือดหลากหลายชนิดกระเซ็นใส่ตัวคุณ ใบหน้า และผมของคุณ แต่คุณกลับไม่รู้สึกอะไร \n มือจำนวนมากร่วมกันส่งเสียงคร่ำครวญอย่างเจ็บปวด หนองน้ำหายไป \n จนกระทั่งหนึ่งสัปดาห์ต่อมา คุณจึงไม่ต้องได้ยินเสียงร้องไห้เหล่านั้นในความฝันร้ายอีกต่อไป。"
  },
  Event_7250_Name = {
    Text = "บึงมืด"
  },
  Event_7251_ChoiceDesc1 = {
    Text = "【รับเงินใจ】อัปเกรดสิ่งสร้างเงิน 1 ชิ้นเป็นสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7251_ChoiceDesc2 = {
    Text = "【พยายามปลุก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」และ「(Skill.Arg3)」"
  },
  Event_7251_ChoiceDesc3 = {
    Text = "【ละเลย】ได้รับ 25 รอยดำ"
  },
  Event_7251_Desc = {
    Text = "ใต้ไม้กระดานที่หลวมตัวออก มีน้ำดำที่แปดเปื้อนไหลออกมา。\nและแสงที่อยู่ในน้ำดำ คือ「เงินใจ」ที่คุณคุ้นเคยเป็นอย่างดี。"
  },
  Event_7251_Name = {
    Text = "การพิสูจน์การมีอยู่"
  },
  Event_7252_ChoiceDesc1 = {
    Text = "【เลือกหนู】สุ่มการ์ดคำสั่ง 1 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7252_ChoiceDesc2 = {
    Text = "【เลือกเทียน】เพิ่มพลังชีวิตสูงสุด Arg1 ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_7252_Desc = {
    Text = "ร่างหลอมละลายกำลังสลายไปต่อหน้าคุณ เถ้าถ่านสีดำเย็นถูกผสมเข้ากับหมอก และรวมตัวกันเป็นตาชั่งแปลกๆ ตาชั่งข้างหนึ่งมีหนูที่หลับอยู่ อีกข้างหนึ่งเป็นเทียนที่แกะสลักเป็นรูปเด็กชาย \n ในความมืดมิด คุณรู้ว่าคุณต้องทำการเลือก.。"
  },
  Event_7252_Name = {
    Text = "ความรู้สึกและเหตุผล"
  },
  Event_7253_ChoiceDesc1 = {
    Text = "【ลองพูดออกมา】"
  },
  Event_7253_ChoiceDesc2 = {
    Text = "【แอบตาม】"
  },
  Event_7253_Desc = {
    Text = "เมื่อคุณเดินข้ามมุมหนึ่ง ทุกสิ่งโดยรอบดูเหมือนจะเลือนลางมากขึ้น มีเพียงเสียงคำรามที่น่ากลัวเท่านั้นที่ชัดเจน\nเสียงฝีเท้าดังขึ้น คุณหันกลับไปดู พบเห็นเงาร่างประหลาดลางๆ: มันดูเหมือนคนแต่ด้านหลังกลับมีเงาซ้อนกันเป็นคู่ คล้ายกับผีเสื้อตัวใหญ่\n「ระวังนะ」 ราโมน่ากระซิบเตือน 「ในแดนลี้ลับนี้ สิ่งที่เห็นอาจไม่ใช่ความจริง ถ้าตามไปโดยไม่คิดให้รอบคอบ อาจเป็นอันตรายได้」"
  },
  Event_7253_Name = {
    Text = "รูปร่างในหมอก"
  },
  Event_7254_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7254_Desc = {
    Text = "คุณหยิบกุญแจเงินออกมา อย่างโศกเศร้าและมีความเชื่อมั่น ถือมันไว้ในฝ่ามือ แสงเรืองรางๆ เหมือนหมอกหุ้มคุณไว้ \nในความเงียบงัน มีเพียงเสียงถอนหายใจเท่านั้น。"
  },
  Event_7254_Name = {
    Text = "ตาที่จ้องมอง"
  },
  Event_7255_ChoiceDesc1 = {
    Text = "【ทางแห่งดาราจักร】การ์ดคำสั่งแบบสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7255_ChoiceDesc2 = {
    Text = "【เลือกเส้นทางรุ้ง】เพิ่มพลังชีวิตสูงสุด Arg1 ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_7255_Desc = {
    Text = "พลั่ก พลั่ก พลั่ก \n เสียงหัวใจเต้นเหมือนเสียงกลอง ปากแห้งและลิ้นเหนียว สายตาจากที่สูงทะลุผ่านกระดูกสันหลังของคุณไปยังหน้าอก \n ข้างหน้าเกิดเป็นทางแยก ทางหนึ่งมีทางช้างเผือกไหลผ่าน อีกทางหนึ่งมีสายรุ้งเปล่งประกาย。"
  },
  Event_7255_Name = {
    Text = "ทางแยกของดวงดาว"
  },
  Event_7256_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7256_Desc = {
    Text = "สายตาที่เหลืออยู่ยังคงจ้องมองคุณ เซลล์เนื้อและเลือดใต้ผิวหนังของคุณกำลังตะโกนและหลบหนีอย่างบ้าคลั่ง หลอดเลือดกำลังขยับอยู่ใต้ผิวหนังเหมือนหนอน \n คุณรู้สึกถึงพละกำลังที่ไหลผ่าน ในความผิดปกติที่แปลกประหลาดของร่างกาย。"
  },
  Event_7256_Name = {
    Text = "ตาที่จ้องมอง"
  },
  Event_7257_ChoiceDesc1 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7257_ChoiceDesc2 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7257_ChoiceDesc3 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7257_Desc = {
    Text = "「ไม่ นี่ไม่ใช่ความจริง อย่างน้อยพวกคุณก็มีร่างกายที่ขนฟูมากกว่ากั้ง\nไม่มีใครปฏิเสธร่างกายที่ขนฟูได้」\nหนูๆ พูดคุยกันอย่างเงียบๆ สุดท้ายก็ยอมรับความเห็นของคุณอย่างอิดออด\n「ดีนะ...จริงๆ แล้วก็ไม่ได้มีขนเยอะขนาดนั้น」\nการได้รับคำชมมักทำให้รู้สึกดี ก่อนจะจากไป หนูๆ ได้มอบของขวัญเล็กๆ ให้กับคุณ。"
  },
  Event_7257_Name = {
    Text = "พิษระบาด"
  },
  Event_7258_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7258_Desc = {
    Text = "「ฉันเห็นด้วย! มนุษย์กับหนูไม่สามารถอยู่ร่วมกันได้!」\nหนูพวกนั้นเริ่มโกรธเล็กน้อย แสดงเขี้ยวขาวๆ ออกมา\n「แล้วเธอยังทำอะไรอยู่ที่นี่? เอาของของเธอไป และอย่ากลับมาอีกเลย」"
  },
  Event_7258_Name = {
    Text = "พิษระบาด"
  },
  Event_7259_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，รับสถานะ「(Skill.Arg2)」"
  },
  Event_7259_Desc = {
    Text = "เสียงกระพือปีกที่แปลกประหลาดลอยอยู่รอบตัวคุณ ในความงุนงง คุณเห็นโรเจอร์สกอดจอร์จตุ๊กตานอนอยู่บนเตียงรักษา มือทั้งสองข้างเต็มไปด้วยเลือดสด。\nคุณเปิดตาและค้นพบว่าคลายเมนตินหายไปแล้ว。\nเมื่อฟื้นคืนสติ คลายเมนตินก็จากไปแล้ว。"
  },
  Event_7259_Name = {
    Text = "การรักษาด้วยการสะกดจิต"
  },
  Event_7260_ChoiceDesc1 = {
    Text = "【ใช้งาน】ใช้กุญแจ。"
  },
  Event_7260_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7260_Desc = {
    Text = "ประตูบานหนึ่งขวางทางคุณไว้ คุณได้ลองทุกวิธีแล้ว แต่มันก็ยังไม่ขยับแม้แต่น้อย"
  },
  Event_7260_Name = {
    Text = "ประตูที่เป็นสนิม"
  },
  Event_7260_Tips1 = {
    Text = "จำเป็นต้องได้รับ「กุญแจที่เป็นสนิม」"
  },
  Event_7261_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7261_Desc = {
    Text = "คุณมองไปยังทิศทางที่คุณคิดว่าเป็นแหล่งกำเนิดสายตา เพดานของโรงงานทันใดนั้นก็สูงขึ้นอย่างมาก เงาของรูม่านตาขนาดใหญ่ซ้อนทับกัน แม้จะมีเพียงบางส่วนที่จ้องมองคุณ คุณยังรู้สึกถึงแรงกดดันมหาศาล。"
  },
  Event_7261_Name = {
    Text = "ใครมอง"
  },
  Event_7262_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7262_Desc = {
    Text = "แมวดำเดินเข้ามาอย่างระมัดระวัง และคายก้อนสีดำที่ดูหนาและหนักออกมาในฝ่ามือของคุณ"
  },
  Event_7262_Name = {
    Text = "ภัยพิบัติของแมวกลางคืน"
  },
  Event_7263_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7263_Desc = {
    Text = "「อืม การเลือกที่ฉลาด ในยามที่ศัตรูใหญ่กำลังมาถึง แน่นอนว่าคุณจะต้องอยากรู้จักทั้งตนเองและศัตรู? แต่การรู้ข้อมูลเกี่ยวกับมิติ มากเกินไปอาจรบกวนจิตใจได้นะ?」\n「เจ้าคนนั้น ชอบพันผูกกับสิ่งมีชีวิตที่ข้ามมิติอยู่เสมอ ฉันก็ต้องใช้ความพยายามพอสมควรถึงจะสามารถเดินทางผ่านรูโหว่ในมิติเหล่านี้ได้อย่างคล่องแคล่ว อา นั่นคงเป็นเรื่องเมื่อสามพันปีก่อนใช่ไหม?」"
  },
  Event_7263_Name = {
    Text = "เวลาเตือน"
  },
  Event_7264_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7264_Desc = {
    Text = "「เหมียว, เหมียวเหมียว, เหมียวเหมียวเหมียว......」\nคุณขยับเสียงให้ฟังดูอ่อนแอและไม่มีอันตราย.\n「เหมียว! เหมียวเหมียว! เหมียวเหมียวเหมียว!」\nกลุ่มแมวดูเหมือนจะยอมรับความปรารถนาดีของคุณ ตอบกลับด้วยเสียงร้องที่ดังสนั่น. เสียงของพวกคุณดังสลับกันไม่หยุดตลอดวันและคืน จนพระจันทร์ต้องหลบซ่อนอยู่ในก้อนเมฆ.。"
  },
  Event_7264_Name = {
    Text = "เมืองแมว"
  },
  Event_7265_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7265_Desc = {
    Text = "คุณบิดจงใจให้จงอยปากแหลมของอีกาที่พยายามจะกัดขนกลับมา แต่มันกลับไม่ยอมแพ้บิดตัวไปมา ด้วยแรงที่มากถึงขนาดทำให้กระดูกของคุณสั่นสะเทือนเสียงดัง \n ใบหน้าของคุณแดงก่ำเต็มไปด้วยเลือด คุณใช้แรงทั้งหมดที่มีเพื่อควบคุมร่างของอีกา หยุดยั้งการกระทำที่บ้าคลั่งของมัน \n ขณะที่คุณถอนหายใจด้วยความโล่งอก คอของอีกาที่เริ่มล้านขนกลับบิดไปข้างหลังอย่างแรง ร่างกายของมันอ่อนแรงลงและกลายเป็นน้ำดำข้นในมือของคุณ。"
  },
  Event_7265_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_7266_ChoiceDesc1 = {
    Text = "【กดค้างที่อีกา】ได้รับ 20 รอยดำ ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7266_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_7266_Desc = {
    Text = "อีกาที่โดดเดี่ยวทำเสียงแหบ สางขนสีดำของตัวเองออกทีละขน \n มันเจ็บจนตัวสั่น ตะโกนเสียงแหลม แต่ไม่สามารถหยุดการเคลื่อนไหวที่เร็วขึ้นเรื่อยๆ ของตัวเองได้ \n「กา——กา——」\n น้ำตาสีน้ำเงินที่มีน้ำดำไหลออกจากตาของมัน นอกจากคุณ ไม่มีใครได้เห็น。"
  },
  Event_7266_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_7267_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7267_Desc = {
    Text = "อีกากัดขนของตัวเอง ราวกับมนุษย์กัดกินร่างกายของตัวเอง \nในโลกแห่งความกลัวนี้ เรื่องนี้เกิดขึ้นบ่อยครั้ง คุณไม่สามารถช่วยชีวิตทุกชีวิตได้。"
  },
  Event_7267_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_7268_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，รับสถานะ「(Skill.Arg2)」"
  },
  Event_7268_Desc = {
    Text = "「ฉันจะพานักเรียนกลับมา」เด็กหญิงกล่าวอย่างมั่นใจ ขณะจับชายกระโปรงของผู้ปลุกตื่นไว้ 「ดูแลตัวเองให้ดีนะ...อย่าตกลงไปในทะเลล่ะ」"
  },
  Event_7268_Name = {
    Text = "การคุ้มครองของนักบุญแห่งการเดินเรือ"
  },
  Event_7269_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7269_Desc = {
    Text = "ฮ่าๆ สีดำ สีดำที่ฉันชอบที่สุด ความไม่เป็นระเบียบ โกลาหล ความเจ็บปวด... คุณควรจะรู้ไว้แล้วว่าสีดำไม่ใช่สัญญาณที่ดีเลย \n แล้วการเลือกครั้งต่อไปของคุณคืออะไร?"
  },
  Event_7269_Name = {
    Text = "การแสดงกำลังเริ่มต้น"
  },
  Event_7270_ChoiceDesc1 = {
    Text = "【กดค้างที่อีกา】ได้รับ 25 รอยดำ, ติดเชื้อ「(Skill.Arg2)」, เลือกต่อไป"
  },
  Event_7270_ChoiceDesc2 = {
    Text = "【ปล่อยทิ้งไว้】จากไป"
  },
  Event_7270_Desc = {
    Text = "อีกาตัวเดียวดายส่งเสียงแหบแห้ง ดึงขนสีดำของตัวเองออกทีละเส้น \n มันเจ็บจนสั่น ร้องเสียงแหลมสูง แต่ก็หยุดไม่ได้กับการเคลื่อนไหวที่รวดเร็วขึ้นเรื่อยๆ \n 「ก๊า——ก๊า——」 \n น้ำตาสีน้ำเงินที่มีน้ำดำไหลออกจากตาของมัน นอกจากคุณ ไม่มีผู้ใดเห็น。"
  },
  Event_7270_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_7271_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7271_Desc = {
    Text = "นั่นคือภายในห้องเรือที่ชำรุดมานาน ขาดแสงสว่างและการชี้นำ \nเด็กหญิงจะออกเดินทางโดยมีพรจากนักบุญแห่งเรือ นี่คือข้อตกลงของพวกเธอ。"
  },
  Event_7271_Name = {
    Text = "การคุ้มครองของนักบุญแห่งการเดินเรือ"
  },
  Event_7272_ChoiceDesc1 = {
    Text = "【ตามหาเสียงเพลง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_7272_ChoiceDesc2 = {
    Text = "【ร้องเพลงตาม】ติดเชื้อ「(Skill.Arg1)」，ทำการแกะสลักแบบสุ่มอีกครั้ง"
  },
  Event_7272_Desc = {
    Text = "เสียงเพลงที่ห่างไกลถูกทำลายเป็นผงดาวเล็ก ๆ :\n「ฉันสาปแช่งน้ำโสโครกในซอยยามค่ำคืน ดอกไม้เน่าเปื่อยที่ติดอยู่ที่โคนกำแพงที่พังทลาย โซ่ตรวนเกาะเกี่ยวกับสมองจนตกลงไปในโคลน ก่อนที่หมอกหนาจะลบการมีอยู่ของฉัน สีสันยามค่ำคืนจะจมลงสู่@3 ที่ลึกที่สุด.」"
  },
  Event_7272_Name = {
    Text = "คำสาปสารขาว"
  },
  Event_7273_ChoiceDesc1 = {
    Text = "【ตามหาเสียงเพลง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_7273_Desc = {
    Text = "เสียงเพลงที่ห่างไกลถูกทำลายเป็นผงดาวเล็ก ๆ :\n「ฉันสาปแช่งน้ำโสโครกในซอยยามค่ำคืน ดอกไม้เน่าเปื่อยที่ติดอยู่ที่โคนกำแพงที่พังทลาย โซ่ตรวนเกาะเกี่ยวกับสมองจนตกลงไปในโคลน ก่อนที่หมอกหนาจะลบการมีอยู่ของฉัน สีสันยามค่ำคืนจะจมลงสู่@4 ที่ลึกที่สุด.」"
  },
  Event_7273_Name = {
