  },
  Event_7275_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7275_Desc = {
    Text = "ไอหมอกสีดำลอยวนขึ้นตามแนวกระดูกสันหลัง จนคุณทนไม่ไหวและล้มลงกับพื้น คุณพูดประโยคนี้ซ้ำไปซ้ำมา"
  },
  Event_7275_Name = {
    Text = "ไม่ควรดูโดยตรง"
  },
  Event_7276_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7276_Desc = {
    Text = "ใช่แล้ว ของเหลวแก้วที่ไหลออกมาจากรูม่านตาช้าๆ เป็นหลักฐานว่าคุณถูกการกัดกร่อนที่ต้องห้าม \n ความซื่อสัตย์ในขณะนี้กลับกลายเป็นสิ่งที่ขัดแย้งกับคุณธรรม。"
  },
  Event_7276_Name = {
    Text = "ไม่ควรดูโดยตรง"
  },
  Event_7277_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7277_Desc = {
    Text = "เหรียญโบราณเปียกชื้นไปด้วย, เหมือนถูกสิ่งสกปรกอาเจียนออกมา, ปลิวไปพร้อมกับไอสีดำที่มองเห็นได้ด้วยตาเปล่า.。"
  },
  Event_7277_Name = {
    Text = "เหรียญโบราณสองด้าน"
  },
  Event_7278_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7278_Desc = {
    Text = "ปลายประสาทที่เฉียบคมส่งสัญญาณเตือนที่อันตราย คุณสะดุ้งอย่างกะทันหัน และต้องเก็บมือกลับอย่างไม่เต็มใจ \nอีกครั้งที่คุณรอดพ้นไปได้... \nคำสาป? หรือการเกิดใหม่ครั้งหนึ่ง?"
  },
  Event_7278_Name = {
    Text = "เหรียญโบราณสองด้าน"
  },
  Event_7279_ChoiceDesc1 = {
    Text = "【ปล่อยผีเสื้อบิน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7279_ChoiceDesc2 = {
    Text = "【กลายเป็นผีเสื้อ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7279_ChoiceDesc3 = {
    Text = "【กลืนลงท้อง】ได้รับ 25 รอยดำ"
  },
  Event_7279_Desc = {
    Text = "คืนนี้เกิดเรื่องราวมากมาย \n การโจมตีที่ท่าเรือ เรือผี ผู้เหยียบทะเล ธูลู เมอร์ฟี่ ราโมน่า... ทุกอย่างหมุนวนอยู่ในวังวน ถูกคนกวนจนกลายเป็นข้าวโอ๊ตที่ร้านมิซากะตอนเจ็ดโมงเช้า \n อยากจะถามผู้ปลุกตื่นที่อยู่ตรงหน้า แต่ไม่รู้จะเริ่มถามอย่างไร เหมือนมีอะไรติดอยู่ในคอ—หรือจะพูดว่าสิ่งที่อยู่ในท้องคือผีเสื้อ。"
  },
  Event_7279_Name = {
    Text = "เอฟเฟกต์ผีเสื้อ"
  },
  Event_7280_ChoiceDesc1 = {
    Text = "【ขจัดภาพลวง】สูญเสียหน่วยชีวิต(Arg3)。"
  },
  Event_7280_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7280_Desc = {
    Text = "ใบหน้าที่เลือนรางปรากฏขึ้นอย่างกะทันหัน มันล้อมรอบคุณอยู่ ใช้สายเสียงที่ไม่มีอยู่จริงคร่ำครวญอย่างสิ้นหวัง。"
  },
  Event_7280_Name = {
    Text = "ภาพลวง"
  },
  Event_7281_ChoiceDesc1 = {
    Text = "【การสวดมนต์】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อโรค「(Skill.Arg2)」"
  },
  Event_7281_ChoiceDesc2 = {
    Text = "【จมลงสู่ทะเล】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」，「(Skill.Arg3)」"
  },
  Event_7281_ChoiceDesc3 = {
    Text = "【ผุดขึ้น】ได้รับ 25 รอยดำ"
  },
  Event_7281_Desc = {
    Text = "「พระเจ้าผู้มีความอ่อนโยน พระเจ้าผู้สูงส่ง。\nโปรดสงบพายุร้าย โปรดหยุดกระแสน้ำที่เชี่ยวกราก。\nโปรดให้มหาสมุทรเป็นบ้านที่ลึกซึ้งของเรา ให้มันปกคลุมอาณาจักรของเราไว้ด้วยผ้าคลุมที่เป็นนิรันดร์……」\nเสียงกระซิบของผู้ศรัทธาในที่สุดก็เชื่อมโยงกันเป็นคำพูดที่ท่านเข้าใจได้ แต่สิ่งที่ตามมาก็คือความรู้สึกขาดอากาศที่ยากจะหลีกหนี。"
  },
  Event_7281_Name = {
    Text = "คำอธิษฐานแห่งความฝัน"
  },
  Event_7282_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7282_Desc = {
    Text = "คุณโยนก้อนเนื้อที่เหลืออยู่ในมือไปให้กลุ่มแมว。\nกลุ่มแมวพุ่งเข้ามาเหมือนคลื่นสีดำ。พวกมันกัดก้อนเนื้ออย่างบ้าคลั่งแล้วก็แตกกระจายออกไปอย่างรวดเร็ว。\nโชคร้ายที่นี่คือเนื้อที่หมดอายุ。มันสามารถทำให้ท้องที่แห้งเหี่ยวเต็มได้ แต่ก็ไม่ทำให้รู้สึกดีนัก。"
  },
  Event_7282_Name = {
    Text = "เมืองแมว"
  },
  Event_7283_ChoiceDesc1 = {
    Text = "【เก็บเข้ากระเป๋า】"
  },
  Event_7283_Desc = {
    Text = "สารสีเงินที่มีลักษณะใกล้เคียงกับปรอท สกัดจากน้ำเมือกหลอมละลาย มีพลังจิตที่เข้มแข็ง ใช้หลัก ๆ ในการลิงก์ผู้ปลุกตื่นมากขึ้นในพิธีกรรม。"
  },
  Event_7283_Name = {
    Text = "เงินใจ"
  },
  Event_7284_ChoiceDesc1 = {
    Text = "【ออกจาก】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น และลดการใช้พลังการคำนวณลง 2 หน่วย ติดเชื้อ 「(Skill.Arg1)」"
  },
  Event_7284_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7284_Desc = {
    Text = "แม้ในขณะนี้ยังไม่สามารถสื่อสารได้ แต่พวกเขาจะได้ยินเสียงเรียกของพวกคุณในไม่ช้า"
  },
  Event_7284_Name = {
