  Event_7285_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7285_Desc = {
    Text = "ร่างทดลองที่เร่ร่อนไปมาได้ทำให้คุณรู้สึกเหนื่อยล้า การพักหายใจสั้น ๆ ก็เหมือนกับน้ำฝนในทะเลทรายที่แห้งแล้ง。"
