  Event_7288_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ Arg1 รอยดำ ติดเชื้อ「(Skill.Arg2)」 โปรดเลือกต่อ"
  },
  Event_7288_ChoiceDesc2 = {
    Text = "【ละเว้น】ออก"
  },
  Event_7288_Desc = {
    Text = "อีกาเกาะอยู่บนตู้เสื้อผ้า ใช้จะงอยปากแหลมกรีดลงบนประตูไม้ สร้างลวดลายประหลาดที่ชวนขนลุก"
