  Event_7290_ChoiceDesc1 = {
    Text = "【อยู่ที่นี่】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_7290_ChoiceDesc2 = {
    Text = "【ค้นหาทางออก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7290_Desc = {
    Text = "คุณก้าวเข้าสู่ความเงียบงันที่ขาวซีด ประตูที่ทับซ้อนกันหมุนวนอย่างไม่หยุดหย่อน ดูดร่างกายของคุณเข้าไปในวังวน \nคุณดิ้นรนอยู่ภายในประตูที่กลับหัวกลับหาง สับสนในทิศทางที่ต้องการหลบหนี แต่ไม่สามารถหลีกเลี่ยงการตกลงไปในประตูอีกบานได้ซ้ำแล้วซ้ำเล่า \nครั้งนี้ คุณหยุดอยู่หน้าประตูอีกครั้ง เบื้องหลังประตูนั้นมีสิ่งที่ไม่รู้จักเคลื่อนไหวอย่างดึงดูดอย่างอันตราย แต่สติของคุณกลับตึงเครียด \nใช่ มันเป็นอันตรายจริงๆ。"
  },
  Event_7290_Name = {
    Text = "นอกประตูใหญ่"
  },
  Event_7291_ChoiceDesc1 = {
    Text = "【ตกอยู่ในความรื่นเริง】ลบการ์ดคำสั่ง 1 ใบ และคืนความชีวิต Arg1 คะแนน"
  },
  Event_7291_ChoiceDesc2 = {
    Text = "【หยุดฝีเท้า】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7291_Desc = {
    Text = "เหมือนกับกะโหลกศีรษะถูกงัดออกอย่างง่ายดาย สมองของคุณหมุนวนอย่างคลื่นอาเจียน มือที่มองไม่เห็นกำลังพลิกพลิ้วสมอง วัตถุที่เคยเป็นของแข็งเริ่มแตกเป็นกองเหลว \n เหมือนกับสิ่งที่อยู่ในกระเพาะอาหารที่ยังไม่ได้ย่อย เหมือนโจ๊กที่ลอยอยู่หลุดพ้นจากแรงดึงดูดของโลก ไหลย้อนเข้าสู่เปลือกสมองที่ว่างเปล่าและขาดแคลนของคุณ \n มันนวด คลุกเคล้า และขยำ โรยด้วยความปิติสุขที่ถูกตัดให้ละเอียด ผสมผสานกับซากของพระอาทิตย์ตกดินลงไปในเนื้อของคุณ。"
  },
  Event_7291_Name = {
    Text = "กวนสมอง"
  },
  Event_7292_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7292_Desc = {
    Text = "เมื่อเทียบกับสุนัขแห่งนรกที่ปรากฏตัวขึ้นอย่างกะทันหัน หยาดน้ำฟ้าที่ตกลงมาตามปกติไม่คุ้มค่าให้คุณสิ้นเปลืองพลังงาน. คุณเพิกเฉยต่อเกล็ดหยาดน้ำฟ้าที่ค่อยๆ โปรยลงมา แล้วพุ่งตัวเข้าสู่ความมืดของราตรี."
  },
  Event_7292_Name = {
    Text = "หยาดน้ำฟ้า"
  },
  Event_7293_ChoiceDesc1 = {
    Text = "【เชื่อมต่อ】ฟื้นฟูชีวิต Arg2 หน่วย。"
  },
  Event_7293_Desc = {
    Text = "คุณกำลังสำรวจในหมอก หนึ่งในนั้น ตราสัญลักษณ์ที่หน้าอกของคุณปล่อยแสงสีเงินอ่อนๆ อะไรคือเสียงที่เรียกคุณจากเครื่องสื่อสาร?"
  },
  Event_7293_Name = {
    Text = "จุดติดต่อ"
  },
  Event_7294_ChoiceDesc1 = {
    Text = "【รู้สึกหวาดกลัว】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7294_ChoiceDesc2 = {
    Text = "【ความมุ่งมั่น】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7294_Desc = {
    Text = "เสียงร้องโหยหวนที่แปลกประหลาดก้องกังวานไม่หยุดยั้ง แต่สิ่งต่าง ๆ ในลอนดีเนี่ยนกลับไม่มีปฏิกิริยาใด ๆ ราวกับว่ามันตายไปแล้ว หรือหลับใหลอยู่ \nคุณเดินไปมาอย่างไร้สติใต้สะพานรถไฟ นึกถึงคำเตือนของอลิสเตอร์ \nเขาเดินเข้ามาอย่างสุภาพ ราวกับกำลังพูดอะไรบางอย่างกับคุณ แต่คำพูดนั้นกลับติดขัดไม่ชัดเจน \nคุณเงยหน้าขึ้น เหลวไหลสีดำข้นไหลออกมาจากปากของเขา ปิดกั้นลำคอของเขา และอุดตันคำพูดของเขา—"
  },
  Event_7294_Name = {
    Text = "เสียงครวญของความวุ่นวาย"
  },
  Event_7295_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_7295_Desc = {
    Text = "「แน่นอน นั่นเป็นเรื่องแน่นอน ถ้าไม่รังเกียจ ฉันก็จะช่วยพวกคุณอีกแรง」\nเขายื่นกระจกมือโบราณให้พวกคุณ\n「อัศวินได้ขึ้นสู่กระดานหมากแล้ว ราชาก็จะไม่รออยู่ที่ด้านหลังนานนัก พวกคุณน่าจะได้พบเขาในไม่ช้า น่าตื่นเต้นจริงๆ」"
  },
  Event_7295_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅳ"
  },
  Event_7296_ChoiceDesc1 = {
    Text = "【ฉีกกระดาษจดหมาย】ลบการ์ด 2 ใบ"
  },
  Event_7296_ChoiceDesc2 = {
    Text = "【อ่านต่อ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7296_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ Arg1 รอยดำ"
  },
  Event_7296_Desc = {
    Text = "คุณเห็นฝูงผีเสื้อสีดำพุ่งออกมา พวกมันปีกกระพืออยู่ตลอดเวลา และตกลงมาบนโต๊ะเขียนหนังสืออย่างไม่หยุดหย่อน \nกระดาษเขียนจดหมายที่กางออกเต็มไปด้วยน้ำหมึก และผีเสื้อที่บาดเจ็บนอนหมดแรงอยู่บนผิวกระดาษ \nน้ำยางสีดำที่ติดอยู่บนปีกถูกเรียงร้อยเป็นข้อความต้องห้าม \nคุณดึงกระดาษนี้ออกมาจากเครื่องพิมพ์ดีด。"
  },
  Event_7296_Name = {
    Text = "บทผีเสื้อ"
  },
  Event_7297_ChoiceDesc1 = {
    Text = "【เผชิญหน้ากับผีเสื้อ】ลบการ์ดคำสั่ง 1 ใบ ได้รับรอยดำจำนวน Arg1"
  },
  Event_7297_ChoiceDesc2 = {
    Text = "【ไม่ผูกพันอีกต่อไป】"
  },
  Event_7297_Desc = {
    Text = "ช่วงนี้ในลอนดีเนี่ยนมีคำพูดหนึ่งที่ว่า: 「การกระพือปีกของผีเสื้อที่อาร์คต์ อาจทำให้เกิดพายุในราชอาณาจักรเลโอ」 \nเมื่อเห็นผีเสื้อพุ่งออกมา คุณไม่สามารถไม่คิดถึงคำพูดนี้ได้ \nผีเสื้อเหล่านี้อาจเพียงพอที่จะก่อให้เกิดภัยพิบัติที่จมหายดาวเคราะห์。"
  },
  Event_7297_Name = {
    Text = "พายุความรู้ทางจิตวิญญาณ"
  },
  Event_7298_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7298_Desc = {
    Text = "คุณวางนิ้วหนึ่งไว้ที่มุมปาก สื่อความหมายว่าคุณจะเงียบในเรื่องนี้。\nแมวสีดำวูบวาบผ่านไปอย่างลึกลับ ทิ้งของขวัญสีดำเงาไว้ที่ข้างเท้าของคุณ。"
  },
  Event_7298_Name = {
    Text = "ภัยพิบัติของแมวกลางคืน"
  },
  Event_7299_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7299_Desc = {
    Text = "พระองค์เลื่อนเข้ามาในกระเป๋าของคุณราวกับผ้าไหม เมื่อมีน้ำหนักเพิ่มขึ้นเล็กน้อย คุณรู้สึกเหมือนได้ยินเสียงขอบคุณเบาๆ \n หลังจากนั้นก็ไม่มีเสียงอีกเลย。"
  },
  Event_7299_Name = {
    Text = "วิญญาณแห่งความวุ่นวาย"
  },
  Event_7300_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7300_Desc = {
    Text = "เสียงร้องของวิญญาณแห่งความวุ่นวายยิ่งแหลมคมขึ้นเรื่อย ๆ จนในที่สุดกลายเป็นเสียงกรีดร้องที่แสบแก้วหูดังก้องไปทั่วร่างกาย \n พระองค์นำของถวายของคุณและความเศร้าที่ไม่สามารถหลุดพ้นลงไปในโคลนอีกครั้ง。"
  },
  Event_7300_Name = {
    Text = "วิญญาณแห่งความวุ่นวาย"
  },
  Event_7301_ChoiceDesc1 = {
    Text = "【กรอกข้อมูลตามจริง】"
  },
  Event_7301_ChoiceDesc2 = {
    Text = "【เขียนส่งเดช】"
  },
  Event_7301_Desc = {
    Text = "ถนนในเขตตะวันออกซับซ้อนมาก ไม่ช้าคุณก็สูญเสียภาพของเด็ก ๆ ไป\nเมื่อคุณรู้สึกสิ้นหวัง มีผู้หญิงลึกลับคนหนึ่งเข้ามาพูดกับคุณ\n「ฉันรู้ว่าเด็ก ๆ ไปไหน แต่ก่อนที่ฉันจะบอกเธอได้ ช่วยฉันทำธุระเล็กน้อยได้ไหม?」\nเธอหยิบกระดาษแผ่นหนึ่งออกมาและยิ้มให้คุณอย่างเป็นมิตร\n「ฉันชื่อคลีเมนไทน์ เป็นหมอจิตวิทยา กำลังทำการสำรวจจิตวิทยาเกี่ยวกับผู้อยู่อาศัยในลอนดีเนี่ยน ถ้าคุณช่วยกรอกแบบสอบถามนี้ให้ฉัน\nถ้ากรอกตามความจริง ฉันยินดีที่จะช่วยคุณและเพื่อนของคุณ」"
  },
  Event_7301_Name = {
    Text = "การประเมินทางจิตวิทยา"
  },
  Event_7302_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7302_Desc = {
    Text = "「นี่ก็เป็นทางเลือกของฉัน」 เงาของคนที่ถือขนมพูดว่า 「แต่เธอจะกลายเป็นชิปของเขา คุณจะต้องเลือก \n ไม่มีจุดจบที่สมบูรณ์แบบในโลกนี้」 \n ความเศร้าโศกอย่างหนักจะจมคุณลง เงานั้นจางหายไป คุณกุมหัวใจของตัวเอง ไม่รู้ว่าเมื่อกี้เป็นภาพลวงตาหรือเป็นภาพหลอนที่เกิดจากความกดดันทางจิตใจ。"
  },
  Event_7302_Name = {
    Text = "ทางแยกเล็กๆ"
  },
  Event_7303_ChoiceDesc1 = {
    Text = "【ขวานทอง】"
  },
  Event_7303_ChoiceDesc2 = {
    Text = "【ขวานเงิน】"
  },
  Event_7303_ChoiceDesc3 = {
    Text = "【ฉันไม่ได้ทำอะไรหล่น】"
  },
  Event_7303_Desc = {
    Text = "「ผู้เดินทางข้ามมิติ」\nเสียงแก่ๆ ดังขึ้นข้างหู ราวกับมาจากยุคก่อนประวัติศาสตร์ ราวกับข้ามเวลามาหลายพันปี\nในความตึงเครียดสุดขีด คุณได้ยินเสียงนั้นถามคำถามที่คุ้นเคย\n「คุณทำตกคือขวานทองเล่มนี้ หรือขวานเงินเล่มนี้กันแน่?」"
  },
  Event_7303_Name = {
    Text = "เสียงจากอีกฟาก"
  },
  Event_7304_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7304_Desc = {
    Text = "「โอ๊ะ นี่...」เธอเก็บแบบสอบถามและเผยสีหน้าที่ดูเหมือนจะไม่มีทางเลือก「ช่างเถอะ คุณก็มีกำหนดการที่จะต้องไป เด็ก ๆ ไปทางนั้น คงไม่ไปไกล」\nคุณรีบหันหลังกลับ จนแทบไม่ได้ยินเสียงกระซิบที่อยู่ข้างหลัง\n「ยังไงเราก็จะได้พบกันอีกครั้ง」"
  },
  Event_7304_Name = {
    Text = "การประเมินทางจิตวิทยา"
  },
  Event_7305_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7305_Desc = {
    Text = "「คุณคือใคร?」\n「ฉันคือเงาของผู้ใช้กุญแจเงินที่ถูกฆ่าตาย โจรคืองูขาวที่เจ้าเล่ห์。」\n「งูขาว? นั่นคืออะไร?」\n「ความผิดพลาด สิ่งที่เกิดจากการผสมพันธุ์ระหว่างคนกับงู...การดูหมิ่น。」\nคุณยังอยากถามต่อ เงาก็หายไปทันที ทิ้งไว้เพียงฝุ่นทองคำที่กระจายอยู่เต็มพื้น。"
  },
  Event_7305_Name = {
    Text = "ผู้ใช้กุญแจเงิน"
  },
  Event_7306_ChoiceDesc1 = {
    Text = "【ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」】"
  },
  Event_7306_ChoiceDesc2 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7306_Desc = {
    Text = "เหตุการณ์355（กำลังพัฒนา），ยังไม่ใช่ผลลัพธ์สุดท้าย"
  },
  Event_7306_Name = {
    Text = "เหตุการณ์355（กำลังพัฒนา）"
  },
  Event_7307_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7307_Desc = {
    Text = "จมลงไปในท้อง ร่วมกับผีเสื้อที่โบยบิน。\nเกล็ดความคิดและผีเสื้อที่ประสานกันโปรยปราย ทำให้เกิดหิมะขาวที่ร่วงหล่นในท้อง。\nคุณเริ่มเข้าใจทุกอย่างชัดเจน เมื่อโอกาสถัดไปมาถึง คุณจะต้องพูดออกมา。"
  },
  Event_7307_Name = {
    Text = "เอฟเฟกต์ผีเสื้อ"
  },
  Event_7308_ChoiceDesc1 = {
    Text = "【โต้แย้งพวกมัน】ติดเชื้อ「(Skill.Arg1)」，การ์ด 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg2)」"
  },
  Event_7308_ChoiceDesc2 = {
    Text = "【เห็นด้วยกับพวกมัน】ติดเชื้อ「(Skill.Arg1)」，การ์ด 1 ใบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg2)」"
  },
  Event_7308_ChoiceDesc3 = {
    Text = "【เสนอแนวคิดใหม่】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7308_Desc = {
    Text = "「กรุณารักษาระยะห่างจากพวกเรา」\nหนูจำนวนมากล้อมรอบคุณอยู่กลางวง โดยรักษาระยะห่างอย่างน้อยห้าฟุต\n「พวกเราพยายามสืบพันธุ์ พวกเรามีการเจริญเติบโต พวกเราไม่เลือกกิน— ดังนั้นเราจึงนำโรค ความวิตกกังวล และความทุกข์มาสู่มนุษย์」\n「พวกเราไม่ควรเข้าใกล้มนุษย์มากเกินไป นี่ไม่ใช่ที่ที่คุณควรมาที่」\nเพื่อทำให้หนูผ่อนคลายความระมัดระวัง คุณตัดสินใจ—"
  },
  Event_7308_Name = {
    Text = "พิษระบาด"
  },
  Event_7309_ChoiceDesc1 = {
    Text = "【เปิดประตูเหล็ก】ได้รับการติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」"
  },
  Event_7309_ChoiceDesc2 = {
    Text = "【ปล่อยผ่าน】ได้รับ 50 รอยดำ"
  },
  Event_7309_Desc = {
    Text = "นี่คือสะพานโค้งแบบลงใต้ที่เป็นแบบฉบับ ขั้นบันไดข้างทางรถไฟเห็นได้อย่างเลือนลางนำไปสู่ประตูเหล็ก ด้านหลังประตูมีเสียงดังอย่างเป็นจังหวะและผิดปกติ ก๊อก ก๊อก \nคุณหยุดยืนมองประตูเห็นว่ามีการล็อกที่หนักหน่วงแขวนอยู่ แต่ไม่ได้ล็อกแน่น。"
  },
  Event_7309_Name = {
    Text = "หลังประตูเหล็ก"
  },
  Event_7310_ChoiceDesc1 = {
    Text = "【Leave】การติดเชื้อ「(Skill.Arg1)」 ได้รับ 50 รอยดำ"
  },
  Event_7310_Desc = {
    Text = "เมื่อเผชิญกับการล่อลวง คุณไม่หวั่นไหว\nเจ้าของเสียงรู้สึกเสียดาย ผิวน้ำกระเพื่อมเล็กน้อยแล้วก็สงบลง."
  },
  Event_7310_Name = {
    Text = "เสียงจากอีกฟาก"
  },
  Event_7311_ChoiceDesc1 = {
    Text = "【ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」】"
  },
  Event_7311_ChoiceDesc2 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7311_Desc = {
    Text = "เหตุการณ์353 (กำลังพัฒนา)，ไม่ใช่ผลสุดท้าย"
  },
  Event_7311_Name = {
    Text = "เหตุการณ์353 (ในระหว่างการพัฒนา)"
  },
  Event_7312_ChoiceDesc1 = {
    Text = "【Leave】การติดเชื้อ「(Skill.Arg1)」 ได้รับ 50 รอยดำ"
  },
  Event_7312_Desc = {
    Text = "「พวกเจ้ามนุษย์ไม่มีคำตอบอื่นอีกแล้วหรือ?」\nเจ้าของเสียงส่งเสียงคำรามอย่างเบื่อหน่าย ขณะที่ทั้งพื้นที่สั่นสะเทือนตามไปด้วย。\n「ความโลภและความไม่รู้... นี่คือเหตุผลที่ทำให้ฉันเบื่อหน่ายพวกเจ้า。」"
  },
  Event_7312_Name = {
    Text = "เสียงจากอีกฟาก"
  },
  Event_7313_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7313_Desc = {
    Text = "ยอมรับการจัดวางของดินแดนลับแล จากสิ่งที่ได้และเสียไป ยอมรับการโอบกอดที่ถูกสาปแช่งด้วยความสงบ"
  },
  Event_7313_Name = {
    Text = "การพุ่งพล่านของความหลงผิด"
  },
  Event_7314_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7314_Desc = {
    Text = "ดวงตากะพริบช้าๆ ไม่แน่ใจว่าเข้าใจคำถามของคุณหรือไม่ \n น้ำตาสีทองแดงหยดจากมุมตา ราวกับดวงดาวเล็กๆ เปล่งประกายแสงอุ่นเหมือนดวงอาทิตย์ มันตกลงมา ตกลงมา พร้อมกับความเศร้าและความสงสาร แตกกระจายเป็นฝุ่นละอองเล็กๆ บนหินอิฐ \n คุณสะดุดกลับมาอีกครั้ง ดวงตานั้นหายไปแล้ว。"
  },
  Event_7314_Name = {
    Text = "มองอย่างบอด"
  },
  Event_7315_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7315_Desc = {
    Text = "เด็กๆ หลายคนที่แต่งตัวเรียบง่ายและดูสกปรกกำลังวิ่งอยู่บนถนน โดยมีผู้ใหญ่ที่สวมชุดตำรวจไล่ตามอยู่ข้างหลัง เด็กคนหนึ่งใส่หมวกคลุมสีน้ำตาลที่ทำให้คุณรู้สึกคุ้นเคย。"
  },
  Event_7315_Name = {
    Text = "ความทรงจำของเรา"
  },
  Event_7316_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7316_Desc = {
    Text = "「อย่าร้องอีกแล้ว——」\nคุณเตือนนักร้องที่เสียงเพี้ยน อย่าได้หวังจะมาทำลายโสตประสาทของคุณอีก"
  },
  Event_7316_Name = {
    Text = "ผู้ร้ายบนทางแคบ"
  },
  Event_7317_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7317_Desc = {
    Text = "「หยุดเดิน!!! มอนสเตอร์การย่อยสลายที่คลานอยู่ยังรู้จักแขนขาของตัวเองดีกว่าคุณ!」\nปล่อยผู้ชมไป......\nคุณอธิษฐานในใจแบบนี้。"
  },
  Event_7317_Name = {
    Text = "ผู้ร้ายบนทางแคบ"
  },
  Event_7318_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7318_Desc = {
    Text = "ดินโคลนสีดำตกลงบนใบหน้าของคุณ ทำให้รู้สึกคันขึ้นมา\nคุณไม่สามารถทนได้ จึงยื่นมือไปตบผีเสื้อ\nผีเสื้อหลบหลีกการเคลื่อนไหวที่ไม่เป็นมิตรของคุณ และหายไปอย่างเงียบเชียบที่ปลายทาง。"
  },
  Event_7318_Name = {
    Text = "สิ่งที่ไม่ควรมีอยู่"
  },
  Event_7319_ChoiceDesc1 = {
    Text = "【ชมมัน】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7319_Desc = {
    Text = "เจนกินพูดว่า: ตื่นสิ จอห์นนี่! การเขียนบทกวีนั้นไม่ช่วยล้างหนี้ที่นายค้างไว้ และก็ไม่ช่วยแก้ปัญหาพื้นบ้านรั่วของนายได้หรอก\nนายพูดว่า: น่าเสียดายที่เซลล์ที่แสวงหาความจริงของนายจะตายวันละแสนเซลล์ ไม่นานนายก็จะกลายเป็นแค่สมองส่วนต้นแท้ๆ\nสมองยักไหล่อย่างไม่ใส่ใจ ถ้ามันมีไหล่ให้ยักก็เถอะ\nสมองพูดว่า: ฉันคิด ฉันจึงมีอยู่ เมื่อไหร่นายมีความคิดลึกซึ้งได้อย่างฉัน นายก็จะไม่สนใจสมองส่วนต้นอีกต่อไป。"
  },
  Event_7319_Name = {
    Text = "สมองปรัชญา"
  },
  Event_7320_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7320_Desc = {
    Text = "เปียโนส่งเสียงถอนหายใจเบา ๆ ราวกับปลอบโยน หรือแสดงความคิดถึง เหมือนรอยยิ้มของใครบางคนในช่วงท้ายของเพลง \n「ขอเพียงเด็ก ๆ... ขอเพียง...」 \nคุณยังไม่ได้ยินเสียงชัดเจน เปียโนก็ล่องลอยไปตามสายลมแล้ว。"
  },
  Event_7320_Name = {
    Text = "เพลงของวัยเด็ก"
  },
  Event_7321_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้างเงิน เลือก 1 จาก 3, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7321_Desc = {
    Text = "คุณรับสมุดบันทึกทางการแพทย์ที่หนาและเปิดออก พบว่าหน้าปกเขียนคำว่า「G·R」สองคำ。\n「โอ้ โอ้ นี่ไม่ใช่บันทึกของคุณหรอกเหรอ?」คลีเมนไทน์ดูเหมือนไม่ได้ใส่ใจ，「แต่การศึกษาจิตใจของคนอื่นก็สามารถเพิ่มความเข้าใจในตัวเองได้นะ。」\nยังไม่ทันที่คุณจะถาม เธอก็หายไปจากสายตาอย่างสิ้นเชิง。"
  },
  Event_7321_Name = {
    Text = "บันทึกการรักษา"
  },
  Event_7322_ChoiceDesc1 = {
    Text = "【ออก】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7322_Desc = {
    Text = "คุณรับบันทึกการรักษาที่บางเบาและเปิดมัน พบว่าข้างในมีแค่แผ่นกระดาษแผ่นเดียวเขียนไว้เพียงประโยคเดียว \n「ในความเคออสอันยาวนาน ดวงตาที่ซีดไร้หนังตากำลังจ้องมองอยู่ตลอดกาล」 \nคุณต้องการถามคลีเมนไทน์ แต่พบว่าเธอได้หายไปแล้ว。"
  },
  Event_7322_Name = {
    Text = "บันทึกการรักษา"
  },
  Event_7323_ChoiceDesc1 = {
    Text = "【ติดต่อ】ฟื้นฟูชีวิตทั้งหมด。"
  },
  Event_7323_ChoiceDesc2 = {
    Text = "【การตื่นรู้】เลือกปลุกผู้ตื่น 1 ตน。"
  },
  Event_7323_Desc = {
    Text = "คุณกำลังสำรวจในหมอก จู่ๆ เข็มกลัดที่หน้าอกก็ปล่อยแสงสีเงินอ่อนๆ อะไรคือเสียงที่เรียกคุณจากปลายสายของเครื่องสื่อสาร?"
  },
  Event_7323_Name = {
    Text = "จุดติดต่อ"
  },
  Event_7324_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7324_Desc = {
    Text = "หลักฐานสำคัญยังควรเก็บรักษาอย่างรอบคอบ และส่งให้ภาควิชาประวัติศาสตร์ทำการวิจัยและวิเคราะห์"
  },
  Event_7324_Name = {
    Text = "รหัสลับ·บน"
  },
  Event_7325_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7325_Desc = {
    Text = "ดวงอาทิตย์ส่องแสงจากฟากฟ้าสูงสู่พื้นดิน ทะลุผ่านความมืดมัว ปลุกวิญญาณที่เหนื่อยล้า"
  },
  Event_7325_Name = {
    Text = "มุมยก"
  },
  Event_7326_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7326_Desc = {
    Text = "คุณรู้สึกพึงพอใจ สายตาของพวกเขาวูบวาบบนท้องฟ้ายามราตรีเหนือศีรษะ จับจ้องไปที่ตัวนั้น"
  },
  Event_7326_Name = {
    Text = "ตาโดม"
  },
  Event_7327_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7327_Desc = {
    Text = "คุณไม่สามารถหลบหนีจากการจ้องมองที่ทำให้รู้สึกอึดอัดได้ และแน่นอนว่าคุณก็ไม่สามารถต่อต้านของขวัญจากเทพเจ้าได้เช่นกัน。"
  },
  Event_7327_Name = {
    Text = "ตาโดม"
  },
  Event_7328_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，รับสถานะ「(Skill.Arg2)」"
  },
  Event_7328_Desc = {
    Text = "「คุณเป็นใครกันแน่?」คุณถามด้วยความตกใจ。\n「ไม่ต้องสนใจเรื่องเหล่านี้。ศัตรูของศัตรูคือเพื่อน ไม่ใช่เหรอ?」ผู้ชายยิ้ม。\n「ของขวัญอยู่บนเก้าอี้แล้ว ขอให้โชคดี」"
  },
  Event_7328_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅳ"
  },
  Event_7329_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7329_Desc = {
    Text = "รามอน่าเข้าใกล้ขึ้นไป หวังว่าจะได้ยินข่าวเกี่ยวกับ「เสื้อกาวน์สีขาว」มากขึ้น 「มีคนแอบฟัง!」เสียงของเครื่องเล่นแผ่นเสียงดังขึ้นอย่างฉับพลัน，「แอบฟัง แอบฟัง แอบฟัง!」"
  },
  Event_7329_Name = {
    Text = "หูของผู้อื่น"
  },
  Event_7330_ChoiceDesc1 = {
    Text = "【ออกไป】ผู้ปลุกเสกทั้งหมดจะฟื้นฟูความบ้าคลั่ง Arg1 คะแนน"
  },
  Event_7330_Desc = {
    Text = "คุณจับมือเล็กๆ ที่นุ่มนวลของเด็กชาย เดินผ่านประตูทีละบาน จนในที่สุดมาถึงเวทีเล็กๆ ที่เก่าและทรุดโทรม \n เด็กชายบีบมือคุณเบาๆ เพื่อแสดงความขอบคุณ \n 「ขอบคุณนะ ลาก่อน」"
  },
  Event_7330_Name = {
    Text = "พิธีปิดฉากⅡ"
  },
  Event_7331_ChoiceDesc1 = {
    Text = "【ดำเนินการต่อ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」, คุณต้องการตกลงไปต่อหรือไม่"
  },
  Event_7331_ChoiceDesc2 = {
    Text = "【ถอนตัวออก】ได้รับ 25 รอยดำ"
  },
  Event_7331_Desc = {
    Text = "「คุณ」กำลังเชิญคุณอยู่。\nในความลึกของเกลียวคลื่น ตัวตนในอดีตและอนาคตของ「คุณ」ได้มอบ「ของขวัญ」จากมิติต่าง ๆ ให้กับคุณ。"
  },
  Event_7331_Name = {
    Text = "เหววน"
  },
  Event_7332_ChoiceDesc1 = {
    Text = "【ปิดปากเงียบ】ได้รับ 25 รอยดำ"
  },
  Event_7332_ChoiceDesc2 = {
    Text = "【ยื่นมือสัมผัส】50% โอกาสได้รับ 50 รอยดำ, 50% โอกาสไม่ได้อะไรเลย"
  },
  Event_7332_Desc = {
    Text = "「ฉันมีคำกล่าวเพียงประโยคเดียว——ไม่มีใครสามารถฆ่าแมวได้!」\n「เจ้าแมวดำตัวนั้นที่น่ารังเกียจมันควรจะถูกเฉือนท้อง ทิ้งซากอยู่ในถิ่นแห้งแล้ง แต่ทว่ามันกลับขุดหลุมศพของตระกูลฉันแล้วกินเนื้อมนุษย์ที่เหลือทั้งหมด โครงกระดูกและชิ้นส่วนร่างกายกระจัดกระจายไปทั่ว。」\n「ภายใต้ดวงตาแนวตั้งที่เย็นชาและมืดมน น้ำหนองสีเหลืองขุ่นลอยมีกลิ่นเหม็น ฉันคลานหนีออกไปอย่างตื่นตระหนก ถูกฝันร้ายทรมานจนจิตใจหดหู่。」\n「เดี๋ยวสิ...พวกคุณจะทำอะไร ฉันไม่ได้บ้า! ฉันไม่ได้บ้า! พวกคุณต้องซ่อนอะไรไว้แน่! มันเป็นเรื่องจริง——」\nนี่เป็นเรื่องจริงแน่นอน มองดูเงาคนเสียสติจางหายไป คุณสบตากับแมวดำที่นั่งอยู่ข้างเท้าเงียบๆ หนึ่งครั้ง。"
  },
  Event_7332_Name = {
    Text = "ภัยพิบัติของแมวกลางคืน"
  },
  Event_7333_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7333_Desc = {
    Text = "คุณถามเขาเกี่ยวกับทิศทางของพิพิธภัณฑ์หุ่นขี้ผึ้ง。\nแปลกจริงๆ นับตั้งแต่ครั้งนี้ ในคืนนี้พวกคุณเจอกันแล้วห้าครั้ง。คุณจุดไฟให้เขาห้าครั้ง ถามทางห้าครั้ง。\nแต่คุณยังจำที่ตั้งของพิพิธภัณฑ์หุ่นขี้ผึ้งไม่ได้ เช่นเดียวกับที่คุณและเขายังคงพบกันเรื่อยๆ。"
  },
  Event_7333_Name = {
    Text = "รูปเงาใต้ไฟถนน"
  },
  Event_7334_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ 25 รอยดำ ส่งผลให้「(Skill.Arg2)」 เลือกต่อไป"
  },
  Event_7334_ChoiceDesc2 = {
    Text = "【ไล่ตามเด็กต่อไป】ออก"
  },
  Event_7334_Desc = {
    Text = "อีกาตัวที่สามจากไป บินไปยังที่ไกลเกินสายตา สู่ความมืดมิดนิรันดร์"
  },
  Event_7334_Name = {
    Text = "การจ้องมองของนกกาดำ"
  },
  Event_7335_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 75 รอยดำ เกิดการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7335_Desc = {
    Text = "สัมผัสที่ขนมีความนุ่มนวลและละเอียดอ่อน ยังเหลือความร้อนที่เหลือจากชีวิตของคุมไว้ \n นั่นคือแสงอาทิตย์สุดท้ายก่อนที่พระอาทิตย์ลับขอบฟ้า ความร้อนที่เหลือนั้นหายไปในพริบตา。"
  },
  Event_7335_Name = {
    Text = "ความร้อนที่เหลือ"
  },
  Event_7336_ChoiceDesc1 = {
    Text = "【ไล่ตาม】"
  },
  Event_7336_Desc = {
    Text = "คุณตรวจสอบผนังอย่างละเอียด และในที่สุดก็พบทางเข้าท่อระบายน้ำที่ซ่อนอยู่หลังพุ่มหญ้า คุณคลานผ่านท่อระบายน้ำ แต่สัตว์ประหลาดได้วิ่งหนีไปไกลแล้ว。"
  },
  Event_7336_Name = {
    Text = "ทางตัน"
  },
  Event_7337_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7337_Desc = {
    Text = "นกต่างๆ มีระเบียบของตนเอง พวกมันไม่ได้ทำตามความประสงค์ของคุณ และคุณไม่มีสิทธิ์แทรกแซงกฎธรรมชาติ。"
  },
  Event_7337_Name = {
    Text = "กุยบินโดดเดี่ยว"
  },
  Event_7338_ChoiceDesc1 = {
    Text = "【มองลงไปเห็นเงา】ได้รับ 25 รอยดำ"
  },
  Event_7338_ChoiceDesc2 = {
    Text = "【คุณเป็นอย่างไรบ้าง?】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7338_Desc = {
    Text = "「คุณ... คุณรู้ไหม... เจ้าของร้านคนใหม่ที่อยู่ข้างๆ มักจะไม่ออกจากบ้าน... วันนั้นฉันเชิญเธอมาดื่มเบียร์หนึ่งแก้ว หลังจากที่ฟองหายไปหมด ฉันก็พบว่า... ในแก้วเหล้าเธอ... เธอไม่มีเงา!」"
  },
  Event_7338_Name = {
    Text = "ชิ้นส่วนความทรงจำ·เบียร์"
  },
  Event_7339_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7339_Desc = {
    Text = "「ฉันอยากร้องเพลงกับคุณอีกครั้ง...」\nเสียงกรีดร้องอย่างบ้าคลั่งของซาร่าที่บิดเบือนหยุดลงอย่างกะทันหัน ใบหน้าที่บิดเบือนเผยให้เห็นความสับสนเล็กน้อย。"
  },
  Event_7339_Name = {
    Text = "「พี่สาวซาซา」"
  },
  Event_7340_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7340_Desc = {
    Text = "「ดีใจจัง! ดีใจจัง!」เสียงที่ดังและแหลมคมเต็มไปด้วยความไร้เดียงสาดังขึ้นข้างหูของคุณ「ให้คุณ, ให้คุณ!」"
  },
  Event_7340_Name = {
    Text = "เอลฟ์แห่งราตรี"
  },
  Event_7341_ChoiceDesc1 = {
    Text = "【สมุดบันทึกทางการแพทย์ที่หนา】"
  },
  Event_7341_ChoiceDesc2 = {
    Text = "【สมุดบันทึกทางการแพทย์เล่มบาง】"
  },
  Event_7341_Desc = {
    Text = "เสียงที่คุ้นเคยเรียกคุณ คุณหรี่ตา แต่ไม่สามารถมองเห็นรูปร่างของเธอได้ \n「ฉันรู้ว่าคุณกำลังเร่งรีบ」 หมอคลีเมนไทน์พูดด้วยน้ำเสียงสดใส 「ฉันสัญญาว่าจะไม่ทำให้คุณเสียเวลานานเกินไป」 \n มือสองข้างทะลุผ่านหมอกในสมองของคุณมา ถือสมุดบันทึกการรักษาอยู่ในมือ หนึ่งเล่มหนาและมีรอยขีดข่วน อีกหนึ่งเล่มบางและใหม่เอี่ยม \n「จากผลการสอบถามของคุณ ฉันได้ทำบันทึกการรักษาให้คุณโดยไม่ขออนุญาต แต่ฉันลืมไปว่าหนังสือเล่มไหนเป็นของคุณ ลองเลือกดูหน่อยไหม?」 \n ไม่รู้ว่าเพราะเหตุใด สมุดบันทึกที่บางนั้นกลับส่งกลิ่นอายที่คุ้นเคยออกมา และมีความสัมพันธ์ทางจิตวิญญาณที่เชื่อมโยงกับคุณและผู้ปลุกตื่นอย่างจางๆ。"
  },
  Event_7341_Name = {
    Text = "บันทึกการรักษา"
  },
  Event_7342_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7342_Desc = {
    Text = "ผนังธรรมดา คุณอดไม่ได้ที่จะเคาะมัน แต่กลับรู้สึกว่าไม่ใช่ของแข็ง"
  },
  Event_7342_Name = {
    Text = "ผนังประหลาด"
  },
  Event_7343_ChoiceDesc1 = {
    Text = "【ฉันไม่ได้อยู่บนผิวน้ำ】สุ่มเลือกสิ่งสร้างเงิน 1 ชิ้นอัปเกรดเป็นสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7343_ChoiceDesc2 = {
    Text = "【ก้มลงดู】ได้รับสิ่งประดิษฐ์เงิน 「(RelicConfig.Arg1)」，ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7343_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7343_Desc = {
    Text = "「ฮิฮิ ผู้พิทักษ์ คุณยังจำคำเตือนของเวินเค่อได้ไหม? ฟังนะ อย่า มอง ลง สู่ เงา ของ ตัวเอง ใน เวลา เที่ยง.」"
  },
  Event_7343_Name = {
    Text = "ภาพสะท้อนไร้รูปทรง"
  },
  Event_7343_Tips1 = {
    Text = "ยังไม่มีสิ่งสร้างเงิน"
  },
  Event_7344_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7344_Desc = {
    Text = "ภาพลวงตาจากอนาคตอันไกลโพ้น ซ่อนตัวอยู่ในช่องเขาของเอลวอส。"
  },
  Event_7344_Name = {
    Text = "ภาพลวงตาของภูเขาไฟ"
  },
  Event_7345_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7345_Desc = {
    Text = "ผีเสื้อแตกสลายอยู่ในฝ่ามือของคุณ ราวกับกระจกเพดานที่ถูกตีแตกอย่างรุนแรง เศษเสี้ยวที่แตกหักตกลงสู่แรงดึงดูดของโลก ตกลง ตกลง ตกลง——"
  },
  Event_7345_Name = {
    Text = "ภาพหลอนของสะพานเหล็ก"
  },
  Event_7346_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7346_Desc = {
    Text = "รอให้พวกเขาปรากฏตัวจากเงามืดนั่นแหละ"
  },
  Event_7346_Name = {
    Text = "โคมไฟหงส์ดำ"
  },
  Event_7347_ChoiceDesc1 = {
    Text = "【เปิดสวิตช์】ขยายขอบเขตการมองเห็นปัจจุบัน。"
  },
  Event_7347_Desc = {
    Text = "อุปกรณ์ส่องสว่างที่เหลืออยู่จากคนรุ่นก่อน สามารถขับไล่หมอกสีดำรอบๆ ได้。\nหมอกที่อยู่รอบๆ มันคลื่นไหวอย่างมีระเบียบ ราวกับถูกการหายใจของมันรบกวน。"
  },
  Event_7347_Name = {
    Text = "ไฟส่องสว่าง"
  },
  Event_7348_ChoiceDesc1 = {
    Text = "【ระบุปัญหา】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7348_ChoiceDesc2 = {
    Text = "【กลืนคำถาม】ติดเชื้อ「(Skill.Arg1)」, การแกะสลักใหม่, สามารถทำได้มากที่สุด 2 ครั้ง"
  },
  Event_7348_Desc = {
    Text = "จนถึงตอนนี้ คุณยังคงรำลึกถึงอดีตที่เมอร์ฟี่เล่าให้ฟัง \n ความทรงจำทำให้คุณรู้สึกเห็นใจ ถูกผูกมัดและบีบคั้นอยู่ในสมองของคุณ แม้กระทั่งคำปลอบใจจากโกไลแอทที่มีต่อเมอร์ฟี่ก็ไม่สามารถทำให้คุณรู้สึกสบายใจได้ \n ...เดี๋ยวก่อน พวกเขาบอกว่าเมื่อดาวอยู่ในตำแหน่งปกติจะเกิดขึ้นในอีกยี่สิบห้าปีข้างหน้า... \n แต่เมอร์ฟี่ที่อยู่ตรงหน้าชัดเจนว่าเป็นแค่เด็กวัยรุ่นคนหนึ่ง..."
  },
  Event_7348_Name = {
    Text = "ชีวิตที่ถูกกักขัง"
  },
  Event_7349_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์เงิน 3 ตัวเลือก 1, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7349_Desc = {
    Text = "เธอควรจะหลั่งน้ำตา ไม่มีใครมีสิทธิ์ร้องไห้มากกว่าเธออีกแล้ว\nแต่ทำไมเธอถึงไม่ร้องล่ะ? ทำไมเธอถึงแค่เป็นผู้ชมอยู่ห่างๆ เหมือนกับว่าคนเหล่านั้นไม่ได้กราบไหว้เธอเลย..."
  },
  Event_7349_Name = {
    Text = "พิธีก่อนบิน"
  },
  Event_7350_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7350_Desc = {
    Text = "อย่างไรก็ตาม การสอดแนมเรื่องส่วนตัวของคนอื่นถือว่าเสียมารยาท"
  },
  Event_7350_Name = {
    Text = "เหมือนได้พบกัน"
  },
  Event_7351_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7351_Desc = {
    Text = "คงจะแค่ตาฝาดไปชั่วขณะ"
  },
  Event_7351_Name = {
    Text = "การจ้องมองของนกกาดำ"
  },
  Event_7352_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_7352_Desc = {
    Text = "ในความทรงจำ ทุกคนต่างก็สวดมนต์ขอร้องเธอ คุณเองก็อดไม่ได้ที่จะเงียบๆ ท่องในใจ.."
  },
  Event_7352_Name = {
    Text = "พิธีก่อนบิน"
  },
  Event_7353_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7353_Desc = {
    Text = "ใต้ท้องของวิฬารดำมีของเหลวเหนียวสีดำหยดลงมาอย่างต่อเนื่อง ลำธารเล็กๆ ที่เกิดจากของเหลวเหนียวที่รวมตัวกันนั้นไหลตรงไปยังท่อระบายน้ำที่ปากตรอก. เมื่อเห็นว่าคุณไม่มีท่าทีจะเข้าใกล้ วิฬารดำจึงหันหลังกระโดดลงท่อระบายน้ำ หายไปจากสายตา."
  },
  Event_7353_Name = {
    Text = "เอลฟ์แห่งราตรี"
  },
  Event_7354_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7354_Desc = {
    Text = "คุณตกใจอย่างมาก ส่งเสียงกรีดร้องที่แหลมดัง \n ดูเหมือนว่าถูกเสียงของคุณหลอกลวง มือที่เคยไม่อดทนชะงักไปชั่วขณะ \n คุณใช้โอกาสนี้รีบหนีออกไปทันที。"
  },
  Event_7354_Name = {
    Text = "บึงมืด"
  },
  Event_7355_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7355_Desc = {
    Text = "บิดเบือน, เลื้อย, คลาน... คุณใช้ทุกวิธีเพื่อหลบหนีจากแขนที่น่ารำคาญเหล่านี้ \n ในที่สุดคุณก็หลบหนีออกมาได้ โดยมีราคาที่ต้องจ่ายคือชุดนักเรียนใหม่เอี่ยม, ซี่โครงสองซี่ และเส้นผมอีกหลายร้อยเส้น。"
  },
  Event_7355_Name = {
    Text = "บึงมืด"
  },
  Event_7356_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7356_Desc = {
    Text = "「เป็นเรื่องปกติ อย่าตกใจไปเหมือนมือใหม่เพิ่งเริ่มทำงาน」\nดอลล์เข้ามาใกล้และช่วยจัดตำแหน่งเข็มกลัดของคุณให้ถูกต้อง「แสดงว่ามีทางเดินของมิติพิเศษอยู่ใกล้ๆ ดูเหมือนจะอยู่ในทิศทางของโรงพยาบาลจิตเวช」"
  },
  Event_7356_Name = {
    Text = "ไม้พิณที่ไม่สงบ"
  },
  Event_7357_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7357_Desc = {
    Text = "คุณไม่มีเหตุผลที่จะยอมรับความต้องการในการให้อาหารจากผู้ศรัทธาแห่งโคมไฟ \n อีกาเคลื่อนไหวศีรษะที่ซ้อนกันอย่างน่าสะอิดสะเอียนด้วยความไม่พอใจ ส่งเสียงแปลกๆ ที่คุณจะได้ยินเฉพาะที่ข้างหลุมศพ ก่อนที่จะกรีดร้องและบินจากไป。"
  },
  Event_7357_Name = {
    Text = "นกกาถูกสาป"
  },
  Event_7358_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7358_Desc = {
    Text = "「นี่ก็เป็นทางเลือกของฉัน」 เงาของคนที่กอดหมีพูดว่า 「แต่เธอจะกลายเป็นหุ่นเชิดของเขา และพวกเขาจะต้องตายไป \n คุณจะเป็นผู้สมรู้ร่วมคิดที่ชั่วร้าย」 \n ความรู้สึกผิดอย่างรุนแรงจะจมคุณลง เงานั้นจางหายไป คุณกุมหัวใจของตัวเอง ไม่รู้ว่าเมื่อกี้เป็นภาพลวงตาหรือเป็นภาพหลอนที่เกิดจากความกดดันทางจิตใจ。"
  },
  Event_7358_Name = {
    Text = "ทางแยกเล็กๆ"
  },
  Event_7359_ChoiceDesc1 = {
    Text = "【ปิดหูต่อไป】รับค่าความคลั่งสูงสุดของร่างกายที่ตื่นขึ้น จำนวนรอยดำเท่ากับค่าความคลั่ง (Arg1)"
  },
  Event_7359_ChoiceDesc2 = {
    Text = "【ยังคงปิดหูต่อไป】ฟื้นฟู(Arg1)จุดชีวิต รอยดำที่มีอยู่จะเพิ่มปริมาณการฟื้นฟู"
  },
  Event_7359_Desc = {
    Text = "คุณยอมทำตามคำปลอบโยนที่ไม่หวังดีข้างหู, เสียงกรีดร้องดุจปลายเข็มบิดตัวแทงเข้าไปในรูหู.\n「หยุด——หยุดเร็ว——ฉันทำตามที่แกบอกแล้ว——หยุดเร็ว——」\nคุณปิดหัวด้วยความเจ็บปวด, แล้วก็ได้ยินเสียงเยาะเย้ยของฝูงอีกา."
  },
  Event_7359_Name = {
    Text = "เพลงของฝูงอีกา"
  },
  Event_7360_ChoiceDesc1 = {
    Text = "【จับอีกาได้หนึ่งตัว】ทุกๆ ร่างกายที่ตื่นขึ้นจากการตื่นรู้ 1 คน จะได้รับ +25 รอยดำ"
  },
  Event_7360_ChoiceDesc2 = {
    Text = "【ส่งเสียงแหลม】เลือกร่างกายที่ตื่นขึ้น 1 ตัว และเพิ่ม「ผลเฉพาะเจาะจง」กับ「ผลคงเหลือ」ให้กับการ์ดการตื่นรู้"
  },
  Event_7360_Desc = {
    Text = "คุณเกิดความคิดเล่น ๆ ยื่นมือไปจับอีกาหนึ่งตัว \n มันดิ้นรนอย่างสิ้นหวังในฝ่ามือของคุณ สุดท้ายก็ระเบิดกลายเป็นน้ำอุ่น ๆ。"
  },
  Event_7360_Name = {
    Text = "เพลงของฝูงอีกา"
  },
  Event_7361_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7361_Desc = {
    Text = "คุณปิดหูและหลับตาลง \n โดน โดน……เสียงหัวใจของคุณและเสียงแหลมกรีดร้องประสานกัน รังสรรค์เป็นบทเพลงแห่งความตายที่ยุ่งเหยิง \n ในขณะนี้ คุณรู้สึกถึงความเงียบสงบที่ไม่เคยมีมาก่อน。"
  },
  Event_7361_Name = {
    Text = "เพลงของฝูงอีกา"
  },
  Event_7362_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7362_Desc = {
    Text = "ในดินแดนลับแลเต็มไปด้วยอันตราย ไม่ใช่ทุกแสงสว่างจะเป็นประภาคารที่ชี้นำทางไปข้างหน้า。\nมันอาจเป็นแสงเทียนที่ดึงดูดแมลงเม่าก็ได้。"
  },
  Event_7362_Name = {
    Text = "แสงนีออนยามค่ำคืน"
  },
  Event_7363_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7363_Desc = {
    Text = "「คุณตายไปนานแล้ว และไม่มีทางกลับบ้านได้.」 เสียงของคุณเย็นชาราวกับว่าเป็นวายุที่เห่าหอนบนทุ่งหิมะของรอสส์. สีหน้าของนักเดินทางไม่เปลี่ยนแปลงแม้แต่น้อย ราวกับว่าเรื่องนี้เป็นเรื่องปกติ. เขาจับมือคุณอีกครั้ง 「ช่วยฉันด้วย. ฉันเป็นทหารที่ได้รับคำสั่งให้เดินทางไปยังดินแดนตะวันออกอันไกลโพ้น...」"
  },
  Event_7363_Name = {
    Text = "ผู้กลืนกิน"
  },
  Event_7364_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7364_Desc = {
    Text = "เครื่องโทรเลขเสียแล้ว คุณสามารถจินตนาการถึงความสิ้นหวังของเจ้าของเครื่องโทรเลขในพายุได้หรือไม่... เพราะตอนนี้คุณก็เป็นเช่นนั้น。"
  },
  Event_7364_Name = {
    Text = "โทรเลขเงียบ"
  },
  Event_7365_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7365_Desc = {
    Text = "「เดินไปข้างหน้า 50 หลา เลี้ยวซ้าย จากนั้นเลี้ยวขวา แล้วเลี้ยวซ้ายอีกครั้ง……\nแล้วเดินต่อไปจนสุดทาง บ้านของคุณอยู่ที่นั่น。」\nนักเดินทางดีใจมาก เขาโบกมือให้คุณแล้วจากไป\nคุณถอนหายใจยาวๆ จู่ๆ ก็รู้สึกว่ามีคนจับมือคุณไว้ ข้างหูคุณได้ยินเสียงที่คุ้นเคยอีกครั้ง：\n「ช่วยฉันด้วย。\nฉันเป็นทหาร ได้รับคำสั่งไปยังตะวันออกที่ห่างไกล……」"
  },
  Event_7365_Name = {
    Text = "ผู้กลืนกิน"
  },
  Event_7366_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7366_Desc = {
    Text = "คุณในที่สุดก็เดินออกจากเขาวงกตนี้ได้。\nในขณะนั้นคุณก็เข้าใจทันทีว่า พิพิธภัณฑ์หุ่นขี้ผึ้งนี้คือสิ่งมีชีวิต。\nทุกสิ่งที่กลอุบาย ความงาม และความโหดร้าย ล้วนเชื่อมโยงกันด้วยพิธีกรรมโบราณ。\nและดวงตาของพิธีกรรมก็คือโรเจอร์ส。"
  },
  Event_7366_Name = {
    Text = "เขาวงกตของตา"
  },
  Event_7367_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7367_Desc = {
    Text = "「การแสดงบทบาทสนุกไหม ผู้พิทักษ์?」 ราโมน่าดึงแขนเสื้อของคุณเล็กน้อย 「ทางออกอยู่ไม่ไกลจากเรา หวังว่าคุณจะรักษาความขบขันในช่วงเวลานี้ไว้ต่อหน้าคุณนายดาฟโฟดิลด้วย」"
  },
  Event_7367_Name = {
    Text = "ชิ้นส่วนแห่งความทรงจำ·ความฝันในอดีตหวนคืน"
  },
  Event_7368_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7368_Desc = {
    Text = "「ร่างกายที่ตื่นขึ้นยากที่จะต่อต้านความตั้งใจของผู้ลิงก์，」คุณตอบกลับ，「แต่เราจะไม่ยอมแพ้。」"
  },
  Event_7368_Name = {
    Text = "การเลือกของเธอ"
  },
  Event_7369_ChoiceDesc1 = {
    Text = "【Enter】ทะลุผ่านกำแพง เพื่อค้นหาความจริง。"
  },
  Event_7369_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7369_Desc = {
    Text = "คุณเข้าใกล้กำแพง จู่ๆ ผิวของกำแพงก็เริ่มบิดตัวอย่างประหลาด ราวกับพยายามจะดูดคุณเข้าไป"
  },
  Event_7369_Name = {
    Text = "พื้นที่บิดเบี้ยว"
  },
  Event_7370_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7370_Desc = {
    Text = "「ไม่ นี่ไม่ใช่ความจริง อย่างน้อยพวกคุณก็มีร่างกายที่ปกคลุมด้วยขนฟูมากกว่าจิ้งจก \n ไม่มีใครสามารถปฏิเสธร่างกายที่ปกคลุมด้วยขนฟูได้」\n หนูๆ กระซิบกระซาบกัน และในที่สุดก็ยอมรับความคิดเห็นของคุณอย่างฝืนๆ \n「ยังดีนะ... จริงๆ แล้วก็ไม่ได้มีขนมากนัก」\n การถูกชมเสมอทำให้รู้สึกดี ก่อนจากไป หนูๆ ได้มอบของขวัญเล็กๆ ให้คุณ。"
  },
  Event_7370_Name = {
    Text = "พิษระบาด"
  },
  Event_7371_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7371_Desc = {
    Text = "「ฉันเห็นด้วย! มนุษย์และหนูไม่สามารถอยู่ร่วมกันได้!」\nหนูพวกนั้นเริ่มโกรธและเผยให้เห็นเขี้ยวขาวๆ ของพวกมัน。\n「แล้วคุณยังทำอะไรที่นี่? เอาของคุณไปซะ อย่ากลับมาอีกเลย。」"
  },
  Event_7371_Name = {
    Text = "พิษระบาด"
  },
  Event_7372_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_7372_Desc = {
    Text = "ยินดีต้อนรับสู่ใต้มหาสมุทรลึก ที่นี่ทุกย่างก้าวจะเต็มไปด้วยแรงกดดันมหาศาล\n\nหมอกแห่งความโกลาหลที่ไม่สามารถส่องแสงผ่านจะปกปิดทุกสิ่งไว้ คุณจะสามารถผ่านทะเลแห่งความมืดนี้ไปได้หรือไม่ภายใต้แรงกดดันนี้?"
  },
  Event_7372_Name = {
    Text = "ใต้คลื่นน้ำขึ้น"
  },
  Event_7373_ChoiceDesc1 = {
    Text = "(สำรวจแบบสุ่ม) ลบ 1 การ์ด"
  },
  Event_7373_ChoiceDesc2 = {
    Text = "【ดูให้ละเอียด】ได้รับ「(RelicConfig.Arg1)」ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7373_Desc = {
    Text = "「ตะตะ...」\nเครื่องพิมพ์ดีดเหมือนกับคนแก่ที่ดื่มวิสกี้มากเกินไป พูดจาอ้อมค้อมพ่นหมึกสีดำออกมา\nคุณจับได้อย่างเฉียบคมถึงคำว่า「เมสัน」ทันที แล้วดึงกระดาษพิมพ์ออกมา。"
  },
  Event_7373_Name = {
    Text = "เครื่องพิมพ์ดีด"
  },
  Event_7374_ChoiceDesc1 = {
    Text = "【จ้องตา】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7374_ChoiceDesc2 = {
    Text = "【ปิดตาทั้งสอง】สุ่มการตื่นรู้ 2 ร่างกายที่ตื่นขึ้น ติดเชื้อสองครั้ง「(Skill.Arg1)」"
  },
  Event_7374_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7374_Desc = {
    Text = "ดวงตานับไม่ถ้วนโอบล้อมอยู่รอบๆ หูของคุณ กระซิบว่า \n「เราเดินทาง เราหยุดพัก เราเดินอย่างรวดเร็วผ่านไปหลายหมื่นปีหรือแม้กระทั่งเวลาที่นานกว่านั้น \nเมื่อดวงอาทิตย์ค่อยๆ มืดลงภายใต้สายตา และชีวิตบนโลกเก่าถูกน้ำท่วมกลืนกิน \nเราได้ถูกดึงดูดโดยความลึกลับของจักรวาลอย่างลึกซึ้งแล้ว。」"
  },
  Event_7374_Name = {Text = "ตา"},
  Event_7375_ChoiceDesc1 = {
    Text = "【ปฏิบัติตามคำสั่ง】เพิ่ม Arg1 คะแนนชีวิต"
  },
  Event_7375_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7375_Desc = {
    Text = "คุณพยายามใช้พลังการย้อนรอยของกุญแจเงินเพื่อค้นหาจุดติดต่อที่ใกล้ที่สุด แต่ข้อมูลที่ได้รับกลับมีความผิดปกติที่ยากจะสังเกต ดูเหมือนว่าจะถูกขัดขวาง。"
  },
  Event_7375_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7376_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7376_Desc = {
    Text = "คุณใช้ผ้าลินินมาตรฐานที่จัดเตรียมไว้ในชุดนักเรียนมิซากะเช็ดผิวหน้าของเครื่องพิมพ์ดีดอย่างเบา ๆ \nเครื่องพิมพ์ดีดกลับคืนสู่ความสงบอีกครั้ง ส่วนผ้าขี้ริ้วที่สกปรก...ก็ปล่อยให้มันอยู่ในดินแดนลับแลเถอะ。"
  },
  Event_7376_Name = {
    Text = "เสียงกระซิบของเครื่องพิมพ์ดีด"
  },
  Event_7377_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7377_Desc = {
    Text = "คุณตั้งใจมองไปที่รอยหมึกที่ซ้อนทับกันจนสั่นไหว และเห็นชื่อหนึ่งปรากฏขึ้นอย่างไม่ชัดเจน 「Fingal Johansen」 \n นี่คือใคร?"
  },
  Event_7377_Name = {
    Text = "เสียงกระซิบของเครื่องพิมพ์ดีด"
  },
  Event_7378_ChoiceDesc1 = {
    Text = "【เงยหน้ามองตรง】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_7378_ChoiceDesc2 = {
    Text = "【มุมเงยของดวงอาทิตย์?】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น เสริมพลัง「(Skill.Arg1)」"
  },
  Event_7378_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7378_Desc = {
    Text = "「ตอนนี้ ยกหน้าขึ้นมองไปทางตะวันออกเฉียงใต้ มุมยกของสุริยันกำลังอยู่ในตำแหน่งที่ถูกต้อง」เสียงสั่งการจากดอลล์ดังมาจากเครื่องสื่อสาร。"
  },
  Event_7378_Name = {
    Text = "มุมยก"
  },
  Event_7379_ChoiceDesc1 = {
    Text = "【ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」】"
  },
  Event_7379_ChoiceDesc2 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7379_Desc = {
    Text = "เหตุการณ์354（กำลังพัฒนา），ยังไม่ใช่ผลลัพธ์ขั้นสุดท้าย"
  },
  Event_7379_Name = {
    Text = "เหตุการณ์354 (กำลังพัฒนา)"
  },
  Event_7380_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7380_Desc = {
    Text = "เสียงของเด็ก ๆ หลั่งไหลออกมาจากเปียโน \n「ลุงชาร์ลีมีแมวขนลายที่เขารักมาก ๆ ...」\n ใต้เสียงร้องของเด็ก ๆ มีเสียงของสตรีสาวคนหนึ่งที่ร้องเพลงอย่างอ่อนหวานเบา ๆ \n คุณได้ยินผิดหรือเปล่า?"
  },
  Event_7380_Name = {
    Text = "เพลงของวัยเด็ก"
  },
  Event_7381_ChoiceDesc1 = {
    Text = "【หมุนตัว】ได้รับ 25 รอยดำ"
  },
  Event_7381_ChoiceDesc2 = {
    Text = "【เดินหน้าต่อ】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7381_Desc = {
    Text = "เสียงฝีเท้าดังมาจากด้านหลัง \n ช้าๆ เหมือนเงา ไม่เร่งรีบ ไม่ช้าเกินไป \n สอดประสานกับเสียงฝีเท้าของคุณ ก้องอยู่ในห้องจัดแสดงที่กว้างขวาง。"
  },
  Event_7381_Name = {
    Text = "รองเท้าออกซฟอร์ด"
  },
  Event_7382_ChoiceDesc1 = {
    Text = "【เก็บกระดาษจดหมาย】ลบ 2 การ์ด"
  },
  Event_7382_ChoiceDesc2 = {
    Text = "【เก็บกระดาษจดหมายไว้】ได้รับสิ่งมีชีวิตแห่งคำสาป 「(RelicConfig.Arg1)」 ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7382_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ Arg1 รอยดำ"
  },
  Event_7382_Desc = {
    Text = "เครื่องพิมพ์ดีดรุ่นใหม่。\nมันมีชุดปุ่มตัวอักษรที่แตกต่างออกไป เหมือนกับกล้องจุลทรรศน์ที่หรูหราและประณีต。\nคุณกำลังหลงใหลในโครงสร้างทางกลที่สมบูรณ์แบบของมัน ตัวอักษรสีดำปรากฏขึ้นอย่างกะทันหัน。\n「เรียนคุณโรเจอร์ส，\nเรามีความเศร้าใจที่จะประกาศว่า คุณถูกไล่ออกจากวิทยาลัย。\nเป็นที่ทราบกันดีว่า @2วิทยาลัยมีชื่อเสียงในด้านทัศนคติในการศึกษาอย่างเข้มงวดในอาณาจักร ข่าวลือที่น่าตกใจ @3 ทำให้เกิดความวิตกกังวลอย่างมาก……」"
  },
  Event_7382_Name = {
    Text = "เหมือนได้พบกัน"
  },
  Event_7383_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7383_Desc = {
    Text = "นาฬิกาที่หยุดนิ่งอยู่ไกลออกไปเหมือนเป็นการเร่งรัด เตือนให้พวกคุณอย่าตกลงไปในกับดักของเวลาและ пространства"
  },
  Event_7383_Name = {
    Text = "การจ้องมองของพระองค์"
  },
  Event_7384_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7384_Desc = {
    Text = "น้ำโคลนสีดำหยดลงบนใบหน้าของคุณ ทำให้รู้สึกคันขึ้นมา\nคุณไม่อาจทนได้ จึงยื่นมือไปตบผีเสื้อ\nผีเสื้อหลบหลีกการกระทำที่ไม่เป็นมิตรของคุณ หายไปอย่างเงียบเชียบที่ปลายทาง。"
  },
  Event_7384_Name = {
    Text = "ผีเสื้อน้ำดำ"
  },
  Event_7385_ChoiceDesc1 = {
    Text = "【สังเกตอย่างละเอียด】"
  },
  Event_7385_ChoiceDesc2 = {
    Text = "【ขุด】"
  },
  Event_7385_Desc = {
    Text = "คุมแบกพวกคุณสามคนเดินค้นหาทางเข้าในโรงพยาบาลบ้า \n ทันใดนั้น มันก็หยุดกระทันหัน จนเกือบทำให้พวกคุณตกจากหลังมัน \n ในขณะที่เสียงคำถามของพวกคุณดังขึ้น คุมก้มหน้าลง สูดดมที่พื้นดินที่นุ่มนวล แล้วหันหัวไปยังพวกคุณ เหมือนกับว่ามีอะไรบางอย่างฝังอยู่ข้างล่าง"
  },
  Event_7385_Name = {
    Text = "วัตถุฝังลึก"
  },
  Event_7386_ChoiceDesc1 = {
    Text = "【รับ】ได้รับสิ่งประดิษฐ์ทองคำ เลือก 1 จาก 3"
  },
  Event_7386_Desc = {
    Text = "ที่นั่นว่างเปล่า ของทุกอย่างมืดมิด ไหลอยู่บนพื้น ไม่สะท้อนสิ่งใดเลย。\nเป็นความรู้สึกของคุณหรือเปล่า?คุณรู้สึกมีบางสิ่งหลุดรอดไปจากซอกนิ้วของคุณ。"
  },
  Event_7386_Name = {
    Text = "ใต้ผิวกระจก"
  },
  Event_7387_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7387_Desc = {
    Text = "ปีกสีดำตกลงบนดินโคลนที่ชื้นในตรอก，กลายเป็นการหลอมกร่อนสีดำ"
  },
  Event_7387_Name = {
    Text = "ฝูงอีกาสับสน"
  },
  Event_7388_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7388_Desc = {
    Text = "「คุณนายดาฟโฟดิลจะชอบอารมณ์ขันของคุณ」 ราโมน่ากระดิกมือ และเงาที่เหมือนหมอกก็จางหายไป「อย่าให้ตัวเองกลายเป็นราคาที่ต้องจ่ายของการเดินทางมิติ」"
  },
  Event_7388_Name = {
    Text = "ชิ้นส่วนแห่งความทรงจำ·ความฝันในอดีตหวนคืน"
  },
  Event_7389_ChoiceDesc1 = {
    Text = "【รับ】ได้รับสิ่งประดิษฐ์ทองคำ เลือก 1 จาก 3"
  },
  Event_7389_Desc = {
    Text = "โอใช่แล้ว เงาที่น่าขยะแขยงนั้นก็คือคุณเอง \n ความชั่วร้ายที่พุ่งออกมารวมตัวกับน้ำดำใต้เท้าของคุณ เต้นรำไปด้วยกันอย่างบิดเบือน ถ้าคุณไม่รังเกียจ มันก็อยากจะปีนขึ้นไปบนไหล่ของคุณ。"
  },
  Event_7389_Name = {
    Text = "ใต้ผิวกระจก"
  },
  Event_7390_ChoiceDesc1 = {
    Text = "【หยุดนิ่ง】ได้รับ 25 รอยดำ"
  },
  Event_7390_ChoiceDesc2 = {
    Text = "【เดินไปมาอย่างอิสระ】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7390_Desc = {
    Text = "คุณเหยียบย่ำเงาของตัวเองจนแตกสลาย ตกลงไปในความมืดของคืนหนึ่ง \n เงาสีดำที่ชำรุดเสียหายเป็นชิ้นเป็นอัน คือสิ่งเดียวที่เชื่อมโยงคุณกับโลกที่หายไป \n คุณยังต้องการเดินในฝันร้ายที่มืดมิดจริงหรือ? คุณยังไม่พบทิศทางเลย。"
  },
  Event_7390_Name = {
    Text = "ผู้เดินฝันร้าย"
  },
  Event_7391_ChoiceDesc1 = {
    Text = "【ค้นหาต้นกำเนิด】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」, ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7391_ChoiceDesc2 = {
    Text = "【เล่นแผ่นเสียงซ้ำ】ร่างกายที่ตื่นขึ้นทั้งหมดเพิ่มความคลั่ง 50 หน่วย ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7391_ChoiceDesc3 = {
    Text = "【ถอดเครื่องเล่นแผ่นเสียง】ได้รับการแกะสลัก โดยเลือก 1 จาก 3"
  },
  Event_7391_Desc = {
    Text = "คุณพบกับเครื่องเล่นแผ่นเสียงเก่าที่ทรุดโทรม\nคุณไขลานและวางเข็มลงบนแผ่นไวนิลที่เต็มไปด้วยรอยขีดข่วน เสียงซิมโฟนีที่บิดเบี้ยวเหมือนกับเสียงฉีกของเทป วงเครื่องเป่าและเครื่องสายต่อสู้กัน ไม่มีเสียงใดที่รอดออกมาจากบทเพลงนี้อย่างครบถ้วน\nเมื่อเพลงจบลงด้วยเสียงแตกพร่าฉุดรั้ง คุณกลับได้ยินเสียงเคาะเป็นจังหวะ\n「ตึ้งตึ้ง…ตึ้งตึ้งตึ้ง…ตึ้ง…」\nคุณขมวดคิ้วและยกเข็มขึ้นจากแผ่น แต่เสียงเคาะนั้นยังคงดำเนินต่อไป。"
  },
  Event_7391_Name = {
    Text = "เส้นทางเสียงลึกลับ"
  },
  Event_7392_ChoiceDesc1 = {
    Text = "【พิจารณาแสงแห่งโชคชะตา】เลือก สิ่งสร้าง 1 ชิ้น เปลี่ยนเป็น สิ่งมีชีวิตแห่งคำสาป 「 (RelicConfig.Arg1) 」"
  },
  Event_7392_ChoiceDesc2 = {
    Text = "【สัมผัสแสงสว่าง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7392_ChoiceDesc3 = {
    Text = "【หันหลังเดินจากไป】ได้รับ 25 รอยดำ"
  },
  Event_7392_Desc = {
    Text = "ใต้ทัศนียภาพแห่งความฝัน หมอกในดินแดนลับแลได้คลุมความจริงด้วยผ้าสีดำ ทุกสิ่งที่มองเห็นดูเหมือนจะมองเห็นได้ไม่ชัดเจน ราวกับมีอยู่และไม่มีอยู่ \n ในความพร่ามัว มีแสงสว่างบางอย่างทะลุผ่านหมอก ดุจประภาคารสำหรับเรือเดินทะเล ควันจากการทำอาหารสำหรับเด็กที่หลงทาง ชี้นำไปในทิศทางที่ปลอดภัย。"
  },
  Event_7392_Name = {
    Text = "แสงนีออนยามค่ำคืน"
  },
  Event_7393_ChoiceDesc1 = {
    Text = "【หยุดเพลง】อัปเกรดสิ่งสร้างเงิน 1 ชิ้นเป็นสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7393_ChoiceDesc2 = {
    Text = "【บทสนทนา】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」และ「(Skill.Arg3)」"
  },
  Event_7393_ChoiceDesc3 = {
    Text = "【ฟังอย่างสงบ】ได้รับ 25 รอยดำ"
  },
  Event_7393_Desc = {
    Text = "คุณดึงความทรงจำที่แตกสลายบางส่วนขึ้นมาจากกองน้ำดำที่แปดเปื้อน \nผลึกใสแจ๋วมีแสงส่องประกาย เส้นด้ายบางๆ สะบัดอยู่ภายใน ความทรงจำที่เหลืออยู่เหมือนกรวดที่ถูกลมพัดกระจาย ฟุ้งกระจายในอากาศ \nภาพที่โกลาหล แปลกประหลาด และน่าหลงใหลลอยขึ้นข้างๆ คุณ \nคุณมองไปที่—— \n"
  },
  Event_7393_Name = {
    Text = "ชิ้นส่วนดวงจันทร์เงิน"
  },
  Event_7394_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7394_Desc = {
    Text = "คุณยื่นมือไปรับหิมะที่ร่วงลงมาไม่กี่ชิ้น แล้วเพ่งมองดู เม็ดหิมะนั้นละลายกลายเป็นลาวาหลอมละลาย"
  },
  Event_7394_Name = {
    Text = "หยาดน้ำฟ้า"
  },
  Event_7395_ChoiceDesc1 = {
    Text = "【ฉันไม่ได้อยู่บนผิวน้ำ】สุ่มเลือกสิ่งสร้างเงิน 1 ชิ้นอัปเกรดเป็นสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7395_ChoiceDesc2 = {
    Text = "【ก้มลงดู】ได้รับสิ่งประดิษฐ์เงิน 「(RelicConfig.Arg1)」，ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7395_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7395_Desc = {
    Text = "หมอกจางหายไป มือที่ผอมแห้งยื่นออกมาข้างหน้าคุณ \n มันดูเหมือนจะถูกกัดกร่อนจนเหลือแต่กระดูก ผิวมือที่ขรุขระถูกปกคลุมด้วยน้ำดำเหนียว ขณะที่มันมีสร้อยคอและแหวนที่ไหลรินด้วยแสงทองมากมาย \n มันโบกมือเรียกคุณ เหมือนกำลังเชิญชวนให้คุณเข้าใกล้ \n เพียงในเงามืดของวิกฤต เท่านั้นที่ขุมทรัพย์ดูจะส่องประกายอย่างโดดเด่น。"
  },
  Event_7395_Name = {
    Text = "กลับกล้ามปีศาจ"
  },
  Event_7395_Tips1 = {
    Text = "ยังไม่มีสิ่งสร้างเงิน"
  },
  Event_7396_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7396_Desc = {
    Text = "ภาพลวงตาโบกมือให้คุณแล้วหายไป ทิ้งไว้เพียงแค่หิมะที่หนาวเย็นและภูเขาที่สูงตระหง่าน。"
  },
  Event_7396_Name = {
    Text = "ภาพลวงตาของภูเขาไฟ"
  },
  Event_7397_ChoiceDesc1 = {
    Text = "【งานศพของจันทร์เงิน】เลือกสิ่งสร้าง 1 ชิ้นเปลี่ยนเป็นสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」"
  },
  Event_7397_ChoiceDesc2 = {
    Text = "【คำอธิษฐานของดวงจันทร์เงิน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7397_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7397_Desc = {
    Text = "คุณดึงความทรงจำที่แตกสลายบางส่วนขึ้นมาจากกองน้ำดำที่แปดเปื้อน \nผลึกใสแจ๋วมีแสงส่องประกาย เส้นด้ายบางๆ สะบัดอยู่ภายใน ความทรงจำที่เหลืออยู่เหมือนกรวดที่ถูกลมพัดกระจาย ฟุ้งกระจายในอากาศ \nภาพที่โกลาหล แปลกประหลาด และน่าหลงใหลลอยขึ้นข้างๆ คุณ \nคุณมองไปที่——"
  },
  Event_7397_Name = {
    Text = "ชิ้นส่วนดวงจันทร์เงิน"
  },
  Event_7398_ChoiceDesc1 = {
    Text = "【เติมน้ำมัน】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_7398_ChoiceDesc2 = {
    Text = "【ดับมัน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」 ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7398_Desc = {
    Text = "「ฉันคือเงาของพนักงานเสิร์ฟที่ถูกฆ่าตาย ผู้ร้ายคือเปลวไฟสีเขียวที่หลอกลวงนั้น。」\nเปลวไฟที่จางๆ สีแดงอ่อนเคลื่อนไหวไปมา ราวกับกำลังฟ้องร้องคุณ。\n「ฉันเคยมีชีวิตอยู่ที่ข้างทะเลสาบที่สะท้อนดวงจันทร์รูปนูน สว่างสดใส เปล่งประกายเจิดจ้า。」"
  },
  Event_7398_Name = {
    Text = "ไฟสลัว"
  },
  Event_7399_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7399_Desc = {
    Text = "คุณและเงายืนอยู่ใต้โคมไฟถนน ไม่มีใครพูดอะไร \nคืนนี้ไม่มีดวงจันทร์ บ้านทุกหลังเงียบสงัด \nคุณโบกมือให้เงาแล้วหันหลังเดินจากไป。"
  },
  Event_7399_Name = {
    Text = "รูปเงาใต้ไฟถนน"
  },
  Event_7400_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ Arg1 รอยดำ ติดเชื้อ「(Skill.Arg2)」 โปรดเลือกต่อ"
  },
  Event_7400_ChoiceDesc2 = {
    Text = "【ละเว้น】ออก"
  },
  Event_7400_Desc = {
    Text = "อีกาหยุดอยู่ที่หัวเตียง จ้องมองคุณด้วยดวงตาที่แดงก่ำ"
  },
  Event_7400_Name = {
    Text = "โคมไฟหงส์ดำ"
  },
  Event_7401_ChoiceDesc1 = {
    Text = "【บอกว่าตัวเองไม่มีกระเป๋าเงิน】ได้รับการแกะสลักแบบเลือก 1 ใน 3"
  },
  Event_7401_ChoiceDesc2 = {
    Text = "【ทำลายตาข่าย】การ์ดคำสั่งสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7401_Desc = {
    Text = "อวนสีส้มเหลืองลอยอยู่นิ่ง ๆ ในอากาศ รูของมันเบาบาง ห่างไกลจากความประณีตของญาติห่าง ๆ ของแมงมุมที่อาศัยอยู่บนข้างกำแพง\nคุณอดไม่ได้ที่จะยื่นมือสัมผัส อวนที่เปราะบางละลายทันที เสียงหัวเราะของเด็ก ๆ ดังขึ้นที่ข้างหูคุณ\n「สีทอง สีเงิน สีเหลือง สีแดง ทุกกระเป๋าสตางค์เป็นของเรา!」"
  },
  Event_7401_Name = {
    Text = "เครือข่ายหลงทาง"
  },
  Event_7402_ChoiceDesc1 = {
    Text = "【เครื่องโทรเลขซ่อมบำรุง】ติดเชื้อ「(Skill.Arg1)」，การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg2)」"
  },
  Event_7402_ChoiceDesc2 = {
    Text = "【เครื่องโทรเลขฝัง】ติดเชื้อ「(Skill.Arg1)」，การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg2)」"
  },
  Event_7402_ChoiceDesc3 = {
    Text = "【เพิกเฉย】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_7402_Desc = {
    Text = "คุณหลบเข้าไปในรอยแตกของถ้ำที่แคบและยาว เพื่อหลบลมและหิมะ แต่คุณรู้ดีว่าคุณไม่สามารถหยุดอยู่ที่นี่นานเกินไป หากกลุ่มคนในชุดคลุมดำพบที่นี่ คุณจะไม่มีทางหนี\nในมุมของรอยแตก คุณกลับพบว่ามีเครื่องส่งโทรเลขที่ชำรุดอยู่เครื่องหนึ่ง。"
  },
  Event_7402_Name = {
    Text = "ของพื้นเพของผู้ล่วงลับ"
  },
  Event_7403_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7403_Desc = {
    Text = "คุณเคยเห็นภาพเหมือนแบบนี้ในหลายสถานที่ภายในอาณาจักร\n「ราชินี」อยู่กลางภาพ โดดเด่นท่ามกลางดอกกุหลาบสีดำ\nมีเพียงจุดเดียวเท่านั้น—ใบหน้าของเธอถูกขุดออกอย่างไร้ความปราณี ทิ้งไว้เพียงหลุมดำที่ถูกเผาไหม้\nคุณยังไม่สามารถเห็นใบหน้าที่แท้จริงของราชินีได้。"
  },
  Event_7403_Name = {
    Text = "ห้องแสดงภาพเหมือน"
  },
  Event_7404_ChoiceDesc1 = {
    Text = "【ปล่อยเธอ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」、ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7404_ChoiceDesc2 = {
    Text = "【ช่วยเหลือเธอ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7404_ChoiceDesc3 = {
    Text = "【ฉันจะเดินบนเส้นทางของตัวเอง】ได้รับ 50 รอยดำ"
  },
  Event_7404_Desc = {
    Text = "เงาสามคนขวางทางคุณไว้ \n 「คุณปล่อยเธอไปเถอะ」 เงาของคนที่กอดตุ๊กตาหมีที่เปื้อนเมือก D พูดว่า 「เธอแค่ขี้ขลาด ไม่ได้ชั่วร้าย เธอไม่อยากทำร้ายใครเลย」 \n 「คุณช่วยเธอได้」 เงาของคนที่ถือขนมที่บรรจุอย่างสวยงามพูดว่า 「คุณสามารถทำสิ่งที่เธอทำไม่ได้ คุณสามารถยุติทุกอย่างนี้ได้」 \n 「คุณไม่จำเป็นต้องฟังเรา」 เงาของคนที่มือว่างเปล่าพูดว่า 「คุณมีทางของคุณเอง」"
  },
  Event_7404_Name = {
    Text = "ทางแยกเล็กๆ"
  },
  Event_7405_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7405_Desc = {
    Text = "เสียงของดาฟเดลหยุดชั่วขณะหนึ่ง。\n「โอ้ คุณเลือกอันนี้เหรอ? เป็นการเลือกที่ดี ในฐานะรางวัล ฉันจะให้ของขวัญพิเศษกับคุณ」\n「ฉันไม่คุ้นเคยกับเด็กคนนั้น แต่ฉันมีสมมติฐานเกี่ยวกับฟรานซิส ฉันรู้สึกว่าอารมณ์ที่ครอบงำเธอและทำให้เธอมีพละกำลังในการ「มองเห็น」คือความรู้สึกเสียใจอย่างรุนแรง ไม่รู้ว่าเธอจะตัดสินใจอย่างไรกับความรู้สึกเสียใจนี้...」"
  },
  Event_7405_Name = {
    Text = "เวลาเตือน"
  },
  Event_74068_ChoiceDesc1 = {
    Text = "【ใส่ในถังสมอง】นำ「ถังสมองสำรอง」ใส่เข้าไปในกองไพ่ที่จั่ว。"
  },
  Event_74068_Desc = {
    Text = "ภายในประตูโค้งที่มีลวดลายซับซ้อน เงายาวๆ เต้นระบำอยู่บนหลังคาเฉียงของผนังอิฐสีแดง และหน้าบ้านที่มีช่องโหว่ แสวงหาคำตอบของปัญหา\nความธรรมดาหมายถึงความตายใช่ไหม?\nการพอใจในสถานะที่เป็นอยู่หมายถึงการหมดไฟใช่หรือไม่?"
  },
  Event_74068_Name = {
    Text = "ความตระหนักที่ยังไม่สูญเสียไป"
  },
  Event_74069_ChoiceDesc1 = {
    Text = "【ดำเนินการต่อ】เลือกการ์ดคำสั่งมากถึง 2 ใบลบออกจากสำรับ และใส่เข้าไปใน「ถังสมองสำรอง」。"
  },
  Event_74069_Desc = {
    Text = "「ฉันเห็นพวกเขาแล้ว หลายคน หลายความละเมอ ที่มีปัญญา ตื้นเขิน มีเหตุผล และบ้าคลั่ง บางครั้ง เถ้าถ่านก็สามารถให้กำเนิดประกายไฟแห่งความหวังได้」"
  },
  Event_74069_Name = {
    Text = "ความตระหนักที่ยังไม่สูญเสียไป"
  },
  Event_7406_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7406_Desc = {
    Text = "คุณค่อยๆ นำหนูออกจากตาชั่ง มันหายใจอย่างสม่ำเสมอ ร่างกายที่ปกคลุมด้วยขนฟูทำให้ฝ่ามือของคุณรู้สึกอุ่น"
  },
  Event_7406_Name = {
    Text = "ความรู้สึกและเหตุผล"
  },
  Event_7407_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7407_Desc = {
    Text = "เงินใจที่มัวหมองพุ่งออกมาเป็นแสงเจิดจ้า ชั่วพริบตาก็หายไป ในมือเหลือเพียงเถ้าถ่านที่ไม่ต้องสงสัยเลยว่าเป็นดินทรายเท่านั้น\nเงินใจได้หมดสิ้นความรู้ทางจิตวิญญาณครั้งสุดท้าย วิญญาณที่ไม่รู้จักไม่สามารถสร้างร่างกายใหม่ได้ แต่ก่อนที่จะสูญหายไปอย่างสมบูรณ์ มันก็ทิ้งร่องรอยของการมีอยู่ไว้."
  },
  Event_7407_Name = {
    Text = "การพิสูจน์การมีอยู่"
  },
  Event_7408_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7408_Desc = {
    Text = "「ฉันไม่คุ้นเคยกับเด็กคนนั้น แต่ฉันมีสมมติฐานเกี่ยวกับฟรานซิส ฉันรู้สึกว่าอารมณ์ที่ครอบงำเธอและทำให้เธอมีพละกำลังในการ『มองเห็น』คือความรู้สึกเสียใจอย่างรุนแรง ไม่รู้ว่าเธอจะตัดสินใจอย่างไรกับความรู้สึกเสียใจนี้...」"
  },
  Event_7408_Name = {
    Text = "เวลาเตือน"
  },
  Event_7409_ChoiceDesc1 = {
    Text = "【หยิบกระดาษออก】ลบการ์ด 1 ใบ"
  },
  Event_7409_ChoiceDesc2 = {
    Text = "【ตอนนี้ยังไม่ใช่เวลา】ได้รับ「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7409_Desc = {
    Text = "เครื่องพิมพ์ดีดพกพาในกระเป๋าเดินทางเริ่มเคลื่อนไหวเองอย่างกะทันหัน พิมพ์ออกมาเป็นข้อความที่บิดเบี้ยวครึ่งหน้า\n 「คุณได้เห็นพระองค์แล้ว พระองค์อยู่ข้างๆ คุณ เงาที่ถูกมลพิษบ้าคลั่งและคลุ้มคลั่ง...อย่าจ้องมองรูปทรงของพระองค์โดยตรง。」"
  },
  Event_7409_Name = {
    Text = "คำเตือนที่ไม่ได้รับเชิญ"
  },
  Event_7410_ChoiceDesc1 = {
    Text = "【ไปทางซ้าย】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，เพิ่มสถานะ「(Skill.Arg2)」"
  },
  Event_7410_ChoiceDesc2 = {
    Text = "【เดินไปทางขวา】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น ส่งผล「(Skill.Arg1)」"
  },
  Event_7410_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7410_Desc = {
    Text = "คุณดูเหมือนจะเดินเข้าไปในเขาวงกต \n หันไปทางซ้าย ทางขวา แล้วก็ทางซ้ายอีกครั้ง... คุณเริ่มสูญเสียความอดทนไปเรื่อย ๆ จนเมื่อคุณเงยหน้าขึ้น ก็เห็นดวงตาคู่นั้น \n ดวงตาจ้องมองมาที่พวกคุณอย่างสงบและทรงอำนาจ ราวกับว่ามันคือผู้ควบคุมที่นี่。"
  },
  Event_7410_Name = {
    Text = "เขาวงกตของตา"
  },
  Event_7411_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7411_Desc = {
    Text = "คุณออกแรงดึงมือกลับ และได้ยินเสียงกระดูกหักอย่างชัดเจน。\nนี่คือราคาที่ต้องจ่ายที่คุณต้องจ่ายเพื่อความอยากรู้。"
  },
  Event_7411_Name = {
    Text = "แรงบันดาลใจพุ่งพล่าน"
  },
  Event_7412_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7412_Desc = {
    Text = "คุณตรวจสอบกล้องอย่างรอบคอบ หนังและทองคำดำถูกฝังอยู่ในตัวเครื่อง สะท้อนแสงเงางามออกมา\nเลนส์ของมันชี้ไปที่คุณ ราวกับว่ากำลังจ้องมอง อยู่ในขณะที่สอดแนม…"
  },
  Event_7412_Name = {
    Text = "บันทึกความบริสุทธิ์"
  },
  Event_7413_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7413_Desc = {
    Text = "คุณดึงฟิล์มอีกครึ่งหนึ่งออกมาโดยไม่ปราณี มันซ่อนอยู่ในท้องกล้อง ถูกดึงออกมาอย่างกะทันหัน แต่ภาพบนฟิล์มกลับทำให้คุณพูดไม่ออกนาน \n ฟิล์มที่ยังไม่ได้ล้างบันทึกภาพอย่างซื่อสัตย์——คุณล้มลงในโคลนสีดำ.。"
  },
  Event_7413_Name = {
    Text = "บันทึกความบริสุทธิ์"
  },
  Event_74145_ChoiceDesc1 = {
    Text = "【อ่าน】ลบการ์ดคำสั่ง 1 ใบ，ได้รับรอยดำ 25"
  },
  Event_74145_ChoiceDesc2 = {
    Text = "【ดำเนินการต่อ】คัดลอกการ์ดใบหนึ่งจากกองการ์ด และทำให้ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_74145_Desc = {
    Text = "เครื่องพิมพ์พ่นหมึกอย่างรุนแรง\nหมึกสีดำพุ่งออกมาจากหัวฉีดเหมือนวิญญาณล่องลอย กระจายตัวในอากาศ กลายเป็นหมอกดำเข้มข้นที่ทำให้อึดอัด\nบนคีย์บอร์ดดูเหมือนจะซ่อนคำใบ้บางอย่าง รอคอยนิ้วมือบริสุทธิ์สัมผัส。"
  },
  Event_74145_Name = {
    Text = "หมึกผี"
  },
  Event_74146_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74146_Desc = {
    Text = "คุณเอนตัวเข้าไปในตรอกมืด หมอกค่อยๆ กัดกินชายเสื้อ แต่เงานั้นกลับแยกตัวออกเป็นดวงตานับไม่ถ้วนที่อยู่เบื้องหลัง เสียงระฆังที่เป็นสนิมพัดพาไปพร้อมกับสัญญาณแห่งความชื้น \n\n คุณรู้ดีว่า ทุกเส้นทางที่วกวนจะต้องพังทลายลงกลายเป็นรังไหมที่วนเวียน——ก่อนรุ่งอรุณที่เน่าเปื่อย คุณและเงาของตัวเองจะได้พบกันอีกครั้ง。"
  },
  Event_74146_Name = {
    Text = "เถ้าแห่งเวลา"
  },
  Event_74147_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74147_Desc = {
    Text = "คุณวาดเส้นขอบเงียบ ๆ ไว้ที่หน้าอก เพื่ออุทิศคำอธิษฐานที่ไม่มีเสียงให้กับผู้ล่วงลับ \n ในโลกที่ถูกทำลายนี้ มีหลายสิ่งที่คุณไม่สามารถช่วยได้ \n ซากศพเปล่งประกาย และของขวัญที่เจ้าของเคยสะสมไว้อย่างมีค่าเผยให้เห็นบางส่วน。"
  },
  Event_74147_Name = {
    Text = "กระดูกซีดจาง"
  },
  Event_74148_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74148_Desc = {
    Text = "「พ่อพระรู้สึกขอบคุณในความเมตตาของเจ้า พ่อพระจะดูแลพวกเรา และไถ่บาปเราให้พ้นจากภาระแห่งความทุกข์」\n\nภาพลวงตาของเธอค่อยๆ จางหายไป เสียงเพลงศักดิ์สิทธิ์ก็กลายเป็นลมที่ไร้ความปรานีพัดผ่านไป。"
  },
  Event_74148_Name = {
    Text = "การอธิษฐานของออร์แกน"
  },
  Event_74149_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74149_Desc = {
    Text = "คุณผลักกระดูกเปลือยเบาๆ มันจมหายไปในของเหลวสีดำอย่างช้าๆ และหายไปอย่างไร้ร่องรอย \n ขอให้วิญญาณได้พักผ่อนในสุญญตา。"
  },
  Event_74149_Name = {
    Text = "กระดูกซีดจาง"
  },
  Event_7414_ChoiceDesc1 = {
    Text = "【จากไป】คุณเอาชนะคู่ต่อสู้ได้สำเร็จ ไม่มีเหตุการณ์ใดๆ เกิดขึ้นเลย"
  },
  Event_7414_Desc = {
    Text = "「ดูเหมือนว่าเด็กน้อยจะต้องได้รับบทเรียนบ้าง ถึงจะรู้ว่าความลับของผู้หญิงนั้นไม่ควรถามไปง่ายๆ。」\nเมื่อเสียงของดาฟโฟดิลสิ้นสุดลง มอนสเตอร์ขนาดใหญ่ก็ปรากฏตัวอยู่ตรงหน้าคุณ。"
  },
  Event_7414_Name = {
    Text = "เวลาเตือน"
  },
  Event_74150_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74150_Desc = {
    Text = "ในหอระฆังที่หนูตัวน้อยซ่อนตัวอยู่ ไม่ควรมีของเล่นที่ผิดปกติเช่นนี้ เสียงนี้มาจากในหัวของคุณ ความทรงจำของคุณ \n คุณนึกถึงความรู้สึกที่เคยมีเมื่อตอนเป็นสมองในโหล ผ่านกระแสไฟฟ้าที่แปลงจากคลื่นเสียง \n เสียงแปลกๆ นั้นเริ่มกลับมาเป็นปกติและสงบลง กลายเป็นเพลงคลาสสิกที่ไหลลื่นวนเวียนในจิตใจของคุณ。"
  },
  Event_74150_Name = {
    Text = "เสียงแปลกๆ จากหอระฆัง"
  },
  Event_74151_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74151_Desc = {
    Text = "นั่นไม่ใช่แมว... นั่นคือสมาชิกของลัทธิโคมไฟที่น่าสะเทือนขวัญ\nภายใต้ผ้าบางสีดำในเงามืดปรากฏแววแห่งความชังและศัตรู เสียงกระซิบกระซาบเผลอเคาะและก่อกวนจิตสำนึกของคุณ นำมาซึ่งภาพลวงตาอันประหลาดเกินคำบรรยาย。"
  },
  Event_74151_Name = {
    Text = "เสียงกระซิบของแมว"
  },
  Event_74152_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74152_Desc = {
    Text = "พวกเขาจับรองเท้าของคุณ จับข้อเท้าของคุณ พวกเขาโลภ พวกเขาโหยหาคุณ พวกเขาต้องการลากคุณลงไปสู่เหวที่พวกเขาอยู่\nคุณพยายามดิ้นรนอย่างสุดความสามารถ เพื่อรักษาสมดุล ถอยหลังไปสองสามก้าวเพื่อหาทางหลุด\nโดยไม่ตั้งใจ มีบางสิ่งตกลงมา。"
  },
  Event_74152_Name = {
    Text = "ภาพสะท้อนฝันร้าย"
  },
  Event_74153_ChoiceDesc1 = {
    Text = "【หลบหลีก】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_74153_ChoiceDesc2 = {
    Text = "【หยุด】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_74153_Desc = {
    Text = "ภาพที่คุ้นเคยทำให้เส้นประสาทของคุณกระตุกและสั่นสะท้านด้วยความกลัว \n「อีกครั้งหนึ่ง...」\nความฝันร้ายที่โหดร้ายได้มาถึงแล้ว ความรู้สึกไร้เรี่ยวแรงขนาดใหญ่ห่อหุ้มคุณไว้ \nคุณไม่สามารถเขียนใหม่ชะตากรรมของเธอได้จริงๆ หรือ? \nไม่มีเวลาที่จะทำแล้ว ในหัวที่แตกออกของซาร่า ปากขนาดใหญ่ที่เปล่งประกายเงินรอคอยที่จะกัดคุณให้ขาดออกไป กลืนกินและเคี้ยว。"
  },
  Event_74153_Name = {
    Text = "ความฝันร้ายกลับมาอีกครั้ง"
  },
  Event_74154_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74154_Desc = {
    Text = "คุณได้ยินเสียงกระซิบที่ทำให้รู้สึกไม่สบายใจ。\n\n「เรามาจากภูเขาและหนองน้ำบนดาวที่ห่างไกล ร่างกายของเราเป็นไส้ตะเกียงและเชื้อเพลิง เราจะจุดไฟที่มาจากโลกาเพื่อส่องสว่างเส้นทางไปสู่โลกใหม่」"
  },
  Event_74154_Name = {
    Text = "เสียงกระซิบของแมว"
  },
  Event_74155_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74155_Desc = {
    Text = "พระอาทิตย์ตก หอระฆัง นกบิน...\nเด็กหญิงคนนั้นถอดหน้ากากออก สายตาของเธอที่มีสีเทาหม่นทำให้คุณไม่สามารถขยับตัวได้.\nภาพลวงเหมือนกับภาพลวงตา ปรากฏขึ้นและหายไปในทันที แต่ความคิดที่วิตกกังวลกลับไม่สามารถลบเลือนออกไปได้。"
  },
  Event_74155_Name = {
    Text = "หน้ากากตาสีขาว"
  },
  Event_74156_ChoiceDesc1 = {
    Text = "【เก็บ】ได้รับสิ่งประดิษฐ์เงิน เลือก 1 จาก 3"
  },
  Event_74156_ChoiceDesc2 = {
    Text = "【ย้อนคิด】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」ได้รับผลกระทบสองครั้ง「(Skill.Arg3)」"
  },
  Event_74156_Desc = {
    Text = "ในส่วนที่หลอมกร่อนตรงมุม มีผ้าปิดตาสีขาวเล็กๆ วางอยู่ \nความทรงจำถาโถมเข้าสู่หัวใจของคุณ"
  },
  Event_74156_Name = {
    Text = "หน้ากากตาสีขาว"
  },
  Event_74157_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74157_Desc = {
    Text = "ฝ่ามือโปร่งใสเคลื่อนไหวอย่างอิสระบนปุ่มเปียโนขาวดำ เสียงเพลงที่เกิดขึ้นกลับแตกหักเป็นชิ้นเล็กๆ คล้ายกล่องดนตรีที่หลุดคีย์ ทุกโน้ตส่งเสียงโหยหวนอย่างไม่มีความผสมกลมกลืน ราวกับเสียงร้องขอความช่วยเหลือที่ต่อสู้ดิ้นรน\nในที่สุด การบรรเลงก็สิ้นสุดลงอย่างรวดเร็วในคอร์ดที่เต็มไปด้วยความหดหู่\nสิ่งที่ชีวิตไม่เคยได้รับ กลับกลายเป็นความเศร้าโศกที่หลงเหลือไว้ในขณะนี้。"
  },
  Event_74157_Name = {
    Text = "โซนาตาแห่งความเสียใจ"
  },
  Event_74158_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74158_Desc = {
    Text = "「เรียนคุณซาร่า：\nฉันขออนุญาตลาออกจากตำแหน่งพยาบาลช่วยเหลือที่บ้านคนจน。\nฉันไม่เห็นด้วยกับแนวคิดของคุณอีกต่อไปแล้ว การสอนของคุณเป็นสิ่งที่ผิด เด็กๆ ในเขตตะวันออกไม่ควรเติบโตขึ้นภายใต้ร่มเงาของคุณ ไม่ควรเชื่อในความดีงามที่บริสุทธิ์และการให้ที่ไม่มีเงื่อนไข。\nพวกเขาจะต้องออกจากปีกของคุณในสักวันหนึ่ง เพื่อเรียนรู้กฎแห่งการอยู่รอดในเขตตะวันออก。\n\n……」\n\nลายมือที่ตามมาถูกทำให้เปียกชุ่มด้วยของเหลวสีดำ จึงทำให้มองไม่ชัดเจน。"
  },
  Event_74158_Name = {
    Text = "หมึกผี"
  },
  Event_74159_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74159_Desc = {
    Text = "「สิ่งที่ฉันสามารถให้กับเด็ก ๆ ได้มีเพียงหลังคาที่กันฝน และอาหารที่ไม่ทำให้พวกเขาหิวตาย ถ้าไม่ใช่เพราะคุณโรเจอร์สที่มีน้ำใจเรียกหมอมาช่วย ตอนที่พวกเธอป่วยก็ไม่สามารถได้รับยาแม้แต่เม็ดเดียว \nฉันไม่ได้อ่านหนังสือมากมาย สิ่งที่ฉันทำได้คือไม่ให้พวกเขาต้องหนาวตายหรือหิวตายอยู่กลางถนน \nฉันไม่เคยเข้าไปยุ่งเกี่ยวกับเด็ก ๆ ว่าพวกเขาจะเป็นอย่างไร แต่พวกเธอต้องมีชีวิตอยู่ต่อไป \n……」"
  },
  Event_74159_Name = {
    Text = "หมึกผี"
  },
  Event_7415_ChoiceDesc1 = {
    Text = "【ค้นหาแหล่งที่มา】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7415_ChoiceDesc2 = {
    Text = "【ทิ้งข้อความ】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7415_ChoiceDesc3 = {
    Text = "【เปิดจดหมาย】ได้รับ 50 รอยดำ"
  },
  Event_7415_Desc = {
    Text = "จดหมายอีกฉบับตกลงมาที่หน้าคุณ กระดาษเขียนจดหมายที่ถูกฉีกขาดทำให้รู้สึกหนักใจ คุณเปิดกระดาษออก \n「มันกลับมาแล้ว สิ่งที่ฉันเตือนล้วนไม่ใช่คำพูดเล่น ๆ! @4 จากที่นี่เริ่มต้น และจะสิ้นสุดที่นี่」\n「ฉันอยากหนี... ซ่อนตัวอยู่ในตู้ไม้ มือสั่นควบคุมไม่ได้ แต่เสียงของร่างกายที่เหนียวเหนอะนั่นกระแทกพื้นยังคงตามติดมา... ฉันได้ยินชื่อหนึ่ง! มันคือมัน! @5!」"
  },
  Event_7415_Name = {
    Text = "อีกจดหมายขอความช่วยเหลือ"
  },
  Event_74160_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74160_Desc = {
    Text = "「ขอบคุณพ่อพระ พละกำลังแห่งการสร้างสรรค์ของพระองค์จะหล่อหลอมเราขึ้นมาใหม่ นำแสงสว่างและเปลวไฟอันเป็นนิรันดร์มาสู่เรา。\n\nเมื่อฉันไปถึงจุดหมาย จะอวยพรให้คุณต่อหน้าพ่อพระ。」\n\nภาพลวงตาของเธอค่อยๆ จางหายไป เสียงเพลงศักดิ์สิทธิ์ก็กลายเป็นลมที่ไร้ความปราณีพัดผ่านไป。"
  },
  Event_74160_Name = {
    Text = "การอธิษฐานของออร์แกน"
  },
  Event_74161_ChoiceDesc1 = {
    Text = "【การฝังศพ】ฟื้นฟู Arg2 จุดชีวิต[ExDesc1]，เลือกการ์ดคำสั่ง 1 ใบลบออก。"
  },
  Event_74161_ChoiceDesc2 = {
    Text = "【คำอธิษฐาน】ได้รับสิ่งประดิษฐ์ทอง「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_74161_Desc = {
    Text = "ชิ้นหนึ่งของกระดูกซีดขาว ครึ่งหนึ่งจมอยู่ในลาวาหลอมละลายสีดำสนิท"
  },
  Event_74161_Name = {
    Text = "กระดูกซีดจาง"
  },
  Event_74162_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74162_Desc = {
    Text = "คุณก้าวเข้าหมอกนั้นโดยตรง เงาลวงตาพันรอบร่างของคุณเหมือนใยแมงมุม ความรู้สึกเย็นยะเยือกซึมลึกเข้าสู่กระดูกของคุณ \n เสียงกระซิบของพวกเขากลายเป็นชิ้นส่วนความทรงจำ เจาะทะลุเข้าไปในอกของคุณ \n เมื่อคุณเดินผ่านไป เบื้องหลังเหลือเพียงความว่างเปล่า ในขณะที่ข้างหน้า ภายในหมอกหนา ปรากฏเงาที่ไม่ชัดเจนมากขึ้น รอคอยที่จะกลืนกิน。"
  },
  Event_74162_Name = {
    Text = "เถ้าแห่งเวลา"
  },
  Event_74163_ChoiceDesc1 = {
    Text = "【หลีกเลี่ยงภาพลวงตา】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ถูกโจมตีด้วยเอฟเฟกต์「(Skill.Arg2)」"
  },
  Event_74163_ChoiceDesc2 = {
    Text = "【ผ่านภาพลวงตา】ได้รับสิ่งสร้างทองคำ เลือก 1 จาก 3, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_74163_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_74163_Desc = {
    Text = "ฝุ่นควันเหมือนม่านหนักหนา ปกคลุมถนน ทุกย่างก้าวเหมือนเหยียบอยู่บนเถ้าถ่านของเวลา.\nไกลออกไป มีเงาที่เลือนลางสองเงาโผล่ขึ้นในหมอก ดูเหมือนจะเป็นผีจากอดีต กระซิบเล่าเรื่องราวที่ถูกลืมไปนานแล้ว.\nจินตนาการที่หลุดออกจากการควบคุมอีกครั้งได้แปรเปลี่ยนเป็นเงาที่น่าสะพรึงกลัว มันบิดเบือน การแพร่ระบาด เหมือนเป็นลางบอกเหตุจากอนาคต ทำให้คุณรู้สึกหายใจไม่ออก.\nคุณรู้ว่าหนทางข้างหน้าจะยิ่งมืดมน แต่ก้าวเท้าของคุณกลับไม่อาจหยุดลงได้。"
  },
  Event_74163_Name = {
    Text = "เถ้าแห่งเวลา"
  },
  Event_74164_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74164_Desc = {
    Text = "คุณหลบการโจมตีครั้งแรกของซาร่าได้อย่างฉิวเฉียด \n แต่ครั้งต่อไปอาจจะไม่โชคดีขนาดนี้อีกแล้ว"
  },
  Event_74164_Name = {
    Text = "ความฝันร้ายกลับมาอีกครั้ง"
  },
  Event_74165_ChoiceDesc1 = {
    Text = "【ทิศทางการชี้】ได้รับของประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_74165_ChoiceDesc2 = {
    Text = "【อธิษฐานร่วมกัน】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_74165_Desc = {
    Text = "เสียงเปียโนและเสียงออร์แกนผสมผสานกันในสายลมที่มืดมน ราวกับว่าเสียงทำนองที่มีพลังเวทย์มนตร์ล่องลอยอยู่ในตรอกซอกซอยที่ไม่มีผู้คน \nแม่ชีผู้ไม่ปรากฏชื่อกำลังสวดภาวนาในเสียงเพลง \n「การสวดภาวนาอย่างง่ายไม่จำเป็นต้องมีพิธีการที่ยิ่งใหญ่ พ่อพระผู้ยิ่งใหญ่จะหว่านความหวังให้กับเรา เหมือนที่พระองค์เคยมอบการสอนที่มีความเชื่อมั่นให้กับเรา」"
  },
  Event_74165_Name = {
    Text = "การอธิษฐานของออร์แกน"
  },
  Event_74166_ChoiceDesc1 = {
    Text = "【ปัดป้องมอนสเตอร์】เลือกสิ่งสร้าง 1 ชิ้นเปลี่ยนเป็นสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_74166_ChoiceDesc2 = {
    Text = "【เก็บดวงดาว】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_74166_ChoiceDesc3 = {
    Text = "【ละเว้น】ได้รับ 25 รอยดำ"
  },
  Event_74166_Desc = {
    Text = "ม่านน้ำตาของดาวตกตกลงบนหอระฆัง。\nคริสตัลใสหนึ่งเม็ดตกลงใกล้เท้าของคุณ ทำให้เกิดหลุมเล็กๆ ขึ้นมา。\nคุณยังคงติดอยู่ลึกในวงล้อม ร่างหลอมละลายที่มีรูปแบบหลากหลายเหมือนเงาที่บิดเบือน เสียงคำรามและเสียงร้องอย่างโหยหวนไม่ขาดสาย。\nคุณตัดสินใจ——"
  },
  Event_74166_Name = {
    Text = "ดาวตก"
  },
  Event_74167_ChoiceDesc1 = {
    Text = "【ถูตา】ได้รับ 50 รอยดำ"
  },
  Event_74167_ChoiceDesc2 = {
    Text = "【ปิดตา】ได้รับรอยดำ 75 ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_74167_Desc = {
    Text = "ฝูงแมวดำที่น่ารังเกียจรุมล้อมอยู่ข้างหลังจูเลียต กระซิบเสียงที่ไม่รู้จัก ปล่อยความชั่วร้ายที่ซ่อนอยู่เป็นภัยคุกคามออกมา。"
  },
  Event_74167_Name = {
    Text = "เสียงกระซิบของแมว"
  },
  Event_74168_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74168_Desc = {
    Text = "ผ้าราคาถูกที่สัมผัสแล้วมีความหยาบเล็กน้อย แต่ยังถูกทำความสะอาดอย่างพิถีพิถัน.\n เก็บรักษามันไว้ให้ดี รอวันที่จะกลับคืนสู่เจ้าของเดิม."
  },
  Event_74168_Name = {
    Text = "หน้ากากตาสีขาว"
  },
  Event_74169_ChoiceDesc1 = {
    Text = "【รักษาระยะห่าง】ได้รับ 25 รอยดำ"
  },
  Event_74169_ChoiceDesc2 = {
    Text = "【เมตตา】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_74169_Desc = {
    Text = "พวกเขาเข้ามาหาคุณจากใต้ฝ่าเท้าของคุณ \n ในใบหน้าที่พร่ามัวของความทุกข์ทรมาน คุณเห็นเงาของตัวเองถูกดึงเข้าไป \n คุณคิดว่าคุณมีสิทธิ์ในการตัดสินพวกเขาจริงๆ หรือ?"
  },
  Event_74169_Name = {
    Text = "ภาพสะท้อนฝันร้าย"
  },
  Event_7416_ChoiceDesc1 = {
    Text = "【ทิ้งชิ้นส่วนที่แตก】มีสิ่งสร้างพิเศษ ติดเชื้อที่มีการแกะสลัก：「(EnchantConfig.Arg1)」- อาการ：การหลอมกร่อนแห่งบ้าคลั่ง"
  },
  Event_7416_ChoiceDesc2 = {
    Text = "【ชิ้นส่วนเสริม】ไม่มีสิ่งสร้างพิเศษ ติดเชื้อ (Skill.Arg1) ได้รับการติดเชื้อ (Skill.Arg2)"
  },
  Event_7416_Desc = {
    Text = "ร่างกายที่ซีดเผือดค่อยๆ เคลื่อนไหวอยู่ตรงหน้าคุณ เธอโน้มตัวไปข้างหน้า ยื่นแขนที่หักออกมาที่หน้าคุณ น้ำตาปูนปลาสเตอร์สีขาวซีดไหลออกมาจากดวงตาที่หลับตาเพราะความเจ็บปวดของเธอ \n「แค่ขาด... แค่ชิ้นสุดท้าย ฉันก็จะสามารถ...」"
  },
  Event_7416_Name = {
    Text = "เสริมสร้างร่างกายที่เสียหาย"
  },
  Event_74170_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74170_Desc = {
    Text = "คุณต้องพยายามช่วยพวกมันไว้ \n แต่อย่าให้พวกมันทำให้เหมือนกัน"
  },
  Event_74170_Name = {
    Text = "ภาพสะท้อนฝันร้าย"
  },
  Event_74171_ChoiceDesc1 = {
    Text = "【ละสายตา】เพิ่มพลังชีวิตสูงสุด Arg1 หน่วย"
  },
  Event_74171_ChoiceDesc2 = {
    Text = "【จ้องมองต่อไป】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ 1 ใบ「(Skill.Arg2)」"
  },
  Event_74171_Desc = {
    Text = "「จุดจบได้ปรากฏขึ้นแล้ว。」\nหัวใจของคุณบีบรัดแน่นและหดตัวลง。\nน้ำเสียงที่มั่นใจของจูเลียตมีบางสิ่งซ่อนอยู่ซึ่งเกี่ยวข้องกับพลังของการสะกดจิตและการสื่อสารทางใจ。\nจุดประสงค์ของจูเลียตในมิตินี้แตกต่างจากจูเลียตที่คุณเคยรู้จักในอดีตอย่างไร?\nปริศนามากมายและอุปสรรคซับซ้อน。\nคุณเงยหน้าขึ้นมองจูเลียต แต่พบว่าเธอก็กำลังจ้องมองมาที่คุณเช่นกัน。"
  },
  Event_74171_Name = {
    Text = "การมองในวันสุดท้าย"
  },
  Event_74172_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74172_Desc = {
    Text = "คุณยกมือเคาะไปบนคีย์เปียโนที่มองไม่เห็นอย่างเก้ๆ กังๆ\nเสียงคีย์เปียโนดังขึ้นเป็นระยะๆ ทุกโน้ตเหมือนกับหยดน้ำค้างใสสะอาด เทคนิคการเล่นที่ชำนาญและยอดเยี่ยมไม่ได้มาจากปลายนิ้วของคุณ\nในช่วงหนึ่ง คุณเห็นมือที่ยาวและไม่มีรูปแบบปกคลุมอยู่บนหลังมือของคุณ เคลื่อนไหวตามจังหวะของการเล่น\nเวลาเหมือนหยุดนิ่ง จนกระทั่งเสียงดนตรีในท้ายที่สุดค่อยๆ จางหาย\nคุณได้ยินเสียงถอนหายใจอย่างพอใจ。"
  },
  Event_74172_Name = {
    Text = "โซนาตาแห่งความเสียใจ"
  },
  Event_74173_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74173_Desc = {
    Text = "จิตสำนึกที่ถ่ายโอนบ่อยครั้งไม่มั่นคง คุณต้องกำจัดสิ่งรบกวนที่ไร้ความหมาย \n คุณจดจ่ออยู่กับเจนกินที่อยู่ตรงหน้า เสียงเครื่องเล่นแผ่นเสียงจึงค่อยๆ จางหายไปและหายไปในหมอก。"
  },
  Event_74173_Name = {
    Text = "เสียงแปลกๆ จากหอระฆัง"
  },
  Event_74174_ChoiceDesc1 = {
    Text = "【ค้นหาแหล่งเสียง】ได้รับสิ่งประดิษฐ์เงิน \"(RelicConfig.Arg1)\"，ติดเชื้อ \"(Skill.Arg2)\""
  },
  Event_74174_ChoiceDesc2 = {
    Text = "【ความทรงจำ】ร่างกายที่ตื่นขึ้นทั้งหมดฟื้นคืนพลังความคลั่ง 50 หน่วย ได้รับผลกระทบจาก 「(Skill.Arg1)」"
  },
  Event_74174_ChoiceDesc3 = {
    Text = "【เพิกเฉยต่อเสียงรบกวน】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_74174_Desc = {
    Text = "คุณได้ยินเสียงที่เกิดจากการกลายพันธุ์ของเข็มเครื่องเล่นแผ่นเสียง。\nเข็มที่บิดเบือนลากผ่านร่องเกลียวที่ชำรุด ส่งเสียงสั่นสะเทือนที่ทำให้ขนลุกอย่างช้าๆ。"
  },
  Event_74174_Name = {
    Text = "เสียงแปลกๆ จากหอระฆัง"
  },
  Event_74175_ChoiceDesc1 = {
    Text = "【บรรเลงให้เขาฟัง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_74175_ChoiceDesc2 = {
    Text = "【ฟังเสียงดนตรีเครื่องสาย】ทุกครั้งที่มีร่างกายที่ตื่นขึ้นที่มีค่าความคลั่ง 50 หรือมากกว่า จะได้รับ 15 รอยดำ"
  },
  Event_74175_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_74175_Desc = {
    Text = "「ที่รักจอห์น：\n    เมื่อเร็ว ๆ นี้ฉันเพิ่งตระหนักว่า เวลาที่ผ่านไปตั้งแต่ครั้งที่คุณเล่นเปียโนให้เราฟังนั้นได้ผ่านไปหลายปีแล้ว \n    ปีนี้ฉันอายุ 81 ปี ยิ่งอายุมากขึ้น ฉันก็ยิ่งตระหนักถึงความมีค่าของความทรงจำในวัยเยาว์ \n    หากคุณได้รับจดหมายนี้ ก็ขอให้คุณแวะที่หน้าห้องของฉันในลอนดีเนี่ยนเมื่อคุณผ่านมาที่นี่ และมาเล่นเพลงให้ฉันฟังสักเพลงนะ.」"
  },
  Event_74175_Name = {
    Text = "โซนาตาแห่งความเสียใจ"
  },
  Event_74176_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74176_Desc = {
    Text = "ความปรารถนาที่จะมีชีวิตรอดกำลังพลุ่งพล่านอยู่ในอกของคุณ คุณไม่ลังเลที่จะออกคำสั่ง \n รอให้คุณทะลวงออกไป เมื่อหันกลับไปดู ดาวดวงนั้นถูกเมือก D กลืนกินไปแล้ว \n ในเมือก D ที่เคลื่อนไหวอย่างต่อเนื่อง มีเสียงแหลมที่มีระเบียบดังขึ้น \n คุณสัมผัสกับพื้นผิวของเมือก D ดาวที่เน่าเปื่อยดวงหนึ่งตกลงมาอยู่ในฝ่ามือของคุณ。"
  },
  Event_74176_Name = {
    Text = "ดาวตก"
  },
  Event_74177_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74177_Desc = {
    Text = "คุณหยิบดาวดวงนั้นขึ้นมา มันอยู่ในฝ่ามือของคุณแต่กลับสูญเสียแสงสว่างไป。\nความรู้สึกกดดันพุ่งเข้ามาอย่างรวดเร็ว ความหนาวเย็นทำให้หลังของคุณเย็นเฉียบ。\nชีวิตและความตายอยู่ในช่วงเวลาที่รวดเร็ว คุณหลบไปข้างข้างหลีกเลี่ยงการโจมตีที่โหดร้ายได้ทัน แต่ยังคงมีรอยขีดข่วนยาวสองนิ้วอยู่บนแขนของคุณ。"
  },
  Event_74177_Name = {
    Text = "ดาวตก"
  },
  Event_74178_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74178_Desc = {
    Text = "ฟันที่ซ่อนอยู่ในสัมผัสได้ฉีกแขนเสื้อของคุณ เลือดแดงสดไหลออกมาเป็นสายเล็กๆ ตามกระดูกข้อมืออย่างต่อเนื่อง \n คุณไม่สามารถแยกแยะสายตาของซาร่าได้ แต่ศีรษะที่แตกสลายส่งเสียงร้องสะท้อนความเจ็บปวดออกมาอย่างเบาบาง。"
  },
  Event_74178_Name = {
    Text = "ความฝันร้ายกลับมาอีกครั้ง"
  },
  Event_74179_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74179_Desc = {
    Text = "คุณมองไปรอบๆ เดินไปเดินมา เสียงเหมือนหนูที่เล่นซ่อนหาอยู่กับคุณ บางครั้งอยู่ทางซ้าย บางครั้งอยู่ทางขวา บางครั้งไกล บางครั้งใกล้\nคุณวนเวียนไปมา แต่เสียงกลับดังขึ้นเรื่อยๆ เสียงโลหะขูดขีดทำให้คุณรู้สึกไม่สบายใจมากขึ้น\nทันใดนั้นคุณเกิดความคิดขึ้น จึงล้วงกระเป๋าของตน แม้ว่าจะไม่พบแหล่งเสียง แต่คุณก็เก็บได้ขุมทรัพย์เล็กๆ ชิ้นหนึ่ง。"
  },
  Event_74179_Name = {
    Text = "เสียงแปลกๆ จากหอระฆัง"
  },
  Event_7417_ChoiceDesc1 = {
    Text = "【ออกจาก】คุณสูญเสียชีวิต (Arg1) ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7417_Desc = {
    Text = "「เด็กดี แต่ยังไงก็ต้องลงโทษเล็กน้อยนะ。」\nเสียงหัวเราะเบาๆ ของ ดาฟเดล จางหายไปในรอยแยกมิติ。"
  },
  Event_7417_Name = {
    Text = "เวลาเตือน"
  },
  Event_74180_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74180_Desc = {
    Text = "คุณเลื่อนสายตาไปทางอื่น ไม่ให้สบตากับเธอ \nแต่พลังบางอย่างยังคงทำให้หัวใจของคุณเต้นระรัวด้วยความไม่สงบ"
  },
  Event_74180_Name = {
    Text = "การมองในวันสุดท้าย"
  },
  Event_74181_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74181_Desc = {
    Text = "จูเลียตสบตากับคุณ \n ในอีกไม่กี่วินาที เธอเผยรอยยิ้มที่บ้าคลั่งอย่างเต็มที่ ราวกับกำลังเยาะเย้ยความอวดดีและความไม่รู้ของคุณ \n แต่รอยยิ้มดังกล่าวก็หายไปในพริบตา คนอื่นๆ ก็ไม่ได้แสดงปฏิกิริยาใดๆ ... ดูเหมือนว่ามันจะเป็นเพียงภาพหลอนของคุณเท่านั้น。"
  },
  Event_74181_Name = {
    Text = "การมองในวันสุดท้าย"
  },
  Event_7418_ChoiceDesc1 = {
    Text = "【มีภารกิจสิ่งสร้าง 1 ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」】"
  },
  Event_7418_ChoiceDesc2 = {
    Text = "【มีไอเทมโบราณ 2 ชิ้น ได้รับของโบราณทอง「(RelicConfig.Arg1)」】"
  },
  Event_7418_ChoiceDesc3 = {
    Text = "【การ์ดคำสั่งแบบสุ่ม 1 ใบได้รับการแกะสลัก 「(EnchantConfig.Arg1)」】"
  },
  Event_7418_Desc = {
    Text = "เหตุการณ์ 254 (กำลังพัฒนา)，ยังไม่ใช่เวอร์ชันสุดท้าย"
  },
  Event_7418_Name = {
    Text = "เหตุการณ์254（อยู่ในระหว่างการพัฒนา）"
  },
  Event_7419_ChoiceDesc1 = {
    Text = "【ส่งมอบการแกะสลักพิเศษ 1 ใบ สุ่มการ์ดคำสั่ง 1 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」】"
  },
  Event_7419_ChoiceDesc2 = {
    Text = "【ใช้งานการแกะสลักพิเศษ 2 แบบ และการ์ดคำสั่ง 1 ใบแบบสุ่มเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」】"
  },
  Event_7419_ChoiceDesc3 = {
    Text = "【ติดเชื้อ「(Skill.Arg1)」และ「(Skill.Arg2)」，ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg3)」】"
  },
  Event_7419_Desc = {
    Text = "เหตุการณ์ 255 (กำลังพัฒนา), ไม่ใช่ผลสุดท้าย"
  },
  Event_7419_Name = {
    Text = "เหตุการณ์255 (กำลังพัฒนา)"
  },
  Event_7420_ChoiceDesc1 = {
    Text = "【หลีกเลี่ยงผีเสื้อ】ลบการ์ด 2 ใบ"
  },
  Event_7420_ChoiceDesc2 = {
    Text = "【โอบกอดผีเสื้อ】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7420_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ Arg1 รอยดำ"
  },
  Event_7420_Desc = {
    Text = "อีกหนึ่งโค้ง อีกหนึ่งโค้ง ถนนที่ไล่ตามสุนัขแห่งนรกดูเหมือนจะไม่มีที่สิ้นสุด \n ข้อเท้าที่เจ็บปวด สมองที่บวมเป่ง ในความโกลาหลคุณได้เห็นผีเสื้ออีกครั้ง คุณรู้ว่านั่นคือความคิดที่บ้าคลั่ง เสียงพึมพำจากดินแดนลับแล มันบินโผบินออกมาจากทุกทิศทาง。"
  },
  Event_7420_Name = {
    Text = "การพุ่งพล่านของความหลงผิด"
  },
  Event_7421_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7421_Desc = {
    Text = "คุณกดระฆังลมเบา ๆ เสียงระฆังดังขึ้นเบา ๆ ไม่กี่ครั้งก็เข้าสู่ความเงียบ มันได้หายไปแล้ว——จะกลับมาอีกครั้งในฝันร้าย。"
  },
  Event_7421_Name = {
    Text = "ระฆังลมเล็กๆ"
  },
  Event_7422_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7422_Desc = {
    Text = "เสียงระฆังดังขึ้นเบา ๆ ไม่กี่ครั้งก็เข้าสู่ความเงียบ มันได้หายไปแล้ว——จะกลับมาอีกครั้งในฝันร้าย。"
  },
  Event_7422_Name = {
    Text = "ระฆังลมเล็กๆ"
  },
  Event_7423_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7423_Desc = {
    Text = "「ดีมาก คุณระมัดระวัง」\n เสียงที่ห่างไกลดังมาจากระฆังลม\n「การระมัดระวังจะนำมาซึ่งรางวัลเล็กน้อย แต่ก็เพียงแค่นั้น」"
  },
  Event_7423_Name = {
    Text = "ระฆังลมเล็กๆ"
  },
  Event_74245_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_74245_Desc = {
    Text = "กระตุกกระตุก ลูกเต๋าเต้นรำอยู่ในแก้วเขย่าด้วยความตื่นเต้น จนหมดแรง \n\n「คุณแพ้แล้ว แต่ในฐานะค่าตอบแทนที่คุณมาเล่นกับฉัน คุณยังคงสามารถได้รับรางวัล」"
  },
  Event_74245_Name = {
    Text = "ข้อความจาก N"
  },
  Event_74246_ChoiceDesc1 = {
    Text = "【ปิดประตูน้ำ】ติดเชื้อ「(Skill.Arg1)」，การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg2)」"
  },
  Event_74246_ChoiceDesc2 = {
    Text = "【รีบหนี】ส่งผลให้「(Skill.Arg1)」，การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับการแกะสลัก：「(EnchantConfig.Arg2)」"
  },
  Event_74246_ChoiceDesc3 = {
    Text = "【เพิกเฉย】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」"
  },
  Event_74246_Desc = {
    Text = "คุณติดอยู่ลึกในเขาวงกตที่สร้างขึ้นจากไอน้ำและเฟือง ท่อทองเหลืองที่อยู่เหนือศีรษะของคุณบิดเบี้ยวเป็นใยแมงมุม ทุกครั้งที่หายใจจะมีหมอกน้ำมันเหนียวข้นกระจายออกมา \n หน้าปัดนาฬิกาที่ควบคุมไม่ได้เกร็งอยู่บนผนัง เข็มนาฬิกากรีดผ่านขีดบอกเวลาและกระเด็นประกายไฟออกมาเหมือนกับแมลงหิ่งห้อยที่ใกล้ตายในห้องทดลองของวิกตอเรีย รอยเชื่อมที่ยึดด้วยน็อตมีสนิมทองแดงซึมออกมา ราวกับแผลที่เน่าเปื่อยของสัตว์ประหลาดเหล็กนี้ และนาฬิกาพกของคุณก็หยุดเดินไปนานแล้ว — เวลาในที่นี้เป็นเพียงการอธิษฐานของเฟืองที่ขบกัน。"
  },
  Event_74246_Name = {
    Text = "เมืองไอน้ำ"
  },
  Event_74247_ChoiceDesc1 = {
    Text = "【ลองดู】ติดเชื้อ「(Skill.Arg1)」 เข้าสู่เกมเสี่ยงโชค"
  },
  Event_74247_ChoiceDesc2 = {
    Text = "【หรือว่าจะไม่เอาดีกว่า】ได้รับ25รอยดำ"
  },
  Event_74247_Desc = {
    Text = "ในมุมถนนที่เต็มไปด้วยหมอกดำลึกลับ กลิ่นอายที่ทำให้หายใจไม่ออกค่อยๆ แผ่ซ่านออกมา\nในหมอกนั้น ลูกเต๋าคู่หนึ่งซึ่งเก่าแก่และเย็นยะเยือกปรากฏขึ้นอย่างเงียบงัน พื้นผิวเต็มไปด้วยสัญลักษณ์ที่ไม่สามารถถอดรหัสและลวดลายที่น่าขนลุก\nพวกมันนอนนิ่งอยู่บนแผ่นหินที่ลื่นราวกับกำลังรอการเรียกหาที่ไม่ชัดเจนจากบางสิ่ง\n「เจ้ารู้ว่าเราคือใคร จะเสี่ยงแทงพนันดูสักครั้งหรือไม่?」"
  },
  Event_74247_Name = {
    Text = "ข้อความจาก N"
  },
  Event_74248_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74248_Desc = {
    Text = "「ฉันฝันถึงหายนะที่ครอบคลุมทุกสิ่ง ทำให้ความรุ่งเรืองในอดีตจมลง ฉันรู้สึกโกรธกับชีวิต และรู้สึกหมดหวังกับอนาคตอย่างไร้ทางเลือก จิตใจของฉันถูกความกลัวฉีกขาด หวังว่าในช่วงเวลาที่กำลังจะล่มสลายนี้ พวกคุณจะเฝ้าระวัง ไม่ให้ชะตากรรมที่น่าสะพรึงกลัวนี้ปรากฏตัว」"
  },
  Event_74248_Name = {
    Text = "คำพูดสุดท้ายที่ไม่ชัดเจน"
  },
  Event_74249_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74249_Desc = {
    Text = "ควันสีดำสั่นสะเทือนอย่างเศร้าหมอง。\n หลังจากนั้น ลูกเต๋าก็หายไปในพริบตา。\n\n คำถามที่วนเวียนอยู่ในหัวของคุณเหลือเพียงข้อเดียว：\n ลูกเต๋าเหล่านี้ทำจากอะไรจริงๆ กันแน่?"
  },
  Event_74249_Name = {
    Text = "ข้อความจาก N"
  },
  Event_7424_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7424_Desc = {
    Text = "คุณหันไปเห็นรองเท้าหนึ่งคู่ และเงาร่างมนุษย์ที่เบลอ \n ดูเหมือนว่าจะเป็นสุภาพบุรุษหนุ่มคนหนึ่ง \n 「ขอโทษที่รบกวน คุณเห็นรองเท้าหนังออกซ์ฟอร์ดสีดำไหม?」 \n 「ตรงหน้าคุณมีอยู่หนึ่งคู่」 \n 「ไม่ ไม่... นี่เป็นหนังแพะ ไม่ใช่หนังวัว \n ฉันติดอยู่ในพิพิธภัณฑ์หุ่นขี้ผึ้งนี้มาเป็นเวลา 12 ปีแล้ว คงเป็นเพราะรองเท้าผิด...」 \n เสียงพูดพึมพำและค่อยๆ เบาลง。"
  },
  Event_7424_Name = {
    Text = "เสียงเท้า"
  },
  Event_74250_ChoiceDesc1 = {
    Text = "【แยกแยะเสียงของผู้ชาย】สุ่ม 3 การ์ดคำสั่งจากกองการ์ด เลือก 1 ใบแล้วทำการคัดลอก"
  },
  Event_74250_ChoiceDesc2 = {
    Text = "【แยกแยะเสียงผู้หญิง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_74250_ChoiceDesc3 = {
    Text = "【ฟังเสียงผู้สูงอายุให้ออก】ได้รับ 25 รอยดำ"
  },
  Event_74250_Desc = {
    Text = "คุณยืนอยู่คนเดียวในหนองน้ำที่มืดมิด \n ในความพร่ามัว คุณได้ยินเสียงพึมพำที่เคออสสลับกันเหมือนคลื่นทะเลที่พัดมา บางเสียงมาจากคนชราที่อายุยืน บางเสียงมาจากเด็กเล็กที่เริ่มพูด บางเสียงมาจากผู้หญิงที่วิตกกังวล และบางเสียงมาจากผู้ชายที่รู้สึกกลัวอย่างไม่รู้สาเหตุ..."
  },
  Event_74250_Name = {
    Text = "คำพูดสุดท้ายที่ไม่ชัดเจน"
  },
  Event_74251_ChoiceDesc1 = {
    Text = "【เดินหน้า】สุ่มการ์ดคำสั่ง 3 ใบจากสำรับ เลือก 1 ใบเพื่อลบ และรับรอยดำ 75 อัน"
  },
  Event_74251_ChoiceDesc2 = {
    Text = "【พักผ่อน】สุ่มเลือกการ์ดคำสั่ง 3 ใบจากสำรับ，เลือกสำเนาต้นฉบับของการ์ด 1 ใบเข้าสู่สำรับ และได้รับรอยดำ 25 อัน"
  },
  Event_74251_ChoiceDesc3 = {
    Text = "【มองย้อนกลับ】รับมา 50 รอยดำ"
  },
  Event_74251_Desc = {
    Text = "คุณเดินอยู่บนถนนที่ไร้ผู้คน รอยเท้าของคุณทำให้เกิดรอยลึกลงไปในเถ้าถ่าน。\n\nถนนในเมืองเหมือนกับใยแมงมุม คุณคือผีเสื้อที่ถูกมัดไว้。"
  },
  Event_74251_Name = {
    Text = "เมืองมัวหมอง"
  },
  Event_74252_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74252_Desc = {
    Text = "เมื่อประตูไอน้ำปิดลงอย่างรวดเร็ว คุณได้ยินเงาของตัวเองกำลังถูกเกลียวที่ถูกเชื่อมต่อกันอย่างแม่นยำบีบขาดทีละน้อย。"
  },
  Event_74252_Name = {
    Text = "เมืองไอน้ำ"
  },
  Event_74253_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74253_Desc = {
    Text = "ภาพเดิมซ้ำๆ ปรากฏขึ้นใหม่ตรงหน้า คุณไม่สามารถหลบหนีได้"
  },
  Event_74253_Name = {
    Text = "เมืองไอน้ำ"
  },
  Event_74254_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74254_Desc = {
    Text = "เวลาเป็นพิกัดที่ไร้ประโยชน์ คุณหวังเพียงแค่ความจริงเท่านั้น"
  },
  Event_74254_Name = {
    Text = "เมืองไอน้ำ"
  },
  Event_74255_ChoiceDesc1 = {
    Text = "【สามจุด】"
  },
  Event_74255_ChoiceDesc2 = {
    Text = "【หกโมง】"
  },
  Event_74255_ChoiceDesc3 = {
    Text = "【จุดเดียว】"
  },
  Event_74255_Desc = {
    Text = "ใครจะกล้าโยนลูกเต๋าที่หมายถึงความโชคร้ายและความบ้าคลั่งนี้? \nแน่นอนว่าคือคุณ。\nคุณเลือก——"
  },
  Event_74255_Name = {
    Text = "ข้อความจาก N"
  },
  Event_74256_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_74256_Desc = {
    Text = "กลิ้ง กลิ้ง ลูกเต๋าเต้นรำอย่างกระตือรือร้นอยู่ในแก้วเขย่าลูกเต๋าจนหมดแรง。\n\n「คุณแพ้แล้ว แต่ในฐานะค่าตอบแทนที่คุณมาร่วมสนุกกับฉัน คุณยังสามารถได้รับรางวัลอยู่」"
  },
  Event_74256_Name = {
    Text = "ข้อความจาก N"
  },
  Event_74257_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74257_Desc = {
    Text = "เส้นทางที่มาถึงเต็มไปด้วยความมืดมิดและเคออสที่ไม่มีที่สิ้นสุด。\nไม่มีเวลาให้คิดถึงชะตากรรมของตนแล้ว คุณต้องกำจัดความกลัว และถึงจุดหมายของตนก่อนที่การปรากฏตัวจะมาถึง。"
  },
  Event_74257_Name = {
    Text = "เมืองมัวหมอง"
  },
  Event_74258_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74258_Desc = {
    Text = "「เมื่อฉันนั่งอยู่ในเงาของกาลเวลา รู้สึกถึงมือที่เยือกเย็นของความตายค่อยๆ เข้ามาใกล้ โลกภายนอกเริ่มมืดมนมากขึ้น เต็มไปด้วยเสียงกระซิบของหายนะ ฉันหวาดกลัวต่อการพิจารณาคดีที่กำลังจะมาถึง การชำระบัญชีของความโง่เขลาของเรา ถนนเต็มไปด้วยบรรยากาศที่ไม่ดี ฉันกังวลว่าวันพิพากษ์ของเรากำลังจะมาถึง อารยธรรมของเราไม่มั่นคง ราวกับว่ากำลังจะถูกทำลายกลืนกิน ติดอยู่ในความหยิ่งยโสที่โง่เขลาของเราเอง」"
  },
  Event_74258_Name = {
    Text = "คำพูดสุดท้ายที่ไม่ชัดเจน"
  },
  Event_74259_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74259_Desc = {
    Text = "การรอดชีวิตจากความตายถือเป็นเรื่องยาก คุณไม่ควรเรียกร้องมากไปกว่า นี้ \n เงาของซากปรักหักพังและเสาแตกยังคงเรียกหาคุณ。"
  },
  Event_74259_Name = {
    Text = "เมืองมัวหมอง"
  },
  Event_7425_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_7425_Desc = {
    Text = "「แบบนี้เหรอ... น่าสนใจมาก」\nเธอเก็บแบบสอบถามและชี้ไปยังทิศทางที่เด็ก ๆ เดินจากไป คุณรีบจากไปจนแทบไม่ได้ยินเสียงกระซิบที่อยู่ข้างหลัง\n「หวังว่าเราจะแบ่งปันเวลาพบกันอีกครั้ง」"
  },
  Event_7425_Name = {
    Text = "การประเมินทางจิตวิทยา"
  },
  Event_74260_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74260_Desc = {
    Text = "คุณอยู่ภายใต้การควบคุมของพละกำลังมหาศาลหรือชะตากรรมที่แข็งแกร่ง \n การพักผ่อนชั่วครู่ไม่สามารถเปลี่ยนแปลงสถานการณ์นี้ได้ แต่ก็น่าจะให้พลังในการเดินหน้ากับขาที่ยืดออกได้บ้าง。"
  },
  Event_74260_Name = {
    Text = "เมืองมัวหมอง"
  },
  Event_74261_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_74261_Desc = {
    Text = "「……เมืองไม่ใช่ที่หลบภัยที่อบอุ่นอีกต่อไป แต่กลับกลายเป็นสุสานที่ซ่อนเร้น ซึ่งกำเนิดความสยองขวัญและความสิ้นหวัง ความฝันที่เคยมีชีวิตชีวา ตอนนี้เหลือเพียงเศษเสี้ยวของความกลัว ฉันไม่สามารถแกล้งทำเป็นไม่กลัวได้อีกต่อไป โลกเบื้องหน้าดูเหมือนฝันร้ายที่ไม่สามารถตื่นขึ้นมาได้」"
  },
  Event_74261_Name = {
    Text = "คำพูดสุดท้ายที่ไม่ชัดเจน"
  },
  Event_74262_ChoiceDesc1 = {
    Text = "【ออก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_74262_Desc = {
    Text = "กระตุก กระตุก ลูกเต๋าเต้นรำอย่างตื่นเต้นอยู่ในแก้วเขย่าลูกเต๋า จนหมดแรง \n\n「คุณแพ้แล้ว แต่ในฐานะที่มาเล่นสนุกกับฉัน คุณก็ยังสามารถได้รับรางวัล」"
  },
  Event_74262_Name = {
    Text = "ข้อความจาก N"
  },
  Event_7426_ChoiceDesc1 = {
    Text = "【จาก】การ์ดคำสั่งแบบสุ่ม 1 ใบ ได้รับการแกะสลัก：ภาพในกระจก"
  },
  Event_7426_Desc = {
    Text = "「ไม่เป็นไร ฉันได้เห็นคำตอบจากตาของเธอแล้ว ฉันยังมีธุระบางอย่างที่ต้องจัดการ ขอออกไปก่อนนะ เธอก็มีเรื่องต้องทำใช่ไหม? ดูนั่นสิ มีคนมาหาเธอแล้ว」\nเธอหันหลังกลับ เงาของโบสถ์แห่งตะเกียงปรากฏขึ้นที่ปลายถนน。"
  },
  Event_7426_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅴ"
  },
  Event_7427_ChoiceDesc1 = {
    Text = "【ออกจาก】การ์ดคำสั่งแบบสุ่ม 1 ใบได้รับการแกะสลัก: การวางแผน"
  },
  Event_7427_Desc = {
    Text = "「ดูเหมือนว่าเธอยังไม่อยากเปิดใจให้ฉัน ฉันรู้สึกผิดหวัง แต่ไม่เป็นไร ฉันยังคงจะให้คำแนะนำที่อบอุ่นที่สุดแก่เธอ: โบสถ์แห่งตะเกียงมาที่นี่ เพื่อค้นหาอะไรอยู่กันแน่?」\n「โอ้ ดูเหมือนว่าจะมีคนไม่ต้องการให้เราคุยกันแล้ว ดูนั่นสิ มีคนมาหาเธอแล้ว」\nเธอหันหลังกลับ เงาของผู้ศรัทธาแห่งโคมไฟปรากฏขึ้นที่ปลายถนน。"
  },
  Event_7427_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅴ"
  },
  Event_7428_ChoiceDesc1 = {
    Text = "【ออก】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับแรงบันดาลใจจากการแกะสลัก"
  },
  Event_7428_Desc = {
    Text = "「เธอซื่อสัตย์มาก สมควรได้รับรางวัล ดังนั้น ฉันจึงตัดสินใจให้คำแนะนำเล็กน้อยแก่เธอ: ทำไมเธอถึงถูกพระองค์จับตามองเมื่อเธอเพิ่งมาถึงเมืองเล็ก ๆ ของลาอี?」\n「โอ้ ดูเหมือนว่าจะมีคนไม่ต้องการให้เราคุยกันแล้ว ดูนั่นสิ มีคนมาหาเธอแล้ว」\nเธอหันหลังกลับ เงาของผู้ศรัทธาแห่งโคมไฟปรากฏขึ้นที่ปลายถนน。"
  },
  Event_7428_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅴ"
  },
  Event_7429_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7429_Desc = {
    Text = "เสียงรบกวนค่อยๆ สงบลง ฝ่ามือของคุณว่างเปล่า แต่อารมณ์ในขณะนั้นได้ถูกบันทึกไว้โดยกุญแจเงินแล้ว"
  },
  Event_7429_Name = {
    Text = "หนังสือของความว่างเปล่า"
  },
  Event_7430_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7430_Desc = {
    Text = "คุณยื่นมือออกไปในความโกลาหลและคว้าจับสิ่งต่างๆ รอบตัว ในความเคออส มีบางสิ่งที่สัมผัสแปลกประหลาดตกลงมาอยู่ในมือคุณ และค่อยๆ รวมตัวกันเป็นรูปเป็นร่าง。"
  },
  Event_7430_Name = {
    Text = "หนังสือของความว่างเปล่า"
  },
  Event_7431_ChoiceDesc1 = {
    Text = "【จากไป】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7431_Desc = {
    Text = "「คุณเคยได้ยินเกี่ยวกับวิธีการล่าของงูไหม? งูสามารถเลื้อยไปบนพื้นได้เท่านั้น ไม่สามารถวิ่งไล่เหมือนเสือชีตาห์ หรือห้อมล้อมเหยื่อแบบฝูงหมาป่า ในทางกลับกัน งูได้เรียนรู้ที่จะเฝ้ารออย่างเงียบ ๆ。」\n「พวกมันรอช่วงเวลาที่เหยื่อผ่อนคลายความระมัดระวัง จากนั้นจึงจู่โจมทันที กลืนมันลงท้องในครั้งเดียว。」"
  },
  Event_7431_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅲ"
  },
  Event_7432_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7432_Desc = {
    Text = "ดูเหมือนจะถูกกวนใจ ขนที่มันเงาของแมวดำทิ้งความเจ็บแปลบไว้ที่ปลายนิ้วของคุณเพียงเล็กน้อย ก่อนจะหายไปในความหมอกที่ลึกซึ้ง。"
  },
  Event_7432_Name = {
    Text = "ภัยพิบัติของแมวกลางคืน"
  },
  Event_7433_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7433_Desc = {
    Text = "เป็นเพียงแค่คำพูดฝันเฟื่องของพวกสาวกผู้บ้าคลั่งและไร้เหตุผล。"
  },
  Event_7433_Name = {
    Text = "รหัสลับ·ลง"
  },
  Event_7434_ChoiceDesc1 = {
    Text = "【แอบฟังต่อ】ได้รับการแกะสลัก 1 ใน 3"
  },
  Event_7434_ChoiceDesc2 = {
    Text = "【ไอเสียงดัง】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก: 「(EnchantConfig.Arg1)」，และได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_7434_Desc = {
    Text = "รอยแยกที่มุมกำแพงมีรอยแตกหลายเส้น ไหลออกมาเหมือนเส้นเลือด\nพร้อมกับเสียงหวีดเบาๆ คุณได้ยินเสียงต่ำของผู้ชายจากอีกด้าน\n「เขตควินติน 5 เขตเวลลิงตัน 10 เขตนอร์แมน 15……\nวัสดุในเดือนนี้ได้ถูกบรรจุเรียบร้อยแล้ว เตรียมส่งออก หมายเลขสินค้า I-0234……\n……\nนอกจากนี้ ต้องขอบคุณพวกมิซากะ เขตไวท์แชปเปลในขณะนี้อยู่ในสถานะเคอร์ฟิว เราเสียแหล่งวัสดุที่ใหญ่ที่สุดไปแล้ว」"
  },
  Event_7434_Name = {
    Text = "ผนังมีหู"
  },
  Event_7435_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ 20 รอยดำ ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7435_ChoiceDesc2 = {
    Text = "【ไล่ตามเด็กต่อไป】ออก"
  },
  Event_7435_Desc = {
    Text = "ภายใต้การขู่กรรโชกของคุณ อีกาทั้งหมดบินไปในทุกทิศทางอย่างวุ่นวาย ปีกสีดำที่ร่วงหล่นหลอมรวมเป็นเมือก หยดลงกลายเป็นรูปทรงของรอยดำ。"
  },
  Event_7435_Name = {
    Text = "การจ้องมองของนกกาดำ"
  },
  Event_7436_ChoiceDesc1 = {
    Text = "【ยอมแพ้ต่อสู้】ลบการ์ดคำสั่ง 1 ใบ ได้รับ Arg1 รอยดำ"
  },
  Event_7436_ChoiceDesc2 = {
    Text = "【ดึงมือกลับ】"
  },
  Event_7436_Desc = {
    Text = "เครื่องพิมพ์ดีดรุ่นใหม่\nมันมีชุดปุ่มตัวอักษรที่แตกต่างออกไป เหมือนกับกล้องจุลทรรศน์ที่หรูหราและประณีต\nคุณวางมืออย่างอยากรู้อยากเห็น แต่กลับพบว่าพวกมันไม่อยู่ในความควบคุม ขึ้นลงบนแป้นพิมพ์ด้วยความเร็วที่เพิ่มมากขึ้นเรื่อยๆ..."
  },
  Event_7436_Name = {
    Text = "แรงบันดาลใจพุ่งพล่าน"
  },
  Event_7437_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7437_Desc = {
    Text = "ก็แค่สิ่งมีชีวิตที่ดิ้นรนเพื่อเอาตัวรอด หวังหาเพียงไม้ลอยให้หยุดพัก...\nคุณถอนหายใจครั้งหนึ่ง ปล่อยให้ยางดำไหลจากปลายหางของผีเสื้อจนถึงใบหน้า。"
  },
  Event_7437_Name = {
    Text = "ผีเสื้อน้ำดำ"
  },
  Event_7438_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7438_Desc = {
    Text = "คุณรับคำขอติดต่อจากโรงเรียน เสียงที่คุ้นเคยทำให้จิตใจของคุณสงบ คุณรวบรวมกำลังใจและก้าวเดินต่อไป"
  },
  Event_7438_Name = {
    Text = "จุดติดต่อ"
  },
  Event_7439_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7439_Desc = {
    Text = "คุณรับคำขอติดต่อจากโรงเรียน เสียงที่คุ้นเคยทำให้จิตใจของคุณสงบ คุณรวบรวมกำลังใจและก้าวเดินต่อไป"
  },
  Event_7439_Name = {
    Text = "จุดติดต่อ"
  },
  Event_7440_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7440_Desc = {
    Text = "ความสงสัยของคุณตกลงไปในอากาศ ไม่มีใครตอบรับ แสงสีเหลืองอบอุ่นส่องผ่านจากหน้าต่างเข้ามา ราวกับความทรงจำที่อบอุ่น。"
  },
  Event_7440_Name = {
    Text = "ความทรงจำภูเขาไฟ"
  },
  Event_7441_ChoiceDesc1 = {
    Text = "【เก็บ】ได้รับผลกระทบ「(Skill.Arg1)」，ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」"
  },
  Event_7441_ChoiceDesc2 = {
    Text = "【ลังเล】ได้รับ 25 รอยดำ"
  },
  Event_7441_Desc = {
    Text = "ในมุมของซอย มีถังไม้ลอยอยู่ซึ่งมีสิ่งของสีแปลกประหลาดลอยอยู่ การปรากฏตัวที่ผิดปกติราวกับกำลังเตือนคุณว่า 「อย่าแตะต้อง」"
  },
  Event_7441_Name = {
    Text = "วัตถุลอยในถัง"
  },
  Event_7442_ChoiceDesc1 = {
    Text = "【มอบให้เธอเถอะ】ได้รับสิ่งประดิษฐ์เงิน เลือก 1 จาก 3"
  },
  Event_7442_ChoiceDesc2 = {
    Text = "【มีสถานการณ์เล็กน้อย】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」ถูกทำให้ติดเชื้อสองครั้ง「(Skill.Arg3)」"
  },
  Event_7442_Desc = {
    Text = "「นี่คือการติดต่อจากมหาวิทยาลัยมิซากะ ฉันคือเอริกา ตรวจพบการเปลี่ยนแปลงของดัชนีนอร์สที่ผิดปกติในร่างกายที่ปลุกตื่น โลทัน ต้องการสนับสนุนหรือไม่?」"
  },
  Event_7442_Name = {
    Text = "การสื่อสารสนับสนุน"
  },
  Event_7443_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7443_Desc = {
    Text = "คุณยอมทำตามคำปลอบโยนที่ไม่หวังดีข้างหู, เสียงกรีดร้องดุจปลายเข็มบิดตัวแทงเข้าไปในรูหู.\n「หยุด——หยุดเร็ว——ฉันทำตามที่แกบอกแล้ว——หยุดเร็ว——」\nคุณปิดหัวด้วยความเจ็บปวด, แล้วก็ได้ยินเสียงเยาะเย้ยของฝูงอีกา."
  },
  Event_7443_Name = {
    Text = "เพลงของฝูงกา"
  },
  Event_7444_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7444_Desc = {
    Text = "ถูกวางไว้ในตำแหน่งนี้ มีความเป็นไปได้สองประการ: สิ่งที่ถูกมองข้าม หรือสิ่งที่ถูกให้คุณค่า หากเป็นอย่างหลัง ก็ให้คืนแก่เจ้าของเดิมเถอะ。"
  },
  Event_7444_Name = {
    Text = "ใจเงินเหงา"
  },
  Event_7445_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7445_Desc = {
    Text = "ความสุขที่สุดก็คือการไม่รู้อะไรเลย。"
  },
  Event_7445_Name = {
    Text = "มองลับ"
  },
  Event_7446_ChoiceDesc1 = {
    Text = "【สร้างมอนสเตอร์ทั่วไป】"
  },
  Event_7446_ChoiceDesc2 = {
    Text = "【สร้างพื้นที่ว่างเปล่า】"
  },
  Event_7446_ChoiceDesc3 = {
    Text = "【สร้างวอยด์】"
  },
  Event_7446_Desc = {
    Text = "ลองดูสิว่าสร้างอะไรได้บ้าง"
  },
  Event_7446_Name = {
    Text = "【รอการบรรจุ】"
  },
  Event_7447_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7447_Desc = {
    Text = "「ใจเย็นๆ」ราโมน่าตบที่หัวคุณ，「แค่เศษซากจากอดีต ไม่รู้ว่าใครทำหล่นไว้ในทางเดินมิตินี้」\n จริงอยู่ มีความรู้สึกคิดถึงอยู่บ้าง。"
  },
  Event_7447_Name = {
    Text = "เศษความทรงจำ·วิสกี้"
  },
  Event_7448_ChoiceDesc1 = {
    Text = "【รวบรวม】อัปเกรดสิ่งสร้างเงิน 1 ชิ้นเป็นสิ่งสร้างทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7448_ChoiceDesc2 = {
    Text = "【ทิ้งมันทั้งหมด】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」, รับผลกระทบจาก「(Skill.Arg2)」และ「(Skill.Arg3)」"
  },
  Event_7448_ChoiceDesc3 = {
    Text = "【พิจารณาอย่างละเอียด】ได้รับ 25 รอยดำ"
  },
  Event_7448_Desc = {
    Text = "ที่นี่มีแกนเงินที่แตกเป็นชิ้นหลายชิ้น\nมัวหมองและแตกร้าว... เห็นได้ชัดว่าไม่ใช่ของชั้นสูง\nบางทีมันอาจเป็นเหตุผลที่ทำให้หุ่นขี้ผึ้งเหล่านี้ 「มีชีวิตขึ้นมา」\nแม้แต่แกนเงินที่หยาบที่สุด ก็ยังมีโอกาสสร้างปาฏิหาริย์ได้。"
  },
  Event_7448_Name = {
    Text = "วิญญาณที่ถูกผูกมัด"
  },
  Event_7449_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7449_Desc = {
    Text = "คุมได้สละทุกอย่างที่เธอสามารถสละได้แล้ว \n ต่อไปเป็นหน้าที่ของคุณที่จะทำให้การเสียสละของเธอไม่สูญเปล่า。"
  },
  Event_7449_Name = {
    Text = "ความร้อนที่เหลือ"
  },
  Event_7450_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7450_Desc = {
    Text = "ขอให้ลมและหิมะนำพาความสงบนิรันดร์มาสู่พวกท่าน"
  },
  Event_7450_Name = {
    Text = "ของพื้นเพของผู้ล่วงลับ"
  },
  Event_7451_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7451_Desc = {
    Text = "คุณยังคงดูแข็งแกร่ง ในการขับขานยังสามารถติดตามตัวเองได้ \nคุณไม่เชื่อในเสียงพึมพำที่ข้างหู สิ่งที่พึ่งพาได้มีเพียงเหตุผลของมนุษย์ \nแต่…ในวันที่พื้นดินที่คุณพึ่งพา ถูกปกคลุมด้วยน้ำมันดำหนืด วันที่ต้องขุดลูกตาออกมาเป็นสิ่งที่มองเห็น จะเป็นทางเลือกเดียวในช่วงเวลาสิ้นหวังของคุณ。"
  },
  Event_7451_Name = {
    Text = "เพลงของฝูงกา"
  },
  Event_7452_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7452_Desc = {
    Text = "คุมถูกคุณดึงออกไปอย่างกระทันหัน หลีกเลี่ยงการโจมตีได้อย่างเฉียดฉิว เธอพยักหน้าให้คุณเพื่อแสดงความขอบคุณ ก่อนที่จะพุ่งไปยังร่างทดลองอีกครั้ง。"
  },
  Event_7452_Name = {
    Text = "โคลอสเซียม"
  },
  Event_7453_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7453_Desc = {
    Text = "กริ๊งกริ๊ง......\nเหรียญตกลงไปในกระเป๋าสตางค์ ส่งเสียงกังวานใสที่ไพเราะ \nกระเป๋าสตางค์เคี้ยวอย่างพอใจ สุดท้ายก็เรอออกมา \nมันยอมแพ้ต่อความใจกว้างของคุณ และปลดปล่อยการป้องกันทั้งหมดออกจากคุณ \nตอนนี้ มันจะใช้เพื่อคุณ。"
  },
  Event_7453_Name = {
    Text = "กระเป๋าเงินหิวกระหาย"
  },
  Event_7454_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7454_Desc = {
    Text = "เหรียญทองแดงร่วงหล่นลงไปในห้วงลึกที่มองไม่เห็นก้นบึ้ง ไม่มีเสียงใด ๆ เลย \n คุณรออย่างใจเย็นเป็นเวลาห้านาที กระเป๋าสตางค์ออกเสียงคร่ำครวญอย่างเจ็บปวด สุดท้ายก็พ่นของเหลวสีดำข้นออกมา \n นี่คือการประท้วงอย่างเงียบ ๆ ของมัน。"
  },
  Event_7454_Name = {
    Text = "กระเป๋าเงินหิวกระหาย"
  },
  Event_7455_ChoiceDesc1 = {
    Text = "【มองออกไปยังที่ไกล】"
  },
  Event_7455_ChoiceDesc2 = {
    Text = "【ฟังอย่างละเอียด】"
  },
  Event_7455_Desc = {
    Text = "เซเลสเทเขย่าเข็มทิศในมือ เธอไม่ได้พูดอะไร แต่รอบข้างกลับมีเสียงเพลงดังแว่วอยู่。\nเพลงของนักเดินเรือข้ามกาลเวลาและผสมผสานกันที่นี่ เพลงเรือที่โกลาหลแต่มีพลังนำทางคุณ ให้คุณมองไปยังอีกด้านของเรือ。"
  },
  Event_7455_Name = {
    Text = "เพลงเรือ"
  },
  Event_7456_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7456_Desc = {
    Text = "คุณเดินเข้าไปขัดจังหวะการสอนเล็กๆ นี้ \n ตั้งแต่ท่าทางการเล่นเปียโนไปจนถึงทฤษฎีดนตรีพื้นฐาน คุณไม่ลังเลที่จะให้ความคิดเห็นอย่างตรงไปตรงมา \n เสียงดนตรีหยุดลง เด็กชายและครูหันมามองคุณพร้อมกัน พร้อมรอยยิ้มที่แปลกประหลาดเหมือนกัน \n 133，355，244…… \n เสียงเปียโนดังขึ้นอีกครั้ง แต่ก็ยังผิดพลาดอย่างร้ายแรง \n ที่แท้พวกเขาไม่ได้ยินอะไรเลย。"
  },
  Event_7456_Name = {
    Text = "บทเรียนเปียโน"
  },
  Event_7457_ChoiceDesc1 = {
    Text = "【เก็บเข้ากระเป๋า】"
  },
  Event_7457_Desc = {
    Text = "ตราดำที่ค้นพบในดินแดนลับแล สามารถบูชายัญให้กับรอยละลายเพื่อแลกเป็นเรลิกและการแสดงออกทางจิตวิญญาณอื่น ๆ หลังออกจากพื้นที่ปัจจุบันจะค่อยๆ สลายเป็นลาวาสีดำ。"
  },
  Event_7457_Name = {
    Text = "รอยดำ"
  },
  Event_7458_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7458_Desc = {
    Text = "ตอนนี้การหาตัวคนลึกลับคนนั้นสำคัญกว่า รามอน่าคิดเช่นนั้นแล้วรีบเดินจากไป"
  },
  Event_7458_Name = {
    Text = "หูของผู้อื่น"
  },
  Event_7459_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7459_Desc = {
    Text = "ปล่อยจิตสำนึกให้เป็นอิสระ จมลงสู่ทะเลลึกตามเส้นทางของคำอธิษฐาน \n คุณเห็นอาณาจักรทองคำที่จมอยู่ใต้ก้นน้ำ เห็นประติมากรรมที่เป็นอมตะ สุดท้ายเผชิญหน้ากับดวงตาที่กระพริบในที่มืดมิด... \n 「ผู้ที่ยังไม่ไหลเวียนเลือดของพระเจ้า... จงจากไป จงจากไป.」"
  },
  Event_7459_Name = {
    Text = "คำอธิษฐานแห่งความฝัน"
  },
  Event_7460_ChoiceDesc1 = {
    Text = "【ออก】เลือกสิ่งมีชีวิตแห่งคำสาป 1 ตัว ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7460_Desc = {
    Text = "ราโมน่าฟันดาบแทงทะลุลำคอของสิ่งทดลอง คุมโยนสิ่งทดลองที่หมดสัญญาณชีวิตไปแล้วออกไป ก่อนจะวิ่งไปยังเป้าหมายถัดไป。"
  },
  Event_7460_Name = {
    Text = "โคลอสเซียม"
  },
  Event_7461_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7461_Desc = {
    Text = "อีกากัดขนของตัวเอง เหมือนกับมนุษย์ที่กัดกร่อนร่างกายของตนเอง \n ในโลกแห่งความกลัวนี้ เรื่องนี้เกิดขึ้นบ่อยครั้ง คุณไม่สามารถช่วยชีวิตทุกชีวิตได้。"
  },
  Event_7461_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_7462_ChoiceDesc1 = {
    Text = "【ปลอบประโลมคูม】"
  },
  Event_7462_ChoiceDesc2 = {
    Text = "【ช่วยคูมร้อง】"
  },
  Event_7462_Desc = {
    Text = "สัตว์ประหลาดขนาดใหญ่คำรามใส่คนตัวเล็กอย่างสุดกำลัง เพื่อพยายามปลุกเพื่อนเก่า แต่สายเสียงที่ถูกทำลายกลับส่งเสียงต่ำและแปลกประหลาดออกมา。"
  },
  Event_7462_Name = {
    Text = "การเรียกของมิตรภาพ"
  },
  Event_7463_ChoiceDesc1 = {
    Text = "【ออก】ค้นหาไฟส่องสว่าง"
  },
  Event_7463_ChoiceDesc2 = {
    Text = "【บุกเข้าหมอก】เสียชีวิต Arg2 จุด"
  },
  Event_7463_Desc = {
    Text = "ข้างหน้าคือหมอกสีดำหนาแน่น การเข้าไปโดยไม่ระมัดระวังจะนำไปสู่ภัยพิบัติ\nหรืออาจจะถึงเวลาที่คุณควรหาไฟส่องสว่างเพื่อขับไล่หมอกออกไป。"
  },
  Event_7463_Name = {
    Text = "ไม่รู้จัก"
  },
  Event_7464_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7464_Desc = {
    Text = "「กรามที่กรอบแกรบเหมือนคุณเหรอ? ชีวิตนี้ไม่เคยเห็นเลย。」\nคุณปฏิเสธคำขอที่ไม่สุภาพของคุณกราม คุณกรามรู้สึกผิดหวังมาก แต่ก็พยายามรักษามารยาทไว้ได้\nเพื่อขอบคุณที่คุณตั้งใจฟัง เขาได้มอบของขวัญเล็กๆ น้อยๆ ให้คุณ。"
  },
  Event_7464_Name = {
    Text = "เสียงครืดคราด"
  },
  Event_7465_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7465_Desc = {
    Text = "คุณตอบรับคำขอแปลกประหลาดนี้ และพาเจ้าคุณกรามไปด้วย \n มันนอนอยู่ในกระเป๋าของคุณ เสียงครืดคราดไม่หยุดพัก \n ตามการแปลของเพื่อนร่วมทาง มันพูดถึงความรู้สึกขอบคุณ ความคิดถึง และความเสียใจ \n ส่วนทำไมเขาถึงกลายเป็นแบบนี้ คุณกรามไม่ยินดีที่จะพูดมาก แค่บอกว่า \n「คุณรู้ไหม เมื่อคุณจ้องมอง @2 @2 ก็จะมองกลับมาหาคุณเช่นกัน」"
  },
  Event_7465_Name = {
    Text = "เสียงครืดคราด"
  },
  Event_7466_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7466_Desc = {
    Text = "พระองค์ไหลเข้าสู่กระเป๋าของคุณราวกับผ้าไหม เมื่อน้ำหนักเพิ่มขึ้นเล็กน้อย คุณรู้สึกเหมือนได้ยินเสียงขอบคุณเบาๆ เสียงนั้นเงียบหายไปในภายหลัง。"
  },
  Event_7466_Name = {
    Text = "วิญญาณแห่งความวุ่นวาย"
  },
  Event_7467_ChoiceDesc1 = {
    Text = "【เดินหน้า】"
  },
  Event_7467_Desc = {
    Text = "แกร๊ก!  \nคุณเสียบกุญแจเข้าไปในรูล็อคและผลักประตูเปิดเบาๆ  \nทั้งกระบวนการเปิดประตูราบรื่นมาก ทำให้คุณมีความมั่นใจในภารกิจสืบสวนที่กำลังจะมาถึง。"
  },
  Event_7467_Name = {
    Text = "ประตูที่เป็นสนิม"
  },
  Event_7468_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7468_Desc = {
    Text = "เสียงนั้นหัวเราะอย่างหนัก น้ำเหลวใต้ฝ่าเท้าของคุณเกิดเป็นระลอกคลื่น\n「คุณจะเข้าใจในไม่ช้า ว่าไม่มีอะไรที่จำเป็นต้องทำ นอกจากความตาย。」"
  },
  Event_7468_Name = {
    Text = "คุณจะไม่อยากพบเจอ"
  },
  Event_7469_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7469_Desc = {
    Text = "คุณปล่อยความทรงจำนี้ทิ้งไป ดึงจิตสำนึกของตัวเองออกจากความปลอบโยนที่หลอกลวง"
  },
  Event_7469_Name = {
    Text = "จมอยู่ในวันเก่า"
  },
  Event_7470_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7470_Desc = {
    Text = "แค่หลับตาเพียงชั่วครู่เท่านั้น หากไม่มีการปลอบประโลม เธอจะผ่านค่ำคืนที่ยาวนานนี้ไปได้อย่างไร..."
  },
  Event_7470_Name = {
    Text = "จมอยู่ในวันเก่า"
  },
  Event_7471_ChoiceDesc1 = {
    Text = "【หยิบรูปภาพ】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：\"(EnchantConfig.Arg1)\""
  },
  Event_7471_Desc = {
    Text = "นี่คือชุดภาพถ่ายหมู่ \n ผู้คนที่ซบเซานั่งอยู่หลังรั้วเหล็ก หน้าตาเต็มไปด้วยความทุกข์ \n ภาพหนึ่งดึงดูดความสนใจของคุณ นั่นควรจะเป็นผู้หญิงสาวร่างผอม หน้าตาไร้ซึ่งสีหน้า \n สิ่งมีชีวิตที่ดูหมิ่นนั้นกำลังพันรอบตัวเธอเป็นวงๆ \n คุณมองไม่เห็นใบหน้าของเธอ แต่ในจินตนาการของคุณ เธอควรจะไม่มีสีหน้าใดๆ。"
  },
  Event_7471_Name = {
    Text = "บันทึกอย่างซื่อสัตย์"
  },
  Event_7472_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7472_Desc = {
    Text = "นั่นคือซากของนก。"
  },
  Event_7472_Name = {
    Text = "ฝูงอีกาสับสน"
  },
  Event_7473_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7473_Desc = {
    Text = "คุณปฏิเสธคำขอของนักเปียโนอย่างเย็นชา \n นักเปียโนรู้สึกผิดหวังอย่างมาก เขาได้ฉีกหูอีกข้างและโยนมันทั้งหมดออกนอกหน้าต่าง \n 「ยังไงฉันก็ไม่ต้องการมันอยู่ดี」 \n นักเปียโนที่เศร้าหมองหน้าหมองคล้ำ ก้มหน้ากดลงไปบนโน้ตเสียงเศร้าอย่างต่อเนื่อง。"
  },
  Event_7473_Name = {
    Text = "เอียงหูฟัง"
  },
  Event_7474_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7474_Desc = {
    Text = "เสียงร้องไห้ของวิญญาณแห่งความวุ่นวายยิ่งแหลมคมขึ้นเรื่อย ๆ จนในที่สุดกลายเป็นเสียงกรีดร้องที่แหลมและดังสะท้อนไปทั่วร่างกาย \n พระองค์นำการเครื่องบูชาของคุณและความเศร้าที่ไม่สามารถหลุดพ้นได้ จมลงไปในโคลนอีกครั้ง。"
  },
  Event_7474_Name = {
    Text = "วิญญาณแห่งความวุ่นวาย"
  },
  Event_7475_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7475_Desc = {
    Text = "นี่คือทางเดินทางเดียว คุณไม่สามารถกลับไปยังทางเข้าได้。"
  },
  Event_7475_Name = {
    Text = "ทางผ่าน"
  },
  Event_7476_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，รับสถานะ「(Skill.Arg2)」"
  },
  Event_7476_Desc = {
    Text = "「ดังนั้น โปรดหลับตาและตั้งใจฟังเสียงฝีเท้าที่กำลังเข้ามา」 \n คุณปฏิบัติตามคำสั่งและหลับตาลง ในทันที เสียงหายใจแปลกประหลาดของสัตว์ร้ายก็ดังขึ้นข้างหู \n เมื่อคุณเปิดตาอย่างตื่นตระหนก ชายเมื่อครู่ก็หายไปแล้ว。"
  },
  Event_7476_Name = {
    Text = "เพื่อนร่วมทางประหลาด I"
  },
  Event_7477_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7477_Desc = {
    Text = "「น่าเสียดายจริง ๆ」\nเสียงของผู้ชายต่ำลง เขาปรับแว่นตา\n「แต่ถ้าพวกคุณไม่เคยได้ยินเรื่องนี้ แล้วทำไมถึงมาที่นี่ในเวลากลางคืนล่ะ?」\nยังไม่ทันให้พวกคุณตอบ เขาก็หันไปและเดินจากไป。"
  },
  Event_7477_Name = {
    Text = "เพื่อนร่วมทางประหลาด I"
  },
  Event_7478_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7478_Desc = {
    Text = "คุณก้าวไปอย่างมั่นคงและเดินต่อไป \n หนึ่งก้าว สองก้าว สามก้าว…… \n เสียงเท้าด้านหลังค่อยๆ หายเข้าไปในความมืด \n พวกคุณยังจะได้พบกันอีกครั้ง。"
  },
  Event_7478_Name = {
    Text = "รองเท้าออกซฟอร์ด"
  },
  Event_7479_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7479_Desc = {
    Text = "คุณก้มตัวครึ่งหนึ่ง ยื่นถาดบนโต๊ะข้าง ๆ ถือไว้ในมือ เปลี่ยนตัวเองเป็นองครักษ์ของเจ้าหญิงในทันใด\nส่วนใครคือเจ้าหญิงผู้โชคดีคนนั้น—แน่นอนว่าต้องเป็นคู่หูผู้ซื่อสัตย์ของคุณ\n「กล้ารินชาบนใบหน้าฉัน คาบเรียนเดือนหน้าก็อย่าหวังว่าจะได้โน้ตแล้วนะ」\nนี่คือคำเตือนจากเจ้าหญิงถึงคุณ。"
  },
  Event_7479_Name = {
    Text = "ทำให้ของปลอมดูเหมือนจริง"
  },
  Event_7480_ChoiceDesc1 = {
    Text = "【ฟังอย่างเงียบๆ】สุ่มปรับปรุงคุณภาพการแกะสลักของการ์ด 1 ใบ"
  },
  Event_7480_ChoiceDesc2 = {
    Text = "【เธอคือ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7480_Desc = {
    Text = "เสียงร้องของซาร่าดังก้องอยู่ในหัวของคุณ เสียงหนึ่งที่คุ้นเคยอย่างเล็กน้อยไม่รู้มาจากไหน มันกระซิบอย่างอ่อนแรงว่า「พี่สาวซาซา」，「พี่สาวซาซา」。\n「พี่สาวซาซา คุณอยู่ที่ไหน?」"
  },
  Event_7480_Name = {
    Text = "「พี่สาวซาซา」"
  },
  Event_7481_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7481_Desc = {
    Text = "「... ข้ากลับรู้สึกว่าคำพูดของเจ้ามีเหตุผลอยู่บ้าง แต่ความปรารถนาไม่สามารถช่วยแก้ไขร่างหลอมละลายได้ ควรทำสิ่งที่เป็นประโยชน์ดีกว่า」"
  },
  Event_7481_Name = {
    Text = "กฎของโรแกน"
  },
  Event_7482_ChoiceDesc1 = {
    Text = "【ได้รับ 100 รอยดำ】"
  },
  Event_7482_ChoiceDesc2 = {
    Text = "【การ์ดคำสั่งสุ่ม 2 ใบรับตราประทับ：「(EnchantConfig.Arg1)」】"
  },
  Event_7482_Desc = {
    Text = "สิ่งสร้างเกิดจากความรู้ทางจิตวิญญาณที่มั่นคงและหยุดนิ่ง บางที จะนำมาซึ่งเสียงเพลงที่กลมกลืน"
  },
  Event_7482_Name = {
    Text = "เสียงไม่ประสาน"
  },
  Event_7483_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7483_Desc = {
    Text = "「นี่คือชิ้นส่วนความทรงจำของใครบางคนที่เคยเข้าสู่มิตินี้」ราโมน่าตอบกลับ「การเคลื่อนที่ในมิตินั้นพบเจอสถานการณ์แบบนี้ได้ง่าย ระวังอย่าให้สับสนกับความทรงจำของตัวเอง」"
  },
  Event_7483_Name = {
    Text = "เศษความทรงจำ·วิสกี้"
  },
  Event_7484_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7484_Desc = {
    Text = "ตามจังหวะการเต้นของหัวใจ ค้นหาความส่องสว่าง พวกคุณจะไม่แยกจากกัน เช่นเดียวกับที่ไม่มีใครสามารถแยกวันและคืนได้อย่างแม่นยำ。"
  },
  Event_7484_Name = {
    Text = "ห้องหัวใจซ้าย"
  },
  Event_7485_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7485_Desc = {
    Text = "คุณลูบไล้มือที่ไม่อดทนเหล่านี้อย่างต่อเนื่อง พยายามทำให้พวกมันสงบลง \nไม่นานโลกของคุณก็สงบลงอย่างสิ้นเชิง \nความรักมักจะได้รับการตอบแทนเสมอ。"
  },
  Event_7485_Name = {
    Text = "บึงมืด"
  },
  Event_7486_ChoiceDesc1 = {
    Text = "【ดิ้นรน】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」】"
  },
  Event_7486_ChoiceDesc2 = {
    Text = "【ละทิ้ง】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg2)」"
  },
  Event_7486_ChoiceDesc3 = {
    Text = "【คำเตือน】ได้รับ 25 รอยดำ"
  },
  Event_7486_Desc = {
    Text = "ของเหลวที่ขุ่นมัวหลั่งไหลเข้ามาในสมองของคุณ ความรู้สึกของสิ่งแปลกปลอมที่สกปรกนั้นชัดเจนยิ่งนัก \n ของเหลวที่ขุ่นมัวและมีกลิ่นเหม็นซึมซาบและครอบงำความคิดทั้งหมดของคุณ ความเจ็บปวดแผ่ซ่านไปทั่วใบหน้าข้างที่เต็มไปด้วยความกลัว คุณติดอยู่ในวงจรฝันร้ายที่ไม่มีที่สิ้นสุด ยากที่จะหลุดพ้น。"
  },
  Event_7486_Name = {
    Text = "ลูกลูกในกะโหลก"
  },
  Event_7487_ChoiceDesc1 = {
    Text = "【เป็นกระจกพิธีกรรมแห่งเมมฟิส】"
  },
  Event_7487_ChoiceDesc2 = {
    Text = "【เข็มทิศนำทาง】"
  },
  Event_7487_ChoiceDesc3 = {
    Text = "【ฉันไม่ได้ทำอะไรหล่น】"
  },
  Event_7487_Desc = {
    Text = "「ผู้เดินทางข้ามมิติ」\n\nเสียงแก่ๆ ดังขึ้นข้างหู ราวกับมาจากยุคก่อนประวัติศาสตร์ ราวกับข้ามเวลามาหลายพันปี。\n\nในความตึงเครียดสุดขีด คุณได้ยินเสียงนั้นถามคำถามที่คุ้นเคย\n\n「สิ่งที่คุณทำตก มันกลมๆ ที่ทำให้คุณสามารถจั่วไพ่ในตอนเริ่มต้นของรอบคืออะไรกันแน่?」"
  },
  Event_7487_Name = {
    Text = "เสียงจากอีกฟาก"
  },
  Event_7488_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7488_Desc = {
    Text = "「ที่นี่ไม่ใช่สถานีรีไซเคิลนะ」ดอลล์บ่นขณะรับไป「เอาเถอะ ยังพอจะดึงอะไรที่มีประโยชน์ออกมาได้บ้าง」"
  },
  Event_7488_Name = {
    Text = "ป้ายชื่อ"
  },
  Event_7489_ChoiceDesc1 = {
    Text = "การแกะสลักธรรมดาสุ่ม"
  },
  Event_7490_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7490_Desc = {
    Text = "คุณกำลังอ่านกระดาษที่มีรอยเปื้อนและชำรุด 「แฝด」 「การชุ่มชื้น」 「บูชายัญ」 「ไม่มีผล」...\nยังคงเป็นแนวคิดที่แตกกระจายและการเขียนที่ยากต่อการตีความ เพียงสมองที่ปวดตุบๆ เท่านั้นที่สามารถพิสูจน์ได้ว่าคุณเคยอ่านหน้ากระดาษที่ไร้ค่าแผ่นนี้。"
  },
  Event_7490_Name = {
    Text = "รหัสลับ·ลง"
  },
  Event_7491_ChoiceDesc1 = {
    Text = "【คุณยินดีที่จะจ่ายราคาที่ต้องจ่ายใด?】สุ่มเพิ่มระดับคุณภาพการแกะสลักของการ์ด 1 ใบ"
  },
  Event_7491_ChoiceDesc2 = {
    Text = "【เลี้ยงเครื่องดื่มบลัดดี้แมรี่หมดอายุให้พวกเขาสักแก้ว】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7491_Desc = {
    Text = "「ยินดีต้อนรับ แขกผู้มีค่าของฉัน เชิญเลือกได้ตามสบาย ทุกสิ่งที่เห็นนี้ล้วนรอคอยคุณอยู่」\n「เอ่อ ขอโทษครับ คุณคือ... น้องสาวฝาแฝดของคุณนายดาฟโฟดิลใช่ไหมครับ?」\n「ฉันคือคุณนายดาฟโฟดิลเอง ขอถามคุณแขกว่ามาที่นี่ในวันนี้มีธุระอะไร...?」\n「ขอโทษ ขอโทษ คุณมีเสน่ห์มากขึ้นกว่าเดิม ฉันถึงกับไม่รับรู้เลย คุณยังจำได้ไหม? ยี่สิบปีที่แล้ว คุณช่วยไล่คนแปลกหน้าคนหนึ่งออกจากบาร์ของฉัน... เมื่อวานนี้ ความฝันร้ายกลับมาอีกครั้ง มันยึดบาร์ พร้อมกับพี่น้องของมัน กลุ่มใหญ่เลย...」"
  },
  Event_7491_Name = {
    Text = "ชิ้นส่วนแห่งความทรงจำ·ความฝันในอดีตหวนคืน"
  },
  Event_7492_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ 30 รอยดำ ติดเชื้อ(Skill.Arg2) เลือกต่อไป"
  },
  Event_7492_ChoiceDesc2 = {
    Text = "【ไล่ตามเด็กต่อไป】ออก"
  },
  Event_7492_Desc = {
    Text = "อีกาตัวที่สองจากไป หางของมันสะบัดเบาๆ เผยให้เห็นสีขาวเล็กน้อย ราวกับเงาของกระดูก"
  },
  Event_7492_Name = {
    Text = "การจ้องมองของนกกาดำ"
  },
  Event_7493_ChoiceDesc1 = {
    Text = "【ลองดู】ติดเชื้อ「(Skill.Arg1)」 เข้าสู่เกมเสี่ยงโชค"
  },
  Event_7493_ChoiceDesc2 = {
    Text = "【หรือว่าจะไม่เอาดีกว่า】ได้รับ25รอยดำ"
  },
  Event_7493_Desc = {
    Text = "「มาเดิมพันกันไหม? ทายแต้มของเรา! แค่ราคาที่ต้องจ่ายนิดเดียว!」\nลูกเต๋าที่ถูกทิ้งส่งเสียงฮัมที่ดังและวุ่นวาย เหมือนกำลังพูดกับคุณ\n「โยนฉัน! โยนฉัน!」\n「เพียงครั้งเดียว! ครั้งสุดท้าย!」\nโอเค แค่ครั้งเดียว——\nคุณหยิบชิปขึ้นมา คุณตัดสินใจ——"
  },
  Event_7493_Name = {
    Text = "การพนันไม่มีที่สิ้นสุด"
  },
  Event_7494_ChoiceDesc1 = {
    Text = "【ต่อต้านความคิดชั่วร้าย】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7494_ChoiceDesc2 = {
    Text = "【โอบกอดความชั่วร้าย】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7494_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7494_Desc = {
    Text = "ความคิดชั่วร้ายกลายเป็นคมดาบ ราวกับฟันแหลมคม \n พวกมันกัดกร่อนสติที่อ่อนแอลงในดินแดนลับแล กลืนกินเจตนารมณ์ที่เหลืออยู่ ราวกับความชั่วร้ายที่โลกแห่งความเป็นจริงได้กระทำต่อคุณ..."
  },
  Event_7494_Name = {
    Text = "ความคิดที่ไม่มีมูล"
  },
  Event_7495_ChoiceDesc1 = {
    Text = "【ดิ้นรนสุดกำลัง】ลบการ์ดคำสั่ง 1 ใบ ได้รับ Arg1 รอยดำ"
  },
  Event_7495_ChoiceDesc2 = {
    Text = "【จุดไฟใยแมงมุม】คัดลอกการ์ดคำสั่ง 1 ใบ แพร่เชื้อ「(Skill.Arg1)」"
  },
  Event_7495_ChoiceDesc3 = {
    Text = "【รออย่างสงบ】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7495_Desc = {
    Text = "เส้นใยละเอียดพันธนาการคุณเหมือนใยแมงมุม ในขณะนี้ คุณถูกล้อมจับกลายเป็นเหยื่อของดินแดนลับแลแล้ว"
  },
  Event_7495_Name = {
    Text = "ติดอยู่ลึก"
  },
  Event_7496_ChoiceDesc1 = {
    Text = "【ผู้รับ：∞】ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7496_ChoiceDesc2 = {
    Text = "【ผู้รับ：ตัวเอง】ลบการ์ด 1 ใบ"
  },
  Event_7496_ChoiceDesc3 = {
    Text = "【ผู้รับ：อาจารย์】ได้รับ 25 รอยดำ"
  },
  Event_7496_Desc = {
    Text = "พระองค์ได้มอบโอกาสให้กับผู้เดินทางในดินแดนลับแล: โอกาสในการเชื่อมต่อกับสิ่งที่ไม่รู้จัก \nกระดาษที่ขาดวิ่นหลายแผ่น เครื่องพิมพ์ดีดที่ปล่อยหมึกออกมา และผู้รับที่ไม่รู้จักซึ่งมีทิศทางเดียว \nเจตจำนงอาจกำหนดได้ว่าข้อความของคุณจะส่งไปที่ไหน..."
  },
  Event_7496_Name = {
    Text = "การสารภาพเดียวดาย"
  },
  Event_7497_ChoiceDesc1 = {
    Text = "【ยินดีตอบรับ】"
  },
  Event_7497_ChoiceDesc2 = {
    Text = "【ปฏิเสธอย่างเด็ดขาด】"
  },
  Event_7497_Desc = {
    Text = "เสียงกระซิบดังขึ้นในสภาพแวดล้อมที่ว่างเปล่า\n「โอ้ นั่นแหละนักพนันชื่อดังที่พูดอยู่ตลอดว่า จะตายหรือจะชนะ เป็นคนที่ไร้ประโยชน์ คุณควรอยู่ห่างจากเขา」\nเงาที่ดูซูบผอมและเศร้าหมองขว้างเหรียญไปที่คุณ เสียงเหรียญชนกันดังเข้ามาในฝ่ามือของคุณ\n「มาเล่นกันสักเกม」"
  },
  Event_7497_Name = {
    Text = "นักพนันชื่อดัง"
  },
  Event_7498_ChoiceDesc1 = {
    Text = "【พวกเราปลอดภัยดี】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7498_ChoiceDesc2 = {
    Text = "【คุณเป็นใคร?】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7498_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7498_Desc = {
    Text = "เครื่องพิมพ์ดีดพ่นหมึกออกมาอย่างกะทันหัน โดยมีเครื่องหมายตกใจมากมายจนทำให้แสบตา \n「ดอลล์ คุณสบายดีไหม???ทำไมผู้พิทักษ์หายไปแล้วคุณก็หายไปด้วย!!!กรุณาตอบกลับถ้าปลอดภัย!!!ถ้ารอนานกว่านี้วิลเลียมผมจะหลุดหมดแล้ว!!!」"
  },
  Event_7498_Name = {
    Text = "การสื่อสารฉุกเฉิน"
  },
  Event_7499_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7499_Desc = {
    Text = "คุณติดตั้งชิ้นส่วนปูนปลาสเตอร์สุดท้าย เธอระเบิดเสียงหัวเราะที่แหลมคม พร้อมกับควันดำที่พุ่งขึ้นมา รูปร่างที่ลอยอยู่ของเธอค่อยๆ จางหายไปในมุมมองของคุณ。"
  },
  Event_7499_Name = {
    Text = "เสริมสร้างร่างกายที่เสียหาย"
  },
  Event_7500_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7500_Desc = {
    Text = "คุณหยิบกุญแจเงินออกมา ด้วยความเศร้าและความเชื่อมั่น กุมมันไว้ในฝ่ามือ แสงเรืองน้อยๆ คลุมคุณไว้เหมือนหมอกบางๆ \nในความเงียบสงัด มีเพียงเสียงถอนหายใจเหลืออยู่。"
  },
  Event_7500_Name = {
    Text = "ตาที่จ้องมอง"
  },
  Event_7501_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7501_Desc = {
    Text = "สายตาที่เหลืออยู่ยังคงจับจ้องมาที่คุณ เซลล์เลือดและเนื้อใต้ผิวหนังของคุณกำลังตะโกนและหนีอย่างบ้าคลั่ง เส้นเลือดใต้ผิวหนังเคลื่อนไหวเหมือนหนอน\nคุณรู้สึกถึงพละกำลังที่ไหลเวียนอยู่ เกิดการระเบิดในความผิดปกติของร่างกาย。"
  },
  Event_7501_Name = {
    Text = "ตาที่จ้องมอง"
  },
  Event_7502_ChoiceDesc1 = {
    Text = "【หลีกเลี่ยงสายตา】การฟื้นคืนแบบสุ่มของ 1 ร่างกายที่ตื่นขึ้น"
  },
  Event_7502_ChoiceDesc2 = {
    Text = "【จ้องมองตรง】เลือกร่างกายที่ตื่นขึ้น 1 ตน และลดการใช้พลังการคำนวณของบัตรปลุกลง 2 หน่วย ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7502_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7502_Desc = {
    Text = "อุโมงค์มิติที่เชื่อมโยงหมื่นจักรวาล ในทางเดินสูงสุด นับพันดวงตาจ้องมองพวกท่านที่กำลังแอบเข้ามา"
  },
  Event_7502_Name = {
    Text = "การจ้องมองของพระองค์"
  },
  Event_7503_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7503_Desc = {
    Text = "มันยุ่งเหยิงเกินไป มันยุ่งเหยิงเกินไป。\nความคิดทั้งหมดถูกพัดพาไปในชั่วขณะโดยกระแสความคิด ถูกพัดพาไปในกระแสน้ำสู่ที่ห่างไกล。\nในแอ่งน้ำของสมอง เหลือเพียงความสับสนและความเจ็บปวดที่จมลงไปด้วยกัน。"
  },
  Event_7503_Name = {
    Text = "แรงบันดาลใจพุ่งพล่าน"
  },
  Event_7504_ChoiceDesc1 = {
    Text = "【เก็บเข้ากระเป๋า】"
  },
  Event_7504_Desc = {
    Text = "ดูเหมือนว่าในเมือกที่มีการหลอมกร่อนเกินขีดความสามารถจะมีสารบางอย่างซ่อนอยู่... ใช้กุญแจเงินในการสังเกต และเปลี่ยนมันให้กลายเป็นพละกำลังของตนเองเถอะ。"
  },
  Event_7504_Name = {
    Text = "จุดแยก"
  },
  Event_7505_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ 35 รอยดำ ติดเชื้อ「(Skill.Arg2)」 เลือกต่อไป"
  },
  Event_7505_ChoiceDesc2 = {
    Text = "【ไล่ตามเด็กต่อไป】ออก"
  },
  Event_7505_Desc = {
    Text = "อีกาตัวหนึ่งบินจากไป ขนนกสีดำใบหนึ่งลอยลงอย่างช้าๆ"
  },
  Event_7505_Name = {
    Text = "การจ้องมองของนกกาดำ"
  },
  Event_7506_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_7506_Desc = {
    Text = "ที่นี่คือสนามรบของเลือดในเหว การต่อสู้ไม่เพียงแต่ต้องการความกล้าหาญ แต่ยังต้องการปัญญาอีกด้วย \n\nขัดเกลาตาของคุณ สังเกตคู่ต่อสู้ของคุณ คุณไม่จำเป็นต้องเอาชนะพวกเขาทั้งหมด คุณแค่ต้องเอาชนะผู้นำของพวกเขา!"
  },
  Event_7506_Name = {
    Text = "การทดสอบซูรา"
  },
  Event_7507_ChoiceDesc1 = {
    Text = "【เชื่อมต่อ】ฟื้นฟูชีวิต Arg2 หน่วย。"
  },
  Event_7507_Desc = {
    Text = "คุณกำลังสำรวจในหมอก จู่ๆ เข็มกลัดที่หน้าอกก็เปล่งแสงสีเงินอ่อนๆ ใครกันที่เรียกคุณอยู่ปลายสายของเครื่องสื่อสาร?"
  },
  Event_7507_Name = {
    Text = "จุดติดต่อ"
  },
  Event_7508_ChoiceDesc1 = {
    Text = "【ติดตามเขา】"
  },
  Event_7508_ChoiceDesc2 = {
    Text = "【ทักทาย】"
  },
  Event_7508_Desc = {
    Text = "ตุบ ตุบ ตุบ。\nเงาร่างสีขาวเดินไปอย่างช้าๆ ในหมอกหนา ราวกับเรือใบที่แล่นเข้าสู่คืนอันเงียบสงบ。\nจากด้านหลังดูเหมือนว่าจะเป็นเด็กชาย。\nคุณฟังเสียงเท้าที่อ่อนแรงของเขา และตัดสินใจในใจ。"
  },
  Event_7508_Name = {
    Text = "พิธีสุดท้ายⅠ"
  },
  Event_7509_ChoiceDesc1 = {
    Text = "【ยินดีอย่างยิ่งที่จะตกลง】"
  },
  Event_7509_ChoiceDesc2 = {
    Text = "【มีความระมัดระวัง】"
  },
  Event_7509_Desc = {
    Text = "ร่างหลอมละลายกรีดร้องล้มลง คุณรู้สึกประหลาดใจเมื่อพบว่าคลีเมนไทน์ยืนอยู่ข้างหลัง \n「ฉันมาที่นี่เพื่ออำลา」เมื่อเธอเผชิญหน้ากับคำถามของคุณ เธอไม่ตอบกลับ，「เพื่อแสดงความขอบคุณ ฉันสามารถบอกเบาะแสบางอย่างให้คุณได้ แต่……นั่นจะต้องใช้ความเชื่อใจของคุณ \nให้ฉันทำนายให้คุณ คุณจะได้รู้ทุกอย่างที่ฉันรู้」 \nคุณเชื่อใจเธอได้ไหม? \n「ระวังนะ」ราโมน่ากล่าวเตือน，「เธอไม่มีทางไม่มีเจตนาที่ซ่อนเร้น」"
  },
  Event_7509_Name = {
    Text = "การรักษาด้วยการสะกดจิต"
  },
  Event_7510_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_7510_Desc = {
    Text = "คุณตั้งสมาธิ ภาพลวงค่อยๆ จางหายไปเหมือนหมึกน้ำ คุณเดินหน้าต่อไป แต่ไม่สามารถขจัดความหม่นหมองในใจออกไปได้อย่างสิ้นเชิง。"
  },
  Event_7510_Name = {
    Text = "ภาพลวง"
  },
  Event_7511_ChoiceDesc1 = {
    Text = "【สิ่งมีชีวิตที่น่าสงสาร?】"
  },
  Event_7511_ChoiceDesc2 = {
    Text = "【มนุษย์วิวัฒน์?】"
  },
  Event_7511_ChoiceDesc3 = {
    Text = "【คุณเป็นใครกันแน่?】"
  },
  Event_7511_Desc = {
    Text = "ชายที่คุณพบเป็นครั้งที่หก ยืนอยู่บนโครงเหล็กสูง มองลงไปยังโลกา สายลมที่พัดแรงพัดพาเส้นผมยาวของเขาเผยให้เห็นรูปลักษณ์ของงู \n สายตาของเขาจับจ้องมาที่พวกคุณ ก่อนจะหันไปมองยังความมืดในระยะไกล \n 「อ๊ะ นี่มันเป็นสิ่งมีชีวิตที่น่าสงสารเช่นไร \n ความรู้สึกถูกหักหลัง คงหวานชื่นเหมือนมนุษย์ที่<Bold:วิวัฒนาการ>ใช่ไหม」"
  },
  Event_7511_Name = {
    Text = "เพื่อนร่วมทางประหลาด Ⅵ"
  },
  Event_7512_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7512_Desc = {
    Text = "ใครจะไปสนใจฟิล์มม้วนหนึ่งภายใต้สายตาของสุนัขแห่งนรก?"
  },
  Event_7512_Name = {
    Text = "ความทรงจำของแสงและเงา"
  },
  Event_7513_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7513_Desc = {
    Text = "ไม่มอง ไม่พูดถึง ไม่ฟัง หรือแม้กระทั่งอย่าไปคิด——นี่คือทางเลือกของคนฉลาด"
  },
  Event_7513_Name = {
    Text = "รูนแห่งความบ้าคลั่ง"
  },
  Event_7514_ChoiceDesc1 = {
    Text = "【ออกจาก】ลบการ์ด 2 ใบ"
  },
  Event_7514_Desc = {
    Text = "ท่ามกลางเสียงรบกวนรอบตัว คุณได้ยินเสียงกระพือปีกที่แปลกประหลาดอย่างแผ่วเบา กุญแจเงินสั่นสะเทือนที่หน้าอกของคุณอย่างกระทันหัน คุณถูกพละกำลังบางอย่างบังคับให้เงยหน้าขึ้นและเห็นหลุมดำขนาดใหญ่ที่ปรากฏขึ้นในอากาศ \n「น่าเสียดาย น่าเสียดาย แต่ไม่เป็นไร เราจะได้พบกันอีกครั้ง ผมเคารพดวงตาที่ไม่มีตา」"
  },
  Event_7514_Name = {
    Text = "การรักษาด้วยการสะกดจิต"
  },
  Event_7515_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7515_Desc = {
    Text = "คุณสามารถมองข้ามทุกสิ่งรอบตัวได้ แต่ไม่สามารถเพิกเฉยต่อการเต้นของหัวใจ มันเร่งความถี่ในการเต้น กระตุ้นคุณ และยังบ่นคุณอีกด้วย。"
  },
  Event_7515_Name = {
    Text = "ห้องหัวใจซ้าย"
  },
  Event_7516_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7516_Desc = {
    Text = "「ดีแล้ว!!! ผมของพี่วิลเลียมรอดแล้ว!!!」 \nถึงแม้จะเป็นเพียงข้อความตัวอักษร แต่เนื้อหาในโทรเลขกลับทำให้คุณได้ยินเสียงคำรามที่เต็มไปด้วยความตื่นเต้นในจินตนาการ.。"
  },
  Event_7516_Name = {
    Text = "การสื่อสารฉุกเฉิน"
  },
  Event_7517_ChoiceDesc1 = {
    Text = "【บอกความจริงกับเขา】สุ่มปลุกร่างกายที่ตื่นขึ้น 1 ตัว ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7517_ChoiceDesc2 = {
    Text = "【ปกปิดความจริง】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_7517_Desc = {
    Text = "「ช่วยฉันด้วย」\nนักเดินทางที่เศร้าหมองจับมือคุณ เขาได้วนเวียนอยู่ที่นี่มาหลายร้อยปีแล้ว \n「ฉันเป็นทหาร ได้รับคำสั่งไปยังตะวันออกที่ห่างไกลเพื่อปราบปรามพวกนอกรีต \nฉันเดินผ่านป่าอันหนาแน่น ข้ามแม่น้ำ แต่กลับหลงทาง กลับไปยังสถานที่เดิมซ้ำแล้วซ้ำเล่า \nมีบางสิ่งในความมืดที่กำลังมองดูฉัน ฉันมองไม่เห็น แต่ฉันรู้ว่า มันเฝ้ามองฉันอยู่ตลอด \nตอนนี้ฉันแค่ต้องการกลับบ้าน...」\nคุณมองไปที่เงาที่ล่องลอยอยู่เบื้องหลัง มันเริ่มต้นจากความคลุมเครือ ก่อนที่จะค่อยๆ ชัดเจนขึ้น—นั่นคือปากใหญ่ที่อ้ากว้าง รอคอยที่จะลิ้มลองวิญญาณที่หลงทางซึ่งถูกดองไว้มานานถึงร้อยปี。"
  },
  Event_7517_Name = {
    Text = "ผู้กลืนกิน"
  },
  Event_7518_ChoiceDesc1 = {
    Text = "【ดำดิ่งสู่ความมืด】"
  },
  Event_7518_ChoiceDesc2 = {
    Text = "【ลาจาก】"
  },
  Event_7518_Desc = {
    Text = "「เฮลิสต์ เธอจะช่วยฉันในครั้งนี้ใช่ไหม」\nเด็กสาวเดินวนด้วยความกระวนกระวายใจ เธอหันกลับไปมองร่างที่เงียบงันเป็นครั้งคราว\nเธอไม่ได้ตอบรับคำพูดของเด็กสาว แต่เมื่อเด็กสาวแสดงสีหน้ากังวลมากขึ้น ลมอ่อนๆ ได้พัดผ่านผ้าขาวเบาๆ และดันเธอไปยังทิศทางหนึ่ง\n「ฉันจะปกปักษ์เธอ」\nฉันจะปกปักษ์เธอ แม้ว่าในเรื่องของ「การปกปักษ์」ฉันเคยล้มเหลวมาแล้วครั้งหนึ่ง\nแต่ครั้งนี้ ฉันจะไม่ปล่อยให้เธอต้องหลงทางในความมืดเพียงลำพัง。"
  },
  Event_7518_Name = {
    Text = "การคุ้มครองของนักบุญแห่งการเดินเรือ"
  },
  Event_7519_ChoiceDesc1 = {
    Text = "【ออก】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7519_Desc = {
    Text = "เสียงเพลงเหล่านั้นบางเสียงก็เก่าแก่ เก่าแก่จนสูญหายไปก่อนที่น้ำท่วมจะแพร่ระบาด; บางเสียงก็ใหม่มาก ร้องเกี่ยวกับปีใหม่ที่แล้ว ภรรยาไปซื้อถุงมือใหม่ที่ห้างลอนดีเนี่ยน…… หลังจากความโกลาหลที่อารมณ์ทับซ้อนกัน ได้เหลือไว้เพียงช่องว่างในใจ.。"
  },
  Event_7519_Name = {
    Text = "เพลงเรือ"
  },
  Event_7520_ChoiceDesc1 = {
    Text = "【ขับไล่สี】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7520_ChoiceDesc2 = {
    Text = "【โอบกอดสีสัน】เลือก 1 จาก 3 สิ่งสร้างทองคำ ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7520_ChoiceDesc3 = {
    Text = "【หันไปทางอื่น】 ได้รับของโบราณเงิน「(RelicConfig.Arg1)」"
  },
  Event_7520_Desc = {
    Text = "เมอร์ฟี่ติดตามอยู่ข้างหลังไม่ห่าง แต่เมื่อเดินผ่านมุมหนึ่งกลับหยุดนิ่งอยู่กับที่。\nสีสันที่ไหลเวียนอยู่เบื้องหน้าหมุนวน ทำให้เกิดเสียงถอนหายใจในอากาศ。\n「เมอร์ฟี่@1……」\nเป็นวิญญาณของผู้จมน้ำที่ติดอยู่ในโซนาニลหมายเลขหรือ? หรือว่าเป็นญาติสนิทที่ตามมาจากโลกแห่งความตาย?"
  },
  Event_7520_Name = {
    Text = "สีที่ทำให้นึกถึง"
  },
  Event_7521_ChoiceDesc1 = {
    Text = "【ค้นหาต่อ】 เพิ่ม Arg1 คะแนนชีวิต, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7521_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7521_Desc = {
    Text = "เสียงที่คุ้นเคยดังขึ้นข้างหู อบอุ่นและทำให้รู้สึกปลอดภัย เมื่อคุณพยายามตามเสียงไป เสียงนั้นกลับเงียบไปอย่างกระทันหัน。"
  },
  Event_7521_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7522_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7522_Desc = {
    Text = "「นั่นคือทำนองที่ลบหลู่」\n คุณเอามือปิดหูที่เลือดไหลออกมา พร้อมกับมั่นใจอย่างนั้น"
  },
  Event_7522_Name = {
    Text = "ข้อห้ามของเสียง"
  },
  Event_7523_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7523_Desc = {
    Text = "สีสันนั้นบิดเบือนเป็นรูปร่างของมนุษย์สองคนอย่างเลือนลาง แต่พวกเขายืนอยู่ในมุมนี้ไม่เคลื่อนไหว ใช้ความสนใจมอบพรสุดท้ายให้กับพวกคุณ。"
  },
  Event_7523_Name = {
    Text = "สีที่ทำให้นึกถึง"
  },
  Event_7524_ChoiceDesc1 = {
    Text = "【ฟัง】ได้รับสิ่งสร้างทองคำ เลือก 1 จาก 3"
  },
  Event_7524_Desc = {
    Text = "เสียงของดาฟเดลหยุดชั่วขณะหนึ่ง。\n「โอ้ คุณเลือกอันนี้เหรอ? เป็นการเลือกที่ดี ในฐานะรางวัล ฉันจะให้ของขวัญพิเศษกับคุณ」"
  },
  Event_7524_Name = {
    Text = "เวลาเตือน"
  },
  Event_7525_ChoiceDesc1 = {
    Text = "【ยืนยันการสอบถาม】ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7525_ChoiceDesc2 = {
    Text = "【ละทิ้งการสอบถาม】เลือกลบการ์ด 1 ใบ"
  },
  Event_7525_Desc = {
    Text = "「อืม การเลือกที่ฉลาด ในยามที่ศัตรูใหญ่กำลังมาถึง แน่นอนว่าคุณจะต้องอยากรู้จักทั้งตนเองและศัตรู? แต่การรู้ข้อมูลเกี่ยวกับมิติ มากเกินไปอาจรบกวนจิตใจได้นะ?」"
  },
  Event_7525_Name = {
    Text = "เวลาเตือน"
  },
  Event_7526_ChoiceDesc1 = {
    Text = "【ยืนยันการสอบถาม】ทำให้ดาฟเดลโกรธ，เข้าสู่การต่อสู้"
  },
  Event_7526_ChoiceDesc2 = {
    Text = "【เลิกถาม】รับบทลงโทษเล็กน้อย"
  },
  Event_7526_Desc = {
    Text = "「หืม? ในเวลาแบบนี้เธอยังคิดจะตามล่าฉันอยู่อีกเหรอ? เด็กน้อย ความโลภมากเกินไปไม่ดีนะ」"
  },
  Event_7526_Name = {
    Text = "เวลาเตือน"
  },
  Event_7527_ChoiceDesc1 = {
    Text = "【เพ่งมอง】เพิ่ม Arg1 จุดพลังชีวิตสูงสุด"
  },
  Event_7527_ChoiceDesc2 = {
    Text = "【เพิกเฉย】การ์ดคำสั่งสุ่ม 2 ใบรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ 2 ใบ「(Skill.Arg2)」"
  },
  Event_7527_Desc = {
    Text = "พวกคุณไล่ตามเงาของสุนัขแห่งนรก วิ่งไปตามถนนในเมืองเล็กๆ \n ท้องฟ้าเริ่มโปรยปรายหิมะเย็นเฉียบ ลงมาที่แก้มอย่างอ่อนโยน ลงมาที่หน้าอก ปลอบประโลมจิตใจที่ไม่สงบของคุณ。"
  },
  Event_7527_Name = {
    Text = "หยาดน้ำฟ้า"
  },
  Event_7528_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7528_Desc = {
    Text = "คุณโบกแขนทั้งสองข้าง พยายามขับไล่พวกอีกาที่น่ารำคาญเหล่านี้ออกไป \n พวกมันส่งเสียงหัวเราะก๊าก ๆ ราวกับว่ากำลังเยาะเย้ยความโง่เขลาของคุณและความอ่อนแอ \n ไม่ว่าจะอย่างไรก็ตาม ความกล้าหาญของคุณก็ยังทำให้พวกมันประทับใจ คุณได้รับรางวัลที่สมควรได้รับ。"
  },
  Event_7528_Name = {
    Text = "เพลงของฝูงอีกา"
  },
  Event_7529_ChoiceDesc1 = {
    Text = "【เกี่ยวกับลิลลี่】ได้รับสิ่งสร้างเงิน「(RelicConfig.Arg1)」"
  },
  Event_7529_ChoiceDesc2 = {
    Text = "【เกี่ยวกับสุนัขแห่งนรก】ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」，ได้รับการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7529_Desc = {
    Text = "ผ่านประตูที่ไม่มีที่สิ้นสุด จากสถานที่ที่ห่างไกลจนไม่สามารถสัมผัสได้ ได้ยินเสียงของดาฟโฟดิล。\n「นี่คือเวลาเตือนของดาฟโฟดิล。」"
  },
  Event_7529_Name = {
    Text = "เวลาเตือน"
  },
  Event_7530_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7530_Desc = {
    Text = "คุณยังคงดูแข็งแกร่ง ในการขับขานยังสามารถติดตามตัวเองได้ \n คุณไม่เชื่อในเสียงพึมพำที่ข้างหู สิ่งที่คุณพึ่งพามีเพียงเหตุผลของมนุษย์ \n แต่... วันที่พื้นดินที่คุณพึ่งพา ถูกปกคลุมด้วยน้ำดำหนืด การขุดลูกตาออกมาเป็นสิ่งที่ใช้สอดส่อง จะเป็นทางเลือกเดียวในช่วงสุดท้ายของคุณ。"
  },
  Event_7530_Name = {
    Text = "เพลงของฝูงอีกา"
  },
  Event_7531_ChoiceDesc1 = {
    Text = "【แหล่งที่มาของสุนัขแห่งนรก】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7531_ChoiceDesc2 = {
    Text = "【การต่อสู้】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7531_Desc = {
    Text = "รูปร่างของสุนัขแห่งนรกกำลังเปลี่ยนแปลง。\nร่างกายของมันเชื่อมต่อกับรอยแยกของผนัง เผยให้เห็นภาพลวงที่แปลกประหลาด。"
  },
  Event_7531_Name = {
    Text = "จากมุม"
  },
  Event_7532_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7532_Desc = {
    Text = "「เหมียว, เหมียวเหมียว, เหมียวเหมียวเหมียว……」\nคุณขยับเสียงให้ดูอ่อนแอและไม่มีอันตราย.\n「เหมียว! เหมียวเหมียว! เหมียวเหมียวเหมียว!」\nฝูงแมวดูเหมือนจะรับความปรารถนาดีของคุณและตอบกลับด้วยเสียงร้องที่ดังสนั่น. เสียงของพวกคุณสลับกันไปมา ไม่หยุดหย่อนตลอดวันและคืน จนทำให้จันทร์หลบไปอยู่ในเมฆ.。"
  },
  Event_7532_Name = {
    Text = "เมืองแมว"
  },
  Event_7533_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7533_Desc = {
    Text = "ก็แค่สิ่งมีชีวิตที่ดิ้นรนเพื่อเอาตัวรอด หวังหาเพียงไม้ลอยให้หยุดพัก...\nคุณถอนหายใจครั้งหนึ่ง ปล่อยให้ยางดำจากปลายหางของผีเสื้อไหลลงมาถึงใบหน้า。"
  },
  Event_7533_Name = {
    Text = "ผีเสื้อน้ำดำ"
  },
  Event_7534_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7534_Desc = {
    Text = "คุณใช้แรงทั้งหมดที่มีจนกระทั่งห่างจากกลุ่มแมวออกไปไกลๆ \n เมื่อหันกลับไปดู แมวต่างก็กลับไปอยู่ที่เดิมของมันแล้ว บางตัวกำลังเลียขน บางตัวกำลังงีบหลับ และบางตัวก็กำลังต่อสู้กัน... \n พูดตามตรง พวกมันไม่สนใจมนุษย์เลย。"
  },
  Event_7534_Name = {
    Text = "เมืองแมว"
  },
  Event_7535_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7535_Desc = {
    Text = "คุณโยนชิ้นเนื้อที่เหลืออยู่ในมือไปยังกลุ่มแมว \n กลุ่มแมวพุ่งเข้ามาเหมือนคลื่นสีดำ พวกมันกัดชิ้นเนื้ออย่างบ้าคลั่งแล้วก็แตกกระจายอย่างรวดเร็ว \n โชคร้ายที่นี่คือชิ้นเนื้อที่หมดอายุ มันสามารถทำให้ท้องที่แห้งเหี่ยวอิ่ม แต่ก็ไม่ค่อยจะทำให้รู้สึกพอใจ。"
  },
  Event_7535_Name = {
    Text = "เมืองแมว"
  },
  Event_7536_ChoiceDesc1 = {
    Text = "【จ้องตา】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7536_ChoiceDesc2 = {
    Text = "【ยอมละทิ้งการต่อสู้】สุ่มการตื่นรู้ 2 ร่างกายที่ตื่นขึ้น ติดเชื้อสองครั้ง「(Skill.Arg1)」"
  },
  Event_7536_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7536_Desc = {
    Text = "ดวงตานับไม่ถ้วนล้อมรอบคุณและกระซิบข้างหู \n「เราเดินทาง เราหยุด เราเดินอย่างมั่นใจผ่านไปนับหมื่นปีหรือแม้กระทั่งนานกว่านั้น \nเมื่อดวงอาทิตย์ค่อยๆ มืดลงในสายตาที่จ้องมอง เมื่อชีวิตบนโลกเก่าถูกน้ำท่วมกลืนกิน \nเราได้ถูกดึงดูดโดยความลึกลับของจักรวาลอย่างลึกซึ้ง。」"
  },
  Event_7536_Name = {Text = "ตา"},
  Event_7537_ChoiceDesc1 = {
    Text = "【รู้สึกหวาดกลัว】การตื่นรู้แบบสุ่มในผู้ตื่น 1 คน"
  },
  Event_7537_ChoiceDesc2 = {
    Text = "【รู้สึกพอใจ】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น และลดการใช้แต้มอริธเมทิกาของการ์ดการตื่นรู้ลง 2 หน่วย ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7537_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7537_Desc = {
    Text = "คุณเคยเห็นท้องฟ้าที่ไม่มีจันทราและดาวนับไม่ถ้วน ท้องฟ้าสูงเต็มไปด้วยรูม่านตาขนาดใหญ่จำนวนมาก \n ราวกับว่าถ้าคุณยื่นมือออกไป คุณจะสามารถบิดมันออกมาได้ และทำให้เลือดและเนื้อกระจายออกไป \n แต่เมื่อคุณเปิดนิ้วทั้งห้า สถานที่ที่คุณสัมผัสกลับว่างเปล่า \n ดวงตาของชะตากรรมจ้องมองคุณอย่างไม่กระพริบ พวกเขาได้หยิบเม็ดทรายที่ใสสะอาดมาจากจักรวาลที่เต็มไปด้วยเคออส。"
  },
  Event_7537_Name = {
    Text = "ตาโดม"
  },
  Event_7538_ChoiceDesc1 = {
    Text = "【ปล่อยมือที่ปิดหูลง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_7538_ChoiceDesc2 = {
    Text = "【ยังคงเอามือปิดหูไว้】ได้รับ 75 รอยดำ, ถูกโจมตีด้วย「(Skill.Arg2)」"
  },
  Event_7538_Desc = {
    Text = "แผดเสียงร่ำร้อง เสียงแผดร้องที่ไม่มีที่สิ้นสุด——\nนักขับร้องอีกาสวมขนสีดำเงางาม ปากแหลมของมันมีแสงเย็นแข็งแกร่งส่องประกาย เสียงคร่ำครวญที่ดังสนั่นหลายครั้งทำให้แก้วหูของคุณแตกสลาย\nปล่อยมือที่ปิดหูของคุณเถอะ!\nฝูงอีกาที่ส่งเสียงร้องในยามค่ำคืนต้องการดื่มด่ำกับร่างที่หดตัวของคุณ ซึ่งเต็มไปด้วยความสั่นสะเทือนที่ยังไม่ได้ผ่านการกลั่นกรอง。"
  },
  Event_7538_Name = {
    Text = "เพลงของฝูงกา"
  },
  Event_7539_ChoiceDesc1 = {
    Text = "【เลียนแบบเสียงแมว】ได้รับ 50 รอยดำ"
  },
  Event_7539_ChoiceDesc2 = {
    Text = "【ให้อาหาร】ได้คะแนน 75 รอยดำ, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7539_Desc = {
    Text = "คุณหลงเข้าไปในอาณาเขตของแมวดำ \n ดวงตานับไม่ถ้วนเปิดขึ้นในความมืดอย่างรวดเร็ว พร้อมกับการสำรวจ การตรวจสอบ และการระมัดระวัง... แต่ไม่มีความปรานีเลย \n สีเขียวอ่อน สีเหลืองอำพัน สีนกยูง... \n คุณเหมือนตกอยู่ในทะเลของอัญมณีที่เปล่งประกาย \n เพื่อหลบหนี คุณ——"
  },
  Event_7539_Name = {
    Text = "เมืองแมว"
  },
  Event_7540_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7540_Desc = {
    Text = "คุณสังเกตเห็นมือที่แตกต่างจากคนอื่น มันนุ่มนวลและขาวผ่อง แสดงความสงบตลอดเวลา \nที่สำคัญกว่านั้น—คุณจำได้ว่ามือนั้นเป็นมือของคุณเอง \nคุณตัดสินใจทันที บิดมันอย่างแรงจนขาด \nเสียงแผดร้องอันเจ็บปวดดังเข้าหูคุณ ในที่สุดหนองน้ำก็หายไป。"
  },
  Event_7540_Name = {
    Text = "บึงมืด"
  },
  Event_7541_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7541_Desc = {
    Text = "「การตัดสินใจที่ชาญฉลาด」 เงาของคนที่มือเปล่าพูดว่า 「ทางเลือกที่ผ่านการพิสูจน์แล้วมีจุดจบที่กำหนดไว้ ในขณะที่การกระทำที่ไม่รู้จักจะนำไปสู่อนาคตใหม่」\n ความหวังเล็กน้อยค่อยๆ ปกคลุมคุณอย่างอ่อนโยน เงานั้นจางหายไป คุณกุมหัวใจของตัวเอง ไม่รู้ว่าเมื่อกี้เป็นภาพลวงตาหรือเป็นภาพหลอนที่เกิดจากความกดดันทางจิตใจ。"
  },
  Event_7541_Name = {
    Text = "ทางแยกเล็กๆ"
  },
  Event_7542_ChoiceDesc1 = {
    Text = "【ชมมัน】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7542_ChoiceDesc2 = {
    Text = "【เยาะเย้ยมัน】ติดเชื้อ「(Skill.Arg1)」，การแกะสลักใหม่，ทำได้มากที่สุด 2 ครั้ง"
  },
  Event_7542_Desc = {
    Text = "สมองพูดว่า: โซ่ตรวนขังสมองส่วนหน้า สมองกลาง และเปลือกสมองของฉัน แต่ไม่สามารถผูกมัดเซลล์เล็ก ๆ ที่แสวงหาความจริงมากกว่า 10,000 ล้านเซลล์ได้เลย \n คุณพูดว่า: ใครทำให้คุณติดอยู่ที่นี่? ร่างกายของคุณล่ะ? \n สมองพูดว่า: ร่างกาย? อย่ามาขำกันเลย ในอดีตพวกเขาเรียกฉันว่า 「จอห์นนี่คนขายหมู」 \n ตอนที่มีร่างกาย ฉันแม้แต่การบวกและลบในสิบก็ยังคิดไม่ออก \n แต่เมื่อผู้ดูแลคัดกรองร่างกายที่เกินจำเป็นออกไป ดูสิว่าฉันกลายเป็นอะไร! นักฟิสิกส์ นักปรัชญา และกวีสมัครเล่น。"
  },
  Event_7542_Name = {
    Text = "สมองปรัชญา"
  },
  Event_7543_ChoiceDesc1 = {
    Text = "【พิสูจน์ข้อความคาดการณ์ของโกลด์บาค】ได้รับสิ่งสร้างเงิน 「(RelicConfig.Arg1)」"
  },
  Event_7543_ChoiceDesc2 = {
    Text = "【จุดสิ้นสุดของการเดินทาง】การ์ดแบบสุ่ม 1 ใบได้รับการแกะสลัก : 「(EnchantConfig.Arg1)」"
  },
  Event_7543_ChoiceDesc3 = {
    Text = "【ปฏิเสธคำถาม】ได้รับ 50 รอยดำ"
  },
  Event_7543_Desc = {
    Text = "เมื่อคุณหยิบบอร์ดสื่อสารวิญญาณ เสียงของสตรีสาวก็ดังเข้ามาในสมองของคุณ \n「ถามฉันได้เลย ฉันรู้ทุกอย่าง」\n「จากคำตอบของฉัน คุณจะได้รับของขวัญจากชะตากรรม」"
  },
  Event_7543_Name = {
    Text = "บอร์ดสื่อสารวิญญาณ"
  },
  Event_7544_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7544_Desc = {
    Text = "คุณกำลังอ่านกระดาษที่มีรอยเปื้อนและชำรุด ประโยคที่แตกกระจายไหลออกจากปากของคุณ คำศัพท์เช่น「บรรพบุรุษ」 「บุตรศักดิ์สิทธิ์」 「ความตายอันเป็นนิรันดร์」 「ความทรงจำที่ยาวนาน」กำลังชะล้างในสมองของคุณ กระตุ้นเส้นประสาทที่บอบบางและไวต่อความรู้สึกจากฝันร้ายอยู่แล้ว。"
  },
  Event_7544_Name = {
    Text = "รหัสลับ·บน"
  },
  Event_7545_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7545_Desc = {
    Text = "น้ำโคลนสีดำหยดลงบนใบหน้าของคุณ ทำให้เกิดความคันขึ้นมา\nคุณไม่สามารถทนได้ ยื่นมือไปปัดผีเสื้อออก\nผีเสื้อหลบหลีกการเคลื่อนไหวที่ไม่เป็นมิตรของคุณ หายไปอย่างเงียบๆ ที่ปลายทาง。"
  },
  Event_7545_Name = {
    Text = "ผีเสื้อน้ำดำ"
  },
  Event_7546_ChoiceDesc1 = {
