  Event_7546_ChoiceDesc3 = {
    Text = "【เข้าสู่ระบบโดยตรง】"
  },
  Event_7546_Desc = {
    Text = "ข้างหน้าเป็นหมอกดำหนาแน่น การเข้าไปโดยไม่ระวังจะนำมาซึ่งภัยพิบัติ。\nอาจจะถึงเวลาที่คุณควรหาฟีไฟส่องสว่างเพื่อขับไล่หมอก。"
  },
  Event_7546_Name = {
    Text = "ไม่รู้จัก"
  },
  Event_7547_ChoiceDesc1 = {
    Text = "【ยอมรับภาพหลอน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7547_ChoiceDesc2 = {
    Text = "【ปฏิเสธภาพหลอน】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7547_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7547_Desc = {
    Text = "ใต้สะพานเหล็กที่มืดทึบและหนักหน่วง บนชายฝั่งแม่น้ำที่เงียบสงบซึ่งมีต้นอ้อขึ้นรก อยู่ๆ ก็มีผีเสื้อที่เปล่งประกายบินออกมา\nผีเสื้อเบาๆ ลงบนฝ่ามือของคุณ เสียงร้องโหยหวนที่น่าขนลุกหยุดลง แทนที่ด้วยเสียงร้องเรียงรายของคนงานที่ขนเหล็กเส้น เสียงเคาะของค้อนตอก และเสียงโลหะที่กระทบกันอย่างใสแจ๋ว……"
  },
  Event_7547_Name = {
    Text = "ภาพหลอนของสะพานเหล็ก"
  },
  Event_7548_ChoiceDesc1 = {
    Text = "【ขับไล่กา】ได้รับ 40 รอยดำ ติดเชื้อ /* ข้อมูลทักษะ */「(Skill.Arg2)」 เลือกต่อไป"
  },
  Event_7548_ChoiceDesc2 = {
    Text = "【ไล่ตามเด็กต่อ】ได้รับ 25 รอยดำ，แล้วออก"
  },
  Event_7548_Desc = {
    Text = "อีกาตัวหนึ่งยืนอยู่บนโคมไฟระย้า。\nอีกาสองตัวยืนอยู่บนโคมไฟระย้า。\nอีกาสามตัวยืนอยู่บนโคมไฟระย้า。\n……\nสิ่งมีชีวิตสีดำสนิทเหล่านั้นบิดคอ ยืนอยู่บนโคมไฟที่ปากซอย มองคุณด้วยสายตาที่เต็มไปด้วยความชั่วร้าย หัวที่เหมือนเงานั้นดูเหมือนจะแบ่งปันร่างเดียวกันที่จมอยู่ในเมือก D。"
  },
  Event_7548_Name = {
    Text = "การจ้องมองของนกกาดำ"
  },
  Event_7549_ChoiceDesc1 = {
    Text = "【ออกจาก】จำนวนร่างกายที่ตื่นขึ้นจากการตื่นรู้น้อยกว่า 3 ราย จะได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」"
  },
  Event_7549_ChoiceDesc2 = {
    Text = "【ออกจาก】เมื่อจำนวนร่างกายที่ตื่นขึ้นจากการปลุกมีอย่างน้อย 3 ราย ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」"
  },
  Event_7549_Desc = {
    Text = "คุณไม่สนใจรอยขีดนี้ ก้าวเดินไปข้างหน้า。\n<Italic:การตื่นรู้ทางจิตวิญญาณมีน้ำหนักมากเพียงใด> รอยขีดนั้นขยายใหญ่ขึ้นและบิดเบี้ยวตามก้าวของคุณ เหมือนกับว่ามือจะยื่นออกมาจากรอยแตกเพื่อดึงคุณลงไปในความลึก。"
  },
  Event_7549_Name = {
    Text = "รอยร้าวคลาน"
  },
  Event_7550_ChoiceDesc1 = {
    Text = "【ตอบสนองต่อสายตา】ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7550_ChoiceDesc2 = {
    Text = "【หลบสายตา】 สุ่มการตื่นรู้ 2 ร่างกายที่ตื่นขึ้น ติดเชื้อซ้ำสองครั้ง 「(Skill.Arg1)」"
  },
  Event_7550_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7550_Desc = {
    Text = "คุณสามารถรู้สึกได้ถึงสายตา สายตาที่มาจากมิติที่สูงกว่าดินแดนลับแลกำลังจ้องมองคุณ รวมถึงเด็กหญิงที่อยู่ข้างหน้าคุณด้วย \nการหายใจของคุณเริ่มเร่งรีบ ความกลัวอันดิบเถื่อนเริ่มกรีดร้องในส่วนลึกของความมีสติ。"
  },
  Event_7550_Name = {
    Text = "ใครมอง"
  },
  Event_7551_ChoiceDesc1 = {
    Text = "【ค้นหาต่อ】 เพิ่ม Arg1 คะแนนชีวิต, ติดเชื้อ 「(Skill.Arg2)」"
  },
  Event_7551_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7551_Desc = {
    Text = "แสงเรืองรองปรากฏขึ้นเบื้องหน้า สดใสและอบอุ่น เมื่อพยายามก้าวตามแสงนั้น มันกลับหายวับไปอย่างกะทันหัน。"
  },
  Event_7551_Name = {
    Text = "การติดต่อที่ผิดปกติ"
  },
  Event_7552_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7552_Desc = {
    Text = "ร่วมขับกล่อมเสียงแผ่วเบาตามการร่ายมนต์ของพวกเขา กระแสน้ำอุ่นได้นำพาพรแห่งการกลับบ้านมาสู่คุณ"
  },
  Event_7552_Name = {
    Text = "เพลงทะเล"
  },
  Event_7553_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_7553_Desc = {
    Text = "คุณพบแสงจางๆ ข้างหน้า คุณพ้นจากหมอกหนาอันอึดอัดนี้แล้ว"
  },
  Event_7553_Name = {
    Text = "หมอกความวุ่นวาย"
  },
  Event_7554_ChoiceDesc1 = {
    Text = "【คลี่คลายกิ่งก้านด้านล่าง】"
  },
  Event_7554_Desc = {
    Text = "ความรู้ทางจิตวิญญาณที่เหลืออยู่ในดินแดนลับแลเชื่อมโยงกัน และสร้างสนามพลังที่ไม่เสถียรขึ้นมา \n บางทีคุณอาจจะสามารถคลายบ่วงรัดของจิตวิญญาณและจัดเรียงเส้นทางไปข้างหน้าสำหรับตัวเองได้。"
  },
  Event_7554_Name = {
    Text = "ทางที่พันกัน"
  },
  Event_7555_ChoiceDesc1 = {
    Text = "【คลี่คลายกิ่งก้านด้านบน】"
  },
  Event_7555_Desc = {
    Text = "ความรู้ทางจิตวิญญาณที่เหลืออยู่ในดินแดนลับแลเชื่อมโยงกันและกัน สร้างความไม่เสถียรของสนามพลังงาน \n บางที คุณอาจจะสามารถคลายบ่วงรัดของจิตวิญญาณ เพื่อจัดระเบียบเส้นทางไปข้างหน้าของคุณได้。"
  },
  Event_7555_Name = {
    Text = "ทางที่พันกัน"
  },
  Event_7556_ChoiceDesc1 = {
    Text = "【คลี่กิ่งด้านซ้าย】"
  },
  Event_7556_Desc = {
    Text = "ความรู้ทางจิตวิญญาณที่เหลืออยู่ในดินแดนลับแลเชื่อมโยงกัน เกิดเป็นสนามพลังที่ไม่เสถียร \n บางที คุณอาจปลดปล่อยความรู้ทางจิตวิญญาณที่ถูกบิดพัน เพื่อจัดเรียงเส้นทางการก้าวไปข้างหน้าของคุณ。"
  },
  Event_7556_Name = {
    Text = "ทางที่พันกัน"
  },
  Event_7557_ChoiceDesc1 = {
    Text = "【คลี่กิ่งด้านซ้าย】"
  },
  Event_7557_Desc = {
    Text = "ความรู้ทางจิตวิญญาณที่เหลืออยู่ในดินแดนลับแลเชื่อมโยงกันอย่างซับซ้อน สร้างเป็นสนามพลังงานที่ไม่เสถียร \n บางที คุณอาจสามารถคลายบ่วงรัดของจิตวิญญาณเพื่อจัดเส้นทางในการก้าวไปข้างหน้าให้กับตัวเองได้。"
  },
  Event_7557_Name = {
    Text = "ทางที่พันกัน"
  },
  Event_7558_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7558_Desc = {
    Text = "พวกคุณยังต้องเผชิญกับการต่อสู้ที่ดุเดือดอีกหลายครั้ง ตอนนี้ไม่ใช่เวลาที่จะตรวจสอบอย่างไม่เร่งรีบ"
  },
  Event_7558_Name = {
    Text = "การลงทะเบียนอวัยวะ"
  },
  Event_7559_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7559_Desc = {
    Text = "ตัวอักษรบนกระดาษจู่ๆ ก็กลายเป็นสมบูรณ์และมีชีวิตชีวา คำพูดที่น่าตกใจเพียงพอที่จะสั่นคลอนความเชื่อและรากฐานของผู้ที่ไม่มีสติทุกคน คุณอ่านไปก็ยิ่งงงงวย ยิ่งอ่านก็ยิ่งกลัว ไม่สามารถหยุดยั้งการเกาสุขภาพหนังศีรษะของตนเองด้วยปลายนิ้วได้\nจู่ๆ สัญลักษณ์ที่เต็มไปด้วยการสาปแช่งเหล่านั้นก็หายไป ราโมน่าขัดจังหวะการอ่านของคุณ แล้วบังคับให้ใส่หน้ากระดาษลงในกระเป๋าเดินทาง。"
  },
  Event_7559_Name = {
    Text = "รหัสลับ·ลง"
  },
  Event_7560_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7560_Desc = {
    Text = "ความสุข ความเศร้า ความเสียใจ ความทุกข์... เหล่านี้คือความรู้สึกของคุณ \n คุณ และคุณที่หลากหลายจากโลกอื่นนับไม่ถ้วนที่อยู่ภายนอกมิติ。"
  },
  Event_7560_Name = {
    Text = "การติด"
  },
  Event_7561_ChoiceDesc1 = {
    Text = "【ฟังอย่างเงียบๆ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7561_ChoiceDesc2 = {
    Text = "【เธออยู่ที่นี่】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7561_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7561_Desc = {
    Text = "เสียงร้องไห้ของมอนสเตอร์ดังก้องอยู่ในหัวของคุณ ในของเหลวสีดำที่ไม่สามารถเป็นรูปเป็นร่างได้ เสียงหนึ่งกระซิบอย่างอ่อนแรงว่า「พี่สาวซาร่า」，「พี่สาวซาร่า」。\n「พี่สาวซาร่า คุณอยู่ที่ไหน?」"
  },
  Event_7561_Name = {
    Text = "「พี่สาวซาซา」"
  },
  Event_7562_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7562_Desc = {
    Text = "「เข้าร่วมกับเขา เข้าร่วมกับพวกเขา เข้าร่วมกับเรา。\nเป็นการ์เดียนของพระองค์ เป็นผู้ดำเนินการของพระองค์。\nใช้ความฝันของพระองค์เป็นทิศทางในการเดินหน้าของคุณ……」\nคำอธิษฐานที่โกลาหลทำให้จิตสำนึกของคุณสับสน และเมื่อเสียงเหล่านั้นหายไป คุณจึงตระหนักว่าตัวเองเหงื่อท่วมศีรษะแล้ว。"
  },
  Event_7562_Name = {
    Text = "คำอธิษฐานแห่งความฝัน"
  },
  Event_7563_ChoiceDesc1 = {
    Text = "【ไม่รู้จัก】"
  },
  Event_7563_ChoiceDesc2 = {
    Text = "【เคยได้ยิน】"
  },
  Event_7563_Desc = {
    Text = "「นักเรียนคนนี้ ขอใช้เวลาคุณสักหน่อยได้ไหม? \n ผมหวังว่าจะรบกวนพวกคุณสักไม่กี่นาที เพื่อแนะนำตำนานท้องถิ่นให้พวกคุณฟัง \n พวกคุณเคยได้ยินเกี่ยวกับสิ่งมีชีวิตที่เรียกว่า 'เคอร์เบรอส' ไหม?」"
  },
  Event_7563_Name = {
    Text = "เพื่อนร่วมทางประหลาด I"
  },
  Event_7564_ChoiceDesc1 = {
    Text = "【ละทิ้งการคิด】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7564_ChoiceDesc2 = {
    Text = "【ไล่ตามแรงบัลดาลใจ】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7564_Desc = {
    Text = "ท่าเรือถูกโจมตี เรือบรรทุกสินค้าลึกลับที่มาและไปไม่มีวันกลับ และ 「เพื่อนใหม่」 ที่มีครีบ... นี่คือกับดักที่วางแผนมาอย่างดีหรือ? หรือเป็นการเดินทางที่เกิดอุบัติเหตุอีกครั้ง? \n ความเป็นจริงและเหตุผลดึงกันและพันกัน ความคิดและแรงบัลดาลใจนับไม่ถ้วนพุ่งออกจากสมอง。"
  },
  Event_7564_Name = {
    Text = "แรงบันดาลใจพุ่งพล่าน"
  },
  Event_7565_ChoiceDesc1 = {
    Text = "【เอลวอส？】เพิ่มพลังชีวิตสูงสุด Arg1 จุด"
  },
  Event_7565_ChoiceDesc2 = {
    Text = "【พยายามนึกถึง】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7565_Desc = {
    Text = "น้ำตาสีดำไหลลงมาที่แก้มของลิลลี่。「เราเคยพบกันแล้ว แม่」เธอกระซิบเบาๆ，「ที่ภูเขาไฟเอลวอส...」"
  },
  Event_7565_Name = {
    Text = "ความทรงจำภูเขาไฟ"
  },
  Event_7566_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7566_Desc = {
    Text = "「ก้าว@1…ทะเล……」\nรูนปรากฏขึ้นในสายตาคุณอย่างไม่ชัดเจน คุณควบคุมตัวเองไม่ได้ ยื่นมือไปในอากาศว่างเปล่า ต้องการจับมันไว้——\n「ทำอะไรอยู่! พวกเขากำลังไล่ตามมาแล้ว!」\nสาวลึกลับดึงคุณวิ่งไปที่อีกด้านของดาดฟ้า ขัดจังหวะการสื่อสารของคุณกับรูน\nแต่มีบางพละกำลังที่ทิ้งร่องรอยไว้ที่ปลายนิ้วของคุณ。"
  },
  Event_7566_Name = {
    Text = "รูนแห่งความบ้าคลั่ง"
  },
  Event_7567_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7567_Desc = {
    Text = "คุณไม่สนใจคำพูดเพ้อๆ ไร้สาระ และไม่อยากเสี่ยงบ้าคลั่งก้าวเข้าสู่ความมืด。"
  },
  Event_7567_Name = {
    Text = "จดหมายขอความช่วยเหลือ"
  },
  Event_7568_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7568_Desc = {
    Text = "ไม่ว่าอย่างไร หน้าที่ของผู้พิทักษ์อยู่ในอกของคุณ คุณไม่สามารถปล่อยความหวังในการหาผู้ส่งของคุณ แม้ว่ามันจะไม่ชัดเจนและมืดมัวเช่นไร。"
  },
  Event_7568_Name = {
    Text = "จดหมายขอความช่วยเหลือ"
  },
  Event_7569_ChoiceDesc1 = {
    Text = "【ดูมัน】จะได้รับ 25 รอยดำ"
  },
  Event_7569_ChoiceDesc2 = {
    Text = "【ลูบมัน】50% โอกาสได้รับ 50 รอยดำ，50% โอกาสไม่ได้อะไรสักอย่าง"
  },
  Event_7569_Desc = {
    Text = "แมวสีดำตัวหนึ่งกระโดดออกมาจากตรอกอย่างกะทันหัน มันพันกันอยู่ที่ขาของพวกคุณอย่างสนิทสนม ดวงตาแนวตั้งสีเขียวเข้มของมันกระพริบประกายที่ทำให้รู้สึกขนลุก ราวกับว่ามันกำลังพูดว่า「อย่าไล่ตามเลย มาหาเล่นกับฉันสักหน่อย」\n 「คุณเห็นมันแล้ว มันอยู่ข้างๆ คุณ เงาที่ถูกมลพิษอย่างบ้าคลั่งและร้อนแรงเหล่านั้น...อย่าจ้องมองรูปร่างของมันโดยตรง」"
  },
  Event_7569_Name = {
    Text = "เอลฟ์แห่งราตรี"
  },
  Event_7570_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7570_Desc = {
    Text = "「เป็นไปไม่ได้ ฉันไม่เชื่อ！」เสียงกรีดร้องออกมา 「ผู้หญิงที่มอบฉันให้ปีศาจนั่น ไม่ใช่พี่ชาชาของฉัน！」"
  },
  Event_7570_Name = {
    Text = "「พี่สาวซาซา」"
  },
  Event_7571_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7571_Desc = {
    Text = "「ได้รับทราบ เราจะส่งมอบวัสดุพื้นฐานให้ กรุณาตรวจสอบด้วย」"
  },
  Event_7571_Name = {
    Text = "การสื่อสารสนับสนุน"
  },
  Event_7572_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7572_Desc = {
    Text = "มันไร้ประโยชน์แล้ว"
  },
  Event_7572_Name = {
    Text = "ของพื้นเพของผู้ล่วงลับ"
  },
  Event_7573_ChoiceDesc1 = {
    Text = "【ดูให้ละเอียด】ได้รับการแกะสลัก (เลือก 1 จาก 3)"
  },
  Event_7573_ChoiceDesc2 = {
    Text = "【ฉีกโปสเตอร์】การ์ดคำสั่งสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7573_Desc = {
    Text = "เชิงเทียนที่เห็นได้ทั่วไปในพิพิธภัณฑ์หุ่นขี้ผึ้ง\nด้วยแสงสีส้มที่ผิดปกติ คุณพบว่าในกำแพงมีโปสเตอร์ที่วาดด้วยมือแปะอยู่。"
  },
  Event_7573_Name = {
    Text = "เสียงหัวเราะในความมืด"
  },
  Event_7574_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7574_Desc = {
    Text = "「ลิลลี่มีใจของเธอเอง ไม่จำเป็นต้องฟังใครทั้งนั้น。」คุณตอบอย่างไม่ถ่อมตัว \nฟรานซิสถอนหายใจเสียงเบา ไม่มีการตอบกลับ。"
  },
  Event_7574_Name = {
    Text = "การเลือกของเธอ"
  },
  Event_7575_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7575_Desc = {
    Text = "นี่คือชุดภาพถ่ายหมู่\nผู้คนที่ซูบผอมเซื่องซึมอยู่หลังรั้วเหล็ก หน้าตาเต็มไปด้วยความทุกข์\nในนั้นมีภาพหนึ่งที่ดึงดูดความสนใจของคุณ นั่นควรจะเป็นสตรีสาวร่างบางที่ใบหน้าว่างเปล่า\nสิ่งที่ดูหมิ่นอย่างไม่มีที่สิ้นสุดนั้น กำลังพันรอบร่างของเธอเป็นวง\nคุณไม่เห็นใบหน้าของเธอ แต่ในจินตนาการของคุณ เธอควรจะไม่มีสีหน้า。"
  },
  Event_7575_Name = {
    Text = "บันทึกอย่างซื่อสัตย์"
  },
  Event_7576_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7576_Desc = {
    Text = "คุณจ้องมองเครื่องประดับที่เปล่งประกายอย่างติดใจ จนไม่ทันระวัง ได้จับมือดำผอมแห้งที่เต็มไปด้วยเมือกนั้นเสียแล้ว.\nมันแค่บีบมือเล็กน้อย แล้วก็ปล่อย.\nไม่มีอะไรเกิดขึ้น มีเพียงสายควันดำจางๆ ที่ไหลเข้าไปตามปลายนิ้วของคุณสู่แขนเสื้อ."
  },
  Event_7576_Name = {
    Text = "กลับกล้ามปีศาจ"
  },
  Event_7577_ChoiceDesc1 = {
    Text = "【เล่นโน้ตไม่กี่ตัว】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7577_ChoiceDesc2 = {
    Text = "【ปิดฝา】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_7577_Desc = {
    Text = "เปียโนที่อยู่ข้างกำแพงเปิดฝาออก มันมีคีย์ที่เหลืองซีดและขอบที่แตกออกเผยให้เห็นสีไม้ แต่ละคีย์ถูกเช็ดทำความสะอาดอย่างดี\nมันเป็นแหล่งความสุขของผู้คนมากมาย。"
  },
  Event_7577_Name = {
    Text = "เพลงของวัยเด็ก"
  },
  Event_7578_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7578_Desc = {
    Text = "ผู้ถือหอกครางเสียงเบาๆ เหมือนเด็กที่ถูกกลั่นแกล้งร้องไห้อยู่ \n เสียงนั้นหายไปในทันที และผู้เหยียบทะเลอีกสองคนก็หายไปด้วย... ที่แท้เป็นเพียงภาพลวงที่สะท้อนออกมาจากดินแดนลับแล。"
  },
  Event_7578_Name = {
    Text = "ไล่ล่าอย่างไม่ย่อท้อ"
  },
  Event_7579_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_7579_Desc = {
    Text = "「คำตอบที่ถูกต้อง.」\nเจ้าของเสียงพอใจกับคำตอบนี้มาก สิ่งของที่ส่องประกายถูกโยนออกจากผิวน้ำ.\n「จงจำไว้ว่าทุกสิ่งมีราคาที่ต้องจ่าย.」"
  },
  Event_7579_Name = {
    Text = "เสียงจากอีกฟาก"
  },
  Event_7580_ChoiceDesc1 = {
    Text = "【ขจัดภาพลวง】อาการติดเชื้อ。"
  },
  Event_7580_ChoiceDesc2 = {
    Text = "【ออกจาก】"
  },
  Event_7580_Desc = {
    Text = "ใบหน้าที่เลือนลางปรากฏขึ้นอย่างกะทันหัน มันล้อมรอบคุณอยู่ ใช้สายเสียงที่ไม่มีอยู่จริงร้องครวญครางอย่างสิ้นหวัง。"
  },
  Event_7580_Name = {
    Text = "ภาพลวง"
  },
  Event_7581_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7581_Desc = {
    Text = "คุณไม่สนใจรอยขีดนี้ ก้าวเดินไปข้างหน้า。\nแต่ดูเหมือนจะถูกกระตุ้น รอยขีดนั้นขยายใหญ่ขึ้นและบิดเบี้ยวตามก้าวของคุณ เหมือนกับว่ามือจะยื่นออกมาจากรอยแตกเพื่อดึงคุณลงไปในความลึก。"
  },
  Event_7581_Name = {
    Text = "รอยร้าวคลาน"
  },
  Event_7582_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7582_Desc = {
    Text = "คุณไม่ได้หลงกลง่ายๆ หมุนตัวอย่างรวดเร็วและเด็ดขาด จากไปโดยไม่ลังเล"
  },
  Event_7582_Name = {
    Text = "รอยร้าวคลาน"
  },
  Event_7583_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7583_Desc = {
    Text = "คุณตระหนักถึงรอยแตกที่ไม่ปกติ นั่งยองๆ สังเกตดู แปลกใจที่รอยแตกที่เมื่อครู่ยังแพร่ระบาดอยู่ กลับเหมือนกับตายอย่างกระทันหัน ตกอยู่ในความเงียบสงัดที่เป็นนิรันดร์。"
  },
  Event_7583_Name = {
    Text = "รอยร้าวคลาน"
  },
  Event_7584_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7584_Desc = {
    Text = "「ไม่ ใช่ จิตใจที่มีสติ การตัดสินใจไม่สามารถช่วยแก้ไขร่างหลอมละลายได้ ผู้พิทักษ์ ควรคิดหาวิธีการให้ดี」"
  },
  Event_7584_Name = {
    Text = "กฎของโรแกน"
  },
  Event_7585_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7585_Desc = {
    Text = "คุณไม่สามารถต้านทานแรงกระตุ้นในใจได้ \nปลายนิ้วเหมือนเด็กที่หลงทางในป่า ท่องไปท่องมาและเล่นสนุกอยู่บนแป้นพิมพ์…… \nค่อยๆ มีผีเสื้อบินออกมาจากเครื่องพิมพ์ดีด \nหนึ่งตัว สองตัว สามตัว…… \nบนใบหน้า บนปลายนิ้ว ผีเสื้อกลุ่มหนึ่งเหมือนกับดอกไม้ไฟที่บานสะพรั่งอยู่ในอากาศ เปล่งประกายแสงเหมือนอัญมณีในความมืด \nเครื่องพิมพ์ดีดนี้ไม่มีประโยชน์ใช้สอยใดๆ แต่กลับเชี่ยวชาญในการสร้างสรรค์ความงาม。"
  },
  Event_7585_Name = {Text = "ตา"},
  Event_7586_ChoiceDesc1 = {
    Text = "【จับไก่แม่ให้ดี】"
  },
  Event_7586_Desc = {
    Text = "ผลิตภัณฑ์ท้องถิ่นของราอี ไก่ตัวเมียที่กระโดดโลดเต้น เสน่ห์ของอาหารอร่อย"
  },
  Event_7586_Name = {
    Text = "ทำกับดัก"
  },
  Event_7587_ChoiceDesc1 = {
    Text = "【สำเร็จแล้ว】"
  },
  Event_7587_Desc = {
    Text = "กับดักราคาถูกแต่ใช้งานได้ดี!"
  },
  Event_7587_Name = {
    Text = "ทำกับดัก"
  },
  Event_7588_ChoiceDesc1 = {
    Text = "【วางกับดักสัตว์】"
  },
  Event_7588_Desc = {
    Text = "กับดักสัตว์ทำจากโลหะ เป็นผู้ช่วยที่ดีของนักล่าที่ไม่ค่อยขยัน。"
  },
  Event_7588_Name = {
    Text = "ทำกับดัก"
  },
  Event_7589_ChoiceDesc1 = {
    Text = "【ตรวจสอบเครื่องโทรเลข】ติดเชื้อ「(Skill.Arg1)」，ได้รับสิ่งสร้างทองคำ「(RelicConfig.Arg2)」"
  },
  Event_7589_ChoiceDesc2 = {
    Text = "【ละเว้น】ได้รับรอยดำ 50"
  },
  Event_7589_Desc = {
    Text = "คุณหลบเข้าไปในรอยแตกของถ้ำที่แคบและยาว เพื่อหลบลมและหิมะ แต่คุณรู้ดีว่าคุณไม่สามารถหยุดอยู่ที่นี่นานเกินไป หากกลุ่มคนในชุดคลุมดำพบที่นี่ คุณจะไม่มีทางหนี\nในมุมของรอยแตก คุณกลับพบว่ามีเครื่องส่งโทรเลขอยู่เครื่องหนึ่ง。"
  },
  Event_7589_Name = {
    Text = "โทรเลขเงียบ"
  },
  Event_7590_ChoiceDesc1 = {
    Text = "【ตรวจสอบฟิล์ม】สุ่มอัปเกรดผลการแกะสลักของการ์ด 2 ใบ"
  },
  Event_7590_ChoiceDesc2 = {
    Text = "【ตรวจสอบกล้อง】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7590_Desc = {
    Text = "เหมือนดึงอวัยวะภายในออกมา ฟิล์มในท้องกล้องถูกฉีกขาดจนเละเทะ ถูกทิ้งอย่างเปิดท้องที่นี่ ไม่มีใครสนใจ \n แสงขาวจ้าสว่างวาบผ่านไป กล้องที่ถูกทิ้งไว้ที่มุมถนนเอียงไปข้างหนึ่ง ชัตเตอร์ถูกกดโดยไม่มีใคร \n 「คั่กแกร๊ก——」 \n สีหน้าที่ตกตะลึงของคุณถูกบันทึกไว้อย่างซื่อสัตย์บนฟิล์มในกล้อง.。"
  },
  Event_7590_Name = {
    Text = "บันทึกความบริสุทธิ์"
  },
  Event_7591_ChoiceDesc1 = {
    Text = "【บีบคอผู้ขับร้อง】ได้รับสิ่งมีชีวิตแห่งคำสาป「(RelicConfig.Arg1)」ถูกทำให้ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7591_ChoiceDesc2 = {
    Text = "【สะดุดก้าวเท้าของนักเต้นรำ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_7591_ChoiceDesc3 = {
    Text = "【ยึดกระดาษร่างของกวี】ได้รับ 50 ตราดำ"
  },
  Event_7591_Desc = {
    Text = "คุณถูกเงาคนสามคนที่เหนียวเหนอะหนะขวางทางไว้。\nเงาหนึ่งกำลังร้องเพลง เสียงแหบห้าว เนื้อเพลงแปลกประหลาด คุณปิดหูและหลบมันไป。\nเงาอีกคนกำลังเต้นรำ ท่าทางแข็งทื่อ ก้าวย่างลังเล คุณหลับตาและหลบมันไป。\nเงาคนหนึ่งกำลังท่องบทกวี จังหวะขาดสะบั้น ประโยคไม่ต่อเนื่อง คุณทนไม่ไหว จึง——"
  },
  Event_7591_Name = {
    Text = "ผู้ร้ายบนทางแคบ"
  },
  Event_7592_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7592_Desc = {
    Text = "「ไม่! ความก้าวหน้าของมนุษย์ไม่ได้ขึ้นอยู่กับประวัติศาสตร์ หรือเทคโนโลยี แต่ขึ้นอยู่กับหนู。」\n「หนูคือผู้ที่เปิดยุคแห่งความมืดนั้น และจากนั้นมนุษย์จึงได้ต้อนรับแสงสว่างแห่งการฟื้นฟู。」\n「มนุษย์ต้องการพวกคุณ—แม้ว่าจะไม่ใช่ทุกคนที่เข้าใจเรื่องนี้。」\nหนูๆ รู้สึกงงงวยกับคำพูดยาวเหยียดของคุณ แต่ก็ยังปล่อยคุณไป。"
  },
  Event_7592_Name = {
    Text = "พิษระบาด"
  },
  Event_7593_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7593_Desc = {
    Text = "คุณอดกลั้นการกระตุกของเส้นประสาทตาและพยายามแยกแยะ……\nที่นั่นดูเหมือนจะมีการวาดอาณาเขตเวททรงกลมที่ฉีกขาดแล้ว\nภายในอาณาเขตเวทประกอบด้วยเส้นโค้งนับไม่ถ้วน ดูเหมือนจะนิ่งอยู่แต่ก็เหมือนกำลังเคลื่อนไหว ทำให้รู้สึกเวียนหัว。"
  },
  Event_7593_Name = {
    Text = "จากมุม"
  },
  Event_7594_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7594_Desc = {
    Text = "<Bold>พิพิธภัณฑ์หุ่นขี้ผึ้งโรเจอร์ส\nถนนนันวอล์ก 44，เมืองลอนดีเนี่ยน@2\nเวลาท่องเที่ยว：21:00-6:00\nหยุดเข้าชมเวลา 3:00 (ปิดในวันหยุดสุดสัปดาห์)\n\n<Bold>นิทรรศการปัจจุบัน\nฟลาดิเมียร์·@2：\nปรัชญาของรอยยิ้ม"
  },
  Event_7594_Name = {
    Text = "เสียงหัวเราะในความมืด"
  },
  Event_7595_ChoiceDesc1 = {
    Text = "【สบตา】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」，ได้รับผลกระทบ「(Skill.Arg2)」"
  },
  Event_7595_ChoiceDesc2 = {
    Text = "【ปิดตา】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น ปลุก「(Skill.Arg1)」"
  },
  Event_7595_ChoiceDesc3 = {
    Text = "【หันหลังให้】ได้รับ 25 รอยดำ"
  },
  Event_7595_Desc = {
    Text = "ไม่ควรเห็นท้องฟ้าด้วยซ้ำ。\nในดินแดนลับแลของโซนาเนียร์ ผ้าฟ้าหมุนเวียนไปด้วยแสงสีสัน ดวงดาวและดวงจันทร์ต่างก็ซ่อนเร้นอยู่。\nในห้องโดยสารที่มืดมิด คุณก็ไม่ควรเห็นท้องฟ้าเช่นกัน。\nที่นี่ควรมีเพียงไฟฟลูออเรสเซนต์และโคมไฟเก่าๆ เท่านั้น——แต่ทำไมคุณยังรู้สึกได้ถึงสายตาที่ลอยอยู่เหนือฟ้า?"
  },
  Event_7595_Name = {
    Text = "มองลับ"
  },
  Event_7596_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7596_Desc = {
    Text = "คุณเลือกที่จะมองตาอย่างกล้าหาญ \n มันคือดวงดาวที่ส่องแสงระยิบระยับในความมืด \n หลังจากนั้นมันก็หัวเราะและกลายเป็นพระจันทร์เสี้ยวมากมาย \n ตาบอกว่า:「คุณไม่กลัวสายตา คุณไม่ควรกลัว... นานแล้วที่ไม่ได้พบกัน, @2」 \n ก่อนที่จะหายไป มันได้มอบของขวัญเล็กๆ ให้กับคุณ เป็นที่ระลึกของ「การพบกันอีกครั้ง」。"
  },
  Event_7596_Name = {Text = "ตา"},
  Event_7597_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7597_Desc = {
    Text = "สะพานรถไฟ หลอดเลือดและเส้นประสาทของลอนดีเนี่ยน เชื่อมต่อหัวใจและอวัยวะสี่ส่วนของเมือง ตราบใดที่สุริยันยังไม่ตกจากที่นี่ หัวใจของลอนดีเนี่ยนจะยังคงเต้นอย่างเข้มข้นตลอดไป."
  },
  Event_7597_Name = {
    Text = "ภาพหลอนของสะพานเหล็ก"
  },
  Event_7598_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7598_Desc = {
    Text = "ฟูกาที่หรูหราสุดๆ ผลงานของผู้ประพันธ์ที่ไม่ทราบชื่อ\nเสียงหลายเสียงที่มีธีมที่ใกล้เคียงกันผสมผสานกันออกมา ทุกโน้ตเหมือนมีดผ่าตัดของหมอที่แม่นยำและไร้ความปรานี\nแม่นยำและหรูหรา—นี่คือความงามของโรเจอร์ส\nฟูกา โบยบินเถอะ!"
  },
  Event_7598_Name = {
    Text = "รสนิยมที่แย่"
  },
  Event_7599_ChoiceDesc1 = {
    Text = "【ทักทายด้วยเสียง】"
  },
  Event_7599_ChoiceDesc2 = {
    Text = "【ขอความช่วยเหลือ】"
  },
  Event_7599_Desc = {
    Text = "เมื่อมือของคุณสัมผัสกับขอบเรือ คุณก็เห็นสาวในชุดขาวคนหนึ่ง \nสูงศักดิ์ บริสุทธิ์ ลึกลับ... และมีความคุ้นเคยอยู่บ้าง \nไม่รู้ว่าเคยเห็นเธอที่ไหนมาก่อน? ในขณะที่คุณกำลังขุดค้นความทรงจำที่ยุ่งเหยิง เธอก็เหมือนจะรู้ตัวว่าคุณอยู่ที่นี่ มองมาที่คุณผ่านความว่างเปล่า \nดวงตาของเธอสงบเหมือนมหาสมุทรในต้นฤดูใบไม้ผลิ แต่คุณกลับรู้สึกแปลกๆ ว่ามีอะไรบางอย่างที่อ่านได้จากดวงตานั้น... \nเธอดูเหมือนกำลังรอให้คุณทักทายเธอ แม้เพียงแค่พูดคุยเกี่ยวกับสภาพอากาศในวันนี้。"
  },
  Event_7599_Name = {
    Text = "สาวในชุดขาว"
  },
  Event_7600_ChoiceDesc1 = {
    Text = "【ชมมัน】เลือก 1 การ์ดคำสั่งจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_7600_ChoiceDesc2 = {
    Text = "【เยาะเย้ยมัน】ติดเชื้อ「(Skill.Arg1)」, สุ่มการแกะสลักอีกครั้ง"
  },
  Event_7600_Desc = {
    Text = "เจนกินพูดว่า: จอห์นนี่! คุณแตกต่างจากเมื่อก่อนจริงๆ... ไม่ว่าจะมองจากมุมไหนก็ตาม。\nคุณพูดว่า: คุณเป็นคนที่ขยันและมีความมุ่งมั่นจริงๆ。\nสมองขยับไปมาสองสามครั้ง ดูเหมือนจะมีความสุขมาก。\nสมองพูดว่า: มาสิ! เมื่อพวกคุณยอมรับความสำเร็จในตอนนี้ของฉันอย่างมากมาย ฉันจะมอบความรู้ตลอดชีวิตของฉันให้พวกคุณ..."
  },
  Event_7600_Name = {
    Text = "สมองปรัชญา"
  },
  Event_7601_ChoiceDesc1 = {
    Text = "【ฟูเกตล้ำค่า】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，ได้รับการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7601_ChoiceDesc2 = {
    Text = "【เพลงโหมโรงยามราตรี】ร่างกายที่ตื่นขึ้นทั้งหมดฟื้นฟูความคลั่ง 50, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7601_ChoiceDesc3 = {
    Text = "【เสียงรบกวนไร้ความหมาย】ได้รับการแกะสลักแบบเลือก 1 ใน 3"
  },
  Event_7601_Desc = {
    Text = "「ฉันไม่ค่อยเห็นด้วยกับรสนิยมทางดนตรีของผู้อำนวยการ คุณก็รู้ว่า...\nมันหรูหราจนเกินไป และฉันเป็นคนที่มีเท้าติดพื้น」\nเสียงชายคนหนึ่งที่เหนื่อยล้าเล็ดลอดออกมาจากเครื่องเล่นแผ่นเสียงที่ขยับเสียงดัง กำลังบ่นอย่างโดดเดี่ยว\n「แต่ นี่คือหน้าที่ของฉัน... โอเค เราประหยัดเวลา เลือกแผ่นหนึ่งเถอะ」"
  },
  Event_7601_Name = {
    Text = "รสนิยมที่แย่"
  },
  Event_7602_ChoiceDesc1 = {
    Text = "【มีสิ่งประดิษฐ์พิเศษ ได้รับสิ่งประดิษฐ์ทองคำ「(RelicConfig.Arg1)」】"
  },
  Event_7602_ChoiceDesc2 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7602_Desc = {
    Text = "เหตุการณ์ 253 (กำลังพัฒนา)，ไม่ใช่ผลสุดท้าย"
  },
  Event_7602_Name = {
    Text = "เหตุการณ์ (253) (กำลังพัฒนา)"
  },
  Event_7603_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7603_Desc = {
    Text = "คุณวิ่งหนีจากสถานที่นั้นด้วยความเร็วสูงสุด \n ตอนนี้คุณกำลังเผชิญหน้ากับมอนสเตอร์ที่ยากจะจัดการและน่ารังเกียจที่สุดในประวัติศาสตร์——หุ่นขี้ผึ้งที่แน่นขนัดเหล่านั้น \n เมื่อเปรียบเทียบกับพวกมัน สิ่งเหล่านี้คือดินเหนียวที่เรียบง่ายดูเหมือนไม่มีค่าเลย \n การแยกแยะสิ่งที่สำคัญและไม่สำคัญ——นี่คือหนึ่งในหลักการที่ผู้พิทักษ์ควรยึดถือ。"
  },
  Event_7603_Name = {
    Text = "แบบฝึกหัด"
  },
  Event_7604_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7604_Desc = {
    Text = "กุญแจเงินกระพริบ แสงเงินเติมเต็มพื้นที่ ทำให้สีสันที่ข้นหนืดไหลกลายเป็นเงินบริสุทธิ์ \n แสงสว่างหายไปในทันที มีเพียงวายุที่เหลือไว้ซึ่งเสียงร้องไห้เศร้า。"
  },
  Event_7604_Name = {
    Text = "สีที่ทำให้นึกถึง"
  },
  Event_7605_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7605_Desc = {
    Text = "รุ้งสีนั้นทำให้คุณตาพร่ามัว จนเผลอตัวหลงใหลไปในนั้น.."
  },
  Event_7605_Name = {
    Text = "ทางแยกของดวงดาว"
  },
  Event_7606_ChoiceDesc1 = {
    Text = "【ตกลงไปเรื่อยๆ】ติดเชื้อ「(Skill.Arg1)」，คุณต้องการตกลงไปอีกหรือไม่"
  },
  Event_7606_ChoiceDesc2 = {
    Text = "【ถอนตัวออก】ได้รับ 25 รอยดำ"
  },
  Event_7606_Desc = {
    Text = "「คุณ」กำลังเชิญคุณอยู่。\nในความลึกของเกลียวคลื่น คุณจากอดีตและอนาคตได้ส่ง「ของขวัญ」จากมิติที่แตกต่างมาถึงคุณ。"
  },
  Event_7606_Name = {
    Text = "เหววน"
  },
  Event_7607_ChoiceDesc1 = {
    Text = "【เข้าใจแจ่มแจ้ง】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，ติดสกิล「(Skill.Arg2)」"
  },
  Event_7607_ChoiceDesc2 = {
    Text = "【ไม่รู้อะไรเลย】ได้รับสิ่งสร้างทองคำหนึ่งในสาม ถูกโจมตีด้วย「(Skill.Arg1)」"
  },
  Event_7607_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」"
  },
  Event_7607_Desc = {
    Text = "เงาสีเงินสองเงาปรากฏขึ้นตรงหน้าคุณ ดูเหมือนของเหลวหนืดลอยอยู่ในอากาศ。\n「ที่นี่คือสถานที่ที่ข้าสูญสลาย。」เงาหนึ่งนั่งยองลง。\n「ในประเทศเทพที่ไม่มีโรคภัยไข้เจ็บ ไม่มีสิ่งที่เรียกว่าความปรารถนาและการสูญเสีย คุณไม่อาจเข้าใจได้จริงๆ——ว่าการสูญสลายคืออะไร。」\nอีกเงาหนึ่งถอนหายใจ มองมายังคุณ。"
  },
  Event_7607_Name = {
    Text = "สวรรค์ที่สาบสูญ"
  },
  Event_7608_ChoiceDesc1 = {
    Text = "【ออก】ค้นหาไฟส่องสว่าง"
  },
  Event_7608_ChoiceDesc2 = {
    Text = "【บุกเข้าสู่หมอก】ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7608_ChoiceDesc3 = {
    Text = "【เข้าสู่ระบบโดยตรง】"
  },
  Event_7608_Desc = {
    Text = "ข้างหน้าคือหมอกสีดำหนาทึบ หากเข้าไปโดยไม่ระวังจะนำมาซึ่งภัยพิบัติ。\nอาจจะถึงเวลาที่คุณควรหาฟืนส่องสว่างเพื่อขับไล่หมอกนั้น。"
  },
  Event_7608_Name = {
    Text = "ไม่รู้จัก"
  },
  Event_7609_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7609_Desc = {
    Text = "「นั่นคือภาพสะท้อนของความทรงจำ」ราโมน่าอธิบายกับคุณ「อาจเป็นของใครคนหนึ่ง หรืออาจเป็นความทรงจำร่วมของหลายคน」\nความทรงจำอันมีค่า ควรได้รับการดูแลอย่างระมัดระวัง。"
  },
  Event_7609_Name = {
    Text = "ความทรงจำของเรา"
  },
  Event_7610_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7610_Desc = {
    Text = "แม้ว่าตอนนี้จะไม่สามารถตีความได้ คุณก็ไม่ได้ยอมแพ้ แต่กลับพับมันอย่างอดทนและใส่ลงในกระเป๋า รอจนกลับไปโรงเรียนเพื่อหาวิธีอื่นในการอ่านข้อมูล \n แค่เพียง เมื่อจดหมายย่นตัวขึ้นมาอย่างแปลกประหลาด หน้าอกของคุณก็เริ่มเจ็บปวดขึ้นมาเบาๆ。"
  },
  Event_7610_Name = {
    Text = "จดหมายที่ขีดฆ่า"
  },
  Event_7611_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7611_Desc = {
    Text = "ในขณะที่เทียนหลุดจากคานมันก็จะติดไฟเอง มันไหลน้ำตาสีขาวขุ่นตกลงมาอย่างรวดเร็วจากซอกนิ้วของคุณ แล้วหายไป。"
  },
  Event_7611_Name = {
    Text = "ความรู้สึกและเหตุผล"
  },
  Event_7612_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7612_Desc = {
    Text = "คุณดึงกระดาษออกมาอย่างรวดเร็ว แต่เครื่องพิมพ์ดีดยังคงทำงานอยู่ มันนำการ์ดใบหนึ่งเข้าไปและพ่นหมึกทับลงไปเต็มไปหมด\nคุณพยายามอ่านอย่างละเอียด ดูเหมือนว่าจะเขียนซ้ำๆ ว่า「อย่าจ้องมองโดยตรงอย่าจ้องมองโดยตรงอย่าจ้องมองโดยตรงอย่าจ้องมองโดยตรงอย่าจ้องมองโดยตรง」"
  },
  Event_7612_Name = {
    Text = "คำเตือนที่ไม่ได้รับเชิญ"
  },
  Event_7613_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7613_Desc = {
    Text = "เมื่อปลายนิ้วสัมผัสกับขอบถ้วยเย็นจัดจนทำให้ไขกระดูกแช่แข็ง คุณก็สะดุ้งขึ้นมาอย่างกระทันหัน\nไม่ว่าจะยังไง มันก็ไม่เหมาะที่จะถูกทิ้งไว้ข้างทาง ควรเก็บมันใส่กระเป๋าเดินทางเถอะ。"
  },
  Event_7613_Name = {
    Text = "ไวน์หวานจากผึ้ง"
  },
  Event_7614_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7614_Desc = {
    Text = "คุณไออย่างรุนแรง\nเสียงดูเหมือนตกใจ แล้วจากนั้นก็เงียบสนิท\nคุณรู้สึกเหมือนพลาดเบาะแสสำคัญบางอย่าง...\nแต่ชีวิตก็เต็มไปด้วยการพลาดและความเสียดาย ใช่ไหม?"
  },
  Event_7614_Name = {
    Text = "ผนังมีหู"
  },
  Event_7615_ChoiceDesc1 = {
    Text = "【ปิดปากเงียบ】ได้รับ 25 รอยดำ"
  },
  Event_7615_ChoiceDesc2 = {
    Text = "【ยื่นมือสัมผัส】50% โอกาสได้รับ 50 รอยดำ, 50% โอกาสไม่ได้อะไรเลย"
  },
  Event_7615_Desc = {
    Text = "「สิ่งที่ฉันต้องการจะพูดมีเพียงคำสอนประโยคเดียว——ไม่มีใครสามารถฆ่าวิฬารได้!」\n「แมวดำนั้นควรถูกผ่าท้องและทิ้งไว้ในป่า แต่มันกลับขุดหลุมศพของครอบครัวฉัน และกินเนื้อคนที่เหลืออยู่จนเกือบหมด เหลือแต่กระดูกและอวัยวะที่กระจัดกระจายไปทั่ว」\n「ภายใต้การจ้องมองของตาที่มีรูปร่างเหมือนแนวตั้ง ความหนาวเย็นและมืดมิด น้ำหนองสีเหลืองคล้ำลอยขึ้นมาพร้อมกับกลิ่นเหม็น ฉันกลิ้งและคลานหนีไปจากที่นั่น ถูกฝันร้ายทำให้จิตใจอ่อนแอ」\n「เดี๋ยวก่อน...พวกคุณจะทำอะไร ฉันไม่ได้บ้า! ฉันไม่ได้! พวกคุณต้องการปกปิดอะไรบางอย่าง! นี่มันเป็นเรื่องจริง——」\nนี่มันเป็นเรื่องจริง เมื่อเห็นเงาของคนบ้าหายไป คุณมองตากับวิฬารสีดำที่นั่งอยู่ข้างเท้าอย่างเงียบๆ。"
  },
  Event_7615_Name = {
    Text = "ภัยพิบัติของแมวกลางคืน"
  },
  Event_7616_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7616_Desc = {
    Text = "ในขณะที่คุณลังเล มันจมหายในรอยละลาย แล้วหายไปในพริบตา"
  },
  Event_7616_Name = {
    Text = "วัตถุลอยในถัง"
  },
  Event_7617_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7617_Desc = {
    Text = "คุณรู้สึกรำคาญใจและขยำกระดาษจดหมายเป็นก้อน ก่อนจะโยนมันลงข้างเท้าอย่างไม่ใส่ใจ"
  },
  Event_7617_Name = {
    Text = "จดหมายที่ขีดฆ่า"
  },
  Event_7618_ChoiceDesc1 = {
    Text = "【ยืนยัน】"
  },
  Event_7618_Desc = {
    Text = "คุณตั้งสมาธิ ภาพลวงค่อยๆ จางหายไปเหมือนหมึกน้ำ คุณเดินต่อไป แต่ไม่สามารถขจัดความมืดมัวในใจออกไปได้อย่างสิ้นเชิง。"
  },
  Event_7618_Name = {
    Text = "ภาพลวง"
  },
  Event_7619_ChoiceDesc1 = {
    Text = "【ตรวจสอบอย่างระมัดระวัง】ได้รับสิ่งประดิษฐ์เงิน「(RelicConfig.Arg1)」，สถานะ「(Skill.Arg2)」"
  },
  Event_7619_ChoiceDesc2 = {
    Text = "【หลีกเลี่ยงเงาร่าง】ได้รับสิ่งประดิษฐ์เงิน 「(RelicConfig.Arg1)」，ได้รับผลกระทบจาก「(Skill.Arg2)」"
  },
  Event_7619_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_7619_Desc = {
    Text = "รามอน่าตึงเครียดอย่างมาก ระมัดระวังหลบหลีกฝูงชนในโรงพยาบาลจิตเวช \n เธอหลบเข้าไปในห้องแคบๆ \n นอกหน้าต่างก็สะท้อนเงาของคนขึ้นมาอย่างกะทันหัน。"
  },
  Event_7619_Name = {
    Text = "การสะท้อนในหน้าต่าง"
  },
  Event_7620_ChoiceDesc1 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_7620_Desc = {
    Text = "ตอนนี้สิ่งที่สำคัญกว่าคือการนำตัวผู้ที่เป็นต้นเหตุของเหตุการณ์ทั้งหมดมาลงโทษ แต่เมล็ดพันธุ์แห่งความโกรธยังคงเติบโตในใจของคุณ โดยไม่รอให้พวกคุณตอบสนอง ชายคนหนึ่งจึงหันข้างออกไป。"
  },
  Event_7620_Name = {
    Text = "รอยเท้าสัตว์ยักษ์"
  },
  Event_7621_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 75 รอยดำ เกิดการติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7621_Desc = {
    Text = "การศึกษาในมิซาเกอร์ที่คุณได้รับตั้งแต่เยาว์วัยทำให้คุณไม่สามารถเพิกเฉยต่อการถ่ายภาพนี้ได้ คุณยื่นมือปัดรอยฝุ่นและรอยเท้าออกไป ในชั่วขณะนั้น คุณเหมือนได้ยินเสียงตอบกลับจากมิติที่ไกลโพ้นว่า 「ขอบคุณ」"
  },
  Event_7621_Name = {
    Text = "รอยเท้าสัตว์ยักษ์"
  },
  Event_7622_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7622_Desc = {
    Text = "คุณกอบกุมกุญแจเงินให้มั่น แสงสีเงินอันนุ่มนวลและการสั่นสะเทือนเล็กน้อยทำให้คุณรู้สึกถึงความสบายใจ สายตาดูเหมือนจะหายไป แต่ก็เหมือนยังอยู่ ไม่ว่าอย่างไร มันได้ทิ้งร่องรอยที่ไม่มีรูปแบบในตัวคุณ。"
  },
  Event_7622_Name = {
    Text = "ใครมอง"
  },
  Event_7623_ChoiceDesc1 = {
    Text = "【ค้นหาทางลับ】"
  },
  Event_7623_Desc = {
    Text = "คุณและราโมน่า โลทัน แยกกันสามทาง เริ่มไล่ตามสุนัขแห่งนรก。\n\nคุณวิ่งผ่านซอยเล็กๆ หลายแห่ง ร่างกายขนาดใหญ่ปรากฏขึ้นต่อหน้าคุณ。\nเมื่อมันเห็นว่าคุณไล่ตาม มันก็หันไปที่มุมถัดไปทันที。\nคุณวิ่งตามไป แต่ที่ปรากฏขึ้นกลับเป็นทางตัน มีกำแพงสูงสามด้านล้อมรอบท้องฟ้าสี่เหลี่ยมแคบๆ。"
  },
  Event_7623_Name = {
    Text = "ทางตัน"
  },
  Event_7624_ChoiceDesc1 = {
    Text = "【เดินผ่าน】"
  },
  Event_7624_ChoiceDesc2 = {
    Text = "【ลูบ】"
  },
  Event_7624_Desc = {
    Text = "ข้างๆ เตียงผ่าตัดที่สะอาดและนุ่มนวล ร่างกายที่อ่อนแรงของคุมกำลังนอนอยู่ \nเธอยังคงสูงใหญ่ เหมือนภูเขา เหมือนตอนที่คุณเห็นเธอครั้งแรก \nแต่เมื่อเปรียบเทียบกับ 「สุนัขแห่งนรก」 ตัวจริงที่อยู่ในอากาศ เธอก็เล็กน้อยจนน่ารัก เหมือนเด็กน้อย。"
  },
  Event_7624_Name = {
    Text = "ความร้อนที่เหลือ"
  },
  Event_7625_ChoiceDesc1 = {
    Text = "[ได้รับเงินใจ]"
  },
  Event_7625_Desc = {
    Text = "อุ๊ย ข้างหน้าเหมือนจะมีของสว่างระยิบระยับมากมาย!\nดมดู...หอมจัง.\nเลียดู...เย็นสบาย!\nดูเหมือนจะเป็นของล้ำค่า รีบเก็บไว้แล้วส่งให้เจนกิน บางทีอาจจะแลกชีสได้เยอะเลย!"
  },
  Event_7625_Name = {
    Text = "สว่างระยิบระยับ"
  },
  Event_7626_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7626_Desc = {
    Text = "ความผิดหวังที่ไม่ใช่ของคุณค่อยๆ แผ่ซ่านในใจ ใยแห่งภาพลวงตาค่อยๆ จางหายไป เปิดทางให้กับเส้นทางหนึ่ง"
  },
  Event_7626_Name = {
    Text = "เครือข่ายหลงทาง"
  },
  Event_7627_ChoiceDesc1 = {
    Text = "【การตื่นรู้ลึกล้ำ】สุ่มปลุกร่างที่ตื่นขึ้น 1 ตน ให้ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_7627_ChoiceDesc2 = {
    Text = "【ละเว้นมัน】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_7627_Desc = {
    Text = "รหัสที่ไหลออกมาจากเสียงคำรามของชีวิตรูปปลา มันเติมเต็มช่องหูของคุณ ช่องจมูกของคุณ และหลอดลมของคุณ มันเผาไหม้ร่างกายของคุณ เพียงอีกสิบวินาทีถัดไป คุณจะเข้าใจความหมายลึกซึ้งในเสียงคำราม..."
  },
  Event_7627_Name = {
    Text = "รูนแห่งความบ้าคลั่ง"
  },
  Event_7628_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7628_Desc = {
    Text = "คุณกัดฟันพยายามต้านทานภาพหลอนที่ยุ่งเหยิงนั้น ราโมน่าวางวัตถุที่เย็นเฉียบชิ้นหนึ่งไว้ในฝ่ามือของคุณ \n「สิ่งที่ฉันค้นพบเมื่อกี้ อาจจะช่วยคุณได้」"
  },
  Event_7628_Name = {
    Text = "มิติลวงตา"
  },
  Event_7629_ChoiceDesc1 = {
    Text = "เลือกการแกะสลักขั้นสูง"
  },
  Event_7630_ChoiceDesc1 = {
    Text = "【กดกาไว้】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_7630_ChoiceDesc2 = {
    Text = "【ฆ่าอีกา】รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_7630_ChoiceDesc3 = {
    Text = "【ออกจาก】"
  },
  Event_7630_Desc = {
    Text = "อีกาที่โดดเดี่ยวส่งเสียงแหบพร่า ดึงขนสีดำของตัวเองออกทีละเส้น。\n มันเจ็บจนตัวสั่น ร้องตะโกนเสียงสูง แต่ก็หยุดการเคลื่อนไหวที่เร็วขึ้นเรื่อยๆ ไม่ได้。\n「ก๊า——ก๊า——」\n น้ำตาสีน้ำเงินที่มีน้ำดำไหลออกจากตาของมัน นอกจากคุณ ไม่มีใครได้เห็น。\n"
  },
  Event_7630_Name = {
    Text = "น้ำตาของภูเขาไฟหลอมละลาย"
  },
  Event_7631_ChoiceDesc1 = {
    Text = "【Leave】เพิ่มพลังชีวิตสูงสุด Arg1 จุด"
  },
  Event_7631_Desc = {
    Text = "「ให้ฉันจัดการเถอะ」คุณลูบหลังของสัตว์ประหลาดเหมือนกับปลอบแมวตัวเล็กที่โกรธจัด「เธอจะต้องตื่นขึ้นมาแน่นอน เราจะไม่ทำร้ายเธอ」"
  },
  Event_7631_Name = {
    Text = "การเรียกของมิตรภาพ"
  },
  Event_7632_ChoiceDesc1 = {
    Text = "【การจากไป】เพิ่มพลังชีวิตสูงสุด Arg1 เกิดผล「(Skill.Arg2)」และ「(Skill.Arg3)」"
  },
  Event_7632_Desc = {
    Text = "「ตื่นเถอะ ลิลลี่ คูมก็หวังว่าเธอจะฟื้นคืนสติเร็วๆ นี้——」"
  },
  Event_7632_Name = {
    Text = "การเรียกของมิตรภาพ"
  },
  Event_7633_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_7633_Desc = {
    Text = "มันไร้ประโยชน์แล้ว"
  },
  Event_7633_Name = {
    Text = "โทรเลขเงียบ"
  },
  Event_79429_ChoiceDesc1 = {
    Text = "เลือกผู้ปลุกตื่น 1 ตัว และเปลี่ยนให้เป็น 「อินเซคทอยด์」 ผ่านพิธีชีวิต การ์ดคำสั่งของ 「อินเซคทอยด์」 จะลดการใช้พลังการคำนวณลง 1 แต่เมื่อเล่นจะถูกใช้ไป。"
  },
  Event_79429_Desc = {
    Text = "「ในกระบวนการรู้จักตัวเอง มักจะมีความเจ็บปวดเสมอ การเปลี่ยนแปลงและการเกิดใหม่ก็เช่นกัน。」\nเธอยิ้มอย่างอ่อนโยนและลูบหน้าของคุณอย่างรักใคร่ \n「ไม่ต้องกลัว ฉันอยู่ที่นี่กับเธอ ดังนั้นเปิดใจและรับทุกสิ่งไว้เถอะ」\n「เด็กดี ฉันรอการเกิดใหม่ของเธอ รอให้เธอ……เป็นส่วนหนึ่งของเรา」"
  },
  Event_79429_Name = {
    Text = "การเปลี่ยนแปลงของชีวิต"
  },
  Event_80463_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้างเงิน เลือก 1 จาก 3, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80463_Desc = {
    Text = "คุณเลือกเส้นทางแล้วดึงวิลเลียมตัวน้อยวิ่งอย่างสุดกำลัง\nโชคดีที่การเลือกของคุณถูกต้อง\nมลพิษทางจิตใจเหล่านั้น คลีเมนไทน์ที่เหมือนกันทุกประการ ถูกคุณปลดปล่อยออกไปในที่สุด\nแน่นอนว่าคุณต้องจ่ายในราคาที่ต้องจ่ายบางอย่าง。"
  },
  Event_80463_Name = {
    Text = "「คลีเมนไทน์」ๆ"
  },
  Event_80464_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80464_Desc = {
    Text = "ความทรงจำที่เกินความเข้าใจถูกฉีดเข้าไปในสมองของคุณ ทำให้เหตุผลของคุณพังทลายลง\nในภาพที่เหมือนกับการเร่งความเร็วอย่างรวดเร็ว คุณจำได้เพียงฉากเดียว: วิหารรูปสามเหลี่ยม\nนั่นคือผลงานอันยิ่งใหญ่ที่สร้างขึ้นโดย@2อินเซคทอยด์เพื่อความโง่เขลาที่ยิ่งใหญ่ของ@4。"
  },
  Event_80464_Name = {
    Text = "ความทรงจำลึกซึ้ง"
  },
  Event_80465_ChoiceDesc1 = {
    Text = "【ออก】เลือกการตื่นรู้ 1 ร่างกายที่ตื่นขึ้น ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80465_Desc = {
    Text = "คุณเลือกเส้นทางแล้วดึงวิลเลียมตัวน้อยวิ่งไปอย่างเต็มที่ \nโชคดีที่การเลือกของคุณถูกต้อง \nมลพิษทางจิตใจเหล่านั้น คลีเมนไทน์ที่เหมือนกันทุกประการ ในที่สุดคุณก็หลุดพ้นจากมัน \nแน่นอนว่าคุณต้องจ่ายในราคาที่ต้องจ่าย。"
  },
  Event_80465_Name = {
    Text = "「คลีเมนไทน์」ๆ"
  },
  Event_80466_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80466_Desc = {
    Text = "「คลิก. คลิก. คลิก」\nในที่สุด「งาน」ก็เสร็จสิ้น, แต่คุณได้อะไรนอกจาก「งาน」เอง?"
  },
  Event_80466_Name = {
    Text = "ความทรมานไม่มีที่สิ้นสุด"
  },
  Event_80467_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_80467_Desc = {
    Text = "「ดีใจที่ได้ยินคำตอบจากใจของคุณ。」\n「หวังว่าเราจะแบ่งปันเวลาพบกันอีกครั้ง。」"
  },
  Event_80467_Name = {
    Text = "การเรียกในความฝัน"
  },
  Event_80468_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_80468_Desc = {
    Text = "「อุ๊ย เด็กที่ไม่ซื่อสัตย์จริงๆ」\n「แต่ไม่เป็นไร ครั้งหน้า ฉันจะทำให้คุณพูดความจริงออกมา」\n「ทั้งหมดที่มาจากใจและจิตวิญญาณคือความจริง」"
  },
  Event_80468_Name = {
    Text = "การเรียกในความฝัน"
  },
  Event_80469_ChoiceDesc1 = {
    Text = "【เริ่ม「ทำงาน」】ลบการ์ดคำสั่ง 1 ใบ รับสัญลักษณ์ดำ Arg1"
  },
  Event_80469_ChoiceDesc2 = {
    Text = "【ถอยออกมาให้ห่าง】"
  },
  Event_80469_Desc = {
    Text = "「คลิก。」\nเสียงของเครื่องพิมพ์ดีดดังขึ้น, ก่อนที่งานจะเสร็จ, คุณจะเป็นทาสของมันไปตลอด。"
  },
  Event_80469_Name = {
    Text = "ความทรมานไม่มีที่สิ้นสุด"
  },
  Event_80470_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80470_Desc = {
    Text = "「น่าเสียดายจริง ๆ ความระมัดระวังของคุณทำให้คุณพลาดโอกาสเดียวที่จะรู้ความจริง。」\nมันถอนหายใจและสลายไปอย่างเงียบ ๆ。"
  },
  Event_80470_Name = {
    Text = "ความทรงจำลึกซึ้ง"
  },
  Event_80471_ChoiceDesc1 = {
    Text = "【โจมตีเต็มที่】"
  },
  Event_80471_ChoiceDesc2 = {
    Text = "【ขอไปต่อ】"
  },
  Event_80471_Desc = {
    Text = "เงาที่ไม่คาดคิดปรากฏขึ้นต่อหน้าคุณคือคลีเมนไทน์。\n「ไม่ต้องตกใจ ฉันแค่อยากทำการทดสอบพิเศษ」\n「ส่วนการทดสอบอะไร เป็นความลับ」คลีเมนไทน์ยิ้มและพูดว่า「สำหรับคุณแล้ว เนื้อหาการทดสอบเพียงอย่างเดียว——」\n「ก็คือการมีชีวิตอยู่」"
  },
  Event_80471_Name = {
    Text = "การทดสอบพิเศษ"
  },
  Event_80472_ChoiceDesc1 = {
    Text = "【ระลึกความหลัง】"
  },
  Event_80472_ChoiceDesc2 = {
    Text = "【ถอนตัวหนอน】"
  },
  Event_80472_Desc = {
    Text = "「โปรดเชื่อเถอะ ฉันไม่มีเจตนาร้าย ฉันแค่ต้องการช่วยคุณ」\nคลีเมนไทน์วิ่งตามคุณและตะโกนเสียงดัง\nเสียงของเธอดูจริงใจอย่างยิ่ง แต่คุณไม่สามารถเชื่ออะไรได้อีกต่อไป\nจริยธรรมของคุณถูกทฤษฎีการรับรู้ที่มีร่างกายทำลายลง และเหตุผลของคุณก็กำลังจะพังทลาย\nคุณต้อง ทำอะไรบางอย่างเพื่อต้านทานเกล็ดหนามที่เติบโตในเนื้อและเลือด ต่อต้านความบ้าคลั่งและความสิ้นหวังที่ค่อยๆ แทรกซึมเข้าสู่จิตวิญญาณ。"
  },
  Event_80472_Name = {
    Text = "วิญญาณที่ดิ้นรน"
  },
  Event_80473_ChoiceDesc1 = {
    Text = "【ออกจาก】ลบการ์ด 2 ใบ"
  },
  Event_80473_Desc = {
    Text = "「ต้องการเก็บรักษาพละกำลังเพื่อเผชิญกับการต่อสู้ครั้งสุดท้ายใช่ไหม?」\n「เป็นทางเลือกที่ชาญฉลาด แต่เมื่อคนเราได้รับสิ่งใดสิ่งหนึ่ง ในขณะเดียวกันก็ต้องสูญเสียไปด้วย」\n「เพราะในโลกที่เผาไหม้และโหดร้ายนี้ การมีชีวิตอยู่เองก็ต้องใช้ราคาที่ต้องจ่าย」"
  },
  Event_80473_Name = {
    Text = "การทดสอบพิเศษ"
  },
  Event_80474_ChoiceDesc1 = {
    Text = "【ละเว้นมัน】ได้รับการแกะสลัก เลือก 1 จาก 3"
  },
  Event_80474_ChoiceDesc2 = {
    Text = "【สัมผัสมัน】การ์ดคำสั่งสุ่ม 1 ใบได้รับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_80474_Desc = {
    Text = "สิ่งแปลกประหลาดที่คล้ายกับสปอร์ดึงดูดความสนใจของคุณ \n มันเหมือนกับแมงกะพรุนที่ประกอบขึ้นจากเนื้อและเลือด หรือเส้นประสาทที่เก็บสัญญาณอยู่ลึกในสมอง \n 「มาสัมผัสฉันสิ」 มันล่อลวงคุณอย่างไร้เสียง 「ฉันจะให้คุณเห็นความทรงจำที่โหดร้าย」"
  },
  Event_80474_Name = {
    Text = "ความทรงจำลึกซึ้ง"
  },
  Event_80475_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับการแกะสลักแบบเลือก 1 จาก 3"
  },
  Event_80475_Desc = {
    Text = "「ราโมน่า, ดอลล์, โลทัน, โอเกียร์…」\nคุณกระซิบซ้ำไปซ้ำมาอย่างวิตกกังวลเกี่ยวกับชื่อเหล่านี้ \nสติของคุณที่พังทลายไม่สามารถนึกถึงรูปลักษณ์ของพวกเขาได้ แต่การมีอยู่ที่ชื่อเหล่านี้เป็นตัวแทนยังคงสามารถทำให้หัวใจและจิตวิญญาณของคุณอบอุ่น \nพวกเขาเคยมีอยู่ พวกเขาเคยหัวเราะ พวกเขา... คือเส้นแบ่งและจุดยึดที่ทำให้คุณรักษาความเป็นมนุษย์ในขณะนี้。"
  },
  Event_80475_Name = {
    Text = "วิญญาณที่ดิ้นรน"
  },
  Event_80476_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งประดิษฐ์เงิน 3 ตัวเลือก 1, ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80476_Desc = {
    Text = "「อ๊ากกกกก——」\nคุณอ้าปากตะโกนเสียงดัง เสียงที่ได้ยินไม่ใช่การตะโกน แต่เหมือนกับเสียงแมลงที่ร้องออกมา\nเกล็ดแมลงที่ถูกดึงออกกลับงอกขึ้นมาใหม่ และสติที่พังทลายก็ไม่กลับมาอีกแล้ว。"
  },
  Event_80476_Name = {
    Text = "วิญญาณที่ดิ้นรน"
  },
  Event_80477_ChoiceDesc1 = {
    Text = "【ออกจาก】ได้รับสิ่งสร้าง「(RelicConfig.Arg1)」，รับสถานะ「(Skill.Arg2)」"
  },
  Event_80477_Desc = {
    Text = "คุณไม่มีการปิดบังใดๆ ทำเต็มที่ ท่าทางนี้ชัดเจนทำให้คลีเมนไทน์มีความสุข。\n「เป็นเด็กดีจริงๆ」\n「ถ้าเป็นแบบนี้ ก็จะให้รางวัลคุณนิดหน่อยนะ แน่นอนว่าต้องมีราคาที่ต้องจ่าย」\n「ในโลกที่โหดร้ายและกำลังเผาไหม้ การมีชีวิตอยู่เองก็ต้องใช้ราคาที่ต้องจ่าย」"
  },
  Event_80477_Name = {
    Text = "การทดสอบพิเศษ"
  },
  Event_80478_ChoiceDesc1 = {
    Text = "【เริ่ม「ทำงาน」】ลบการ์ดคำสั่ง 1 ใบ รับสัญลักษณ์ดำ Arg1"
  },
  Event_80478_ChoiceDesc2 = {
    Text = "【ถอยออกมาให้ห่าง】"
  },
  Event_80478_Desc = {
    Text = "「แชะ。แชะ。」\nเสียงของเครื่องพิมพ์ดีดดังขึ้น, ในขณะที่「งาน」กำลังดำเนินอยู่, คุณก็เป็นเพียงเครื่องมือในการทำ「งาน」เท่านั้น。"
  },
  Event_80478_Name = {
    Text = "ความทรมานไม่มีที่สิ้นสุด"
  },
  Event_80479_ChoiceDesc1 = {
    Text = "【วิ่งไปทางซ้าย】"
  },
  Event_80479_ChoiceDesc2 = {
    Text = "【วิ่งไปทางขวา】"
  },
  Event_80479_Desc = {
    Text = "เงาที่คุ้นเคยติดตามคุณอย่างใกล้ชิด ไม่ใช่หนึ่งหรือสอง แต่เป็นหลายสิบหลายร้อยคน \nทางเดินแคบๆ ไม่สามารถรองรับจำนวนมากขนาดนี้ของ「คลีเมนไทน์」ได้ ดังนั้นจึงมี「คลีเมนไทน์」ถูกผลักลงไป มี「คลีเมนไทน์」ถูกเหยียบจนเละ \nแต่พวกเธอเรียกคุณด้วยเสียงเดียวกัน ซ้ำๆ วลีที่ทำให้คุณตกอยู่ในมลพิษทางจิตใจ \n「ทำไมต้องหนีล่ะ? ฉันแค่อยากให้คุณปรึกษาจิตใจเฉยๆ?」\nและคุณ วิ่งไปตามทางเดินของสถานพักฟื้น เผชิญกับทางเลือกที่แยกออก。"
  },
  Event_80479_Name = {
    Text = "「คลีเมนไทน์」ๆ"
  },
  Event_80480_ChoiceDesc1 = {
    Text = "【เริ่ม「ทำงาน」】ลบการ์ดคำสั่ง 1 ใบ รับสัญลักษณ์ดำ Arg1"
  },
  Event_80480_ChoiceDesc2 = {
    Text = "【ถอยออกมาให้ห่าง】"
  },
  Event_80480_Desc = {
    Text = "「แก้ไข! งาน! อย่าหยุด!」\nเสียงหึ่งนับไม่ถ้วนก้องอยู่ในหูของคุณ ทำให้คุณไม่สามารถต้านทานได้ที่จะเข้าใกล้เครื่องพิมพ์ดีดที่ปรากฏขึ้นอย่างกะทันหันนั้น.\n「จะทำยังไงดี จะทำยังไงดี ทำมาตั้งแต่เช้าจนถึงค่ำ แต่ทำงานไม่เสร็จเลย。」\n「แก้ไข! แก้ไข! แก้ไขแผน, เสนอความต้องการ, ทำงานให้เสร็จ!」\n「ทำงาน! ทำงาน!! ทำงาน!!!」\nจิตวิญญาณที่หึ่งก้องชนกับเครื่องพิมพ์ดีดที่เคาะไม่หยุด สุดท้าย เครื่องพิมพ์ดีดนั้นก็หยุดลง.\nแต่หลังจากนั้นไม่นาน เครื่องพิมพ์ดีดก็กลับมาทำงานอีกครั้ง\n「แก้ไข! งาน! อย่าหยุด!」\nเพราะงานไม่มีที่สิ้นสุด.。"
  },
  Event_80480_Name = {
    Text = "ความทรมานไม่มีที่สิ้นสุด"
  },
  Event_80481_ChoiceDesc1 = {
    Text = "【ตอบตามจริง】"
  },
  Event_80481_ChoiceDesc2 = {
    Text = "【ปฏิเสธการตอบ】"
  },
  Event_80481_Desc = {
    Text = "เพียงชั่วเสี้ยววินาที ทิวทัศน์ตรงหน้าก็กลายเป็นภาพเลือนลางลวงตา\nคุณคิดว่าเป็นเพราะห้องที่บิดเบี้ยวเปลี่ยนแปลง แต่ต่อมา คุณจึงเข้าใจว่านั่นเป็นเพราะเส้นประสาทตาของคุณถูกบุกรุก\n「เราเจอกันอีกแล้วนะ」\nในสายตาที่พร่ามัว เคลเมนทีนยิ้มอย่างแผ่วเบา\n「ถึงแม้ว่าจะได้พบเร็วกว่าที่คิดไว้ แต่ฉันก็ยังดีใจอยู่ ไม่ทราบว่า %player% เธอเองรู้สึกแบบนั้นหรือเปล่า?」"
  },
  Event_80481_Name = {
    Text = "การเรียกในความฝัน"
  },
  Event_80595_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80595_Desc = {
    Text = "\nต่อหน้าการไล่ล่าของคุณ ผีเสื้อไม่แสดงอาการใด ๆ \nมันตามติดมือคุณอย่างดื้อรั้น และสูญเสียลมหายใจในฝ่ามือของคุณ \n「อา อุ่นมาก......」\nนี่คือเสียงสุดท้ายของมัน。"
  },
  Event_80595_Name = {
    Text = "ความฝันของผีเสื้อ"
  },
  Event_80596_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80596_Desc = {
    Text = "「ฉันอยากให้ดอกไม้บานสะพรั่งตลอดไป ฉันอยากให้รอยยิ้มคงอยู่ตลอดกาล.」\n「ฉันอยากให้ทุกคนที่เป็นโรคการย่อยสลายหายดีและปลอดภัย ฉันอยากให้โลกใบนี้กลับคืนสู่อดีต ไม่ต้องเผาไหม้อีกต่อไป.」\n「ฉันอยากให้...」\nผีเสื้อเล็กๆ กระพือปีกอยู่ในฝ่ามือของคุณ สูญเสียชีวิตชีวาไป\nอย่างน้อยก็มีคนที่ได้ฟังเสียงของมัน."
  },
  Event_80596_Name = {
    Text = "ความฝันของผีเสื้อ"
  },
  Event_80597_ChoiceDesc1 = {
    Text = "【ไล่ผีเสื้อ】การ์ดคำสั่งสุ่ม 1 ใบรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_80597_ChoiceDesc2 = {
    Text = "【ฟังความปรารถนา】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบได้รับออริซอน：「(EnchantConfig.Arg1)」"
  },
  Event_80597_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_80597_Desc = {
    Text = "ผีเสื้อเล็กๆก็มีความฝันมากมาย.\nความฝันเหล่านี้กระจัดกระจายอยู่ในทุ่งดอกไม้,      ในห้องคนป่วย,      และบน@2แท่นบูชาที่เต็มไปด้วยเนื้อและเลือด.\nในวันนี้มันได้รอคอยคนที่ผูกพันกับมันในที่สุด ไม่รู้ว่าคุณจะยินดีรับฟังความปรารถนาเล็กๆ ที่เล็กน้อยของมันหรือไม่."
  },
  Event_80597_Name = {
    Text = "ความฝันของผีเสื้อ"
  },
  Event_80610_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80610_Desc = {
    Text = "「ความมีเหตุผลเหรอ？คำตอบที่น่าสนใจ。」\n「หวังว่าคุณจะไม่เสียใจเกี่ยวกับการเลือกของคุณ。」"
  },
  Event_80610_Name = {
    Text = "ราคาที่ต้องจ่ายของความเป็นมนุษย์"
  },
  Event_80612_ChoiceDesc1 = {
    Text = "【ให้อาหารพวกเขา】ได้รับของโบราณเงิน「(RelicConfig.Arg1)」เลือกติดเชื้อ 1 ครั้งอาการ"
  },
  Event_80612_ChoiceDesc2 = {
    Text = "【ไม่มีการสนใจ】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับคำอธิษฐาน:「(EnchantConfig.Arg1)」, ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_80612_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_80612_Desc = {
    Text = "ผู้อยู่อาศัยมาแล้วจากไป แต่ฝูงหนูยังอยู่ยืนนาน\nเมื่อเทียบกับมนุษย์แล้ว พวกมันต่างหากคือ 「ผู้อยู่ที่แท้จริง」 ของปราสาทเก่าแก่แห่งนี้\nแต่พวกมันไม่มีข้อขัดแย้งใดๆ กับการเข้ามาของมนุษย์\nเพราะเหล่าสิ่งขาวนุ่มนิ่ม กลิ่นหอม ที่ดูแปลกประหลาดเหล่านั้น ชอบโยนอาหารที่หอมขาวนุ่มนิ่มและประหลาดอยู่เสมอมาให้พวกมัน\n「แล้วเจ้า สิ่งประหลาด เจ้าเป็นพวกแบบไหนกัน?」"
  },
  Event_80612_Name = {
    Text = "ความลับของปราสาทโบราณ"
  },
  Event_80613_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80613_Desc = {
    Text = "\nเสียงหัวเราะอ่อนโยนดังมาจากความมืด。\n「ฉันรอคุณ, มาเจอฉัน。」\n「หนอนตัวน้อยผู้กล้าหาญ。」"
  },
  Event_80613_Name = {
    Text = "「เธอ」มองลับ"
  },
  Event_80614_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80614_Desc = {
    Text = "「หุบปากหุบปาก เสียงน่ารังเกียจจริงๆ。」\nแมวดำทำท่าปิดหูอย่างมีมนุษยธรรม。\n「มนุษย์ ภาษาแมวของคุณแย่มาก พูดอะไรไม่เป็นเรื่องเป็นราว!」\nแม้จะพูดแบบนี้ แต่สีหน้าของแมวดำกลับสงบลง。\n「เห็นแก่ที่คุณร้องเมี้ยวเพื่อทำให้ฉันพอใจ ฉันจะให้ของขวัญกับคุณ。」\n「ส่วนเนื้อหาของของขวัญขึ้นอยู่กับโชคของคุณ。」"
  },
  Event_80614_Name = {
    Text = "นิเกลแมน"
  },
  Event_80615_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80615_Desc = {
    Text = "\n「แม่ หลังจากที่สูญเสียเพื่อน สามี และลูกชาย ฉันก็ได้สูญเสียไดอานา ลูกสาวตัวน้อยของฉันไปตลอดกาล」\n「เมื่อเธอกลายเป็นเถ้าถ่านต่อหน้าฉัน สมองของฉันว่างเปล่า……」ลายมือถัดไปไม่สามารถอ่านได้ชัดเจน\nคุณจึงต้องเปลี่ยนไปอ่านบรรทัดถัดไป\nฉันได้ตัดสินใจแล้ว ถ้าหากได้พบกันอีกครั้ง อย่าตำหนิฉันเลย ฉันแค่... คิดถึงพวกคุณมากเกินไป。"
  },
  Event_80615_Name = {
    Text = "ความคิดถึงที่จางหาย"
  },
  Event_80616_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80616_Desc = {
    Text = "การไล่ของคุณได้ผล ร่างกายบางส่วนที่มองไม่เห็นรูปพรรณกำลังบิดเบือนหนีไป ในขณะที่ส่วนใหญ่ยังคงอยู่ที่เดิม \n พวกเขาไม่หัวเราะอีกต่อไป ไม่ได้ขับร้องอีก แต่กลับร้องไห้เสียงดัง \n เสียงร้องไห้ของเด็กดังขึ้นข้างหูคุณ เพียงพูดซ้ำประโยคเดียว \n「ฆ่ามอนสเตอร์ให้ตาย!」"
  },
  Event_80616_Name = {
    Text = "วัยเด็กของ「เขา」"
  },
  Event_80617_ChoiceDesc1 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80617_ChoiceDesc2 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80617_ChoiceDesc3 = {
    Text = "【ออก】การติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80617_Desc = {
    Text = "คุณให้อาหารเพื่อเอาใจฝูงหนู\nฝูงหนูจำนวนมหาศาลเคลื่อนไหวอย่างว่องไว มอบของขวัญให้คุณซึ่งถูกห่อไว้อย่างหยาบกระด้าง\nคุณไม่สามารถมองเห็นรูปลักษณ์ของของขวัญนั้นได้ เพียงแต่เห็นเลือดจำนวนมากที่ซึมเปื้อนอยู่บนห่อของขวัญนั้น。"
  },
  Event_80617_Name = {
    Text = "ความลับของปราสาทโบราณ"
  },
  Event_80618_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80618_Desc = {
    Text = "「……」\n「…………」\n「………………」\nเงาดำเงียบอยู่ เขาต้องการร้องไห้ แต่กลับสูญเสียความสามารถในการหลั่งน้ำตาไปแล้ว。\nในที่สุด เขาก็แค่ถอนหายใจลึกๆ。\n「เพื่อน ขอให้คุณสามารถปกป้องสิ่งที่มีค่าที่สุดของคุณได้」"
  },
  Event_80618_Name = {
    Text = "คนว่าง"
  },
  Event_80619_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80619_Desc = {
    Text = "การดุของคุณไม่มีผลอะไร กลับทำให้พวกเขาตื่นเต้นและมีความสุขมากขึ้น \n เสียงหัวเราะและการขับร้องยิ่งดังขึ้นเรื่อย ๆ ร้องเพลงเด็กอีกเพลงหนึ่ง \n「วิลเลียมตัวน้อย อาศัยอยู่ในปราสาท กินหนูมนุษย์ วิ่งอยู่ในกำแพง.\n เมื่อถึงเวลาที่มีการบูชายัญ ทุกคนจะถูกกัดจนล้มลง」"
  },
  Event_80619_Name = {
    Text = "วัยเด็กของ「เขา」"
  },
  Event_80620_ChoiceDesc1 = {
    Text = "【หลีกเลี่ยงสายตา】การฟื้นคืนแบบสุ่มของ 1 ร่างกายที่ตื่นขึ้น"
  },
  Event_80620_ChoiceDesc2 = {
    Text = "【จ้องมองตรง】เลือกร่างกายที่ตื่นขึ้น 1 ตน และลดการใช้พลังการคำนวณของบัตรปลุกลง 2 หน่วย ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80620_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_80620_Desc = {
    Text = "ทุกสิ่งในสถานพักฟื้นอยู่ภายใต้การควบคุมและมองลับของเธอ แน่นอนว่าคุณก็อยู่ด้วย \n แต่เธอพร้อมที่จะเปิดตาข้างหนึ่งและปิดตาข้างหนึ่งเพื่อคุณ \n เพราะท้ายที่สุด เกมต้องมีไปมีมา ถึงจะสนุกมากขึ้น。"
  },
  Event_80620_Name = {
    Text = "「เธอ」มองลับ"
  },
  Event_80621_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80621_Desc = {
    Text = "คุณวางซองจดหมายกลับที่เดิมเตรียมจะจากไป แต่ทันใดนั้นก็ได้ยินเสียงกระซิบที่แปลกประหลาด \n「ตามคำขอของฉัน หมอคลีเมนไทน์ในที่สุดก็ยอมเปิดปาก \nเธอได้บรรยายให้ฉันฟังถึงจักรวาลอันกว้างใหญ่ และในจักรวาลลึกลับนั้น จะต้องมีวิธีการที่จะช่วยพวกคุณกลับมาได้ \nฉันได้เตรียมพร้อมสำหรับ「 ใหม่เกิด 」แล้ว ไม่ว่าจะต้องล่องลอยไปกี่ปีแสง ฉันก็ปรารถนาที่จะได้พบพวกคุณอีกครั้ง」"
  },
  Event_80621_Name = {
    Text = "ความคิดถึงที่จางหาย"
  },
  Event_80622_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80622_Desc = {
    Text = "หมอคลีเมนไทน์ช่วยชีวิตฉันไว้ \n เธอเป็นคนที่ดีมาก ๆ และยินดีที่จะฟังเสียงของฉัน \n ฉันอยากจะพูดเรื่องราวที่มีความสุขและสนุกสนาน แต่ในขณะนี้ ฉันมีแต่ความเจ็บปวดและความสิ้นหวัง \n เกรงว่าฉันจะทำให้ความตั้งใจของหมอผิดหวัง \n หลังจากที่ฉันสูญเสียพวกคุณ ชีวิตสำหรับฉันก็มีแต่ความแห้งแล้ง。"
  },
  Event_80622_Name = {
    Text = "ความคิดถึงที่จางหาย"
  },
  Event_80623_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80623_Desc = {
    Text = "「เธอ, เธอ...」\n「ฮึ่ม เทคนิคใช้ได้ไม่เลวเลย คราวนี้ถือว่าผ่านไปแล้ว แต่ครั้งหน้าคงไม่ง่ายขนาดนี้แน่!」\nวิฬารดำกระโดดไปข้างหน้าอย่างคล่องแคล่วแล้ววิ่งหายไป。"
  },
  Event_80623_Name = {
    Text = "นิเกลแมน"
  },
  Event_80624_ChoiceDesc1 = {
    Text = "【โจมตีแมวดำ】มีโอกาส 50% ที่จะได้รับสัญลักษณ์ดำ 125 ใบ และ 50% ที่จะติดเชื้อ「(Skill.Arg2)」"
  },
  Event_80624_ChoiceDesc2 = {
    Text = "【เรียนเสียงแมว】มีโอกาส 75% ที่จะได้รับสัญลักษณ์ดำ 100 ใบ และ 25% ที่จะติดเชื้อ「(Skill.Arg2)」"
  },
  Event_80624_ChoiceDesc3 = {
    Text = "【ลองเลี้ยงแมว】ได้รับสัญลักษณ์ดำ 50 ใบ"
  },
  Event_80624_Desc = {
    Text = "「เฮ้! คุณ ห้ามเดินต่อ」\nแมวดำกระโดดออกมาอย่างกะทันหัน ขวางทางไม่ให้คุณเดินต่อไป\nพวกมันเลียกรงเล็บอย่างสง่างาม ท่าทางแสดงออกถึงความหยิ่งผยองและภูมิใจ\n「ข้างหน้ามีอันตรายมากมาย ไม่ใช่คนที่อ่อนแออย่างคุณที่จะสำรวจได้」\nคุณแสดงให้เห็นถึงความตั้งใจที่จะเดินต่อไป ในขณะนั้น ตาของแมวดำนำกลายเป็นแนวตั้งเลื่อนกลับไปมา แสดงให้เห็นถึงธรรมชาติที่โหดร้ายในการเล่นกับเหยื่อ「งั้นก็แสดงให้เราเห็นถึงความตั้งใจของคุณสิ」"
  },
  Event_80624_Name = {
    Text = "นิเกลแมน"
  },
  Event_80625_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80625_Desc = {
    Text = "\nความไม่สนใจของคุณทำให้ฝูงหนูโกรธ มันร้องเสียงดังพุ่งเข้าหาคุณ แต่คุณได้วิ่งหนีไปไกลก่อนที่ฝูงหนูจะเคลื่อนไหว。"
  },
  Event_80625_Name = {
    Text = "ความลับของปราสาทโบราณ"
  },
  Event_80626_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80626_Desc = {
    Text = "「อา ใช่แล้ว พังปีกของฉันเถอะ」\n「เวลา สุขภาพ ศักดิ์ศรี ชีวิต พวกเขาได้ฉกฉวยจากฉันไปมากเกินไป」\n「ความฝันสุดท้ายนี้ แน่นอนว่าก็ไม่ใช่ของฉัน」\n「เพราะว่าฉันเป็นเพียงนกที่ถูกกักขังและสูญเสียอิสรภาพ」"
  },
  Event_80626_Name = {
    Text = "คนว่าง"
  },
  Event_80627_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80627_Desc = {
    Text = "「มีอารมณ์เหรอ? เป็นคำตอบที่น่าสนใจ。」\n「หวังว่าคุณจะไม่เสียใจสำหรับการเลือกของคุณ。」"
  },
  Event_80627_Name = {
    Text = "ราคาที่ต้องจ่ายของความเป็นมนุษย์"
  },
  Event_80628_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80628_Desc = {
    Text = "「ฉันยอมรับคำขอของคุณ。」\nเสียงหึ่งเข้ามาใกล้ ผ่านช่องหูค่อยๆ เจาะเข้าสู่สมองของคุณ.\nสมองของคุณสั่นสะเทือน และในความสั่นสะเทือนนี้ คุณได้ยิน「เสียง」ของจักรวาล.\n「เชื่อมต่อกับฉัน」"
  },
  Event_80628_Name = {
    Text = "การไถ่บาปแห่งความมืด"
  },
  Event_80629_ChoiceDesc1 = {
    Text = "【อธิษฐาน】ปลุกเสกผู้ปลุกเสก 1 คนแบบสุ่ม ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80629_ChoiceDesc2 = {
    Text = "【ปฏิเสธ】ได้รับสูงสุด 3 ออริซอน"
  },
  Event_80629_Desc = {
    Text = "「ไม่ควรจะเป็นแบบนี้ ไม่ควรจะเป็นแบบนี้」  \n「ฉันน่ะ ควรจะหลุดพ้นจากสิ่งมีชีวิตชั้นต่ำอย่างมนุษย์นี้ เพื่อวิวัฒนาการเป็นสิ่งมีชีวิตที่สูงขึ้น...」  \nในความมืด เสียงสะอื้นด้วยความเจ็บปวดดังขึ้น  \nเสียงสะอื้นเหล่านั้นรวมตัวกัน ก่อตัวเป็นเสียงหึ่งๆ ขนาดมหึมา  \n「โลกที่กำลังลุกไหม้แห่งนี้ เปรียบได้กับหลุมดำที่ไม่รู้จักพอ กลืนกินทุกคน ดังนั้น——」  \n「จงขอพรต่อข้า จักรวาลอันไร้ที่สิ้นสุดจะมอบการไถ่บาปให้แก่เจ้า」"
  },
  Event_80629_Name = {
    Text = "การไถ่บาปแห่งความมืด"
  },
  Event_80630_ChoiceDesc1 = {
    Text = "【เปิดซองจดหมาย】ได้รับของโบราณทอง「(RelicConfig.Arg1)」ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_80630_ChoiceDesc2 = {
    Text = "【อ่าน】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับการแกะสลัก：「(EnchantConfig.Arg1)」"
  },
  Event_80630_ChoiceDesc3 = {
    Text = "【นำกลับไปที่เดิม】ได้รับสัญลักษณ์ดำ 50 ใบ"
  },
  Event_80630_Desc = {
    Text = "ในมุมที่ไม่มีใครสนใจ มีจดหมายตกอยู่แผ่นหนึ่ง.\nตัวอักษรบนจดหมายหลายตัวไม่สามารถอ่านออกได้ แต่มีอยู่คำหนึ่งที่ชัดเจน.\nคำนั้นคือ「แม่」。"
  },
  Event_80630_Name = {
    Text = "ความคิดถึงที่จางหาย"
  },
  Event_80631_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80631_Desc = {
    Text = "「ฮึ มนุษย์ที่เล็กน้อย นายทำการเลือกที่ผิดพลาด」\nวิฬารมองดูนายอย่างเย็นชา และจู่โจมอย่างกะทันหัน \n「นายต้องจ่ายค่าตอบแทน——แน่นอนว่า เราก็เคารพผู้แข็งแกร่ง」"
  },
  Event_80631_Name = {
    Text = "นิเกลแมน"
  },
  Event_80632_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80632_Desc = {
    Text = "\nเสียงหัวเราะอ่อนโยนดังมาจากความมืด。\n「ฉันรอคุณ, มาเจอฉัน。」\n「หนอนตัวน้อยน่ารัก。」"
  },
  Event_80632_Name = {
    Text = "「เธอ」มองลับ"
  },
  Event_80633_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80633_Desc = {
    Text = "ภายใต้การโจมตีของคุณ เงาแปลกประหลาดเหล่านี้ finalmente หนีไปแล้ว \n รอบข้างเงียบสงบ มีเพียงการเต้นของหัวใจคุณที่ร้องไห้อย่างเงียบ ๆ \n ที่แท้ นี่คือวัยเด็กของ「เขา」"
  },
  Event_80633_Name = {
    Text = "วัยเด็กของ「เขา」"
  },
  Event_80635_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80635_Desc = {
    Text = "「อ้า กับดักข้อความเล็กๆ ถูกเปิดเผยแล้ว。」\n「นี่คือรางวัล เพราะว่า...」\n「ไม่ใช่ทุกครั้งที่เลือก จะต้องเลือกเสมอ。」"
  },
  Event_80635_Name = {
    Text = "ราคาที่ต้องจ่ายของความเป็นมนุษย์"
  },
  Event_80636_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80636_Desc = {
    Text = "「@3ผู้ฝ่าฝืน」\nเสียงหึ่งเริ่มอ่อนแอลงจนหายไป ทิ้งไว้เพียงคำพูดสุดท้าย\n「รักษามนุษยชาติ แต่ไม่สามารถมีชีวิตอยู่ในโลกที่โหดร้ายนี้ได้」"
  },
  Event_80636_Name = {
    Text = "การไถ่บาปแห่งความมืด"
  },
  Event_80637_ChoiceDesc1 = {
    Text = "【เลือกปฏิเสธ】ลบการ์ดคำสั่ง 1 ใบ รับสัญลักษณ์ดำ Arg1"
  },
  Event_80637_ChoiceDesc2 = {
    Text = "【เลือกเชื่อฟัง】คัดลอกการ์ดคำสั่ง 1 ใบ ติดเชื้อ「(Skill.Arg1)」"
  },
  Event_80637_ChoiceDesc3 = {
    Text = "【เลือกกอด】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบได้รับออริซอน：「(EnchantConfig.Arg1)」"
  },
  Event_80637_Desc = {
    Text = "「ฉันคือนกในกรง ถูกขังอยู่ในลานที่เต็มไปด้วยห้องมากมาย」\nในความมืดมีเงาคนที่ไม่ชัดเจนเดินไปมา นั่นคือความหลงใหลที่เหลืออยู่จากผู้ที่จากไป\n「พวกเขาบอกว่านี่คือโรงพยาบาลจิตเวช แต่ฉันรู้ว่านี่คือกรงพิเศษของมนุษย์ ที่กักขังนกอิสระที่ไม่ยอมปฏิบัติตามกฎของสังคม」\n「แต่นกถ้าไม่สามารถบินได้ ยังจะเรียกว่านกอยู่ไหม?」\nความหลงใหลต่างๆเข้าหาคุณ ส่งเสียงขอความช่วยเหลือเพื่อไถ่บาป\n「โปรดหักปีกของฉัน ฉันเบื่อหน่ายกับการบินแล้ว」"
  },
  Event_80637_Name = {
    Text = "คนว่าง"
  },
  Event_80638_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_80638_Desc = {
    Text = "「……」\n「…………」\n「………………」\nเงาดำสั่นไหวอย่างกระทันหันและละลายเข้าไปในร่างกายของคุณ。\n「เพื่อน，จงก้าวไปข้างหน้า เพื่อปกป้องสิ่งที่มีค่าที่สุดของตัวเอง。」\n「แม้ว่าเราจะจากไปแล้ว แต่ยังคงเต็มใจที่จะฝันให้กับคุณ และมอบพรสุดท้ายให้กับคุณ。」"
  },
  Event_80638_Name = {
    Text = "คนว่าง"
  },
  Event_80639_ChoiceDesc1 = {
    Text = "【เลือกอารมณ์】ฟื้นฟู Arg1 คะแนนชีวิต"
  },
  Event_80639_ChoiceDesc2 = {
    Text = "【รักษาสติ】การ์ดคำสั่ง 1 ใบแบบสุ่มได้รับออริซอน：「(EnchantConfig.Arg1)」"
  },
  Event_80639_ChoiceDesc3 = {
    Text = "【ปฏิเสธการเลือก】ได้รับสัญลักษณ์ดำ 25 ใบ"
  },
  Event_80639_Desc = {
    Text = "「เลือกเถอะ เลือกเถอะ」\nในความมืดที่วิ่งไปมา เสียงกระซิบมากมายดังขึ้นมา\nเสียงนี้อ่อนโยนและมีเสน่ห์ มันเหมือนมีพลังมหาศาล ทำให้คุณเกิดภาพหลอนที่บ้าคลั่ง\nสมองของคุณจมอยู่ในความบ้าคลั่ง เคลื่อนไหวออกจากร่างกาย ขณะที่หัวใจดูเหมือนจะเกิดความรู้สึกบางอย่าง ตะโกนเรียกคุณ\n「เลือกเถอะ เลือกเถอะ」\n「รักษาเหตุผลหรือความรู้สึก คุณต้องทำการเลือก」"
  },
  Event_80639_Name = {
    Text = "ราคาที่ต้องจ่ายของความเป็นมนุษย์"
  },
  Event_80641_ChoiceDesc1 = {
    Text = "【ดุ「พวกเขา」】ติดเชื้อ「(Skill.Arg1)」ได้รับของโบราณที่ถูกสาป「(RelicConfig.Arg2)」"
  },
  Event_80641_ChoiceDesc2 = {
    Text = "【ขับไล่「พวกเขา」】ติดเชื้อ 2 ครั้ง「(Skill.Arg1)」ได้รับของโบราณเงิน「(RelicConfig.Arg2)」และ「(RelicConfig.Arg3)」"
  },
  Event_80641_ChoiceDesc3 = {
    Text = "【โจมตี「พวกเขา」】ได้รับของโบราณเงิน「(RelicConfig.Arg1)」"
  },
  Event_80641_Desc = {
    Text = "「วิลเลียมตัวน้อย เป็นตัวประหลาด นอนในหลุมฝังศพ ไม่มีใครรัก อย่าเข้าใกล้ ระวังเขาจะทำร้ายลับๆ」\nร่างกายที่ไม่เห็นรูปร่างบิดเบี้ยว แต่เสียงเหมือนกับเด็กเล็ก\nพวกเขาหัวเราะอย่างสนุกสนาน ร้องเพลงด้วยเสียงเสียดสี และมองคุณด้วยสายตาเหยียดหยามและกระตือรือร้น\nเต็มไปด้วยความชั่วร้าย。"
  },
  Event_80641_Name = {
    Text = "วัยเด็กของ「เขา」"
  },
  Event_90571_ChoiceDesc1 = {
    Text = "【เพลิดเพลินกับมัน】ใส่ 1 การ์ด「การปรุงบริการคืนวิญญาณ」ลงในกองไพ่。"
  },
  Event_90571_Desc = {
    Text = "โต๊ะอาหารที่หรูหรา ลานเต้นรำที่คึกคัก เครื่องใช้บนโต๊ะอาหารที่ประณีต และกลิ่นหอมของร่างกาย...\nโอ้ ฉันรู้ว่าคุณคงรอไม่ไหวแล้ว แต่กรุณารอสักครู่ครับ แขกผู้มีเกียรติ\nเครื่องดื่มที่เจ้าภาพจัดเตรียมพิเศษนี้ เป็นของขวัญที่มอบให้แขกผู้มีเกียรติเท่านั้น\nจับมันไว้ ดื่มมัน ในรสชาติที่เหลืออยู่ เพลิดเพลินไปกับความปิติสุขในงานเลี้ยงนี้เถอะ!"
  },
  Event_90571_Name = {
    Text = "พิธีกรรมก่อนเลี้ยงฉลอง"
  },
  Event_91460_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91460_Desc = {
    Text = "คุณไม่สามารถต้านทานได้ ต้องปล่อยให้เสียงเจาะทะลุเข้าไป\nเสียงร้องแหลมคมได้ผ่าออกจากสมองของคุณ ความกลัวที่ถูกลืมบางอย่างไหลออกมา และคุณรู้สึกถึงความหิวโหยของมัน\nสิ่งมีชีวิตที่น่ากลัวที่กินเนื้อ..."
  },
  Event_91460_Name = {
    Text = "การสารภาพที่เงียบเชียบ"
  },
  Event_91461_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91461_Desc = {
    Text = "คุณไม่สามารถควบคุมตัวเองได้อีกต่อไป ปล่อยให้ความร้อนแรงนั้นหลุดออกมาอย่างเต็มที่ คำพูดที่ยังไม่ได้พูดทั้งหมดพุ่งออกมาจากศีรษะของคุณอย่างต่อเนื่อง \n คุณรู้สึกถึงแรงบันดาลใจที่น่าอัศจรรย์ หลงใหลในความสามารถของพิคแมน。"
  },
  Event_91461_Name = {
    Text = "ภูเขาไฟที่หลับใหล"
  },
  Event_91462_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91462_Desc = {
    Text = "เปลวไฟพันกันกับหมึกทิ้งรอยเลือดเปรอะเปื้อนไว้ \n ในช่วงเวลานั้น คุณตกอยู่ที่ขอบของความฝันและความจริง คุณเห็นตัวเองกลายเป็นเด็กหญิงคนหนึ่ง จับมือดูเรซินและเต้นรำด้วยกัน \n เมื่อคุณตื่นขึ้นมาและมองไปที่ดูเรซินอีกครั้ง ความเศร้าโศกหนักหน่วงได้เข้ามาครอบงำสมองของคุณ。"
  },
  Event_91462_Name = {
    Text = "การเปิดเผยของความฝัน"
  },
  Event_91463_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91463_Desc = {
    Text = "คุณวิ่งเข้าไป เปลวไฟหายไปในผิวหนังของคุณ สำหรับภาพนั้น ใครๆ ก็มองว่าเป็นเพียงภาพเหมือนที่ธรรมดาเท่านั้น \nในความฝันหลังจากนี้ คุณมักจะเห็นตัวเองที่กำลังเผาไหม้อยู่ ได้รับความร้อนที่พอเหมาะ แล้วในวันหนึ่งก็จะถูกนำไปตั้งบนโต๊ะอาหารของคุณเอง。"
  },
  Event_91463_Name = {
    Text = "ภาพเหมือนลุกไหม้"
  },
  Event_91464_ChoiceDesc1 = {
    Text = "【ฟัง】ได้รับสัญลักษณ์ดำ 30 ตัว，ติดเชื้อ「(Skill.Arg2)」，เลือกต่อ"
  },
  Event_91464_ChoiceDesc2 = {
    Text = "【ละเว้น】ออก"
  },
  Event_91464_Desc = {
    Text = "ในความเงียบที่วุ่นวาย คุณค่อย ๆ เข้าใจคำพูดของอีกาผู้นั้น…"
  },
  Event_91464_Name = {
    Text = "การสารภาพที่เงียบเชียบ"
  },
  Event_91465_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91465_Desc = {
    Text = "คุณหยิบก้อนหินขึ้นมา ทำให้เงาหนูที่กำลังจดจ่อกัดกร่อนต้องสะดุ้งเฮือก。\nพวกมันมองตาคุณอย่างตะกละตะกลาม。\nคุณได้กลิ่นอับชื้นและสกปรกจากพวกมัน ราวกับเป็นลางบอกเหตุอะไรบางอย่าง。"
  },
  Event_91465_Name = {
    Text = "อาณาจักรที่ถูกเนรเทศ"
  },
  Event_91466_ChoiceDesc1 = {
    Text = "【ฟัง】ได้รับสัญลักษณ์ดำ 25 ตัว，ติดเชื้อ「(Skill.Arg2)」，เลือกต่อ"
  },
  Event_91466_ChoiceDesc2 = {
    Text = "【ละเว้น】ออก"
  },
  Event_91466_Desc = {
    Text = "มันกำลังต้อนรับ คุณต้อนรับใคร?\nแน่นอนคือคุณ!\nอาจจะมันเห็นคุณเป็นอาหารมื้อค่ำของวันพรุ่งนี้"
  },
  Event_91466_Name = {
    Text = "การสารภาพที่เงียบเชียบ"
  },
  Event_91467_ChoiceDesc1 = {
    Text = "【กรีดฝ่ามือ】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91467_ChoiceDesc2 = {
    Text = "【ยอมรับการเติบโต】ได้รับของโบราณเงิน「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91467_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_91467_Desc = {
    Text = "ผีเสื้อตัวนั้นไม่ได้บินมา แต่ค่อยๆ เติบโตขึ้นจากฝ่ามือของคุณ\nตอนแรกคุณคิดว่าเป็นแค่เหงื่อ แต่กลับเห็นของเหลวสีดำราวกับเส้นเลือดที่ค่อยๆ ซึมออกมาผ่านร่องนิ้วของคุณ ก่อรวมตัวเป็นปีกที่เย็นเยียบและเต้นกระพือ\nทุกครั้งที่มันกระพือปีก มันก็ทำให้เกิดระลอกในเลือดของคุณ。"
  },
  Event_91467_Name = {
    Text = "ปรสิตชนชั้นสูง"
  },
  Event_91468_ChoiceDesc1 = {
    Text = "【ช่วยเหลือภาพเหมือน】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91468_ChoiceDesc2 = {
    Text = "【ยอมรับความว่างเปล่า】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91468_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ 25 รอยดำ"
  },
  Event_91468_Desc = {
    Text = "คุณยืนอยู่ต่อหน้าของขวัญจากพิคแมน \n นั่นคือภาพวาดที่สร้างจากเลือดสด เปลวไฟสีดำมืดกำลังลุกไหม้อย่างเงียบ ๆ \n ผ่านทางเบ้าตาที่ว่างเปล่าของตัวละครในภาพ คุณเห็นว่า— \n ความทรงจำของคุณกำลังพลุ่งพล่านและลุกไหม้ ยืดออก บิดเบือน เปล่งประกาย ราวกับไฟที่มองไม่เห็นกำลังเลียทางเดินในสมองของคุณ ในช่วงที่สับสน คุณได้ยินเสียงคนพูด \n 「ถึงเวลาลงหม้อแล้ว อุณหภูมินี้พอดี」 \n นี่คือภาพความทรงจำที่คุณวาดขึ้นเอง คุณกำลังดิ้นรนและเปลี่ยนแปลงในเปลวไฟ。"
  },
  Event_91468_Name = {
    Text = "ภาพเหมือนลุกไหม้"
  },
  Event_91469_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91469_Desc = {
    Text = "คุณปฏิเสธที่จะรับสาย เงียบมองมันสั่นจนหยุด。\nตลอดหลายปีมานี้ คุณได้เรียนรู้ที่จะต่อสู้กับความบ้า。"
  },
  Event_91469_Name = {
    Text = "การโทรที่พลาด"
  },
  Event_91470_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91470_Desc = {
    Text = "คุณถอยหลังไปหนึ่งก้าว ปล่อยให้ผืนผ้าถูกไฟเผาไหม้。\nคุณเห็นตัวเองถูกไฟทำให้กลายเป็นสีน้ำตาลทองที่น่าดึงดูด ไขมันเริ่มแตกออกมาเสียงดังเป๊าะแป๊ะ ราวกับว่าคุณสามารถดมกลิ่นเนื้อผ่านผืนผ้าได้。\nดูเรซินรู้สึกถึงสิ่งล่อลวงแบบนี้ใช่ไหม?"
  },
  Event_91470_Name = {
    Text = "ภาพเหมือนลุกไหม้"
  },
  Event_91471_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91471_Desc = {
    Text = "ด้วยความอยากรู้อยากเห็นที่เกือบจะดูหมิ่น หรือความกล้าหาญในการต่อสู้กับสิ่งที่ไม่รู้จัก คุณค้นหาการเปิดเผยในภาพลวงตาในอดีต \n คุณเห็นเด็กหญิงคนหนึ่งเต้นรำกับผู้ชายที่มีรูปร่างคลุมเครือข้างๆ ความสุขที่ไม่สามารถอธิบายได้เต็มเปี่ยมอยู่ในหัวใจของคุณ。"
  },
  Event_91471_Name = {
    Text = "เงาของอดีต"
  },
  Event_91472_ChoiceDesc1 = {
    Text = "【ยกเลิกการบันทึก】ลบการ์ด 2 ใบ"
  },
  Event_91472_ChoiceDesc2 = {
    Text = "【ต่อไปนี้】ได้รับของโบราณที่ถูกสาป「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91472_ChoiceDesc3 = {
    Text = "【ออกจาก】ได้รับ Arg1 รอยดำ"
  },
  Event_91472_Desc = {
    Text = "ในที่สุดคุณก็หลุดพ้นจากตลาดของผีดิบและหามุมเงียบๆ เพื่อจดบันทึกตามปกติ\nเครื่องพิมพ์ดีดเริ่มสั่นคลอนอย่างรุนแรง ปุ่มกดขึ้นลงเอง และของเหลวสีดำพุ่งออกมาจากช่องว่าง เปียกชุ่มสติของคุณ\nคุณมองเห็นภาพเงาของผีเสื้อค่อยๆ ปรากฏขึ้นบนกระดาษ…"
  },
  Event_91472_Name = {
    Text = "เงาผีเสื้อซ้อนทับกัน"
  },
  Event_91473_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91473_Desc = {
    Text = "แปลกมากที่แม้จะเป็นภาษาที่ไม่เคยเรียนรู้ แต่คุณกลับเหมือนเข้าใจความหมายในนั้นได้\nวรรคกลอนเต็มไปด้วยความคิดถึงญาติพี่น้อง ความคิดถึงนี้ข้ามผ่านชีวิตและความตายและถูกส่งต่อในความฝันของคุณ\nคุณสามารถจำตัวอักษรที่อยู่ปลายวรรคได้อย่างคลุมเครือ\nคือ「เซลีเน」"
  },
  Event_91473_Name = {
    Text = "การเปิดเผยของความฝัน"
  },
  Event_91474_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91474_Desc = {
    Text = "คุณกัดฟันเปิดผิวหนังที่ฝ่ามือ ใช้เปลวไฟเผาเนื้อที่เกิดใหม่\nของเหลวสีดำพวยพุ่งออกมา ผีเสื้อแตกสลาย\nทุกอย่างกลายเป็นสะอาดปราศจากร่องรอย แต่คุณกลับรู้สึกว่ามีเสียงกระพือปีกเบาๆ ส่งผ่านมาจากฝ่ามือ เหมือนกับความคิดที่ยังไม่ฟักออกมาอย่างสมบูรณ์ ยังคงหายใจช้าๆ อยู่ในหลอดเลือดของคุณ\nดูเรซินไม่แสดงความคิดเห็นเกี่ยวกับเรื่องนี้ เพียงแค่ต้องการเลือดสดที่คุณทิ้งไว้。"
  },
  Event_91474_Name = {
    Text = "ปรสิตชนชั้นสูง"
  },
  Event_91475_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91475_Desc = {
    Text = "คุณรู้ดีหรือไม่ว่าความคิดที่ร้อนแรงจะนำไปสู่ภัยพิบัติ ดังนั้นคุณจึงได้ใช้เหตุผลเก็บทุกสิ่งไว้"
  },
  Event_91475_Name = {
    Text = "ภูเขาไฟที่หลับใหล"
  },
  Event_91476_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91476_Desc = {
    Text = "คุณจ้องมองที่ดวงตานั้น พยายามเข้าใจข้อมูลที่มันส่งมา \n แม้ว่าคุณจะผ่านการต่อสู้มาอย่างมากมาย แต่การเผชิญหน้ากับโกไลแอทในครั้งนี้... ความกลัวได้บีบคั้นหัวใจของคุณ \n「เกือบปกติ คือรูปแบบที่เงียบที่สุดก่อนที่ภัยพิบัติจะเกิดขึ้น。」"
  },
  Event_91476_Name = {
    Text = "เกือบปกติ"
  },
  Event_91477_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91477_Desc = {
    Text = "คุณหลับตาลง หันหลังเดินเข้าสู่ทุ่งกว้าง\nคุณสามารถสัมผัสถึงความปรารถนาและลางบอกเหตุที่ซ่อนอยู่ แต่คุณจะไม่มีวันหยุดยั้งมันได้ด้วยมือของตัวเอง\nคุณมองไปที่หลุมศพที่ไม่มีตัวอักษรอยู่รอบๆ อาจเป็นเช่นนี้แหละที่เป็นจุดจบของคุณ。"
  },
  Event_91477_Name = {
    Text = "งานเลี้ยงของฝูงอีกา"
  },
  Event_91478_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91478_Desc = {
    Text = "คุณค่อยๆ เงยหน้าขึ้น ในขณะนั้น แสงได้ทะลุผ่านม่านตา ร้อนระอุในสมองเบ่งบานเป็นดอกไม้สีขาว\nดวงดาราในเนครอโพลิสไม่มีความแตกต่างจากที่อื่น และดูเหมือนว่าซากศพที่มีชีวิตนิรันดร์ก็ต้องอยู่ใต้ดาว ไม่สามารถมีอิสระ。"
  },
  Event_91478_Name = {
    Text = "คืนแห่งดวงดาว"
  },
  Event_91479_ChoiceDesc1 = {
    Text = "【โยนลงไฟ】ลบการ์ด 1 ใบ"
  },
  Event_91479_ChoiceDesc2 = {
    Text = "【พยายามตีความ】รับ「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91479_Desc = {
    Text = "จิตสำนึกของคุณลอยอยู่ในหมอกดำที่ไม่มีที่สิ้นสุด แหวกว่ายไปมาระหว่างภาพจิตของผู้มีชีวิตและผู้ล่วงลับนับไม่ถ้วน \nในความฝัน เครื่องพิมพ์ดีดอันมหัศจรรย์ได้พ่นบทกลอนแปลกหน้าออกมา นี่คือเรื่องราวของใครกัน? \nมันถูกตราประทับลงบนกระดาษที่ไม่รู้จักที่มา ตัวอักษรที่บิดเบือนดูเหมือนจะถูกเขียนโดยผู้ที่เมาและตื่นรู้ \nคุณถูกแรงกระตุ้นที่ไม่สามารถบรรยายได้ในความฝันขับเคลื่อน จึงหยิบกระดาษแผ่นนั้นขึ้นมา หมึกกระโดดไปมาท่ามกลางแสงเงาของไฟในเตา。"
  },
  Event_91479_Name = {
    Text = "การเปิดเผยของความฝัน"
  },
  Event_91480_ChoiceDesc1 = {
    Text = "【เข้าร่วม】ติดเชื้อ「(Skill.Arg1)」，การ์ดใบสุ่ม 1 ใบได้รับคำอธิษฐาน:「(EnchantConfig.Arg2)」"
  },
  Event_91480_ChoiceDesc2 = {
    Text = "【ขับไล่】ติดเชื้อ「(Skill.Arg1)」，ได้รับการ์ด 1 ใบแบบสุ่มเพื่อรับคำอธิษฐาน：「(EnchantConfig.Arg2)」"
  },
  Event_91480_ChoiceDesc3 = {
    Text = "【เพิกเฉย】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับคำอธิษฐาน：「(EnchantConfig.Arg1)」"
  },
  Event_91480_Desc = {
    Text = "คุณได้ยินเสียงแตรกระดูกที่เลือนรางมาจากที่ไกลโพ้น。\nฝูงหนูเดินตามเสียงออกมาจากโคลนดำ กัดกินซากศพที่ไม่มีชื่อซึ่งนอนอยู่บนพื้นแม่น้ำที่แห้งแล้ง。\nพวกมันล้อมรอบเป็นวง กลางวงคือซากศพที่ว่างเปล่า และรอบวงคืออาณาจักรใหม่ที่มีการลืมเป็นกฎหมาย。\nและคุณกำลังยืนอยู่ที่ทางเข้าสู่อาณาจักรนี้。"
  },
  Event_91480_Name = {
    Text = "อาณาจักรที่ถูกเนรเทศ"
  },
  Event_91481_ChoiceDesc1 = {
    Text = "【ยกหน้าขึ้นมอง】ได้รับของโบราณเงิน「(RelicConfig.Arg1)」"
  },
  Event_91481_ChoiceDesc2 = {
    Text = "【ก้มหน้าและจากไป】รับ 75 สัญลักษณ์ดำ，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91481_Desc = {
    Text = "ฝูงกากำลังโฉบอยู่บนท้องฟ้า ราวกับเลื่อยที่ลังเล ตัดสันหลังของท้องฟ้าอย่างต่อเนื่อง \n พวกมันบินต่ำรอบตัวคุณ ราวกับว่าเห็นถึงความตายของคุณ และรอคอยการเริ่มต้นของงานเฉลิมฉลองอย่างใจเย็น。"
  },
  Event_91481_Name = {
    Text = "งานเลี้ยงของฝูงอีกา"
  },
  Event_91482_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91482_Desc = {
    Text = "คุณให้มันเขียนต่อไปด้วยจังหวะการเต้นของคุณ ความเจ็บปวด ความทรงจำและการคาดเดาของคุณ \nผีเสื้อได้หลุดพ้นจากการผูกมัดของกระดาษ จิตใจของคุณจึงได้โบยบิน \nคุณเริ่มจินตนาการถึงความสุขของตัวเองในสวนสนุก คุณไม่ได้บอกดูเรซินว่า จริงๆ แล้วคุณชอบสวนสนุกมาก แม้กระทั่งสวนสนุกที่มีศพ... \nคงจะ...ไม่แปลกประหลาดเกินไปใช่ไหม?"
  },
  Event_91482_Name = {
    Text = "เงาผีเสื้อซ้อนทับกัน"
  },
  Event_91483_ChoiceDesc1 = {
    Text = "【สังเกตอีกครั้ง】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับคำอธิษฐาน：「(EnchantConfig.Arg1)」"
  },
  Event_91483_Desc = {
    Text = "ค่ำคืนที่เคยชัดเจนกลายเป็นงานเฉลิมฉลองที่เต็มไปด้วยเนื้อและเลือด คุณนึกถึงวัตถุดิบบนเตา กลิ่นเน่าเหม็นกระตุ้นจมูกของคุณ \nความกลัวบีบหัวใจของคุณ คุณต้องทำทางเลือก。"
  },
  Event_91483_Name = {
    Text = "เงาของอดีต"
  },
  Event_91484_ChoiceDesc1 = {
    Text = "【ไม่สนเสียงกระดิ่ง】ได้รับคำอธิษาณขั้นสูง 3 ตัวเลือก 1"
  },
  Event_91484_ChoiceDesc2 = {
    Text = "【หยิบหูฟังขึ้น】ได้รับของโบราณทอง「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91484_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_91484_Desc = {
    Text = "มันไม่ควรดังขึ้น——โทรศัพท์เครื่องนั้นซึ่งซุกซ่อนอยู่หลังผ้าใบ。\nสายของหูฟังพันอยู่กับตัวเครื่องขนาดใหญ่ ราวกับสายสะดือที่เป็นสนิม ดูเหมือนจะยืดออกมาจากสมองของคุณ。\nคุณพยายามแยกแยะความถี่ของการสั่นสะเทือน เสียงแปลกๆ นั้นเหมือนกับศิลปะเหนือจริงของพิคแมน。"
  },
  Event_91484_Name = {
    Text = "การโทรที่พลาด"
  },
  Event_91485_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91485_Desc = {
    Text = "คุณยกขึ้นมาจากสมองที่เย็นเฉียบ เมื่อนั้นมันก็กลายเป็นน้ำที่ไหลออกจากรอยนิ้วของคุณอย่างเงียบๆ \nตุ้มถ่วงจึงไม่สมดุล หัวใจของคุณยุบตัวลงอย่างรวดเร็วเหมือนผลไม้เน่า และละลายกลายเป็นน้ำดำที่เงียบสงบ \nความหิวทั้งหมดหายไป คุณมีความสงบ ไม่เสียใจ และความชัดเจนชั่วคราว。"
  },
  Event_91485_Name = {
    Text = "เกมหิวโหย"
  },
  Event_91486_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91486_Desc = {
    Text = "ไม่มีเสียง ไม่มีใครตอบรับ บางทีแค่เป็นเรื่องตลก? \n ขณะที่คุณวางหูโทรศัพท์ ความรู้สึกหนักหน่วงบางอย่างก็ย้อนกลับเข้ามาในร่างกายของคุณ。"
  },
  Event_91486_Name = {
    Text = "การโทรที่พลาด"
  },
  Event_91487_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91487_Desc = {
    Text = "อีกาหายไปแล้ว。\nแต่คุณเห็นตัวเองยืนอยู่ในกระจกของคืนที่แตกต่าง มองไปที่อีกาตัวนี้。\nมันยังคงร้องเสียงเงียบ ๆ ราวกับกำลังเฝ้ารอการตอบสนองของคุณ。"
  },
  Event_91487_Name = {
    Text = "การสารภาพที่เงียบเชียบ"
  },
  Event_91488_ChoiceDesc1 = {
    Text = "【สังเกตอีกครั้ง】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อรับคำอธิษฐาน：「(EnchantConfig.Arg1)」"
  },
  Event_91488_ChoiceDesc2 = {
    Text = "【ยอมแพ้ต่อการต่อต้าน】ติดเชื้อ「(Skill.Arg1)」，เปลี่ยนคำอธิษาณที่ได้รับจากตัวเลือก 1 ได้อีกครั้ง"
  },
  Event_91488_Desc = {
    Text = "คุณหลบสายตาออกจากนั้น ในขณะที่ภาพนั้นกลับเหมือนเงาภาพลอยมาในสายตาของคุณ……\nมันคือการเต้นคู่ที่เศร้า。"
  },
  Event_91488_Name = {
    Text = "เงาของอดีต"
  },
  Event_91489_ChoiceDesc1 = {
    Text = "【เพลิดเพลิน】เลือก 1 ใน 3 การ์ดคำสั่งเพื่อรับคำอธิษฐาน:「(EnchantConfig.Arg1)」"
  },
  Event_91489_ChoiceDesc2 = {
    Text = "【ปฏิเสธอย่างสุภาพ】ติดเชื้อ「(Skill.Arg1)」，อธิษฐานอีกครั้ง สูงสุด 2 ครั้ง"
  },
  Event_91489_Desc = {
    Text = "นี่คือสิ่งที่ดูเรซินเตรียมไว้สำหรับพวกคุณที่ทำงานหนักในการสอบสวน\nไม่มีการใส่เครื่องเทศแต่ไม่มีรสเน่าเหม็น อย่างที่ดูเรซินพูด นี่คือวัตถุดิบที่ดีที่สุด\nงานเลี้ยงจัดขึ้นเพื่อคุณ ขณะที่สมองเงียบสงบอยู่ในจาน\n「อยากลองชิมไหม?」"
  },
  Event_91489_Name = {
    Text = "การลิ้มรสอาหารอร่อย"
  },
  Event_91490_ChoiceDesc1 = {
    Text = "【ฟัง】ได้รับ 40 รอยดำ, ติดเชื้อ「(Skill.Arg2)」，เลือกต่อไป"
  },
  Event_91490_ChoiceDesc2 = {
    Text = "【ละเลย】ได้รับรอยดำ 25，แล้วจากไป"
  },
  Event_91490_Desc = {
    Text = "นั่นคืออีกาตัวหนึ่ง。\nมันยืนอยู่บนโคมไฟโครงกระดูก ยิ้มหวาน แต่ไม่ได้ปล่อยเสียงออกมาเลย。"
  },
  Event_91490_Name = {
    Text = "การสารภาพที่เงียบเชียบ"
  },
  Event_91491_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91491_Desc = {
    Text = "คุณค่อยๆ ยื่นมือไปยังหัวใจที่ยังร้อนอยู่ มันเต้นและหดตัว จนกระทั่งกลายเป็นกลิ่นหอมอบอวลที่กระจายไป \n ตาชั่งสั่นสะเทือนอย่างรุนแรง สมองของคุณตกลงสู่ความมืดที่ไม่มีที่สิ้นสุด \n ความรู้สึกอิ่มท้องแทนที่ความหิว คุณได้เข้าใจถึงความร้อนแรง ความเจ็บปวด และความทรงจำที่แท้จริง。"
  },
  Event_91491_Name = {
    Text = "เกมหิวโหย"
  },
  Event_91492_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91492_Desc = {
    Text = "คุณเงยหน้าขึ้นต้อนรับการหมุนวนที่ไม่มีเสียง เหมือนกับผู้แสวงบุญในพิธีบูชาที่โบราณ.\nพวกเขาสนุกสนานกับการบริโภคเนื้อและเลือดของคุณ คุณรู้สึกเจ็บปวด แต่ก็ชัดเจน.\nคุณเห็นตัวตนที่หายไปของตัวเอง ส่วนที่ยังไม่ตาย ในที่สุดก็ถูกนำพาไป.\nเมื่อจิตสำนึกกลับคืน คุณพบว่าตัวเองปลอดภัยดี。"
  },
  Event_91492_Name = {
    Text = "งานเลี้ยงของฝูงอีกา"
  },
  Event_91493_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91493_Desc = {
    Text = "คุณใช้ปูนซีเมนต์แห่งความทรงจำและอารมณ์ปิดช่องล็อกไว้ ความจริงไม่สามารถล่อลวงคุณได้อีกต่อไป \n ดูเรซินมองคุณด้วยท่าทีเหมือนเจอศัตรู เขาลิ้มรสที่มุมปาก \n 「ยังอยากลองอีกไหม? นี่คือมอซซาเรลลาที่ทำพิเศษสำหรับท่านผู้พิทักษ์」"
  },
  Event_91493_Name = {
    Text = "วิวรณ์"
  },
  Event_91494_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91494_Desc = {
    Text = "ความจริงแล้ว คุณสนใจในประสบการณ์ของซอมบี้เสมอมา\n「ดังนั้นคุณก้าวเข้าสู่ฝูงหนู และกลายเป็นส่วนหนึ่งของพวกมัน—」\nคุณต้องยอมรับว่าการมาของผู้ร่อนทะเลทำให้สมองของคุณสับสนไปหมด。"
  },
  Event_91494_Name = {
    Text = "อาณาจักรที่ถูกเนรเทศ"
  },
  Event_91495_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91495_Desc = {
    Text = "คุณไม่ต้องการมีส่วนร่วมกับความเสื่อมโทรมและโกลาหล。\nคุณชินกับทุกอย่างที่เน่าเปื่อยราวกับเป็นเรื่องปกติ。"
  },
  Event_91495_Name = {
    Text = "อาณาจักรที่ถูกเนรเทศ"
  },
  Event_91496_ChoiceDesc1 = {
    Text = "【เพลิดเพลิน】เลือก 1 ใน 3 การ์ดคำสั่งเพื่อรับคำอธิษฐาน:「(EnchantConfig.Arg1)」"
  },
  Event_91496_ChoiceDesc2 = {
    Text = "【ปฏิเสธอย่างสุภาพ】ติดเชื้อ「(Skill.Arg1)」，สุ่มคำอธิษฐานอีกครั้ง"
  },
  Event_91496_Desc = {
    Text = "ดูเรซินช่วยคุณหั่นชิ้น「สมอง」อย่างมีเสน่ห์ \n รสชาติหวานนี้... \n เนื้อสัมผัสนุ่มและแน่นนี้... \n คุณอยากลองอีกคำหนึ่ง。"
  },
  Event_91496_Name = {
    Text = "การลิ้มรสอาหารอร่อย"
  },
  Event_91497_ChoiceDesc1 = {
    Text = "【ฉันกำลังฝัน】ได้รับของโบราณเงิน「(RelicConfig.Arg1)」"
  },
  Event_91497_ChoiceDesc2 = {
    Text = "【มันไม่ธรรมดา】ได้รับของโบราณทอง「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91497_Desc = {
    Text = "หลุมศพที่เรียบเนียนสะท้อนดวงตาที่กำลังบิดเบี้ยวอย่างช้าๆ \n เหมือนกำลังแบกรับภาพบางอย่างที่ตามนุษย์ไม่สามารถบรรยายได้ ความทรงจำหนึ่งที่ไม่ใช่ของคุณ แต่กลับฝังลึกอยู่ในรอยพับใต้ตาของคุณ \n คุณพยายามกะพริบตาและใช้ปลายนิ้วถู แต่ดวงตานั้นไม่ใช่ของคุณอีกต่อไป มันเริ่มสะท้อนภาพที่เหมือนกับกระจกเงาหลากสี。"
  },
  Event_91497_Name = {
    Text = "เกือบปกติ"
  },
  Event_91498_ChoiceDesc1 = {
    Text = "【สังเกตต่อ】เลือกการ์ดคำสั่ง 1 ใบจาก 3 ใบเพื่อเข้ารับคำอธิษฐาน：「(EnchantConfig.Arg1)」"
  },
  Event_91498_ChoiceDesc2 = {
    Text = "【หันหน้าหนี】ติดเชื้อ「(Skill.Arg1)」，เปลี่ยนคำอธิษาณที่ได้รับจากตัวเลือก 1 ได้ 2 ครั้ง"
  },
  Event_91498_Desc = {
    Text = "ในมุมชื้นของปราสาทโบราณ คุณค้นพบฟิล์มม้วนหนึ่ง \n ภาพถ่ายเหมือนกับภาพลวงตาที่จมน้ำตายในแม่น้ำแห่งเวลา ในการหยุดชั่วคราวอย่างช้าๆ แข็งตัว บางครั้งขยายตัวกลายเป็นสิ่งที่ไม่สามารถบรรยายได้ บางครั้งยุบตัวลงกลายเป็นจุดแสงที่กระพริบไม่หยุด \n คุณจมอยู่ในนั้น และความรู้สึกเวียนศีรษะเตือนคุณถึงการล่วงเลยของเวลา。"
  },
  Event_91498_Name = {
    Text = "เงาของอดีต"
  },
  Event_91499_ChoiceDesc1 = {
    Text = "【จ้องมองดวงดาว】รับของโบราณทอง「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91499_ChoiceDesc2 = {
    Text = "【ปิดตา】ปลุกเสกผู้ปลุกเสก 2 คนแบบสุ่ม，ติดเชื้อสองครั้ง「(Skill.Arg1)」"
  },
  Event_91499_ChoiceDesc3 = {
    Text = "【ออก】ได้รับ 50 รอยดำ"
  },
  Event_91499_Desc = {
    Text = "คุณยืนอยู่ในสุสานที่ไม่มีใครอยู่ ดวงดาวทำให้คืนสว่างเหมือนกลางวัน\nลูกบอลแสงที่ลอยอยู่ในมหาสมุทรแห่งเวลาไม่เคยพูด แต่กลับค่อยๆ มุ่งเน้นในวงเวียนที่ยาวนานเหมือนละเมอ\nพวกมันจ้องมองไปที่ดาวเดียวดายที่ถูกลืม\nพระองค์จ้องมองคุณ จ้องมองทุกสิ่งที่ตายและนิรันดร์。"
  },
  Event_91499_Name = {
    Text = "คืนแห่งดวงดาว"
  },
  Event_91500_ChoiceDesc1 = {
    Text = "【ฟัง】ได้รับสัญลักษณ์ดำ 20 ตัว，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91500_ChoiceDesc2 = {
    Text = "【ละเว้น】ออก"
  },
  Event_91500_Desc = {
    Text = "คุณมองตากับมัน。\nในความมืดมิด คุณเห็นเปลวไฟที่โลภ。"
  },
  Event_91500_Name = {
    Text = "การสารภาพที่เงียบเชียบ"
  },
  Event_91501_ChoiceDesc1 = {
    Text = "【เปิดล็อค】ได้รับของโบราณที่ถูกสาป「(RelicConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91501_ChoiceDesc2 = {
    Text = "【ปิดรูกุญแจ】การ์ด 1 ใบแบบสุ่มได้รับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_91501_Desc = {
    Text = "เมื่อเผชิญหน้ากับดูเรซินที่ยื่นให้มา คุณปฏิเสธหลายครั้ง แต่สุดท้ายก็ไม่อาจต้านทานความเย้ายวนใจของปัญญาได้\nความรู้ไม่ได้มาถึงอย่างช้าๆ แต่กลับหลั่งไหลมาอย่างรวดเร็ว\nสมองเริ่มปวดตุบๆ ความคิดเหมือนกับขนมปังที่กำลังฟูตัวอย่างต่อเนื่อง เมื่อคุณล้มลงในที่สุด ความเจ็บปวดก็เหมือนกับน้ำทะเลที่ถอนตัวออกไป จิตสำนึกเหมือนจะขาดหายไปหนึ่งส่วน เหลือไว้เพียงรูที่สะอาดและโบราณ\nนี่แหละคือรูปแบบของความรู้! คุณรู้สึกถึงปัญญาที่ไม่เคยมีมาก่อน\nหรือว่า...คุณอาจจะได้รับมากกว่านี้?"
  },
  Event_91501_Name = {
    Text = "วิวรณ์"
  },
  Event_91502_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91502_Desc = {
    Text = "คุณใช้คมมีดที่เหลืออยู่ในจิตสำนึกงัดรูล็อกนั้นออก\nคุณไม่รู้ว่ากุญแจคืออะไร ใช้เพียงความหลงใหลในการลองเท่านั้น ในช่วงเวลานั้น ความคิดของคุณถูกเผาไหม้จนหมดสิ้น เหลือเพียงบางอย่างที่ไม่ใช่มนุษย์กระซิบอยู่ในรูล็อกที่ว่างเปล่า\nนี่คือการเปิดเผยใช่ไหม? คุณกระตุ้นใจแบ่งปันกับดูเรซิน\n「ยังอยากลองอีกไหม? นี่คือมอซาเรลลาที่ทำขึ้นพิเศษสำหรับท่านผู้พิทักษ์」"
  },
  Event_91502_Name = {
    Text = "วิวรณ์"
  },
  Event_91503_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91503_Desc = {
    Text = "คุณไม่ระเบิดมัน และไม่กดมันไว้\nในสถานะของผู้ชมที่ประหลาด คุณมองความคิดที่พลั่งออกมาคล้ายกับการแปรเปลี่ยนของสภาพอากาศ ปล่อยให้มันไหลไปยังปลายทางที่ไม่รู้จัก\nในภาพวาดที่แทรกด้วยเลือดและเนื้อ คุณได้สัมผัสกับศิลปะนิรันดร์。"
  },
  Event_91503_Name = {
    Text = "ภูเขาไฟที่หลับใหล"
  },
  Event_91504_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91504_Desc = {
    Text = "ปุ่มหยุดลงอย่างกะทันหัน เงาของผีเสื้อหายไปในพริบตา\nมันเป็นภาพลวงตาหรือเปล่า? คุณรู้สึกสูญเสียบางสิ่ง\nบางทีคุณควรฟังคำพูดของดูเลอเซอินแล้วไปซื้อกระป๋องความทรงจำที่ร้านขายสมองใบไม้\n「ไม่ใช่สิ ฉันกำลังคิดอะไรอยู่?」"
  },
  Event_91504_Name = {
    Text = "เงาผีเสื้อซ้อนทับกัน"
  },
  Event_91505_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91505_Desc = {
    Text = "คุณไม่ต่อสู้แล้ว ปล่อยให้ปีกและของเหลวสีดำทะลุผ่านลายมือของคุณ\nคุณกลายเป็นภาชนะของมัน และมันใช้คุณเป็นเปลือก ยังคงคิดต่อไป\nผีเสื้อยิ่งใหญ่ขึ้นเรื่อย ๆ คุณในที่สุดก็ทนไม่ไหวกับน้ำหนัก\nเมื่อเห็นเช่นนี้ ดูเรซินก็เต็มไปด้วยความสนใจ ใช้มีดอาหารตัดการเชื่อมต่อระหว่างคุณกับผีเสื้อ สายตาของเขาที่เต็มไปด้วยความกระตือรือร้นชัดเจนว่าเขาต้องการ…\nคุณปฏิเสธคำขอของเขา。"
  },
  Event_91505_Name = {
    Text = "ปรสิตชนชั้นสูง"
  },
  Event_91506_ChoiceDesc1 = {
