  },
  Event_91506_Desc = {
    Text = "คุณคิดว่ามันเงียบ จนกระทั่งจิตสำนึกของคุณเริ่มเอียง ราวกับหัวของอีกาไม่รู้กี่ตัวกำลังร้องเรียกในหัวของคุณ \n คุณทรุดลงกับพื้น โลกหมุนวนอยู่ในสายตาของคุณ。"
  },
  Event_91506_Name = {
    Text = "การสารภาพที่เงียบเชียบ"
  },
  Event_91507_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91507_Desc = {
    Text = "คุณหลับตาลง ก้าวเข้าสู่ฝุ่นละอองที่ไม่มีที่สิ้นสุดและนุ่มนวล เนบิวล่ากอดคุณไว้ และคุณสูญเสียรูปร่าง มีสิ่งที่มั่นคงกว่าร่างกายอยู่ภายในตัวคุณค่อยๆ ตกผลึก \nคืนวันนั้น ดาวนับพันยังคงหมุนวน ราวกับว่าเป็นวันที่สดใสเช่นเคย \nสำหรับผู้มีชีวิตนิรันดร์ ท้องฟ้ายามค่ำคืนหมายถึงอะไร? บางทีคุณอาจควรถามดูเรซิน。"
  },
  Event_91507_Name = {
    Text = "คืนแห่งดวงดาว"
  },
  Event_91508_ChoiceDesc1 = {
    Text = "【เพลิดเพลิน】เลือก 1 ใน 3 การ์ดคำสั่งเพื่อรับคำอธิษฐาน:「(EnchantConfig.Arg1)」"
  },
  Event_91508_Desc = {
    Text = "แท้จริงมันคือชีส\nในขณะที่คุณรู้สึกดีใจ แต่ก็มีความรู้สึกเสียดายเล็กน้อย"
  },
  Event_91508_Name = {
