  Event_91509_ChoiceDesc1 = {
    Text = "【จุดไฟ】ติดเชื้อ「(Skill.Arg1)」，ได้รับของโบราณเงิน「(RelicConfig.Arg2)」"
  },
  Event_91509_ChoiceDesc2 = {
    Text = "【รอคอย】ติดเชื้อ「(Skill.Arg1)」，ได้รับของโบราณเงิน「(RelicConfig.Arg2)」"
  },
  Event_91509_ChoiceDesc3 = {
    Text = "【เก็บรักษา】รับ 25 สัญลักษณ์ดำ"
  },
  Event_91509_Desc = {
    Text = "คุณจ้องมองภาพของพิคแมน กลิ่นเน่าที่ทำให้รู้สึกคลื่นไส้ทำให้คุณรู้สึกเวียนหัว。\nความคิดค่อยๆ ลอยขึ้นจากสมอง เริ่มแรกเป็นเพียงไอร้อน ต่อมาคือหมอกบาง แล้วต่อมา——"
  },
  Event_91509_Name = {
    Text = "ภูเขาไฟที่หลับใหล"
  },
  Event_91510_ChoiceDesc1 = {
    Text = "【สัมผัสสมอง】ได้รับการ์ดคำสั่งแบบสุ่ม 1 ใบเพื่อรับคำอธิษฐาน：「(EnchantConfig.Arg1)」"
  },
  Event_91510_ChoiceDesc2 = {
    Text = "【สัมผัสหัวใจ】เพิ่มพลังชีวิตสูงสุด Arg1 จุด，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91510_Desc = {
    Text = "คุณเดินเข้าไปในห้องสีเทาที่ไร้เสียงกระซิบ มีตาชั่งปรากฏอยู่ในหมอกดำ \n ด้านซ้ายคือสมองที่สงบเหมือนทะเลสาบ ร่องรอยสีเงินเปล่งประกายเล็กน้อย; ด้านขวาคือหัวใจสีแดงร้อนที่มีไอน้ำพวยพุ่งออกมา \n ทันใดนั้นคุณได้กลิ่นหอม ความปรารถนาที่หิวโหยพุ่งสูงขึ้นเรื่อยๆ สติของคุณถูกความมืดอันไม่มีที่สิ้นสุดกดดัน \n คุณยื่นมือออกไป。"
  },
  Event_91510_Name = {
    Text = "เกมหิวโหย"
  },
  Event_91511_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91511_Desc = {
    Text = "นี่ต้องเป็นความฝันแน่ๆ คุณพยายามโน้มน้าวตัวเองซ้ำไปมา\nโดยไม่รู้ตัว คุณก็ตกอยู่ในห้วงฝัน\nบางทีอาจเป็นเพราะการสื่อสารที่มากเกินไป คุณถึงกับฝันเห็นดูแลเซย์น—เป็นฝ่ายเสนอตัวให้ดูแลเซย์นกินเลือดและเนื้อของตัวเอง? เรื่องสยองขวัญอะไรแบบนี้?"
  },
  Event_91511_Name = {
    Text = "เกือบปกติ"
  },
  Event_91660_ChoiceDesc1 = {
    Text = "【หาทางอื่น】เลือก 1 ใบจากการ์ดคำสั่ง 3 ใบเพื่อรับตราประทับ：「(EnchantConfig.Arg1)」"
  },
  Event_91660_ChoiceDesc2 = {
    Text = "【ปล่อยให้มันมีอยู่】รับการ์ดคำสั่งสุ่ม 3 ใบเพื่อรับคำอธิษฐาน:「(EnchantConfig.Arg1)」，ติดเชื้อ「(Skill.Arg2)」"
  },
  Event_91660_Desc = {
    Text = "「จงนำพาวิญญาณ เจ้านั้นต้องนำทางผู้ล่วงลับไปจนถึงจุดสิ้นสุด」\nพร้อมกับคำพูดของดูเลอซายน์ เจ้าก็เกิดความเข้าใจขึ้นมา\nมันไม่ใช่ความรู้ ไม่ใช่ความทรงจำ—สิ่งนั้นคล้ายกับน้ำหนักหนึ่งที่แทรกผ่านเบ้าตาของเจ้า เข้ามาในสมองของเจ้าราวน้ำหลาก\nอารมณ์ของเจ้าเหมือนจะไม่อยู่ในสถานที่และเวลาแห่งนี้อีก มันถอยห่างออกไป เผยให้เห็นรอยร้าวหนึ่งของความละเลยในจักรวาล\nทุกสิ่งที่เจ้าสามารถรับรู้ได้ หยุดอยู่ที่นั่น เหมือนมาถึงจุดสิ้นสุดของเส้นทางหนึ่ง。"
  },
  Event_91660_Name = {
    Text = "จุดสิ้นสุดของวิญญาณ"
  },
  Event_91661_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91661_Desc = {
    Text = "คุณให้จิตวิญญาณเดินจากไป。\nที่ขอบเขตของ「ตัวตน」คุณดูเหมือนจะได้ยินเสียงกระซิบของผู้ที่ล่วงลับไปแล้ว。\nแต่เมื่อคุณฟังอย่างตั้งใจ ทุกอย่างกลับหายไป。"
  },
  Event_91661_Name = {
    Text = "จุดสิ้นสุดของวิญญาณ"
  },
  Event_91662_ChoiceDesc1 = {
    Text = "【ออกจาก】"
  },
  Event_91662_Desc = {
    Text = "คุณห่อหุ้มจิตสำนึกของตัวเองไว้ จึงตัดขาดจากสิ่งล่อลวงที่ไม่รู้จัก \n คุณหลงอยู่ที่ปลายวิญญาณ มองเห็นเพียงตัวเอง \n จริงๆ แล้ว ในฐานะที่เป็นมนุษย์ คุณไม่สามารถมีพลังของซอมบี้ได้。"
  },
